def _exc_note(exc, timeout=None) -> str:
    """Short, safe note about an exception for logs: the exception
    TYPE only, plus the timeout budget for a TimeoutException
    ("TimeoutException after 30.0s"). Never the exception text —
    httpx error text carries the request URL, and the Gemini URL
    carries the API key (?key=...), which leaked into the Render
    logs (13 Nov 2026). The type + budget is the whole diagnosis
    a timeout needs: live, 18 Nov 2026, three voice notes failed
    with a bare "transport error" and no way to tell a 5s timeout
    from a dropped connection."""
    name = type(exc).__name__
    if isinstance(exc, httpx.TimeoutException) and timeout is not None:
        return f"{name} after {timeout}s"
    return name


def _log_ai_failure(message: str, exc, note: str = None) -> None:
    """Log an AI-provider failure: message + HTTP status only.

    Never log the exception object or a traceback here — an httpx
    error's text carries the request URL, and the Gemini URL carries
    the API key (?key=...), which leaked into the Render logs (13 Nov
    2026). The status code is all the debugging signal there is.
    The message format is exact — existing secrecy tests assert the
    "(HTTP 429)" substring — so timing is logged on its own line
    by _ai_attempt, never appended here. `note` is an optional
    caller-supplied safe note (see _exc_note: type name only, never
    exception text); it is appended after the message and before
    the status, so "(HTTP 429)" still appears verbatim.
    """
    text = f"{message} ({note})" if note else message
    response = getattr(exc, "response", None)
    status = getattr(response, "status_code", None)
    if isinstance(status, int):
        log.warning("%s (HTTP %s)", text, status)
    else:
        log.warning("%s", text)


async def _ai_attempt(provider: str, coro):
    """One provider attempt inside ai_generate: time it and log the
    provider name + seconds, on success and on failure. Never logs
    the exception text, a URL, a prompt or a reply — the Gemini URL
    carries the API key (?key=...), which leaked into the Render
    logs (13 Nov 2026); failures go through _log_ai_failure, which
    logs the HTTP status only.
    """
    _start = time.monotonic()
    try:
        _text = await coro
    except Exception as exc:
        _elapsed = time.monotonic() - _start
        _log_ai_failure(
            f"{provider} generate failed, trying next provider", exc
        )
        log.info("ai %s failed %.2fs", provider, _elapsed)
        raise
    log.info("ai %s ok %.2fs", provider, time.monotonic() - _start)
    return _text


def _turn_log(stage: str, t0: float) -> None:
    """One handler-stage timing line for a text turn: the stage name
    + seconds since the turn started. Timings and intent type only —
    never the user's message text, a link, a phone number, a token,
    a key, a URL, a prompt or a reply. (17 Nov 2026: a live reply
    took 29s while both AI calls took under 1s each, so the delay
    sits somewhere in the handler — these lines show where.)
    """
    log.info("turn %s %.2fs", stage, time.monotonic() - t0)


async def ai_generate(prompt: str, system: str = None) -> str:
    """Text from the AI: Groq when GROQ_API_KEY is set (first since
    17 Nov 2026, owner: Groq first, DeepSeek second; Groq's free
    tier is fast and free, but it has a daily limit — a Groq failure
    falls through to DeepSeek), else DeepSeek when DEEPSEEK_API_KEY
    is set, else Grok when GROK_API_KEY is set (third since 17 Nov
    2026; Grok is expensive vs DeepSeek, and a Grok failure —
    including its daily limit — falls through to Zen), else
    Zen when ZEN_API_KEY is set (model deepseek-v4.1-flash-free —
    free tier, no card, owner approved 14 Nov 2026; a Zen failure
    falls through to Qwen), else Qwen when QWEN_API_KEY is set,
    else Mistral when MISTRAL_API_KEY is set (model
    mistral-small-latest — pay-as-you-go, owner approved 14 Nov
    2026: $0.10/$0.30 per 1M tokens, PAYG needs $10 prepaid credits
    first, no monthly minimum; a Mistral failure falls through to
    OpenAI), else ChatGPT when
    OPENAI_API_KEY is set, else Gemini, else Kilo (no key — free
    gateway, only after Gemini failed, so it never burns its per-IP
    hourly cap), else OpenRouter when OPENROUTER_API_KEY is set
    (free :free models — only after Kilo failed, so it never burns
    its daily cap), else GLM when GLM_API_KEY is set (free last
    resort — slow and rate-limited, so it only runs when every other
    provider failed).
    Every caller uses this, so the provider switch is one env var
    and the fallback is automatic. A provider that raises falls through to the next one at once (fast failover, 17 Nov 2026); only when every
    configured provider failed does the error reach the caller
    (extract_intent then answers from local_intent instead of going
    silent). The last provider's error is re-raised — never retried
    — so a total failure fails once, not twice. Every attempt is
    timed and logged (provider + seconds, status only on failure —
    see _ai_attempt), plus the total time for the whole call, so a
    slow reply can be traced to the provider that ate the time."""
    last_exc = None
    _start = time.monotonic()
    if GROQ_API_KEY:
        try:
            _text = await _ai_attempt("Groq", groq_generate(prompt, system=system))
        except Exception as exc:
            last_exc = exc
        else:
            log.info("ai_generate ok %.2fs", time.monotonic() - _start)
            return _text
    if DEEPSEEK_API_KEY:
        try:
            _text = await _ai_attempt("DeepSeek", deepseek_generate(prompt, system=system))
        except Exception as exc:
            last_exc = exc
        else:
            log.info("ai_generate ok %.2fs", time.monotonic() - _start)
            return _text
    if GROK_API_KEY:
        try:
            _text = await _ai_attempt("Grok", grok_generate(prompt, system=system))
        except Exception as exc:
            last_exc = exc
        else:
            log.info("ai_generate ok %.2fs", time.monotonic() - _start)
            return _text
    if ZEN_API_KEY:
        try:
            _text = await _ai_attempt("Zen", zen_generate(prompt, system=system))
        except Exception as exc:
            last_exc = exc
        else:
            log.info("ai_generate ok %.2fs", time.monotonic() - _start)
            return _text
    if QWEN_API_KEY:
        try:
            _text = await _ai_attempt("Qwen", qwen_generate(prompt, system=system))
        except Exception as exc:
            last_exc = exc
        else:
            log.info("ai_generate ok %.2fs", time.monotonic() - _start)
            return _text
    if MISTRAL_API_KEY:
        try:
            _text = await _ai_attempt("Mistral", mistral_generate(prompt, system=system))
        except Exception as exc:
            last_exc = exc
        else:
            log.info("ai_generate ok %.2fs", time.monotonic() - _start)
            return _text
    if OPENAI_API_KEY:
        try:
            _text = await _ai_attempt("OpenAI", openai_generate(prompt, system=system))
        except Exception as exc:
            last_exc = exc
        else:
            log.info("ai_generate ok %.2fs", time.monotonic() - _start)
            return _text
    if GEMINI_API_KEY:
        try:
            _text = await _ai_attempt("Gemini", gemini_generate(prompt, system=system))
        except Exception as exc:
            last_exc = exc
        else:
            log.info("ai_generate ok %.2fs", time.monotonic() - _start)
            return _text
    try:
        _text = await _ai_attempt("Kilo", kilo_generate(prompt, system=system))
    except Exception as exc:
        last_exc = exc
    else:
        log.info("ai_generate ok %.2fs", time.monotonic() - _start)
        return _text
    if OPENROUTER_API_KEY:
        try:
            _text = await _ai_attempt("OpenRouter", openrouter_generate(prompt, system=system))
        except Exception as exc:
            last_exc = exc
        else:
            log.info("ai_generate ok %.2fs", time.monotonic() - _start)
            return _text
    if GLM_API_KEY:
        try:
            _text = await _ai_attempt("GLM", glm_generate(prompt, system=system))
        except Exception as exc:
            last_exc = exc
        else:
            log.info("ai_generate ok %.2fs", time.monotonic() - _start)
            return _text
    if last_exc is not None:
        log.info("ai_generate failed %.2fs", time.monotonic() - _start)
        raise last_exc
    # No provider configured at all: let Gemini raise so the caller
    # falls back to local rules instead of going silent.
    return await gemini_generate(prompt, system=system)


# ------------------------------------------- Amharic translate-bridge ---
# Amharic, Tigrinya and Oromo messages are translated to English by
# Gemini first, the whole flow runs in English, and prose replies
# are translated back to the user's language before sending (see
# reply_message). Owner, 13 Nov 2026: DeepSeek/Qwen/Groq have
# unproven Amharic, but Gemini is strong on it, so Gemini does the
# translating while the main AI does the thinking. Oromo and
# Tigrinya were added the same way on 14 Nov 2026. Links, numbers,
# service IDs, prices and service names are never translated — the
# prompts say so, and Confirm cards, buttons and post-acceptance
# summaries never pass through the bridge at all. If either
# translation call fails, the original text is used instead — the
# bot never goes silent and never drops an order over a translation
# failure.
#
# _BRIDGE_LANG is the language this turn's message was bridged from
# ("am", "ti" or "om"), or None when the message was English. It is
# reset at the start of every turn in handle_order_text: the old
# boolean flag was set on an Amharic turn and never cleared, and
# because PTB processes updates sequentially in one task
# (max_concurrent_updates=1, the default — build_application does
# not change it), it leaked into every later English turn and
# translated those replies to Amharic too (live bug, 14 Nov 2026:
# "I'm tired" and "I said do you speak English" both got Amharic
# replies). _BRIDGE_AMHARIC is kept as a legacy alias, synced by
# _set_bridge_lang, because the offline tests reset it between
# cases.
_BRIDGE_LANG = contextvars.ContextVar("paxyo_bridge_lang", default=None)
_BRIDGE_AMHARIC = contextvars.ContextVar("paxyo_bridge_amharic", default=False)

_BRIDGE_LANG_NAMES = {
    "am": "Amharic", "ti": "Tigrinya", "om": "Oromo (Afaan Oromo)",
}


def _set_bridge_lang(lang):
    """Record the language this turn was bridged from (or None)."""
    _BRIDGE_LANG.set(lang)
    _BRIDGE_AMHARIC.set(lang == "am")


def _bridge_to_english_prompt(lang: str) -> str:
    return (
        f"Translate this {_BRIDGE_LANG_NAMES[lang]} message to English. "
        "Keep links, numbers, service IDs and prices exactly as they "
        "are. Reply with only the translation."
    )


def _bridge_from_english_prompt(lang: str) -> str:
    return (
        f"Translate this reply to {_BRIDGE_LANG_NAMES[lang]}. Keep links, "
        "numbers, service IDs, prices and service names exactly as "
        "they are. Reply with only the translation."
    )


BRIDGE_TO_ENGLISH_PROMPT = _bridge_to_english_prompt("am")
BRIDGE_TO_AMHARIC_PROMPT = _bridge_from_english_prompt("am")


async def translate_to_english(text: str, source_lang: str = "am") -> str:
    """A non-English message -> English via Gemini. Returns "" on any
    failure (no key, 429, empty reply) — the caller then uses the
    original text instead."""
    if not GEMINI_API_KEY:
        return ""
    try:
        result = await gemini_generate(
            _bridge_to_english_prompt(source_lang) + "\n\n" + text
        )
    except Exception as exc:
        _log_ai_failure("bridge translate to English failed", exc)
        return ""
    return (result or "").strip()


async def translate_to_language(text: str, lang: str) -> str:
    """English -> the user's language via Gemini. Returns "" on any
    failure — the caller then sends the English reply as-is."""
    if not GEMINI_API_KEY:
        return ""
    try:
        result = await gemini_generate(
            _bridge_from_english_prompt(lang) + "\n\n" + text
        )
    except Exception as exc:
        _log_ai_failure("bridge translate from English failed", exc)
        return ""
    return (result or "").strip()


async def translate_to_amharic(text: str) -> str:
    """English -> Amharic via Gemini. Wrapper kept for callers that
    only know Amharic; translate_to_language is the general one."""
    return await translate_to_language(text, "am")


def _latin_words_readable(text: str) -> bool:
    """Stricter test for a Latin-script transcription — the race's
    guard against fluent-looking garble (owner, 18 Nov 2026).
    Measured 18 Nov 2026: Groq's garbled English of an English
    voice note, "Mentioned this and I'll deposit me there
    again.", passed the old guard because it contains recognisable
    words ("deposit", "me", "there") — recognised-word coverage
    0.33 with a longest known run of 3, HIGHER than real English
    ("I want one thousand followers" is 0.20 / run 1, "I want to
    cancel my order" 0.17 / run 1). No coverage or run threshold
    separates it: any bar the garble clears, real English fails.
    So a Latin transcription wins only when (a) at least 80% of
    its words are words the bot knows (the garble is 0.67; the
    lowest real English measured is 0.80, "Please deposit one
    hundred birr"), or (b) it is at most two words and every word
    is recognised ("Thank you"), or (c) it names two domain
    things ("Salam, TikTok followers hâlliâ?" — tiktok +
    followers). Oromo words pass it outright, and text with no
    Latin words passes vacuously. The bias is deliberate:
    rejecting a correct transcription only costs seconds
    (Gemini/Chirp still answer it), while accepting a garbled one
    shows the user words he did not say — so short real English
    with an unknown word ("I need followers", "My order did not
    arrive") loses the fast path rather than risking a wrong
    "You said:". The recognised-word check reuses
    _recognisable_english one word at a time, so the two can
    never drift apart."""
    words = re.findall(r"[a-z]+", (text or "").lower())
    if not words:
        return True
    if set(words) & _OROMO_WORDS:
        return True
    if (
        sum(1 for w in words if w in _GARBLED_KNOWN_WORDS) / len(words)
        >= 0.80
    ):
        return True
    if (
        all(_recognisable_english(w) for w in words)
        and len(words) <= 2
    ):
        return True
    # Domain content words: the bot's own metrics, platforms and
    # state words, plus the domain nouns and verbs it already
    # carries in _GARBLED_KNOWN_WORDS. A transcription with two
    # of these is naming things the bot sells or does ("Salam,
    # TikTok followers hâlliâ?" has tiktok + followers); one on
    # its own ("deposit" in the 08:00 garble) is not enough.
    # Built inline like _recognisable_english builds its union.
    content = (
        set(_METRICS)
        | set(_PLATFORM_WORDS)
        | set(_REPORT_METRIC_WORDS)
        | {w for s in _SIMPLE_STATE_WORDS for w in s.split()}
        | {
            "balance", "price", "order", "deposit", "cancel",
            "status", "history", "link", "pay", "payment", "help",
            "support", "service", "profile", "account", "video",
            "post", "watch", "hours", "like", "likes", "cheap",
            "cheapest", "fast", "fastest",
        }
    )
    if sum(1 for w in words if w in content) >= 2:
        return True
    return False


def _transcription_usable(text, language=None) -> bool:
    """True when a transcription is worth using — the race's win
    condition, and the garbage guard's rule (owner, 18 Nov 2026).
    Non-string results (a mock returning a MagicMock) and blank
    text are unusable. Arabic script is a mis-detection when the
    transcriber was told the language is a Ge'ez language
    (Amharic/Tigrinya) — Whisper mis-hears Amharic as Arabic
    (14 Nov 2026) — so it does not win the race for those hints;
    for any other hint it may be a genuine Arabic speaker, so it
    passes here and the Arabic retry in transcribe_voice_with_retry
    handles it. Ge'ez script, a digit, a link, an @handle or an
    emoji is readable as before and passes at once. Anything else
    is Latin-script words, and those must ALSO clear the stricter
    coverage test in _latin_words_readable -- the old "one known
    word is enough" bar let Groq's garbled English win the race
    live on 18 Nov 2026 ("Mentioned this and I'll deposit me
    there again." for an English voice note: the "You said:"
    showed words the user did not say, though the deposit intent
    still read correctly). The three live Groq garblings of
    Amharic ("Azra Olede Shifor or Rafaell Galo.",
    "Asherahulet tishifu lorafel li galo.", "Yansar alutte si
    forora veli vello.") still fail it; "Salam, TikTok followers
    hâlliâ?" still passes it (two domain words)."""
    if not isinstance(text, str) or not text.strip():
        return False
    if _has_arabic_script(text):
        return language not in ("am", "ti")
    if re.search(r"[\u1200-\u137f]", text):
        return True
    if (
        re.search(r"\d", text)
        or "://" in text
        or text.strip().startswith("@")
        or " @" in text
        or any(emoji_meanings(text))
    ):
        return True
    return _latin_words_readable(text)


async def ai_transcribe(audio_bytes: bytes, language: str = None) -> str:
    """Voice transcription, RACED (owner, 18 Nov 2026): Gemini,
    Google Cloud Speech-to-Text (Chirp 3) and Groq Whisper run IN
    PARALLEL and the first USABLE result wins.
    Live 18 Nov 2026, 07:34 EAT: Gemini hears Amharic correctly
    (\"ሰላም የኢንስታግራም ፎሎወር ፈልጌ ነበረ\") but took 30s + 30s + 17s
    = 80s on the free tier, while Groq answers in ~0.3s but
    garbles Amharic 3 times in 4 — so Gemini-then-Groq is slow
    and Groq-then-Gemini is wrong. Racing takes Groq's answer
    when it is readable (~1-2s) and waits for Gemini when it is
    not. Chirp 3 joins the race when its key and project id are
    set (owner, 18 Nov 2026: the paid dedicated speech system);
    without them the race is exactly Gemini + Groq, unchanged.
    Gemini is attempted ONCE per call — no second 30s
    retry: the 30+30 doubling is what made 80s. When one wins
    the other task is cancelled, so the bot does not pay for
    all three; when several finish at once the tie-break is
    Gemini, then Chirp, then Groq. Worst case
    per call is one Gemini media budget (~30s) plus the chat
    reply — when Gemini is unreachable AND Groq garbles, the
    answer is an honest \"could not understand\" after ~30s,
    not another 30s retry. Returns \"\" when nothing usable
    arrives, so the caller answers honestly instead of feeding
    wrong text to the order flow.
    `language` is a hint (\"am\", \"ti\", \"om\", \"en\") — None means
    auto-detect."""
    racers = [
        ("Gemini", gemini_transcribe(audio_bytes, language=language),
         GEMINI_MEDIA_TIMEOUT_SECONDS),
    ]
    if GOOGLE_CLOUD_STT_API_KEY and GOOGLE_CLOUD_STT_PROJECT_ID:
        racers.append(
            ("Chirp", chirp_transcribe(audio_bytes, language=language),
             CHIRP_TRANSCRIBE_TIMEOUT_SECONDS)
        )
    racers.append(
        ("Groq", groq_transcribe(audio_bytes, language=language),
         AI_POST_TIMEOUT_SECONDS)
    )
    tasks = {}
    for name, coro, timeout in racers:
        tasks[asyncio.create_task(coro)] = (name, timeout)
    pending = set(tasks)
    try:
        while pending:
            done, pending = await asyncio.wait(
                pending, return_when=asyncio.FIRST_COMPLETED
            )
            # Tie-break is the racers order (Gemini, Chirp, Groq):
            # when several already finished, the most accurate
            # for Amharic wins. (In real time the first finisher
            # wins; a tie only happens when they answered at once.)
            for task, (name, timeout) in tasks.items():
                if task not in done:
                    continue
                try:
                    text = task.result()
                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    _log_ai_failure(
                        f"{name} transcribe failed",
                        exc,
                        note=_exc_note(exc, timeout),
                    )
                    continue
                if _transcription_usable(text, language):
                    for other in pending:
                        other.cancel()
                    return text
                log.warning(
                    "%s transcribe unusable, waiting for the other",
                    name,
                )
        return ""
    finally:
        for task in pending:
            task.cancel()
        if pending:
            await asyncio.gather(*pending, return_exceptions=True)


def _has_arabic_script(text: str) -> bool:
    """True when the text contains Arabic-script characters
    (U+0600–U+06FF). Amharic is Ge'ez script, Tigrinya is Ge'ez,
    Oromo is Latin — Arabic script in a transcription means the
    transcriber mis-detected the language, unless the user
    actually speaks Arabic."""
    return bool(re.search(r"[\u0600-\u06ff]", text or ""))


def _history_language_hint(user_id: int):
    """The language of the user's most recent stored message that
    carries a reliable language signal, or None. Scans the chat
    history newest-first: Ge'ez script is Amharic or Tigrinya
    (vocabulary decides, Amharic on a tie — the same rule as
    detect_language); a Latin-script Oromo word is Oromo. Plain
    Latin words are NOT a signal: they are either real English
    or transcriber gibberish for Amharic speech, and the two
    cannot be told apart — so an English-looking history never
    overrides anything. The stored history is the durable truth
    about the language the user actually writes (owner, 18 Nov
    2026: the server-stored session lang was poisoned to "en" by
    gibberish Latin transcriptions detected as English, so the
    lang field cannot be trusted — the Ge'ez words in the history
    can)."""
    for entry in reversed(CHAT_HISTORY.get(int(user_id), []) or []):
        if not isinstance(entry, dict):
            continue
        text = entry.get("user") or ""
        if is_amharic(text):
            return detect_language(text, "")
        words = set(re.findall(r"[a-z]+", text.lower()))
        if words & _OROMO_WORDS:
            return "om"
    return None


def _voice_language_hint(user_id: int, user_lang: str):
    """The language to hint the transcriber with ("am", "ti",
    "om", "en"), or None when it is genuinely unknown and the
    transcriber must auto-detect. Precedence (owner, 18 Nov
    2026): a non-English last detected language first — it can
    only come from Ge'ez script or an Oromo word, never from
    Latin gibberish; then the stored history's newest reliable
    signal — the durable truth after a restart, when LAST_LANG
    is empty, and the override when LAST_LANG was poisoned to
    "en" by a gibberish transcription detected as English;
    then an English last language; then the Telegram language;
    else unknown — never a guess. Hinting the known language on
    the first attempt is what makes Gemini hear Amharic from the
    start instead of auto-detecting."""
    hint = LAST_LANG.get(user_id)
    if hint in ("am", "ti", "om"):
        return hint
    history_hint = _history_language_hint(user_id)
    if history_hint in ("am", "ti", "om"):
        return history_hint
    if hint == "en":
        return "en"
    code = (user_lang or "").lower()
    return code[:2] if code[:2] in ("am", "ti", "om", "en") else None


def _recognisable_english(text: str) -> bool:
    """True when a Latin-script transcription contains at least
    one word the bot itself knows in English — built only from
    the word sets the bot already carries (greetings, state
    words, metrics, platforms, info phrases, formal words,
    quantity fillers), plus the Oromo words, which are a real
    language, not gibberish. Transcriber gibberish for Amharic
    audio ("Asherahulet tishifu lorafel li galo.") contains
    none of them. This is the garbage guard's English test
    (owner, 18 Nov 2026): an Amharic user speaking English is
    still heard — "I want one thousand followers" has
    "followers" — while Latin gibberish is rejected. A bare
    "yes"/"ok" has no known word and is rejected too; the user
    retypes it, which is honest, not wrong."""
    words = set(re.findall(r"[a-z]+", (text or "").lower()))
    if not words:
        return False
    if words & _OROMO_WORDS:
        return True
    known = (
        {w for g in _SIMPLE_GREETINGS for w in g.split()}
        | set(_SIMPLE_STATE_WORDS)
        | set(_METRICS)
        | set(_REPORT_METRIC_WORDS)
        | set(_PLATFORM_WORDS)
        | set(_FORMAL_WORDS)
        | set(_BARE_QUANTITY_FILLERS)
        | {w for p in _PAXYO_INFO_PHRASES for w in p.split()}
    )
    return bool(words & known)


async def transcribe_voice_with_retry(audio, user_id: int, user_lang: str) -> str:
    """Transcribe a voice note — ai_transcribe races Gemini,
    Chirp 3 and Groq Whisper in parallel (owner, 18 Nov 2026) and the first
    usable result wins; Gemini hears Amharic correctly where
    Groq Whisper mis-heard it, e.g. "12 ሺህ ፎሎወር እፈልጋለሁ".
    The first try hints the user's language
    when it is known (LAST_LANG, else Telegram language), so
    the transcribers are told "in Amharic, in the Ge'ez alphabet"
    from the start instead of auto-detecting; auto-detect is only
    for a genuinely unknown language, so an Amharic-language user
    speaking English is still heard in English. One
    language-hinted retry is kept for the case the first try
    comes back in Arabic script (owner, 14 Nov 2026: a
    transcriber mis-detecting Amharic as Arabic — both are
    Semitic languages — and the Arabic-script text then flows
    into the order flow, where detect_language has no Arabic
    branch and the AI mirrors the Arabic back). The retry is
    kept as a guard even though Gemini has not been seen to
    mis-detect this way: it costs one call only when Arabic
    script actually appears. The garbage guard (owner, 18 Nov
    2026): a transcription that carries nothing readable — no
    Ge'ez script, no Arabic script, no digit, no link, and no
    word the bot knows in English or Oromo — is transcriber
    gibberish, not speech in any language the bot understands,
    and it is rejected for ANY hint, so the caller answers
    honestly instead of feeding it to the order flow. The guard
    used to fire only when the hint was "am", which never
    happened live (the hint was poisoned to "en"), so Groq's
    "Yansar alutte si forora veli vello." sailed through on
    18 Nov 2026. Real words still pass: a bare "yes" or "ok", a
    quantity ("12 thousand", "12000"), Oromo, and English all
    carry something readable.
    Returns "" when the transcription is empty or unusable or
    both tries fail or stay Arabic, so the caller answers
    honestly instead of feeding wrong text to the order flow."""
    hint = _voice_language_hint(user_id, user_lang)
    text = await ai_transcribe(audio, language=hint)
    if _has_arabic_script(text) and not (user_lang or "").lower().startswith("ar"):
        try:
            retry = await ai_transcribe(audio, language=hint or "am")
        except Exception:
            return ""
        if _has_arabic_script(retry):
            return ""
        text = retry
    if (
        text
        and not _has_arabic_script(text)
        and _looks_garbled(text)
        and not _recognisable_english(text)
    ):
        # Transcriber gibberish for ANY hint (live, 18 Nov 2026:
        # "Yansar alutte si forora veli vello." with no hint at
        # all, "Asherahulet tishifu lorafel li galo." hinted
        # "am"): nothing readable — no Ge'ez, no digit, no link,
        # no known English or Oromo word. Answer honestly instead
        # of feeding it to the order flow, where the classifier
        # would call it off_topic and ask for English. Arabic
        # script is exempted above (the Arabic retry already
        # handled it), and Oromo is exempted by
        # _recognisable_english; "yes"/"ok" and quantities pass
        # because _looks_garbled counts them as readable.
        return ""
    return text


async def ai_vision(image_bytes: bytes, prompt: str = VISION_PROMPT) -> str:
    """Picture reading: ChatGPT vision when OPENAI_API_KEY is set,
    else Gemini vision."""
    if OPENAI_API_KEY:
        return await openai_vision(image_bytes, prompt=prompt)
    return await gemini_vision(image_bytes, prompt=prompt)


def parse_vision_result(text: str):
    """Parse Gemini vision output into a dict, or None when it has no
    usable JSON. Unknown/missing "want" becomes "other"; "amount" is
    coerced to a float when it parses. All fields default to None."""
    obj = extract_json(text)
    if obj is None:
        return None
    want = str(obj.get("want") or "").strip().lower()
    if want not in ("deposit_receipt", "order", "support", "other"):
        want = "other"
    amount = obj.get("amount")
    try:
        amount = float(amount) if amount is not None else None
    except (TypeError, ValueError):
        amount = None
    # Order from a screenshot (ideas batch 1 #10, 16 Nov 2026):
    # the platform/metric the picture shows, normalized through
    # the same detectors the text flow uses — a free-text value
    # vision invents ("cool stuff") never becomes a hint.
    platform = str(obj.get("platform") or "").strip().lower() or None
    if platform is not None and platform not in _PLATFORMS:
        platform = None
    metric = kind_from_text(str(obj.get("metric") or ""))
    return {
        "summary": obj.get("summary"),
        "amount": amount,
        "phone": obj.get("phone"),
        "tx_ref": obj.get("tx_ref"),
        "link": obj.get("link"),
        "username": obj.get("username"),
        "platform": platform,
        "metric": metric,
        "want": want,
    }


def platform_from_link(link: str):
    """Platform from a link's domain, or None. Used when a photo
    gives a profile/post link: the order flow can then skip the
    'which platform?' question and go straight to 'how many?'."""
    if not link:
        return None
    host = str(link).strip().lower()
    for domain, platform in (
        ("instagram.com", "instagram"),
        ("tiktok.com", "tiktok"),
        ("t.me", "telegram"),
        ("youtube.com", "youtube"),
        ("youtu.be", "youtube"),
        ("facebook.com", "facebook"),
        ("fb.com", "facebook"),
        ("x.com", "x"),
        ("twitter.com", "x"),
        ("spotify.com", "spotify"),
        ("open.spotify.com", "spotify"),
        ("twitch.tv", "twitch"),
        ("kick.com", "kick"),
        ("linkedin.com", "linkedin"),
        ("threads.net", "threads"),
        ("discord.com", "discord"),
        ("discord.gg", "discord"),
        ("snapchat.com", "snapchat"),
        ("reddit.com", "reddit"),
        ("pinterest.com", "pinterest"),
        ("shopee.", "shopee"),
        ("kwai.com", "kwai"),
        ("rutube.ru", "rutube"),
        ("bsky.app", "bluesky"),
        ("line.me", "line"),
        ("wa.me", "whatsapp"),
        ("whatsapp.com", "whatsapp"),
    ):
        if domain in host:
            return platform
    return None


