SEEN_UPDATES = set()
MAX_SEEN_UPDATES = 1000


def _update_seen(update) -> bool:
    """True when this Telegram update was already handled: the
    caller skips it. Records the id otherwise. Returns False for
    updates without an id."""
    update_id = getattr(update, "update_id", None)
    if update_id is None:
        return False
    if update_id in SEEN_UPDATES:
        return True
    if len(SEEN_UPDATES) >= MAX_SEEN_UPDATES:
        SEEN_UPDATES.clear()
    SEEN_UPDATES.add(update_id)
    return False
# ------------------------------------------------------- round 5 ------
# Round-5 helpers (13 Nov 2026): short names, bare quantities,
# price questions, reply/quote context, order history, voice fixes,
# GIFs/stickers, humor, off-topic steering, offensive users,
# conversation memory, order-now, delivery times, terms, ban answers.

# --- conversation memory: last ~10 exchanges per user ---------------
# Persisted to a local JSON file (best effort) so it survives a bot
# restart. Render's free disk is ephemeral on redeploy, so this is
# not permanent storage — see README, "Conversation memory".
CHAT_HISTORY_FILE = os.environ.get("CHAT_HISTORY_FILE", "chat_history.json")
MAX_HISTORY_EXCHANGES = 10
MAX_HISTORY_USERS = 500
CHAT_HISTORY = {}
_CHAT_HISTORY_LOADED = False
_LAST_HISTORY_SAVE = 0.0
_CURRENT_USER_ID = contextvars.ContextVar("paxyo_current_user", default=None)
_LAST_USER_TEXT = contextvars.ContextVar("paxyo_last_user_text", default=None)


def load_chat_history() -> None:
    """Load saved conversation memory (best effort)."""
    global _CHAT_HISTORY_LOADED
    if _CHAT_HISTORY_LOADED:
        return
    _CHAT_HISTORY_LOADED = True
    try:
        with open(CHAT_HISTORY_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, ValueError):
        return
    if not isinstance(data, dict):
        return
    for key, exchanges in data.items():
        try:
            user_id = int(key)
        except (TypeError, ValueError):
            continue
        if isinstance(exchanges, list):
            CHAT_HISTORY[user_id] = [
                e for e in exchanges
                if isinstance(e, dict) and e.get("user") and e.get("bot")
            ][-MAX_HISTORY_EXCHANGES:]


def save_chat_history() -> None:
    """Persist conversation memory (best effort — never raises).
    Throttled to one write per 5 seconds: the in-memory copy is
    always current, so a crash loses at most a few seconds."""
    global _LAST_HISTORY_SAVE
    import time

    now = time.monotonic()
    if now - _LAST_HISTORY_SAVE < 5:
        return
    _LAST_HISTORY_SAVE = now
    try:
        data = {
            str(uid): exchanges[-MAX_HISTORY_EXCHANGES:]
            for uid, exchanges in list(CHAT_HISTORY.items())[-MAX_HISTORY_USERS:]
        }
        with open(CHAT_HISTORY_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False)
    except OSError:
        pass


def record_exchange(user_id: int, user_text: str, bot_text: str) -> None:
    """Remember one user/bot exchange, capped at the last 10."""
    if not user_id or not (user_text or "").strip() or not (bot_text or "").strip():
        return
    load_chat_history()
    exchanges = CHAT_HISTORY.setdefault(int(user_id), [])
    exchanges.append({"user": user_text.strip()[:500], "bot": bot_text.strip()[:500]})
    del exchanges[:-MAX_HISTORY_EXCHANGES]
    if len(CHAT_HISTORY) > MAX_HISTORY_USERS:
        CHAT_HISTORY.pop(next(iter(CHAT_HISTORY)))
    save_chat_history()
    # Session store (smart-loop round 1, 14 Nov 2026): the durable
    # copy of this turn's history and draft goes to the API, so a
    # restart or redeploy does not wipe it. Best-effort and
    # throttled — see schedule_session_save.
    schedule_session_save(user_id)


def chat_history_lines(user_id: int, max_exchanges: int = 10):
    """'User: ... / Bot: ...' lines for the AI prompt, or []. Only
    the last `max_exchanges` turns (prompt shrink, 14 Nov 2026:
    the classifier does not need the whole chat — 3 turns is
    enough context and keeps the prompt small)."""
    load_chat_history()
    lines = []
    for e in CHAT_HISTORY.get(int(user_id), [])[-max_exchanges:]:
        lines.append(f"User: {e.get('user', '')}")
        lines.append(f"Bot: {e.get('bot', '')}")
    return lines


def history_summary_text(user_id: int, lang: str):
    """What this user talked about before, or None when there is
    nothing to remember."""
    load_chat_history()
    user_texts = [
        e.get("user", "") for e in CHAT_HISTORY.get(int(user_id), [])
        if e.get("user")
    ]
    if not user_texts:
        return None
    summary = "; ".join(user_texts[-3:])
    return t("history_summary", lang, summary=summary)


# --- session store: survive Render restarts AND redeploys ------------
# CHAT_HISTORY + PARTIAL live in memory and in a local JSON file, but
# Render's free disk is ephemeral on redeploy — a redeploy wipes
# both. The durable copy lives in Paxyo's MySQL, through the Bot API
# (api-bot-sessions.php): bot_sessions (telegram_id, history, draft,
# lang) and bot_confusions (the failure log). Every call is
# best-effort: when the API is unreachable the bot keeps working
# from memory and logs a warning — a chat is never broken by the
# store. (Smart-loop round 1, 14 Nov 2026.)
_SESSION_RESTORED = set()  # telegram_id: a restore was attempted this process
_LAST_SESSION_SAVE = {}  # telegram_id -> monotonic time of the last save
_SESSION_SAVE_MIN_SECONDS = 5.0
CONFUSIONS = []  # in-memory failure log, newest last, bounded
MAX_CONFUSIONS = 200
CONFUSION_REASONS = ("not_understood", "garbled", "correction", "abandoned")
FALLBACK_MISS = {}  # telegram_id -> consecutive fallback (miss) turns


def _session_payload(user_id: int) -> dict:
    """This user's session as the API stores it: the last 10
    exchanges, the order draft being built (or None), and the
    language of their last message."""
    return {
        "history": [
            {"user": e.get("user", ""), "bot": e.get("bot", "")}
            for e in CHAT_HISTORY.get(int(user_id), [])
        ][-MAX_HISTORY_EXCHANGES:],
        "draft": dict(PARTIAL.get(int(user_id)) or {}) or None,
        "lang": LAST_LANG.get(int(user_id)) or "en",
    }


async def _save_session_now(user_id: int) -> None:
    """One best-effort save to the API. Never raises."""
    if paxyo is None:
        return
    try:
        await paxyo.save_session(int(user_id), _session_payload(user_id))
    except Exception as exc:
        log.warning("session save failed: %s", exc)


def schedule_session_save(user_id: int) -> None:
    """Queue a best-effort session save (throttled to one per 5
    seconds per user, never raises). Called from record_exchange:
    every turn that changes the history or the draft saves, and a
    crash loses at most a few seconds. When there is no running
    event loop (sync unit tests) it quietly does nothing — the
    local file is the store there."""
    import time

    now = time.monotonic()
    last = _LAST_SESSION_SAVE.get(int(user_id), 0.0)
    if now - last < _SESSION_SAVE_MIN_SECONDS:
        return
    _LAST_SESSION_SAVE[int(user_id)] = now
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        return
    loop.create_task(_save_session_now(int(user_id)))


async def restore_session(user_id: int) -> None:
    """Load a stored session for a user with nothing in memory (a
    fresh process after a restart or redeploy). Runs once per user
    per process; a missing session, a not-yet-deployed endpoint, or
    a failed API call is a no-op — the user just starts fresh. The
    three API calls (traits, prefs, session) run concurrently in
    _restore_session_fetch instead of one after another (17 Nov
    2026: live they took ~2.9s + ~1.9s + ~2.2s in sequence, so
    the first turn after a restart paid ~7s)."""
    user_id = int(user_id)
    if user_id in _SESSION_RESTORED:
        return
    _SESSION_RESTORED.add(user_id)
    if paxyo is None:
        return
    await _restore_session_fetch(
        user_id,
        # A session fetch is skipped when in-memory state already
        # exists — the in-memory state is newer. Decided here, at
        # the moment the restore starts, not inside the fetch: a
        # background restore runs beside the reply, and the turn
        # builds its own state while the fetch is still queued.
        need_session=not (
            CHAT_HISTORY.get(user_id) or PARTIAL.get(user_id)
        ),
    )


_RESTORE_TASKS = set()  # in-flight background restores, kept alive until done


def schedule_session_restore(user_id: int) -> None:
    """Start a session restore in the background (best-effort,
    never raises): the turn that triggered it answers at once
    from fresh state and the restore lands a moment later for
    the next turn. The _SESSION_RESTORED guard is claimed here,
    synchronously, so a second turn arriving while the restore
    is still in flight never starts a second one — exactly the
    guard restore_session claims when awaited. When there is no
    running event loop (sync unit tests) it quietly does
    nothing, like schedule_session_save."""
    user_id = int(user_id)
    if user_id in _SESSION_RESTORED:
        return
    _SESSION_RESTORED.add(user_id)
    if paxyo is None:
        return
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        return
    _task = loop.create_task(_restore_session_background(
        user_id,
        # Decided here, synchronously — see restore_session: by
        # the time the background fetch runs, the turn may already
        # have built its own in-memory state.
        need_session=not (
            CHAT_HISTORY.get(user_id) or PARTIAL.get(user_id)
        ),
    ))
    _RESTORE_TASKS.add(_task)
    _task.add_done_callback(_RESTORE_TASKS.discard)


async def _restore_session_background(user_id: int, need_session: bool) -> None:
    """Background half of schedule_session_restore: the fetch
    itself, with every failure swallowed — a restore must never
    raise into a chat, and there is no caller here to raise to
    anyway (the per-call warnings inside still log). Cancelled
    cleanly like any other task (CancelledError is not an
    Exception, so it is not swallowed here)."""
    try:
        await _restore_session_fetch(user_id, need_session=need_session)
    except Exception as exc:
        log.warning("session restore failed: %s", exc)


async def _restore_session_fetch(user_id: int, need_session: bool) -> None:
    """The three restore fetches, concurrently: user-traits,
    user-prefs and the session. Each fetch has its own
    try/except (inside _restore_traits / _restore_prefs / the
    session job below), so one failing or slow endpoint never
    cancels the others and never raises into a chat — a missing
    piece just means the user starts fresh for that piece.

    Merge, don't clobber: this runs beside the reply now, so
    the turn that triggered it may already have recorded its
    own exchange or learned something newer while the fetches
    were in flight. The server history is older, so it goes
    first and the turn's own exchanges stay after it; a stored
    draft fills the gaps in a draft the turn already built for
    the same order, and a draft for a different order is left
    alone; traits and prefs fill only keys the turn has not set
    yet. The stored language is the durable truth, as before.
    """
    user_id = int(user_id)
    if paxyo is None:
        return
    _start = time.monotonic()
    # Per-user traits (feature 5, 15 Nov 2026): the learned usuals
    # + tone load alongside the session, from their own table — a
    # traits load can never touch the session. Runs even when the
    # session fetch below is skipped for in-memory state, so the
    # mirror is filled once per process either way.
    _jobs = [
        asyncio.create_task(_restore_traits(user_id)),
        asyncio.create_task(_restore_prefs(user_id)),
    ]
    if need_session:
        _jobs.append(asyncio.create_task(_fetch_session(user_id)))
    await asyncio.gather(*_jobs, return_exceptions=True)
    log.info("restore done %.2fs", time.monotonic() - _start)


async def _fetch_session(user_id: int) -> None:
    """One best-effort session fetch + apply (see
    _restore_session_fetch for the merge rules). Never raises."""
    user_id = int(user_id)
    try:
        data = await paxyo.load_session(user_id)
    except Exception as exc:
        log.warning("session load failed: %s", exc)
        return
    if not isinstance(data, dict):
        return
    history = data.get("history") or []
    if isinstance(history, list):
        _server_history = [
            {"user": str(e.get("user", "")), "bot": str(e.get("bot", ""))}
            for e in history
            if isinstance(e, dict) and e.get("user") and e.get("bot")
        ][-MAX_HISTORY_EXCHANGES:]
        CHAT_HISTORY[user_id] = (
            _server_history + CHAT_HISTORY.get(user_id, [])
        )[-MAX_HISTORY_EXCHANGES:]
    draft = data.get("draft")
    if isinstance(draft, dict) and draft:
        # Fill the gaps in the turn's own draft from the stored
        # one — but only when it is the same order (same
        # platform, or the turn has not picked one yet). The
        # stored draft's missing pieces (service hint, quantity)
        # complete a turn that only sent the link, which is how
        # a user resumes a half-built order after a restart. A
        # draft for a different platform is a new order: the
        # turn's own draft wins untouched.
        _current = PARTIAL.get(user_id) or {}
        _stored_platform = draft.get("platform")
        _current_platform = _current.get("platform")
        if not _current or _current_platform in (None, _stored_platform):
            _merged = {k: v for k, v in draft.items() if v is not None}
            _merged.update(
                {k: v for k, v in _current.items() if v is not None}
            )
            PARTIAL[user_id] = _merged
    lang = data.get("lang")
    if lang in ("en", "am", "ti", "om"):
        LAST_LANG[user_id] = lang


# --- per-user personality traits (feature 5, 15 Nov 2026) -----------
# The bot remembers each user: their usual order (platform, metric,
# quantity, service) and their tone (brief / chatty / formal). The
# durable copy lives in Paxyo's MySQL, in bot_user_traits — a
# SEPARATE table from bot_sessions, reached through the Bot API
# (api-user-traits.php) — so traits outlive a session clear and a
# traits save can never touch history/draft/lang. The bot keeps
# in-memory mirrors (USER_TRAITS and the learning counters below)
# so a chat works exactly as before when the API is down: every
# call is best-effort, 404-tolerant, and never raises into a chat.
# Traits are per-user private: they are never mentioned to anyone
# but the user themself, and never reveal another user's traits.
# Language is NOT a trait — bot_sessions.lang stays the single
# source of truth. Traits never change prices, totals, the Confirm
# flow, or which service is picked for a NEW order — they only
# shape prose replies and the "same as usual" fallback. What the
# customer ASKED FOR is different: explicit prefs (the pref_*
# section right after forget_traits below) DO change the pick, the
# rescue, and the Confirm flow — but only for the customer who
# set them.
USER_TRAITS = {}  # telegram_id -> {tone, usual_platform, usual_metric, usual_quantity, usual_service_id}
MAX_USER_TRAITS = 500  # in-memory mirrors only; the server copy is durable
_TRAITS_FROM_SERVER = set()  # telegram_id: mirror loaded from the API (a proven usual)
_LAST_TRAITS_SAVE = {}  # telegram_id -> monotonic time of the last traits save
_TRAITS_SAVE_MIN_SECONDS = 5.0  # same throttle as session saves
_USUAL_COUNTS = {}  # telegram_id -> {(platform, metric_slug): placed-order count}
_TONE_SIGNALS = {}  # telegram_id -> {"brief": n, "chatty": n, "formal": n}

# LEARNING THRESHOLDS (all conservative, all bot-side — the server
# accepts whatever validated traits the bot sends):
# - A usual needs the SAME platform+metric placed at least twice
#   (USUAL_MIN_PLACEMENTS). One placed order only proves the most
#   recent choice — it could be a one-off. Two shows a pattern.
# - A tone needs at least TONE_MIN_OBSERVATIONS votes for the same
#   tone, and it must lead the other tones. A trait is never set
#   from a single message.
# - Once a tone is set, a different tone replaces it only when its
#   votes exceed the current tone's votes by TONE_FLIP_MARGIN — one
#   contrary message never flips it.
USUAL_MIN_PLACEMENTS = 2
_TONE_MIN_OBSERVATIONS = 3
_TONE_FLIP_MARGIN = 3
_TONE_BRIEF_MAX_WORDS = 3  # a message this short (with words) votes "brief"
_TONE_CHATTY_MIN_WORDS = 12  # a message this long votes "chatty"
_FORMAL_WORDS = frozenset(("please", "kindly", "dear", "እባክዎ"))
_FORGET_TRAITS_PHRASES = (
    "forget what you know about me",
    "forget everything you know about me",
    "forget what you've learned about me",
    "forget what you have learned about me",
    "delete what you know about me",
    "forget about me",
    "forget me",
)


def _traits_entry(user_id: int) -> dict:
    """The in-memory traits mirror for a user, creating it when
    new. Bounded to MAX_USER_TRAITS users (oldest evicted first,
    counters included); the server copy is the durable one, so an
    eviction only loses the in-process mirror until their next
    message restores it from the API."""
    user_id = int(user_id)
    entry = USER_TRAITS.get(user_id)
    if entry is None:
        if len(USER_TRAITS) >= MAX_USER_TRAITS:
            oldest = next(iter(USER_TRAITS))
            USER_TRAITS.pop(oldest)
            _USUAL_COUNTS.pop(oldest, None)
            _TONE_SIGNALS.pop(oldest, None)
            _TRAITS_FROM_SERVER.discard(oldest)
            _LAST_TRAITS_SAVE.pop(oldest, None)
        entry = USER_TRAITS[user_id] = {}
    return entry


def _trait_slug(kind: str):
    """A metric kind as the server stores it: a lowercase slug
    ("comment likes" -> "comment_likes", "watch hours" ->
    "watch_hours", "views" -> "views"). None when there is no kind
    to store."""
    if not kind:
        return None
    slug = re.sub(r"[^a-z0-9]+", "_", str(kind).strip().lower()).strip("_")
    return slug or None


async def _save_traits_now(user_id: int, traits: dict) -> None:
    """One best-effort traits save to the API. Only the traits
    given are sent — the server merges, so a save can never wipe a
    field it was not told about. Never raises."""
    if paxyo is None:
        return
    try:
        await paxyo.save_traits(int(user_id), dict(traits or {}))
    except Exception as exc:
        log.warning("traits save failed: %s", exc)


def schedule_traits_save(user_id: int, traits: dict) -> None:
    """Queue a best-effort traits save (throttled to one per 5
    seconds per user, never raises) — the same shape as
    schedule_session_save. Traits change rarely, so a save dropped
    by the throttle is picked up by the next learning event, which
    re-sends the current values. When there is no running event
    loop (sync unit tests) it quietly does nothing."""
    import time

    now = time.monotonic()
    last = _LAST_TRAITS_SAVE.get(int(user_id), 0.0)
    if now - last < _TRAITS_SAVE_MIN_SECONDS:
        return
    _LAST_TRAITS_SAVE[int(user_id)] = now
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        return
    loop.create_task(_save_traits_now(int(user_id), traits))


async def _restore_traits(user_id: int) -> None:
    """Load a user's stored traits into the in-memory mirror.
    Best-effort like the session load: no stored traits, a
    not-yet-deployed endpoint (404), or a failed API call is a
    no-op — the user just has nothing learned yet. A mirror loaded
    from the server counts as established (see
    _usual_is_established): the server only ever stores a usual
    that already passed the placement threshold."""
    user_id = int(user_id)
    if paxyo is None:
        return
    try:
        traits = await paxyo.load_traits(user_id)
    except Exception as exc:
        log.warning("traits load failed: %s", exc)
        return
    if not isinstance(traits, dict) or not traits:
        return
    entry = _traits_entry(user_id)
    # Merge, don't overwrite: the turn that triggered this
    # restore may already have learned something newer while the
    # fetch was in flight (a background restore runs beside the
    # reply now). The server copy fills only keys the turn has
    # not set yet. Prefs load as their own parallel job in
    # _restore_session_fetch, not here.
    for key, value in traits.items():
        if value is not None and entry.get(key) is None:
            entry[key] = value
    _TRAITS_FROM_SERVER.add(user_id)


def user_tone(user_id: int):
    """This user's learned tone ("brief", "chatty", "formal"), or
    None when nothing has been learned yet — the caller then uses
    the default replies unchanged."""
    return (USER_TRAITS.get(int(user_id)) or {}).get("tone")


def tone_order_summary(user_id: int, lang: str, summary: str) -> str:
    """Shape an order confirmation for what the bot has learned
    about this user. Small, explicit, deterministic variations in
    the reply helper — NOT a prompt change, and never a price
    change: brief -> the summary alone (no humour line, no extra
    words); chatty -> the summary plus one warm line; formal -> a
    polite opening line before the summary. No learned tone -> the
    summary is returned unchanged, and the caller adds the humour
    line exactly as before."""
    tone = user_tone(user_id)
    if tone == "brief":
        return summary
    if tone == "chatty":
        return summary + "\n" + t("tone_chatty_order", lang)
    if tone == "formal":
        return t("tone_formal_order", lang) + "\n" + summary
    return summary


def _tone_signal(text: str):
    """The tone signal in one user message, or None. At most one
    signal per message, formal first: explicit politeness words
    ("please", "kindly", "dear") are the strongest formal marker,
    then a long message (>= _TONE_CHATTY_MIN_WORDS words) is chatty,
    then a very short one (1-_TONE_BRIEF_MAX_WORDS words) is brief.
    A bare number, link or emoji carries no words and no signal —
    "1000" is a quantity, not a tone."""
    words = re.findall(r"[a-z]+", (text or "").lower())
    words += re.findall(r"[\u1200-\u137c]+", text or "")
    if not words:
        return None
    if set(words) & _FORMAL_WORDS:
        return "formal"
    if len(words) >= _TONE_CHATTY_MIN_WORDS:
        return "chatty"
    if len(words) <= _TONE_BRIEF_MAX_WORDS:
        return "brief"
    return None


def observe_tone(user_id: int, text: str):
    """Learn this user's tone from their own messages only — never
    from the bot's replies, never invented. One message is one
    vote; the tone is set only after _TONE_MIN_OBSERVATIONS votes
    for the same tone, and only when that tone leads the others.
    Once set, a different tone replaces it only when its votes
    exceed the current tone's votes by _TONE_FLIP_MARGIN — one
    contrary message never flips it. Returns the new tone when it
    changed, else None. The save sends only the tone (the server
    merges)."""
    signal = _tone_signal(text)
    if signal is None:
        return None
    user_id = int(user_id)
    signals = _TONE_SIGNALS.setdefault(
        user_id, {"brief": 0, "chatty": 0, "formal": 0}
    )
    signals[signal] = signals.get(signal, 0) + 1
    traits = _traits_entry(user_id)
    current = traits.get("tone")
    if current is None:
        others = max(signals[o] for o in signals if o != signal)
        if signals[signal] >= _TONE_MIN_OBSERVATIONS and signals[signal] > others:
            traits["tone"] = signal
            schedule_traits_save(user_id, {"tone": signal})
            return signal
        return None
    if signal != current and (
        signals[signal] - signals.get(current, 0) >= _TONE_FLIP_MARGIN
    ):
        traits["tone"] = signal
        schedule_traits_save(user_id, {"tone": signal})
        return signal
    return None


def learn_from_placed_order(user_id: int, service: dict, quantity) -> None:
    """Learn the usuals from a PLACED order — a placed order is
    proof, not a guess. The mirror always keeps the most recent
    placed order (platform, metric, quantity, service id), but it
    only counts as the user's "usual" for defaults — and only gets
    saved to the server — once the same platform+metric has been
    placed USUAL_MIN_PLACEMENTS times (see the counting rule in the
    thresholds comment above). A service with no recognisable
    platform or metric teaches nothing. The save sends only the
    four usual fields (the server merges)."""
    user_id = int(user_id)
    service = service or {}
    platform, _hint = _platform_hint_of_service(service)
    kind = kind_from_text(
        f"{service.get('name') or ''} {service.get('category') or ''}"
    )
    if not platform or not kind:
        return
    metric = _trait_slug(kind)
    if not metric:
        return
    try:
        bare = int(service.get("service") or 0) or None
    except (TypeError, ValueError):
        bare = None
    if not bare:
        return
    # Learn the COMBINED id ("gop:<id>" / "smm:<id>", second
    # provider, 15 Nov 2026): a bare id alone could make "same as
    # usual" re-pin the other provider's service of the same
    # number. The server accepts the combined id string (see
    # api-user-traits.php); old bare-int traits still resolve.
    service_id = service_combined_id(service)
    try:
        quantity = int(quantity) if quantity is not None else None
    except (TypeError, ValueError):
        quantity = None
    traits = _traits_entry(user_id)
    old_key = (traits.get("usual_platform"), traits.get("usual_metric"))
    counts = _USUAL_COUNTS.setdefault(user_id, {})
    key = (platform, metric)
    counts[key] = counts.get(key, 0) + 1
    traits["usual_platform"] = platform
    traits["usual_metric"] = metric
    if quantity and quantity > 0:
        traits["usual_quantity"] = quantity
    traits["usual_service_id"] = service_id
    if key != old_key:
        # The usual changed to a pattern the server has never
        # stored: the server provenance no longer applies to these
        # values, and only the fresh count can establish them.
        _TRAITS_FROM_SERVER.discard(user_id)
    if counts[key] >= USUAL_MIN_PLACEMENTS:
        # Only the fields actually learned are sent (the server
        # merges) — a None quantity is left out, never sent as
        # null, or it would clear the stored quantity.
        _save = {
            "usual_platform": platform,
            "usual_metric": metric,
            "usual_service_id": service_id,
        }
        if quantity and quantity > 0:
            _save["usual_quantity"] = quantity
        schedule_traits_save(user_id, _save)


def _usual_is_established(user_id: int) -> bool:
    """True when the mirror's usual may drive defaults: either the
    same platform+metric was placed USUAL_MIN_PLACEMENTS times in
    this process, or the mirror was loaded from the server (the
    server only ever stores a usual that already passed the
    threshold, so a restart never has to re-count)."""
    traits = USER_TRAITS.get(int(user_id)) or {}
    platform = traits.get("usual_platform")
    metric = traits.get("usual_metric")
    if not platform or not metric or not traits.get("usual_service_id"):
        return False
    if int(user_id) in _TRAITS_FROM_SERVER:
        return True
    counts = _USUAL_COUNTS.get(int(user_id)) or {}
    return counts.get((platform, metric), 0) >= USUAL_MIN_PLACEMENTS


def is_forget_traits_request(text: str) -> bool:
    """True when the user asks the bot to forget what it learned
    about them ("forget what you know about me", "forget me").
    A negation ("don't forget me", "never forget me") is the
    opposite request and does not match."""
    s = " ".join((text or "").strip().lower().split())
    if not s:
        return False
    if any(n in s for n in ("don't", "do not", "dont", "never")):
        return False
    return any(p in s for p in _FORGET_TRAITS_PHRASES)


async def forget_traits(user_id: int) -> None:
    """Wipe this user's learned traits: the server row (POST
    /user-traits/clear, best-effort, 404-tolerant) and the
    in-memory mirror + learning counters. The session (history,
    draft, language) is untouched — forgetting traits is not
    forgetting the conversation."""
    user_id = int(user_id)
    USER_TRAITS.pop(user_id, None)
    _USUAL_COUNTS.pop(user_id, None)
    _TONE_SIGNALS.pop(user_id, None)
    _TRAITS_FROM_SERVER.discard(user_id)
    _LAST_TRAITS_SAVE.pop(user_id, None)
    if paxyo is None:
        return
    try:
        await paxyo.clear_traits(user_id)
    except Exception as exc:
        log.warning("traits clear failed: %s", exc)


# --- per-customer order preferences (customizations, 15 Nov 2026) -----
# What the customer ASKED FOR, in plain words in chat ("cheapest
# first", "ask me before you change service", "my link is ...",
# "never slower than 1 hour"). Stored in the SAME in-memory mirror
# (USER_TRAITS) and the SAME server table (bot_user_traits) as the
# learned traits, under keys prefixed "pref_" — but the two are
# deliberately different things and never overwrite each other:
#   * learned traits (usual_platform etc.) are what the bot
#     LEARNED from placed orders — they only shape prose replies
#     and the "same as usual" fallback, and NEVER change which
#     service is picked for a new order;
#   * explicit prefs (pref_*) are what the customer ASKED FOR —
#     they DO change the pick, the rescue, and the Confirm flow,
#     but ONLY for the customer who set them, and ONLY while the
#     pref is set. Everyone who set nothing gets the NORMAL way,
#     unchanged: fastest-first, auto-rescue, no ceiling, no quiet
#     hours, Confirm card on every order.
# Prefs are per-user private, never mentioned to anyone but the
# user themself. Server side they ride api-user-prefs.php (same
# merge shape as api-user-traits.php, prf_ prefix); the bot sends
# ONLY the prefs that changed, and a field sent as null clears it.
# Every pref value is validated before it is stored (see
# validate_pref) so a stale or hand-edited row can never inject
# an invalid pref. All helpers are pure and sync unless they touch
# the API — the order flow calls them, the tests call them.
PREF_KEYS = frozenset((
    "pref_pick_order", "pref_ask_first", "pref_max_slowness_min",
    "pref_default_link", "pref_default_quantity", "pref_price_ceiling",
    "pref_refill_only", "pref_auto_repeat", "pref_topup_missing",
    "pref_no_confirm", "pref_no_confirm_max_etb", "pref_quiet_hours",
    # New options (21, 24, 25, 27, 30-40), 15 Nov 2026.
    "pref_favourite_services", "pref_low_balance_alert_etb",
    "pref_weekly_spend_limit_etb", "pref_saved_links",
    "pref_auto_cancel_min", "pref_start_fast_only", "pref_language",
    "pref_double_confirm_etb", "pref_banned_services", "pref_try_new",
    "pref_watch_post", "pref_wait_price", "pref_monthly_report",
))
# #18 (place small orders without asking): a customer may set their
# own cap, but never above this — a "small order" the bot places
# without a Confirm card is at most 100 ETB. Default when they
# set the pref without a number: 50 ETB.
MAX_NO_CONFIRM_ETB = 100
DEFAULT_NO_CONFIRM_MAX_ETB = 50
# #19 (quiet hours): "at night" with no times means 22:00–07:00 EAT.
QUIET_DEFAULT = ("22:00", "07:00")
# #15 (drip-feed): a run must be at least 30 minutes apart, and a
# drip spans at most 30 days.
DRIP_MIN_INTERVAL_MINUTES = 30
DRIP_MAX_SPAN_MINUTES = 43200
# #8 (max slowness): a limit of more than 7 days is meaningless.
PREF_MAX_SLOWNESS_MAX_MIN = 10080
# #36 (start fast only): a service counts as fast-starting when its
# claimed average time is 15 minutes or less.
START_FAST_MAX_MIN = 15
# #39 (ban list): at most 50 banned services; #21 (favourites): at
# most 20. Service ids are stored as bare strings ("5535") — the
# same shape the customer types in chat.
MAX_FAVOURITE_SERVICES = 20
MAX_BANNED_SERVICES = 50
_PREFS_FROM_SERVER = set()  # telegram_id: prefs loaded from the API
_LAST_PREFS_SAVE = {}  # telegram_id -> monotonic time of the last prefs save
_PREFS_SAVE_MIN_SECONDS = 5.0  # same throttle as traits saves


def _parse_clock(value):
    """A clock time as "HH:MM", or None. Accepts "22:00", "22",
    "10pm", "10 pm", "7:30am"."""
    if value is None:
        return None
    s = str(value).strip().lower()
    match = re.fullmatch(r"(\d{1,2})(?::(\d{2}))?\s*(am|pm)?", s)
    if not match:
        return None
    hour = int(match.group(1))
    minute = int(match.group(2) or 0)
    meridiem = match.group(3)
    if meridiem:
        if not 1 <= hour <= 12:
            return None
        if meridiem == "pm" and hour != 12:
            hour += 12
        if meridiem == "am" and hour == 12:
            hour = 0
    if not 0 <= hour <= 23 or not 0 <= minute <= 59:
        return None
    return f"{hour:02d}:{minute:02d}"


def _validate_link(value):
    """A link value as stored (default link, saved links, watch
    post), or None when it is not a link."""
    if not isinstance(value, str):
        return None
    link = value.strip()
    if not link or " " in link:
        return None
    if link.startswith(("http://", "https://", "t.me/", "www.", "@")):
        return link
    if re.fullmatch(r"[a-z0-9.-]+\.[a-z]{2,}(/\S*)?", link):
        return link
    return None


def _validate_service_id_list(value, max_len):
    """A list of bare service-id strings ("5535"), cleaned and
    deduped in order, or None when it is not such a list. Used
    for favourites (#21) and the ban list (#39)."""
    if not isinstance(value, list):
        return None
    cleaned = []
    for item in value:
        item = str(item).strip()
        if not re.fullmatch(r"\d{1,8}", item):
            return None
        if item not in cleaned:
            cleaned.append(item)
    if not cleaned or len(cleaned) > max_len:
        return None
    return cleaned


def validate_pref(key, value):
    """Clean one pref value, or None when it is invalid. Only the
    whitelisted keys are accepted; anything else returns None."""
    if key == "pref_pick_order":
        return value if value in ("fastest", "cheapest") else None
    if key in (
        "pref_ask_first", "pref_refill_only", "pref_topup_missing",
        "pref_no_confirm", "pref_start_fast_only", "pref_try_new",
        "pref_monthly_report",
    ):
        return value if isinstance(value, bool) else None
    if key == "pref_max_slowness_min":
        try:
            minutes = int(value)
        except (TypeError, ValueError):
            return None
        return minutes if 5 <= minutes <= PREF_MAX_SLOWNESS_MAX_MIN else None
    if key == "pref_default_link":
        return _validate_link(value)
    if key == "pref_favourite_services":
        return _validate_service_id_list(value, MAX_FAVOURITE_SERVICES)
    if key == "pref_banned_services":
        return _validate_service_id_list(value, MAX_BANNED_SERVICES)
    if key == "pref_low_balance_alert_etb":
        try:
            amount = int(value)
        except (TypeError, ValueError):
            return None
        return amount if 1 <= amount <= 100000 else None
    if key == "pref_weekly_spend_limit_etb":
        try:
            amount = int(value)
        except (TypeError, ValueError):
            return None
        return amount if 1 <= amount <= 1000000 else None
    if key == "pref_double_confirm_etb":
        try:
            amount = int(value)
        except (TypeError, ValueError):
            return None
        return amount if 1 <= amount <= 1000000 else None
    if key == "pref_auto_cancel_min":
        try:
            minutes = int(value)
        except (TypeError, ValueError):
            return None
        return minutes if 5 <= minutes <= PREF_MAX_SLOWNESS_MAX_MIN else None
    if key == "pref_language":
        return value if value in ("en", "am", "ti", "om") else None
    if key == "pref_saved_links":
        if not isinstance(value, dict):
            return None
        cleaned = {}
        for name, link in value.items():
            name = str(name).strip().lower()
            if not re.fullmatch(r"[a-z0-9_-]{1,30}", name):
                return None
            clean_link = _validate_link(link)
            if clean_link is None:
                return None
            cleaned[name] = clean_link
        return cleaned if cleaned and len(cleaned) <= 10 else None
    if key == "pref_watch_post":
        if not isinstance(value, dict):
            return None
        link = _validate_link(value.get("link"))
        if link is None:
            return None
        cleaned = {"link": link}
        below = value.get("below")
        if below is not None:
            try:
                below = int(below)
            except (TypeError, ValueError):
                return None
            if not 1 <= below <= 100_000_000:
                return None
            cleaned["below"] = below
        return cleaned
    if key == "pref_wait_price":
        if not isinstance(value, dict):
            return None
        platform = value.get("platform")
        metric = value.get("metric")
        if not (
            isinstance(platform, str) and platform
            and isinstance(metric, str) and metric
        ):
            return None
        try:
            target = float(value.get("target"))
        except (TypeError, ValueError):
            return None
        if not 0 < target <= 100000:
            return None
        return {
            "platform": platform, "metric": metric, "target": target,
        }
    if key == "pref_default_quantity":
        if not isinstance(value, dict):
            return None
        cleaned = {}
        for qty_key, qty in value.items():
            qty_key = str(qty_key)
            if qty_key != "*" and not re.fullmatch(
                r"(?:[a-z]+:)?[a-z_]+", qty_key
            ):
                return None
            try:
                qty = int(qty)
            except (TypeError, ValueError):
                return None
            if not 1 <= qty <= 100_000_000:
                return None
            cleaned[qty_key] = qty
        return cleaned if cleaned else None
    if key == "pref_price_ceiling":
        try:
            price = float(value)
        except (TypeError, ValueError):
            return None
        return price if 0 < price <= 100000 else None
    if key == "pref_auto_repeat":
        if not isinstance(value, dict):
            return None
        try:
            interval = int(value.get("interval_minutes"))
        except (TypeError, ValueError):
            return None
        if not MIN_RECURRING_MINUTES <= interval <= DRIP_MAX_SPAN_MINUTES:
            return None
        platform = value.get("platform")
        metric = value.get("metric")
        if not (
            isinstance(platform, str) and platform
            and isinstance(metric, str) and metric
        ):
            return None
        return {
            "interval_minutes": interval,
            "platform": platform,
            "metric": metric,
        }
    if key == "pref_no_confirm_max_etb":
        try:
            cap = int(value)
        except (TypeError, ValueError):
            return None
        return cap if 1 <= cap <= MAX_NO_CONFIRM_ETB else None
    if key == "pref_quiet_hours":
        if not isinstance(value, dict):
            return None
        start = _parse_clock(value.get("start"))
        end = _parse_clock(value.get("end"))
        if not start or not end or start == end:
            return None
        return {"start": start, "end": end}
    return None


def get_pref(user_id, key, default=None):
    """One pref from the in-memory mirror, or `default` when the
    customer never set it. Never raises."""
    entry = USER_TRAITS.get(int(user_id)) or {}
    value = entry.get(key)
    return default if value is None else value


def set_pref(user_id, key, value):
    """Validate + store one pref in the mirror and queue a server
    save. Returns the stored (cleaned) value, or None when the
    value is invalid — nothing is stored then."""
    cleaned = validate_pref(key, value)
    if cleaned is None:
        return None
    user_id = int(user_id)
    _traits_entry(user_id)[key] = cleaned
    schedule_prefs_save(user_id, {key: cleaned})
    return cleaned


def clear_pref(user_id, key):
    """Drop one pref from the mirror and the server (sends null —
    the server clears that field, nothing else)."""
    user_id = int(user_id)
    (USER_TRAITS.get(user_id) or {}).pop(key, None)
    schedule_prefs_save(user_id, {key: None})


async def _save_prefs_now(user_id: int, prefs: dict) -> None:
    """One best-effort prefs save to the API. Only the prefs given
    are sent — the server merges, so a save can never wipe a field
    it was not told about. Never raises."""
    if paxyo is None:
        return
    try:
        await paxyo.save_prefs(int(user_id), dict(prefs or {}))
    except Exception as exc:
        log.warning("prefs save failed: %s", exc)


def schedule_prefs_save(user_id: int, prefs: dict) -> None:
    """Queue a best-effort prefs save (throttled to one per 5
    seconds per user, never raises) — the same shape as
    schedule_traits_save. When there is no running event loop
    (sync unit tests) it quietly does nothing."""
    import time

    now = time.monotonic()
    last = _LAST_PREFS_SAVE.get(int(user_id), 0.0)
    if now - last < _PREFS_SAVE_MIN_SECONDS:
        return
    _LAST_PREFS_SAVE[int(user_id)] = now
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        return
    loop.create_task(_save_prefs_now(int(user_id), prefs))


async def _restore_prefs(user_id: int) -> None:
    """Load a user's stored prefs into the in-memory mirror (once
    per process per user). Best-effort like the traits load: no
    stored prefs, a not-yet-deployed endpoint (404), or a failed
    API call is a no-op — the user just has nothing set yet. Only
    whitelisted, validated keys land in the mirror."""
    user_id = int(user_id)
    if user_id in _PREFS_FROM_SERVER:
        return
    _PREFS_FROM_SERVER.add(user_id)
    if paxyo is None:
        return
    try:
        stored = await paxyo.load_prefs(user_id)
    except Exception as exc:
        log.warning("prefs load failed: %s", exc)
        return
    if not isinstance(stored, dict):
        return
    entry = _traits_entry(user_id)
    for key, value in stored.items():
        if key in PREF_KEYS and value is not None:
            cleaned = validate_pref(key, value)
            # Merge, don't overwrite (see _restore_traits): the
            # turn that triggered this restore may already have
            # set a newer value while the fetch was in flight.
            if cleaned is not None and entry.get(key) is None:
                entry[key] = cleaned


# --- pref accessors (what the order/rescue code reads) ---------------
def pref_pick_order(user_id):
    """The customer's pick order: "fastest" (the default for
    everyone) or "cheapest" (only when they explicitly set it)."""
    return get_pref(user_id, "pref_pick_order") or "fastest"


def pref_ask_first(user_id):
    """True only when the customer set ask-first (#6): the bot
    asks before moving a stuck order to another service."""
    return bool(get_pref(user_id, "pref_ask_first"))


def pref_topup_missing(user_id):
    """True only when the customer set top-up (#17): when only
    part of an order delivers, the bot orders the missing part
    itself instead of only refunding."""
    return bool(get_pref(user_id, "pref_topup_missing"))


def pref_no_confirm_cap(user_id):
    """(allowed, cap_etb): whether small orders go without a
    Confirm card (#18), and the cap the customer set (default 50,
    hard cap 100 ETB)."""
    if not get_pref(user_id, "pref_no_confirm"):
        return (False, 0)
    return (
        True,
        get_pref(user_id, "pref_no_confirm_max_etb")
        or DEFAULT_NO_CONFIRM_MAX_ETB,
    )


def pref_default_quantity(user_id, platform, metric):
    """The customer's usual quantity for a platform+metric, or
    None. Lookup: exact "platform:metric", then "*:metric", then
    the global "*"."""
    stored = get_pref(user_id, "pref_default_quantity") or {}
    for key in (f"{platform}:{metric}", f"*:{metric}", "*"):
        if key in stored:
            return stored[key]
    return None


def pref_quiet_hours(user_id):
    """(start, end) as "HH:MM" EAT strings, or None when the
    customer set no quiet hours (#19)."""
    stored = get_pref(user_id, "pref_quiet_hours")
    if not isinstance(stored, dict):
        return None
    start = _parse_clock(stored.get("start"))
    end = _parse_clock(stored.get("end"))
    if not start or not end:
        return None
    return (start, end)


def in_quiet_hours(user_id, now=None):
    """True when `now` (EAT, default now) falls inside the
    customer's quiet hours. Handles the overnight wrap (22:00–
    07:00) and a same-day span (01:00–05:00) alike."""
    hours = pref_quiet_hours(user_id)
    if not hours:
        return False
    now = (now or datetime.now(EAT_TZ)).astimezone(EAT_TZ)
    start, end = hours
    cur = f"{now.hour:02d}:{now.minute:02d}"
    if start < end:
        return start <= cur < end
    return cur >= start or cur < end


_PREF_INF = 10 ** 9  # "unknown average time" for a time filter


def filter_pref_candidates(services, user_id, deadline=None, now=None,
                         skip_ceiling=False):
    """Filter a candidate list by the customer's prefs (+ an
    optional per-order deadline). Returns (kept, blocked_by):
    kept is the filtered list (same order), blocked_by is None
    when nothing was filtered out, or the first filter that
    emptied the list ("max_slowness", "price_ceiling",
    "refill_only", "banned", "start_fast", "deadline"). A service with an UNKNOWN
    average time is excluded by a time filter — the bot cannot
    prove it meets the limit. The caller warns the customer
    when blocked_by is set. `skip_ceiling` is for rescues: the
    confirmed-total cap already enforces the ceiling there (the
    original service passed it, and the +10% band is Paxyo-paid,
    so the customer's effective rate never exceeds it) — a rate
    filter would wrongly kill the band."""
    pool = list(services or [])
    blocked_by = None
    limit = get_pref(user_id, "pref_max_slowness_min")
    if limit is not None and pool:
        kept = [
            s for s in pool
            if (parse_average_time(s.get("average_time")) or _PREF_INF) <= limit
        ]
        if kept:
            pool = kept
        else:
            pool, blocked_by = [], "max_slowness"
    ceiling = None if skip_ceiling else get_pref(user_id, "pref_price_ceiling")
    if ceiling is not None and pool:
        kept = [
            s for s in pool
            if float(s.get("rate_etb_per_1000") or 0) <= ceiling
        ]
        if kept:
            pool = kept
        else:
            pool, blocked_by = [], "price_ceiling"
    if get_pref(user_id, "pref_refill_only") and pool:
        kept = [s for s in pool if s.get("refill")]
        if kept:
            pool = kept
        else:
            pool, blocked_by = [], "refill_only"
    banned = get_pref(user_id, "pref_banned_services") or []
    if banned and pool:
        kept = [
            s for s in pool
            if str(s.get("service")) not in banned
            and str((s.get("combined_id") or "").split(":")[-1])
            not in banned
        ]
        if kept:
            pool = kept
        else:
            pool, blocked_by = [], "banned"
    if get_pref(user_id, "pref_start_fast_only") and pool:
        kept = [
            s for s in pool
            if (parse_average_time(s.get("average_time")) or _PREF_INF)
            <= START_FAST_MAX_MIN
        ]
        if kept:
            pool = kept
        else:
            pool, blocked_by = [], "start_fast"
    if deadline is not None and pool:
        now = (now or datetime.now(EAT_TZ)).astimezone(EAT_TZ)
        minutes_left = (
            deadline - now
        ).total_seconds() / 60.0
        kept = [
            s for s in pool
            if (parse_average_time(s.get("average_time")) or _PREF_INF)
            <= minutes_left
        ]
        if kept:
            pool = kept
        else:
            pool, blocked_by = [], "deadline"
    return pool, blocked_by


_WEEKDAY_NUMBERS = {
    "monday": 0, "tuesday": 1, "wednesday": 2, "thursday": 3,
    "friday": 4, "saturday": 5, "sunday": 6,
}


def parse_deadline(text, now=None):
    """The delivery deadline a customer set ("i need it by friday
    5pm", "by tomorrow 5pm", "by 5pm", "need it in 2 hours"), as
    an aware EAT datetime, or None when the message sets no
    deadline. Only "by"/"before" + a clock time or day word, or
    "need it in N hours", counts — a plain "in 2 hours" is the
    delayed-order flow ("place it after 2 hours"), NOT a
    deadline, and "by tomorrow" with no time means tomorrow
    23:59. A clock time that already passed rolls forward (next
    day, or next week for a named weekday)."""
    if not text:
        return None
    s = " ".join(str(text).strip().lower().split())
    now = (now or datetime.now(EAT_TZ)).astimezone(EAT_TZ)
    # "need it in N hours/mins" — a deadline counted from now.
    units = {
        "day": 1440, "days": 1440,
        "hour": 60, "hours": 60, "hr": 60, "hrs": 60,
        "minute": 1, "minutes": 1, "min": 1, "mins": 1,
    }
    match = re.search(
        r"\bneed(?: it)? (?:by|in)\s+(\d+)\s*"
        r"(days?|hours?|hrs?|minutes?|mins?)\b",
        s,
    )
    if match:
        return now + timedelta(
            minutes=int(match.group(1)) * units[match.group(2)]
        )
    # "by"/"before" + [day word] + [clock time].
    match = re.search(r"\b(?:by|before)\b\s*(.+)$", s)
    if not match:
        return None
    tail = match.group(1)
    day = now.date()
    weekday = None
    for name, number in _WEEKDAY_NUMBERS.items():
        if re.search(rf"\b{name}\b", tail):
            weekday = number
            break
    if "tomorrow" in tail:
        day = day + timedelta(days=1)
    elif weekday is not None:
        day = day + timedelta(days=(weekday - now.weekday()) % 7)
    clock = None
    clock_match = re.search(r"(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b", tail)
    if clock_match:
        clock = _parse_clock(clock_match.group(0))
    else:
        clock_match = re.search(r"\b(\d{1,2}):(\d{2})\b", tail)
        if clock_match:
            clock = _parse_clock(clock_match.group(0))
    if clock is None:
        if "tomorrow" in tail or weekday is not None:
            clock = "23:59"
        else:
            return None
    hour, minute = (int(part) for part in clock.split(":"))
    deadline = datetime(
        day.year, day.month, day.day, hour, minute, tzinfo=EAT_TZ
    )
    if deadline <= now:
        deadline = deadline + timedelta(
            days=7 if weekday is not None else 1
        )
    return deadline


def parse_drip_span(text):
    """The span of a spread/drip-feed request in minutes, or None.
    "spread 10000 views over 2 days" -> 2880, "drip-feed it over
    3 hours" -> 180, "deliver it slowly over a day" -> 1440. The
    words spread/drip/slowly/gradually AND "over" + a duration
    must both be present — a plain "over 2 days" without them is
    not a drip request. "a day"/"an hour" count as 1."""
    if not text:
        return None
    s = " ".join(str(text).strip().lower().split())
    if not re.search(
        r"\b(spread|drip|drip-feed|dripfeed|slowly|gradually)\b", s
    ):
        return None
    match = re.search(r"\bover\b\s*(.+)$", s)
    if not match:
        return None
    tail = match.group(1)
    units = {
        "day": 1440, "days": 1440,
        "hour": 60, "hours": 60, "hr": 60, "hrs": 60,
        "minute": 1, "minutes": 1, "min": 1, "mins": 1,
    }
    total = 0
    found = False
    for number, unit in re.findall(
        r"(\d+)\s*(days?|hours?|hrs?|minutes?|mins?)", tail
    ):
        total += int(number) * units[unit]
        found = True
    if not found:
        word = re.search(r"\b(?:a|an|one)\s+(day|hour|minute)\b", tail)
        if word:
            total = units[word.group(1)]
            found = True
    if not found or total <= 0:
        return None
    return min(total, DRIP_MAX_SPAN_MINUTES)


def drip_plan(quantity, service, span_min):
    """Split a quantity into provider drip-feed runs, or None when
    it cannot be split evenly. Returns (runs, interval_min,
    per_run_qty): the per-run qty is a multiple of 10 and at
    least the service minimum, runs >= 2, interval >= 30
    minutes. Tries 10, 5, then 2 runs — the finest even split
    that fits."""
    try:
        qty = int(quantity)
    except (TypeError, ValueError):
        return None
    try:
        span = int(span_min)
    except (TypeError, ValueError):
        return None
    if qty <= 0 or span < 2 * DRIP_MIN_INTERVAL_MINUTES:
        return None
    minimum = _ceil_to_10(_service_min_qty(service))
    for runs in (10, 5, 2):
        if qty % runs != 0:
            continue
        per_run = qty // runs
        if per_run % 10 != 0:
            continue
        if per_run < minimum:
            continue
        interval = span // runs
        if interval < DRIP_MIN_INTERVAL_MINUTES:
            continue
        return (runs, interval, per_run)
    return None


# --- auto-refill / keep-above-target: count checks ------------------
# The bot checks a live count every hour and tops it back up to
# the target from the user's balance (19 Nov 2026). The count
# comes from a FALLBACK CHAIN of free providers, cheapest first,
# so no single free allowance decides whether refills work:
#
#   0. own scraper — fetch the public page directly and read the
#      count out of it (TikTok, YouTube, Telegram). No allowance
#      at all, but a page can block us, so it falls through.
#   1. EnsembleData — 50 units/day free trial (trial ends 26 Nov
#      2026; after that unknown). TikTok video 2 units, TikTok
#      user 1 unit. Token from ENSEMBLEDATA_API_TOKEN only.
#   2. SocialHolmes — new unified API (api.socialholmes.com),
#      async start-run + poll, Bearer key from
#      SOCIALHOLMES_API_TOKEN. TikTok video (play_count) and
#      profile (follower_count), 1 result per check out of the
#      first 1,000 free results, one-time — enforced as a total
#      budget in code, not a daily one. A run that returns
#      nothing costs nothing, so only delivered answers spend it.
#   3. Scrape Everything — 100 credits one-time on signup (the
#      account exists already). Its TikTok lookup FAILED 8 times
#      on 19 Nov (PROXY_CONNECT_FAILED / PARSE_ERROR: TikTok
#      blocked it), so it is a fallback only, never first.
#   4. YouTube Data API v3 — official, free 10,000 quota units a
#      day; a video/channel lookup costs 1 unit.
#   5. Telegram Bot API getChatMemberCount — free, no quota, for
#      Telegram channel members (the bot must be able to see the
#      channel; a channel it cannot see answers with an error and
#      the chain moves on).
#
# Instagram stays on the API providers: its public pages mostly
# need a login now, so the own scraper does not cover it.
#
# Rules the chain keeps: a failed call never consumes budget
# (providers refund failures too); a 429 parks that provider for
# an hour; a count fetched in the last 30 minutes is reused
# instead of spending units again; per-provider daily usage lives
# in the refill record itself (count_usage), so it survives a
# restart when the server persists the record in bot_refills.
# No token or key is ever hard-coded here — every provider reads
# its credential from the environment, and a provider with no
# credential configured is simply skipped.
COUNT_CACHE_TTL_SECONDS = 1800  # 30 minutes: reuse a fresh count
_COUNT_CACHE = {}  # (platform, metric, link) -> (count, provider, at)
COUNT_SCRAPER_TIMEOUT_SECONDS = 10.0  # short: a slow page must not stall the check
COUNT_SCRAPER_USER_AGENT = (
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
    "AppleWebKit/537.36 (KHTML, like Gecko) "
    "Chrome/120.0.0.0 Safari/537.36"
)

# Per-provider daily budgets the code enforces. None means no
# daily cap is tracked here: Scrape Everything's 100 credits are
# one-time (its own balance is the limit) and Telegram has no
# quota. SocialHolmes has no daily cap either — its first 1,000
# results are free ONE-TIME, so it carries a total_budget
# instead (see CountUsage): once 1,000 results are used, the
# chain skips it until the operator tops the account up and
# resets the counter.
COUNT_PROVIDERS = {
    "own_scraper": {"daily_budget": None, "cost": 0, "enabled": True},
    "ensembledata": {"daily_budget": 50, "cost": 2, "enabled": True},
    "socialholmes": {
        "daily_budget": None, "cost": 1, "enabled": True,
        "total_budget": 1000,
    },
    "scrapeeverything": {"daily_budget": None, "cost": 1, "enabled": True},
    "youtube": {"daily_budget": 10000, "cost": 1, "enabled": True},
    "telegram": {"daily_budget": None, "cost": 0, "enabled": True},
}
# (platform, metric) -> providers in try order. SocialHolmes sits
# second for TikTok, after EnsembleData and before Scrape
# Everything. Instagram has no chain yet: no free provider is
# wired for it, so setup refuses it honestly.
COUNT_CHAIN = {
    ("tiktok", "views"): [
        "own_scraper", "ensembledata", "socialholmes", "scrapeeverything",
    ],
    ("tiktok", "followers"): [
        "own_scraper", "ensembledata", "socialholmes", "scrapeeverything",
    ],
    ("youtube", "views"): ["own_scraper", "youtube"],
    ("youtube", "subscribers"): ["own_scraper", "youtube"],
    ("telegram", "members"): ["own_scraper", "telegram"],
}
# SocialHolmes — WIRED 19 Nov 2026 (new unified API at
# api.socialholmes.com, docs developers.socialholmes.com; the
# old TikTok-only API at tik.socialholmes.com is dead). The
# account is abatejohannes@gmail.com with the first 1,000
# results free, one-time; the key is the SOCIALHOLMES_API_TOKEN
# Fly secret. A check is one run: POST
# /scrape/tiktok/video {"parameters": {"video_id": "..."},
# "limit": 1} (views) or POST /scrape/tiktok/profile
# {"parameters": {"username": "..."}, "limit": 1} (followers)
# answers 202 with a run id; poll GET /runs/:id every few
# seconds until the status is terminal (succeeded, empty,
# failed, cancelled); read GET /runs/:id/results. The video
# record carries play_count, the profile record
# follower_count. Only a delivered result is billed (1 per
# check); empty/failed runs cost nothing. The run is capped at
# 60 seconds of polling — a slow run falls through to the next
# provider, it never stalls the hourly check.
SOCIALHOLMES_BASE_URL = "https://api.socialholmes.com/api/public/v1"
SOCIALHOLMES_POLL_INTERVAL_SECONDS = 2.0
SOCIALHOLMES_POLL_MAX_SECONDS = 60.0
SOCIALHOLMES_TOTAL_BUDGET = 1000  # first 1,000 results free, one-time


def count_tokens_from_env():
    """Provider credentials from the environment only. A missing
    var means that provider is skipped, never faked. No token is
    logged anywhere."""
    return {
        "ensembledata": (os.environ.get("ENSEMBLEDATA_API_TOKEN") or "").strip() or None,
        "socialholmes": (os.environ.get("SOCIALHOLMES_API_TOKEN") or "").strip() or None,
        "scrapeeverything": (os.environ.get("SCRAPEEVERYTHING_API_KEY") or "").strip() or None,
        "youtube": (os.environ.get("YOUTUBE_API_KEY") or "").strip() or None,
        "telegram": (os.environ.get("TELEGRAM_BOT_TOKEN") or "").strip() or None,
    }


def count_proxy_from_env():
    """Residential proxy for the own scraper, from COUNT_PROXY_URL
    (full URL with credentials, e.g.
    http://user:pass@gate.decodo.com:7000 — the user's Decodo
    residential proxy). Nothing is hard-coded: no proxy is
    configured when the var is empty, and the scraper then runs
    direct only."""
    return (os.environ.get("COUNT_PROXY_URL") or "").strip() or None


def count_chain_supports(platform, metric):
    """True when at least one provider is wired for this
    platform+metric (disabled providers do not count)."""
    chain = COUNT_CHAIN.get((platform or "", metric or "")) or []
    return any(
        (COUNT_PROVIDERS.get(name) or {}).get("enabled")
        for name in chain
    )


def is_auto_refill_request(text):
    """True when the message sets up keeping a count above a
    target: "keep my followers above 15k", "auto refill my views
    when they drop", "don't let my views fall under 5000". A
    panel refill ("it stopped at 800 out of 1000, send the rest")
    has none of these phrases and stays a plain "refill"."""
    s = " ".join(str(text or "").strip().lower().split())
    if not s:
        return False
    words = set(re.findall(r"[a-z]+", s))
    has_metric = kind_from_text(s) is not None or bool(
        words & {"followers", "views", "likes", "members", "subscribers"}
    )
    if "auto refill" in s or "auto-refill" in s or "autorefill" in s:
        return True
    if "refill automatically" in s or "top up automatically" in s:
        return True
    if "keep" in words and has_metric and any(
        p in s for p in ("above", "at least", "not below", "over")
    ):
        return True
    if "stay above" in s and has_metric:
        return True
    if has_metric and any(
        p in s for p in (
            "when it drops", "when they drop", "whenever it drops",
            "whenever they drop", "if it drops", "if they drop",
            "when it falls", "never drop below", "keep it up",
            "top up when", "fall under", "fall below", "drop below",
            "go below", "goes below", "don't let", "dont let",
        )
    ):
        return True
    if "maintain" in words and has_metric and any(
        p in s for p in ("above", "at least", "not below")
    ):
        return True
    return False


def is_auto_refill_status_request(text):
    """"my auto refills", "auto refill status" — what is being
    kept up. A bare "refill status" is NOT this: it can mean a
    panel refill of a stopped order."""
    s = " ".join(str(text or "").strip().lower().split())
    return any(
        p in s for p in (
            "auto refill status", "auto-refill status",
            "my auto refills", "my auto-refills", "auto refills",
            "what are you keeping", "what are you topping up",
        )
    )


def is_auto_refill_stop_request(text):
    """\"stop auto refill\", \"turn off auto refill\" — before the
    plain "cancel" branch, which would eat it."""
    s = " ".join(str(text or "").strip().lower().split())
    return any(
        p in s for p in (
            "stop auto refill", "stop auto-refill",
            "turn off auto refill", "turn off auto-refill",
            "cancel auto refill", "cancel auto-refill",
            "stop refilling", "stop keeping", "stop topping up",
        )
    )


def parse_auto_refill_target(text):
    """The count to stay above, or None. "keep my followers above
    15k" -> 15000 (the text is already normalised, so "15k"
    reads as 15000). The number must sit right after a trigger
    word ("above", "at least", "target", "keep it at"), so a
    stray number elsewhere ("my balance is 100") never counts."""
    s = " ".join(str(text or "").strip().lower().split())
    if not s:
        return None
    for match in re.finditer(
        r"(above|at least|minimum|not below|stay above|target"
        r"|keep(?: it)? at|keep(?: it)? above|fall below|fall under"
        r"|drop below|below|under|at)\s*:?\s*(\d[\d,]*)\s*([km]?)",
        s,
    ):
        try:
            value = float(match.group(2).replace(",", ""))
        except ValueError:
            continue
        if match.group(3) == "k":
            value *= 1000
        elif match.group(3) == "m":
            value *= 1000000
        value = int(value)
        if 10 <= value <= 1000000:
            return value
    return None


def parse_auto_refill_trigger(text):
    """The user's own trigger, or None to keep the 5% default.
    "when it drops by 200" / "drop 200" / a bare "200" -> a
    quantity trigger; "10%", "10 percent", "drops 10%" -> a
    percent trigger. A percent must be under 100; a quantity
    must be at least 1. Anything else (including "ok") is None —
    the caller keeps the default, never guesses."""
    s = " ".join(str(text or "").strip().lower().split())
    if not s:
        return None
    match = re.search(r"(\d+(?:\.\d+)?)\s*(?:%|percent|pct)", s)
    if match:
        try:
            pct = float(match.group(1)) / 100.0
        except ValueError:
            return None
        if 0 < pct < 1:
            return {"type": "pct", "value": pct}
        return None
    match = re.search(
        r"(?:drop(?:s|ped)?|fall(?:s)?|decrease|down|by)\s*(?:by\s*)?(\d[\d,]*)",
        s,
    )
    if match:
        try:
            qty = int(match.group(1).replace(",", ""))
        except ValueError:
            return None
        if qty >= 1:
            return {"type": "qty", "value": qty}
        return None
    if s.isdigit():
        qty = int(s)
        if qty >= 1:
            return {"type": "qty", "value": qty}
    return None


def parse_auto_refill_daily_cap(text):
    """A daily spending limit in ETB, or None. "limit 1000",
    "max 500 a day", "cap 1000 ETB" -> the number. "no limit",
    "none", "no cap", "unlimited", "ok" -> None (no limit), the
    same as the default. A number with no limit word ("1000")
    is NOT a cap — a bare number while the setup waits is a
    trigger quantity, never a spending limit."""
    s = " ".join(str(text or "").strip().lower().split())
    if not s:
        return None
    if re.search(r"\b(no\s+limit|no\s+cap|unlimited|none)\b", s):
        return None
    match = re.search(
        r"(?:limit|max|cap|daily\s+limit)\s*:?\s*(\d[\d,]*)", s)
    if match:
        try:
            cap = float(match.group(1).replace(",", ""))
        except ValueError:
            return None
        if cap > 0:
            return cap
    return None


def auto_refill_trigger_text(trigger, target, lang):
    """The trigger as a clause in the user's language, for the
    preview and the started message: "when it drops 5% below
    10,000", "when it drops by 200", "when it drops 10% below
    10,000". None means the 5% default."""
    if trigger and str(trigger.get("type") or "").strip().lower() == "qty":
        try:
            qty = int(trigger.get("value"))
        except (TypeError, ValueError):
            qty = None
        if qty and qty > 0:
            if lang == "am":
                return f"በ {qty:,} ሲቀንስ"
            return f"when it drops by {qty:,}"
    if trigger and str(trigger.get("type") or "").strip().lower() == "pct":
        try:
            pct = float(trigger.get("value"))
        except (TypeError, ValueError):
            pct = None
        if pct and 0 < pct < 1:
            shown = int(pct * 100) if float(pct * 100).is_integer() else pct * 100
            if lang == "am":
                return f"ከ {int(target):,} በታች {shown}% ሲወርድ"
            return f"when it drops {shown}% below {int(target):,}"
    shown = int(AUTO_REFILL_DEFAULT_TRIGGER_PCT * 100)
    if lang == "am":
        return f"ከ {int(target):,} በታች {shown}% ሲወርድ"
    return f"when it drops {shown}% below {int(target):,}"


def auto_refill_limit_text(daily_cap, lang):
    """The daily limit as a sentence: none by default (the bot
    may use the whole balance), or the user's own limit."""
    if daily_cap is None:
        if lang == "am":
            return "የቀን ገደብ የለም — balanceዎን ሙሉ መጠቀም እችላለሁ።"
        return "There is no daily limit — I can use your whole balance."
    if lang == "am":
        return f"በቀን እስከ {format_money(daily_cap)} ETB።"
    return f"At most {format_money(daily_cap)} ETB a day."


def auto_refill_min_drop(target, trigger=None):
    """The smallest drop worth ordering for. Default: 5% of the
    target (owner, 20 Nov 2026). A user-set trigger replaces it:
    {"type": "qty", "value": 200} ("when it drops by 200") or
    {"type": "pct", "value": 0.10} ("when it drops 10%"). A bad
    or empty trigger falls back to the 5% default — a refill
    never orders on a drop of nothing."""
    if trigger:
        kind = str(trigger.get("type") or "").strip().lower()
        try:
            value = trigger.get("value")
            if kind == "qty":
                qty = int(value)
                if qty > 0:
                    return qty
            elif kind == "pct":
                pct = float(value)
                if 0 < pct < 1:
                    goal = int(target)
                    if goal > 0:
                        # 1e-9 guards the float: 15000 * 0.10 is a
                        # hair above 1500.0 in binary, and ceil
                        # would wrongly give 1501.
                        return max(1, math.ceil(goal * pct - 1e-9))
        except (TypeError, ValueError):
            pass
    try:
        goal = int(target)
    except (TypeError, ValueError):
        return 1
    if goal <= 0:
        return 1
    # ceil(5% of the target) in whole numbers: (goal + 19) // 20.
    return max(1, (goal + 19) // 20)


def auto_refill_top_up_qty(current, target, service, trigger=None):
    """How many to order to get back to the target, or None when
    no order is needed. Rounded up to a multiple of 10 and at
    least the service minimum (an order below the minimum would
    be refused by the provider)."""
    try:
        now = int(current)
        goal = int(target)
    except (TypeError, ValueError):
        return None
    drop = goal - now
    if drop <= 0 or drop < auto_refill_min_drop(goal, trigger=trigger):
        return None
    qty = _ceil_to_10(drop)
    return max(qty, _ceil_to_10(_service_min_qty(service)))


def auto_refill_decide(current, target, service, spent_today,
                       cap=None, trigger=None):
    """Pure top-up decision, no network. Returns {"action",
    "quantity", "cost", "reason"}: "top_up" (order this many),
    "skip" (at target, or the drop is too small to bother),
    "cap" (the user's own daily spend cap would be passed),
    "unavailable" (no count to judge from). cap=None means NO
    daily cap: the bot may use the user's whole balance (owner,
    20 Nov 2026) — a cap only applies when the user set one.
    trigger is the per-refill trigger (None = the 5% default).
    The caller places nothing — the server worker does that,
    after this decision."""
    if current is None:
        return {"action": "unavailable", "quantity": None,
                "cost": None, "reason": "no_count"}
    try:
        now = int(current)
        goal = int(target)
    except (TypeError, ValueError):
        return {"action": "unavailable", "quantity": None,
                "cost": None, "reason": "no_count"}
    if now >= goal:
        return {"action": "skip", "quantity": None, "cost": None,
                "reason": "at_target"}
    qty = auto_refill_top_up_qty(now, goal, service, trigger=trigger)
    if qty is None:
        return {"action": "skip", "quantity": None, "cost": None,
                "reason": "drop_too_small"}
    rate = float((service or {}).get("rate_etb_per_1000", 0) or 0)
    cost = estimated_total_etb(rate, qty)
    if cap is not None:
        try:
            limit = float(cap)
        except (TypeError, ValueError):
            limit = None
        if limit is not None:
            try:
                spent = float(spent_today or 0)
            except (TypeError, ValueError):
                spent = 0.0
            if spent + cost > limit:
                return {"action": "cap", "quantity": qty, "cost": cost,
                        "reason": "daily_cap"}
    return {"action": "top_up", "quantity": qty, "cost": cost,
            "reason": "below_target"}


# --- count parsing: one deep search, every provider ---------------
def _coerce_count(value):
    """A count in any shape the providers use: an int, a digit
    string ("5178"), a compact string ("12.3K subscribers",
    "5,178 views"), or {"simpleText": "5,178 views"} (YouTube).
    Returns the int, or None."""
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value if value >= 0 else None
    if isinstance(value, float):
        return int(value) if value >= 0 else None
    if isinstance(value, dict):
        for key in ("simpleText", "text", "count"):
            if key in value:
                return _coerce_count(value[key])
        return None
    if isinstance(value, str):
        return parse_compact_count(value)
    return None


def parse_compact_count(text):
    """\"5,178 views\" -> 5178, \"12.3K\" -> 12300, \"1.2M\" ->
    1200000, \"5178\" -> 5178. None when no number is there."""
    if text is None:
        return None
    match = re.search(r"([\d,\.]+)\s*([KMB]?)", str(text).strip(), re.IGNORECASE)
    if not match:
        return None
    try:
        number = float(match.group(1).replace(",", ""))
    except ValueError:
        return None
    suffix = (match.group(2) or "").upper()
    multiplier = {"K": 1000, "M": 1000000, "B": 1000000000}.get(suffix, 1)
    return int(number * multiplier)


def _deep_find_count(data, field_names, _depth=0):
    """First int found under any of the field names, anywhere in
    a JSON payload. Providers nest the same count differently
    (data.play_count, data.stats.playCount, statistics.viewCount),
    so the search walks the whole payload instead of trusting
    one path. Depth-capped so a hostile payload cannot recurse
    forever."""
    if data is None or _depth > 12:
        return None
    if isinstance(data, dict):
        for key in field_names:
            if key in data:
                found = _coerce_count(data[key])
                if found is not None:
                    return found
        for value in data.values():
            found = _deep_find_count(value, field_names, _depth + 1)
            if found is not None:
                return found
        return None
    if isinstance(data, list):
        for item in data:
            found = _deep_find_count(item, field_names, _depth + 1)
            if found is not None:
                return found
    return None


def parse_ensembledata_count(payload, field):
    """The count out of an EnsembleData response, or None. The
    live shape (verified 19 Nov 2026 on video
    7666462351436107015) is {"success": true, "data":
    {"play_count": 5178, "digg_count": 7, ...}}; the search also
    accepts the camelCase variants the raw TikTok payload uses."""
    if not isinstance(payload, dict):
        return None
    if payload.get("success") is False:
        return None
    variants = {field, field.replace("_", ""), field.replace("_count", "Count")}
    if field == "play_count":
        variants |= {"playCount"}
    if field == "follower_count":
        variants |= {"followerCount", "followers"}
    if field == "view_count":
        variants |= {"viewCount"}
    return _deep_find_count(payload, sorted(variants))


# --- own scraper: provider 0 ---------------------------------------
def _extract_json_blob(html, marker, terminator=None):
    """The JSON object that follows `marker` in a page, or None.
    With a terminator (e.g. "</script>") the slice is cut there;
    without one the braces are balanced from the first "{"."""
    if not html or marker not in html:
        return None
    start = html.index(marker) + len(marker)
    if terminator is not None:
        end = html.find(terminator, start)
        if end < 0:
            return None
        snippet = html[start:end].strip().rstrip(";").strip()
    else:
        brace = html.find("{", start)
        if brace < 0:
            return None
        depth = 0
        end = None
        for pos in range(brace, len(html)):
            char = html[pos]
            if char == "{":
                depth += 1
            elif char == "}":
                depth -= 1
                if depth == 0:
                    end = pos + 1
                    break
        if end is None:
            return None
        snippet = html[brace:end]
    try:
        parsed = json.loads(snippet)
    except (ValueError, TypeError):
        return None
    return parsed if isinstance(parsed, (dict, list)) else None


def parse_tiktok_page_count(html, metric):
    """The count out of a TikTok video or profile page, or None.
    play_count lives in the SIGI_STATE JSON (ItemModule.<id>.
    stats.playCount); follower_count in the same blob
    (UserModule...stats.followerCount). The rehydration JSON is
    tried second; a bare "playCount":5178 regex is the last
    resort for pages that serve a cut-down shell."""
    if not html:
        return None
    field = "playCount" if metric == "views" else "followerCount"
    for marker in (
        '<script id="SIGI_STATE" type="application/json">',
        '<script id="__UNIVERSAL_DATA_FOR_REHYDRATION__" type="application/json">',
    ):
        blob = _extract_json_blob(html, marker, "</script>")
        if blob is not None:
            found = _deep_find_count(blob, [field])
            if found is not None:
                return found
    match = re.search(rf'"{field}"\s*:\s*(\d+)', html)
    if match:
        try:
            return int(match.group(1))
        except ValueError:
            return None
    return None


def parse_youtube_page_count(html, metric):
    """The count out of a YouTube video or channel page, or None.
    Views come from ytInitialData's viewCount ("5,178 views"),
    subscribers from subscriberCountText ("12.3K subscribers").
    The JSON is balanced out of the page; a bare regex on the
    subscriber text is the fallback."""
    if not html:
        return None
    field = "viewCount" if metric == "views" else "subscriberCount"
    blob = _extract_json_blob(html, "var ytInitialData = ")
    if blob is not None:
        found = _deep_find_count(blob, [field])
        if found is not None:
            return found
    if metric == "subscribers":
        match = re.search(
            r'"subscriberCountText"\s*:\s*\{\s*"simpleText"\s*:\s*"([^"]+)"',
            html,
        )
        if match:
            return parse_compact_count(match.group(1))
    else:
        match = re.search(
            r'"viewCount"\s*:\s*\{\s*"simpleText"\s*:\s*"([^"]+)"',
            html,
        )
        if match:
            return parse_compact_count(match.group(1))
    return None


def parse_telegram_page_count(html):
    """The subscriber count out of a public channel page
    (t.me/s/<channel>), or None. The page carries it in plain
    text: <div class="tgme_page_extra">1,234 subscribers</div>."""
    if not html:
        return None
    match = re.search(
        r"tgme_page_extra[^>]*>\s*([\d,\.]+[KM]?)\s+subscribers",
        html, re.IGNORECASE,
    )
    if match:
        return parse_compact_count(match.group(1))
    match = re.search(r"([\d,\.]+[KM]?)\s+subscribers", html, re.IGNORECASE)
    if match:
        return parse_compact_count(match.group(1))
    return None


def _own_scraper_url(platform, metric, link):
    """The public page to fetch for this count, or None when the
    link cannot be used. TikTok and YouTube links are fetched
    as-is (short links follow redirects); a Telegram link is
    rewritten to its public preview page t.me/s/<channel>."""
    raw = (link or "").strip()
    if not raw:
        return None
    if platform == "telegram":
        match = re.search(r"t\.me/(?:s/)?([A-Za-z0-9_]+)", raw)
        if not match or match.group(1) in ("c", "s"):
            return None
        return f"https://t.me/s/{match.group(1)}"
    if platform in ("tiktok", "youtube"):
        if not raw.startswith("http"):
            return None
        return raw
    return None


def _parse_own_scraper_page(platform, metric, html):
    if platform == "tiktok":
        return parse_tiktok_page_count(html, metric)
    if platform == "youtube":
        return parse_youtube_page_count(html, metric)
    if platform == "telegram":
        return parse_telegram_page_count(html)
    return None


async def _count_http_get(http_get, method, url, params=None,
                         json_body=None, headers=None, proxy=None,
                         timeout=10.0):
    """One HTTP call. Tests inject `http_get` (an async callable
    returning (status, body_text)); live code uses httpx with
    redirects followed and an optional proxy. Returns
    (status, body_text)."""
    if http_get is not None:
        return await http_get(
            method, url, params=params, json_body=json_body,
            headers=headers, proxy=proxy, timeout=timeout,
        )
    async with httpx.AsyncClient(
        timeout=timeout, follow_redirects=True, proxy=proxy,
    ) as client:
        response = await client.request(
            method, url, params=params, json=json_body, headers=headers,
        )
        return response.status_code, response.text


async def fetch_own_scraper(platform, metric, link, http_get=None,
                            proxy=None, timeout=COUNT_SCRAPER_TIMEOUT_SECONDS):
    """Provider 0: fetch the public page and read the count out
    of it. Returns (count, error_key): error_key is None on
    success, else "unsupported" (no page for this platform or
    metric), "blocked" (403/429/5xx — the page refused us),
    "unavailable" (network error, non-200, empty page) or
    "parse_failed" (the page loaded but the count is not in it).
    Defensive by design: short timeout, one retry, and the retry
    goes through the residential proxy when one is configured —
    a direct fetch that gets blocked is retried via the proxy,
    and any failure here only means "try the next provider"."""
    if (platform, metric) not in (
        ("tiktok", "views"), ("tiktok", "followers"),
        ("youtube", "views"), ("youtube", "subscribers"),
        ("telegram", "members"),
    ):
        return None, "unsupported"
    url = _own_scraper_url(platform, metric, link)
    if url is None:
        return None, "unsupported"
    attempts = [(url, None)]
    if proxy:
        attempts.append((url, proxy))
    last_error = "unavailable"
    for attempt_url, attempt_proxy in attempts:
        try:
            status, body = await _count_http_get(
                http_get, "GET", attempt_url,
                headers={"User-Agent": COUNT_SCRAPER_USER_AGENT},
                proxy=attempt_proxy, timeout=timeout,
            )
        except Exception:
            last_error = "unavailable"
            continue
        if status in (403, 429, 451) or status >= 500:
            last_error = "blocked"
            continue
        if status != 200 or not body:
            last_error = "unavailable"
            continue
        count = _parse_own_scraper_page(platform, metric, body)
        if count is None:
            last_error = "parse_failed"
            continue
        return count, None
    return None, last_error


# --- provider fetchers: one per API in the chain -------------------
def _tiktok_username_from_link(link):
    match = re.search(r"tiktok\.com/@([A-Za-z0-9_.]+)", link or "")
    return match.group(1) if match else None


def _youtube_id_from_link(link):
    """("video", id) / ("channel", id) / ("handle", name) / None.
    A @handle cannot be resolved without a search call (100
    quota units), so subscribers for a @handle link is
    unsupported — the setup asks for the channel link instead."""
    raw = (link or "").strip()
    match = re.search(r"[?&]v=([A-Za-z0-9_-]{6,})", raw)
    if match:
        return ("video", match.group(1))
    match = re.search(r"youtu\.be/([A-Za-z0-9_-]{6,})", raw)
    if match:
        return ("video", match.group(1))
    match = re.search(r"youtube\.com/(?:shorts|embed)/([A-Za-z0-9_-]{6,})", raw)
    if match:
        return ("video", match.group(1))
    match = re.search(r"youtube\.com/channel/(UC[A-Za-z0-9_-]{6,})", raw)
    if match:
        return ("channel", match.group(1))
    match = re.search(r"youtube\.com/@([A-Za-z0-9_.-]+)", raw)
    if match:
        return ("handle", match.group(1))
    return None


def _telegram_chat_from_link(link):
    """The chat id for getChatMemberCount: "@name" for a public
    channel, "-100<digits>" for a t.me/c/<digits> link. An invite
    link (t.me/+...) names no public chat and is unsupported."""
    raw = (link or "").strip()
    match = re.search(r"t\.me/c/(\d+)", raw)
    if match:
        return f"-100{match.group(1)}"
    match = re.search(r"t\.me/([A-Za-z0-9_]+)", raw)
    if match and match.group(1) not in ("s", "c"):
        return f"@{match.group(1)}"
    return None


async def _fetch_ensembledata(platform, metric, link, token, http_get):
    """EnsembleData: GET /apis/tt/post/info?url&token (2 units)
    for views, /apis/tt/user/info?username&token (1 unit) for
    followers. Returns (count, error_key, cost)."""
    if not token:
        return None, "not_configured", 0
    if platform != "tiktok":
        return None, "unsupported", 0
    if metric == "views":
        url = "https://ensembledata.com/apis/tt/post/info"
        params = {"url": link, "token": token}
        cost, field = 2, "play_count"
    elif metric == "followers":
        username = _tiktok_username_from_link(link)
        if not username:
            return None, "unsupported", 0
        url = "https://ensembledata.com/apis/tt/user/info"
        params = {"username": username, "token": token}
        cost, field = 1, "follower_count"
    else:
        return None, "unsupported", 0
    try:
        status, body = await _count_http_get(http_get, "GET", url, params=params)
    except Exception:
        return None, "unavailable", 0
    if status == 429:
        return None, "rate_limited", 0
    if status != 200 or not body:
        return None, "unavailable", 0
    try:
        payload = json.loads(body)
    except (ValueError, TypeError):
        return None, "unavailable", 0
    count = parse_ensembledata_count(payload, field)
    if count is None:
        return None, "unavailable", 0
    return count, None, cost


def _tiktok_video_id_from_link(link):
    """The numeric video id out of a TikTok video link
    (.../video/7666462351436107015), or None. A short link
    (vt.tiktok.com/...) carries no id, so this provider cannot
    use it — the chain falls through to the next provider."""
    match = re.search(r"/video/(\d+)", link or "")
    return match.group(1) if match else None


async def _fetch_socialholmes(platform, metric, link, token, http_get):
    """SocialHolmes (new unified API): POST /scrape/tiktok/video
    {"parameters": {"video_id": ...}, "limit": 1} for views,
    POST /scrape/tiktok/profile {"parameters": {"username": ...},
    "limit": 1} for followers. Async: 202 + run id, then poll
    GET /runs/:id until a terminal status and read
    GET /runs/:id/results. The video record carries play_count,
    the profile record follower_count. Returns
    (count, error_key, cost): cost is 1 only on a delivered
    result — an empty/failed run, a timeout or a 401 costs
    nothing, so the 1,000-result free allowance is spent only
    on answers. Any failure here only means "try the next
    provider": it never raises, and polling is capped at
    SOCIALHOLMES_POLL_MAX_SECONDS."""
    if not token:
        return None, "not_configured", 0
    if platform != "tiktok":
        return None, "unsupported", 0
    if metric == "views":
        video_id = _tiktok_video_id_from_link(link)
        if not video_id:
            return None, "unsupported", 0
        endpoint, params = "video", {"video_id": video_id}
        field = "play_count"
    elif metric == "followers":
        username = _tiktok_username_from_link(link)
        if not username:
            return None, "unsupported", 0
        endpoint, params = "profile", {"username": username}
        field = "follower_count"
    else:
        return None, "unsupported", 0
    headers = {"Authorization": f"Bearer {token}"}
    try:
        status, body = await _count_http_get(
            http_get, "POST",
            f"{SOCIALHOLMES_BASE_URL}/scrape/tiktok/{endpoint}",
            json_body={"parameters": params, "limit": 1},
            headers=headers,
        )
    except Exception:
        return None, "unavailable", 0
    if status == 429:
        return None, "rate_limited", 0
    if status != 202 or not body:
        return None, "unavailable", 0
    try:
        run = json.loads(body)
    except (ValueError, TypeError):
        return None, "unavailable", 0
    run_id = run.get("id") if isinstance(run, dict) else None
    if not run_id:
        return None, "unavailable", 0
    deadline = time.monotonic() + SOCIALHOLMES_POLL_MAX_SECONDS
    terminal = None
    while True:
        try:
            status, body = await _count_http_get(
                http_get, "GET",
                f"{SOCIALHOLMES_BASE_URL}/runs/{run_id}",
                headers=headers,
            )
        except Exception:
            return None, "unavailable", 0
        if status == 429:
            return None, "rate_limited", 0
        if status == 404:
            return None, "unavailable", 0
        if status == 200 and body:
            try:
                polled = json.loads(body)
            except (ValueError, TypeError):
                polled = None
            if isinstance(polled, dict):
                state = polled.get("status")
                if state in ("succeeded", "empty", "failed", "cancelled"):
                    terminal = state
                    break
        if time.monotonic() >= deadline:
            return None, "unavailable", 0
        await asyncio.sleep(SOCIALHOLMES_POLL_INTERVAL_SECONDS)
    if terminal != "succeeded":
        return None, "unavailable", 0
    try:
        status, body = await _count_http_get(
            http_get, "GET",
            f"{SOCIALHOLMES_BASE_URL}/runs/{run_id}/results",
            headers=headers,
        )
    except Exception:
        return None, "unavailable", 0
    if status != 200 or not body:
        return None, "unavailable", 0
    try:
        payload = json.loads(body)
    except (ValueError, TypeError):
        return None, "unavailable", 0
    count = _deep_find_count(
        payload, [field, field.replace("_count", "Count")])
    if count is None:
        return None, "unavailable", 0
    return count, None, 1


async def _fetch_scrapeeverything(platform, metric, link, key, http_get):
    """Scrape Everything: POST /v1/tiktok/video {"url": ...} (1
    credit) for views, POST /v1/tiktok/profile {"username": ...}
    for followers. Bearer key. Known to fail on TikTok (8
    failures on 19 Nov: PROXY_CONNECT_FAILED / PARSE_ERROR), so
    a failure here is routine — the chain just moves on. Failed
    calls are refunded by the provider, so they cost 0."""
    if not key:
        return None, "not_configured", 0
    if platform != "tiktok":
        return None, "unsupported", 0
    if metric == "views":
        url = "https://api.scrapeeverything.com/v1/tiktok/video"
        body = {"url": link}
        field = "play_count"
    elif metric == "followers":
        username = _tiktok_username_from_link(link)
        if not username:
            return None, "unsupported", 0
        url = "https://api.scrapeeverything.com/v1/tiktok/profile"
        body = {"username": username}
        field = "follower_count"
    else:
        return None, "unsupported", 0
    try:
        status, text = await _count_http_get(
            http_get, "POST", url, json_body=body,
            headers={"Authorization": f"Bearer {key}"},
        )
    except Exception:
        return None, "unavailable", 0
    if status == 429:
        return None, "rate_limited", 0
    if status != 200 or not text:
        return None, "unavailable", 0
    try:
        payload = json.loads(text)
    except (ValueError, TypeError):
        return None, "unavailable", 0
    if isinstance(payload, dict) and payload.get("success") is False:
        return None, "unavailable", 0
    count = _deep_find_count(payload, [field, field.replace("_count", "Count")])
    if count is None:
        return None, "unavailable", 0
    return count, None, 1


async def _fetch_youtube(platform, metric, link, key, http_get):
    """YouTube Data API v3 (official): videos.list
    ?part=statistics&id=... for views, channels.list
    ?part=statistics&id=... for subscribers. 1 quota unit each
    out of the free 10,000/day. A @handle link cannot be
    resolved without a search call (100 units), so it is
    unsupported — the channel link is needed instead."""
    if not key:
        return None, "not_configured", 0
    if platform != "youtube":
        return None, "unsupported", 0
    kind = _youtube_id_from_link(link)
    if metric == "views":
        if kind is None or kind[0] != "video":
            return None, "unsupported", 0
        url = "https://www.googleapis.com/youtube/v3/videos"
        params = {"part": "statistics", "id": kind[1], "key": key}
        field = "viewCount"
    elif metric == "subscribers":
        if kind is None or kind[0] != "channel":
            return None, "unsupported", 0
        url = "https://www.googleapis.com/youtube/v3/channels"
        params = {"part": "statistics", "id": kind[1], "key": key}
        field = "subscriberCount"
    else:
        return None, "unsupported", 0
    try:
        status, text = await _count_http_get(http_get, "GET", url, params=params)
    except Exception:
        return None, "unavailable", 0
    if status == 429:
        return None, "rate_limited", 0
    if status == 403:
        # Quota exceeded (or the key is bad): treat as a limit,
        # not a crash — the chain parks this provider for an hour.
        return None, "rate_limited", 0
    if status != 200 or not text:
        return None, "unavailable", 0
    try:
        payload = json.loads(text)
    except (ValueError, TypeError):
        return None, "unavailable", 0
    count = _deep_find_count(payload, [field])
    if count is None:
        return None, "unavailable", 0
    return count, None, 1


async def _fetch_telegram(platform, metric, link, token, http_get):
    """Telegram Bot API getChatMemberCount: free, no quota. The
    bot's own token (TELEGRAM_BOT_TOKEN) is used. A channel the
    bot cannot see answers ok:false, which is "unavailable" —
    the chain moves on, nothing crashes."""
    if not token:
        return None, "not_configured", 0
    if platform != "telegram" or metric != "members":
        return None, "unsupported", 0
    chat = _telegram_chat_from_link(link)
    if chat is None:
        return None, "unsupported", 0
    url = f"https://api.telegram.org/bot{token}/getChatMemberCount"
    try:
        status, text = await _count_http_get(
            http_get, "GET", url, params={"chat_id": chat},
        )
    except Exception:
        return None, "unavailable", 0
    if status == 429:
        return None, "rate_limited", 0
    if status != 200 or not text:
        return None, "unavailable", 0
    try:
        payload = json.loads(text)
    except (ValueError, TypeError):
        return None, "unavailable", 0
    if not isinstance(payload, dict) or payload.get("ok") is not True:
        return None, "unavailable", 0
    count = _coerce_count(payload.get("result"))
    if count is None:
        return None, "unavailable", 0
    return count, None, 0


# --- the chain -------------------------------------------------------
class CountUsage:
    """Per-provider daily usage, kept in the refill record itself
    (refill["count_usage"]) so it survives restarts: the server
    persists the record in bot_refills, and the worker passes it
    back on every check. Shape: {provider: {"date":
    "2026-11-19", "used": 4, "backoff_until": 0}}. A new day
    resets the count; a 429 parks the provider for an hour.
    Providers with no daily budget (own scraper, Telegram, Scrape
    Everything's one-time credits) are never blocked by budget —
    their own balance or quota is the limit. SocialHolmes instead
    carries a total_budget (its 1,000 free results, one-time):
    its "total_used" never resets with the date, so once 1,000
    results are spent the chain skips it until the operator tops
    the account up and resets the counter."""

    def __init__(self, raw=None):
        self.data = {}
        for name, entry in (raw or {}).items():
            if isinstance(entry, dict):
                kept = {
                    "date": entry.get("date"),
                    "used": int(entry.get("used") or 0),
                    "backoff_until": float(entry.get("backoff_until") or 0),
                }
                if (COUNT_PROVIDERS.get(str(name)) or {}).get(
                        "total_budget") is not None:
                    kept["total_used"] = int(entry.get("total_used") or 0)
                self.data[str(name)] = kept

    def _today(self, now=None):
        stamp = now if now is not None else time.time()
        return datetime.fromtimestamp(stamp, tz=timezone.utc).strftime("%Y-%m-%d")

    def used_today(self, provider, now=None):
        entry = self.data.get(provider) or {}
        if entry.get("date") != self._today(now):
            return 0
        return int(entry.get("used") or 0)

    def total_used(self, provider):
        """Cumulative results spent on a provider with a
        total_budget (SocialHolmes' 1,000 free results, one-time).
        Unlike used_today it never resets with the date."""
        return int((self.data.get(provider) or {}).get("total_used") or 0)

    def is_parked(self, provider, now=None):
        stamp = now if now is not None else time.time()
        entry = self.data.get(provider) or {}
        return float(entry.get("backoff_until") or 0) > stamp

    def can_use(self, provider, cost, now=None):
        if self.is_parked(provider, now):
            return False
        budget = (COUNT_PROVIDERS.get(provider) or {}).get("daily_budget")
        if budget is not None:
            if self.used_today(provider, now) + int(cost) > int(budget):
                return False
        total = (COUNT_PROVIDERS.get(provider) or {}).get("total_budget")
        if total is not None:
            return self.total_used(provider) + int(cost) <= int(total)
        return True

    def record(self, provider, cost, now=None):
        today = self._today(now)
        entry = self.data.get(provider) or {}
        if entry.get("date") != today:
            fresh = {"date": today, "used": 0, "backoff_until": 0}
            if (COUNT_PROVIDERS.get(provider) or {}).get(
                    "total_budget") is not None:
                fresh["total_used"] = int(entry.get("total_used") or 0)
            entry = fresh
        entry["used"] = int(entry.get("used") or 0) + int(cost)
        if (COUNT_PROVIDERS.get(provider) or {}).get(
                "total_budget") is not None:
            entry["total_used"] = (
                int(entry.get("total_used") or 0) + int(cost))
        self.data[provider] = entry

    def park(self, provider, seconds=3600, now=None):
        stamp = now if now is not None else time.time()
        today = self._today(now)
        entry = self.data.get(provider) or {}
        if entry.get("date") != today:
            fresh = {"date": today, "used": 0, "backoff_until": 0}
            if (COUNT_PROVIDERS.get(provider) or {}).get(
                    "total_budget") is not None:
                fresh["total_used"] = int(entry.get("total_used") or 0)
            entry = fresh
        entry["backoff_until"] = stamp + seconds
        self.data[provider] = entry

    def to_dict(self):
        return {name: dict(entry) for name, entry in self.data.items()}


def count_cache_get(platform, metric, link, now=None):
    """A count fetched in the last COUNT_CACHE_TTL_SECONDS, or
    None. Reusing it spends no units at all."""
    stamp = now if now is not None else time.time()
    entry = _COUNT_CACHE.get((platform, metric, link))
    if entry is None:
        return None
    count, _provider, at = entry
    if stamp - at > COUNT_CACHE_TTL_SECONDS:
        _COUNT_CACHE.pop((platform, metric, link), None)
        return None
    return count


def count_cache_put(platform, metric, link, count, provider, now=None):
    stamp = now if now is not None else time.time()
    _COUNT_CACHE[(platform, metric, link)] = (count, provider, stamp)


async def fetch_live_count(platform, metric, link, usage=None,
                          tokens=None, http_get=None, proxy=None,
                          now=None):
    """The fallback chain: try each provider for this
    platform+metric in COUNT_CHAIN order until one returns a
    count. Returns (count, provider, cost, usage_dict) on
    success, or (None, error_key, 0, usage_dict) when none did.
    error_key: "unsupported" (nothing is wired for this
    platform+metric), "no_provider" (wired but nothing is
    configured, budgeted or unparked), "rate_limited" (every
    tried provider answered 429), "all_failed" (the rest).
    `usage` is the refill record's CountUsage dict (plain dict);
    it is updated in place and returned, so the caller can
    persist it. Failed calls never consume budget; a 429 parks
    that provider for an hour."""
    stamp = now if now is not None else time.time()
    tracker = CountUsage(usage)
    tokens = tokens if tokens is not None else count_tokens_from_env()
    chain = COUNT_CHAIN.get((platform or "", metric or "")) or []
    if not chain:
        return None, "unsupported", 0, tracker.to_dict()
    cached = count_cache_get(platform, metric, link, now=stamp)
    if cached is not None:
        return cached, "cache", 0, tracker.to_dict()
    saw_rate_limit = False
    tried_any = False
    for name in chain:
        info = COUNT_PROVIDERS.get(name) or {}
        if not info.get("enabled"):
            continue
        # Budget first: a provider over its daily allowance is
        # never called — calling it would spend units on the
        # provider's side even though the answer is thrown away.
        if name == "ensembledata":
            _cost = 2 if metric == "views" else 1
        elif name in ("scrapeeverything", "youtube", "socialholmes"):
            _cost = 1
        else:
            _cost = 0
        if not tracker.can_use(name, _cost, now=stamp):
            continue
        if name == "own_scraper":
            count, error = await fetch_own_scraper(
                platform, metric, link, http_get=http_get, proxy=proxy,
            )
            cost = 0
        elif name == "ensembledata":
            count, error, cost = await _fetch_ensembledata(
                platform, metric, link, tokens.get("ensembledata"), http_get,
            )
        elif name == "socialholmes":
            count, error, cost = await _fetch_socialholmes(
                platform, metric, link, tokens.get("socialholmes"), http_get,
            )
        elif name == "scrapeeverything":
            count, error, cost = await _fetch_scrapeeverything(
                platform, metric, link, tokens.get("scrapeeverything"), http_get,
            )
        elif name == "youtube":
            count, error, cost = await _fetch_youtube(
                platform, metric, link, tokens.get("youtube"), http_get,
            )
        elif name == "telegram":
            count, error, cost = await _fetch_telegram(
                platform, metric, link, tokens.get("telegram"), http_get,
            )
        else:
            continue
        if error == "not_configured" or error == "unsupported":
            continue
        if error == "rate_limited":
            saw_rate_limit = True
            tracker.park(name, now=stamp)
            continue
        tried_any = True
        if error is not None:
            log.info("count check: %s failed for %s %s (%s)", name, platform, metric, error)
            continue
        if count is None:
            continue
        if cost:
            # A zero-cost hit (own scraper, Telegram) records
            # nothing: the usage record only tracks providers with
            # a daily allowance to protect.
            tracker.record(name, cost, now=stamp)
        count_cache_put(platform, metric, link, count, name, now=stamp)
        return count, name, cost, tracker.to_dict()
    if saw_rate_limit and not tried_any:
        return None, "rate_limited", 0, tracker.to_dict()
    if not tried_any:
        return None, "no_provider", 0, tracker.to_dict()
    return None, "all_failed", 0, tracker.to_dict()


async def auto_refill_check(refill, tokens=None, http_get=None,
                            proxy=None, now=None):
    """One hourly check for one refill record. The record carries
    everything the check needs and everything it updates, so the
    server worker can persist it in bot_refills and the check
    survives restarts:
      in:  {"telegram_id", "service", "link", "target",
            "spent_today", "last_count", "last_check",
            "count_usage"}
      out: {"action", "current", "quantity", "cost", "provider",
            "reason", "count_usage", "last_count", "last_check"}
    The record's own last_count is the durable cache: when it is
    fresher than COUNT_CACHE_TTL_SECONDS the chain is not called
    at all. The caller places the top-up order for a "top_up"
    decision — this function never orders and never moves money."""
    stamp = now if now is not None else time.time()
    service = refill.get("service") or {}
    platform = (refill.get("platform") or "").strip().lower()
    metric = (refill.get("metric") or "").strip().lower()
    link = refill.get("link") or ""
    target = refill.get("target")
    spent_today = refill.get("spent_today") or 0
    usage = dict(refill.get("count_usage") or {})
    last_count = refill.get("last_count")
    last_check = refill.get("last_check")
    current = None
    provider = None
    if last_count is not None and last_check is not None:
        try:
            if stamp - float(last_check) <= COUNT_CACHE_TTL_SECONDS:
                current = int(last_count)
                provider = "cache"
        except (TypeError, ValueError):
            current = None
    error_key = None
    if current is None:
        current, provider, _cost, usage = await fetch_live_count(
            platform, metric, link, usage=usage, tokens=tokens,
            http_get=http_get, proxy=proxy, now=stamp,
        )
        if current is None:
            # fetch_live_count returns its error key in the
            # provider slot when it finds no count.
            error_key = provider
            provider = None
        else:
            last_count = current
            last_check = stamp
    if current is None:
        return {
            "action": "unavailable", "current": None, "quantity": None,
            "cost": None, "provider": None, "reason": error_key,
            "count_usage": usage, "last_count": last_count,
            "last_check": last_check,
        }
    decision = auto_refill_decide(
        current, target, service, spent_today,
        cap=refill.get("daily_cap"),
        trigger=refill.get("trigger"),
    )
    decision["current"] = current
    decision["provider"] = provider
    decision["count_usage"] = usage
    decision["last_count"] = last_count
    decision["last_check"] = last_check
    return decision


# --- settings in plain words (the "what are my settings" chat) -----
_DURATION_WORDS = {
    "minute": 1, "minutes": 1, "min": 1, "mins": 1,
    "hour": 60, "hours": 60, "hr": 60, "hrs": 60,
    "day": 1440, "days": 1440,
    "week": 10080, "weeks": 10080,
}


def _parse_duration_minutes(text):
    """'3 hours' / '1 hour 30 minutes' / '2 days' -> minutes, or
    None. 'an hour' / 'a day' count as 1."""
    if not text:
        return None
    s = str(text).strip().lower()
    total = 0
    found = False
    for number, unit in re.findall(
        r"(\d+)\s*(days?|weeks?|hours?|hrs?|minutes?|mins?)", s
    ):
        total += int(number) * _DURATION_WORDS[unit]
        found = True
    if not found:
        word = re.search(r"\b(?:a|an|one)\s+(hour|day|minute|week)\b", s)
        if word:
            total = _DURATION_WORDS[word.group(1)]
            found = True
    return total if found and total > 0 else None


def _parse_interval_words(tail):
    """A repeat interval in plain words -> minutes, or None.
    'monday' -> a week (10080), 'day'/'daily' -> 1440, 'week' ->
    10080, 'hour'/'hourly' -> 60, 'month' -> 43200, '3 days' ->
    4320. A number wins over the bare words ("3 days" is 4320,
    not 1440)."""
    if not tail:
        return None
    s = str(tail).strip().lower()
    if re.search(r"\d", s):
        return _parse_duration_minutes(s)
    for name in _WEEKDAY_NUMBERS:
        if re.search(rf"\b{name}\b", s):
            return 10080
    if re.search(r"\b(daily|day)\b", s):
        return 1440
    if re.search(r"\b(weekly|week)\b", s):
        return 10080
    if re.search(r"\b(hourly|hour)\b", s):
        return 60
    if re.search(r"\b(monthly|month)\b", s):
        return 43200
    return None


def _platform_metric_from_text(text):
    """(platform, metric_slug) named in a settings message, or
    (None, None) when the message names none. The platform comes
    from the explicit platform words; the metric from
    kind_from_text, slugged the same way the usual metric is
    stored."""
    s = (text or "").lower()
    platform = None
    for name in (
        "tiktok", "instagram", "facebook", "youtube", "telegram",
        "twitter",
    ):
        if re.search(rf"\b{name}\b", s):
            platform = name
            break
    metric = kind_from_text(text)
    return (platform, _trait_slug(metric) if metric else None)


def parse_pref_command(text, user_id=None):
    """A per-customer settings command in plain words, or None.
    Returns one of:
      {"action": "show"}
      {"action": "set", "key": ..., "value": ...}
      {"action": "set_quantity", "key": "platform:metric"|"*",
       "value": int}
      {"action": "set_repeat", "interval_minutes": int,
       "platform": str|None, "metric": str|None}
      {"action": "clear", "key": ...}
      {"action": "clear_all"}
      {"action": "set_favourites", "ids": [...]} (replace) /
      {"action": "add_favourite", "id": ...} /
      {"action": "remove_favourite", "id": ...}
      {"action": "add_banned", "ids": [...]} /
      {"action": "remove_banned", "id": ...}
      {"action": "set_saved_link", "name": ..., "link": ...} /
      {"action": "use_saved_link", "name": ..., "link": ...} /
      {"action": "clear_saved_link", "name": ...}
      {"action": "pause_repeats"} / {"action": "resume_repeats"}
      {"action": "best_time", "platform": ..., "metric": ...}
      {"action": "set_watch_post", "link": ..., "below": ...}
      {"action": "set_wait_price", "platform": ..., "metric": ...,
       "target": ...}
      {"action": "not_available", "option": 1|2|3|5|7|9|10|22|23|28|29}
    New-option sections run after the original ones; the
    not-available sections run LAST, so a real setting always
    wins over a lookalike phrase.
    Only explicit settings phrasing matches — an order message
    ("cheapest tiktok followers", "order 1000 views") never does:
    every set pattern needs a settings word ("always", "never",
    "my usual", "remember", "turn off", "only", "don't message
    me") that an order never carries. Actions from an ambiguous
    phrase ("just do it", "just refund", "any price is fine")
    carry "ambiguous": True — the handler only treats them as a
    setting when the pref is actually on (and no Confirm card is
    waiting), so a bare acceptance is never swallowed. `user_id`
    is only used for that check in the handler; the parse itself
    is pure text."""
    if not text:
        return None
    s = " ".join(str(text).strip().lower().split())
    if not s:
        return None

    # --- clear all ---------------------------------------------------
    # Checked BEFORE show: "reset my settings" contains "my
    # settings", and must clear, not show.
    if re.search(
        r"\b(clear|reset|delete|remove) (all )?(my )?"
        r"(settings|preferences)\b",
        s,
    ):
        return {"action": "clear_all"}

    # --- show ------------------------------------------------------
    if (
        "my settings" in s or "my preferences" in s
        or "what did i set" in s or "what have i set" in s
        or "what are my quiet hours" in s
        or "when are my quiet hours" in s
        or "show my saved links" in s
        or "what are my saved links" in s
        or re.search(r"\bam i on (the )?(cheapest|fastest)\b", s)
        or re.search(
            r"\bwhat is my (usual quantity|price limit|spending "
            r"limit|balance alert|default link)\b",
            s,
        )
        or "what link do you use for me" in s
        or "did i set a default link" in s
        or "which services do you never use for me" in s
        or "what language am i locked to" in s
        or "do i have a weekly limit" in s
    ):
        return {"action": "show"}

    # --- pick order (#4) ---------------------------------------------
    # The OFF phrasing is checked FIRST: "turn off cheapest first"
    # contains "cheapest first", so the set branch below would
    # swallow it and set cheapest instead of turning it off (bug
    # found by the slice-9 tests, 15 Nov 2026). Turning it off
    # means back to the default, fastest-first.
    if (
        "turn off cheapest first" in s
        or "stop cheapest first" in s
        or "stop using the cheapest" in s
    ):
        return {
            "action": "set", "key": "pref_pick_order",
            "value": "fastest",
        }
    if re.search(r"\bcheapest first\b", s) or re.search(
        r"\b(always|prefer)\b.*\bcheapest\b", s
    ):
        return {
            "action": "set", "key": "pref_pick_order",
            "value": "cheapest",
        }
    if re.search(r"\bfastest first\b", s) or re.search(
        r"\b(always|prefer)\b.*\bfastest\b", s
    ):
        return {
            "action": "set", "key": "pref_pick_order",
            "value": "fastest",
        }

    # --- ask-first (#6) ----------------------------------------------
    if re.search(r"\bask (me )?first\b", s) or re.search(
        r"\bask (me )?before you (change|move|switch|try)\b", s
    ) or re.search(r"\balways ask( me)? before\b", s) or re.search(
        r"\bdon't (?:change|move|switch)\b.*\bwithout asking\b", s
    ):
        return {
            "action": "set", "key": "pref_ask_first", "value": True,
        }
    if re.search(
        r"\b(move it yourself|just (do it|move it|change it))\b", s
    ):
        return {
            "action": "set", "key": "pref_ask_first", "value": False,
            "ambiguous": True,
        }
    if re.search(
        r"\b(don't|do not|dont) ask( me)? (first|before|to change|"
        r"to move)\b", s
    ) or "no need to ask" in s or "turn off ask first" in s or (
        "stop asking me first" in s
    ):
        return {
            "action": "set", "key": "pref_ask_first", "value": False,
        }

    # --- max slowness (#8) -------------------------------------------
    match = re.search(r"\bnever slower than\b\s*(.+?)$", s)
    if match:
        minutes = _parse_duration_minutes(match.group(1))
        if minutes:
            return {
                "action": "set", "key": "pref_max_slowness_min",
                "value": minutes,
            }
    match = re.search(
        r"\bnever use a service slower than\b\s*(.+?)$", s
    )
    if match:
        minutes = _parse_duration_minutes(match.group(1))
        if minutes:
            return {
                "action": "set", "key": "pref_max_slowness_min",
                "value": minutes,
            }
    match = re.search(r"\bonly\b.*\bfaster than\b\s*(.+?)$", s)
    if match:
        minutes = _parse_duration_minutes(match.group(1))
        if minutes:
            return {
                "action": "set", "key": "pref_max_slowness_min",
                "value": minutes,
            }
    if re.search(
        r"\b(only (use )?(fast|quick) services|no slow services)\b",
        s,
    ):
        return {
            "action": "set", "key": "pref_max_slowness_min",
            "value": 60,
        }
    if (
        "any speed is fine" in s or "no speed limit" in s
        or "turn off the speed limit" in s
        or "remove the speed limit" in s
        or "don't care about speed" in s
    ):
        return {
            "action": "clear", "key": "pref_max_slowness_min",
            "ambiguous": "any speed is fine" in s,
        }

    # --- default link (#11) ------------------------------------------
    if (
        any(
            phrase in s
            for phrase in (
                "my link is", "remember my link",
                "my usual link is",
            )
        )
        and "order" not in s
    ):
        links = extract_links(text)
        if links:
            return {
                "action": "set", "key": "pref_default_link",
                "value": links[0],
            }
    match = re.search(
        r"\bremember (?:this )?link\b", s
    )
    if match and "order" not in s:
        links = extract_links(text)
        if links:
            return {
                "action": "set", "key": "pref_default_link",
                "value": links[0],
            }
    match = re.search(
        r"\buse\s+(https?://\S+|t\.me/\S+)\b.*"
        r"\b(?:as my link|for all my orders)\b",
        s,
    )
    if match:
        return {
            "action": "set", "key": "pref_default_link",
            "value": match.group(1),
        }
    if re.search(r"\bforget my (default )?link\b", s) or (
        "turn off my link" in s or "don't use my link" in s
        or "stop using my saved link" in s
    ):
        return {"action": "clear", "key": "pref_default_link"}

    # --- default quantity (#12) --------------------------------------
    match = re.search(
        r"\b(?:i usually order|my usual quantity is|usually order|"
        r"my usual order is|remember my usual quantity)\b\s*(.+?)$",
        s,
    )
    if match:
        number = re.search(r"(\d[\d,]*)", match.group(1))
        if number:
            qty = int(number.group(1).replace(",", ""))
            platform, metric = _platform_metric_from_text(text)
            if metric:
                key = (
                    f"{platform}:{metric}" if platform
                    else f"*:{metric}"
                )
            else:
                key = "*"
            return {
                "action": "set_quantity", "key": key, "value": qty,
            }
    if re.search(r"\bforget my (usual )?quantity\b", s) or (
        "turn off my quantity" in s
    ):
        return {"action": "clear", "key": "pref_default_quantity"}

    # --- price ceiling (#13) -----------------------------------------
    match = re.search(
        r"\b(?:never pay more than|not more than|no more than|"
        r"don't pay over|do not pay over|"
        r"max(?:imum)?)\s+(\d+(?:\.\d+)?)\s*(?:birr|etb)?\s*"
        r"per 1000\b",
        s,
    )
    if match:
        return {
            "action": "set", "key": "pref_price_ceiling",
            "value": float(match.group(1)),
        }
    if (
        "no price limit" in s or "turn off the price limit" in s
        or "remove the price limit" in s
    ):
        return {"action": "clear", "key": "pref_price_ceiling"}
    if "any price is fine" in s:
        return {
            "action": "clear", "key": "pref_price_ceiling",
            "ambiguous": True,
        }

    # --- refill-only (#14) -------------------------------------------
    if re.search(r"\brefill only\b", s) or re.search(
        r"\bonly\b.*\brefill\b", s
    ):
        return {
            "action": "set", "key": "pref_refill_only", "value": True,
        }
    if (
        "don't care about refill" in s
        or "turn off refill only" in s or "refill doesn't matter" in s
        or "stop the refill-only rule" in s
    ):
        return {
            "action": "set", "key": "pref_refill_only",
            "value": False,
        }

    # --- auto-repeat (#16) -------------------------------------------
    match = re.search(
        r"\balways repeat\b\s*(.+?)\s*\bevery\b\s*(.+)$", s
    )
    if match:
        interval = _parse_interval_words(match.group(2))
        if interval:
            platform, metric = _platform_metric_from_text(match.group(1))
            return {
                "action": "set_repeat",
                "interval_minutes": interval,
                "platform": platform, "metric": metric,
            }
    if (
        re.search(r"\bstop repeating\b", s)
        or "turn off auto-repeat" in s or "turn off auto repeat" in s
        or "don't repeat my orders" in s or "don't repeat anymore" in s
    ):
        return {"action": "clear", "key": "pref_auto_repeat"}

    # --- top up the missing part (#17) -------------------------------
    if (
        re.search(
            r"\b(always )?(top up|top-up|fill|order) (the )?"
            r"(missing|rest)\b",
            s,
        )
        or "order the missing part" in s
    ) and not re.search(r"\d", s):
        return {
            "action": "set", "key": "pref_topup_missing",
            "value": True,
        }
    if "don't top up" in s or "no top-up" in s or "no top up" in s:
        return {
            "action": "set", "key": "pref_topup_missing",
            "value": False,
        }
    if "just refund" in s:
        return {
            "action": "set", "key": "pref_topup_missing",
            "value": False, "ambiguous": True,
        }

    # --- small orders without asking (#18) ---------------------------
    # The OFF patterns run first: "stop placing orders without
    # asking" contains "without asking", which is also a SET
    # trigger below — checking off first keeps it from setting
    # the very thing the customer wants off.
    def _no_confirm_cap(message):
        number = re.search(r"\bunder\s+(\d+)\s*(?:birr|etb)?\b", message)
        if number:
            return int(number.group(1))
        return DEFAULT_NO_CONFIRM_MAX_ETB

    if re.search(
        r"\bask me to confirm (again|always|every|each)\b", s
    ) or "turn off placing without asking" in s or (
        "turn off auto-place" in s
    ) or "turn off no-confirm" in s or re.search(
        r"\bstop placing\b.*\bwithout asking\b", s
    ):
        return {
            "action": "set", "key": "pref_no_confirm", "value": False,
        }
    if re.search(
        r"\bplace (?:my )?(?:small )?orders? without asking\b", s
    ) or re.search(
        r"\b(don't|do not|dont) ask( me)? to confirm\b", s
    ) or "skip the confirmation" in s or "skip the confirm" in s:
        return {
            "action": "set", "key": "pref_no_confirm", "value": True,
            "cap": _no_confirm_cap(s),
        }
    if re.search(
        r"\border(s)? under (\d+)\s*(?:birr|etb)?\b.*\bjust place\b",
        s,
    ) or re.search(r"\bjust place (my )?(small )?orders\b", s) or (
        re.search(r"\b(small )?orders? just place\b", s)
    ) or (
        re.search(r"\bplace\b.*\borders?\b.*\bwithout asking\b", s)
    ):
        return {
            "action": "set", "key": "pref_no_confirm", "value": True,
            "cap": _no_confirm_cap(s),
        }

    # --- quiet hours (#19) -------------------------------------------
    if re.search(r"\bturn off quiet hours\b", s) or (
        "message me anytime" in s or "no quiet hours" in s
    ):
        return {"action": "clear", "key": "pref_quiet_hours"}
    if re.search(r"\bdon't message me at night\b", s) or re.search(
        r"\bno messages? at night\b", s
    ) or "quiet hours" in s or re.search(
        r"\bdon't message me (?:after|from)\b", s
    ) or "message me only in the morning" in s or (
        "only message me in the morning" in s
    ):
        times = re.findall(
            r"(\d{1,2}(?::\d{2})?\s*(?:am|pm))", s
        )
        if len(times) >= 2:
            start = _parse_clock(times[0])
            end = _parse_clock(times[1])
            if start and end:
                return {
                    "action": "set", "key": "pref_quiet_hours",
                    "value": {"start": start, "end": end},
                }
        if re.search(r"\bdon't message me (?:after|from)\b", s):
            start = re.search(
                r"\b(?:after|from)\s+"
                r"(\d{1,2}(?::\d{2})?\s*(?:am|pm))",
                s,
            )
            end = re.search(
                r"\bto\s+(\d{1,2}(?::\d{2})?\s*(?:am|pm))", s
            )
            if start:
                return {
                    "action": "set", "key": "pref_quiet_hours",
                    "value": {
                        "start": _parse_clock(start.group(1)),
                        "end": (
                            _parse_clock(end.group(1))
                            if end else "07:00"
                        ),
                    },
                }
        return {
            "action": "set", "key": "pref_quiet_hours",
            "value": {
                "start": QUIET_DEFAULT[0], "end": QUIET_DEFAULT[1],
            },
        }

    # --- favourite services (#21) ----------------------------------
    # "my favourite services are 5535, 6001" replaces the list;
    # "add service 5535 to my favourites" merges into it.
    match = re.search(
        r"\bmy (?:favourite|favorite)[s]?(?: services?)? (?:are|:)\s*"
        r"([\d, ]+)",
        s,
    )
    if match:
        ids = re.findall(r"\d{1,8}", match.group(1))
        if ids:
            return {
                "action": "set_favourites", "ids": ids,
            }
    match = re.search(
        r"\badd (?:service )?(\d{1,8}) to my (?:favourite|favorite)[s]?\b",
        s,
    )
    if match:
        return {"action": "add_favourite", "id": match.group(1)}
    match = re.search(
        r"\b(?:favourite|favorite) service (\d{1,8})\b", s
    )
    if match:
        return {"action": "add_favourite", "id": match.group(1)}
    match = re.search(
        r"\bmy (?:favourite|favorite)(?: service)? (?:is|:)?\s*"
        r"(\d{1,8})\b",
        s,
    )
    if match:
        return {"action": "add_favourite", "id": match.group(1)}
    match = re.search(
        r"\bmake (?:service )?(\d{1,8}) my (?:favourite|favorite)\b",
        s,
    )
    if match:
        return {"action": "add_favourite", "id": match.group(1)}
    match = re.search(r"\bi love service (\d{1,8})\b", s)
    if match:
        return {"action": "add_favourite", "id": match.group(1)}
    match = re.search(
        r"\bremove (?:service )?(\d{1,8}) from my "
        r"(?:favourite|favorite)[s]?\b",
        s,
    )
    if match:
        return {"action": "remove_favourite", "id": match.group(1)}
    if (
        "forget my favourites" in s or "forget my favorites" in s
        or "clear my favourites" in s or "clear my favorites" in s
        or "turn off my favourites" in s
    ):
        return {"action": "clear", "key": "pref_favourite_services"}

    # --- low balance alert (#24) -----------------------------------
    match = re.search(
        r"\bwarn me when my balance (?:is )?(?:below|under|drops below|"
        r"falls below)\s+(\d[\d,]*)\b",
        s,
    )
    if not match:
        match = re.search(
            r"\b(?:low balance alert|alert me if my balance drops below|"
            r"tell me when my balance is under)\s+(?:at\s+)?(\d[\d,]*)\b",
            s,
        )
    if match:
        return {
            "action": "set", "key": "pref_low_balance_alert_etb",
            "value": int(match.group(1).replace(",", "")),
        }
    if re.search(
        r"\b(?:tell me when|warn me when) my balance (?:gets low|is low|"
        r"drops)\b",
        s,
    ) and not re.search(r"\d", s):
        # No number named: ask for the level instead of inventing
        # one.
        return {"action": "ask_low_balance"}
    if "turn off low balance alert" in s or "no low balance alert" in s:
        return {"action": "clear", "key": "pref_low_balance_alert_etb"}

    # --- weekly spending limit (#25) -------------------------------
    match = re.search(
        r"\b(?:don't|do not|dont) let me spend more than\s+"
        r"(\d[\d,]*)\b",
        s,
    )
    if not match:
        match = re.search(
            r"\b(?:weekly spending limit|limit my spending to|"
            r"spend at most|max)\s+(\d[\d,]*)\b",
            s,
        )
        if match and "week" not in s and "max" in s:
            # "max 100 birr" with no week is not a weekly limit.
            match = None
    if match:
        return {
            "action": "set", "key": "pref_weekly_spend_limit_etb",
            "value": int(match.group(1).replace(",", "")),
        }
    if (
        "turn off weekly limit" in s or "no weekly limit" in s
        or "turn off the weekly spending limit" in s
    ):
        return {"action": "clear", "key": "pref_weekly_spend_limit_etb"}

    # --- pause / resume repeats (#27) ------------------------------
    if re.search(r"\bpause\b", s) and re.search(
        r"\b(repeats?|repeating|schedules?)\b", s
    ):
        return {"action": "pause_repeats"}
    if re.search(r"\bstop\b.*\brepeats?\b", s):
        return {"action": "pause_repeats"}
    if re.search(r"\b(resume|unpause)\b", s) and re.search(
        r"\b(repeats?|repeating|schedules?)\b", s
    ):
        return {"action": "resume_repeats"}

    # --- saved links (#31) -----------------------------------------
    # "save this link as main https://..." / "remember <link> as
    # main". A name is one slug word; "default"/"usual" are not
    # names — they belong to the default link (#11).
    match = re.search(
        r"\bsave (?:this )?link (?:as )?([a-z0-9_-]+)\b", s
    )
    if match and match.group(1) not in ("default", "usual"):
        links = extract_links(text)
        if links:
            return {
                "action": "set_saved_link",
                "name": match.group(1), "link": links[0],
            }
    match = re.search(
        r"\bremember\s+(https?://\S+|t\.me/\S+)\s+as\s+([a-z0-9_-]+)\b",
        s,
    )
    if match and match.group(2) not in ("default", "usual"):
        return {
            "action": "set_saved_link",
            "name": match.group(2), "link": match.group(1),
        }
    match = re.search(
        r"\bremember my ([a-z0-9_-]+) link\b", s
    )
    if match and match.group(1) not in ("default", "usual"):
        links = extract_links(text)
        if links:
            return {
                "action": "set_saved_link",
                "name": match.group(1), "link": links[0],
            }
    match = re.search(
        r"\bsave\s+(https?://\S+|t\.me/\S+)\s+as my ([a-z0-9_-]+) "
        r"link\b",
        s,
    )
    if match and match.group(2) not in ("default", "usual"):
        return {
            "action": "set_saved_link",
            "name": match.group(2), "link": match.group(1),
        }
    if "forget my saved links" in s or "clear my saved links" in s:
        return {"action": "clear", "key": "pref_saved_links"}
    match = re.search(
        r"\b(?:use|order on) my ([a-z0-9_-]+) link\b", s
    )
    if match and match.group(1) not in ("default", "usual"):
        saved = (
            get_pref(user_id, "pref_saved_links")
            if user_id is not None else None
        ) or {}
        link = saved.get(match.group(1))
        if link:
            return {
                "action": "use_saved_link",
                "name": match.group(1), "link": link,
            }
    match = re.search(
        r"\b(?:forget|delete) my ([a-z0-9_-]+) link\b", s
    )
    if match and match.group(1) not in ("default", "usual"):
        return {"action": "clear_saved_link", "name": match.group(1)}

    # --- best time to deliver (#32) --------------------------------
    if re.search(
        r"\b(best time|when (?:is|should i)|what(?:'s| is) the best time)"
        r"\b.*\b(order|deliver)\b",
        s,
    ) or re.search(r"\bwhat time is best for\b", s):
        platform, metric = _platform_metric_from_text(text)
        return {
            "action": "best_time",
            "platform": platform, "metric": metric,
        }

    # --- auto-cancel if too slow (#34) -----------------------------
    match = re.search(
        r"\b(?:auto-?cancel|cancel)(?: it| my order)? if (?:it )?"
        r"(?:takes|is) (?:longer|more) than\s+(.+?)$",
        s,
    )
    if match:
        minutes = _parse_duration_minutes(match.group(1))
        if minutes:
            return {
                "action": "set", "key": "pref_auto_cancel_min",
                "value": minutes,
            }
    if (
        re.search(r"\bcancel stuck orders? after\b", s)
        or "auto-cancel if too slow" in s
        or "auto cancel if too slow" in s
        or "cancel my order if it's slow" in s
        or "cancel if it takes too long" in s
    ):
        match = re.search(r"\bafter\s+(.+?)$", s)
        minutes = (
            _parse_duration_minutes(match.group(1)) if match else None
        )
        return {
            "action": "set", "key": "pref_auto_cancel_min",
            "value": minutes or 60,
        }
    if (
        "turn off auto-cancel" in s or "turn off auto cancel" in s
        or "don't auto-cancel" in s or "no auto-cancel" in s
        or "stop auto-cancel" in s
    ):
        return {"action": "clear", "key": "pref_auto_cancel_min"}

    # --- start fast only (#36) --------------------------------------
    if "turn off start fast only" in s:
        return {
            "action": "set", "key": "pref_start_fast_only",
            "value": False,
        }
    if re.search(
        r"\b(?:start fast|fast[- ]start)\b", s
    ) or "only use services that start fast" in s or (
        "services that start fast only" in s
    ):
        return {
            "action": "set", "key": "pref_start_fast_only",
            "value": True,
        }

    # --- language lock (#37) ---------------------------------------
    _LANG_WORDS = {
        "amharic": "am", "english": "en",
        "tigrinya": "ti", "oromo": "om",
    }
    match = re.search(
        r"\b(?:always reply in|speak to me in|lock my language to|"
        r"only|reply in)\s+(amharic|english|tigrinya|oromo)\b",
        s,
    )
    if match:
        return {
            "action": "set", "key": "pref_language",
            "value": _LANG_WORDS[match.group(1)],
        }
    if (
        "reply in whatever language i use" in s
        or "turn off language lock" in s or "no language lock" in s
        or "unlock my language" in s
    ):
        return {"action": "clear", "key": "pref_language"}

    # --- double confirm for big orders (#38) -----------------------
    match = re.search(
        r"\bdouble[- ]?(?:check|confirm)\b.*"
        r"\b(?:over|above)\s+(\d[\d,]*)\b",
        s,
    )
    if not match:
        match = re.search(
            r"\bask (?:me )?twice\b.*"
            r"\b(?:over|above)\s+(\d[\d,]*)\b",
            s,
        )
    if not match:
        match = re.search(
            r"\b(?:double[- ]?(?:check|confirm)|ask (?:me )?twice)\b"
            r".*\bbig orders\b",
            s,
        )
    if not match:
        match = re.search(r"\bconfirm big orders twice\b", s)
    if match:
        amount = match.group(1) if match.lastindex else None
        return {
            "action": "set", "key": "pref_double_confirm_etb",
            "value": int(amount.replace(",", "")) if amount else 1000,
        }
    if "turn off double confirm" in s or "stop the double confirm" in s:
        return {"action": "clear", "key": "pref_double_confirm_etb"}

    # --- never use these services (#39) ----------------------------
    match = re.search(
        r"\b(?:never use|don't (?:ever )?use|do not (?:ever )?use|ban)"
        r" (?:these )?(?:services?)?[:\s]*([\d, ]+)",
        s,
    )
    if match:
        ids = re.findall(r"\d{1,8}", match.group(1))
        if ids:
            return {"action": "add_banned", "ids": ids}
    match = re.search(r"\bunban (?:service )?(\d{1,8})\b", s)
    if match:
        return {"action": "remove_banned", "id": match.group(1)}
    if (
        "clear my banned services" in s
        or "remove all my banned services" in s
        or "unban my services" in s
    ):
        return {"action": "clear", "key": "pref_banned_services"}

    # --- try new services (#40) ------------------------------------
    if (
        "don't use new services" in s or "do not use new services" in s
        or "turn off try new" in s or "don't try new services" in s
        or "stop trying new services" in s
    ):
        return {
            "action": "set", "key": "pref_try_new", "value": False,
        }
    if re.search(
        r"\b(?:try|use|let me try) (?:the )?new\b", s
    ) or "i want to try new services" in s:
        return {
            "action": "set", "key": "pref_try_new", "value": True,
        }

    # --- watch my post (#30), wait for a lower price (#33),
    # monthly report (#35): remembered, but the doing part is not
    # switched on yet — the handler says so honestly.
    if (
        (
            re.search(r"\bwatch\b", s)
            and (
                "post" in s or "top it up" in s or "top up" in s
                or "refill it" in s
            )
        )
        or "keep an eye on my post" in s
    ):
        links = extract_links(text)
        link = links[0] if links else None
        if link is None and user_id is not None:
            link = get_pref(user_id, "pref_default_link")
        below = None
        below_match = re.search(
            r"\bbelow\s+(\d[\d,]*)\b", s
        )
        if below_match:
            below = int(below_match.group(1).replace(",", ""))
        return {
            "action": "set_watch_post", "link": link, "below": below,
        }
    if "stop watching my post" in s:
        return {"action": "clear", "key": "pref_watch_post"}
    if (
        "my usual" not in s
        and (
            re.search(r"\bwait\b.*\b(?:until|for|when)\b", s)
            or re.search(
                r"\btell me when\b.*\b(?:cheaper|price)\b", s
            )
        )
        and (
            "lower price" in s or "cheaper" in s
            or "drops below" in s or "drop below" in s
            or "under" in s or "below" in s or "drop" in s
        )
    ):
        platform, metric = _platform_metric_from_text(text)
        target = None
        target_match = re.search(
            r"\b(?:under|below)\s+(\d+(?:\.\d+)?)\b", s
        )
        if target_match:
            target = float(target_match.group(1))
        return {
            "action": "set_wait_price",
            "platform": platform, "metric": metric, "target": target,
        }
    if "stop waiting for a lower price" in s or "stop waiting" in s:
        return {"action": "clear", "key": "pref_wait_price"}
    if (
        "monthly report" in s or "monthly spending report" in s
        or "report every month" in s or "monthly summary" in s
    ):
        if "stop" in s:
            return {
                "action": "set", "key": "pref_monthly_report",
                "value": False,
            }
        return {
            "action": "set", "key": "pref_monthly_report",
            "value": True,
        }

    # --- NOT approved: recognised, never set. These run LAST, so
    # a real setting always wins over a lookalike phrase. The
    # handler answers with the honest line for the option.
    if (
        "turn off the test order" in s or "no test order" in s
        or "don't do a test order" in s or "never do a test order" in s
        or "place it all at once, no test" in s
    ):
        return {"action": "not_available", "option": 1}
    if (
        re.search(r"\bmake the test\b", s)
        or re.search(r"\btest with\b.*\bfirst\b", s)
    ):
        return {"action": "not_available", "option": 2}
    if (
        re.search(r"\btest (line|orders? over)\b", s)
        or "change the test line" in s
    ):
        return {"action": "not_available", "option": 3}
    if (
        re.search(r"\ballow\b.*\bextra\b", s)
        or re.search(r"\byou can spend\b.*\bmore for me\b", s)
        or "let paxyo cover" in s or "paxyo can cover" in s
    ):
        return {"action": "not_available", "option": 5}
    if (
        re.search(
            r"\btry (?:\d+|more|just once|twice|three|five)"
            r"(?: times?)?\b",
            s,
        )
        or "try more services" in s
    ):
        return {"action": "not_available", "option": 7}
    if (
        re.search(r"\bpin\b.*\bservice\b", s)
        or re.search(r"\balways use service (\d{1,8})\b", s)
        or re.search(r"\buse only service (\d{1,8})\b", s)
        or "never change from service" in s
        or "stick to service" in s
    ):
        return {"action": "not_available", "option": 9}
    if (
        "spending cap" in s or "cap my spending" in s
        or re.search(
            r"\bnever spend more than\b.*\b(?:per|on) (?:one )?order\b", s
        )
    ):
        return {"action": "not_available", "option": 10}
    if (
        re.search(r"\bsplit\b.*\bacross services\b", s)
        or re.search(r"\bsplit\b.*\bbetween services\b", s)
        or re.search(r"\b(two|multiple) services for one order\b", s)
    ):
        return {"action": "not_available", "option": 22}
    if (
        "delivery report" in s
        or ("report after" in s and "delivery" in s)
    ):
        return {"action": "not_available", "option": 23}
    if (
        "my usual" in s
        and ("cheaper" in s or "price" in s)
        and ("tell me" in s or "alert" in s or "watch" in s)
    ):
        return {"action": "not_available", "option": 28}
    if (
        "all or nothing" in s
        or "if it can't all deliver" in s
        or "don't partially deliver" in s
        or "don't deliver partially" in s
    ):
        return {"action": "not_available", "option": 29}

    return None


def parse_pref_commands(text, user_id=None):
    """Two settings at once ("cheapest first and don't message me
    at night") -> a list of parse_pref_command actions, at most
    3, deduped by (action, key). Splits on " and " and ", " — but
    when a part does not parse, the whole message is tried as ONE
    action instead (so "my favourite services are 5535, 6001"
    does not split the id list in two). Returns [] when nothing
    parses."""
    if not text:
        return []
    parts = re.split(r"\s+and\s+|,\s+", str(text).strip())
    if len(parts) < 2:
        single = parse_pref_command(text, user_id)
        return [single] if single else []
    actions = [parse_pref_command(part, user_id) for part in parts]
    if any(action is None for action in actions):
        single = parse_pref_command(text, user_id)
        return [single] if single else []
    seen = set()
    out = []
    for action in actions:
        key = (action.get("action"), action.get("key"),
               action.get("name"), action.get("id"))
        if key in seen:
            continue
        seen.add(key)
        out.append(action)
        if len(out) >= 3:
            break
    return out


