_PREF_LABELS = {
    "pref_pick_order": "pick order",
    "pref_ask_first": "ask first",
    "pref_max_slowness_min": "speed limit",
    "pref_default_link": "default link",
    "pref_default_quantity": "usual quantity",
    "pref_price_ceiling": "price limit",
    "pref_refill_only": "refill only",
    "pref_auto_repeat": "auto-repeat",
    "pref_topup_missing": "top up the missing part",
    "pref_no_confirm": "placing small orders without asking",
    "pref_no_confirm_max_etb": "small-order cap",
    "pref_quiet_hours": "quiet hours",
    "pref_favourite_services": "favourite services",
    "pref_low_balance_alert_etb": "low balance alert",
    "pref_weekly_spend_limit_etb": "weekly spending limit",
    "pref_saved_links": "saved links",
    "pref_auto_cancel_min": "auto-cancel",
    "pref_start_fast_only": "start fast only",
    "pref_language": "language",
    "pref_double_confirm_etb": "double confirm",
    "pref_banned_services": "banned services",
    "pref_try_new": "try new services",
    "pref_watch_post": "watch my post",
    "pref_wait_price": "wait for a lower price",
    "pref_monthly_report": "monthly report",
}


_LANGUAGE_NAMES = {
    "en": "English", "am": "Amharic", "ti": "Tigrinya", "om": "Oromo",
}


def _pref_language_name(code):
    """"am" -> "Amharic" (settings replies)."""
    return _LANGUAGE_NAMES.get(code, code)


def _pref_label(key):
    """A short human label for a pref key (settings replies)."""
    return _PREF_LABELS.get(key, key)


def _pref_set_line(key, value):
    """The confirmation line for a pref just set ("Got it — ...").
    English — the chat bridge translates it for Amharic /
    Tigrinya / Oromo users."""
    if key == "pref_pick_order":
        if value == "cheapest":
            return "I'll use the cheapest first from now on"
        return "I'll use the fastest first from now on"
    if key == "pref_ask_first":
        if value:
            return (
                "I'll ask you first before moving a stuck order "
                "to another service"
            )
        return "I'll move a stuck order myself, no need to ask"
    if key == "pref_max_slowness_min":
        return (
            "I'll never use a service slower than "
            f"{format_interval(value)}"
        )
    if key == "pref_default_link":
        return f"I'll use {value} as your link when you don't paste one"
    if key == "pref_price_ceiling":
        return (
            "I'll never pay more than "
            f"{format_money(value)} ETB per 1,000"
        )
    if key == "pref_refill_only":
        if value:
            return "I'll only use services with refill"
        return "refill doesn't matter anymore"
    if key == "pref_topup_missing":
        if value:
            return (
                "when an order is short, I'll order the missing "
                "part myself instead of only refunding"
            )
        return (
            "when an order is short, I'll just refund the "
            "missing part"
        )
    if key == "pref_quiet_hours":
        return (
            "I won't message you between "
            f"{value['start']} and {value['end']} EAT — updates "
            "wait until morning"
        )
    if key == "pref_favourite_services":
        ids = ", ".join(str(v) for v in value)
        return f"I'll prefer your favourite services ({ids}) when they fit"
    if key == "pref_low_balance_alert_etb":
        return (
            "I'll warn you when your balance drops below "
            f"{format_money(value)} ETB"
        )
    if key == "pref_weekly_spend_limit_etb":
        return (
            "I'll stop orders that would take this week's spending "
            f"over {format_money(value)} ETB"
        )
    if key == "pref_auto_cancel_min":
        return (
            "I'll cancel a stuck order and refund it after "
            f"{format_interval(value)} without asking"
        )
    if key == "pref_start_fast_only":
        if value:
            return (
                "I'll only use services that start fast "
                f"(within {START_FAST_MAX_MIN} minutes)"
            )
        return "any start speed is fine from now on"
    if key == "pref_language":
        return f"I'll always reply in {_pref_language_name(value)}"
    if key == "pref_double_confirm_etb":
        return (
            "I'll ask you twice before placing orders over "
            f"{format_money(value)} ETB"
        )
    if key == "pref_banned_services":
        ids = ", ".join(str(v) for v in value)
        return f"I won't use services {ids}"
    if key == "pref_try_new":
        if value:
            return "I'll try new services when they fit your order"
        return "I won't try new services"
    if key == "pref_monthly_report":
        if value:
            return "I'll send you a monthly report"
        return "no monthly report anymore"
    return f"{_pref_label(key)} is set"


def pref_settings_text(user_id):
    """The customer's current settings, one short line each, or
    the empty-state text when nothing is set. English — the chat
    bridge translates it for Amharic/Tigrinya/Oromo users."""
    lines = ["Your settings:"]
    pick = get_pref(user_id, "pref_pick_order")
    if pick == "cheapest":
        lines.append("• Order: cheapest first")
    elif pick == "fastest":
        lines.append("• Order: fastest first")
    if get_pref(user_id, "pref_ask_first"):
        lines.append("• If a service gets stuck: I ask you first")
    limit = get_pref(user_id, "pref_max_slowness_min")
    if limit is not None:
        lines.append(
            f"• Never slower than {format_interval(limit)}"
        )
    link = get_pref(user_id, "pref_default_link")
    if link:
        lines.append(f"• Default link: {link}")
    quantities = get_pref(user_id, "pref_default_quantity") or {}
    for key, value in quantities.items():
        lines.append(f"• Usual quantity ({key}): {value:,}")
    ceiling = get_pref(user_id, "pref_price_ceiling")
    if ceiling is not None:
        lines.append(
            "• Never pay more than "
            f"{format_money(ceiling)} ETB per 1,000"
        )
    if get_pref(user_id, "pref_refill_only"):
        lines.append("• Only services with refill")
    repeat = get_pref(user_id, "pref_auto_repeat")
    if isinstance(repeat, dict):
        lines.append(
            "• Repeat "
            f"{repeat.get('platform', '')} "
            f"{repeat.get('metric', '')} every "
            f"{format_interval(repeat.get('interval_minutes', 0))}"
        )
    if get_pref(user_id, "pref_topup_missing"):
        lines.append(
            "• Top up the missing part when an order is short"
        )
    allowed, cap = pref_no_confirm_cap(user_id)
    if allowed:
        lines.append(
            f"• Small orders under {cap} ETB: placed without asking"
        )
    hours = pref_quiet_hours(user_id)
    if hours:
        lines.append(f"• Quiet hours: {hours[0]}–{hours[1]} EAT")
    favourites = get_pref(user_id, "pref_favourite_services") or []
    if favourites:
        lines.append(
            "• Favourite services: " + ", ".join(str(v) for v in favourites)
        )
    alert = get_pref(user_id, "pref_low_balance_alert_etb")
    if alert is not None:
        lines.append(
            f"• Warn me when my balance is below {format_money(alert)} ETB"
        )
    weekly = get_pref(user_id, "pref_weekly_spend_limit_etb")
    if weekly is not None:
        lines.append(
            f"• Weekly spending limit: {format_money(weekly)} ETB"
        )
    saved = get_pref(user_id, "pref_saved_links") or {}
    for name, link in saved.items():
        lines.append(f"• Saved link ({name}): {link}")
    auto_cancel = get_pref(user_id, "pref_auto_cancel_min")
    if auto_cancel is not None:
        lines.append(
            "• Cancel a stuck order after "
            f"{format_interval(auto_cancel)}"
        )
    if get_pref(user_id, "pref_start_fast_only"):
        lines.append("• Only services that start fast")
    language = get_pref(user_id, "pref_language")
    if language:
        lines.append(
            f"• Always reply in {_pref_language_name(language)}"
        )
    double = get_pref(user_id, "pref_double_confirm_etb")
    if double is not None:
        lines.append(
            "• Ask twice before orders over "
            f"{format_money(double)} ETB"
        )
    banned = get_pref(user_id, "pref_banned_services") or []
    if banned:
        lines.append(
            "• Never use services: " + ", ".join(str(v) for v in banned)
        )
    if get_pref(user_id, "pref_try_new"):
        lines.append("• Try new services")
    watch = get_pref(user_id, "pref_watch_post")
    if isinstance(watch, dict) and watch.get("link"):
        lines.append(f"• Watching {watch['link']} for drops")
    wait = get_pref(user_id, "pref_wait_price")
    if isinstance(wait, dict):
        lines.append(
            "• Waiting for "
            f"{wait.get('platform', '')} {wait.get('metric', '')} under "
            f"{format_money(wait.get('target', 0))} ETB per 1,000"
        )
    if get_pref(user_id, "pref_monthly_report"):
        lines.append("• Monthly report on")
    if len(lines) == 1:
        return (
            "You haven't set anything yet — I use the normal way "
            "for everything: fastest first, I move a stuck order "
            "myself, and I always ask before placing an order.\n"
            "You can tell me things like: \"cheapest first\", "
            "\"ask me before you change service\", "
            "\"never slower than 1 hour\", \"my link is ...\", "
            "\"don't message me at night\"."
        )
    lines.append(
        "Say \"turn off ...\" to change one, or "
        "\"reset my settings\" to clear them all."
    )
    return "\n".join(lines)


async def _apply_setting_no_reply(user_id, action):
    """Apply one set/clear/set_quantity/set_repeat action without
    replying, and return its reply fragment (for the two-at-once
    combined reply), or None when it does not apply."""
    kind = action["action"]
    if kind == "clear":
        clear_pref(user_id, action["key"])
        return f"turned off {_pref_label(action['key'])}"
    if kind == "set_quantity":
        stored = dict(get_pref(user_id, "pref_default_quantity") or {})
        stored[action["key"]] = action["value"]
        set_pref(user_id, "pref_default_quantity", stored)
        return (
            "your usual quantity for "
            f"{action['key']} is {action['value']:,}"
        )
    if kind == "set_repeat":
        platform = action.get("platform")
        metric = action.get("metric")
        if not platform or not metric:
            traits = USER_TRAITS.get(user_id) or {}
            platform = platform or traits.get("usual_platform")
            metric = metric or traits.get("usual_metric")
        if not platform or not metric:
            return None
        set_pref(user_id, "pref_auto_repeat", {
            "interval_minutes": action["interval_minutes"],
            "platform": platform,
            "metric": metric,
        })
        return (
            f"after your next {platform} {metric} order, I'll "
            f"repeat it every {format_interval(action['interval_minutes'])}"
        )
    if kind == "set":
        key = action["key"]
        if key == "pref_no_confirm" and action.get("value") is True:
            asked = action.get("cap") or DEFAULT_NO_CONFIRM_MAX_ETB
            cap = min(asked, MAX_NO_CONFIRM_ETB)
            set_pref(user_id, "pref_no_confirm", True)
            set_pref(user_id, "pref_no_confirm_max_etb", cap)
            fragment = (
                f"small orders under {cap} ETB will go without asking"
            )
            if cap < asked:
                fragment += f" (capped at {MAX_NO_CONFIRM_ETB} ETB)"
            return fragment
        set_pref(user_id, key, action["value"])
        return _pref_set_line(key, action["value"])
    return None


async def handle_settings_text(message, user_id, text, lang, voice):
    """Handle a settings command (see parse_pref_command).
    Returns True when the message was a settings command (and
    the reply was sent), False when it was not one. Runs right
    after the forget-traits check in handle_order_text, before
    the classifier — so a settings command never leaks into an
    order, and an order never leaks into a setting. `message` is
    the Telegram message to reply to (reply_message needs the
    message object — a bare user id has no reply_text). Two
    settings at once ("cheapest first and don't message me at
    night") get ONE combined reply; anything that is not a plain
    set/clear (show, clear-all, pause, best-time, a not-approved
    ask) falls back to handling the first action alone."""
    actions = parse_pref_commands(text, user_id)
    if not actions:
        return False
    if len(actions) > 1:
        combinable = {"set", "clear", "set_quantity", "set_repeat"}
        if all(
            a["action"] in combinable and not a.get("ambiguous")
            for a in actions
        ):
            fragments = []
            for action in actions:
                fragment = await _apply_setting_no_reply(user_id, action)
                if fragment:
                    fragments.append(fragment)
            if fragments:
                await reply_message(
                    message,
                    "Got it — " + ", and ".join(fragments) + ".",
                    lang=lang, voice=voice,
                )
                return True
        return await _handle_one_setting(
            message, user_id, actions[0], text, lang, voice
        )
    return await _handle_one_setting(
        message, user_id, actions[0], text, lang, voice
    )


async def _handle_one_setting(message, user_id, action, text, lang, voice):
    """One settings action, with its reply. Returns True when it
    was handled (and the reply was sent)."""
    # An ambiguous phrase ("just do it", "just refund", "any
    # price is fine") only counts as a setting when the pref is
    # actually on and no Confirm card is waiting — otherwise it
    # is the user answering the order in front of them.
    if action.get("ambiguous"):
        key = action["key"]
        current = get_pref(user_id, key)
        if user_id in PENDING or not current:
            return False
    if action["action"] == "show":
        await reply_message(
            message, pref_settings_text(user_id),
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "clear_all":
        for key in PREF_KEYS:
            clear_pref(user_id, key)
        await reply_message(
            message,
            "Done — all your settings are cleared. I use the "
            "normal way for everything now.",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "clear":
        clear_pref(user_id, action["key"])
        await reply_message(
            message,
            f"Done — turned off {_pref_label(action['key'])}.",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "not_available":
        await reply_message(
            message,
            _NOT_AVAILABLE_TEXT.get(
                action["option"], "That can't be changed."
            ),
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "ask_low_balance":
        await reply_message(
            message,
            "Below what amount should I warn you? Tell me like "
            "\"warn me when my balance is below 100 birr\".",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "pause_repeats":
        paused = 0
        if paxyo is not None:
            try:
                schedules = await paxyo.list_recurring(user_id) or []
            except Exception as exc:
                log.warning("pause repeats list failed: %s", exc)
                schedules = []
            for sched in schedules:
                try:
                    await paxyo.pause_recurring(sched.get("id"), user_id)
                    paused += 1
                except Exception as exc:
                    log.warning("pause repeat failed: %s", exc)
        if paused:
            await reply_message(
                message,
                f"Done — paused {paused} repeating order"
                f"{'s' if paused != 1 else ''}.",
                lang=lang, voice=voice,
            )
        else:
            await reply_message(
                message,
                "You have no repeating orders to pause.",
                lang=lang, voice=voice,
            )
        return True
    if action["action"] == "resume_repeats":
        # No resume endpoint on the server yet: honest, not faked.
        await reply_message(
            message,
            "Resuming a paused repeat isn't set up yet — tell me "
            "the repeat again (like \"always repeat my TikTok "
            "views every Monday\") and I'll start it.",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "best_time":
        platform = action.get("platform")
        metric = action.get("metric")
        fastest = None
        if platform and metric and paxyo is not None:
            try:
                services = await paxyo.services()
                picks = pick_services(
                    services or [], platform=platform,
                    service_hint=metric, limit=1,
                )
                fastest = picks[0] if picks else None
            except Exception as exc:
                log.warning("best time services failed: %s", exc)
        if fastest is not None:
            avg = fastest.get("average_time")
            if avg:
                line = (
                    f"The fastest {metric} usually starts within "
                    f"{avg} — order any time, the sooner the better."
                )
            else:
                line = (
                    f"The fastest {metric} has no start time listed "
                    "— order any time, the sooner the better."
                )
        elif platform and metric:
            line = f"I couldn't find a {metric} service right now."
        else:
            line = (
                "Order any time — the fastest services start within "
                "minutes. Tell me the platform and metric and I'll "
                "check the fastest one."
            )
        await reply_message(message, line, lang=lang, voice=voice)
        return True
    if action["action"] == "set_favourites":
        set_pref(user_id, "pref_favourite_services", action["ids"])
        await reply_message(
            message,
            "Got it — " + _pref_set_line(
                "pref_favourite_services", action["ids"]) + ".",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "add_favourite":
        merged = list(
            get_pref(user_id, "pref_favourite_services") or []
        )
        if action["id"] not in merged:
            merged.append(action["id"])
        if len(merged) > MAX_FAVOURITE_SERVICES:
            await reply_message(
                message,
                "You already have 20 favourite services — remove "
                "one first.",
                lang=lang, voice=voice,
            )
            return True
        set_pref(user_id, "pref_favourite_services", merged)
        await reply_message(
            message,
            "Got it — " + _pref_set_line(
                "pref_favourite_services", merged) + ".",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "remove_favourite":
        merged = [
            v for v in (
                get_pref(user_id, "pref_favourite_services") or []
            )
            if v != action["id"]
        ]
        if merged:
            set_pref(user_id, "pref_favourite_services", merged)
        else:
            clear_pref(user_id, "pref_favourite_services")
        await reply_message(
            message,
            "Done — removed service "
            f"{action['id']} from your favourites.",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "add_banned":
        merged = list(get_pref(user_id, "pref_banned_services") or [])
        for sid in action["ids"]:
            if sid not in merged:
                merged.append(sid)
        if len(merged) > MAX_BANNED_SERVICES:
            await reply_message(
                message,
                "You already have 50 banned services — unban one "
                "first.",
                lang=lang, voice=voice,
            )
            return True
        set_pref(user_id, "pref_banned_services", merged)
        await reply_message(
            message,
            "Got it — " + _pref_set_line(
                "pref_banned_services", merged) + ".",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "remove_banned":
        merged = [
            v for v in (get_pref(user_id, "pref_banned_services") or [])
            if v != action["id"]
        ]
        if merged:
            set_pref(user_id, "pref_banned_services", merged)
        else:
            clear_pref(user_id, "pref_banned_services")
        await reply_message(
            message,
            f"Done — service {action['id']} is allowed again.",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "set_saved_link":
        stored = dict(get_pref(user_id, "pref_saved_links") or {})
        stored[action["name"]] = action["link"]
        set_pref(user_id, "pref_saved_links", stored)
        await reply_message(
            message,
            f"Got it — I'll remember {action['link']} as your "
            f"{action['name']} link.",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "use_saved_link":
        draft = PARTIAL.get(user_id) or {}
        draft["link"] = action["link"]
        PARTIAL[user_id] = draft
        await reply_message(
            message,
            f"Your {action['name']} link is {action['link']} — "
            "what do you want to order on it?",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "clear_saved_link":
        stored = dict(get_pref(user_id, "pref_saved_links") or {})
        if action["name"] not in stored:
            await reply_message(
                message,
                f"You don't have a saved link called {action['name']}.",
                lang=lang, voice=voice,
            )
            return True
        stored.pop(action["name"])
        if stored:
            set_pref(user_id, "pref_saved_links", stored)
        else:
            clear_pref(user_id, "pref_saved_links")
        await reply_message(
            message,
            f"Done — forgot your {action['name']} link.",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "set_watch_post":
        link = action.get("link")
        if not link:
            await reply_message(
                message,
                "Which post should I watch? Send me the link.",
                lang=lang, voice=voice,
            )
            return True
        value = {"link": link}
        if action.get("below"):
            value["below"] = action["below"]
        set_pref(user_id, "pref_watch_post", value)
        await reply_message(
            message,
            f"Got it — I've saved {link} to watch. The automatic "
            "top-up isn't switched on yet, so it won't top up on "
            "its own for now.",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "set_wait_price":
        platform = action.get("platform")
        metric = action.get("metric")
        target = action.get("target")
        if not platform or not metric or target is None:
            await reply_message(
                message,
                "Which service should I wait for, and under what "
                "price per 1,000? Tell me like \"wait until TikTok "
                "views are under 5 birr\".",
                lang=lang, voice=voice,
            )
            return True
        set_pref(user_id, "pref_wait_price", {
            "platform": platform, "metric": metric, "target": target,
        })
        await reply_message(
            message,
            f"Got it — I'll wait for {platform} {metric} under "
            f"{format_money(target)} ETB per 1,000. The price "
            "watch isn't switched on yet, so I can't watch it "
            "for you right now.",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "set_quantity":
        stored = dict(get_pref(user_id, "pref_default_quantity") or {})
        stored[action["key"]] = action["value"]
        set_pref(user_id, "pref_default_quantity", stored)
        await reply_message(
            message,
            "Got it — your usual quantity for "
            f"{action['key']} is {action['value']:,} from now on.",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "set_repeat":
        platform = action.get("platform")
        metric = action.get("metric")
        if not platform or not metric:
            traits = USER_TRAITS.get(user_id) or {}
            platform = platform or traits.get("usual_platform")
            metric = metric or traits.get("usual_metric")
        if not platform or not metric:
            await reply_message(
                message,
                "Which order should I repeat? Tell me like "
                "\"always repeat my TikTok views every Monday\".",
                lang=lang, voice=voice,
            )
            return True
        set_pref(user_id, "pref_auto_repeat", {
            "interval_minutes": action["interval_minutes"],
            "platform": platform,
            "metric": metric,
        })
        await reply_message(
            message,
            "Got it — after your next "
            f"{platform} {metric} order, I'll repeat it every "
            f"{format_interval(action['interval_minutes'])}.",
            lang=lang, voice=voice,
        )
        return True
    if action["action"] == "set":
        key = action["key"]
        if key == "pref_no_confirm" and action.get("value") is True:
            # #18: explicit opt-in only, small orders only, and
            # the bot confirms the setting back in chat. The cap
            # the customer names is honoured up to 100 ETB.
            asked = action.get("cap") or DEFAULT_NO_CONFIRM_MAX_ETB
            cap = min(asked, MAX_NO_CONFIRM_ETB)
            set_pref(user_id, "pref_no_confirm", True)
            set_pref(user_id, "pref_no_confirm_max_etb", cap)
            note = (
                "Got it — small orders under "
                f"{cap} ETB will go without asking from now on. "
                "Bigger orders still get a Confirm card."
            )
            if cap < asked:
                note += (
                    f" (I capped it at {MAX_NO_CONFIRM_ETB} ETB.)"
                )
            if user_id in PENDING:
                note += (
                    " Your order that is waiting still needs the "
                    "Confirm card."
                )
            await reply_message(
                message, note, lang=lang, voice=voice,
            )
            return True
        set_pref(user_id, key, action["value"])
        note = f"Got it — {_pref_set_line(key, action['value'])}."
        if key == "pref_monthly_report" and action["value"] is True:
            # #35: remembered, but the doing part is not switched
            # on yet — say so honestly, like drip-feed before its
            # server file landed.
            note += (
                " It isn't switched on yet, so no report will "
                "arrive until it is."
            )
        await reply_message(
            message, note, lang=lang, voice=voice,
        )
        return True
    return False


def _deadline_from_draft(value):
    """A draft deadline (ISO string from the saved draft, or a
    datetime in tests) as an aware EAT datetime, or None."""
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.astimezone(EAT_TZ)
    try:
        parsed = datetime.fromisoformat(str(value))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=EAT_TZ)
    return parsed.astimezone(EAT_TZ)


def _pref_blocked_text(blocked_by, user_id):
    """The reply when every candidate service is filtered out by
    the customer's own prefs: which setting blocked it, and how
    to change it. English — the chat bridge translates it. For a
    deadline the reply also offers "place it anyway", which
    clears the deadline (see the multi-turn flow)."""
    if blocked_by == "deadline":
        return (
            "No service can deliver by your deadline — I kept "
            "your order. Say \"place it anyway\" to order without "
            "the deadline, or pick a later time."
        )
    reasons = {
        "max_slowness": (
            "your speed limit "
            "("
            f"{format_interval(get_pref(user_id, 'pref_max_slowness_min') or 0)}"
            ")"
        ),
        "price_ceiling": (
            "your price limit "
            "("
            f"{format_money(get_pref(user_id, 'pref_price_ceiling') or 0)}"
            " ETB per 1,000)"
        ),
        "refill_only": "refill-only",
        "banned": "the services you banned",
        "start_fast": "only services that start fast",
    }
    reason = reasons.get(blocked_by, "your settings")
    return (
        f"No service fits {reason} — I kept your order. "
        "Say \"turn off ...\" to change it, or \"reset my "
        "settings\" to clear them all."
    )


# --- failure log (the confusion tracker) ------------------------------
# Every chat where the bot got confused is recorded twice: in the
# in-memory CONFUSIONS list (bounded, newest last) and, best-effort,
# in the server-side bot_confusions table — that table is what the
# daily list and the admin "Confused chats" section will read
# (built after this round). Nothing sensitive is ever stored: phone
# numbers are masked, balance figures are hidden, and the text is
# capped at 500 characters like the conversation history.

_PHONE_RE = re.compile(
    r"\+?251[79]\d{8}|\b0[79]\d{8}\b|\b\d{3}[ -]\d{3}[ -]\d{4}\b|\b\d{9,}\b"
)
_BALANCE_RE = re.compile(
    r"(?i)(balance(?: is now)?\s*:?\s*)[\d,]+(?:\.\d+)?\s*ETB"
)


def _scrub_confusion_text(text: str) -> str:
    """Strip anything sensitive from a logged message: phone numbers
    (Ethiopian 09/07/+251 and any 9+ digit run) and balance figures
    (\"Balance: 1,000.00 ETB\", \"balance is now 10.00 ETB\"). Links,
    quantities and service names stay: the daily list needs them to
    see what the user actually asked for."""
    if not text:
        return ""
    scrubbed = _PHONE_RE.sub("[phone]", str(text))
    scrubbed = _BALANCE_RE.sub(r"\1[hidden]", scrubbed)
    return scrubbed.strip()[:500]


async def _post_confusion(entry: dict) -> None:
    """One best-effort POST of a logged confusion. Never raises."""
    if paxyo is None:
        return
    try:
        await paxyo.log_confusion(
            entry["telegram_id"], entry["user_message"],
            entry["bot_reply"], entry["reason"],
        )
    except Exception as exc:
        log.warning("confusion log failed: %s", exc)


def log_confusion(user_id: int, user_text: str, bot_reply: str,
                  reason: str) -> None:
    """Record one confused chat in the failure log. Never raises,
    never blocks a reply: the in-memory list is written at once and
    the API post is queued in the background."""
    if reason not in CONFUSION_REASONS:
        reason = "not_understood"
    entry = {
        "telegram_id": int(user_id),
        "user_message": _scrub_confusion_text(user_text),
        "bot_reply": _scrub_confusion_text(bot_reply),
        "reason": reason,
    }
    CONFUSIONS.append(entry)
    del CONFUSIONS[:-MAX_CONFUSIONS]
    if paxyo is None:
        return
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        return
    loop.create_task(_post_confusion(entry))


# --- garbled input ------------------------------------------------------
# Words the bot can read, for telling voice-to-text garbage apart
# from a real attempt: platforms, metrics, and the words of the
# intents and everyday chat. A message with none of these, no
# digits, no link, no @handle and no emoji carries nothing readable.
_GARBLED_KNOWN_WORDS = frozenset(
    list(_PLATFORMS) + list(_PLATFORM_WORDS) + list(_METRICS) + [
        "balance", "price", "order", "deposit", "cancel", "status",
        "history", "link", "pay", "payment", "help", "support",
        "cheap", "cheapest", "fast", "fastest", "much", "many",
        "want", "buy", "get", "give", "show", "check", "send",
        "please", "thanks", "hello", "hi", "yes", "no", "ok",
        "first", "second", "third", "one", "two", "three", "ten",
        "hundred", "thousand", "like", "likes", "watch", "hours",
        "video", "post", "profile", "account", "service", "change",
        "wrong", "again", "usual", "same", "my", "me", "i", "the",
        "a", "an", "for", "and", "to", "of", "it", "that", "this",
        "what", "how", "when", "is", "are", "do", "can", "could",
        "would", "should", "not", "dont", "don't",
    ]
)


def _looks_garbled(text: str) -> bool:
    """True when a message carries nothing the bot can read: no
    digits, no link, no @handle, no emoji, and no known word at
    all. Voice-to-text garbage (\"Sent br aleg ahun\", live 14 Nov
    2026) lands here; a real attempt with a typo (\"tiktok veews\")
    still has a known word and is not garbled. Text in the
    Ethiopic script is never garbled — its words are just not in
    the Latin word list (a failed translation is a language issue,
    not garbage)."""
    s = (text or "").strip().lower()
    if not s:
        return True
    if re.search(r"[\u1200-\u137f]", s):
        return False
    if re.search(r"\d", s):
        return False
    if "://" in s or s.startswith("@") or " @" in s:
        return False
    if any(emoji_meanings(s)):
        return False
    words = set(re.findall(r"[a-z']+", s))
    return not (words & _GARBLED_KNOWN_WORDS)


# --- better fallback ------------------------------------------------------
# The bot never dead-ends on a bare "I did not understand": it asks
# ONE short question tied to the missing slot, and on the second
# miss in a row it offers the main choices too. The miss count
# lives in FALLBACK_MISS and resets on any understood reply (see
# reply_message). Every fallback is logged in the failure log.

def _fallback_slot_question(user_id: int, merged: dict, lang: str) -> str:
    """The one question the fallback asks, tied to the missing slot:
    no platform or service yet -> which platform; service known
    but no link -> the link question for that service; link known
    but no quantity -> how many. The stored draft fills in what
    this turn did not say."""
    draft = PARTIAL.get(int(user_id)) or {}
    platform = (merged or {}).get("platform") or draft.get("platform")
    hint = (merged or {}).get("service_hint") or draft.get("service_hint")
    link = (merged or {}).get("link") or draft.get("link")
    quantity = (merged or {}).get("quantity")
    if quantity is None:
        quantity = draft.get("quantity")
    if not platform and not hint:
        return t("ask_platform", lang)
    if not link:
        return ask_link_text(platform, hint, lang)
    if quantity is None:
        return t("ask_quantity", lang)
    return t("ask_platform", lang)


async def fallback_reply(message, user_id: int, user_text: str, lang: str,
                         voice: bool = False, merged: dict = None) -> None:
    """Send the better fallback and log the confusion. The lead
    (\"I did not understand — \") stays so the user knows the bot
    missed; the question is what makes it not a dead end."""
    question = _fallback_slot_question(user_id, merged or {}, lang)
    text = t("fallback_lead", lang) + question
    if FALLBACK_MISS.get(int(user_id), 0) >= 1:
        text = text + "\n" + t("fallback_choices", lang)
    await reply_message(message, text, lang, voice=voice, is_fallback=True)
    reason = "garbled" if _looks_garbled(user_text) else "not_understood"
    log_confusion(user_id, user_text, text, reason)


def _record_bot_reply(bot_text: str) -> None:
    """Record the bot's reply against the user message that caused
    this turn (set by handle_order_text). Only the first reply of a
    turn is recorded, so one turn is one exchange."""
    user_id = _CURRENT_USER_ID.get()
    if user_id is None:
        return
    user_text = _LAST_USER_TEXT.get()
    if not user_text:
        return
    _LAST_USER_TEXT.set(None)
    record_exchange(user_id, user_text, bot_text)


# --- off-topic steering: first two get a general answer + nudge -----
OFF_TOPIC_COUNT = {}  # telegram_id -> consecutive off-topic turns


# --- no fake-follower moralizing (owner, 14 Nov 2026) --------------
# Paxyo sells followers/likes/views, so the bot must NEVER lecture
# a user about "fake followers" or warn them off buying. The AI's
# free answers sometimes do exactly that ("avoid buying fake
# followers"), so the rule is in every free-answer prompt AND in a
# sanitizer that strips any such sentence if the AI still writes
# one. The ban answer keeps the owner's NO line (14 Nov 2026,
# platform-general — no platform bans or strikes over fake
# followers, likes or views) — it states the fact for the ban
# question specifically and is not a lecture.
_MORALIZING_RES = (
    re.compile(
        r"avoid\s+(buying\s+)?(fake\s+)?(followers|likes|views|members|reactions)",
        re.IGNORECASE,
    ),
    re.compile(
        r"(don't|do not|never|shouldn't|should not)\s+buy\s+(fake\s+)?"
        r"(followers|likes|views|members|reactions)",
        re.IGNORECASE,
    ),
    re.compile(
        r"\bfake\s+(followers|likes|views|members|reactions)\b.{0,80}\b"
        r"(harm|hurt|risk|ban|damage|penal|danger|unsafe|bad for)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b(beware|be careful|watch out)\b.{0,60}\bfake\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"buying\s+(fake\s+)?(followers|likes|views)\b.{0,60}\b"
        r"(against|violates|breaks|harm|risk|danger)",
        re.IGNORECASE,
    ),
)


def strip_moralizing(text: str) -> str:
    """Drop any sentence that lectures the user against buying
    followers/likes/views (owner, 14 Nov 2026). Returns the cleaned
    text, or "" when nothing is left. A sentence that merely says
    the followers are real ("these are not fake followers") has no
    warning words and survives."""
    if not text:
        return ""
    parts = re.split(r"(?<=[.!?])\s+", text.strip())
    kept = [p for p in parts if not any(rx.search(p) for rx in _MORALIZING_RES)]
    return " ".join(kept).strip()


async def answer_general_question(text: str, lang: str):
    """A brief general-knowledge answer (1-2 short sentences) from
    the AI, or None when the AI is down. Never about Paxyo's supplier
    or costs — the system prompt says so, and the caller steers back
    to ordering right after. Never moralizes about fake followers
    (owner, 14 Nov 2026): the prompt forbids it and the reply is
    sanitized, so a warning the AI writes anyway never reaches the
    user."""
    system = (
        "Answer briefly (1-2 short sentences) from your own general "
        "knowledge, in "
        + {
            "am": "Amharic (Ethiopic fidels mixed with English)",
            "ti": "Tigrinya (Ge'ez script)",
            "om": "Oromo (Afaan Oromo, Latin script)",
        }.get(lang, "English")
        + ". Never mention where Paxyo's services come from, what "
        "Paxyo pays for them, or any supplier. Never quote a price. "
        "Never warn the user against buying followers, likes, views, "
        "members or reactions, and never call them fake — Paxyo sells "
        "these services."
    )
    try:
        reply = await ai_generate(text, system=system)
    except Exception as exc:
        _log_ai_failure("general answer failed", exc)
        return None
    return strip_moralizing((reply or "").strip()) or None


# --- offensive users: firm and blunt, never polite -------------------
_OFFENSIVE_RE = re.compile(
    r"\b(fuck\w*|shit\w*|bitch\w*|bastard\w*|asshole\w*|dickhead\w*|moron\w*|idiot\w*)\b"
    r"|shut up|stupid bot|dumb bot|hate you|useless bot",
    re.IGNORECASE,
)
OFFENSE_COUNT = {}  # telegram_id -> consecutive offensive messages


def is_offensive(text: str) -> bool:
    """True when the message insults or swears at the bot."""
    return bool(_OFFENSIVE_RE.search(normalize_text(text or "")))


# --- humor: a light line on happy paths ------------------------------
HUMOR_LINES = {
    "en": [
        "🎉 Order in — nice choice!",
        "Done! Your order is on its way. 🚀",
        "Nice — that's ordered! 🎉",
        "All set — enjoy! 🚀",
    ],
    "am": [
        "🎉 Order ገብቷል — ጥሩ ምርጫ!",
        "ተጠናቋል! Orderዎ በመንገድ ላይ ነው። 🚀",
        "ጥሩ ነው — ተዘዟል! 🎉",
        "ሁሉም ተዘጋጅቷል — ይደሰቱ! 🚀",
    ],
}
HUMOR_INDEX = {}


def humor_line(user_id: int, lang: str) -> str:
    """A rotating light line, so the same joke is not repeated
    every time."""
    lines = HUMOR_LINES.get(lang) or HUMOR_LINES["en"]
    idx = HUMOR_INDEX.get(user_id, 0)
    HUMOR_INDEX[user_id] = idx + 1
    return lines[idx % len(lines)]


# --- bare quantities, order-now, price/ban/public/terms/history ------
_BARE_QUANTITY_FILLERS = {"please", "pls", "just", "only", "thanks", "thank", "you"}


def bare_quantity(text: str):
    """A message that is essentially just a number ('1000 please',
    '200') as a quantity, or None. Quantities must be multiples of
    10, so a bare service ID (6139) never counts."""
    words = [
        w.strip(".,!?") for w in normalize_text(text or "").split()
    ]
    words = [w for w in words if w not in _BARE_QUANTITY_FILLERS]
    if len(words) == 1 and re.fullmatch(r"\d[\d,]*", words[0]):
        try:
            value = int(words[0].replace(",", ""))
        except ValueError:
            return None
        if 10 <= value <= 1000000 and value % 10 == 0:
            return value
    # Word form ("one thousand please", "hundred"): the remaining
    # words must be exactly one number-word phrase.
    if words and all(
        w in _NUMBER_WORDS or w in ("a", "an", "and") for w in words
    ):
        value = _number_phrase_value(words)
        if value is not None and 10 <= value <= 1000000 and value % 10 == 0:
            return value
    return None


_ORDER_NOW_PHRASES = (
    "order now", "order it now", "place it now", "place the order now",
    "just place it", "do it now", "order right now",
    "place it right now", "now please", "right now",
)


def is_order_now(text: str) -> bool:
    """True when the user explicitly says to order NOW (owner
    override, 13 Nov 2026): the order is placed at once, no Confirm
    card. A vague 'I want views' is never order-now."""
    s = " ".join((text or "").strip().lower().split())
    return any(p in s for p in _ORDER_NOW_PHRASES)


# Order verbs the local order guard recognises (round 7,
# 13 Nov 2026). Amharic እፈል- covers እፈልጋለሁ/እፈልግ/እፈልጋለች
# ("I want"); ትዕዛዝ/ይዘዝ is "order", ይግዝ is "buy". "please"
# is deliberately NOT here: "please, is this link safe?" is a
# question, not an order.
_ORDER_REQUEST_VERBS = (
    "want", "order", "buy", "get me", "give me", "need",
    "እፈል", "ትዕዛዝ", "ይዘዝ", "ይግዝ",
)
# Intent types the order guard may override: a message that pastes
# a link and names a metric with an order verb IS an order, even
# when the AI called it one of these. Anything more specific
# (usual, batch, recurring, deposit, ...) is left alone.
_ORDER_OVERRIDABLE = (
    "safety", "paxyo_info", "unclear", "off_topic", "goal",
    "content_help", "support_issue", "greeting", "help",
    "refund_policy", "geo_target", "free_sample", "price_pushback",
    "discount",
)


def is_order_request(text: str) -> bool:
    """True when the message itself is an order: it pastes a link (or
    an @handle) and names a metric or platform with an order verb
    ("I want TikTok followers for <link>"). Used to rescue orders
    the AI misclassified (round 7, 13 Nov 2026: that message came
    back as "safety", so the link-mismatch answer never fired in
    that turn and the followers draft leaked into the next one).
    Genuine questions are untouched: a price, ban, payment or
    public-account question is answered by its own check, and a
    message with no order verb ("is this link safe?") is not an
    order."""
    s = " ".join((text or "").strip().lower().split())
    if not s:
        return False
    if (is_price_question(text) or is_ban_question(text)
            or is_pay_methods_question(text) or is_public_question(text)):
        return False
    links = extract_links(text)
    has_target = bool(links) or any(
        tok.startswith("@") and tok.lower() != "@paxyo_bot"
        for tok in s.split()
    )
    if not has_target:
        return False
    if kind_from_text(text) is None and not any(
        p in s.split() for p in _PLATFORM_WORDS
    ):
        return False
    return any(v in s for v in _ORDER_REQUEST_VERBS)


def _empty_intent(intent_type, **fields):
    out = {
        "intent": intent_type, "platform": None, "service_hint": None,
        "service_id": None, "link": None, "quantity": None,
        "interval_minutes": None, "delay_minutes": None, "amount": None,
        "method": None,
        "phone": None, "quantity_multiplier": None, "orders": None,
        "split": None,
    }
    out.update(fields)
    return out


def reply_or_bare_intent(text: str, quoted_text, user_id: int):
    """An intent from a bare-quantity answer or a reply/quote, or
    None. Runs before the classifier, so '1000 please' after 'How
    many?' and '1000' replied TO the bot's 'How many?' message both
    complete the order instead of being misread as a service search.
    A reply only counts when it answers the bot's quantity question;
    a plain message only counts while an order is waiting for its
    quantity. Never fires while a deposit amount or split links are
    awaited."""
    if user_id in DEPOSIT_DRAFT and not (PARTIAL.get(user_id) or {}).get("link"):
        return None
    if user_id in SPLIT_DRAFT:
        return None
    qty = bare_quantity(text)
    if qty is None:
        return None
    stored = PARTIAL.get(user_id) or {}
    if quoted_text is not None:
        q = " ".join(str(quoted_text).strip().lower().split())
        if ("how many" in q or "quantity" in q) and (
            stored.get("link") or stored.get("platform") or stored.get("service_hint")
        ):
            return _empty_intent("order", quantity=qty)
        return None
    if stored.get("quantity"):
        return None
    if stored.get("link") or stored.get("platform") or stored.get("service_hint"):
        return _empty_intent("order", quantity=qty)
    return None


# The link/quantity of the order a user just cancelled (round 6,
# 13 Nov 2026). The order flow drops exactly these values if the
# AI returns them from conversation history after the cancel — and
# only these values. The record clears as soon as the user gives a
# fresh link, or an order is placed (see complete_order).
CANCELLED_DRAFT = {}


def clear_order_state(user_id: int, cancelled=None):
    """Drop everything a cancelled order left behind (round 6,
    13 Nov 2026): the draft being built, any Confirm card still open
    for this user, the budget choice and any fastest-fallback token.
    A fresh order after a cancel starts from scratch — it must not
    auto-show the cancelled order's link and quantity. (The last
    PLACED order is not touched: LAST_ORDER and the server's order
    history still remember it, so "the usual" keeps working.)

    `cancelled` is the Confirm card that was cancelled (its link and
    quantity): it is remembered in CANCELLED_DRAFT so the order flow
    can drop exactly those values if the AI returns them from
    conversation history after the cancel."""
    PARTIAL.pop(user_id, None)
    PARTIAL_ACTIVITY.pop(user_id, None)
    CARD_EDIT_PENDING.pop(user_id, None)
    FRIDAY_LINK.pop(user_id, None)
    BUDGET_OPTIONS.pop(user_id, None)
    for token in [
        t for t, fb in FASTEST_FALLBACK.items()
        if fb.get("user_id") == user_id
    ]:
        FASTEST_FALLBACK.pop(token, None)
    for cid in [
        c for c, p in PENDING.items() if p.get("user_id") == user_id
    ]:
        PENDING.pop(cid, None)
    if cancelled:
        _record = {
            k: cancelled.get(k)
            for k in ("link", "quantity")
            if cancelled.get(k) is not None
        }
        if _record:
            CANCELLED_DRAFT[user_id] = _record


_USUAL_PHRASES = (
    "the usual", "same as yesterday", "same as last", "as usual",
    "my usual",
)


def is_usual_request(text: str) -> bool:
    """True when the user wants their usual order again ('same like
    as usual please order 1k views', 'give me the usual'). The AI
    sometimes reads it as a plain order and the flow then asks for
    the link, even though the last order's link is known — so the
    phrasing is caught locally, before the classifier."""
    s = " ".join((text or "").strip().lower().split())
    return any(p in s for p in _USUAL_PHRASES)


_CANCEL_PHRASES = (
    "cancel", "cancel it", "cancel this", "cancel that",
    "cancel my order", "cancel the order", "cancel this order",
    "cancel please", "cancel my order please",
    "cancel the order please", "never mind", "nevermind",
    "forget it", "stop", "stop it", "stop this", "stop the order",
    "stop my order",
)


def is_cancel_request(text: str) -> bool:
    """True when the message IS a cancel command (\"cancel\", \"I
    don't want to\", \"never mind\", bare \"stop\") — a deterministic
    command the classifier must never misread. A bare \"Cancel\"
    with nothing pending came back from the AI as off_topic and got
    a free-chat continuation (live, 14 Nov 2026 19:10 and 19:29
    EAT — \"no one can guarantee zero risk\", contradicting the
    standing ban answer), so it is caught locally, before the
    classifier, like the usual-request check. Questions ABOUT
    cancelling (\"can I cancel after it starts?\") are not matched:
    the terms answer still handles those, since it runs before the
    cancel branch. \"Cancel my schedule\" is not matched either: the
    classifier routes that to stop_schedule."""
    s = " ".join((text or "").strip().lower().split())
    s = re.sub(r"[.!?]+$", "", s)
    if s in _CANCEL_PHRASES:
        return True
    if "don't want to" in s or "dont want to" in s:
        return True
    if "don't want it" in s or "dont want it" in s:
        return True
    return s.startswith("please cancel")


def is_invite_link_request(text: str) -> bool:
    """True when the message IS an invite-link command ("my invite
    link", "invite link") — a deterministic command the classifier
    must never sit on. Late-reply fix (16 Nov 2026): "my invite
    link" had no fast path at all, so it waited on the AI like any
    free text. Trailing punctuation is stripped, like
    is_cancel_request, so a voice-transcribed "My invite link."
    matches too. Longer messages ("send my invite link to a
    friend") are not matched — they go through the normal flow."""
    s = " ".join((text or "").strip().lower().split())
    s = re.sub(r"[.!?]+$", "", s)
    return s in ("my invite link", "invite link")


# English number words (owner, 14 Nov 2026 — "one thousand" and
# "five hundred" must work like 1000 and 500). There is no Amharic
# number-word handling anywhere in the code, so this is English
# only: Amharic orders still go through the translate bridge, which
# turns "አንድ ሺህ" into "one thousand" before this runs.
_NUMBER_WORD_ONES = {
    "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
    "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
    "eleven": 11, "twelve": 12, "thirteen": 13, "fourteen": 14,
    "fifteen": 15, "sixteen": 16, "seventeen": 17, "eighteen": 18,
    "nineteen": 19,
}
_NUMBER_WORD_TENS = {
    "twenty": 20, "thirty": 30, "forty": 40, "fifty": 50,
    "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90,
}
_NUMBER_WORD_SCALES = {
    "hundred": 100, "hundreds": 100,
    "thousand": 1000, "thousands": 1000,
    "million": 1000000, "millions": 1000000,
}
_NUMBER_WORDS = (
    set(_NUMBER_WORD_ONES) | set(_NUMBER_WORD_TENS)
    | set(_NUMBER_WORD_SCALES)
)


def _number_phrase_value(phrase):
    """Value of one number-word phrase (tokens, in order), or None
    when it is not a number at all. "a"/"an" counts as 1 ("a
    hundred" is 100); "and" is skipped ("one hundred and fifty"
    is 150); a vague plural scale reads as the scale itself
    ("hundreds" is 100)."""
    current = 0
    result = 0
    seen = False
    for w in phrase:
        if w in ("a", "an"):
            current += 1
            seen = True
        elif w in _NUMBER_WORD_ONES:
            current += _NUMBER_WORD_ONES[w]
            seen = True
        elif w in _NUMBER_WORD_TENS:
            current += _NUMBER_WORD_TENS[w]
            seen = True
        elif w in ("hundred", "hundreds"):
            current = (current or 1) * 100
            seen = True
        elif w in ("thousand", "thousands", "million", "millions"):
            result += (current or 1) * _NUMBER_WORD_SCALES[w]
            current = 0
            seen = True
        # "and" is skipped.
    if not seen:
        return None
    return result + current


def _number_word_values(text: str):
    """Values of every English number-word phrase in the text, in
    order ("one thousand five hundred" -> 1500, "a hundred" -> 100,
    "hundreds" -> 100, "two hundred fifty" -> 250). A phrase is a
    maximal run of number words, "a"/"an" as 1 next to a number
    word, and "and" between number words. No quantity filter: "one"
    yields 1 — callers decide what counts."""
    words = re.findall(r"[a-z]+", (text or "").lower())
    values = []
    i = 0
    while i < len(words):
        # A phrase starts at a number word, or at "a"/"an" followed
        # by one ("a hundred", "a thousand"); a bare "a" ("a video")
        # is not a number.
        if words[i] in _NUMBER_WORDS or (
            words[i] in ("a", "an")
            and i + 1 < len(words)
            and words[i + 1] in _NUMBER_WORDS
        ):
            j = i
            phrase = []
            while j < len(words):
                w = words[j]
                if w in _NUMBER_WORDS or w in ("a", "an"):
                    phrase.append(w)
                    j += 1
                elif (
                    w == "and" and phrase
                    and j + 1 < len(words)
                    and words[j + 1] in _NUMBER_WORDS
                ):
                    phrase.append(w)
                    j += 1
                else:
                    break
            value = _number_phrase_value(phrase)
            if value is not None:
                values.append(value)
            i = j
        else:
            i += 1
    return values


def parse_number_words(text: str):
    """First English number-word phrase in the text that is a valid
    quantity (a multiple of 10, 10..1,000,000), or None. "hundreds"
    (vague plural) reads as 100 — the Confirm card shows it, so the
    user can correct it."""
    for value in _number_word_values(text):
        if 10 <= value <= 1000000 and value % 10 == 0:
            return value
    return None


def quantity_from_text(text: str):
    """First number in the message that is a valid quantity (a
    multiple of 10, 10..1,000,000), or None. The text is already
    normalised, so '1k' reads as 1000; number words ('one
    thousand', 'five hundred', 'hundreds') read as quantities too."""
    for m in re.finditer(r"\d[\d,]*", text or ""):
        try:
            value = int(m.group(0).replace(",", ""))
        except ValueError:
            continue
        if 10 <= value <= 1000000 and value % 10 == 0:
            return value
    return parse_number_words(text)


def quantity_before_metric(text: str):
    """Quantity written right before the metric it buys ("200 TikTok
    views", "200 የቲክቶክ እይታዎች"), or None. Only a number
    immediately before the metric counts, so a stray number
    elsewhere in the message ("my balance is 100") is never read as
    the quantity. (Round 7, 13 Nov 2026: "please order now 200
    TikTok views" asked "How many?" because the AI did not return
    the quantity.)"""
    s = text or ""
    am_words = "|".join(
        sorted(_AMHARIC_METRICS, key=len, reverse=True)
    )
    pattern = (
        r"(\d[\d,]*)\s+(?:[^\s]+\s+){0,2}?"
        r"(views?|followers?|likes?|comments?|subscribers?|members?|shares?"
        r"|reactions?"
        r"|" + am_words + r")\b"
    )
    for m in re.finditer(pattern, s, flags=re.IGNORECASE):
        try:
            value = int(m.group(1).replace(",", ""))
        except ValueError:
            continue
        if 10 <= value <= 1000000 and value % 10 == 0:
            return value
    # Word-form quantities right before the metric ("hundred views",
    # "one thousand tiktok views"): a number-word phrase, then up
    # to two filler words, then the metric — the same shape as the
    # digit pattern above.
    tokens = re.findall(r"[a-z]+|[\u1200-\u137c]+", s.lower())
    for idx, tok in enumerate(tokens):
        if _canonical_metric(tok) is None and tok not in _AMHARIC_METRICS:
            continue
        j = idx - 1
        fillers = 0
        while j >= 0 and tokens[j] not in _NUMBER_WORDS and tokens[j] not in ("a", "an", "and"):
            fillers += 1
            if fillers > 2:
                break
            j -= 1
        if fillers > 2 or j < 0:
            continue
        phrase = []
        k = j
        while k >= 0 and (tokens[k] in _NUMBER_WORDS or tokens[k] in ("a", "an", "and")):
            phrase.append(tokens[k])
            k -= 1
        phrase.reverse()
        value = _number_phrase_value(phrase) if phrase else None
        if value is not None and 10 <= value <= 1000000 and value % 10 == 0:
            return value
    return None


# Pay phrasings only (round 6, 13 Nov 2026): "how do I add
# money?" / "how do I deposit?" are deposit-flow entries — the
# existing tests pin them to asking for the amount — so they are
# NOT methods questions and must not be swallowed by this guard.
_PAY_METHODS_PHRASES = (
    "how can i pay", "how do i pay", "how to pay",
    "how can i pay you",
    "how do you accept payment", "how do you take payment",
    "what payment methods", "which payment methods", "payment methods",
)


def is_pay_methods_question(text: str) -> bool:
    """True for a bare how-to-pay question ('how can I pay?'). A
    message that already carries an amount, a method or a phone is
    a deposit in progress, not a question — the deposit flow keeps
    it instead of answering with the methods list."""
    s = " ".join((text or "").strip().lower().split())
    if not any(p in s for p in _PAY_METHODS_PHRASES):
        return False
    if parse_money_amount(s) is not None or parse_deposit_amount(s) is not None:
        return False
    if normalize_method(text) is not None or normalize_phone(text) is not None:
        return False
    return True


_VIDEO_LINK_MARKERS = (
    "/video/", "vt.tiktok.com", "/p/", "/reel", "/shorts/",
    "watch", "youtu.be", "/clip/",
)
_PROFILE_METRICS = ("followers", "members", "subscribers")
_CONTENT_METRICS = ("views", "likes", "comments", "shares")


def link_content_kind(link: str):
    """'video' when the link points at a single post/video,
    'profile' when it points at an account/channel, None when it
    cannot be told (a short link with no recognisable shape)."""
    low = str(link or "").strip().lower()
    if not low:
        return None
    if any(m in low for m in _VIDEO_LINK_MARKERS):
        return "video"
    if "t.me/" in low:
        # t.me/name/123 is a post; t.me/name is a channel.
        tail = low.split("t.me/", 1)[1].strip("/")
        return "video" if "/" in tail and tail.rsplit("/", 1)[1].isdigit() else "profile"
    if any(d in low for d in (
        "tiktok.com", "instagram.com", "youtube.com", "youtu.be",
        "facebook.com", "fb.com", "x.com", "twitter.com",
    )):
        return "profile"
    if low.startswith("@"):
        return "profile"
    return None


def metric_content_kind(service_hint: str):
    """The kind of link a metric needs: 'profile' for followers /
    members / subscribers, 'video' for views / likes / comments /
    shares, None when the hint names no metric."""
    words = (service_hint or "").lower().split()
    if any(w in words for w in _PROFILE_METRICS):
        return "profile"
    if any(w in words for w in _CONTENT_METRICS):
        return "video"
    return None


def _needs_post_link(service_hint: str) -> bool:
    """True when the metric needs a single post, not a channel or
    profile: views, likes, comments, shares, reactions."""
    hint = (service_hint or "").lower()
    if "reaction" in hint:
        return True
    return metric_content_kind(hint) == "video"


def link_story_state(link):
    """'story' / 'post' / None for a link (story/post bug, 16 Nov
    2026): a t.me/<channel>/<number> link is a POST, never a
    story; a /stories/ URL is a story; a Facebook /posts/ URL or
    an Instagram /p/ or /reel/ URL is a post. Anything else is
    unknown (None) — the pick then does not filter on story-ness.
    A tg:// link is not a story or a post: it is unusable as an
    order link at all (see validate_order_link). Pure."""
    low = str(link or "").strip().lower()
    if not low:
        return None
    if "/stories/" in low:
        return "story"
    if "t.me/" in low:
        tail = low.split("t.me/", 1)[1].strip("/")
        if "/" in tail and tail.rsplit("/", 1)[1].isdigit():
            return "post"
        return None
    if "facebook.com" in low or "fb.com" in low:
        if "/posts/" in low:
            return "post"
        return None
    if "instagram.com" in low:
        if "/p/" in low or "/reel" in low:
            return "post"
        return None
    return None


def _story_flag(link, hint=None, explicit=None):
    """True / False / None for a reactions pick (story/post bug,
    16 Nov 2026): an explicit draft flag wins; else the link's
    state; else a hint that says "story" (the user asked for
    story reactions with no link yet). None means unknown — the
    pool is not filtered. Pure."""
    if explicit is not None:
        return bool(explicit)
    state = link_story_state(link)
    if state == "story":
        return True
    if state == "post":
        return False
    if hint and "story" in str(hint).lower():
        return True
    return None


def validate_order_link(link, service):
    """Link check before paying (cancel-cutting item 5, 16 Nov
    2026): the link's domain must match the service's platform,
    and the link type must match the metric — followers /
    subscribers / members need a profile/channel link, views /
    likes / comments / shares / reactions need a post/video
    link. Returns None when the link fits, else "platform" (the
    domain is another platform's) or "link_type" (a profile link
    for a post metric, or a post link for a profile metric).
    Conservative by design: when either side cannot be told (no
    recognisable platform in the service name, no recognisable
    shape in the link), the link passes — an unknown shape never
    blocks an order. No live profile fetching, ever. Pure: no
    network, no state."""
    if not link or not service:
        return None
    if str(link).strip().lower().startswith("tg://"):
        # A tg://openmessage deep link is a client-side link, not
        # a post URL the provider can open — never an order link
        # (story/post bug, 16 Nov 2026).
        return "link_type"
    platform, hint = _platform_hint_of_service(service)
    link_platform = platform_from_link(link)
    if platform and link_platform and link_platform != platform:
        return "platform"
    need = metric_content_kind(hint or "")
    if need is None and "reaction" in (hint or "").lower():
        # Reactions are a content metric, but the word is not in
        # _CONTENT_METRICS — a reaction service always needs a
        # post link.
        need = "video"
    if need is None:
        return None
    got = link_content_kind(link)
    if got is not None and got != need:
        return "link_type"
    return None


def _same_link(a: str, b: str) -> bool:
    """Same link up to scheme, www, query string and a trailing
    slash — the AI sometimes normalises the link it returns."""
    def _norm(u):
        u = str(u or "").strip().lower()
        u = re.sub(r"^https?://", "", u)
        u = re.sub(r"^www\.", "", u)
        return u.split("?")[0].rstrip("/")
    return bool(a) and bool(b) and _norm(a) == _norm(b)


def _link_grounded_in_text(text: str, link) -> bool:
    """True when the link the intent carries is actually in this
    message (pasted just now), not pulled from an older turn."""
    if not link:
        return False
    for candidate in extract_links(text):
        if _same_link(candidate, link):
            return True
    # A handle target (@user) is grounded by an @-mention in the text.
    if str(link).startswith("@"):
        return any(tok.startswith("@") for tok in (text or "").split())
    return False


def _quantity_grounded_in_text(text: str, quantity) -> bool:
    """True when the quantity the intent carries is a number in this
    message (the text is already normalised, so '1k' reads as 1000)."""
    try:
        wanted = int(quantity)
    except (TypeError, ValueError):
        return False
    for m in re.finditer(r"\d[\d,]*", text or ""):
        try:
            if int(m.group(0).replace(",", "")) == wanted:
                return True
        except ValueError:
            continue
    # Word form too ("hundred views" grounds quantity 100).
    return wanted in _number_word_values(text)


# Question phrasing for a cheapest question: "what is the
# cheapest tiktok views", "which is the cheapest", "tell me the
# cheapest". A bare "cheapest <platform> <metric>" with no
# question words is a price question too (the owner asked for
# those variants); anything else after "cheapest" ("is it fast?",
# "for me") is not.
_CHEAPEST_QUESTION_WORDS = (
    "what is", "what's", "whats", "what are", "which is",
    "which are", "which one", "how much", "how many",
    "tell me", "show me",
)
# Words a bare cheapest phrase may contain, besides the cheapest
# word itself: platforms, metrics (singular and plural), the words
# of every multi-word kind ("live", "viewers", "story", "bot",
# "start", ...), and politeness fillers. "comment" covers "comment
# likes". "private"/"channel" cover the MAX private-channel line.
_CHEAPEST_BARE_WORDS = frozenset(
    {"cheapest", "lowest", "the", "a", "an", "please", "pls"}
    | set(_PLATFORMS)
    | set(_PLATFORM_WORDS)
    | set(_METRICS)
    | {m[:-1] for m in _METRICS}
    | {w for phrase, _k in _MULTIWORD_KINDS for w in phrase.split()}
    | {"watch", "watchhour", "watchhours", "watchtime",
       "hour", "hours", "time", "private", "channel", "dm", "mass"}
)


def is_cheapest_question(text: str) -> bool:
    """True when the user asks what the cheapest service costs
    ("what is the cheapest tiktok views", "cheapest views") — a
    price question, never an order. Live fault, 15 Nov 2026: the
    bot answered that exact question with "Please send the link
    of the video", because is_price_question only knew "price",
    "cost", "rate" and "how much" — "cheapest" fell through to
    the classifier, which called it an order. An order verb, a
    quantity, or a link makes it an order instead ("order 1000
    cheapest Instagram followers", "I want the cheapest tiktok
    views", "1000 cheapest tiktok views", "cheapest views for
    <link>"). A bare "the cheapest one" names no platform or
    metric, so it stays a service choice inside the order being
    built."""
    s = " ".join(normalize_text(text or "").lower().split())
    if not s:
        return False
    words = re.findall(r"[a-z]+", s)
    word_set = set(words)
    if not word_set & {"cheapest", "lowest"}:
        return False
    if extract_links(text):
        return False
    if any(v in s for v in _ORDER_REQUEST_VERBS):
        return False
    # The gate (service-types inventory §6.5): the old check used
    # _PLATFORMS, which holds "x" but not the word "twitter" the
    # user typed — so "cheapest twitter retweets" failed here while
    # "cheapest x retweets" failed in detect_platform_metric
    # instead. Both sides now use the same word set.
    if kind_from_text(s) is None and not (
        any(w in word_set for w in _PLATFORM_WORDS)
        or "private channel" in s
    ):
        return False
    if any(q in s for q in _CHEAPEST_QUESTION_WORDS):
        return True
    if quantity_from_text(s) is not None:
        return False
    # Bare form: every word must be a platform, metric, kind or
    # cheapest word — "is the cheapest tiktok views fast?" is a
    # speed question about the cheapest service, not a price
    # question. _CHEAPEST_BARE_WORDS is built from the full
    # platform/metric/kind tables, so new types pass it without a
    # kind shortcut.
    return word_set <= _CHEAPEST_BARE_WORDS


def is_price_question(text: str) -> bool:
    """True when the user asks the price of a service ('how much are
    tiktok views?', "what's the price of 1000 views?"). A cheapest
    question ('what is the cheapest tiktok views') counts too — see
    is_cheapest_question. A budget
    ('how much views can 10 br get me') carries a currency amount
    and is not a price question; neither is a balance or a deposit
    question. A pasted link is not a price question only when the
    message also has an order verb ("I want 1000 views for
    <link>") — a link with a bare price question ("how much for
    1000 views on this <link>?") still is one. Shapes the owner
    hit live (14 Nov 2026): "what's the rate", "how much for
    1000" (no platform named), "how much is it", and Amharic
    (ዋጋ is price, ስንት is how much) when the translate bridge
    fails and the Ge'ez text reaches this detector unchanged."""
    s = " ".join(normalize_text(text or "").split())
    if extract_links(text) and any(
        v in s for v in _ORDER_REQUEST_VERBS
    ):
        return False
    if parse_money_amount(s) is not None:
        return False
    if "deposit" in s or "balance" in s:
        return False
    if "price" in s or "cost" in s:
        return True
    if any(w in s.split() for w in ("rate", "rates", "pricing", "charge", "charges")):
        return True
    if "ዋጋ" in s:
        return True
    if "ስንት" in s and (
        kind_from_text(text) is not None
        or any(p in s.split() for p in _PLATFORM_WORDS)
    ):
        return True
    if "how much" in s and (
        kind_from_text(s) is not None
        or any(p in s.split() for p in _PLATFORM_WORDS)
        or re.search(r"\d", s) is not None
        # Word-boundary match: "how much is it?" ends in "it?",
        # and a split() comparison ("it" != "it?") misses it.
        or re.search(r"\b(it|this|that|one|them)\b", s) is not None
    ):
        return True
    # "Cheapest" is a price question too (live fault, 15 Nov 2026):
    # "what is the cheapest tiktok views" asked for a price and
    # got "Please send the link of the video" instead, because
    # none of the words above match "cheapest".
    if is_cheapest_question(text):
        return True
    return False


def _service_price_line(service, quantity, lang: str) -> str:
    """The deterministic price line for one service, straight from
    the catalogue: "Thumbs up 👍: 5.46 ETB for 1,000 (5.46 ETB per
    1000)." when a quantity was asked for, else the per-1000 rate."""
    rate = float(service.get("rate_etb_per_1000", 0) or 0)
    name = short_service_name(service.get("name"))
    if quantity is not None:
        try:
            qty = int(quantity)
        except (TypeError, ValueError):
            qty = None
        if qty:
            return t(
                "price_total", lang, service=name, quantity=f"{qty:,}",
                rate=format_money(rate),
                total=format_money(estimated_total_etb(rate, qty)),
            )
    return t(
        "price_per_1000", lang, service=name, rate=format_money(rate)
    )


async def _price_line(user_id: int, text: str, platform, hint, quantity,
                      lang: str, reaction_emoji=None, services=None):
    """The deterministic price line for an identified service, straight
    from the catalogue (rate x420 ETB): "Thumbs up 👍: 5.46 ETB for
    1,000 (5.46 ETB per 1000)." when a quantity was asked for, else
    the per-1000 rate. Returns (line, platform, hint, service) — line
    is None when no service can be named, and platform/hint are the
    values actually used, after falling back to the order in progress
    and then to the message itself. `service` is the service the line
    quotes, or None: the caller remembers it as the quoted service,
    so the next order for the same platform+metric is charged on
    that exact service (19:28 EAT 16 Nov 2026). Short service names
    only, like everywhere else. The caller decides what None means:
    price_answer_text asks which service; the link-ask safety net
    just skips the line."""
    platform = (platform or "").strip().lower() or None
    if not platform and not hint:
        platform, hint = _conversation_context(user_id)
    if not platform and hint:
        # A price question that names a metric but no platform
        # ("how much are the views?") is about the order being
        # built, not the fastest views service on any platform —
        # take the platform from the pending order or the draft.
        _ctx_platform, _ctx_hint = _conversation_context(user_id)
        if _ctx_platform:
            platform = _ctx_platform
    if not platform and not hint:
        words = set(re.findall(r"[a-z]+", normalize_text(text).lower()))
        platform = _platform_from_words(words, text)
        metric = kind_from_text(text)
        hint = " ".join(p for p in (platform, metric) if p) or None
    if not platform and not hint:
        return None, platform, hint, None
    if services is None:
        try:
            services = await paxyo.services()
        except Exception as exc:
            log.warning("price lookup failed: %s", exc)
            return None, platform, hint, None
    picks = pick_services(
        services, platform=platform, service_hint=hint, limit=100,
        reaction_emoji=reaction_emoji,
    )
    if not picks:
        return None, platform, hint, None
    return _service_price_line(picks[0], quantity, lang), platform, hint, picks[0]


def no_service_reply(platform, hint, text, lang):
    """The honest 'we don't have that' line for a known-empty
    type, or None when there is no specific case (the caller keeps
    its generic no-service line). Telegram followers, channel
    joins, YouTube engagement package, Shopee plain views,
    YouTube auto views, and reaction words with no dedicated
    service — the bot names the missing thing and the closest real
    thing instead of a silent guess or a different product
    (service-types inventory §5, 15 Nov 2026)."""
    plat = (platform or "").strip().lower() or None
    kind = kind_from_text(hint or "") or kind_from_text(text or "")
    words = set(re.findall(r"[a-z]+", ((hint or "") + " " + (text or "")).lower()))
    if plat is None:
        plat, _k = detect_platform_metric(text or "")
    if plat == "telegram" and kind == "followers":
        return t("no_telegram_followers", lang)
    if "join" in words or "joins" in words:
        return t("no_channel_joins", lang)
    if plat == "youtube" and kind == "engagement package":
        return t("no_youtube_engagement_package", lang)
    if plat == "shopee" and kind == "views":
        return t("no_shopee_views", lang)
    if plat == "youtube" and kind == "auto views":
        return t("no_youtube_auto_views", lang)
    if kind == "reactions":
        emoji = reaction_emoji(text or "") or reaction_emoji(hint or "")
        if emoji is not None:
            return t("no_exact_reaction", lang, emoji=emoji)
    if plat and kind:
        disp = _PLATFORM_DISPLAY.get(
            plat,
            "Website traffic" if plat == "website-traffic" else plat.title(),
        )
        return t("no_service_type", lang, platform=disp, kind=kind)
    return None


def _remember_quote(user_id: int, service, platform, hint):
    """Remember the service a price answer just quoted, so the next
    order for the same platform+metric is charged on that exact
    service at that exact price (19:28 EAT 16 Nov 2026: a user
    quoted 1.6 ETB was handed a 1,118.04 ETB traffic service). The
    quote is only a pin for the same platform+metric — complete_order
    re-resolves the service from the live catalogue and checks it is
    still orderable before using it. A platform-less quote is still
    stored (the pin needs a platform to match, so it simply never
    fires for one)."""
    if not service:
        return
    metric = kind_from_text(hint or "") or kind_from_text(
        f"{service.get('name') or ''} {service.get('category') or ''}"
    )
    QUOTED_SERVICE[int(user_id)] = {
        "combined_id": service_combined_id(service),
        "platform": (platform or "").strip().lower() or None,
        "metric": metric,
        "price": float(service.get("rate_etb_per_1000") or 0),
    }


async def price_answer_text(user_id: int, text: str, intent: dict, lang: str):
    """The price, straight from the catalogue: ETB per 1000, and the
    total when a quantity was asked for. Never asks for the link
    first. Always answers a price question with a price line, the cheapest price for the platform/metric, or
    the ask-which-service line — never None once the catalogue is
    fetched (owner, 14 Nov 2026: a price question that fell
    through to a free AI reply got no price at all, because the
    free-answer prompts forbid quoting prices). None only when the
    catalogue itself cannot be fetched, so the caller falls through
    to the classifier and retries — the flaky-lookup tests pin the
    fetch count, so this fetches exactly once per call."""
    platform = (intent.get("platform") or "").strip().lower() or None
    hint = intent.get("service_hint")
    quantity = intent.get("quantity")
    if not platform and not hint:
        # The AI classifier returns nothing usable for new types
        # ("private channel ...", new platforms): read the message
        # deterministically instead of answering blind.
        _dplat, _dmetric = detect_platform_metric(text)
        if _dplat:
            platform = _dplat
            hint = " ".join(p for p in (_dplat, _dmetric) if p) or None
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("price lookup failed: %s", exc)
        return None
    # Stale-price fix (16 Nov 2026): a bare price question ("how
    # much is the price") names no service itself — the classifier
    # may carry the platform/metric forward from an earlier
    # conversation, and answering from that stale hint quotes the
    # WRONG service (live fault: a TikTok views order got the old
    # Telegram Reactions price, 37.80 ETB/1000). When the message
    # itself names no platform or metric, the price comes from the
    # CURRENT draft (the order being built, or the open Confirm
    # card) — never from the classifier's carried-forward hint.
    # With no current draft either, ask which service instead of
    # guessing an old one.
    _own_platform, _own_metric = detect_platform_metric(text)
    _context_metric_only = False
    if _own_platform is None and _own_metric is None:
        platform, hint = _conversation_context(user_id)
        if not platform and not hint:
            return t("price_ask_service", lang)
        if not platform and hint:
            # The question names nothing itself — it is about the
            # order being built, whose metric is known but whose
            # platform is not (see the guard below).
            _context_metric_only = True
    _links = extract_links(text)
    if _links:
        # One-line price check (ideas batch 1 #2, 16 Nov 2026): a
        # link + a price word answers the cheapest price for THAT
        # link — the metric comes from the link's shape (a video
        # link is views, a profile link is followers, a YouTube
        # channel link is subscribers), never the fastest service
        # of any metric on the platform (live fault: a TikTok video
        # link + "how much" answered the Video Save price, 2.10,
        # because Save is the fastest TikTok service). A metric the
        # message itself names always wins over the link-derived
        # one. No draft is started and "How many?" is never asked:
        # a price question never starts an order.
        _kind = link_content_kind(_links[0])
        _derived = None
        if _kind == "video":
            _derived = "views"
        elif _kind == "profile":
            _derived = (
                "subscribers" if platform == "youtube" else "followers"
            )
        if _derived and not kind_from_text(hint or ""):
            hint = " ".join(
                p for p in (platform, _derived) if p
            ) or hint
            _cheapest = cheapest_service(
                services, platform=platform, service_hint=hint
            )
            if _cheapest is not None:
                _remember_quote(user_id, _cheapest, platform, hint)
                return _service_price_line(_cheapest, quantity, lang)
    if is_cheapest_question(text):
        # A cheapest question is answered from the cheapest
        # service, not the fastest pick: the fastest TikTok views
        # service is 18.90 ETB/1000 while the cheapest is 1.26 —
        # quoting the fastest for "what is the cheapest" is the
        # wrong price (live fault, 15 Nov 2026). cheapest_service
        # forces the cheapest ranking, so this is the true global
        # cheapest. No draft is seeded here: a price question
        # never starts an order.
        cheapest = cheapest_service(
            services, platform=platform, service_hint=hint
        )
        if cheapest is not None:
            _remember_quote(user_id, cheapest, platform, hint)
            return _service_price_line(cheapest, quantity, lang)
    if _context_metric_only:
        # Wrong-platform guard (17 Nov 2026): the price question
        # names nothing itself, so it is about the order being
        # built — but that draft has a metric and no platform.
        # Quoting the fastest service for the metric would pick
        # it on ANY platform (live fault: Facebook Followers
        # 87.43 was quoted for an X/Twitter followers order).
        # Ask which service instead. Genuine global-cheapest
        # questions already returned above, and a question that
        # names its own metric (or a draft with a platform)
        # never sets this flag.
        return t("price_ask_service", lang)
    line, platform, hint, _quoted = await _price_line(
        user_id, text, platform, hint, quantity, lang,
        reaction_emoji=reaction_emoji(text), services=services,
    )
    if line is None and (platform or hint):
        # No fastest pick for this platform/metric: offer the
        # cheapest price for it instead of silence.
        cheapest = cheapest_service(
            services, platform=platform, service_hint=hint
        )
        if cheapest is not None:
            line = _service_price_line(cheapest, quantity, lang)
            _remember_quote(user_id, cheapest, platform, hint)
    if line is not None:
        if _quoted is not None:
            _remember_quote(user_id, _quoted, platform, hint)
        if quantity is not None:
            try:
                qty = int(quantity)
            except (TypeError, ValueError):
                qty = None
            if qty:
                _remember_price_question(user_id, platform, hint, qty, text)
        return line
    if platform or hint:
        # A known type with no service at all: say so honestly
        # instead of asking which service.
        honest = no_service_reply(platform, hint, text, lang)
        if honest is not None:
            return honest
    return t("price_ask_service", lang)


def _remember_price_question(user_id: int, platform, hint, qty, text):
    """Remember what a price question asked about, in the draft
    (round 8.1, 14 Nov 2026): "how much 1k" names the quantity
    for the order being built, so the next turn — and the "do you
    understand" restatement — must not ask "how many" again. Only
    when no Confirm card is pending and the draft has no link (a
    price question never hijacks an order already being built). A
    different metric replaces a link-less draft, the same as a new
    order does (round 7). When the draft DOES have a link, the
    quantity is still remembered when the question is about that
    same order (same platform and metric): a follow-up drip version
    of this order derives its runs from it (19 Nov 2026). A
    question about a different platform or metric never touches
    the linked draft."""
    _cid, pending = pending_for_user(user_id)
    if pending is not None:
        return
    stored = PARTIAL.get(user_id) or {}
    if stored.get("link"):
        stored_platform = (stored.get("platform") or "").strip().lower()
        new_platform = (platform or "").strip().lower()
        if new_platform and stored_platform and new_platform != stored_platform:
            return
        stored_metric = _primary_metric(
            kind_from_text(stored.get("service_hint") or "")
        )
        new_metric = _primary_metric(kind_from_text(hint or ""))
        if (
            stored_metric is not None
            and new_metric is not None
            and stored_metric != new_metric
        ):
            return
        merged = {k: v for k, v in stored.items() if v is not None}
        merged["quantity"] = qty
        if platform and not merged.get("platform"):
            merged["platform"] = platform
        if hint and not merged.get("service_hint"):
            merged["service_hint"] = hint
        PARTIAL[user_id] = merged
        return
    stored_metric = _primary_metric(kind_from_text(stored.get("service_hint") or ""))
    new_metric = _primary_metric(kind_from_text(hint or ""))
    if not stored or stored_metric is None or stored_metric == new_metric:
        merged = {k: v for k, v in stored.items() if v is not None}
        merged.update({
            "platform": platform, "service_hint": hint, "quantity": qty,
            "reaction_emoji": reaction_emoji(text) or stored.get("reaction_emoji"),
        })
        PARTIAL[user_id] = {k: v for k, v in merged.items() if v is not None}
    else:
        PARTIAL[user_id] = {
            "platform": platform, "service_hint": hint, "quantity": qty,
            "reaction_emoji": reaction_emoji(text),
        }


def is_ban_question(text: str) -> bool:
    """True when the user asks about bans / shadowbans.

    English is matched on Latin words — but the detector also
    runs on the RAW text when the translate bridge is down
    (Gemini's free tier is 20/day, so an Amharic question often
    reaches this check untranslated), so Ge'ez and Oromo ban
    words are matched too. Live bug, 14 Nov 2026: the Amharic
    question "ተከታዮችን በመግዛት አካውንቴ ሊታገድ ይችላል?" got a
    free AI answer saying "no one can guarantee zero risk"
    instead of the deterministic NO — the detector saw no Latin
    ban word. The Ge'ez ban verb is ታገደ: "ሊታገድ" (may be
    banned), "ታገደ" (was banned), "ይታገዳል" (is being banned),
    "ታግዷል" (has been banned), "ታግደዋል" (have been banned),
    "እገዳ" (a ban) — the same root in Tigrinya. The stems are
    matched exactly ("ታገ" alone would also catch ታገሠ,
    patience), so every real inflection is listed. Oromo:
    "cufamuu" (to be closed/shut), "dhoowwaa" (prohibition)."""
    words = set(re.findall(r"[a-z]+", (text or "").lower()))
    if (
        words & {"ban", "banned", "banning", "shadowban", "shadowbanned"}
        or ("shadow" in words and "ban" in words)
    ):
        return True
    geez = re.findall(r"[\u1200-\u137c]+", text or "")
    if any(
        part in word
        for word in geez
        for part in (
            "ታገድ", "ታገደ", "ታገዳ", "ታግዷ", "ታግደ", "እገዳ",
        )
    ):
        return True
    if any(
        word == "ባን" for word in geez
    ):
        return True
    if any(
        word.startswith(prefix)
        for word in words
        for prefix in ("cufam", "dhooww")
    ):
        return True
    return False


def is_public_question(text: str) -> bool:
    """True when the user asks whether their account must be public."""
    s = " ".join((text or "").strip().lower().split())
    return ("public" in s or "private" in s) and (
        "account" in s or "profile" in s or "need" in s or "must" in s
        or "have to" in s
    )


def is_history_question(text: str) -> bool:
    """True when the user asks what they talked about before."""
    s = " ".join((text or "").strip().lower().split())
    return any(p in s for p in (
        "what did i ask", "what did i say", "what did we talk about",
        "what was my last", "do you remember", "what did i order before",
        "what did i ask about before", "what did i talk about",
    ))


_QUESTION_OPENERS = (
    "how", "what", "where", "when", "why", "who", "whom", "whose",
    "which", "can", "could", "should", "would", "do", "does", "did",
    "is", "are", "was", "were", "will", "have", "has",
)


def is_question(text: str) -> bool:
    """True when the message is shaped like a question: it ends
    with '?' or opens with a question word. A question always
    gets a free AI answer (owner, 14 Nov 2026) — it is never
    steered away unanswered, however many turns it takes."""
    s = " ".join((text or "").strip().lower().split())
    if not s:
        return False
    if s.endswith("?"):
        return True
    return s.split(" ", 1)[0] in _QUESTION_OPENERS


def is_comment_likes_question(text: str) -> bool:
    """True when the user asks what the bot needs for likes on a
    comment (owner, 14 Nov 2026): the link of the video/post the
    comment is on, plus either the comment's own link or the
    username. An actual order (a link is pasted) is never a
    question — the order flow keeps it."""
    if extract_links(text):
        return False
    s = " ".join((text or "").strip().lower().split())
    if "comment" not in s or "like" not in s:
        return False
    return (
        "how" in s or "what" in s or "need" in s or "do i" in s
        or "?" in (text or "")
    )


def is_telegram_post_link_question(text: str) -> bool:
    """True when the user asks how to get the link of a Telegram
    post (owner, 14 Nov 2026): "how do I get the link of a
    Telegram post?", "how to copy a telegram post link". A
    deterministic Paxyo fact — the AI kept getting the steps
    wrong ("click the post and click copy link" skips the share
    step; "right-click" is useless on a phone), so the answer is
    a template, never a free reply. A comment-link question
    ("link of a comment") is not a post-link question, and a
    channel-link question ("link of my channel") is not one
    either."""
    s = " ".join((text or "").strip().lower().split())
    has_telegram = (
        "telegram" in s or "ቴሌግራም" in s or " tg " in f" {s} "
    )
    has_link = "link" in s or "ሊንክ" in s
    has_post = "post" in s or "ፖስት" in s
    has_how = "how" in s.split() or "እንዴት" in s or "እንደምን" in s
    return has_telegram and has_link and has_post and has_how


async def speed_answer_text(user_id: int, text: str, intent: dict, lang: str):
    """A REAL delivery-time answer for a speed question (owner,
    13 Nov 2026): the pending Confirm card's service first (round
    4), else the fastest service for the platform+metric in the
    message, else the no-time line with the order-now nudge. The
    vague 'shown before you confirm / varies by service' line is
    never used."""
    _cid, pending = pending_for_user(user_id)
    if pending is not None:
        answer = pending_confirm_answer(pending.get("service"), "speed", lang)
        if answer is not None:
            return answer
    platform = (intent.get("platform") or "").strip().lower() or None
    hint = intent.get("service_hint")
    if not platform and not hint:
        platform, hint = _conversation_context(user_id)
    if not platform and not hint:
        words = set(re.findall(r"[a-z]+", normalize_text(text).lower()))
        platform = _platform_from_words(words, text)
        metric = kind_from_text(text)
        hint = " ".join(p for p in (platform, metric) if p) or None
    if not platform and not hint:
        return t("speed_unknown", lang)
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("speed lookup failed: %s", exc)
        return t("speed_unknown", lang)
    picks = pick_services(
        services, platform=platform, service_hint=hint, limit=100,
        reaction_emoji=reaction_emoji(text),
    )
    if not picks:
        return t("speed_unknown", lang)
    service = picks[0]
    avg = service.get("average_time")
    if parse_average_time(avg) is not None:
        return t(
            "speed_answer", lang,
            service=short_service_name(service.get("name")), avg=avg,
        )
    return t("speed_unknown", lang)


_ORDER_STATUS_ICONS = {
    "completed": "✅", "pending": "⏳", "in_progress": "⏳",
    "processing": "⏳", "cancelled": "❌", "canceled": "❌",
    "refunded": "❌", "failed": "❌",
}


async def orders_history_text(user_id: int, lang: str,
                              platform: str = None) -> str:
    """The user's LAST 5 orders only (owner, 14 Nov 2026 — the
    20-row monospace table was ugly and confusing on a phone):
    one line per order — ID, short service name, quantity, status
    with an icon, total in ETB. Newest first. No extra fields,
    no long text, no monospace block that wraps badly.

    My orders by platform (ideas batch 1 #6, 16 Nov 2026):
    `platform` filters the list to that platform only ("Show my
    TikTok orders"), read from each order's service name — no
    catalogue fetch. No orders on that platform says so plainly
    instead of showing another platform's orders."""
    platform = (platform or "").strip().lower() or None
    try:
        orders = await paxyo.recent_orders(user_id, limit=5)
    except Exception as exc:
        log.warning("orders history failed: %s", exc)
        return t("not_understood", lang)
    if not orders:
        if platform:
            disp = _PLATFORM_DISPLAY.get(platform, platform.title())
            return t(
                "orders_history_empty_platform", lang, platform=disp
            )
        # The API has nothing, but this session placed an order
        # (tracked in memory): show its status line.
        return await last_order_status_text(user_id, lang)
    if platform:
        disp = _PLATFORM_DISPLAY.get(platform, platform.title())
        orders = [
            o for o in orders
            if _platform_hint_of_service(
                {"name": o.get("service_name") or ""}
            )[0] == platform
        ]
        if not orders:
            return t(
                "orders_history_empty_platform", lang, platform=disp
            )
        lines = [t(
            "orders_history_title_platform", lang, platform=disp
        )]
    else:
        lines = [t("orders_history_title", lang)]
    for o in orders[:5]:
        status = str(o.get("status") or "?").strip().lower()
        icon = _ORDER_STATUS_ICONS.get(status, "ℹ️")
        name = short_service_name(o.get("service_name") or "") or f"service {o.get('service_id')}"
        lines.append(
            f"#{o.get('id') or o.get('order_id') or '?'} {name} "
            f"×{int(o.get('quantity') or 0)}, {icon} {status}, "
            f"{format_money(o.get('charge', 0) or 0)} ETB"
        )
    return "\n".join(lines)


def terms_answer(text: str, lang: str):
    """An answer from Paxyo's Terms & Conditions (paxyo-terms.md),
    or None when the message is not a terms question. Never invents
    a term: an uncovered terms question says so and offers support."""
    s = " ".join((text or "").strip().lower().split())
    about_terms = "term" in s or "condition" in s
    if any(p in s for p in ("show me the terms", "full terms", "read the terms", "terms and conditions", "terms & conditions")):
        return t("terms_full", lang)
    if "refund" in s or "money back" in s or "get my money back" in s:
        return t("terms_refund", lang)
    if "cancel" in s and any(p in s for p in ("after", "start", "processing", "placed", "begun")):
        return t("terms_cancel", lang)
    if any(p in s for p in ("privacy", "my data", "personal data", "sell my data")):
        return t("terms_privacy", lang)
    if any(p in s for p in ("suspend", "suspended", "terminat")):
        return t("terms_suspension", lang)
    if "public" in s and "account" in s:
        return t("public_answer", lang)
    if about_terms:
        return t("terms_not_covered", lang)
    return None


async def place_order_now(message, user_id: int, merged: dict, lang: str,
                          named_service_id=None, last_service_id=None,
                          note: str = None, show_full_name: bool = False) -> bool:
    """Place a fully-specified order at once, no Confirm card
    (owner override, 13 Nov 2026 — explicit 'order now' only).
    Returns True when the user got an answer (placed, or a plain
    failure line); False when nothing could be placed yet, so the
    caller falls through to the normal Confirm card. An ambiguous
    metric is never guessed: False, and the normal flow asks."""
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("order-now services failed: %s", exc)
        return False
    service = None
    if named_service_id is not None:
        service, svc_error = resolve_named_service(services, named_service_id)
        if svc_error is not None:
            return False
        # Cancel-cutting item 2 (16 Nov 2026): a service the user
        # named that is auto-paused right now is never placed on
        # at once — False falls through to the normal Confirm
        # card, which says plainly it is paused and offers the
        # fastest one instead.
        _paused_now = await _cached_paused_services()
        if _paused_now is not None and service_combined_id(service) in _paused_now:
            return False
    if service is None:
        # Cancel-cutting (16 Nov 2026): the order-now pick rides
        # the merged ranking too (trusted first, unreliable /
        # paused / low-balance-provider services skipped).
        _rel, _paused, _health = await _pick_context()
        picks = pick_services(
            services, platform=merged.get("platform"),
            service_hint=merged.get("service_hint"),
            reaction_emoji=merged.get("reaction_emoji"),
            reliability=_rel, paused=_paused, balance_health=_health,
            quantity=merged.get("quantity"),
            story=_story_flag(
                merged.get("link"), merged.get("service_hint")
            ),
        )
        if not picks:
            return False
        if not merged.get("service_hint"):
            metrics = []
            for pick in picks[:3]:
                found = _primary_kind(
                    pick.get("name"), pick.get("category")
                )
                if found and found not in metrics:
                    metrics.append(found)
            if len(metrics) > 1:
                return False
        service = picks[0]
    error = validate_quantity(merged.get("quantity"), service)
    if error:
        return False
    quantity = int(merged["quantity"])
    total = estimated_total_etb(float(service.get("rate_etb_per_1000", 0)), quantity)
    pending = {
        "user_id": user_id, "service": service, "link": merged["link"],
        "quantity": quantity, "total": total,
        "full_name": show_full_name,
    }
    PARTIAL.pop(user_id, None)
    # A complete order was placed: the cancelled draft is history now.
    CANCELLED_DRAFT.pop(user_id, None)
    await send_order_result(message, lang, pending, user_id)
    return True


# A single deposit over this is refused in one line.
MAX_DEPOSIT_ETB = 100000


async def resolve_last_order(user_id: int):
    """The user's most recent order from the Paxyo API, or None.

    This is the bot's durable memory of the last link: it lives in
    Paxyo's orders table, so it survives bot restarts. Returns None
    when the user has no orders or the endpoint is not live yet.
    """
    try:
        orders = await paxyo.recent_orders(user_id, limit=5)
    except Exception as exc:
        log.warning("recent_orders failed: %s", exc)
        return None
    if not orders:
        return None
    return orders[0]


_LINK_RECALL_PHRASES = (
    "link of the last order", "link of my last order",
    "link of the previous order", "link of the latest order",
    "link of my order", "link of that order",
    "send me the link of", "what was the link of",
    "what is the link of", "give me the link of",
    "link for the last order", "link from my last order",
)


def is_link_recall_question(text: str) -> bool:
    """A request for the LINK of a past order (owner, 14 Nov
    2026) — \"please send me the link of the last order about
    the Telegram reaction\" — as opposed to a request for the
    link of the order being built. The \"link of\" phrasing is
    what separates the two: the order flow says \"send the link\"
    with no \"of\"."""
    s = " ".join((text or "").strip().lower().split())
    if "link" not in s:
        return False
    return any(p in s for p in _LINK_RECALL_PHRASES)


def _match_recall_order(orders, text):
    """The most recent order matching what the user named: the
    platform and the kind, when either is named. No type named
    means the single most recent order. Returns None when
    nothing matches."""
    words = set(re.findall(r"[a-z]+", (text or "").lower()))
    platform = _platform_from_words(words, text)
    metric = kind_from_text(text)
    for order in orders:
        o_platform, _hint = _platform_hint_of_service(
            {"name": order.get("service_name") or ""}
        )
        o_kind = kind_from_text(order.get("service_name") or "")
        if platform is not None and o_platform != platform:
            continue
        if metric is not None and o_kind != metric:
            continue
        return order
    return None


def _recall_desc(text):
    """The words describing the order the user asked about
    (\"Telegram reactions \", \"Instagram followers \", or \"\"
    when no type was named), for the recall reply."""
    words = set(re.findall(r"[a-z]+", (text or "").lower()))
    platform = _platform_from_words(words, text)
    metric = kind_from_text(text)
    parts = []
    if platform:
        parts.append(_PLATFORM_DISPLAY.get(platform, platform.title()))
    if metric:
        parts.append(metric)
    return (" ".join(parts) + " ") if parts else ""


async def link_recall_text(user_id: int, text: str, lang: str):
    """The link of a past order (owner, 14 Nov 2026). The API's
    GET /orders list DOES return the link for each order, so the
    bot answers with the actual link of the most recent matching
    order. When no order matches, or the order has no link
    saved, it says so honestly — it never invents a link."""
    try:
        orders = await paxyo.recent_orders(user_id, limit=5)
    except Exception as exc:
        log.warning("link recall recent_orders failed: %s", exc)
        return t("not_understood", lang)
    if not orders:
        return t("link_recall_none", lang)
    desc = _recall_desc(text)
    order = _match_recall_order(orders, text)
    if order is None:
        return t("link_recall_no_match", lang, desc=desc)
    link = (order.get("link") or "").strip()
    if not link:
        return t("link_recall_no_link", lang)
    return t("link_recall_found", lang, desc=desc, link=link)


# ------------------------------------------------- edge-case helpers ----
# Messy real-world inputs (owner spec, 13 Nov 2026): the helpers the
# new intent handlers share. All of them are pure except the ones
# that read the in-memory order state.

def confirm_card_text(lang: str, service, quantity, total, link,
                      note: str = None, full_name: bool = False) -> str:
    """The Confirm card for one order: service, quantity, link and
    total, always in that order, with an optional one-line note on
    top (a quantity change, a doubled usual, a link warning). The
    service name is SHORT by default (owner, 13 Nov 2026); the full
    long name is shown only when the user entered a service ID
    (full_name=True). A public-account reminder is always on the
    card: a private account can't receive the order."""
    name = (
        clean_service_name(service.get("name"))
        if full_name
        else short_service_name(service.get("name"))
    )
    lines = [t("confirm_title", lang), ""]
    if note:
        lines.append(note)
        lines.append("")
    lines.extend([
        f"{name} (#{service.get('service')})",
        f"⏱ {service.get('average_time') or 'n/a'}",
        f"💰 {format_money(service.get('rate_etb_per_1000', 0))} ETB / 1000",
        f"🔢 {quantity}",
        f"🧾 {format_money(total)} ETB (estimated)",
        f"🔗 {link}",
        "",
        t("public_reminder", lang),
    ])
    # No long dash in any reply (owner, 17 Nov 2026): a provider
    # service name can carry one, so strip it from the whole card.
    return _strip_dashes("\n".join(lines))


def pending_note(user_id: int, lang: str) -> str:
    """One line telling the user where their order stands, or "".

    A Confirm card waiting for Confirm is named first; otherwise a
    half-built order (what the bot already has). Used after an
    interruption (a question mid-flow) so the user is never left
    wondering whether their order survived it. Only a draft with a
    LINK counts as an order being built (owner, 14 Nov 2026): a
    link-less draft left by a price question ("how much 1k" stores
    platform + quantity) is not an order, and naming it on an info
    answer is a stray confusing line."""
    _cid, pending = pending_for_user(user_id)
    if pending is not None:
        return t(
            "pending_reminder", lang,
            service=short_service_name(pending["service"].get("name")),
            quantity=pending["quantity"],
        )
    _did, delayed = pending_delayed_for_user(user_id)
    if delayed is not None:
        return t(
            "delayed_pending_reminder", lang,
            service=short_service_name(delayed["service"].get("name")),
            quantity=delayed["quantity"],
            time=format_eat_run_at(delayed["run_at"]),
        )
    partial = PARTIAL.get(user_id) or {}
    if not partial.get("link"):
        return ""
    given = [k for k in ("platform", "link", "quantity") if partial.get(k)]
    if given:
        return t("partial_reminder", lang, given=", ".join(given))
    return ""


def with_pending_note(user_id: int, lang: str, text: str) -> str:
    """A reply plus the where-your-order-stands line, when there is
    one. Interruptions (questions, trust, pricing) never silently
    drop a half-built order."""
    note = pending_note(user_id, lang)
    return f"{text}\n{note}" if note else text


def cheapest_service(services, platform=None, service_hint=None):
    """The cheapest usable service for a platform/metric, or None.

    Used when the user haggles, wants a free sample, or asks what
    their money buys: the answer is always a real service at its
    real Paxyo price — never a negotiated number. The cheapest
    ranking is forced here (15 Nov 2026): pick_services ranks
    fastest-first by default and only returns `limit` services, so
    taking the min over its top-100 fastest picks missed a cheap
    service ranked 101st by speed — the live quote of 1.51 ETB/1000
    for TikTok views came from that truncated pool, while the
    snapshot's true cheapest is #5535 at 1.26 ETB/1000. With
    "cheapest" in the hint the pool is ranked by price first, so
    the min over it IS the global cheapest."""
    hint = (service_hint or "").strip()
    if "cheapest" not in hint.lower().split():
        hint = ("cheapest " + hint).strip()
    picks = pick_services(services, platform=platform,
                          service_hint=hint, limit=100)
    if not picks:
        return None
    return min(picks, key=lambda s: float(s.get("rate_etb_per_1000", 0) or 0))


def slowest_service(services, platform=None, service_hint=None):
    """The slowest usable service (longest average time), or None.

    Offered when the user worries about safety: a slower, more
    gradual service is the honest alternative to a fast one."""
    picks = pick_services(services, platform=platform,
                          service_hint=service_hint, limit=100)
    if not picks:
        return None
    timed = [s for s in picks if parse_average_time(s.get("average_time"))]
    pool = timed if timed else picks
    return max(pool, key=lambda s: parse_average_time(s.get("average_time")) or 0)


def _platform_hint_of_service(service):
    """(platform, service_hint) for a service dict, from its name and
    category: the platform word and the kind phrase ("tiktok comment
    likes", "tiktok views"). Word-based, so "x" never matches "max"."""
    hay = _clean_kind_text(
        str(service.get("name") or "") + " "
        + str(service.get("category") or "")
    ).lower()
    words = re.findall(r"[a-z]+", hay)
    platform = _platform_from_words(words, hay)
    kind = kind_from_text(hay)
    hint = " ".join(p for p in (platform, kind) if p) or None
    return platform, hint


def _conversation_context(user_id: int):
    """(platform, service_hint) of the order the user is talking
    about — the pending Confirm card first, then the order being
    built. Used when a message ("something cheaper", "how much can
    10 br get me") names no platform of its own: the cheapest reply
    stays on the platform and metric already in the conversation
    instead of wandering to another platform's cheapest service
    (13 Nov 2026 — a TikTok views chat got Twitter Tweet
    Statistics). Returns (None, None) when there is no context."""
    _cid, pending = pending_for_user(user_id)
    if pending is not None:
        return _platform_hint_of_service(pending.get("service") or {})
    partial = PARTIAL.get(user_id) or {}
    platform = (partial.get("platform") or "").strip().lower() or None
    hint = partial.get("service_hint")
    if platform or hint:
        return platform, hint
    return None, None


def extract_links(text: str):
    """URLs (and bare t.me links) in a message, in order, de-duped.

    Used when the user pastes several links at once for a split or a
    batch order. Shortened links (vt.tiktok.com, bit.ly) are kept
    as-is — the provider resolves them."""
    found = re.findall(r"https?://\S+|t\.me/\S+", text or "")
    seen = set()
    out = []
    for link in found:
        link = link.rstrip(".,!?)]}")
        if link and link not in seen:
            seen.add(link)
            out.append(link)
    return out


# Impatience about a placed order: "why hasn't it started yet",
# "it's been 45 seconds". Answered with the real status plus the
# service's average time — never a bare "soon".
WAIT_QUESTION_PATTERNS = (
    "why hasn't", "why hasnt", "why is it taking", "hasn't started",
    "hasnt started", "not started yet", "still not started",
    "how long", "been 45 seconds", "been a minute", "taking so long",
    "taking too long", "when will it start", "why is my order",
)


def is_wait_question(text: str) -> bool:
    """True when the user is asking why a placed order has not
    started yet (as opposed to asking for its status in general)."""
    s = " ".join((text or "").strip().lower().split())
    return any(p in s for p in WAIT_QUESTION_PATTERNS)


# A question about the order being built, rather than new order
# details: speed ("how fast can you deliver it?") or drops
# ("wouldn't it drop?"). Answered from the stored service instead
# of asking for the link again (13 Nov 2026 — both questions got
# "Please send the link the order is for.").
_PENDING_SPEED_PHRASES = (
    "how fast", "how long", "how soon", "when will", "when does",
    "when do", "deliver", "delivery", "how quickly",
)
_PENDING_DROP_PHRASES = (
    "drop", "disappear", "refill", "fall off", "decrease", "go down",
    # Next batch (14 Nov 2026): the owner asks about drops as
    # "fade" / "go away" / "vanish" too — same question.
    "fade", "go away", "vanish",
)


def _canonical_metric(word: str):
    """Plural metric in _METRICS for a singular/plural word, or None.

    "comment" -> "comments", "like" -> "likes", "view" -> "views",
    "follower" -> "followers", "subscriber" -> "subscribers",
    "share" -> "shares", "member" -> "members", "save" -> "saves",
    "reply" -> "replies", "wish" -> "wishes", "play" -> "plays".
    Already-plural words return themselves; anything else is None.
    """
    w = (word or "").strip().lower()
    for m in _METRICS:
        if w == m:
            return m
        if w == m[:-1]:
            return m
        if m.endswith("es") and w == m[:-2]:
            return m
        if m.endswith("ies") and w == m[:-3] + "y":
            return m
        if w.endswith("y") and w[:-1] + "ies" == m:
            return m
    return None


def _clean_kind_text(name: str) -> str:
    """A service name lowered for kind matching, with descriptor
    text stripped out (service-types inventory §6): "[Real Views]"
    / "[Human Views]" are quality descriptors, not a views product;
    "Source: X" is not the platform or the metric ("Source: Reddit"
    is a YouTube shares service); "Views From Followers" /
    "Source From Followers" is the source of the members, not a
    followers product (Telegram has no followers product — the 20
    name hits are all "Members … From Followers"); "Free Views" on
    a reactions
    service is a free bonus, not the metric being bought."""
    s = (name or "").lower()
    s = re.sub(r"\[[^\]]*(real views|human views)[^\]]*\]", " ", s)
    s = re.sub(r"\bsource:[^|]*", " ", s)
    s = s.replace("views from followers", " ")
    s = s.replace("source from followers", " ")
    s = s.replace("from followers", " ")
    s = s.replace("free views", " ")
    return s


@functools.lru_cache(maxsize=16384)
def _name_kinds(name: str, category: str = ""):
    """Canonical kind words in a service name, as a set.

    Word-based, not substring: "preview" never counts as "views",
    and "comment" in "Tiktok Comment Likes" counts as "comment
    likes", not comments+likes. Multi-word kinds are detected
    first and their spans removed, so "Live Stream Views" is
    {live viewers} — never plain views (the single biggest
    wrong-pool cause: 67% of the TikTok plain-views pool was
    timed live-stream services). Descriptor text is ignored (see
    _clean_kind_text). The category is consulted only for package
    kinds ("Instagram Growth Packages" holds a comments+likes
    bundle whose product IS the package) and when the name carries
    no kind at all ("Votes Autorization with Telegram" is contest
    votes via its category; "YouTube Pre-Premiere Waitings" is
    live viewers via its category).
    """
    s = _clean_kind_text(name)
    cat = (category or "").lower()
    words = re.findall(r"[a-z]+", s)
    word_set = set(words)
    # Package kinds: the package wording may live in the category
    # ("Instagram Growth Packages" holds a comments+likes bundle
    # whose product IS the package). The package kind is ADDED to
    # the name's own kinds, not a replacement — the bundle's
    # components still count (#821, the Facebook engagement
    # package, is also the cheapest Facebook comments, emotions
    # and reach service in the catalogue).
    package_kind = None
    if any(p in s or p in cat for p in (
            "growth package", "growth packages", "discover package",
            "discover packages", "discovery package",
            "discovery packages")):
        package_kind = "growth package"
    elif any(p in s or p in cat for p in (
            "engagement package", "engagement packages")):
        package_kind = "engagement package"
    kinds = set()
    rest = s
    for phrase, kind in _MULTIWORD_KINDS:
        if phrase in rest:
            kinds.add(kind)
            rest = rest.replace(phrase, " ")
    rest_words = re.findall(r"[a-z]+", rest)
    # "auto" is a subscription only when it sits directly before
    # its metric ("AUTO Likes", "AUTO Video Views", "[Auto] ...
    # Post Views", "Members + Auto Views"). "<N> Days Auto" /
    # "Lifetime Auto" is auto-refill on a plain service, not an
    # auto product — so it adds no kind (15 Nov 2026: "TikTok
    # Likes ... 30 Days Auto" is plain likes; "Tiktok AUTO Likes
    # [Subscriptions]" is the auto product).
    for i, w in enumerate(words):
        if w != "auto":
            continue
        j = i + 1
        while j < len(words) and (
            words[j] in _AUTO_FILLERS or words[j] in _PLATFORMS
            or words[j] in _PLATFORM_WORDS
        ):
            j += 1
        if j >= len(words):
            continue
        nxt = words[j]
        auto_map = {
            "likes": "auto likes", "views": "auto views",
            "comments": "auto comments", "reactions": "auto reactions",
        }
        if nxt in auto_map:
            kinds.add(auto_map[nxt])
            kinds.discard(nxt)
            kinds.discard("post views")
    # Single-word kinds from what is left after the phrases.
    tweet_pending = False
    for w in rest_words:
        if w == "dm":
            kinds.add("direct messages")
            continue
        if w == "chatbot":
            kinds.add("ai chatbot")
            continue
        if w in ("like", "likes") and "reaction" in word_set:
            # "Like 👍" inside a Reactions name is the emoji's
            # name, not a likes product.
            continue
        if w in ("member", "members") and (
            "premium members" in kinds or "online members" in kinds
        ):
            continue
        if w in ("tweet", "tweets"):
            # "Tweet" is a product only when it IS the product:
            # "Twitter Tweets" is tweets, but "Tweet Views" /
            # "Tweet Shares" / "Tweet Statistics" are views /
            # shares / statistics of a tweet. The pending kind is
            # added only if no other kind was found.
            tweet_pending = True
            continue
        metric = _canonical_metric(w)
        if metric is not None:
            kinds.add(metric)
    if "reshares" in kinds:
        # A reshare IS the share action on Threads — a reshare
        # service is also a shares service.
        kinds.add("shares")
    if not kinds and tweet_pending:
        kinds.add("tweets")
    if "watchlist" in kinds:
        # "Watchlist Followers" is a watchlist product, not
        # followers.
        kinds.discard("followers")
    # "Story Likes + Views": the Views are story views, not plain
    # views; same for the Likes in "Story Views + Likes".
    if "story" in word_set:
        if "views" in kinds:
            kinds.discard("views")
            kinds.add("story views")
        if "likes" in kinds:
            kinds.discard("likes")
            kinds.add("story likes")
    # "live stream" + likes/shares is a live product as well as a
    # likes/shares one ("TikTok Live Stream Likes" is the cheapest
    # live-stream service in the catalogue); a bare "live stream"
    # with no other metric is live viewers ("YouTube Live Stream",
    # 100% concurrent). Live-stream comments stay plain comments
    # unless they are chat comments (Kwai "Livestream Custom
    # Comments" is a comments product).
    if "live stream" in s or "livestream" in s:
        if not kinds:
            kinds.add("live viewers")
        elif kinds <= {"likes", "shares"}:
            kinds.add("live viewers")
    if ("chat comments" in s and "live" in word_set) or (
        "chats" in word_set and "live" in word_set
        and "chatbot" not in word_set and "chatbots" not in word_set
    ):
        # "Live Broadcast Views [ 20 View+ 20 Chats ]" — the chats
        # ARE the live chat comments.
        kinds.discard("comments")
        kinds.add("live chat comments")
    if _has_watch_hours(s):
        kinds.add("watch hours")
    if package_kind is not None:
        kinds.add(package_kind)
        if package_kind == "engagement package" and (
            "emotion" in word_set or "emotions" in word_set
        ):
            kinds.add("emotions")
    if not kinds and cat:
        return _name_kinds(cat)
    return kinds


def _word_variants(word: str):
    """Singular/plural spellings of a hint word, so "requests"
    matches a service named "Request", "replies" matches "Reply",
    "saves" matches "Save", "messages" matches "Message" — the
    plural bug (service-types inventory §4e): only _METRICS words
    had a singular fallback, so 10+ types returned empty pools
    although the service exists in singular form."""
    w = (word or "").strip().lower()
    out = {w}
    if w.endswith("ies") and len(w) > 3:
        out.add(w[:-3] + "y")
    elif w.endswith("es") and len(w) > 2:
        out.add(w[:-1])
        if w[:-2].endswith(("s", "x", "z", "ch", "sh")):
            out.add(w[:-2])
    elif w.endswith("s") and len(w) > 1:
        out.add(w[:-1])
    else:
        out.add(w + "s")
        if w.endswith("y") and len(w) > 1:
            out.add(w[:-1] + "ies")
    return out


# Reaction words and the emoji the catalogue writes instead
# ("heart" matches ❤️, "pray" matches 🙏): the catalogue names
# reactions by emoji, not by word, so a word-form hint ("heart
# reactions") must match the emoji in the service name — otherwise
# the word form finds nothing although the service exists
# (service-types inventory §5, 15 Nov 2026). "up"/"down"/"eyes"/
# "joy"/"hand"/"on" are the second words of reaction names
# ("thumbs up", "heart eyes", "tears of joy", "writing hand",
# "heart on fire").
_REACTION_WORD_EMOJI = {
    "heart": ("❤️", "❤", "❤️‍🔥", "❤‍🔥"),
    "pray": ("🙏",),
    "fire": ("🔥", "❤️‍🔥", "❤‍🔥"),
    "thumbs": ("👍", "👎"),
    "thumb": ("👍", "👎"),
    "up": ("👍",),
    "down": ("👎",),
    "eyes": ("😍",),
    "joy": ("😂", "🤣"),
    "laugh": ("😂", "🤣"),
    "crying": ("😢",),
    "sad": ("😢",),
    "angry": ("😡",),
    "thinking": ("🤔",),
    "celebration": ("🎉",),
    "party": ("🎉",),
    "wow": ("😮",),
    "snowman": ("☃️", "☃"),
    "lightning": ("⚡️", "⚡"),
    "writing": ("✍️", "✍"),
    "hand": ("✍️", "✍"),
    "on": ("❤️‍🔥", "❤‍🔥"),
    "dislike": ("👎",),
}


def _hint_word_matches(word: str, hay: str) -> bool:
    """True when a hint word appears in a service name/category.

    Whole-word matching (service-types inventory §6): the old
    substring match sold Facebook Page Reviews for a views order
    ("views" inside "reviews"), retweets for a tweets order
    ("tweets" inside "retweets"), and anything with "Max" in its
    name for an "x" order. Kind words match in singular or plural
    ("views" matches a service named "TikTok View", "comment"
    matches "Comments"); every other word matches in singular or
    plural too (requests/replies/messages/mentions/...)."""
    if word in ("watchhour", "watchhours"):
        return "watch hour" in hay
    if word == "watchtime":
        return "watch time" in hay or "watch hour" in hay
    hay_words = set(re.findall(r"[a-z]+", hay))
    if word in ("viewers", "viewer"):
        # "Live Viewers" and "Live Stream Views" are the same
        # product — the catalogue writes it both ways.
        return bool({"views", "view", "viewers", "viewer"} & hay_words)
    if word in ("growth", "discover", "discovery"):
        # A "growth package" and a "discover package" are the same
        # product family (TikTok #2733 is a Discover Package).
        return bool({"growth", "discover", "discovery"} & hay_words)
    if word == "direct":
        # "Direct messages" is written "Mass DM" in the catalogue.
        return "dm" in hay_words or bool(_word_variants(word) & hay_words)
    if word in ("messages", "message"):
        return "dm" in hay_words or bool(_word_variants(word) & hay_words)
    if word in ("shares", "share", "reshares", "reshare"):
        # A Threads reshare IS the share action there — a reshare
        # service is a shares service. The kinds check still
        # guards the pool, so a plain shares service is never
        # sold as reshares.
        return bool({"shares", "share", "reshares", "reshare"} & hay_words)
    if word in ("comments", "comment"):
        # Live chat comments are written "Chats" ("20 View+ 20
        # Chats"); the kinds check still guards the pool, so a
        # plain chat service is never sold as comments.
        return (
            bool({"chat", "chats"} & hay_words)
            or bool(_word_variants(word) & hay_words)
        )
    if word in _REACTION_WORD_EMOJI:
        # A reaction word matches its emoji in the name ("heart"
        # matches ❤️, "pray" matches 🙏).
        if any(e in hay for e in _REACTION_WORD_EMOJI[word]):
            return True
    return bool(_word_variants(word) & hay_words)


# Amharic metric words (round 7, 13 Nov 2026): the bot reads
# Amharic orders, but kind_from_text only saw Latin words, so an
# Amharic views order inherited the previous turn's followers hint
# from the AI and got the wrong answer. Extended 15 Nov 2026 for
# the new kinds where a natural Amharic word exists (transliterations
# Ethiopians actually type, or the plain word): saves, plays, live
# viewers, poll votes, reactions, story views, downloads, traffic,
# comment replies. Kinds with no clean Amharic word (bot start,
# channel boost, watchlist, ...) stay English-only — the Latin
# phrase still works, and inventing a word would mis-route.
_AMHARIC_METRICS = {
    "እይታ": "views", "እይታዎች": "views",
    "ተከታይ": "followers", "ተከታዮች": "followers",
    "ላይክ": "likes", "ላይኮች": "likes",
    "አስተያየት": "comments", "አስተያየቶች": "comments",
    "ኮሜንት": "comments", "ኮሜንቶች": "comments",
    "ሰብስክራይበር": "subscribers", "ሰብስክራይበሮች": "subscribers",
    "ሼር": "shares", "አባል": "members", "አባላት": "members",
    "ሴቭ": "saves", "ሴቮች": "saves",
    "ፕሌይ": "plays", "ፕሌዮች": "plays",
    "ቀጥታ": "live viewers", "ተመልካች": "views", "ተመልካቾች": "views",
    "ድምጽ": "poll votes", "ድምጾች": "poll votes",
    "ሪአክሽን": "reactions", "ሪአክሽኖች": "reactions",
    "ምላሽ": "reactions", "ምላሾች": "reactions",
    "ስቶሪ": "story views",
    "ዳውንሎድ": "downloads",
    "ትራፊክ": "traffic",
    "መልስ": "comment replies", "መልሶች": "comment replies",
}


# Watch-time phrases (live fault, 15 Nov 2026): "what is cheapest
# youtube watch hour" was answered with a subscribers service,
# because no metric word matched — "watch" and "hour" are not in
# _METRICS, so the hint was platform-only and the cheapest YouTube
# service overall (a subscribers service) won. "watch hours" is a
# first-class metric kind, like "comment likes".
def _has_watch_hours(text: str) -> bool:
    """True when the text asks for watch time: "watch hour(s)",
    "watchhour(s)", "watch time" or "watchtime". A bare "watch"
    does not count — it is usually a verb ("watch my video")."""
    s = (text or "").lower()
    return (
        "watch hour" in s
        or "watch time" in s
        or "watchhour" in s
        or "watchtime" in s
    )


def kind_from_text(text: str):
    """The service kind the message asks for, or None.

    Multi-word kinds first ("story views" beats "views", "live
    stream views" beats "views", "comment likes" beats "likes"),
    then the watch-hours phrase, then the first metric word in
    message order ("views", "likes", "followers", ...). Singular
    and plural count the same, so "tiktok comment" and "tiktok
    comments" are the same kind. "viewers" on its own means live
    viewers (concurrent viewers), and a bare "live stream" with no
    other metric is live viewers too ("YouTube Live Stream" is a
    concurrent-viewers product, not plain views). Amharic metric
    words count the same way ("እይታዎች" is views).
    """
    # URLs are stripped first: their words ("t", "me", "com") are
    # not the user's words, and a link must never push the metric
    # scan past the quantity ("like https://t.me/... hundred
    # views"). Digits stay in the scan so the filler-"like" check
    # below can see a quantity written right after "like".
    s = re.sub(r"https?://\S+|t\.me/\S+", " ", text or "")
    low = s.lower()
    for phrase, kind in _MULTIWORD_KINDS:
        if phrase in low:
            return kind
    words = re.findall(r"[a-z]+|\d[\d,]*", low)
    word_set = set(words)
    if "viewers" in word_set or "viewer" in word_set:
        return "live viewers"
    if ("live stream" in low or "livestream" in low) and not any(
        _canonical_metric(w) is not None for w in words
    ):
        return "live viewers"
    am_words = re.findall(r"[\u1200-\u137c]+", text or "")
    am_metrics = [
        _AMHARIC_METRICS[w] for w in am_words if w in _AMHARIC_METRICS
    ]
    if "comment" in word_set and ("like" in word_set or "likes" in word_set):
        return "comment likes"
    if "comments" in am_metrics and "likes" in am_metrics:
        return "comment likes"
    if _has_watch_hours(low):
        return "watch hours"
    for idx, w in enumerate(words):
        if w in ("like", "likes"):
            # Filler "like" ("I want, like, 100 views", live 14 Nov
            # 2026): skip it when a quantity follows within the next
            # few words — the real metric comes after the quantity.
            # A real likes request ("likes for my video") has no
            # quantity after "likes", so it is kept.
            rest = words[idx + 1:idx + 4]
            if any(
                re.fullmatch(r"\d[\d,]*", t) for t in rest
            ) or any(t in _NUMBER_WORDS for t in rest):
                continue
        if w == "dm":
            return "direct messages"
        if w == "chatbot":
            return "ai chatbot"
        if w in ("tweet", "tweets"):
            # "Tweet" is the product only when nothing else follows
            # it: "twitter tweets" is tweets, but "twitter tweet
            # views" is views of a tweet.
            if any(
                _canonical_metric(x) is not None
                for x in words[idx + 1:]
            ):
                continue
        metric = _canonical_metric(w)
        if metric is not None:
            return metric
    if am_metrics:
        return am_metrics[0]
    # An emoji can carry the metric on its own (round 8, 14 Nov
    # 2026): "👍" means the thumbs-up reaction, "👀" means views.
    # It is a fallback only — a word the user typed wins over it.
    if reaction_emoji(text) is not None:
        return "reactions"
    if "👀" in (text or ""):
        return "views"
    return None


_PLATFORM_DISPLAY = {
    "telegram": "Telegram", "instagram": "Instagram",
    "tiktok": "TikTok", "youtube": "YouTube",
    "facebook": "Facebook", "x": "X",
}


def ask_link_text(platform, service_hint, lang):
    """The link question for the order being built (owner, 14 Nov
    2026): specific to what is being ordered — followers get the
    profile link naming the platform, video views the video link,
    Telegram post interaction the Telegram post link, likes the
    post/video to like, comments the post/video to comment on,
    comment likes the existing two-thing question. The bare
    generic ask_link is used only when the order type is
    genuinely unknown."""
    metric = kind_from_text(service_hint or "")
    platform = (platform or "").strip().lower() or None
    disp = _PLATFORM_DISPLAY.get(
        platform or "", (platform or "").title()
    )
    if metric == "followers" and platform:
        return t("ask_link_profile", lang, platform=disp)
    if metric == "views":
        if platform == "telegram":
            return t("ask_link_post", lang, platform=disp)
        return t("ask_link_video", lang)
    if metric == "reactions":
        if platform:
            return t("ask_link_post", lang, platform=disp)
        return t("ask_link_post_generic", lang)
    if metric == "likes":
        return t("ask_link_like", lang)
    if metric == "comments":
        return t("ask_link_comment", lang)
    if metric == "comment likes":
        return t("comment_likes_need", lang)
    if metric == "members":
        return t("ask_link_group", lang)
    if metric == "subscribers":
        return t("ask_link_channel", lang)
    if metric == "shares":
        return t("ask_link_share", lang)
    return t("ask_link", lang)


# ------------------------------------------------- prompt shrink -------
# Prompt shrink (owner approved, 14 Nov 2026): every AI call used to
# send the whole SYSTEM_PROMPT (~2,460 tokens) plus up to 10 turns
# of history. The service catalogue was NEVER in the prompt — the
# bulk was the classifier instructions and the history — so the
# shrink is: a compact SYSTEM_PROMPT, the last 3 turns only, and a
# short list of matching services, but only when the message names
# both a platform and a metric. The full catalogue is never pasted
# into a prompt (7,176 services would be ~100k tokens); the
# deterministic code (pick_services, price) still works from the
# full catalogue, exactly as before.
PROMPT_SERVICES_LIMIT = 30

def detect_platform_metric(text):
    """(platform, metric) the message asks for, deterministically —
    words and links only, never the AI. Platform from a platform
    word ("tiktok", "telegram", ...) or a link's domain; metric
    from kind_from_text (words, Amharic words, or a reaction emoji).
    "private channel" means the MAX private-channel line ("max" is
    not a platform word — it collides with "max 1000 views").
    Returns (None, None) when neither can be read — the caller then
    sends no services section and the deterministic code still
    works from the full catalogue."""
    norm = normalize_text(text or "")
    words = set(re.findall(r"[a-z]+", norm.lower()))
    platform = None
    # The link decides first (owner, 14 Nov 2026): a pasted t.me
    # link is Telegram even when the words name nothing — or name
    # something else (a forwarded notice about TikTok).
    for token in re.findall(r"https?://\S+|t\.me/\S+", norm):
        platform = platform_from_link(token)
        if platform:
            break
    if platform is None and "private channel" in norm.lower():
        platform = "max"
    if platform is None:
        for word, plat in _PLATFORM_WORDS.items():
            if word in words:
                platform = plat
                break
    if platform is None and "x.com" in norm.lower():
        platform = "x"
    metric = kind_from_text(norm)
    return platform, metric


def _explicit_platform_word(text: str):
    """Platform word the user typed themselves (not inside a URL):
    "tiktok" in "I want tiktok views" counts; "facebook" inside
    "https://www.facebook.com/..." does not. Used so the link can
    win over the AI's guess without silencing a real mismatch the
    user typed ("YouTube subscribers" + a TikTok link). "private
    channel" means the MAX line."""
    s = re.sub(r"https?://\S+|t\.me/\S+", " ", text or "")
    if "private channel" in s.lower():
        return "max"
    words = set(re.findall(r"[a-z]+", s.lower()))
    for word, plat in _PLATFORM_WORDS.items():
        if word in words:
            return plat
    return None


def services_for_prompt(services, platform=None, metric=None,
                        limit=PROMPT_SERVICES_LIMIT, reaction_emoji=None):
    """Services to show the AI for this message: the matching ones
    only (same matching as pick_services — fastest first, inactive
    and blacklisted excluded, reactions limited to the emoji's
    single-post family). When platform or metric is unknown, returns
    the FULL catalogue unchanged: the caller must then NOT paste it
    into the prompt — it omits the section, and the deterministic
    code (pick_services, price) still works from the full catalogue,
    exactly as today."""
    if not platform or not metric:
        return list(services or [])
    hint = " ".join(p for p in (platform, metric) if p)
    return pick_services(
        services or [], platform=platform, service_hint=hint,
        limit=limit, reaction_emoji=reaction_emoji,
    )


def _classify_state_block(user_id: int):
    """One line of the user's CURRENT order state for the END of the
    classify prompt (smart-loop round 2, 14 Nov 2026): a Confirm card
    waiting for a tap, or the half-built draft — platform, metric,
    quantity and what is still missing. It goes LAST, after the
    services section, so the classifier reads the message, the
    history and the candidates first and the live state last.
    NEVER balance, last order, phone number or deposit: those never
    go to an AI provider (see TRAINING.md / the data-flow rules),
    and the draft's link is left out too — the history already
    carries it, so repeating it here would only spend tokens.
    Returns "" when there is no order state to report."""
    if user_id is None:
        return ""
    _, pending = pending_for_user(user_id)
    if pending is not None:
        service = pending.get("service") or {}
        name = short_service_name(service.get("name")) or "the order"
        qty = pending.get("quantity")
        line = f"Current state: waiting for Confirm on {name}"
        if qty is not None:
            line += f" x{qty}"
        return line + "."
    _, delayed = pending_delayed_for_user(user_id)
    if delayed is not None:
        service = delayed.get("service") or {}
        name = short_service_name(service.get("name")) or "the order"
        qty = delayed.get("quantity")
        line = f"Current state: waiting for Confirm on a delayed order — {name}"
        if qty is not None:
            line += f" x{qty}"
        return line + f", to be placed at about {format_eat_run_at(delayed.get('run_at'))}."
    delayed_draft = DELAYED_DRAFT.get(user_id) or {}
    if delayed_draft:
        parts = [p for p in (
            delayed_draft.get("platform"), delayed_draft.get("service_hint"),
        ) if p]
        line = "Current state: building a delayed order"
        if parts:
            line += " — " + " ".join(parts)
        if delayed_draft.get("quantity") is not None:
            line += f" x{delayed_draft.get('quantity')}"
        if delayed_draft.get("delay_minutes") is not None:
            line += f", in {format_interval(delayed_draft.get('delay_minutes'))}"
        missing = []
        if not delayed_draft.get("link"):
            missing.append("waiting for the link")
        if delayed_draft.get("quantity") is None:
            missing.append("waiting for the quantity")
        if delayed_draft.get("delay_minutes") is None:
            missing.append("waiting for the delay")
        if missing:
            line += ", " + " and ".join(missing)
        return line + "."
    draft = PARTIAL.get(user_id) or {}
    if draft:
        parts = [p for p in (
            draft.get("platform"), draft.get("service_hint"),
        ) if p]
        line = "Current state: building an order"
        if parts:
            line += " — " + " ".join(parts)
        if draft.get("quantity") is not None:
            line += f" x{draft.get('quantity')}"
        missing = []
        if not draft.get("link"):
            missing.append("waiting for the link")
        if draft.get("quantity") is None:
            missing.append("waiting for the quantity")
        if missing:
            line += ", " + " and ".join(missing)
        return line + "."
    return ""


def build_classify_prompt(text, services=None, user_id=None,
                          max_history=3):
    """The prompt extract_intent sends the AI: the message, the last
    few turns, and — only when the message names BOTH a platform and
    a metric — the matching services, at most 30, fastest first (id,
    short name, ETB per 1000, average time). When platform or metric
    cannot be read, there is no services section at all: the
    deterministic code still picks from the full catalogue, exactly
    as before. The full catalogue is never pasted into a prompt.

    Ordering contract (smart-loop round 2): the STATIC system
    prompt (SYSTEM_PROMPT, rules + few-shot examples) is the
    system message, and this user prompt is dynamic-only, in this
    order — message first, then recent history, then candidate
    services, then the current order state last. That keeps the
    static prefix identical across calls (DeepSeek prefix caching
    reuses it) and the per-call state at the end, where it cannot
    leak into the cached part. No balance, last order, phone
    number or deposit ever appears here."""
    prompt = normalize_text(text)
    if user_id is not None:
        history = chat_history_lines(user_id, max_exchanges=max_history)
        if history:
            prompt += (
                "\n\nRecent conversation with this user (most recent last):\n"
                + "\n".join(history)
            )
    if services:
        platform, metric = detect_platform_metric(text)
        if platform and metric:
            shown = services_for_prompt(
                services, platform, metric,
                reaction_emoji=reaction_emoji(text),
            )
            if shown:
                lines = [
                    "Candidate services for this request "
                    "(id, name, ETB per 1000, average time):"
                ]
                for s in shown:
                    rate = s.get("rate_etb_per_1000")
                    try:
                        rate_text = format_money(rate)
                    except (TypeError, ValueError):
                        rate_text = "?"
                    avg = s.get("average_time") or "no time listed"
                    lines.append(
                        f"#{s.get('service')} "
                        f"{short_service_name(s.get('name'))} — "
                        f"{rate_text} ETB per 1000, {avg}"
                    )
                prompt += "\n\n" + "\n".join(lines)
    if user_id is not None:
        state = _classify_state_block(user_id)
        if state:
            prompt += "\n\n" + state
    return prompt


def _primary_metric(kind: str):
    """The metric actually being bought in a kind string ("comment
    likes" -> "likes", "views" -> "views"), or None. Used to tell a
    new order (different metric) from a clarification of the same
    one ("likes for my comment" is still likes)."""
    if not kind:
        return None
    if _has_watch_hours(kind):
        return "watch hours"
    for w in reversed(str(kind).split()):
        metric = _canonical_metric(w)
        if metric is not None:
            return metric
    return None


def metric_from_text(text: str):
    """First metric kind in the message text, or None.

    The classifier sometimes drops the metric ("I want 1000 tiktok
    views" -> hint "tiktok" or none); the order flow reads the metric
    back from the user's own words instead of guessing. May return
    the two-word kind "comment likes" for likes on a comment.
    """
    return kind_from_text(text)


def pending_order_question(text: str, known_quantity=None):
    """'speed' / 'drop' / None: is this message a question about an
    order being built? A question carries no link and no
    quantity-like number, and is not a service choice ("use the
    fastest one"). A number that equals a quantity already known
    (the pending order's quantity, or the order being built) is a
    reference to that order, not new information, so it does not
    block the question: "how fast would those 1000 views arrive?"
    is a question about the 1000-view order."""
    s = " ".join((text or "").strip().lower().split())
    if not s:
        return None
    if extract_links(text):
        return None
    if "fastest" in s or "cheapest" in s or "use the" in s:
        return None
    for m in re.finditer(r"\d[\d,]*", s):
        try:
            value = int(m.group(0).replace(",", ""))
        except ValueError:
            continue
        if value == known_quantity:
            continue
        if 10 <= value <= 1000000 and value % 10 == 0:
            return None
    if any(p in s for p in _PENDING_DROP_PHRASES):
        return "drop"
    if any(p in s for p in _PENDING_SPEED_PHRASES):
        return "speed"
    return None


def pending_confirm_answer(service, question: str, lang: str):
    """Answer a question about an order awaiting Confirm, from the
    pending service itself. Returns the answer string, or None when
    there is no service to answer from. The order stays open — the
    caller does not cancel it. (13 Nov 2026: "how fast can you
    deliver it" after a Confirm card got the busy line, because the
    pending-question fix only covered a PARTIAL order waiting for a
    link.)"""
    if not service:
        return None
    name = short_service_name(service.get("name"))
    if question == "speed":
        avg = service.get("average_time")
        if parse_average_time(avg) is not None:
            return t("confirm_speed", lang, service=name, avg=avg)
        return t("confirm_speed_unknown", lang, service=name)
    if question == "drop":
        # Owner, 14 Nov 2026: Telegram reactions, Telegram views
        # and Facebook reactions never drop — say so instead of
        # the refill line. Any other service keeps the refill
        # answer below.
        kind = _service_never_drop_kind(service)
        if kind is not None:
            return t("never_drop", lang, service=kind)
    low = str(service.get("name") or "").lower()
    if "no refill" in low:
        refill = t("pending_no_refill", lang)
    elif "refill" in low:
        refill = t("pending_has_refill", lang)
    else:
        refill = t("pending_refill_unknown", lang)
    return t("confirm_drop", lang, service=name, refill=refill)


def link_needs_warning(text: str, link: str) -> bool:
    """True when the link may fail: a private account, or a story
    that expires soon. Shortened links are fine — the provider
    resolves them — so they do not trigger a warning."""
    s = " ".join((text or "").strip().lower().split())
    l = str(link or "").lower()
    return (
        "private" in s or "story" in s or "stories" in s
        or "/stories/" in l or "/story/" in l
    )


def pending_batch_for_user(user_id: int):
    """(confirm_id, batch) of the user's most recent batch awaiting
    Confirm, or (None, None)."""
    for confirm_id, batch in reversed(list(PENDING_BATCH.items())):
        if batch["user_id"] == user_id:
            return confirm_id, batch
    return None, None


def pending_bundle_for_user(user_id: int):
    """(confirm_id, bundle) of the user's most recent post bundle
    awaiting Confirm, or (None, None)."""
    for confirm_id, bundle in reversed(list(PENDING_BUNDLE.items())):
        if bundle["user_id"] == user_id:
            return confirm_id, bundle
    return None, None


def pending_refill_for_user(user_id: int):
    """(confirm_id, refill) of the user's most recent refill
    awaiting Confirm, or (None, None)."""
    for confirm_id, refill in reversed(list(PENDING_REFILL.items())):
        if refill["user_id"] == user_id:
            return confirm_id, refill
    return None, None


