# Ideas batch (owner, 15 Nov 2026): persistent quick-reply buttons.
# A Telegram reply keyboard (not inline): once shown it stays under
# the chat until replaced, so the user always has one-tap Order /
# Balance / My orders / Deposit / Support. Shown after greetings and
# after completed flows. The labels are English + emoji in every
# language — reply keyboards are never translated (same rule as
# Confirm cards), and the tap handler matches the label with or
# without the emoji.
QUICK_REPLY_LABELS = (
    "🛒 Order", "💰 Balance", "📦 My orders", "💳 Deposit", "🆘 Support",
)


def quick_reply_keyboard() -> ReplyKeyboardMarkup:
    """The persistent quick-reply keyboard, two buttons a row."""
    return ReplyKeyboardMarkup(
        [
            [KeyboardButton("🛒 Order"), KeyboardButton("💰 Balance")],
            [KeyboardButton("📦 My orders"), KeyboardButton("💳 Deposit")],
            [KeyboardButton("🆘 Support")],
        ],
        resize_keyboard=True,
    )


def hide_reply_keyboard() -> ReplyKeyboardRemove:
    """Hide the persistent reply keyboard (16 Nov 2026, William):
    the Order / Balance / My orders / Deposit / Support buttons
    are gone — every bot reply carries this instead, so the
    buttons disappear from the chat. Inline keyboards are
    unaffected: they ride on reply_markup explicitly, never
    through here. The text commands (Order, Balance, My orders,
    Deposit, Support) still work when typed — see
    quick_reply_action."""
    return ReplyKeyboardRemove()


def quick_reply_action(text: str):
    """The quick-reply action for a message ("order", "balance",
    "orders", "deposit", "support"), or None. Matches the button
    label with or without its emoji, case-insensitive — a typed
    "Balance" does the same thing as tapping 💰 Balance. Trailing
    punctuation is stripped first (late-reply fix, 16 Nov 2026):
    voice transcription often adds it ("Order.", "balance!"), and
    without the strip a plain command word fell through to the AI
    classifier and waited on a slow provider."""
    s = " ".join((text or "").strip().lower().split())
    s = re.sub(r"[.!?]+$", "", s)
    for label in QUICK_REPLY_LABELS:
        plain = label.split(" ", 1)[-1].strip().lower()
        if s == label.lower() or s == plain:
            return {
                "order": "order", "balance": "balance",
                "my orders": "orders", "deposit": "deposit",
                "support": "support",
            }[plain]
    return None


def rating_keyboard(order_id) -> InlineKeyboardMarkup:
    """👍 / 👎 on a delivery message (rate your order, ideas batch
    2, feature 3, 15 Nov 2026). Callback data
    "rate:<order_id>:good" / "rate:<order_id>:bad" — one tap files
    the rating; a second tap answers "Already noted"."""
    return InlineKeyboardMarkup([[
        InlineKeyboardButton("👍", callback_data=f"rate:{order_id}:good"),
        InlineKeyboardButton("👎", callback_data=f"rate:{order_id}:bad"),
    ]])


def reorder_keyboard(orders) -> InlineKeyboardMarkup:
    """One "🔁 Order again" button per order (at most 5, newest
    first): the same service, quantity and link as a new draft,
    shown as a Confirm card. Callback data "reorder:<order_id>".
    Under the reorder rows, one "⚠️ Report a problem" button per
    order (report a problem, ideas batch 2, feature 2, 15 Nov
    2026): callback data "report:<order_id>". The reorder rows
    stay first, so the shape the old tests pin (row 0 is the first
    reorder button) is unchanged."""
    buttons = []
    for o in list(orders or [])[:5]:
        order_id = o.get("id") or o.get("order_id")
        if order_id is None:
            continue
        name = short_service_name(o.get("service_name") or "") or f"service {o.get('service_id')}"
        label = f"🔁 #{order_id} {name} ×{int(o.get('quantity') or 0)}"
        buttons.append([
            InlineKeyboardButton(label, callback_data=f"reorder:{order_id}")
        ])
    for o in list(orders or [])[:5]:
        order_id = o.get("id") or o.get("order_id")
        if order_id is None:
            continue
        buttons.append([
            InlineKeyboardButton(
                f"⚠️ Report a problem #{order_id}",
                callback_data=f"report:{order_id}",
            )
        ])
    return InlineKeyboardMarkup(buttons)


def build_digest_text(stats, lang: str) -> str:
    """The daily digest for William (owner, 15 Nov 2026): one short
    text with yesterday's/today's orders, revenue and new users.
    Pure formatting — the numbers come from the server's
    /admin/stats; nothing here invents a figure. `stats` is the
    server record: {"date", "orders", "completed", "revenue_etb",
    "new_users", "top_service", "top_quantity"}. Missing keys read
    as zero / empty, never as an invented number."""
    stats = stats or {}
    top_service = stats.get("top_service")
    top_line = ""
    if top_service:
        top_line = t(
            "digest_top_line", lang, service=top_service,
            quantity=int(stats.get("top_quantity") or 0),
        )
    return t(
        "daily_digest", lang,
        date=str(stats.get("date") or "today"),
        orders=int(stats.get("orders") or 0),
        completed=int(stats.get("completed") or 0),
        revenue=format_money(stats.get("revenue_etb") or 0),
        new_users=int(stats.get("new_users") or 0),
        top_line=top_line,
    )


def is_order_stuck(placed_at: float, avg_minutes, now: float) -> bool:
    """True when an in-flight order has run far past its claimed
    average time: at least 3× the average AND at least 15 minutes
    overdue. No average time means never stuck — the bot never
    invents a time. Pure predicate, so the rule is testable
    without the scheduler."""
    if avg_minutes is None:
        return False
    try:
        avg = float(avg_minutes)
    except (TypeError, ValueError):
        return False
    if avg <= 0:
        return False
    elapsed_min = (now - placed_at) / 60.0
    return elapsed_min >= 3 * avg and elapsed_min - avg >= 15


def watch_order(user_id: int, order_id, service, quantity, link,
                total=None, rescue_count=0, failed_services=None,
                split=None, drip=None, deadline=None):
    """Start watching a placed order for its delivery update and
    stuck warning (ideas batch, 15 Nov 2026). Only orders placed
    through the bot are watched — one delivered message and at most
    one stuck warning per order. `service` is the catalogue dict
    (its average_time is the claimed time); a missing order id is
    never watched. `total` is what the user paid (for the rescue
    message, when the server's refund reply omits the figure);
    `rescue_count` / `failed_services` carry a rescue chain forward
    onto the replacement order (stall rescue, 15 Nov 2026).
    `split` (split-test, 15 Nov 2026) is the split context dict
    (group_id, leg "test"/"remainder", total_qty, test_qty,
    rest_qty, confirmed_total, spent) — the scheduler routes a
    watched split leg through the split-test flow instead of the
    plain rescue flow. `drip` (customizations #15) is the drip
    context dict (runs, interval, per_run_qty) — a drip order
    delivers over time BY DESIGN, so the scheduler never
    stall-rescues it; it is only watched for its completion.
    `deadline` (customizations #20) is the ISO string the customer
    set — a rescue replacement must still be able to make it, so
    the deadline rides forward onto every replacement order."""
    if order_id is None or str(order_id) in ("", "?"):
        return
    avg = None
    if isinstance(service, dict):
        avg = parse_average_time(service.get("average_time"))
    import time

    WATCHED_ORDERS[str(order_id)] = {
        "user_id": user_id,
        "service": service if isinstance(service, dict) else {},
        "quantity": quantity,
        "link": link,
        "placed_at": time.time(),
        "avg_minutes": avg,
        "warned": False,
        "total": total,
        "rescue_count": rescue_count,
        "rescue_attempted": False,
        "failed_services": list(failed_services or []),
        "split": dict(split) if split is not None else None,
        "drip": dict(drip) if drip else None,
        "deadline": deadline,
    }


def _crosssell_line(services, service):
    """One cross-sell line for a delivered VIEWS order, or "".

    Only when a likes service exists for the same platform — the
    cheapest-fastest likes pick, priced from the catalogue. A
    non-views order, or a platform with no likes service, gets no
    line at all."""
    name = str((service or {}).get("name") or "")
    if "views" not in _name_kinds(name):
        return ""
    platform, _hint = _platform_hint_of_service(service or {})
    if not platform:
        return ""
    picks = pick_services(
        services, platform=platform,
        service_hint=f"{platform} likes", limit=1,
    )
    if not picks:
        return ""
    like = picks[0]
    return "\n" + t(
        "order_delivered_crosssell", "en",
        service=short_service_name(like.get("name")),
        price=format_money(like.get("rate_etb_per_1000", 0)),
    )


def _rescue_price_cap(watched, service, quantity):
    """The most a rescue replacement may cost (owner rule, 15 Nov
    2026): the amount the user confirmed for the original order —
    never more. The watch entry keeps the confirmed total; when it
    is missing (an older entry), the original service's catalogue
    estimate is the cap. After a rescue the replacement's own
    total becomes the cap for the next rescue, so the cap only
    ever stays the same or shrinks down a chain."""
    total = (watched or {}).get("total")
    if total is None:
        total = estimated_total_etb(
            float((service or {}).get("rate_etb_per_1000") or 0),
            quantity,
        )
    return float(total)


# How many fastest candidates the rescue pick looks at: pricier
# candidates are skipped (owner rule, 15 Nov 2026), so the pick
# must look further down the list than the old limit of 3 to find
# an affordable service.
RESCUE_CANDIDATE_LIMIT = 10


def _failed_combined_ids(service, failed_services):
    """The set of combined ids ("gop:<id>" / "smm:<id>") that must
    never be picked again in this chain: every failed service plus
    the service itself. A bare id in failed_services is treated
    as a GOP id, so it can never wrongly exclude the other
    provider's service of the same number."""
    failed = set()
    for sid in failed_services or []:
        if isinstance(sid, str) and ":" in sid:
            failed.add(sid)
            continue
        try:
            failed.add(service_combined_id({"service": int(sid)}))
        except (TypeError, ValueError):
            continue
    failed.add(service_combined_id(service or {}))
    return failed


# Split-test for big orders (owner, 15 Nov 2026): an order over
# this confirmed total is placed as a 10% test first, then the
# remaining 90% once the test delivers. The default method — it
# can be customised per customer later (no per-customer settings
# are built now).
SPLIT_TEST_THRESHOLD_ETB = 400
SPLIT_TEST_FRACTION = 0.10
# Paxyo covers at most this fraction above the confirmed total
# when no cheaper service works (owner, 15 Nov 2026) — the extra
# comes from Paxyo's pocket, never from the customer.
SPLIT_COVER_MAX_FRACTION = 0.10


def _ceil_to_10(value):
    """Round a quantity UP to a multiple of 10 — quantities must
    be multiples of 10 (the server enforces it)."""
    import math

    return int(math.ceil(float(value) / 10.0)) * 10


def _service_min_qty(service):
    """A service's minimum quantity, or 0 when it has none."""
    try:
        return max(0, int((service or {}).get("min") or 0))
    except (TypeError, ValueError):
        return 0


def split_test_quantities(quantity, service):
    """(test_qty, rest_qty) for a split-test placement, or None
    when the order cannot be split on this service. The test is
    10% of the order rounded UP to a multiple of 10, at least the
    service minimum (also rounded up to a multiple of 10), and
    the remainder is the exact rest — so test + rest is exactly
    the ordered quantity, never more. None when the remainder
    would be zero or below the service minimum: a small order on
    a high-minimum service is placed whole instead, on the
    non-split path."""
    try:
        qty = int(quantity)
    except (TypeError, ValueError):
        return None
    if qty <= 0:
        return None
    if qty % 10 != 0:
        # Quantities are multiples of 10 (the bot enforces it at
        # parse, the server at placement) — a non-multiple order
        # cannot be split exactly, so it is placed whole instead.
        return None
    minimum = _ceil_to_10(_service_min_qty(service))
    test_qty = max(_ceil_to_10(qty * SPLIT_TEST_FRACTION), minimum)
    if test_qty > qty:
        return None
    rest_qty = qty - test_qty
    if rest_qty <= 0 or rest_qty < minimum:
        return None
    return (test_qty, rest_qty)


def split_leg_cover(confirmed_total, leg_qty, total_qty, leg_cost):
    """Paxyo's cover for one leg of a split order: the leg's cost
    above the user's proportional share of the confirmed total
    (share = confirmed * leg_qty / total_qty). Zero when the leg
    costs at most its share — the common case, where the service
    is the confirmed one or cheaper. The caller caps the cover
    for the whole order at 10% of the confirmed total; this
    helper only ever prices one leg."""
    try:
        share = float(confirmed_total) * int(leg_qty) / int(total_qty)
    except (TypeError, ValueError, ZeroDivisionError):
        return 0.0
    return round(max(0.0, float(leg_cost) - share), 2)


def _next_split_service(services, service, failed_services, total_qty,
                        confirmed_total, allow_cover=True,
                        reliability=None, paused=None,
                        balance_health=None, story=None):
    """The next service for a stalled split test: the same platform
    + metric, CHEAPEST first (the retry walks down the cheaper
    services), excluding every service that already stalled in
    this chain and any service the order cannot be split on (its
    remainder would fall below its minimum). Returns (service,
    cover) or (None, 0.0): cover is the Paxyo-paid extra when the
    cheapest remaining service costs more than the confirmed
    total — at most 10% of it, and only when no affordable
    service exists at all (the list is cheapest-first, so the
    first candidate within the band is the cheapest one there).
    A candidate beyond the +10% band is never returned. The pool
    is the same 10 fastest as the rescue pick, re-sorted cheapest
    first — the cap on attempts bounds the walk anyway.
    `allow_cover` is False until the server confirms it honours
    the cover (split_cover_live): without it only a service
    costing at most the confirmed total is returned.
    Cancel-cutting (16 Nov 2026): `reliability` / `paused` /
    `balance_health` ride the pick (see pick_services) — the
    filters (unreliable / paused / low-balance-provider skips)
    survive the cheapest re-sort below; the trust ordering does
    not (the retry walks cheapest-first by design). `total_qty`
    is the quantity for the unproven small-order cap."""
    platform, hint = _platform_hint_of_service(service or {})
    picks = pick_services(
        services or [], platform=platform, service_hint=hint,
        limit=RESCUE_CANDIDATE_LIMIT,
        reliability=reliability, paused=paused,
        balance_health=balance_health, quantity=total_qty,
        story=story,
    )
    failed = _failed_combined_ids(service, failed_services)
    candidates = [
        p for p in picks
        if service_combined_id(p) not in failed
        and split_test_quantities(total_qty, p) is not None
    ]
    candidates.sort(
        key=lambda p: estimated_total_etb(
            float(p.get("rate_etb_per_1000") or 0), total_qty
        )
    )
    max_cover = round(
        float(confirmed_total) * SPLIT_COVER_MAX_FRACTION, 2
    )
    for pick in candidates:
        full = estimated_total_etb(
            float(pick.get("rate_etb_per_1000") or 0), total_qty
        )
        cover = round(max(0.0, full - float(confirmed_total)), 2)
        if cover == 0.0:
            return pick, 0.0
        if allow_cover and cover <= max_cover:
            return pick, cover
    return None, 0.0


def _split_replacement_kwargs(watched):
    """Split markers for a replacement of a split remainder leg
    (15 Nov 2026): the replacement is still the remainder of the
    same split order, so it carries the same group id, the
    "remainder" part, and the confirmed total — the server
    records it on the order row and the mini-app history shows
    it as part of the split. {} for a non-split order (or a
    split order without a group), so plain rescues are unchanged.
    No cover rides here: the plain rescue's price cap already
    holds the replacement at or below the remainder's own cost."""
    split_ctx = (watched or {}).get("split") or {}
    if not split_ctx.get("group_id"):
        return {}
    return {
        "split_group_id": split_ctx.get("group_id"),
        "split_part": "remainder",
        "confirmed_total_etb": split_ctx.get("confirmed_total"),
    }


def _split_test_admin_text(order_id, service, test_qty, refunded,
                           failed, next_step, cost=None):
    """The admin message for a stuck split test (owner, 15 Nov
    2026): order id, service, quantity, cost, and what the bot
    did next — so William can cancel it manually if the
    automatic cancel did not go through. English only, never
    names the provider. `refunded` is None when nothing was
    refunded yet (the automatic cancel did not go through) — the
    message then says so plainly instead of claiming a refund;
    `cost` is the test order's total for the parenthetical, and
    defaults to the refunded figure."""
    amount = cost if cost is not None else refunded
    if refunded is None:
        money = "Not refunded yet, please cancel it manually."
    else:
        money = f"Refunded {format_money(refunded)} ETB."
    return (
        f"⚠️ Split test {'failed' if failed else 'stalled'}: "
        f"order #{order_id}, "
        f"{short_service_name(service.get('name')) or 'service'} "
        f"×{int(test_qty or 0)} ({format_money(amount or 0)} ETB). "
        f"{money} {next_step}"
    )


def _next_rescue_service(services, service, failed_services,
                         max_total=None, quantity=0, cheapest_first=False,
                         user_id=None, reliability=None, paused=None,
                         balance_health=None, story=None):
    """The next-best service for a stalled order: the same platform
    + metric, fastest first (reuse pick_services), excluding every
    service that already stalled in this chain — not just the latest
    one, or the second rescue would go back to the first failure.
    Returns None when no service is left. `failed_services` holds
    COMBINED ids ("gop:<id>" / "smm:<id>", second provider, 15 Nov
    2026) — a bare id in there is treated as a GOP id, so it
    can never wrongly exclude the other provider's service of the
    same number; the caller records combined ids.

    Price cap (owner rule, 15 Nov 2026): when `max_total` is set,
    only a service whose total for `quantity` is at most
    `max_total` is returned — the fastest AFFORDABLE service,
    across both providers. A pricier candidate is skipped, not
    an attempt: skipping never consumes a rescue. With no cap
    (max_total None) the pick is the old fastest-first one.
    `cheapest_first` (small-order +10% band, 15 Nov 2026) sorts
    the survivors cheapest first instead — used only for the
    Paxyo-paid band, where the cheapest service in the band costs
    Paxyo the least. The default pick stays fastest-first: the
    standing fulfilment rule, pinned by the cross-provider tests,
    and fastest-vs-cheapest is a per-customer setting William
    approved separately (customizations #4, 15 Nov 19:57 EAT), not
    a change to the default — when the customer set cheapest-first,
    `user_id` carries it and the affordable tier sorts cheapest
    first too.
    Cancel-cutting (16 Nov 2026): `reliability` / `paused` /
    `balance_health` ride the pick (see pick_services) — trusted
    first, unreliable / paused / low-balance-provider services
    skipped; `quantity` doubles as the unproven small-order cap.
    A quantity of 0 (the "any service at all" checks) lifts the
    cap, so the check stays permissive."""
    platform, hint = _platform_hint_of_service(service or {})
    picks = pick_services(
        services or [], platform=platform, service_hint=hint,
        limit=RESCUE_CANDIDATE_LIMIT,
        reliability=reliability, paused=paused,
        balance_health=balance_health, quantity=quantity,
        story=story,
    )
    failed = _failed_combined_ids(service, failed_services)
    candidates = [
        pick for pick in picks
        if service_combined_id(pick) not in failed
    ]
    # Cheapest-first (#4): the +10% band sorts cheapest first,
    # and so does the affordable tier when the customer set
    # cheapest-first. The default stays fastest-first.
    if cheapest_first or (
        user_id is not None and pref_pick_order(user_id) == "cheapest"
    ):
        candidates.sort(
            key=lambda p: estimated_total_etb(
                float(p.get("rate_etb_per_1000") or 0), quantity
            )
        )
    for pick in candidates:
        if max_total is not None:
            total = estimated_total_etb(
                float(pick.get("rate_etb_per_1000") or 0), quantity
            )
            if total > float(max_total):
                continue
        return pick
    return None


def _rescue_with_cover(services, service, failed_services, quantity,
                       confirmed_total, allow_cover=True, user_id=None,
                       reliability=None, paused=None,
                       balance_health=None, story=None):
    """The rescue pick with the Paxyo +10% band (owner, 15 Nov
    2026 — small orders, and the split-test path's own pick is
    _next_split_service): first the fastest service costing at
    most the confirmed total — the cheaper tier is tried first,
    so a rescue never goes pricier while an affordable service
    exists. Only when no affordable service exists, the CHEAPEST
    service costing up to 10% above the confirmed total, with
    cover = the excess over the confirmed total (Paxyo's pocket —
    the customer still pays only the confirmed total). Returns
    (service, cover) or (None, 0.0); cover is 0 in the cheaper
    tier. `allow_cover` is False until the server confirms it
    honours the cover (split_cover_live) — without it only a
    service costing at most the confirmed total is returned, the
    old strict-cap behaviour. A candidate beyond the +10% band is
    never returned. `user_id` carries the cheapest-first pref
    (#4) into the affordable tier — the band is cheapest-first
    already. Cancel-cutting (16 Nov 2026): `reliability` /
    `paused` / `balance_health` ride both tiers (see
    _next_rescue_service)."""
    nxt = _next_rescue_service(
        services, service, failed_services,
        max_total=confirmed_total, quantity=quantity,
        user_id=user_id,
        reliability=reliability, paused=paused,
        balance_health=balance_health, story=story,
    )
    if nxt is not None:
        return nxt, 0.0
    if not allow_cover:
        return None, 0.0
    band_max = round(
        float(confirmed_total) * (1 + SPLIT_COVER_MAX_FRACTION), 2
    )
    nxt = _next_rescue_service(
        services, service, failed_services,
        max_total=band_max, quantity=quantity, cheapest_first=True,
        user_id=user_id,
        reliability=reliability, paused=paused,
        balance_health=balance_health, story=story,
    )
    if nxt is None:
        return None, 0.0
    cover = round(
        max(
            0.0,
            estimated_total_etb(
                float(nxt.get("rate_etb_per_1000") or 0), quantity
            ) - float(confirmed_total),
        ),
        2,
    )
    return nxt, cover


def _rescue_cover_kwargs(watched, confirmed_total, cover):
    """The extra order fields for a rescue replacement that uses
    the Paxyo cover (15 Nov 2026): the confirmed total and the
    cover, on top of whatever split markers the order already
    carries (a split remainder leg keeps its group id and part).
    {} when there is no cover — a plain rescue sends nothing
    extra. The server validates cover <= 10% of the confirmed
    total and debits total - cover, so the customer still pays
    only the confirmed total."""
    if not cover or cover <= 0:
        return _split_replacement_kwargs(watched)
    kwargs = dict(_split_replacement_kwargs(watched))
    kwargs["confirmed_total_etb"] = float(confirmed_total)
    kwargs["paxyo_cover_etb"] = float(cover)
    return kwargs


async def _propose_rescue(app, order_id, watched, nxt, cover, kind,
                          price=None, refunded=None, failed=False):
    """Ask-first (#6, customizations, 15 Nov 2026): ask the
    customer before moving a stuck order to another service, and
    WAIT for their answer. Stores the proposal on the watch entry
    (so the Yes/No callback can execute it), sends the ask with
    Yes/No buttons, and marks the entry warned — the ask IS the
    notice, so no stuck warning follows while the customer is
    deciding. Returns True (the caller treats it as handled).
    `kind` is "stall", "failed" or "split_test"; `price` is the
    figure the move would cost (the full new total, or the new
    test leg's cost for a split test); `refunded` is the amount
    already refunded (failed rescues only — the money is back
    before the question is asked)."""
    user_id = watched.get("user_id")
    if price is None:
        price = estimated_total_etb(
            float(nxt.get("rate_etb_per_1000") or 0),
            watched.get("quantity") or 0,
        )
    watched["rescue_proposal"] = {
        "kind": kind,
        "service": service_combined_id(nxt),
        "cover": cover,
        "refunded": refunded,
        "failed": bool(failed),
    }
    watched["warned"] = True
    lang = LAST_LANG.get(user_id, "en")
    await notify_user(
        app, user_id,
        t(
            "rescue_ask", lang,
            order=order_id,
            name=short_service_name(nxt.get("name"))
            or f"service {nxt.get('service')}",
            time=nxt.get("average_time") or "?",
            price=format_money(price),
        ),
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton(
                "✅ Yes, move it",
                callback_data=f"rescue_yes:{order_id}",
            ),
            InlineKeyboardButton(
                "❌ No, refund me",
                callback_data=f"rescue_no:{order_id}",
            ),
        ]]),
    )
    return True


def _resolve_proposal_service(services, service, failed_services,
                              proposal, quantity, confirmed_total,
                              allow_cover, reliability=None, paused=None,
                              balance_health=None, story=None):
    """The service a rescue proposal named, when it is still usable
    (in the catalogue, active, not failed in this chain, not paused
    since the proposal was made, and its total fits the confirmed
    total or the +10% band) — else a fresh pick via
    _rescue_with_cover. Returns (service, cover). The caller
    passes the pref-filtered pool, so a proposed service the
    customer's own rules now exclude is never used. Cancel-cutting
    (16 Nov 2026): `reliability` / `paused` / `balance_health`
    ride the fresh pick."""
    wanted = (proposal or {}).get("service")
    candidate = None
    for svc in services or []:
        if service_combined_id(svc) == wanted:
            candidate = svc
            break
    if candidate is not None and candidate.get("active", True):
        failed = _failed_combined_ids(service, failed_services)
        if service_combined_id(candidate) not in failed:
            # A pause that started while the customer was deciding
            # beats the proposal: the service is not used, and the
            # fresh pick below finds the next best instead.
            if paused and service_combined_id(candidate) in paused:
                candidate = None
            else:
                total = estimated_total_etb(
                    float(candidate.get("rate_etb_per_1000") or 0),
                    quantity,
                )
                cover = round(
                    max(0.0, total - float(confirmed_total)), 2
                )
                max_cover = round(
                    float(confirmed_total) * SPLIT_COVER_MAX_FRACTION, 2
                )
                if cover == 0.0 or (allow_cover and cover <= max_cover):
                    return candidate, cover
    return _rescue_with_cover(
        services, service, failed_services, quantity,
        confirmed_total, allow_cover=allow_cover,
        reliability=reliability, paused=paused,
        balance_health=balance_health, story=story,
    )


async def _decline_rescue_proposal(app, order_id, watched, proposal):
    """The customer said NO to a rescue move: refund the order and
    drop the entry. A "failed" rescue is already refunded, so
    there is nothing more to do there. A stalled order (or a
    stalled/failed split test) is refunded now — cancel-refund
    for a stall, fail-refund for a failed test — and William gets
    the admin alert for a split test, as he does for every stuck
    test. When the refund cannot be made yet, the entry stays
    watched and the customer is told plainly. Returns the message
    text to show the customer (the caller edits the ask message
    with it, so the answer never arrives as a second message)."""
    user_id = watched.get("user_id")
    kind = (proposal or {}).get("kind")
    lang = LAST_LANG.get(user_id, "en")
    if kind == "failed":
        WATCHED_ORDERS.pop(order_id, None)
        return t("rescue_declined", lang)
    service = watched.get("service") or {}
    test_qty = watched.get("quantity") or 0
    try:
        if kind == "split_test" and (proposal or {}).get("failed"):
            refund = await paxyo.fail_refund(order_id, user_id)
        else:
            refund = await paxyo.cancel_refund(order_id, user_id)
    except Exception as exc:
        log.warning(
            "rescue decline %s: refund failed: %s", order_id, exc
        )
        refund = None
    if not refund:
        return t("rescue_refund_failed", lang, order=order_id)
    if kind == "split_test":
        split = watched.get("split") or {}
        await notify_admins(
            app,
            _split_test_admin_text(
                order_id, service, test_qty,
                (refund or {}).get("refunded_etb"),
                (proposal or {}).get("failed", False),
                "The customer said no to a new test, refunded.",
                cost=watched.get("total"),
            ),
        )
    WATCHED_ORDERS.pop(order_id, None)
    return t("rescue_declined", lang)


def _resolve_split_proposal(services, service, failed_services,
                            proposal, total_qty, confirmed_total,
                            allow_cover, reliability=None, paused=None,
                            balance_health=None, story=None):
    """The service a split-test proposal named, when it is still
    usable (in the catalogue, active, not failed in this chain,
    not paused since the proposal was made, and the order can be
    split on it) — else a fresh pick via _next_split_service.
    Returns (service, cover). Cancel-cutting (16 Nov 2026):
    `reliability` / `paused` / `balance_health` ride the fresh
    pick."""
    wanted = (proposal or {}).get("service")
    candidate = None
    for svc in services or []:
        if service_combined_id(svc) == wanted:
            candidate = svc
            break
    if (
        candidate is not None
        and candidate.get("active", True)
        and service_combined_id(candidate) not in _failed_combined_ids(
            service, failed_services
        )
        and not (paused and service_combined_id(candidate) in paused)
        and split_test_quantities(total_qty, candidate) is not None
    ):
        full = estimated_total_etb(
            float(candidate.get("rate_etb_per_1000") or 0), total_qty
        )
        cover = round(max(0.0, full - float(confirmed_total)), 2)
        max_cover = round(
            float(confirmed_total) * SPLIT_COVER_MAX_FRACTION, 2
        )
        if cover == 0.0 or (allow_cover and cover <= max_cover):
            return candidate, cover
    return _next_split_service(
        services, service, failed_services, total_qty,
        confirmed_total, allow_cover=allow_cover,
        reliability=reliability, paused=paused,
        balance_health=balance_health, story=story,
    )


async def _attempt_stall_rescue(app, order_id, watched, services=None,
                               proposal=None):
    """Try to rescue one stuck order: cancel + refund it, then place
    the same order on the next-best service. Returns True when the
    rescue happened (rescue message sent, old id dropped, new id
    watched); False on any failure — the caller then sends the
    normal stuck warning instead, and never retries this order.
    Never raises.

    No Confirm card: the user already confirmed this order, and the
    rescue only carries it out on the next service — the same
    fulfilment design as HANDOVER.md section 1 (the bot moves a
    stalled order to the next service). The replacement is placed
    with a FRESH idempotency key, never the original order's key,
    or the server would return the duplicate instead of a new
    order. Prices always come from the catalogue (pick_services /
    the service rate) — never from the AI, and nothing about the
    provider is ever named to the user. Price cap (owner rule,
    15 Nov 2026, extended with the +10% Paxyo band the same day):
    the replacement costs at most the amount the user confirmed —
    the pick tries the cheaper tier first, and only when no
    service fits the confirmed total does it use a service up to
    10% above it, the extra covered by Paxyo (the customer still
    pays only the confirmed total). When every remaining service
    costs more than the confirmed total plus 10%, the order is
    refunded in full with a plain message instead of being moved.
    Skipping a pricier candidate is not a rescue attempt. The
    band does NOT apply to a split remainder leg: its cover
    fields would overwrite the split group's confirmed total on
    the order row, so a remainder rescue keeps the strict cap
    (the remainder leg's own total).

    Ask-first (#6, customizations, 15 Nov 2026): when the
    customer set it, the rescue is PROPOSED first (see
    _propose_rescue) and nothing is refunded or moved until they
    answer. `proposal` is the accepted proposal (from the Yes
    callback) — the proposed service is used when it is still
    usable, else a fresh pick is made and named in the rescue
    message."""
    user_id = watched.get("user_id")
    service = watched.get("service") or {}
    quantity = watched.get("quantity") or 0
    link = watched.get("link")
    # Find the replacement FIRST: when no next service exists the
    # order is left alone (still pending, still refundable later)
    # and the caller sends the stuck warning instead of cancelling
    # an order that cannot be replaced. The pick is price-capped
    # (owner rule, 15 Nov 2026, with the +10% Paxyo band): the
    # cheaper tier first, then the cheapest service up to 10%
    # above the confirmed total with Paxyo covering the extra.
    # The cover is only offered when the server confirms it
    # honours it (split_cover_live) — a cover the server ignores
    # would debit the full cost. A split remainder leg never uses
    # the band (see the docstring): its own total stays the cap.
    if services is None:
        try:
            services = await paxyo.services()
        except Exception as exc:
            log.warning(
                "stall rescue %s: services fetch failed: %s", order_id, exc
            )
            return False
    # Per-customer prefs (#8, #14, #20): a rescue replacement must
    # still fit what the customer set — max slowness, refill-only,
    # delivery deadline. The price ceiling is NOT filtered here:
    # the confirmed-total cap below already enforces it (see
    # filter_pref_candidates).
    services, _ = filter_pref_candidates(
        services, user_id,
        deadline=_deadline_from_draft(watched.get("deadline")),
        skip_ceiling=True,
    )
    confirmed_total = _rescue_price_cap(watched, service, quantity)
    try:
        cover_live = await paxyo.split_cover_live()
    except Exception:
        cover_live = False
    allow_cover = (watched.get("split") or {}).get("leg") != "remainder"
    # Cancel-cutting (16 Nov 2026): the rescue pick rides the
    # merged ranking (trusted first, unreliable / paused /
    # low-balance-provider services skipped).
    _rel, _paused, _health = await _pick_context()
    # Story/post (16 Nov 2026): the rescue pick rides
    # the same link type as the order - a post link
    # never rescues onto a story service.
    _story = _story_flag(
        link,
        _platform_hint_of_service(service or {})[1],
    )
    if proposal is not None:
        # The customer already said yes: use the proposed service
        # when it is still usable, else re-pick (and name the new
        # service in the rescue message below).
        nxt, cover = _resolve_proposal_service(
            services, service, watched.get("failed_services"),
            proposal, quantity, confirmed_total,
            cover_live and allow_cover,
            reliability=_rel, paused=_paused, balance_health=_health, story=_story,
        )
    else:
        nxt, cover = _rescue_with_cover(
            services, service, watched.get("failed_services"), quantity,
            confirmed_total, allow_cover=cover_live and allow_cover,
            user_id=user_id,
            reliability=_rel, paused=_paused, balance_health=_health, story=_story,
        )
        if nxt is not None and pref_ask_first(user_id):
            # Ask-first (#6): propose the move and wait — nothing
            # is refunded or placed until the customer answers.
            return await _propose_rescue(
                app, order_id, watched, nxt, cover, "stall"
            )
    pricier_only = False
    _link_mismatch = False
    if nxt is None:
        # No affordable service — but is there any service at all?
        # None at all: leave the order alone, as before. Services
        # that exist but all cost more than the confirmed total
        # plus the 10% band: refund in full and tell the user
        # plainly instead of the generic stuck warning.
        if _next_rescue_service(
            services, service, watched.get("failed_services"),
            reliability=_rel, paused=_paused, balance_health=_health, story=_story,
        ) is None:
            log.warning("stall rescue %s: no next service", order_id)
            return False
        pricier_only = True
    if nxt is not None:
        # Link check (cancel-cutting item 5, 16 Nov 2026): the
        # replacement service must fit the link the user gave —
        # before any money moves. A mismatch means the order
        # should never have been placed on this kind of service:
        # refund it in full below and ask for the right link
        # instead of moving it.
        _link_error = validate_order_link(link, nxt)
        if _link_error is not None:
            _link_mismatch = True
            nxt = None
    # The bot itself is asking for this cancel (cancel-cutting
    # item 4): mark the entry BEFORE the call, so the watch never
    # mistakes the provider word "cancelled" that follows for a
    # provider cancel and tries to rescue it again.
    watched["bot_requested_cancel"] = True
    try:
        refund = await paxyo.cancel_refund(order_id, user_id)
    except Exception as exc:
        log.warning(
            "stall rescue %s: cancel-refund failed: %s", order_id, exc
        )
        return False
    if not refund:
        # None: the endpoint is not live yet (404) — nothing was
        # refunded, nothing to move. The stuck warning covers it.
        return False
    refunded = refund.get("refunded_etb")
    if refunded is None:
        # The server refunds the full stored total; the watch entry
        # keeps it, so the message still states the real figure.
        refunded = watched.get("total")
    if refunded is None:
        refunded = estimated_total_etb(
            float(service.get("rate_etb_per_1000") or 0), quantity
        )
    if pricier_only:
        # Refunded in full, no replacement: the next services all
        # cost more than the confirmed amount, so the bot does not
        # move the order. Resolved — the caller sends no stuck
        # warning for this episode.
        await notify_user(
            app, user_id,
            t(
                "order_rescue_pricier", "en",
                order_id=order_id,
                service=short_service_name(service.get("name"))
                or f"service {service.get('service')}",
                quantity=int(quantity or 0),
                refunded=format_money(refunded),
            ),
        )
        WATCHED_ORDERS.pop(order_id, None)
        return True
    if _link_mismatch:
        # Refunded in full, no replacement: the link does not fit
        # this kind of service, so the order cannot be moved —
        # say so plainly and ask for the right link, so the user
        # can order again with a link that fits.
        _platform, _hint = _platform_hint_of_service(service or {})
        await notify_user(
            app, user_id,
            t(
                "order_rescue_link_mismatch", "en",
                order_id=order_id,
                service=short_service_name(service.get("name"))
                or f"service {service.get('service')}",
                quantity=int(quantity or 0),
                refunded=format_money(refunded),
            )
            + "\n"
            + ask_link_text(_platform, _hint, "en"),
        )
        WATCHED_ORDERS.pop(order_id, None)
        return True
    new_total = estimated_total_etb(
        float(nxt.get("rate_etb_per_1000") or 0), quantity
    )
    # The refund was just credited, and the replacement costs at
    # most the refunded amount plus the Paxyo cover (price cap
    # above), so this check normally passes — it stays as a guard
    # for a balance read that fails or disagrees, and then no
    # order is placed. With a cover the server debits new_total -
    # cover, so the balance only needs to cover that part.
    try:
        bal = await paxyo.balance(user_id)
    except Exception as exc:
        log.warning(
            "stall rescue %s: balance check failed: %s", order_id, exc
        )
        return False
    need = round(new_total - cover, 2)
    if not bal.get("found") or float(bal.get("balance", 0)) < need:
        log.warning(
            "stall rescue %s: balance too low for replacement (%s < %s)",
            order_id, bal.get("balance", 0), need,
        )
        return False
    try:
        result = await create_order_for_service(
            paxyo, user_id, nxt, link, quantity, uuid.uuid4().hex,
            split=_rescue_cover_kwargs(watched, confirmed_total, cover),
        )
    except Exception as exc:
        log.warning(
            "stall rescue %s: replacement failed: %s", order_id, exc
        )
        return False
    order = result.get("order", result) if isinstance(result, dict) else {}
    new_id = order.get("id") or order.get("order_id") or "?"
    # The server computes the real total; use it when the reply
    # carries it, else the catalogue estimate above.
    server_total = order.get("total", order.get("charge"))
    if server_total is not None:
        try:
            new_total = round(float(server_total), 2)
        except (TypeError, ValueError):
            pass
    # Watch the replacement like any placed order: it gets its own
    # delivery message, and if it stalls too it can be rescued once
    # more — up to MAX_STALL_RESCUES for the whole chain.
    failed = list(watched.get("failed_services") or [])
    # Record the stalled service by COMBINED id ("gop:<id>" /
    # "smm:<id>", second provider, 15 Nov 2026): a bare id could
    # never tell the providers apart, and the next rescue must not
    # exclude the other provider's service of the same number.
    failed.append(service_combined_id(service))
    WATCHED_ORDERS.pop(order_id, None)
    LAST_ORDER[user_id] = new_id
    watch_order(
        user_id, new_id, nxt, quantity, link,
        total=new_total,
        rescue_count=(watched.get("rescue_count") or 0) + 1,
        failed_services=failed,
        split=watched.get("split"),
        deadline=watched.get("deadline"),
    )
    rescued_text = t(
        "order_rescued", "en",
        old_order_id=order_id,
        old_service=short_service_name(service.get("name"))
        or f"service {service.get('service')}",
        quantity=int(quantity or 0),
        refunded=format_money(refunded),
        new_service=short_service_name(nxt.get("name"))
        or f"service {nxt.get('service')}",
        new_order_id=new_id,
        new_total=format_money(new_total),
    )
    if cover > 0:
        # The new order costs more than the refunded one — say
        # plainly that Paxyo covers the extra, so the user never
        # reads the higher figure as a charge to them.
        rescued_text += "\n" + t(
            "order_rescue_cover_note", "en",
            cover=format_money(cover),
            confirmed=format_money(refunded),
        )
    await notify_user(app, user_id, rescued_text)
    return True


# How long the failed-rescue waits between fail-refund attempts for
# one order (seconds). The server's fail-refund is idempotent, so a
# retry is safe — but the provider status is re-read on every try,
# so attempts are throttled like the partial-refund path's.
FAIL_REFUND_RETRY_SECONDS = 3600


async def _attempt_failed_rescue(app, order_id, watched, services=None,
                                 now=None, proposal=None):
    """Try to rescue one provider-FAILED order: refund it via POST
    /orders/{id}/fail-refund, then place the same order on the
    next-best service. Returns True when the entry is resolved
    (rescued, refunded with no replacement, or the user was told
    honestly and the entry dropped); False when the caller should
    keep watching (throttled, or a transient failure — the next
    cycle retries). Never raises.

    Cancel-cutting item 4 (16 Nov 2026): a PROVIDER-cancelled
    order ("cancelled"/"canceled" from the provider) goes through
    this same path — the watch only calls it when the entry is NOT
    marked bot_requested_cancel, so an order the bot cancelled
    itself (stall rescue, auto-cancel) or the user asked to cancel
    never reaches here; those are refunded by the cancel endpoint
    instead. "Refunded" (already refunded) is never rescued. The
    server re-reads the LIVE provider status itself and refunds
    only when the provider word is failed / canceled / cancelled,
    so a stale "failed" from the watch cannot refund an order the
    provider later completed: on a 409 the entry stays watched and
    the next cycle re-reads the status. A 404 (endpoint not live
    yet) tells the user honestly once and keeps watching — if the
    endpoint is installed later, the next hourly retry refunds and
    rescues. The refund is the FULL stored total, and the server
    records it once ever (duplicate calls return the recorded
    refund), so retrying after a successful refund is safe. A
    stored 'cancelled' order the server refuses (its cancel path
    already refunded it) surfaces the same way — the server's
    fail-refund file must be the patched one (see HANDOVER.md)
    for provider-cancelled refunds to work at all.

    No Confirm card: the user already confirmed this order, and the
    rescue only carries it out on the next service — the same
    fulfilment design as the stall rescue. The replacement is placed
    with a FRESH idempotency key, never the original order's key.
    Prices always come from the catalogue — never from the AI, and
    nothing about the provider is ever named to the user. Price cap
    (owner rule, 15 Nov 2026, extended with the +10% Paxyo band the
    same day): the replacement costs at most the amount the user
    confirmed — the pick tries the cheaper tier first, and only
    when no service fits the confirmed total does it use a service
    up to 10% above it, the extra covered by Paxyo (the customer
    still pays only the confirmed total). When every remaining
    service costs more than the confirmed total plus 10%, the order
    stays refunded in full with a plain message instead of being
    moved. Skipping a pricier candidate is not a rescue attempt.
    The band does NOT apply to a split remainder leg (its cover
    fields would overwrite the split group's confirmed total).

    Ask-first (#6, customizations, 15 Nov 2026): the refund
    happens first (a failed order's money is returned whatever
    the customer decides), and the REPLACEMENT is proposed — the
    question is asked only once the money is back. `proposal` is
    the accepted proposal (from the Yes callback). A proposal
    already waiting on the entry means the answer has not come
    yet: the attempt returns True (handled — waiting), so the
    watch cycle does not ask again."""
    user_id = watched.get("user_id")
    service = watched.get("service") or {}
    quantity = watched.get("quantity") or 0
    link = watched.get("link")
    if proposal is None and watched.get("rescue_proposal"):
        return True
    if now is None:
        now = time.time()
    # Throttle: one fail-refund attempt per hour per order — unless
    # a refund is already recorded (fail_refund_done), in which
    # case the retry returns the recorded refund at once and the
    # rescue can proceed to the replacement immediately.
    last_try = watched.get("fail_refund_attempted_at") or 0
    if last_try and not watched.get("fail_refund_done"):
        if now - last_try < FAIL_REFUND_RETRY_SECONDS:
            return False
    watched["fail_refund_attempted_at"] = now
    try:
        refund = await paxyo.fail_refund(order_id, user_id)
    except Exception as exc:
        log.warning(
            "failed rescue %s: fail-refund failed: %s", order_id, exc
        )
        conflicts = (watched.get("fail_refund_conflicts") or 0) + 1
        watched["fail_refund_conflicts"] = conflicts
        if conflicts >= 2 and not watched.get("fail_refund_unclear_sent"):
            watched["fail_refund_unclear_sent"] = True
            await notify_user(
                app, user_id,
                t(
                    "order_failed_unclear", "en",
                    order_id=order_id,
                    service=short_service_name(service.get("name"))
                    or f"service {service.get('service')}",
                    quantity=int(quantity or 0),
                ),
            )
        # Keep watching: the next cycle re-reads the status — a
        # provider word of "completed" still gets its delivery
        # message, and the hourly retry re-attempts the refund.
        return False
    if not refund:
        # None: the endpoint is not live yet (404) — nothing was
        # refunded. Tell the user once, honestly, and keep
        # watching: if the endpoint is installed later, the next
        # hourly retry refunds and rescues.
        if not watched.get("fail_refund_not_live_sent"):
            watched["fail_refund_not_live_sent"] = True
            await notify_user(
                app, user_id,
                t(
                    "order_failed_no_refund", "en",
                    order_id=order_id,
                    service=short_service_name(service.get("name"))
                    or f"service {service.get('service')}",
                    quantity=int(quantity or 0),
                ),
            )
        return False
    watched["fail_refund_done"] = True
    refunded = refund.get("refunded_etb")
    if refunded is None:
        # The server refunds the full stored total; the watch entry
        # keeps it, so the message still states the real figure.
        refunded = watched.get("total")
    if refunded is None:
        refunded = estimated_total_etb(
            float(service.get("rate_etb_per_1000") or 0), quantity
        )

    async def _refunded_no_replacement():
        await notify_user(
            app, user_id,
            t(
                "order_failed_refunded", "en",
                order_id=order_id,
                service=short_service_name(service.get("name"))
                or f"service {service.get('service')}",
                quantity=int(quantity or 0),
                refunded=format_money(refunded),
            ),
        )
        WATCHED_ORDERS.pop(order_id, None)
        return True

    async def _refunded_pricier():
        # Refunded in full, no replacement: the next services all
        # cost more than the confirmed amount, so the bot does not
        # move the order. The refund figure and the plain reason
        # are both stated.
        await notify_user(
            app, user_id,
            t(
                "order_failed_refunded_pricier", "en",
                order_id=order_id,
                service=short_service_name(service.get("name"))
                or f"service {service.get('service')}",
                quantity=int(quantity or 0),
                refunded=format_money(refunded),
            ),
        )
        WATCHED_ORDERS.pop(order_id, None)
        return True

    # The refund is done even when no replacement follows — the cap
    # limits RE-PLACEMENT attempts, never the refund itself.
    if (watched.get("rescue_count") or 0) >= MAX_STALL_RESCUES:
        log.warning(
            "failed rescue %s: rescue cap reached, refund only",
            order_id,
        )
        return await _refunded_no_replacement()
    if services is None:
        try:
            services = await paxyo.services()
        except Exception as exc:
            log.warning(
                "failed rescue %s: services fetch failed: %s",
                order_id, exc,
            )
            return await _refunded_no_replacement()
    # Per-customer prefs (#8, #14, #20): a rescue replacement must
    # still fit what the customer set — max slowness, refill-only,
    # delivery deadline. The price ceiling is NOT filtered here:
    # the confirmed-total cap below already enforces it (see
    # filter_pref_candidates).
    services, _ = filter_pref_candidates(
        services, user_id,
        deadline=_deadline_from_draft(watched.get("deadline")),
        skip_ceiling=True,
    )
    confirmed_total = _rescue_price_cap(watched, service, quantity)
    try:
        cover_live = await paxyo.split_cover_live()
    except Exception:
        cover_live = False
    allow_cover = (watched.get("split") or {}).get("leg") != "remainder"
    # Cancel-cutting (16 Nov 2026): the rescue pick rides the
    # merged ranking (trusted first, unreliable / paused /
    # low-balance-provider services skipped).
    _rel, _paused, _health = await _pick_context()
    # Story/post (16 Nov 2026): the rescue pick rides
    # the same link type as the order - a post link
    # never rescues onto a story service.
    _story = _story_flag(
        link,
        _platform_hint_of_service(service or {})[1],
    )
    if proposal is not None:
        # The customer already said yes: use the proposed service
        # when it is still usable, else re-pick.
        nxt, cover = _resolve_proposal_service(
            services, service, watched.get("failed_services"),
            proposal, quantity, confirmed_total,
            cover_live and allow_cover,
            reliability=_rel, paused=_paused, balance_health=_health, story=_story,
        )
    else:
        nxt, cover = _rescue_with_cover(
            services, service, watched.get("failed_services"), quantity,
            confirmed_total, allow_cover=cover_live and allow_cover,
            user_id=user_id,
            reliability=_rel, paused=_paused, balance_health=_health, story=_story,
        )
        if nxt is not None and pref_ask_first(user_id):
            # Ask-first (#6): the refund is already done — the
            # question is only whether to place the replacement.
            return await _propose_rescue(
                app, order_id, watched, nxt, cover, "failed",
                refunded=refunded,
            )
    if nxt is None:
        # No affordable service — but is there any service at all?
        # None at all: refund only, as before. Services that exist
        # but all cost more than the confirmed total plus the 10%
        # band: refund only, with the plain reason.
        if _next_rescue_service(
            services, service, watched.get("failed_services"),
            reliability=_rel, paused=_paused, balance_health=_health, story=_story,
        ) is not None:
            log.warning(
                "failed rescue %s: only pricier services remain",
                order_id,
            )
            return await _refunded_pricier()
        log.warning("failed rescue %s: no next service", order_id)
        return await _refunded_no_replacement()
    # Link check (cancel-cutting item 5, 16 Nov 2026): the
    # replacement service must fit the link the user gave — the
    # refund is already done, so a mismatch means refund-only
    # plus the right-link question, never a placement on a
    # service the link does not fit.
    if validate_order_link(link, nxt) is not None:
        _platform, _hint = _platform_hint_of_service(service or {})
        await notify_user(
            app, user_id,
            t(
                "order_failed_refunded", "en",
                order_id=order_id,
                service=short_service_name(service.get("name"))
                or f"service {service.get('service')}",
                quantity=int(quantity or 0),
                refunded=format_money(refunded),
            )
            + "\n"
            + ask_link_text(_platform, _hint, "en"),
        )
        WATCHED_ORDERS.pop(order_id, None)
        return True
    new_total = estimated_total_etb(
        float(nxt.get("rate_etb_per_1000") or 0), quantity
    )
    # The refund was just credited, and the replacement costs at
    # most the refunded amount plus the Paxyo cover (price cap
    # above), so this check normally passes — it stays as a guard
    # for a balance read that fails or disagrees, and then no
    # order is placed. With a cover the server debits new_total -
    # cover, so the balance only needs to cover that part.
    try:
        bal = await paxyo.balance(user_id)
    except Exception as exc:
        log.warning(
            "failed rescue %s: balance check failed: %s", order_id, exc
        )
        return await _refunded_no_replacement()
    need = round(new_total - cover, 2)
    if not bal.get("found") or float(bal.get("balance", 0)) < need:
        log.warning(
            "failed rescue %s: balance too low for replacement (%s < %s)",
            order_id, bal.get("balance", 0), need,
        )
        return await _refunded_no_replacement()
    try:
        result = await create_order_for_service(
            paxyo, user_id, nxt, link, quantity, uuid.uuid4().hex,
            split=_rescue_cover_kwargs(watched, confirmed_total, cover),
        )
    except Exception as exc:
        log.warning(
            "failed rescue %s: replacement failed: %s", order_id, exc
        )
        # The refund is recorded server-side (duplicate-safe), so
        # the next cycle retries the replacement on the same next
        # service instead of losing the order.
        return False
    order = result.get("order", result) if isinstance(result, dict) else {}
    new_id = order.get("id") or order.get("order_id") or "?"
    # The server computes the real total; use it when the reply
    # carries it, else the catalogue estimate above.
    server_total = order.get("total", order.get("charge"))
    if server_total is not None:
        try:
            new_total = round(float(server_total), 2)
        except (TypeError, ValueError):
            pass
    # Watch the replacement like any placed order: it gets its own
    # delivery message, and if it stalls or fails too it can be
    # rescued once more — up to MAX_STALL_RESCUES for the whole
    # chain.
    failed = list(watched.get("failed_services") or [])
    # Record the failed service by COMBINED id ("gop:<id>" /
    # "smm:<id>", second provider, 15 Nov 2026): a bare id could
    # never tell the providers apart, and the next rescue must not
    # exclude the other provider's service of the same number.
    failed.append(service_combined_id(service))
    WATCHED_ORDERS.pop(order_id, None)
    LAST_ORDER[user_id] = new_id
    watch_order(
        user_id, new_id, nxt, quantity, link,
        total=new_total,
        rescue_count=(watched.get("rescue_count") or 0) + 1,
        failed_services=failed,
        split=watched.get("split"),
        deadline=watched.get("deadline"),
    )
    rescued_text = t(
        "order_failed_rescued", "en",
        old_order_id=order_id,
        old_service=short_service_name(service.get("name"))
        or f"service {service.get('service')}",
        quantity=int(quantity or 0),
        refunded=format_money(refunded),
        new_service=short_service_name(nxt.get("name"))
        or f"service {nxt.get('service')}",
        new_order_id=new_id,
        new_total=format_money(new_total),
    )
    if cover > 0:
        # The new order costs more than the refunded one — say
        # plainly that Paxyo covers the extra, so the user never
        # reads the higher figure as a charge to them.
        rescued_text += "\n" + t(
            "order_rescue_cover_note", "en",
            cover=format_money(cover),
            confirmed=format_money(refunded),
        )
    await notify_user(app, user_id, rescued_text)
    return True


async def _place_split_remainder(app, test_order_id, watched):
    """Place the remaining 90% after a split test delivered, on the
    same service. Returns True always — the test entry is dropped
    either way, so the caller never replays it. Never raises.

    The remainder is watched like any placed order, with the split
    context carried forward (leg "remainder", spent = the delivered
    test's cost) so its delivery message states the full ordered
    quantity and the saving. When the remainder cannot be placed
    (balance short, cover not live yet, placement refused) the
    user is told honestly what happened to the delivered test and
    what to do — the test portion stays delivered and paid, the
    rest is simply not ordered."""
    user_id = watched.get("user_id")
    service = watched.get("service") or {}
    split = watched.get("split") or {}
    link = watched.get("link")
    rest_qty = split.get("rest_qty") or 0
    total_qty = split.get("total_qty") or watched.get("quantity") or 0
    test_qty = split.get("test_qty") or 0
    confirmed_total = float(split.get("confirmed_total") or 0)
    test_cost = float(watched.get("total") or 0)
    rest_cost = estimated_total_etb(
        float(service.get("rate_etb_per_1000") or 0), rest_qty
    )
    cover = split_leg_cover(confirmed_total, rest_qty, total_qty, rest_cost)
    need = round(rest_cost - cover, 2)
    try:
        bal = await paxyo.balance(user_id)
    except Exception as exc:
        log.warning(
            "split remainder %s: balance check failed: %s",
            test_order_id, exc,
        )
        await notify_user(
            app, user_id,
            t(
                "order_split_rest_failed", "en",
                test_quantity=int(test_qty or 0),
                quantity=int(total_qty or 0),
                rest_quantity=int(rest_qty or 0),
            ),
        )
        WATCHED_ORDERS.pop(test_order_id, None)
        return True
    if not bal.get("found") or float(bal.get("balance", 0)) < need:
        await notify_user(
            app, user_id,
            t(
                "order_split_rest_topup", "en",
                test_quantity=int(test_qty or 0),
                quantity=int(total_qty or 0),
                rest_quantity=int(rest_qty or 0),
                needed=format_money(need),
                balance=format_money(bal.get("balance", 0)),
            ),
        )
        WATCHED_ORDERS.pop(test_order_id, None)
        return True
    if cover > 0:
        # A cover above zero with the endpoint not live would debit
        # the full rest cost (overcharging the user when their
        # balance happens to cover it), so the remainder is only
        # placed with a cover the server confirms it supports.
        try:
            live = await paxyo.split_cover_live()
        except Exception:
            live = False
        if not live:
            await notify_user(
                app, user_id,
                t(
                    "order_split_rest_no_cover", "en",
                    test_quantity=int(test_qty or 0),
                    quantity=int(total_qty or 0),
                    rest_quantity=int(rest_qty or 0),
                ),
            )
            WATCHED_ORDERS.pop(test_order_id, None)
            return True
    split_kwargs = {
        "split_group_id": split.get("group_id"),
        "split_part": "remainder",
        "confirmed_total_etb": confirmed_total,
    }
    if cover > 0:
        split_kwargs["paxyo_cover_etb"] = cover
    try:
        result = await create_order_for_service(
            paxyo, user_id, service, link, rest_qty,
            f"split-rest-{uuid.uuid4().hex}",
            split=split_kwargs,
        )
    except Exception as exc:
        log.warning(
            "split remainder %s: placement failed: %s", test_order_id, exc
        )
        await notify_user(
            app, user_id,
            t(
                "order_split_rest_failed", "en",
                test_quantity=int(test_qty or 0),
                quantity=int(total_qty or 0),
                rest_quantity=int(rest_qty or 0),
            ),
        )
        WATCHED_ORDERS.pop(test_order_id, None)
        return True
    order = result.get("order", result) if isinstance(result, dict) else {}
    new_id = order.get("id") or order.get("order_id") or "?"
    # The server computes the real total; use it when the reply
    # carries it, else the catalogue estimate above.
    server_total = order.get("total", order.get("charge"))
    if server_total is not None:
        try:
            rest_cost = round(float(server_total), 2)
        except (TypeError, ValueError):
            pass
    failed = list(watched.get("failed_services") or [])
    WATCHED_ORDERS.pop(test_order_id, None)
    LAST_ORDER[user_id] = new_id
    watch_order(
        user_id, new_id, service, rest_qty, link,
        total=rest_cost,
        rescue_count=watched.get("rescue_count") or 0,
        failed_services=failed,
        split={
            "group_id": split.get("group_id"),
            "leg": "remainder",
            "total_qty": total_qty,
            "test_qty": test_qty,
            "rest_qty": rest_qty,
            "confirmed_total": confirmed_total,
            "spent": test_cost,
        },
        deadline=watched.get("deadline"),
    )
    await notify_user(
        app, user_id,
        t(
            "order_split_test_done", "en",
            test_quantity=int(test_qty or 0),
            quantity=int(total_qty or 0),
            rest_quantity=int(rest_qty or 0),
            new_order_id=new_id,
        ),
    )
    return True


async def _attempt_split_test_rescue(app, order_id, watched, services=None,
                                     now=None, failed=False, proposal=None):
    """Rescue one split-test leg that stalled (or failed at the
    provider): refund the test, tell William, and test the next
    service — cheapest first. Returns True when the entry is
    resolved (a new test is watched, or the user was told honestly
    and the entry dropped); False when the caller should keep
    watching (refund endpoint not live yet, or a transient failure
    before any refund). Never raises.

    A stalled test counts as an attempt under MAX_STALL_RESCUES
    like any rescue; skipping a service that is pricier than the
    confirmed total plus the 10% Paxyo tolerance is not an
    attempt. The test order is a real order the customer paid
    for, so it stays in the orders table (and the mini-app
    history) — the refund is a balance credit on it, not a
    deletion. William also gets an admin message for every stuck
    test, so he can cancel it manually if the automatic cancel
    did not go through. Nothing is returned False after the
    refund: once the money is back, the entry is always resolved
    with a plain message, never left to the generic stuck
    warning (which would claim an order is still being worked on
    after it was refunded).

    Ask-first (#6, customizations, 15 Nov 2026): when the
    customer set it, the next test is PROPOSED first and nothing
    is refunded or placed until they answer. `proposal` is the
    accepted proposal (from the Yes callback). A proposal already
    waiting on the entry means the answer has not come yet: the
    attempt returns True (handled — waiting), so the watch cycle
    does not ask again."""
    user_id = watched.get("user_id")
    service = watched.get("service") or {}
    split = watched.get("split") or {}
    test_qty = watched.get("quantity") or 0
    total_qty = split.get("total_qty") or test_qty
    confirmed_total = float(split.get("confirmed_total") or 0)
    link = watched.get("link")
    if proposal is None and watched.get("rescue_proposal"):
        return True
    if now is None:
        import time

        now = time.time()
    if services is None:
        try:
            services = await paxyo.services()
        except Exception as exc:
            log.warning(
                "split test rescue %s: services fetch failed: %s",
                order_id, exc,
            )
            return False
    # Per-customer prefs (#8, #14, #20): the next test must still
    # fit what the customer set — max slowness, refill-only,
    # delivery deadline. The price ceiling is NOT filtered here:
    # the confirmed-total + 10% band below already enforces it
    # (see filter_pref_candidates).
    services, _ = filter_pref_candidates(
        services, user_id,
        deadline=_deadline_from_draft(watched.get("deadline")),
        skip_ceiling=True,
    )
    # The next service is picked BEFORE the refund, so a pick that
    # needs the Paxyo cover can check the server honours it first
    # — a cover the server ignores would debit the full cost.
    try:
        cover_live = await paxyo.split_cover_live()
    except Exception:
        cover_live = False
    # Cancel-cutting (16 Nov 2026): the next test rides the merged
    # ranking (trusted first, unreliable / paused /
    # low-balance-provider services skipped).
    _rel, _paused, _health = await _pick_context()
    # Story/post (16 Nov 2026): the rescue pick rides
    # the same link type as the order - a post link
    # never rescues onto a story service.
    _story = _story_flag(
        link,
        _platform_hint_of_service(service or {})[1],
    )
    _link_mismatch = False
    if proposal is not None:
        # The customer already said yes: use the proposed service
        # when it is still usable, else re-pick.
        nxt, cover = _resolve_split_proposal(
            services, service, watched.get("failed_services"),
            proposal, total_qty, confirmed_total,
            allow_cover=cover_live,
            reliability=_rel, paused=_paused, balance_health=_health, story=_story,
        )
    else:
        nxt, cover = _next_split_service(
            services, service, watched.get("failed_services"), total_qty,
            confirmed_total, allow_cover=cover_live,
            reliability=_rel, paused=_paused, balance_health=_health, story=_story,
        )
    if nxt is not None and validate_order_link(link, nxt) is not None:
        # Link check (item 5): the link does not fit the next
        # service — refund the test below and ask for the right
        # link instead of testing a service the link does not fit.
        _link_mismatch = True
        nxt = None
    # Balance pre-check: the refund of this test (its stored total)
    # lands back first, so the new test is affordable when the
    # current balance plus that refund covers its cost after cover.
    test_total = watched.get("total")
    if test_total is None:
        test_total = estimated_total_etb(
            float(service.get("rate_etb_per_1000") or 0), test_qty
        )
    if nxt is not None:
        new_test_qty, _new_rest = split_test_quantities(total_qty, nxt)
        new_test_cost = estimated_total_etb(
            float(nxt.get("rate_etb_per_1000") or 0), new_test_qty
        )
        leg_cover = split_leg_cover(
            confirmed_total, new_test_qty, total_qty, new_test_cost
        )
        try:
            bal = await paxyo.balance(user_id)
        except Exception as exc:
            log.warning(
                "split test rescue %s: balance check failed: %s",
                order_id, exc,
            )
            return False
        available = float(bal.get("balance", 0)) + float(test_total or 0)
        if not bal.get("found") or available < round(
            new_test_cost - leg_cover, 2
        ):
            log.warning(
                "split test rescue %s: balance too low for next test "
                "(%s < %s)", order_id, available,
                round(new_test_cost - leg_cover, 2),
            )
            return False
    if nxt is not None and proposal is None and pref_ask_first(user_id):
        # Ask-first (#6): the next test is proposed only once the
        # balance pre-check passed — never ask about a move the
        # customer could not afford. Nothing is refunded or placed
        # until they answer.
        _new_test_qty, _ = split_test_quantities(total_qty, nxt)
        _new_test_cost = estimated_total_etb(
            float(nxt.get("rate_etb_per_1000") or 0), _new_test_qty
        )
        return await _propose_rescue(
            app, order_id, watched, nxt, cover, "split_test",
            price=_new_test_cost, failed=failed,
        )
    # Refund the test leg: cancel + refund when it stalled,
    # fail-refund when the provider ended it failed.
    if failed:
        # Throttle like the failed-rescue path: one fail-refund
        # attempt per hour per order.
        last_try = watched.get("fail_refund_attempted_at") or 0
        if last_try and not watched.get("fail_refund_done"):
            if now - last_try < FAIL_REFUND_RETRY_SECONDS:
                return False
        watched["fail_refund_attempted_at"] = now
        try:
            refund = await paxyo.fail_refund(order_id, user_id)
        except Exception as exc:
            log.warning(
                "split test rescue %s: fail-refund failed: %s",
                order_id, exc,
            )
            conflicts = (watched.get("fail_refund_conflicts") or 0) + 1
            watched["fail_refund_conflicts"] = conflicts
            if conflicts >= 2 and not watched.get(
                "fail_refund_unclear_sent"
            ):
                watched["fail_refund_unclear_sent"] = True
                # The provider will not confirm the failure, so
                # the refund cannot be made — William gets the
                # order details so he can check it manually.
                await notify_admins(
                    app,
                    _split_test_admin_text(
                        order_id, service, test_qty, None, failed,
                        "The provider will not confirm the "
                        "failure, so no refund could be made.",
                        cost=test_total,
                    ),
                )
                await notify_user(
                    app, user_id,
                    t(
                        "order_failed_unclear", "en",
                        order_id=order_id,
                        service=short_service_name(service.get("name"))
                        or f"service {service.get('service')}",
                        quantity=int(test_qty or 0),
                    ),
                )
            return False
        if not refund:
            # None: the endpoint is not live yet — tell the user
            # once, honestly, and keep watching: if the endpoint
            # is installed later, the next hourly retry refunds
            # and rescues. William is told too — the test order is
            # still open, so he can check it manually.
            if not watched.get("fail_refund_not_live_sent"):
                watched["fail_refund_not_live_sent"] = True
                await notify_admins(
                    app,
                    _split_test_admin_text(
                        order_id, service, test_qty, None, failed,
                        "The refund endpoint is not live yet — the "
                        "test order is still open.",
                        cost=test_total,
                    ),
                )
                await notify_user(
                    app, user_id,
                    t(
                        "order_failed_no_refund", "en",
                        order_id=order_id,
                        service=short_service_name(service.get("name"))
                        or f"service {service.get('service')}",
                        quantity=int(test_qty or 0),
                    ),
                )
            return False
        watched["fail_refund_done"] = True
    else:
        # The bot itself is asking for this cancel (cancel-cutting
        # item 4): mark the entry BEFORE the call, so the watch
        # never mistakes the provider word "cancelled" that
        # follows for a provider cancel and tries to rescue it
        # again.
        watched["bot_requested_cancel"] = True
        try:
            refund = await paxyo.cancel_refund(order_id, user_id)
        except Exception as exc:
            log.warning(
                "split test rescue %s: cancel-refund failed: %s",
                order_id, exc,
            )
            # The automatic cancel did not go through — William
            # gets the order details so he can cancel it manually.
            await notify_admins(
                app,
                _split_test_admin_text(
                    order_id, service, test_qty, None, failed,
                    "The automatic cancel did not go through.",
                    cost=test_total,
                ),
            )
            return False
        if not refund:
            # None: the endpoint is not live yet (404) — nothing
            # was refunded, nothing to move. William is told so
            # he can cancel it manually; the stuck warning covers
            # the user.
            await notify_admins(
                app,
                _split_test_admin_text(
                    order_id, service, test_qty, None, failed,
                    "The cancel endpoint is not live yet — the "
                    "test order is still open.",
                    cost=test_total,
                ),
            )
            return False
    refunded = refund.get("refunded_etb")
    if refunded is None:
        refunded = test_total
    if refunded is None:
        refunded = estimated_total_etb(
            float(service.get("rate_etb_per_1000") or 0), test_qty
        )
    capped = (watched.get("rescue_count") or 0) >= MAX_STALL_RESCUES
    if capped:
        # The refund still happens at the cap — the cap limits
        # RE-PLACEMENT attempts, never the refund itself.
        await notify_admins(
            app,
            _split_test_admin_text(
                order_id, service, test_qty, refunded, failed,
                "Rescue cap reached — refunded, no further tries.",
            ),
        )
        await notify_user(
            app, user_id,
            t(
                "order_split_cap_refunded", "en",
                order_id=order_id,
                service=short_service_name(service.get("name"))
                or f"service {service.get('service')}",
                test_quantity=int(test_qty or 0),
                refunded=format_money(refunded),
            ),
        )
        WATCHED_ORDERS.pop(order_id, None)
        return True
    if nxt is None:
        if _link_mismatch:
            # Link check (item 5): refunded, nothing placed — the
            # link does not fit this kind of service, so ask for
            # the right link instead of the generic no-service
            # message.
            _platform, _hint = _platform_hint_of_service(service or {})
            await notify_admins(
                app,
                _split_test_admin_text(
                    order_id, service, test_qty, refunded, failed,
                    "Link does not fit the next service — refunded, "
                    "nothing placed.",
                ),
            )
            await notify_user(
                app, user_id,
                t(
                    "order_rescue_link_mismatch", "en",
                    order_id=order_id,
                    service=short_service_name(service.get("name"))
                    or f"service {service.get('service')}",
                    quantity=int(total_qty or 0),
                    refunded=format_money(refunded),
                )
                + "\n"
                + ask_link_text(_platform, _hint, "en"),
            )
            WATCHED_ORDERS.pop(order_id, None)
            return True
        await notify_admins(
            app,
            _split_test_admin_text(
                order_id, service, test_qty, refunded, failed,
                "No service left within the price band — refunded, "
                "nothing placed.",
            ),
        )
        await notify_user(
            app, user_id,
            t(
                "order_split_no_service", "en",
                order_id=order_id,
                service=short_service_name(service.get("name"))
                or f"service {service.get('service')}",
                test_quantity=int(test_qty or 0),
                refunded=format_money(refunded),
            ),
        )
        WATCHED_ORDERS.pop(order_id, None)
        return True
    new_test_qty, new_rest_qty = split_test_quantities(total_qty, nxt)
    new_test_cost = estimated_total_etb(
        float(nxt.get("rate_etb_per_1000") or 0), new_test_qty
    )
    leg_cover = split_leg_cover(
        confirmed_total, new_test_qty, total_qty, new_test_cost
    )
    split_kwargs = {
        "split_group_id": split.get("group_id"),
        "split_part": "test",
        "confirmed_total_etb": confirmed_total,
    }
    if leg_cover > 0:
        split_kwargs["paxyo_cover_etb"] = leg_cover
    try:
        result = await create_order_for_service(
            paxyo, user_id, nxt, link, new_test_qty,
            f"split-test-{uuid.uuid4().hex}",
            split=split_kwargs,
        )
    except Exception as exc:
        log.warning(
            "split test rescue %s: next test failed: %s", order_id, exc
        )
        await notify_admins(
            app,
            _split_test_admin_text(
                order_id, service, test_qty, refunded, failed,
                f"Refunded; the next test on "
                f"{short_service_name(nxt.get('name'))} could not "
                f"be placed.",
            ),
        )
        await notify_user(
            app, user_id,
            t(
                "order_split_no_service", "en",
                order_id=order_id,
                service=short_service_name(service.get("name"))
                or f"service {service.get('service')}",
                test_quantity=int(test_qty or 0),
                refunded=format_money(refunded),
            ),
        )
        WATCHED_ORDERS.pop(order_id, None)
        return True
    order = result.get("order", result) if isinstance(result, dict) else {}
    new_id = order.get("id") or order.get("order_id") or "?"
    server_total = order.get("total", order.get("charge"))
    if server_total is not None:
        try:
            new_test_cost = round(float(server_total), 2)
        except (TypeError, ValueError):
            pass
    failed_services = list(watched.get("failed_services") or [])
    failed_services.append(service_combined_id(service))
    WATCHED_ORDERS.pop(order_id, None)
    LAST_ORDER[user_id] = new_id
    watch_order(
        user_id, new_id, nxt, new_test_qty, link,
        total=new_test_cost,
        rescue_count=(watched.get("rescue_count") or 0) + 1,
        failed_services=failed_services,
        split={
            "group_id": split.get("group_id"),
            "leg": "test",
            "total_qty": total_qty,
            "test_qty": new_test_qty,
            "rest_qty": new_rest_qty,
            "confirmed_total": confirmed_total,
            "spent": 0.0,
        },
        deadline=watched.get("deadline"),
    )
    await notify_admins(
        app,
        _split_test_admin_text(
            order_id, service, test_qty, refunded, failed,
            f"Testing {short_service_name(nxt.get('name'))} next "
            f"(test order #{new_id}).",
        ),
    )
    await notify_user(
        app, user_id,
        t(
            "order_split_test_moved", "en",
            old_order_id=order_id,
            old_service=short_service_name(service.get("name"))
            or f"service {service.get('service')}",
            test_quantity=int(test_qty or 0),
            refunded=format_money(refunded),
            new_service=short_service_name(nxt.get("name"))
            or f"service {nxt.get('service')}",
            new_order_id=new_id,
        ),
    )
    return True


async def _notify_loyalty_award(app, user_id: int, username,
                                bonus: float, milestone: int):
    """The admin report for a credited loyalty bonus (feature 9,
    William 15 Nov 10:57 EAT): William gets one report naming who
    got it and how much, every time the bonus is credited. Only
    on a successful credit (awarded:true) — never on a failed
    attempt, never when already awarded, never when the endpoint
    is not installed (the callers only reach this on awarded:true).
    The username comes from the SERVER reply (best-effort from the
    auth table); when it is null the report carries the Telegram
    ID alone rather than inventing a name. The server's
    idempotency is the dedupe — a repeat check_loyalty call
    returns already_awarded, so this only ever runs on a fresh
    award. Never raises."""
    if app is None:
        return
    if username:
        who = f"@{username} ({user_id})"
    else:
        who = f"user {user_id}"
    await notify_admins(
        app,
        t(
            "loyalty_bonus_admin", "en",
            user=who, bonus=format_money(bonus),
            order_number=milestone * 10,
        ),
    )


async def _loyalty_bonus_line(app, user_id: int) -> str:
    """The loyalty-bonus line for a delivery message (feature 9,
    15 Nov 2026), or "". Calls check_loyalty() when the order
    completes; on awarded:true the line carries the EXACT bonus
    figure from the reply — never a self-computed figure — and
    William gets the admin report naming who got it and how much
    (see _notify_loyalty_award; the username in it comes from the
    server reply, never invented). A 404 (the endpoint is not
    live yet) or any failure says nothing about a bonus: the bot
    never promises credit that is not switched on. Non-milestone
    and already-awarded replies also say nothing — and send no
    admin report. Never raises."""
    try:
        result = await paxyo.check_loyalty(user_id)
    except Exception as exc:
        log.warning("loyalty check failed: %s", exc)
        return ""
    if not isinstance(result, dict) or not result.get("awarded"):
        return ""
    try:
        bonus = float(result.get("bonus_etb") or 0)
        milestone = int(result.get("milestone") or 0)
    except (TypeError, ValueError):
        return ""
    if bonus <= 0 or milestone <= 0:
        return ""
    await _notify_loyalty_award(
        app, user_id, result.get("username"), bonus, milestone
    )
    return t(
        "loyalty_bonus", "en",
        bonus=format_money(bonus),
        order_number=milestone * 10,
    )


def channel_nudge_keyboard():
    """The Join button for the channel nudge: a URL button to
    t.me/paxyo251, so tapping it opens the channel (the banner on
    the website works the same way — the link text is never shown
    as text, only as the button)."""
    return InlineKeyboardMarkup([[
        InlineKeyboardButton(
            t("channel_nudge_button", "en"),
            url="https://t.me/paxyo251",
        ),
    ]])


async def _maybe_channel_nudge(app, user_id: int):
    """The join-channel nudge (30, 15 Nov 2026): after the user's
    FIRST completed order, one short invite to join t.me/paxyo251.
    The visible completed count must be exactly 1 AND fewer than
    20 orders visible — with 20+ orders the list is truncated, so
    a heavy user's older history could fake a "first". Once ever:
    CHANNEL_NUDGE_SENT is the backstop (the watch entry is popped
    with the delivery message, so the nudge can only fire with
    it). The delivery message itself is already sent by the
    caller; this is a second, separate message, so it never
    collides with the rating buttons. Never raises."""
    if user_id in CHANNEL_NUDGE_SENT:
        return
    try:
        orders = await paxyo.recent_orders(user_id, limit=20) or []
    except Exception as exc:
        log.warning("channel nudge orders failed: %s", exc)
        return
    if len(orders) >= 20:
        return
    completed = [
        o for o in orders
        if isinstance(o, dict)
        and str(o.get("status") or "").strip().lower()
        in ("completed", "success", "paid")
    ]
    if len(completed) != 1:
        return
    CHANNEL_NUDGE_SENT.add(user_id)
    await notify_user(
        app, user_id, t("channel_nudge", "en"),
        reply_markup=channel_nudge_keyboard(),
    )


async def run_delivery_watch_cycle(app, now=None):
    """One pass over the watched orders (ideas batch, 15 Nov 2026):
    a completed order gets its delivery message once (plus the
    cross-sell line for a views order); an order far past its
    claimed average time is rescued once when it can be (stall
    rescue, 15 Nov 2026: cancel + refund, re-place on the next
    service) or gets one honest stuck warning with the support
    link; a FAILED order is refunded and re-placed on the next
    service (failed-order rescue, 15 Nov 2026); a
    cancelled/refunded order is dropped silently.
    Never raises — one bad order must not stop the rest. Called
    from the 60-second scheduler loop."""
    import time

    if now is None:
        now = time.time()
    if not WATCHED_ORDERS:
        return
    services = None
    for order_id, watched in list(WATCHED_ORDERS.items()):
        user_id = watched.get("user_id")
        try:
            # Provider-aware status (second provider, 15 Nov 2026):
            # an SMM order's status is read from the SMM endpoint,
            # not from GOP — the watch entry carries the
            # service, so no extra call is needed.
            data = await paxyo.order_status(
                order_id, user_id,
                provider=service_provider(watched.get("service") or {}),
            )
        except Exception as exc:
            log.warning("delivery watch %s failed: %s", order_id, exc)
            continue
        status = str(
            (data or {}).get("status")
            or (data or {}).get("order", {}).get("status", "")
        ).strip().lower()
        if status in ("completed", "success", "paid"):
            service = watched.get("service") or {}
            split = watched.get("split") or {}
            if split.get("leg") == "test":
                # Split-test (15 Nov 2026): the test delivered —
                # place the remaining 90% on the same service. No
                # delivery message yet: the order is not finished.
                await _place_split_remainder(app, order_id, watched)
                continue
            qty = int(watched.get("quantity") or 0)
            saved = 0.0
            if split.get("leg") == "remainder":
                # The remainder delivered: the whole order is done.
                # State the FULL ordered quantity (test + rest),
                # and the money saved when the cheaper service cost
                # less than the confirmed total.
                qty = int(split.get("total_qty") or qty)
                spent = float(split.get("spent") or 0)
                total_spent = spent + float(watched.get("total") or 0)
                saved = round(
                    float(split.get("confirmed_total") or 0)
                    - total_spent,
                    2,
                )
            text = t(
                "order_delivered", "en",
                quantity=qty,
                service=short_service_name(service.get("name"))
                or f"service {service.get('service')}",
                order_id=order_id,
            )
            if saved > 0:
                # Saving line (owner wording, 15 Nov 2026 20:30
                # EAT): "we got a better deal and the rest of the
                # money returned to your balance" — in the user's
                # own language when it is known (Amharic included),
                # English otherwise. The rest of the delivery
                # message stays English, as the scheduler sends it.
                text += "\n" + t(
                    "order_split_saved",
                    LAST_LANG.get(user_id, "en"),
                    saved=format_money(saved),
                    total=format_money(
                        split.get("confirmed_total") or 0
                    ),
                )
            if services is None:
                try:
                    services = await paxyo.services()
                except Exception as exc:
                    log.warning("delivery watch services failed: %s", exc)
                    services = []
            text += _crosssell_line(services or [], service)
            loyalty_line = await _loyalty_bonus_line(app, user_id)
            if loyalty_line:
                text += "\n" + loyalty_line
            if str(order_id) not in RATING_ASKED:
                # Rate your order (ideas batch 2, feature 3, 15 Nov
                # 2026): ask once, on the delivery message itself —
                # one tap, 👍 or 👎. The order is marked asked here,
                # so no later cycle or message can ever ask again
                # (the watch entry is dropped below anyway); a tap
                # that files nothing still counts as asked — never
                # nag. The ask line rides in English, like the rest
                # of the delivery message.
                text += "\n" + t("rate_ask", "en")
                RATING_ASKED.add(str(order_id))
                await notify_user(
                    app, user_id, text,
                    reply_markup=rating_keyboard(order_id),
                )
            else:
                await notify_user(app, user_id, text)
            WATCHED_ORDERS.pop(order_id, None)
            # Join-channel nudge (30, 15 Nov 2026): after the user's
            # FIRST completed order, one short invite to join
            # t.me/paxyo251 — once ever, never again. A separate
            # message with a Join button, so it never collides with
            # the delivery message's rating buttons.
            await _maybe_channel_nudge(app, user_id)
        elif status == "partial":
            # Partial order (13, 15 Nov 2026): the provider
            # delivered less than ordered — refund the undelivered
            # part and say so honestly, naming the exact refund.
            # The refund is attempted at most once per hour per
            # order (partial_attempted_at on the watch entry): the
            # endpoint may not be live yet, and a 409/502 means the
            # status has already moved on — the next cycle then
            # sees the new status instead of refunding twice.
            last_try = watched.get("partial_attempted_at") or 0
            if now - last_try >= 3600:
                watched["partial_attempted_at"] = now
                line, info = await _maybe_partial_refund(
                    app, user_id, order_id, watched.get("quantity")
                )
                if line is not None:
                    # Top up the missing part (#17): when the
                    # customer set it, the missing quantity is
                    # ordered on the same service instead of only
                    # being refunded — paid from the refunded part
                    # (plus the +10% Paxyo cover at most). The
                    # top-up helper returns its own line (placed,
                    # or too expensive so the refund stands); None
                    # means the plain refund line stands.
                    if pref_topup_missing(user_id) and info is not None:
                        topup_line = await _maybe_topup_missing(
                            app, user_id, order_id, watched, info
                        )
                        if topup_line is not None:
                            line = topup_line
                    await notify_user(app, user_id, line)
                    WATCHED_ORDERS.pop(order_id, None)
            # No line: endpoint not live yet, or the status moved
            # on — keep watching; the next cycle re-reads it.
        elif status in ("pending", "in_progress", "processing"):
            if watched.get("drip"):
                # A drip order (#15) delivers over time BY DESIGN —
                # the stall check (3x the average time) does not
                # apply to it: a 2-day drip is not "stuck" after a
                # few hours. It is only watched for its completion.
                continue
            if not is_order_stuck(
                watched.get("placed_at") or now,
                watched.get("avg_minutes"), now,
            ):
                continue
            # Auto-cancel (#34): the customer set a limit — a stuck
            # order past it is cancelled and refunded, no rescue.
            # A failed refund falls through to the normal rescue /
            # warning below.
            _auto_cancel = get_pref(user_id, "pref_auto_cancel_min")
            if _auto_cancel is not None:
                _elapsed_min = max(
                    0, int((now - watched.get("placed_at", now)) / 60)
                )
                if _elapsed_min > _auto_cancel:
                    refunded = None
                    # The bot itself is asking for this cancel
                    # (cancel-cutting item 4): mark the entry BEFORE
                    # the call, so the watch never mistakes the
                    # provider word "cancelled" that follows for a
                    # provider cancel and tries to rescue it again.
                    watched["bot_requested_cancel"] = True
                    try:
                        refunded = await paxyo.cancel_refund(
                            order_id, user_id
                        )
                    except Exception as exc:
                        log.warning(
                            "auto-cancel %s refund failed: %s",
                            order_id, exc,
                        )
                    if isinstance(refunded, dict):
                        try:
                            _amount = float(
                                refunded.get("refunded_etb") or 0
                            )
                        except (TypeError, ValueError):
                            _amount = 0.0
                        await notify_user(
                            app, user_id,
                            "Your order "
                            f"{order_id} was taking too long, so I "
                            "cancelled it and refunded "
                            f"{format_money(_amount)} ETB to your "
                            "balance, as you set.",
                        )
                        WATCHED_ORDERS.pop(order_id, None)
                        continue
            # Stall rescue (feature 2, 15 Nov 2026): one attempt per
            # stuck order. A rescued order gets the rescue message,
            # not the stuck warning, for this episode; a failed
            # rescue falls through to the warning below.
            if not watched.get("rescue_attempted"):
                if services is None:
                    try:
                        services = await paxyo.services()
                    except Exception as exc:
                        log.warning(
                            "delivery watch services failed: %s", exc
                        )
                        services = []
                split = watched.get("split") or {}
                if split.get("leg") == "test":
                    # Split-test (15 Nov 2026): a stalled test is
                    # rescued by the split-test flow (refund, tell
                    # William, next cheaper test) — not the plain
                    # rescue. The cap is handled inside it: a test
                    # at the cap is refunded, not left "still in
                    # progress", so the exhausted check below is
                    # skipped for test legs.
                    rescued = await _attempt_split_test_rescue(
                        app, order_id, watched, services or [], now
                    )
                else:
                    if (watched.get("rescue_count") or 0) >= MAX_STALL_RESCUES:
                        # All five tries stalled: honest final
                        # message, once, and stop — never loop forever.
                        # The order stays watched, so a late delivery
                        # still gets its message.
                        if not watched.get("warned"):
                            service = watched.get("service") or {}
                            await notify_user(
                                app, user_id,
                                t(
                                    "order_rescue_exhausted", "en",
                                    order_id=order_id,
                                    service=short_service_name(
                                        service.get("name"))
                                    or f"service {service.get('service')}",
                                    quantity=int(watched.get("quantity") or 0),
                                ),
                            )
                            watched["warned"] = True
                        continue
                    rescued = await _attempt_stall_rescue(
                        app, order_id, watched, services or []
                    )
                watched["rescue_attempted"] = True
                if rescued:
                    continue
            if not watched.get("warned"):
                service = watched.get("service") or {}
                avg = service.get("average_time") or "?"
                elapsed_min = max(0, int((now - watched.get("placed_at", now)) / 60))
                await notify_user(
                    app, user_id,
                    t(
                        "order_stuck", "en",
                        order_id=order_id,
                        service=short_service_name(service.get("name"))
                        or f"service {service.get('service')}",
                        quantity=int(watched.get("quantity") or 0),
                        avg=avg,
                        elapsed=f"{elapsed_min} minutes",
                    ),
                )
                watched["warned"] = True
        elif status == "failed":
            # Failed-order rescue (second provider, 15 Nov 2026):
            # refund via POST /orders/{id}/fail-refund and re-place
            # on the next-fastest service, across providers. Only
            # "failed" is rescued — never "cancelled"/"canceled"
            # (that may be the user's own cancel) or "refunded"
            # (already refunded). False keeps the entry watched;
            # the next cycle retries (throttled inside the rescue).
            # A failed split TEST leg goes through the split-test
            # rescue instead (refund, tell William, next cheaper
            # test); a failed remainder leg uses the plain rescue
            # with its split context carried forward. services
            # passes through as-is: None means "fetch the
            # catalogue inside", like the stall branch below.
            split = watched.get("split") or {}
            if split.get("leg") == "test":
                handled = await _attempt_split_test_rescue(
                    app, order_id, watched, services, now, failed=True
                )
            else:
                handled = await _attempt_failed_rescue(
                    app, order_id, watched, services, now
                )
            if handled:
                continue
        elif status in ("cancelled", "canceled"):
            # Cancel-cutting item 4 (16 Nov 2026): a PROVIDER
            # cancel goes through the SAME rescue as "failed" —
            # refund via fail-refund and re-place on the next
            # fastest affordable service. But only when the
            # provider cancelled it: an entry the bot itself
            # cancelled (stall rescue, split-test rescue,
            # auto-cancel — marked bot_requested_cancel BEFORE
            # the cancel_refund call) is already refunded, so it
            # is just dropped; and a user-asked cancel is never
            # rescued either (the round-3 user-cancel flow
            # refunds through its own endpoint and its entries
            # are already gone — this branch never sees them).
            # A cancelled split TEST leg goes through the
            # split-test rescue instead (refund, tell William,
            # next cheaper test); a cancelled remainder leg uses
            # the plain rescue. False keeps the entry watched;
            # the next cycle retries (throttled inside the
            # rescue). The pause record is best-effort: a
            # failure there must never block the rescue.
            if watched.get("bot_requested_cancel"):
                WATCHED_ORDERS.pop(order_id, None)
                continue
            split = watched.get("split") or {}
            _svc = watched.get("service") or {}
            try:
                _pause = await paxyo.record_service_cancel(
                    service_provider(_svc), _svc.get("service"),
                    order_id,
                )
            except Exception as exc:
                log.warning(
                    "watch %s: record service cancel failed: %s",
                    order_id, exc,
                )
                _pause = None
            if isinstance(_pause, dict) and _pause.get("paused_now"):
                _note_paused_service(service_combined_id(_svc))
                await notify_admins(
                    app,
                    _service_pause_admin_text(
                        _svc, _pause.get("cancel_count"),
                        _pause.get("paused_until"),
                    ),
                )
            if split.get("leg") == "test":
                handled = await _attempt_split_test_rescue(
                    app, order_id, watched, services, now, failed=True
                )
            else:
                handled = await _attempt_failed_rescue(
                    app, order_id, watched, services, now
                )
            if handled:
                continue
        elif status == "refunded":
            WATCHED_ORDERS.pop(order_id, None)
        # Any other status: keep watching; the next cycle retries.


def abandoned_nudge_keyboard(lang):
    """The Resume button for the abandoned-order nudge."""
    return InlineKeyboardMarkup([[
        InlineKeyboardButton(
            t("abandoned_resume_button", lang),
            callback_data="resume_draft",
        ),
    ]])


async def run_abandoned_nudge_cycle(app, now=None):
    """One pass over half-built normal order drafts (feature 4,
    15 Nov 2026): a draft whose owner has been quiet for ~30
    minutes gets ONE nudge with a Resume button, in the user's own
    language (LAST_LANG — the scheduler otherwise sends English,
    but the language lookup here is one dict read). Never more
    than once per draft; never while a Confirm card is open for
    that user (they are deciding, not abandoning); never after
    the draft was cancelled or the order completed (both drop
    PARTIAL, so there is nothing to iterate); never for delayed
    or recurring drafts — those live in DELAYED_DRAFT /
    RECURRING_DRAFT, not PARTIAL, so this loop never sees them.
    Best-effort throughout: a failed send is logged by
    notify_user and never raises into the scheduler cycle.
    Called from the 60-second scheduler loop."""
    import time

    if now is None:
        now = time.time()
    if not PARTIAL:
        return
    for user_id, draft in list(PARTIAL.items()):
        if not draft:
            continue
        # A Confirm card open for this user means they are
        # deciding, not abandoning — never nudge.
        _cid, _pending = pending_for_user(user_id)
        if _pending is not None:
            continue
        key = _partial_draft_key(draft)
        entry = PARTIAL_ACTIVITY.get(user_id)
        if entry is None or entry.get("draft_key") != key:
            # First sight of this draft (it was built in the same
            # turn as the user's last message, before the touch
            # ran, or by a button tap): the quiet clock starts now.
            PARTIAL_ACTIVITY[user_id] = {
                "last_active": now, "nudged_at": None, "draft_key": key,
            }
            continue
        if entry.get("nudged_at") is not None:
            continue  # already nudged once for this draft
        last_active = entry.get("last_active") or now
        if now - last_active < ABANDONED_NUDGE_MINUTES * 60:
            continue
        lang = LAST_LANG.get(user_id) or "en"
        await notify_user(
            app, user_id, t("abandoned_nudge", lang),
            reply_markup=abandoned_nudge_keyboard(lang),
        )
        entry["nudged_at"] = now
    # Prune activity for drafts that are gone (cancelled,
    # completed, or replaced): the next draft for that user
    # starts with a fresh nudge allowance.
    for user_id in list(PARTIAL_ACTIVITY):
        if user_id not in PARTIAL:
            PARTIAL_ACTIVITY.pop(user_id, None)


def abandoned_deposit_keyboard(confirm_id):
    """The Resume button for the abandoned-deposit nudge (14):
    callback "resumedep:<confirm_id>" re-shows the same Confirm
    card, so the existing Confirm/Cancel tail handles the tap."""
    return InlineKeyboardMarkup([[
        InlineKeyboardButton(
            t("abandoned_deposit_resume_button", "en"),
            callback_data=f"resumedep:{confirm_id}",
        ),
    ]])


async def run_abandoned_deposit_cycle(app, now=None):
    """One pass over deposits whose Confirm card was shown but
    never tapped (14, 15 Nov 2026): after ABANDONED_DEPOSIT_HOURS
    of quiet, ONE gentle reminder with a Resume button, in the
    user's own language (LAST_LANG). Never more than once per
    abandoned deposit (nudged_at); never after the card is gone
    (confirmed or cancelled — the record is pruned); never to a
    user who completed a deposit since the card was shown
    (checked against GET /deposits — a completed deposit with a
    created_at at or after the card, or an unparseable date, ends
    the record instead of nagging a payer). Best-effort
    throughout: a failed send or a failed deposits read is logged
    by notify_user / the warning below and never raises into the
    scheduler cycle. Called from the 60-second scheduler loop."""
    import time

    if now is None:
        now = time.time()
    if not DEPOSIT_ABANDONED:
        return
    for user_id, entry in list(DEPOSIT_ABANDONED.items()):
        confirm_id = entry.get("confirm_id")
        _cid, pending = pending_deposit_for_user(user_id)
        if pending is None or _cid != confirm_id:
            # Card gone (confirmed, cancelled, or replaced by a
            # newer deposit): nothing to resume, drop the record.
            DEPOSIT_ABANDONED.pop(user_id, None)
            continue
        if entry.get("nudged_at") is not None:
            continue  # already nudged once for this deposit
        started_at = entry.get("started_at") or now
        if now - started_at < ABANDONED_DEPOSIT_HOURS * 3600:
            continue
        try:
            deposits = await paxyo.list_deposits(user_id)
        except Exception as exc:
            log.warning(
                "abandoned deposit check failed: %s", exc
            )
            deposits = None
        if deposits:
            completed_since = False
            for dep in deposits:
                if str(dep.get("status") or "").strip().lower() not in (
                    "completed", "success", "paid"
                ):
                    continue
                created = _parse_order_created_at(dep.get("created_at"))
                if created is None:
                    # Unparseable date on a completed deposit: do
                    # not risk nagging someone who paid.
                    completed_since = True
                    break
                if created.timestamp() >= started_at:
                    completed_since = True
                    break
            if completed_since:
                DEPOSIT_ABANDONED.pop(user_id, None)
                continue
        lang = LAST_LANG.get(user_id) or "en"
        await notify_user(
            app, user_id,
            t(
                "abandoned_deposit_nudge", lang,
                amount=format_money(entry.get("amount") or 0),
            ),
            reply_markup=abandoned_deposit_keyboard(confirm_id),
        )
        entry["nudged_at"] = now


async def run_deposit_credit_cycle(app, now=None):
    """One pass over deposits awaiting automatic credit (owner,
    17 Nov 2026): the Chapa callback credits a paid deposit
    server-side, and this watcher tells the user it landed — no
    "I paid" tap needed. It re-reads each watched deposit with
    GET /deposits/{id} (the server re-verifies with Chapa when
    still pending, so this IS the recheck — the bot never credits
    anything itself). Completed -> the same "went through" line
    (plus referral-bonus lines and the big-deposit alert, exactly
    as the explicit recheck does) and the watch is dropped;
    failed -> one honest "it failed" line and the watch is
    dropped; still pending -> keep watching (dropped after 48
    hours, when the server fails it too). A 404 (endpoint not
    live yet) or a failed read keeps the watch for next time.
    Best-effort throughout: a failed send or read is logged and
    never raises into the scheduler cycle. Called from the
    60-second scheduler loop."""
    import time

    if now is None:
        now = time.time()
    if not DEPOSIT_CREDIT_WATCH:
        return
    for user_id, entry in list(DEPOSIT_CREDIT_WATCH.items()):
        deposit_id = entry.get("deposit_id")
        started_at = entry.get("started_at") or now
        if now - started_at > 48 * 3600:
            DEPOSIT_CREDIT_WATCH.pop(user_id, None)
            continue
        try:
            deposit = await paxyo.deposit_status(deposit_id, user_id)
        except Exception as exc:
            log.warning("deposit credit watch failed: %s", exc)
            continue
        if deposit is None:  # 404: endpoint not live yet
            continue
        status = str(deposit.get("status") or "").strip().lower()
        if status not in ("completed", "success", "paid",
                          "failed", "cancelled", "canceled",
                          "expired", "rejected"):
            continue  # still pending: keep watching
        DEPOSIT_CREDIT_WATCH.pop(user_id, None)
        lang = LAST_LANG.get(user_id) or "en"
        amount = deposit.get("amount")
        try:
            amount_text = format_money(amount)
        except (TypeError, ValueError):
            amount_text = "?"
        if status in ("completed", "success", "paid"):
            try:
                bal = await paxyo.balance(user_id)
            except Exception as exc:
                log.warning(
                    "balance failed after deposit credit: %s", exc
                )
                bal = None
            if bal and bal.get("found"):
                text = t(
                    "deposit_went_through", lang,
                    amount=amount_text,
                    balance=format_money(bal.get("balance", 0)),
                )
            else:
                text = t(
                    "deposit_went_through_nobalance", lang,
                    amount=amount_text,
                )
            await notify_user(app, user_id, text)
            # Referral-bonus lines + big-deposit alert, mirroring
            # the explicit recheck (deposit_status_text).
            try:
                for line in await _referral_bonus_lines(
                    user_id, deposit, lang, app
                ):
                    await notify_user(app, user_id, line)
            except Exception as exc:
                log.warning("deposit credit bonus lines failed: %s", exc)
            try:
                await _maybe_big_deposit_alert(
                    app, deposit, user_id, None,
                    (bal or {}).get("balance"),
                )
            except Exception as exc:
                log.warning("deposit credit alert failed: %s", exc)
            # A completed deposit teaches the bot the user's last
            # successful method (23): the method rides on the
            # deposit record. Best-effort, like the recheck.
            _method = str(deposit.get("method") or "").strip().lower()
            if _method in ("telebirr", "cbe", "cbebirr", "mpesa"):
                _traits_entry(user_id)["last_deposit_method"] = _method
                schedule_traits_save(
                    user_id, {"last_deposit_method": _method}
                )
        else:
            await notify_user(
                app, user_id,
                t("deposit_failed_check", lang, amount=amount_text),
            )


async def run_uptime_watch_cycle(app, now=None):
    """One uptime-watch pass (19, 15 Nov 2026): the bot watches
    its own provider + the paxyo.et API on the scheduler cycle.
    The API is up when admin_stats() answers; the provider is up
    when the provider balance is present in that same reply (the
    server reads it live — a missing field means the provider
    could not be reached, and a 404 means the stats endpoint is
    not live yet, so the watch stays off instead of alerting on
    a missing number). Two consecutive failures alert William
    once per target (throttled to one alert per hour); a success
    after "down" sends one recovery message. Checked at most
    every UPTIME_CHECK_SECONDS (5 minutes) — the cycle itself
    runs every 60 seconds. Never raises, never messages a
    customer."""
    import time

    global _UPTIME_LAST_CHECK
    if now is None:
        now = time.monotonic()
    if now - _UPTIME_LAST_CHECK < UPTIME_CHECK_SECONDS:
        return
    _UPTIME_LAST_CHECK = now
    try:
        stats = await paxyo.admin_stats()
    except Exception as exc:
        log.warning("uptime watch stats failed: %s", exc)
        stats = None
    if stats is None:
        # 404 (endpoint not live yet) or a failed call: the watch
        # stays off with a log warning — never an alert on a
        # missing number.
        log.warning(
            "uptime watch off: /admin/stats did not answer "
            "(endpoint not live yet)"
        )
        return
    up = {
        "api": True,
        "provider": stats.get("provider_balance_usd") is not None,
    }
    for target in ("api", "provider"):
        state = UPTIME_STATE[target]
        if up[target]:
            if state["down"]:
                state["down"] = False
                state["fails"] = 0
                await notify_admins(
                    app,
                    f"✅ {target} is back up.",
                )
            else:
                state["fails"] = 0
            continue
        state["fails"] += 1
        if state["fails"] < 2 or state["down"]:
            continue
        # A last_alert of 0.0 means "never alerted" — the first
        # alert is never throttled by the zero default.
        if (
            state["last_alert"]
            and now - state["last_alert"] < UPTIME_ALERT_THROTTLE_SECONDS
        ):
            state["down"] = True
            continue
        state["down"] = True
        state["last_alert"] = now
        await notify_admins(
            app,
            f"⚠️ {target} is down (failed twice in a row).",
        )


async def run_fraud_watch_cycle(app, now=None):
    """One fraud-watch pass (17, 15 Nov 2026): ask the server for
    flagged users (rapid-fire orders, repeated failed payments, a
    burst of new accounts) and relay each flag to William, once.
    The server claims one alert per user per day, so the bot never
    spams him — it only relays what the endpoint returns, and
    throttles its own calls to every FRAUD_WATCH_CHECK_SECONDS
    (15 minutes). Never blocks a user automatically, only flags.
    A 404 (endpoint not live yet) stays silent with a log
    warning. Never raises, never messages a customer."""
    import time

    global _FRAUD_WATCH_LAST_CHECK
    if now is None:
        now = time.monotonic()
    if now - _FRAUD_WATCH_LAST_CHECK < FRAUD_WATCH_CHECK_SECONDS:
        return
    _FRAUD_WATCH_LAST_CHECK = now
    try:
        data = await paxyo.fraud_watch()
    except Exception as exc:
        log.warning("fraud watch failed: %s", exc)
        return
    if data is None:
        log.warning(
            "fraud watch off: GET /fraud-watch returned 404 "
            "(endpoint not live yet)"
        )
        return
    flags = data.get("flags") or []
    if not flags:
        return
    lines = ["🚨 Fraud watch:"]
    for flag in flags:
        if not isinstance(flag, dict):
            continue
        who = flag.get("telegram_id")
        reason = flag.get("reason") or "suspicious activity"
        count = flag.get("count")
        line = f"• user {who}: {reason}"
        if count is not None:
            line += f" ({count})"
        lines.append(line)
    await notify_admins(app, "\n".join(lines))


# ------------------------------------------------- conversation (round 8) ---

# Round 8, 14 Nov 2026 — the bot talks like a normal AI mid-order.
# Live case: the user said "Do you understand what I said first"
# and the bot just repeated "Please send the link the order is for."
# A normal AI says what it understood first, then continues. These
# guards run BEFORE the order flow, so a question or a chatty
# message is never swallowed by the next order prompt. They never
# touch the draft or a pending Confirm card — the order survives
# the chat, and the next order message picks it up where it was.

_CONFIRM_UNDERSTANDING_PHRASES = (
    "do you understand", "did you understand", "do you get it",
    "did you get it", "did you get that", "do you know what i mean",
    "do you know what i want", "do you understand what i said",
    "do you understand me", "did you understand me",
    "what did i say", "what did i just say", "what did i tell you",
    "are you following", "are you listening", "did you hear me",
    "do you follow", "did you get what i said",
    # Amharic equivalents (fidels): "did you understand",
    # "what did I say".
    "ገባህ", "ገብቶሃል", "ተረድተሃል", "ተረድተሺ", "ምን አልኩ",
)

_CONVERSATION_QUESTION_PHRASES = (
    "what do you mean", "what did you mean", "what do u mean", "wdym",
    "why are you asking", "why do you ask", "why are you asking that",
    "why do you need", "why do you need that", "why are you asking me",
    "what are you asking", "what do you want to know",
    "ምን ማለት", "ለምን ጠየቅ", "እያዳመጥክ",
)

# Chatty messages that are not orders: laughter, thanks, feelings,
# small talk, opinions ("do you think ..."). Single words only
# count in a short message, so "great, send me the link" still
# goes to the order flow.
_FREE_CHAT_PHRASES = (
    "haha", "lol", "lmao", "hehe", "i'm tired", "i am tired",
    "i'm bored", "i am bored", "i'm happy", "i am happy",
    "i'm sad", "i am sad", "i feel", "how are you", "how r you",
    "what's up", "whats up", "good morning", "good afternoon",
    "good evening", "do you think", "what do you think",
    "thank you", "thank u",
)
_FREE_CHAT_WORDS = {
    "nice", "cool", "great", "awesome", "thanks", "thx", "wow", "lovely",
}

_PLATFORM_DISPLAY = {
    "tiktok": "TikTok", "instagram": "Instagram", "telegram": "Telegram",
    "youtube": "YouTube", "facebook": "Facebook", "x": "X",
}


def is_confirm_understanding(text: str) -> bool:
    """True when the user asks whether the bot understood what they
    said ("do you understand", "did you get that", "what did I
    say", "are you listening" — English and Amharic)."""
    s = " ".join((text or "").strip().lower().split())
    if not s:
        return False
    return any(p in s for p in _CONFIRM_UNDERSTANDING_PHRASES)


def is_conversation_question(text: str, user_id=None) -> bool:
    """True when the user asks about the conversation itself mid-order
    ("what do you mean", "why are you asking that"). A bare "what?"
    or "huh?" counts only while an order is being built — otherwise
    it is just confusion with nothing to explain."""
    s = " ".join((text or "").strip().lower().split())
    if not s:
        return False
    if any(p in s for p in _CONVERSATION_QUESTION_PHRASES):
        return True
    if s in ("what?", "what", "huh?", "huh", "??", "???", "what??", "huh??"):
        if user_id is None:
            return False
        _cid, pending = pending_for_user(user_id)
        return pending is not None or bool(PARTIAL.get(user_id))
    return False


def is_free_chat(text: str) -> bool:
    """True when the message is chat, not an order: a greeting, small
    talk, a comment, a feeling, an opinion, a joke. The caller must
    have already ruled out order details (link, quantity, service
    ID, deposit fields) — this only reads the chatty markers."""
    s = " ".join((text or "").strip().lower().split())
    if not s:
        return False
    if any(p in s for p in _FREE_CHAT_PHRASES):
        return True
    if any(emoji in s for emoji in _CHAT_EMOJI):
        return True
    words = set(re.findall(r"[a-z]+", s))
    if words & _FREE_CHAT_WORDS and len(words) <= 4:
        return True
    return False


def _describe_hint(hint: str, platform: str, user_id: int, text=None) -> str:
    """Short plain description of an order being built, for
    restatements: "👍 reactions for your Telegram channel post",
    "TikTok views", "Instagram followers". The reaction emoji comes
    from the message itself, else from the user's recent messages."""
    h = (hint or "").strip().lower()
    p = (platform or "").strip().lower()
    if "reaction" in h:
        emoji = reaction_emoji(text) if text else None
        if emoji is None:
            load_chat_history()
            for entry in reversed(CHAT_HISTORY.get(int(user_id), [])[-5:]):
                emoji = reaction_emoji(entry.get("user", ""))
                if emoji is not None:
                    break
        label = f"{emoji} reactions" if emoji else "reactions"
        if p == "telegram" or "telegram" in h:
            return f"{label} for your Telegram channel post"
        if p:
            return f"{label} for your {p} post"
        return label
    if h:
        words = h.split()
        if words and words[0] in _PLATFORM_DISPLAY:
            words[0] = _PLATFORM_DISPLAY[words[0]]
            desc = " ".join(words)
        elif p and p not in h:
            desc = f"{_PLATFORM_DISPLAY.get(p, p.capitalize())} {h}"
        else:
            desc = h[:1].upper() + h[1:]
        return desc
    if p:
        return _PLATFORM_DISPLAY.get(p, p.capitalize())
    return ""


def _recent_quantity(user_id: int, kind):
    """The quantity the user gave for this metric in their last 3
    chat messages (round 8.1, 14 Nov 2026): "I want 👍 reaction
    for my telegram channel post how much 1k" names 1,000, so a
    later "do you understand what I said first" must restate the
    1,000 and never ask "how many" again. The metric must match —
    a quantity given for followers does not carry into a views
    order. A quantity in a message naming a different metric is
    ignored, and the search stops at the newest matching one."""
    load_chat_history()
    entries = CHAT_HISTORY.get(int(user_id), [])
    user_texts = [e.get("user", "") for e in entries if e.get("user")]
    wanted = _primary_metric(kind)
    for text in reversed(user_texts[-3:]):
        text_kind = kind_from_text(text)
        if wanted is not None and text_kind is not None:
            if _primary_metric(text_kind) != wanted:
                continue
        # The text is normalised first: quantity_from_text reads
        # "1k" only after normalisation expands it to 1000.
        qty = quantity_from_text(normalize_text(text))
        if qty:
            return qty
    return None


def _order_context_summary(user_id: int):
    """What the user is talking about: the pending Confirm card
    first, then the draft being built, then the last thing they
    asked about in chat history. Returns {"desc", "quantity",
    "link", "missing", "pending"} or None when there is nothing
    to restate."""
    _cid, pending = pending_for_user(user_id)
    if pending is not None:
        service = pending.get("service") or {}
        name = short_service_name(service.get("name")) or "your order"
        qty = pending.get("quantity")
        desc = f"{name}, {qty:,}" if qty else name
        return {
            "desc": desc, "quantity": qty, "link": pending.get("link"),
            "missing": [], "pending": True,
        }
    partial = PARTIAL.get(user_id) or {}
    hint = (partial.get("service_hint") or "").strip()
    platform = (partial.get("platform") or "").strip()
    if hint or platform:
        desc = _describe_hint(hint, platform, user_id)
        missing = []
        if not partial.get("link"):
            missing.append("link")
        if not partial.get("quantity"):
            missing.append("quantity")
        return {
            "desc": desc, "quantity": partial.get("quantity"),
            "link": partial.get("link"), "missing": missing,
            "pending": False,
        }
    load_chat_history()
    entries = CHAT_HISTORY.get(int(user_id), [])
    user_texts = [e.get("user", "") for e in entries if e.get("user")]
    for text in reversed(user_texts[-3:]):
        kind = kind_from_text(text)
        qty = quantity_from_text(normalize_text(text))
        words = set(re.findall(r"[a-z]+", (text or "").lower()))
        platform = _platform_from_words(words, text)
        if kind or platform or qty:
            desc = _describe_hint(kind or "", platform or "", user_id, text)
            links = extract_links(text)
            # The quantity may live in an earlier message than the
            # one being restated (the price question named 1,000;
            # "do you understand" names none) — look back at the
            # same metric instead of asking "how many" again.
            if not qty:
                qty = _recent_quantity(user_id, kind)
            missing = []
            if not links:
                missing.append("link")
            if not qty:
                missing.append("quantity")
            return {
                "desc": desc, "quantity": qty,
                "link": links[0] if links else None,
                "missing": missing,
                "pending": False,
            }
    return None


def understanding_text(user_id: int, lang: str) -> str:
    """The restatement for "do you understand": what the bot
    understood from the conversation so far, and what is still
    missing. Never just the link prompt again."""
    summary = _order_context_summary(user_id)
    if summary is None:
        return t("understand_none", lang)
    if summary.get("pending"):
        return t("understand_pending", lang, desc=summary["desc"])
    desc = summary["desc"]
    qty = summary.get("quantity")
    if qty and f"{qty:,}" not in desc:
        desc = f"{desc}, {qty:,}"
    missing = summary.get("missing") or []
    if not missing:
        return t("understand_partial", lang, desc=desc, missing="")
    if missing == ["link"]:
        missing_text = t("missing_link", lang)
    elif missing == ["quantity"]:
        missing_text = t("missing_quantity", lang)
    else:
        missing_text = t("missing_link_quantity", lang)
    return t("understand_partial", lang, desc=desc, missing=missing_text)


def explain_asking_text(user_id: int, lang: str) -> str:
    """The answer for "what do you mean / why are you asking":
    what the bot needs and why, from the order being built. Falls
    back to quoting the bot's last message."""
    _cid, pending = pending_for_user(user_id)
    if pending is not None:
        service = pending.get("service") or {}
        name = short_service_name(service.get("name")) or "your order"
        qty = pending.get("quantity")
        desc = f"{name}, {qty:,}" if qty else name
        return t("mean_pending", lang, desc=desc)
    if DEPOSIT_DRAFT.get(user_id):
        return t("mean_deposit", lang)
    partial = PARTIAL.get(user_id) or {}
    if partial:
        desc = _describe_hint(
            partial.get("service_hint") or "",
            partial.get("platform") or "", user_id,
        ) or "your order"
        if not partial.get("link"):
            return t("mean_link", lang, desc=desc)
        if not partial.get("quantity"):
            return t("mean_quantity", lang, desc=desc)
    load_chat_history()
    for entry in reversed(CHAT_HISTORY.get(int(user_id), [])):
        last = entry.get("bot", "")
        if last:
            return t("mean_last", lang, last=last[:200])
    return t("understand_none", lang)


def _feeling_ack(text: str, lang: str) -> str:
    """The human part of a message, acknowledged FIRST (round 8.1,
    14 Nov 2026): "haha nice, I'm tired today but I need views"
    is laughter AND tiredness, and the bot must not ignore either
    and jump straight to tips. Laugh + tired together get the
    combined line; either one alone gets its own line; nothing
    felt returns ""."""
    s = " ".join((text or "").strip().lower().split())
    laugh = any(w in s for w in ("haha", "lol", "lmao", "hehe")) \
        or any(e in s for e in ("😂", "🤣"))
    tired = "tired" in s or "bored" in s
    if laugh and tired:
        return t("chat_laugh_tired", lang)
    if laugh:
        return t("chat_laugh", lang)
    if tired:
        return t("chat_tired", lang)
    return ""


def local_chat_reply(text: str, lang: str) -> str:
    """Warm acknowledgement when the AI is down: keyed by what the
    user said. Never a price, never an order prompt — the caller
    appends the soft continuation. The human part comes first
    (round 8.1, 14 Nov 2026): laugh and tiredness are
    acknowledged before anything else, so a tired user never gets
    only tips."""
    ack = _feeling_ack(text, lang)
    if ack:
        return ack
    s = " ".join((text or "").strip().lower().split())
    if "thank" in s or "thx" in s:
        return t("chat_thanks", lang)
    if "happy" in s or "feel good" in s:
        return t("chat_happy", lang)
    if any(p in s for p in (
        "how are you", "how r you", "what's up", "whats up",
        "good morning", "good afternoon", "good evening",
    )):
        return t("chat_greeting", lang)
    if "viral" in s:
        return t("chat_viral", lang)
    return t("chat_default", lang)


def chat_continue_note(user_id: int, lang: str) -> str:
    """The soft line that ends a free-chat reply: it points back to
    the order without interrogating ("send the link when you're
    ready"), or invites a first order when there is none."""
    _cid, pending = pending_for_user(user_id)
    if pending is not None:
        return t("chat_continue_confirm", lang)
    partial = PARTIAL.get(user_id) or {}
    if partial:
        if not partial.get("link"):
            return t("chat_continue_link", lang)
        if not partial.get("quantity"):
            return t("chat_continue_quantity", lang)
        return t("chat_continue_confirm", lang)
    return t("chat_continue_fresh", lang)


async def conversation_reply(update, text: str, lang: str, voice: bool = False) -> bool:
    """Answer a conversational message mid-order and return True
    when handled (the caller returns). Three kinds, in order:
    "do you understand" gets a restatement of the order; "what do
    you mean / why are you asking" gets an explanation; free chat
    (greetings, small talk, comments, feelings, opinions) gets a
    natural AI answer plus a soft steer back. Real questions and
    order details are never swallowed: ban, price, source, payment,
    usual, order-now, links, quantities, service IDs and deposit
    fields all fall through to their own handlers. A bare reaction
    emoji is never swallowed either: it is an order start, not
    small talk. The draft and any Confirm card stay untouched."""
    user = update.effective_user
    user_id = user.id
    s = " ".join((text or "").strip().lower().split())
    if not s:
        return False
    # A bare reaction emoji is an order start, not small talk: it
    # must reach the bare-emoji branch below, which stores a
    # reactions draft and asks for the post link. Without this,
    # 😂/🤣/😄/😊 are swallowed here as free chat (they are also
    # in _CHAT_EMOJI) and never start a reactions order
    # (many-emoji expansion, 14 Nov 2026). Only a message that
    # is exactly one reaction emoji is skipped — "haha 😂" is
    # still free chat, and 🙏 on its own is still thanks.
    _only = (text or "").strip().replace("\ufe0f", "")
    _emoji = reaction_emoji(text)
    if (
        _emoji is not None
        and _emoji != "🙏"
        and _only == _emoji.replace("\ufe0f", "")
    ):
        return False
    if (is_ban_question(text) or is_price_question(text)
            or is_source_question(text) or is_paid_phrase(text)
            or is_usual_request(text) or is_order_now(text)
            or extract_links(text) or extract_service_id(text) is not None
            or quantity_from_text(text) is not None
            or normalize_method(text) is not None
            or normalize_phone(text) is not None
            or parse_deposit_amount(text) is not None
            or parse_interval_minutes(text) is not None):
        return False
    if is_confirm_understanding(text):
        await reply_message(
            update.message, understanding_text(user_id, lang),
            lang, voice=voice,
        )
        OFF_TOPIC_COUNT.pop(user_id, None)
        return True
    if is_conversation_question(text, user_id):
        await reply_message(
            update.message, explain_asking_text(user_id, lang),
            lang, voice=voice,
        )
        OFF_TOPIC_COUNT.pop(user_id, None)
        return True
    # Mid-draft emoji correction (screenshot bug, 16 Nov 2026):
    # while a reactions draft (or card) is open, naming a
    # DIFFERENT reaction emoji is a correction, not small talk —
    # "only 😂" must re-pick the 😂 service instead of getting a
    # laugh reply. Without this, 😂/🤣/😄/😊 are swallowed by
    # is_free_chat below (they are also in _CHAT_EMOJI) and the
    # correction chain never runs. A message naming the draft's
    # own emoji is still chat.
    _new_emoji = reaction_emoji(text) or _reaction_emoji_from_words(text)
    if _new_emoji is not None:
        _draft = PARTIAL.get(user_id) or {}
        _cid, _card = pending_for_user(user_id)
        _card_emoji = (_card or {}).get("reaction_emoji")
        _draft_hint = (_draft.get("service_hint") or "").lower()
        _card_name = ((_card or {}).get("service") or {}).get("name", "")
        _is_reactions = (
            "reaction" in _draft_hint
            or bool(_draft.get("reaction_emoji"))
            or "reaction" in str(_card_name).lower()
            or bool(_card_emoji)
        )
        _old_emoji = (
            _draft.get("reaction_emoji")
            or reaction_emoji(_draft_hint)
            or _card_emoji
        )
        if _is_reactions and _new_emoji != _old_emoji:
            return False
    if is_free_chat(text):
        _cid, _pending = pending_for_user(user_id)
        _partial = PARTIAL.get(user_id) or {}
        if _pending is None and not _partial:
            # Pure small talk with no order being built counts toward
            # the same 2-3 turn steering as off-topic (round 5).
            count = OFF_TOPIC_COUNT.get(user_id, 0) + 1
            OFF_TOPIC_COUNT[user_id] = count
            if count >= 3:
                await reply_message(
                    update.message,
                    with_pending_note(
                        user_id, lang, t("off_topic_steer", lang)
                    ),
                    lang, voice=voice,
                )
                return True
        general = await answer_general_question(text, lang)
        if general is None:
            general = local_chat_reply(text, lang)
        else:
            # The AI answered the content but never acknowledges
            # the human part (round 8.1, 14 Nov 2026: "haha nice,
            # I'm tired today" got only video tips) — the feeling
            # goes first, before the tips or the steering.
            ack = _feeling_ack(text, lang)
            if ack and ack not in general:
                general = ack + " " + general
        await reply_message(
            update.message,
            general + "\n" + chat_continue_note(user_id, lang),
            lang, voice=voice,
        )
        return True
    return False


