async def maybe_first_order_nudge(user_id: int, lang: str):
    """The first-order nudge (ideas batch, 15 Nov 2026): for a
    brand-new user (no orders yet) offer the cheapest test order —
    1000 of the cheapest views service, one tap to start. Returns
    (text, keyboard) or None. Offered ONCE per user (also after a
    decline): FIRST_ORDER_NUDGE_DONE is marked as soon as the offer
    is shown. The cheapest service is pinned only when the user
    taps the button (see the "firstorder" callback) — merely
    seeing the offer never changes a later order's service."""
    if user_id in FIRST_ORDER_NUDGE_DONE:
        return None
    try:
        orders = await paxyo.recent_orders(user_id)
    except Exception as exc:
        log.warning("nudge orders check failed: %s", exc)
        return None
    if orders:
        FIRST_ORDER_NUDGE_DONE.add(user_id)
        return None
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("nudge services failed: %s", exc)
        return None
    service = cheapest_service(
        services or [], platform="tiktok", service_hint="tiktok views"
    )
    if service is None:
        return None
    FIRST_ORDER_NUDGE_DONE.add(user_id)
    quantity = 1000
    total = estimated_total_etb(
        float(service.get("rate_etb_per_1000", 0)), quantity
    )
    text = t(
        "first_order_offer", lang,
        quantity=quantity,
        service=short_service_name(service.get("name")),
        total=format_money(total),
    )
    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton(
            t("first_order_button", lang),
            # The service id rides in the button, so the tap knows
            # which service to pin — the offer itself pins nothing.
            callback_data=f"firstorder:{int(service.get('service'))}",
        )
    ]])
    return text, keyboard


FRIDAY_OFFERED = set()  # (user_id, service_id, quantity, weekday, iso_year, iso_week): offered once per week
FRIDAY_PENDING = {}  # telegram_id -> pattern dict of the open offer (service_id, service_name, quantity, weekday, link)
FRIDAY_LINK = {}  # telegram_id -> last matching order's link, set only when the user accepts the offer


def _parse_order_created_at(value):
    """An order's created_at -> aware UTC datetime, or None.

    The server sends ISO with Z ("2026-11-13T10:00:00Z"); a MySQL
    DATETIME ("2026-11-13 10:00:00") is also read, as UTC. An
    unparseable value is None, never a crash — that order simply
    cannot join a pattern."""
    if not value:
        return None
    s = str(value).strip()
    if not s:
        return None
    try:
        if s.endswith("Z"):
            return datetime.strptime(
                s, "%Y-%m-%dT%H:%M:%SZ"
            ).replace(tzinfo=timezone.utc)
        parsed = datetime.fromisoformat(s)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)
    except ValueError:
        pass
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
        try:
            return datetime.strptime(s, fmt).replace(tzinfo=timezone.utc)
        except ValueError:
            continue
    return None


def detect_weekly_patterns(orders):
    """Weekly ordering patterns in a user's order list: the SAME
    service + quantity ordered on the SAME EAT weekday at least
    twice. Weekday is taken in Africa/Addis_Ababa — the orders'
    timestamps are UTC, so a 22:30 UTC order is already the next
    day in EAT and must count for that day. Returns newest first,
    each pattern carrying the newest matching order's service name
    and link. A non-list, or an order without a parseable
    created_at / service / quantity, is skipped, never a crash."""
    if not isinstance(orders, (list, tuple)):
        return []
    groups = {}
    for order in orders:
        if not isinstance(order, dict):
            continue
        try:
            service_id = int(order.get("service_id") or 0)
            quantity = int(order.get("quantity") or 0)
        except (TypeError, ValueError):
            continue
        if not service_id or not quantity:
            continue
        # Group by COMBINED id ("gop:<id>" / "smm:<id>", second
        # provider, 15 Nov 2026): a bare id would merge the two
        # providers' same-number services into one pattern.
        combined = order.get("combined_id") or f"gop:{service_id}"
        created = _parse_order_created_at(order.get("created_at"))
        if created is None:
            continue
        weekday = created.astimezone(EAT_TZ).weekday()
        groups.setdefault((combined, quantity, weekday), []).append(
            (created, order)
        )
    patterns = []
    for (service_id, quantity, weekday), rows in groups.items():
        if len(rows) < 2:
            continue
        rows.sort(key=lambda row: row[0], reverse=True)
        newest = rows[0][1]
        patterns.append({
            "service_id": service_id,
            "service_name": str(newest.get("service_name") or ""),
            "quantity": quantity,
            "weekday": weekday,
            "link": newest.get("link"),
            "last_created_at": rows[0][0],
        })
    patterns.sort(key=lambda p: p["last_created_at"], reverse=True)
    return patterns


def _friday_weekday_name(weekday: int, lang: str) -> str:
    """'Friday' / 'ዓርብ' for weekday 4 (Monday 0 … Sunday 6)."""
    names = _WEEKDAY_NAMES.get(lang) or _WEEKDAY_NAMES["en"]
    try:
        return names[int(weekday)]
    except (IndexError, TypeError, ValueError):
        return _WEEKDAY_NAMES["en"][4]


def _friday_has_open_state(user_id: int) -> bool:
    """True when the user already has an order in progress — a
    draft, a Confirm card (order, recurring, delayed or batch) or
    a deposit draft. The Friday offer never interrupts one."""
    user_id = int(user_id)
    if PARTIAL.get(user_id):
        return True
    if pending_for_user(user_id)[1] is not None:
        return True
    if pending_recurring_for_user(user_id)[1] is not None:
        return True
    if pending_delayed_for_user(user_id)[1] is not None:
        return True
    if pending_batch_for_user(user_id)[1] is not None:
        return True
    if pending_deposit_for_user(user_id)[1] is not None:
        return True
    return (
        user_id in DELAYED_DRAFT
        or user_id in RECURRING_DRAFT
        or user_id in DEPOSIT_DRAFT
    )


def _friday_ordered_this_week(orders, pattern, iso_year, iso_week):
    """True when the pattern's service + quantity was already
    ordered in this ISO week (EAT) — the user just placed it, so
    there is nothing to offer."""
    if not isinstance(orders, (list, tuple)):
        return False
    for order in orders:
        if not isinstance(order, dict):
            continue
        try:
            if int(order.get("quantity") or 0) != pattern["quantity"]:
                continue
        except (TypeError, ValueError):
            continue
        # Compare by COMBINED id ("gop:<id>" / "smm:<id>", second
        # provider, 15 Nov 2026): the pattern stores the combined
        # id, and an old order row without one reads as GOP — a
        # bare id alone could match the other provider's service
        # of the same number.
        combined = order.get("combined_id")
        if combined is None:
            try:
                combined = f"gop:{int(order.get('service_id') or 0)}"
            except (TypeError, ValueError):
                continue
        if combined != pattern["service_id"]:
            continue
        created = _parse_order_created_at(order.get("created_at"))
        if created is None:
            continue
        year, week, _ = created.astimezone(EAT_TZ).isocalendar()
        if (year, week) == (iso_year, iso_week):
            return True
    return False


def friday_offer_keyboard(pattern) -> InlineKeyboardMarkup:
    """Yes / Not today for the Friday offer. Buttons stay English
    (same rule as Confirm cards — buttons are never translated)."""
    return InlineKeyboardMarkup([[
        InlineKeyboardButton(
            t("friday_yes_button", "en"),
            callback_data=(
                f"friday:{pattern['service_id']}:{pattern['quantity']}"
            ),
        ),
        InlineKeyboardButton(
            t("friday_no_button", "en"),
            callback_data=(
                f"fridayno:{pattern['service_id']}:{pattern['quantity']}"
            ),
        ),
    ]])


async def maybe_friday_pattern_offer(update, user_id: int, lang: str,
                                     now=None, orders=None) -> bool:
    """The Friday-pattern offer (feature 5, 15 Nov 2026): when the
    user messages on the weekday they usually order on, offer that
    order once — "You usually order 1000 TikTok views on Fridays —
    want me to place it?" At most one offer per pattern per week
    (FRIDAY_OFFERED, keyed by ISO week); never while a draft or
    Confirm card is open; never when the same order was already
    placed this week; never when an offer is already open. Returns
    True when the offer was sent (the caller returns). The check
    runs when the user messages, so it costs one orders-list call
    per light message and never wakes a sleeping user. In-memory
    only: a restart may re-offer (same caveat as the delivery
    watch). Any API failure is a quiet no-offer, never an error
    in the chat."""
    user_id = int(user_id)
    now = now or datetime.now(timezone.utc)
    today_eat = now.astimezone(EAT_TZ)
    weekday = today_eat.weekday()
    iso_year, iso_week, _ = today_eat.isocalendar()
    _open = FRIDAY_PENDING.get(user_id)
    if _open is not None:
        # An offer ignored last week must not block this week's
        # offer: a pending offer from a different ISO week is
        # stale and dropped. The week's key in FRIDAY_OFFERED
        # still stops a second offer inside the same week.
        if _open.get("offered_week") == (iso_year, iso_week):
            return False
        FRIDAY_PENDING.pop(user_id, None)
        FRIDAY_LINK.pop(user_id, None)
    if _friday_has_open_state(user_id):
        return False
    try:
        # `orders` is the caller's shared recent-orders list when
        # given (owner, 18 Nov 2026: the Friday and feedback gates
        # fetched the same list twice on one light turn); else
        # fetch it here, as before.
        orders = (
            orders
            if orders is not None
            else await paxyo.recent_orders(user_id, limit=20)
        )
        patterns = [
            p for p in detect_weekly_patterns(orders)
            if p["weekday"] == weekday
        ]
    except Exception as exc:
        log.warning("friday pattern orders failed: %s", exc)
        return False
    for pattern in patterns:
        key = (
            user_id, pattern["service_id"], pattern["quantity"],
            weekday, iso_year, iso_week,
        )
        if key in FRIDAY_OFFERED:
            continue
        if _friday_ordered_this_week(orders, pattern, iso_year, iso_week):
            continue
        FRIDAY_OFFERED.add(key)
        FRIDAY_PENDING[user_id] = {
            **pattern, "offered_week": (iso_year, iso_week),
        }
        name = (
            short_service_name(pattern["service_name"])
            or f"service {pattern['service_id']}"
        )
        await reply_message(
            update.message,
            t(
                "friday_offer", lang,
                quantity=pattern["quantity"], service=name,
                weekday=_friday_weekday_name(weekday, lang),
            ),
            lang,
            reply_markup=friday_offer_keyboard(pattern),
        )
        return True
    return False


def feedback_keyboard(order_id) -> InlineKeyboardMarkup:
    """👍 / 👎 for the feedback ask. Buttons stay English, like
    Confirm cards and the rating buttons."""
    return InlineKeyboardMarkup([[
        InlineKeyboardButton(
            "👍", callback_data=f"feedback:good:{order_id}",
        ),
        InlineKeyboardButton(
            "👎", callback_data=f"feedback:bad:{order_id}",
        ),
    ]])


async def _first_completed_order(user_id: int, orders=None):
    """The user's OLDEST visible completed order (order_id, created
    datetime), or None. The orders endpoint returns at most 20,
    newest first, so the oldest visible completed order is the
    proxy for the first order: when 20+ orders exist and the
    oldest visible is already >= 7 days old, the first order
    certainly is too; when it is newer, the user is not due yet.
    An order with no parseable date cannot prove the first order
    is old enough, so it is skipped. Never raises."""
    try:
        # `orders` is the caller's shared recent-orders list when
        # given (owner, 18 Nov 2026 — same list the Friday gate
        # just used); else fetch it here, as before.
        orders = (
            orders
            if orders is not None
            else await paxyo.recent_orders(user_id, limit=20)
        ) or []
    except Exception as exc:
        log.warning("feedback recent orders failed: %s", exc)
        return None
    oldest = None
    oldest_dt = None
    for order in orders:
        if not isinstance(order, dict):
            continue
        if str(order.get("status") or "").strip().lower() != "completed":
            continue
        created = _parse_order_created_at(order.get("created_at"))
        if created is None:
            continue
        if oldest_dt is None or created < oldest_dt:
            oldest_dt = created
            oldest = order
    if oldest is None:
        return None
    return (oldest.get("id") or oldest.get("order_id"), oldest_dt)


async def maybe_feedback_ask(update, user_id: int, lang: str,
                             now=None, orders=None) -> bool:
    """The feedback check (feature 10, 15 Nov 2026): 7 days after
    the user's first completed order, the next time they message
    the bot, ask once "How was your first order with Paxyo?" with
    👍/👎 buttons. At most once per user: the in-memory
    FEEDBACK_ASKED is checked first, then the server's
    /feedback/asked (the backstop across restarts); the ask is
    recorded in both right after it is sent. Never while a draft
    or Confirm card is open (same open-state check as the Friday
    offer), and never while a Friday offer is itself open and
    awaiting the user's answer — two asks never stack. Never via
    the scheduler, never on an order message (the caller only
    runs this on light intents). A 404 on the asked-endpoint falls back to memory only — never a crash, and
    the ask still goes out once per process. Returns True when
    the ask was sent (the caller returns: the ask replaces the
    light-intent reply for that turn)."""
    user_id = int(user_id)
    if user_id in FEEDBACK_ASKED:
        return False
    if user_id in FRIDAY_PENDING:
        # A Friday offer is open, awaiting the user's yes/no — the
        # feedback ask waits until it is answered, so two asks
        # never stack on one user in the same conversation. (The
        # Friday test's second greeting relies on this: the offer
        # is still open, so the stock greeting answers instead.)
        return False
    if _friday_has_open_state(user_id):
        return False
    first = await _first_completed_order(user_id, orders=orders)
    if first is None:
        return False
    order_id, created = first
    now_dt = now or datetime.now(timezone.utc)
    if (now_dt - created).total_seconds() < FEEDBACK_DAYS * 86400:
        return False
    asked = None
    try:
        asked = await paxyo.feedback_asked(user_id)
    except Exception as exc:
        log.warning("feedback asked check failed: %s", exc)
        asked = None
    if asked is True:
        FEEDBACK_ASKED.add(user_id)
        return False
    await reply_message(
        update.message, t("feedback_ask", lang), lang,
        reply_markup=feedback_keyboard(order_id),
    )
    FEEDBACK_ASKED.add(user_id)
    try:
        await paxyo.mark_feedback_asked(user_id)
    except Exception as exc:
        log.warning("feedback mark asked failed: %s", exc)
    return True


async def handle_feedback_text(update, text: str, lang: str,
                               voice=False) -> bool:
    """The feedback follow-up branch of handle_order_text: True
    when the message belonged to the feedback flow and has been
    answered, False when no feedback flow is open. Runs before
    the classifier, right after the report flow.

    After a 👎 tap the bot asked what went wrong; the next message
    is filed via report_problem against that first order and
    confirmed briefly. "cancel" (or "never mind", "stop") drops
    the flow with nothing filed; a quick-reply tap drops it and
    runs normally; a bare "yes" is not an answer, so the question
    is asked again instead of filing one word — all mirroring the
    report-a-problem flow. A 404 (the support endpoint is not
    live yet) or any other failure is answered honestly with the
    t.me/paxyo fallback — the bot never pretends the feedback
    was filed."""
    user = update.effective_user
    flow = FEEDBACK_PENDING.get(user.id)
    if flow is None:
        return False
    if quick_reply_action(text) is not None:
        FEEDBACK_PENDING.pop(user.id, None)
        return False
    if is_cancel_request(text):
        FEEDBACK_PENDING.pop(user.id, None)
        await reply_message(
            update.message, t("feedback_cancelled", lang),
            lang, voice=voice,
        )
        return True
    order_id = flow.get("order_id")
    if is_acceptance(text):
        await reply_message(
            update.message,
            t("feedback_bad_ask", lang, order_id=order_id),
            lang, voice=voice,
        )
        return True
    FEEDBACK_PENDING.pop(user.id, None)
    # The server caps the message at 2000 characters and rejects
    # longer input — trim, so a long description still files.
    message = (text or "").strip()[:2000]
    result = None
    if paxyo is not None:
        try:
            result = await paxyo.report_problem(
                user.id, message, order_id=order_id
            )
        except Exception as exc:
            log.warning("feedback report failed: %s", exc)
            result = None
    if isinstance(result, dict) and result.get("ok"):
        await reply_message(
            update.message,
            t("feedback_filed", lang, order_id=order_id),
            lang, voice=voice,
        )
    else:
        await reply_message(
            update.message,
            t("feedback_not_live", lang, order_id=order_id),
            lang, voice=voice,
        )
    return True


async def _friday_accept_text(user_id: int, pattern, lang: str):
    """Build the link-ask after the user accepts the Friday offer.
    Returns (text, markup). Pre-fills PARTIAL with the pattern's
    platform + metric + quantity and pins the pattern's service
    one-shot (USUAL_SERVICE, like the "same as usual" fallback),
    so the link the user sends next completes the order and the
    normal Confirm card runs — nothing is placed here. The old
    link is kept in FRIDAY_LINK only: it is offered as the
    "Same link as last time" button, never reused silently. A
    service that vanished / went inactive / is blacklisted gets
    the honest friday_gone line instead. Prices come from the
    catalogue, as always."""
    user_id = int(user_id)
    try:
        services = await paxyo.services()
    except Exception:
        services = []
    service, error = resolve_named_service(
        services or [], pattern["service_id"]
    )
    if service is None:
        return t("friday_gone", lang), None
    platform, _hint = _platform_hint_of_service(service)
    metric = _primary_metric(" ".join(_name_kinds(service.get("name"))))
    hint = (
        f"{platform} {metric}" if platform and metric
        else (metric or platform or "")
    )
    PARTIAL[user_id] = {
        k: v for k, v in {
            "platform": platform,
            "service_hint": hint,
            "quantity": pattern["quantity"],
        }.items() if v is not None
    }
    USUAL_SERVICE[user_id] = service_combined_id(service)
    if pattern.get("link"):
        FRIDAY_LINK[user_id] = pattern["link"]
    touch_partial_activity(user_id)
    total = estimated_total_etb(
        float(service.get("rate_etb_per_1000", 0)), pattern["quantity"]
    )
    name = short_service_name(service.get("name"))
    if pattern.get("link"):
        text = t(
            "friday_link_ask_same", lang, service=name,
            quantity=pattern["quantity"], total=format_money(total),
        )
        markup = InlineKeyboardMarkup([[
            InlineKeyboardButton(
                t("friday_same_link_button", "en"),
                callback_data=(
                    f"fridaylink:{pattern['service_id']}"
                    f":{pattern['quantity']}"
                ),
            ),
        ]])
    else:
        text = t(
            "friday_link_ask", lang, service=name,
            quantity=pattern["quantity"], total=format_money(total),
        )
        markup = None
    return text, markup


async def _friday_accept_reply(update, user_id: int, pattern, lang: str,
                               voice: bool = False):
    """Accepting the Friday offer by typing "yes": same pre-fill
    as the button tap, as a new message."""
    text, markup = await _friday_accept_text(user_id, pattern, lang)
    await reply_message(
        update.message, text, lang, voice=voice, reply_markup=markup
    )


_FRIDAY_DECLINE_WORDS = frozenset((
    "no", "nope", "no thanks", "not today", "maybe later", "later",
    "not now", "አይ", "አይደለም", "ዛሬ አይደለም",
))


def is_friday_decline(text: str) -> bool:
    """True when the message declines the open Friday offer
    ("no", "not today", …). Only read while an offer is open."""
    s = " ".join((text or "").strip().lower().split())
    s = s.strip(" .!,?።፣")
    return s in _FRIDAY_DECLINE_WORDS


async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # A redelivered /start (same update id, seen 14 Nov 2026: the
    # greeting went out twice at 07:26) must not greet twice.
    if _update_seen(update):
        return
    user = update.effective_user
    lang = detect_language("", user.language_code)
    try:
        await paxyo.create_user(
            user.id, username=user.username, first_name=user.first_name
        )
    except Exception as exc:  # account creation must never block /start
        log.warning("create_user failed (continuing): %s", exc)
    # Deep-link invite code (per-user invite codes, 15 Nov 2026):
    # a /start carrying a code records who referred this user
    # BEFORE they deposit, so the referrer can earn the 20%
    # first-deposit bonus (server-side; the hook is not installed
    # live yet — see server/api-referrals.php, and whether the
    # server credits ANY bonus today is unverified). Best-effort:
    # an invalid payload is ignored silently, the user's own code
    # is never recorded, and a failure here never blocks /start.
    # The shared code is recorded too (the server maps it to
    # referrer 0, no attribution, no bonus).
    _payload = None
    try:
        _args = getattr(context, "args", None) or []
        if _args:
            _payload = str(_args[0]).strip()
    except Exception:
        _payload = None
    if _payload:
        _code = _payload.upper()
        _owner = invite_code_owner(_code)
        if _code == INVITE_CODE or (_owner is not None and _owner != user.id):
            try:
                _ref_result = await paxyo.record_referral(user.id, _code)
            except Exception as exc:  # referral must never block /start
                log.warning("record_referral failed (continuing): %s", exc)
            else:
                # Registration notice (William, 16 Nov 2026): the code
                # giver hears someone joined with their code — fresh
                # registration only, real referrer only (the shared
                # code maps to referrer 0, already-recorded means the
                # user joined before). Best-effort, never blocks /start.
                if (
                    isinstance(_ref_result, dict)
                    and not _ref_result.get("already_recorded")
                    and (_ref_result.get("referrer_telegram_id") or 0) > 0
                ):
                    await _notify_referrer_joined(
                        getattr(context, "bot", None),
                        _ref_result["referrer_telegram_id"],
                        user.first_name, user.username,
                    )
    # Ideas batch (15 Nov 2026): the quick-reply keyboard stays
    # under the chat from here on; a brand-new user also gets the
    # one-time cheapest-test offer as a second message.
    # Deposit-hijack fix (16 Nov 2026): /start switches flows too,
    # so an open order draft is parked first (saved, not lost).
    # A bundle draft is dropped (ideas batch 1 #3).
    _parked = _park_order_draft(user.id)
    BUNDLE_DRAFT.pop(user.id, None)
    await update.message.reply_text(
        t("greeting", lang), reply_markup=hide_reply_keyboard()
    )
    if _parked:
        await update.message.reply_text(t("draft_parked", lang))
    record_exchange(user.id, update.message.text or "/start", t("greeting", lang))
    nudge = await maybe_first_order_nudge(user.id, lang)
    if nudge is not None:
        text, keyboard = nudge
        await update.message.reply_text(text, reply_markup=keyboard)


async def balance_text(user_id: int, lang: str) -> str:
    """Balance line for a user. Shared by /balance and the balance
    intent, so both answer the same way."""
    try:
        data = await paxyo.balance(user_id)
    except Exception as exc:
        log.warning("balance failed: %s", exc)
        return t("not_understood", lang)
    if not data.get("found"):
        return t("greeting", lang)
    return t("balance", lang, balance=format_money(data.get("balance", 0)))


async def last_order_status_text(user_id: int, lang: str) -> str:
    """Status line for the user's last order. Shared by /orders and
    the orders intent. The in-memory LAST_ORDER is checked first; when
    it is empty (e.g. after a bot restart) the last order is resolved
    from the Paxyo API instead, so "where is my order" still works."""
    order_id = LAST_ORDER.get(user_id)
    provider = None
    if not order_id:
        last = await resolve_last_order(user_id)
        if not last:
            return t("no_orders", lang)
        order_id = last.get("id") or last.get("order_id")
        if not order_id:
            return t("no_orders", lang)
        # Provider-aware status (second provider, 15 Nov 2026):
        # the order row carries provider/combined_id after the
        # server patch; without it this reads as GOP and
        # the generic path runs, exactly like before.
        provider = service_provider(last)
        LAST_ORDER[user_id] = order_id
    try:
        data = await paxyo.order_status(order_id, user_id, provider=provider)
    except Exception as exc:
        log.warning("order_status failed: %s", exc)
        return t("not_understood", lang)
    status = data.get("status") or data.get("order", {}).get("status", "?")
    if str(status).strip().lower() == "partial":
        # Partial order (13, 15 Nov 2026): the user asked where
        # their order is — attempt the refund now and answer with
        # what arrived and what was refunded, instead of a bare
        # "partial" status. The quantity is left to the helper,
        # which falls back to delivered + remains (the server's
        # exact figures). A None reply (endpoint not live yet, or
        # the status moved on) falls through to the plain status
        # line below. No top-up here: the user asked a question,
        # so nothing is ordered — the watch cycle tops up.
        line, _info = await _maybe_partial_refund(None, user_id, order_id, None)
        if line is not None:
            return line
    return t("order_ok", lang, order_id=order_id, status=status)


async def schedules_text(user_id: int, lang: str) -> str:
    """Short list of the user's active repeating orders, or the
    no-schedules line. Shared by the schedules intent and /schedules."""
    try:
        schedules = await paxyo.list_recurring(user_id)
    except Exception as exc:
        log.warning("list_recurring failed: %s", exc)
        return t("not_understood", lang)
    if not schedules:
        return t("no_schedules", lang)
    lines = []
    for i, sched in enumerate(schedules, 1):
        name = short_service_name(sched.get("service_name")) or f"service {sched.get('service_id')}"
        lines.append(
            f"{i}. {name} ×{sched.get('quantity')} "
            f"every {format_interval(sched.get('interval_minutes'))}"
        )
    return "\n".join(lines)


