# ------------------------------------------------------- order accept ---
# A bare acceptance ("yes", "confirm", "አዎ", ...) while an order is
# pending places that order. Only a bare acceptance counts: a new order
# message never matches, because it names a service.
ACCEPT_WORDS = frozenset({
    "yes", "yeah", "yep", "ok", "okay", "confirm", "confirmed",
    "place it", "do it", "go ahead", "proceed", "sure",
    "አዎ", "እሺ", "ይሁን", "አረጋግጥ", "ፈጽም", "ቀጥል", "እሺ ይሁን",
})


def is_acceptance(text: str) -> bool:
    """True when the message is just an acceptance of a pending order."""
    s = " ".join((text or "").strip().lower().split())
    s = s.strip(" .!,?።፣")
    return s in ACCEPT_WORDS


def pending_for_user(user_id: int):
    """(confirm_id, pending) of the user's most recent pending order,
    or (None, None) when they have none."""
    for confirm_id, pending in reversed(list(PENDING.items())):
        if pending["user_id"] == user_id:
            return confirm_id, pending
    return None, None


def drop_pending_confirms_for_user(user_id: int):
    """Drop every pending normal Confirm for a user. PENDING is
    keyed by confirm id, not by user, so this scans the values —
    a bare PENDING.pop(user_id) would pop nothing. Used when a
    delayed order is saved (19 Nov 2026, Order ID 1881): a stale
    normal Confirm must not survive to be placed by a later bare
    "Ok". Only normal confirms live in PENDING; delayed, recurring
    and auto-refill setups live in their own dicts and are never
    touched here."""
    for confirm_id in [
        cid for cid, entry in PENDING.items()
        if entry.get("user_id") == user_id
    ]:
        PENDING.pop(confirm_id, None)


async def create_order_for_service(client, user_id: int, service, link: str,
                                   quantity: int, idempotency_key: str,
                                   split=None, drip=None):
    """Place an order on the service's own provider (second provider,
    15 Nov 2026): a GOP service goes through POST /orders,
    an SMM Social Media service through POST /orders/smm. The
    service dict decides — its provider/combined_id, never the bare
    id (2,790 bare ids collide between the providers). Same reply
    shape either way; errors raise exactly like create_order does,
    so every caller keeps its own failure handling. `split` is an
    optional dict of split-test fields (split_group_id,
    split_part, confirmed_total_etb, paxyo_cover_etb) passed
    through to the order endpoint — omitted entirely for a normal
    order, so every existing caller is unchanged. `drip` is an
    optional dict (runs, interval) for a provider drip-feed order
    (customizations #15) — quantity is then the PER-RUN quantity,
    and the server charges quantity x runs up front."""
    split = dict(split or {})
    drip = dict(drip or {})
    if service_provider(service) == "smm":
        return await client.create_order_smm(
            user_id, int(service["service"]), link, quantity, idempotency_key,
            split_group_id=split.get("split_group_id"),
            split_part=split.get("split_part"),
            confirmed_total_etb=split.get("confirmed_total_etb"),
            paxyo_cover_etb=split.get("paxyo_cover_etb"),
            runs=drip.get("runs"),
            interval=drip.get("interval"),
        )
    return await client.create_order(
        user_id, int(service["service"]), link, quantity, idempotency_key,
        split_group_id=split.get("split_group_id"),
        split_part=split.get("split_part"),
        confirmed_total_etb=split.get("confirmed_total_etb"),
        paxyo_cover_etb=split.get("paxyo_cover_etb"),
        runs=drip.get("runs"),
        interval=drip.get("interval"),
    )


async def _place_split_test(pending, user_id: int, split_qtys):
    """Place the 10% test leg of a big order (split-test, owner,
    15 Nov 2026). Returns (result, error) like place_pending_order:
    result carries split_test=True so the callers can say the order
    is being tested first. The test is a REAL order on the fastest
    (confirmed) service — it is recorded in the orders table and
    the mini-app history like any order, with the split markers on
    it (split-test idempotency key + split fields). The remaining
    90% is placed by the delivery watch once this test delivers."""
    service = pending["service"]
    quantity = pending["quantity"]
    total = pending["total"]
    link = pending["link"]
    test_qty, rest_qty = split_qtys
    group_id = uuid.uuid4().hex
    try:
        result = await create_order_for_service(
            paxyo, user_id, service, link, test_qty,
            f"split-test-{uuid.uuid4().hex}",
            split={
                "split_group_id": group_id,
                "split_part": "test",
                "confirmed_total_etb": float(total),
            },
        )
    except httpx.HTTPStatusError as exc:
        log.warning("split test rejected: %s", exc.response.status_code)
        return None, ("order_failed",)
    except Exception as exc:
        log.warning("split test failed: %s", exc)
        return None, ("order_failed",)
    order = result.get("order", result) if isinstance(result, dict) else {}
    order_id = order.get("id") or order.get("order_id") or "?"
    status = order.get("status", "pending")
    LAST_ORDER[user_id] = order_id
    test_cost = estimated_total_etb(
        float(service.get("rate_etb_per_1000") or 0), test_qty
    )
    server_total = order.get("total", order.get("charge"))
    if server_total is not None:
        try:
            test_cost = round(float(server_total), 2)
        except (TypeError, ValueError):
            pass
    watch_order(
        user_id, order_id, service, test_qty, link,
        total=test_cost,
        split={
            "group_id": group_id,
            "leg": "test",
            "total_qty": quantity,
            "test_qty": test_qty,
            "rest_qty": rest_qty,
            "confirmed_total": float(total),
            "spent": 0.0,
        },
        deadline=pending.get("deadline"),
    )
    learn_from_placed_order(user_id, service, quantity)
    return {
        "order_id": order_id,
        "status": status,
        "service": (
            clean_service_name(service.get("name"))
            if pending.get("full_name")
            else short_service_name(service.get("name"))
        ),
        "quantity": quantity,
        "link": link,
        "total": total,
        "split_test": True,
        "test_order_id": order_id,
        "test_quantity": test_qty,
    }, None


async def user_is_banned(user_id: int) -> bool:
    """True when the server says the user is banned (GET
    /admin/users/{id}/ban). Fail-open by design: a missing
    endpoint (404), a transport failure, or any other error
    means NOT banned — the bot must never block a good user
    because a lookup failed. A ban only ever blocks when the
    server positively says so."""
    if paxyo is None:
        return False
    try:
        data = await paxyo.get_user_ban(user_id)
    except Exception as exc:
        log.warning("get_user_ban failed: %s", exc)
        return False
    if not isinstance(data, dict):
        return False
    return bool(data.get("banned"))


async def place_pending_order(pending, user_id: int):
    """Balance check + create order for a pending order.

    Returns (result, error). On success result is a dict with the order
    id, status, service name, quantity, link and total, and error is
    None. On failure result is None and error is ("insufficient",
    balance, total), ("order_failed",), ("not_understood",),
    ("bad_link", reason), ("bad_quantity",) or ("banned",).
    """
    # Ban (19 Nov 2026): a banned user places nothing — checked
    # first, before any money moves. The callers answer ("banned",)
    # with the short "banned" reply.
    if await user_is_banned(user_id):
        return None, ("banned",)
    service = pending["service"]
    quantity = pending["quantity"]
    total = pending["total"]
    # Link check (cancel-cutting item 5, 16 Nov 2026): before any
    # money moves — a link that does not fit the service is
    # refused, never placed. The quantity bounds are enforced
    # here too as a backstop (complete_order already checks, but
    # the Confirm card is not the only caller).
    link_error = validate_order_link(pending.get("link"), service)
    if link_error is not None:
        return None, ("bad_link", link_error)
    if validate_quantity(quantity, service) is not None:
        return None, ("bad_quantity",)
    try:
        bal = await paxyo.balance(user_id)
    except Exception as exc:
        log.warning("balance check failed: %s", exc)
        return None, ("not_understood",)
    if not bal.get("found") or float(bal.get("balance", 0)) < total:
        return None, ("insufficient", bal.get("balance", 0), total)
    # Drip-feed (customizations #15, 15 Nov 2026): a drip order is
    # placed WHOLE — one provider order with runs/interval — never
    # split-tested. A 10% test of a drip would itself be a drip,
    # and the provider counts each run against the test's small
    # quantity; the test would prove nothing about the full order.
    # The pending dict carries drip={"runs", "interval",
    # "per_run_qty"} (set by complete_order); the per-run quantity
    # is what the provider is asked for, and the total the
    # customer confirmed is quantity x runs.
    drip = pending.get("drip") or {}
    if drip:
        try:
            result = await create_order_for_service(
                paxyo, user_id, service, pending["link"],
                drip.get("per_run_qty", quantity),
                uuid.uuid4().hex,
                drip={
                    "runs": drip.get("runs"),
                    "interval": drip.get("interval"),
                },
            )
        except httpx.HTTPStatusError as exc:
            log.warning(
                "drip create_order rejected: %s", exc.response.status_code
            )
            return None, ("order_failed",)
        except Exception as exc:
            log.warning("drip create_order failed: %s", exc)
            return None, ("order_failed",)
        order = result.get("order", result) if isinstance(result, dict) else {}
        order_id = order.get("id") or order.get("order_id") or "?"
        status = order.get("status", "pending")
        LAST_ORDER[user_id] = order_id
        watch_order(
            user_id, order_id, service, quantity, pending["link"],
            total=total, drip=dict(drip),
            deadline=pending.get("deadline"),
        )
        learn_from_placed_order(user_id, service, quantity)
        return {
            "order_id": order_id,
            "status": status,
            "service": (
                clean_service_name(service.get("name"))
                if pending.get("full_name")
                else short_service_name(service.get("name"))
            ),
            "quantity": quantity,
            "link": pending["link"],
            "total": total,
            "drip": dict(drip),
        }, None
    # Split-test for big orders (owner, 15 Nov 2026): over 400 ETB
    # the order is placed as a 10% test first; the remaining 90%
    # follows once the test delivers (delivery watch). A service
    # the order cannot be split on falls through to the normal
    # whole placement below — the order still goes through.
    try:
        total_value = float(total)
    except (TypeError, ValueError):
        total_value = 0.0
    if total_value > SPLIT_TEST_THRESHOLD_ETB:
        split_qtys = split_test_quantities(quantity, service)
        if split_qtys is not None:
            return await _place_split_test(pending, user_id, split_qtys)
    try:
        result = await create_order_for_service(
            paxyo, user_id, service, pending["link"], quantity,
            uuid.uuid4().hex,
        )
    except httpx.HTTPStatusError as exc:
        log.warning("create_order rejected: %s", exc.response.status_code)
        return None, ("order_failed",)
    except Exception as exc:
        log.warning("create_order failed: %s", exc)
        return None, ("order_failed",)
    order = result.get("order", result) if isinstance(result, dict) else {}
    order_id = order.get("id") or order.get("order_id") or "?"
    status = order.get("status", "pending")
    LAST_ORDER[user_id] = order_id
    # Ideas batch (15 Nov 2026): watch this order for its delivery
    # message and stuck warning — one of each, from the scheduler.
    watch_order(user_id, order_id, service, quantity, pending["link"],
                total=total, deadline=pending.get("deadline"))
    # Per-user personality (feature 5, 15 Nov 2026): a placed order
    # is proof of the user's usual — learn from it (the usual only
    # counts for defaults after the same platform+metric is placed
    # twice; see learn_from_placed_order).
    learn_from_placed_order(user_id, service, quantity)
    return {
        "order_id": order_id,
        "status": status,
        "service": (
            clean_service_name(service.get("name"))
            if pending.get("full_name")
            else short_service_name(service.get("name"))
        ),
        "quantity": quantity,
        "link": pending["link"],
        "total": total,
    }, None


async def _maybe_start_auto_repeat(user_id, pending):
    """Auto-repeat (#16, customizations, 15 Nov 2026): the customer
    set a standing repeat for this platform+metric. After they
    place an order of that type, create the recurring schedule
    from it — once, and only when no schedule for that type exists
    yet. Best-effort: a failure never fails the order (it is
    already placed). Returns True when a schedule was created.
    Only GOP services: the server's recurring row carries no
    provider column, so a repeat on an SMM service would place on
    the wrong provider — those orders skip the auto-repeat (the
    pref stays, and the next GOP order of that type starts it).
    The dedup maps each existing schedule's service through the
    catalogue, so a repeat already running on a different service
    of the same type still counts as one."""
    repeat = get_pref(user_id, "pref_auto_repeat")
    if not isinstance(repeat, dict):
        return False
    service = pending.get("service") or {}
    if service_provider(service) != "gop":
        return False
    platform, _ = _platform_hint_of_service(service)
    metric = _primary_metric(" ".join(_name_kinds(service.get("name"))))
    if platform != repeat.get("platform") or metric != repeat.get("metric"):
        return False
    try:
        existing = await paxyo.list_recurring(user_id)
        services = await paxyo.services()
    except Exception as exc:
        log.warning("auto-repeat list failed: %s", exc)
        return False
    by_combined = {}
    for svc in services or []:
        by_combined[service_combined_id(svc)] = svc
    for schedule in existing or []:
        if not isinstance(schedule, dict):
            continue
        svc = None
        combined = schedule.get("combined_id")
        if combined:
            svc = by_combined.get(combined)
        if svc is None and schedule.get("service_id") is not None:
            svc = by_combined.get(f"gop:{schedule.get('service_id')}")
        if svc is None:
            continue
        s_platform, _ = _platform_hint_of_service(svc)
        s_metric = _primary_metric(
            " ".join(_name_kinds(svc.get("name")))
        )
        if s_platform == platform and s_metric == metric:
            return False
    try:
        await paxyo.create_recurring(
            user_id, int(service["service"]), pending["link"],
            pending["quantity"], repeat["interval_minutes"],
        )
    except Exception as exc:
        log.warning("auto-repeat create failed: %s", exc)
        return False
    return True


def _restore_draft_after_bad_link(pending, user_id: int):
    """Restore the order draft (minus the bad link) after a link
    check refusal (cancel-cutting item 5, 16 Nov 2026): the user
    only needs to send the right link to continue — the platform,
    metric, emoji and quantity are kept. Returns (platform, hint)
    for the ask-link question. Pure apart from the PARTIAL write."""
    _platform, _hint = _platform_hint_of_service(pending.get("service") or {})
    PARTIAL[user_id] = {
        k: v for k, v in {
            "platform": pending.get("platform") or _platform,
            "service_hint": pending.get("service_hint") or _hint,
            "reaction_emoji": pending.get("reaction_emoji"),
            "quantity": pending.get("quantity"),
        }.items() if v is not None
    }
    return _platform, _hint


async def send_order_result(message, lang: str, pending, user_id: int):
    """Place a pending order and send the full summary as a new TEXT
    message. Used when the user accepts by voice or by text: the
    summary is always text, even when the user spoke."""
    result, error = await place_pending_order(pending, user_id)
    if error:
        key = error[0]
        if key == "insufficient":
            await message.reply_text(
                t(
                    "insufficient",
                    lang,
                    balance=format_money(error[1]),
                    total=format_money(error[2]),
                ),
                reply_markup=deposit_webapp_keyboard(lang),
            )
        elif key == "bad_link":
            # Link check (item 5): do not place — ask for the
            # right link with the per-order-type wording, and
            # restore the draft (minus the bad link) so the user
            # can continue by sending just the link.
            _platform, _hint = _restore_draft_after_bad_link(
                pending, user_id
            )
            await message.reply_text(
                ask_link_text(_platform, _hint, lang)
            )
        elif key == "bad_quantity":
            # Backstop that should never fire (complete_order
            # validates first): state the bounds plainly.
            _svc = pending.get("service") or {}
            await message.reply_text(
                t(
                    "bad_quantity", lang,
                    service=short_service_name(_svc.get("name")),
                    min=_svc.get("min"), max=_svc.get("max"),
                )
            )
        else:
            await message.reply_text(t(key, lang))
        return
    summary = t(
        "order_summary",
        lang,
        service=result["service"],
        quantity=result["quantity"],
        link=result["link"],
        total=format_money(result["total"]),
        order_id=result["order_id"],
        status=result["status"],
    )
    # Split-test (15 Nov 2026): the summary shows the full order
    # as confirmed, plus one line saying the first 10% is being
    # tested first — the rest follows once it delivers.
    if result.get("split_test"):
        summary += "\n" + t(
            "order_split_test_placed", lang,
            test_quantity=result["test_quantity"],
            quantity=result["quantity"],
        )
    # Drip-feed (19 Nov 2026): the summary names the plan, so a
    # drip never reads like one order of the whole quantity.
    _drip_line = _drip_summary_line(lang, result.get("drip") or {})
    if _drip_line:
        summary += "\n" + _drip_line
    # No-confirm (#18) and auto-repeat (#16): a small order placed
    # without asking says so in one line, and a standing repeat
    # for this order type starts now (once — see
    # _maybe_start_auto_repeat). Both lines ride inside the
    # summary, so the tone shaping below keeps them.
    if pending.get("no_confirm"):
        summary += (
            "\nPlaced without asking, as you set for small orders."
        )
    if await _maybe_start_auto_repeat(user_id, pending):
        repeat = get_pref(user_id, "pref_auto_repeat") or {}
        summary += (
            "\nRepeating every "
            f"{format_interval(repeat.get('interval_minutes', 0))} "
            "from now on."
        )
    # Ideas batch (15 Nov 2026): one-tap reorder under the summary,
    # and the quick-reply keyboard stays under the chat after a
    # completed flow. (The Confirm-tap path shows the same summary
    # by editing the card in place — inline buttons cannot ride on
    # it, and the reply keyboard is already under the chat.)
    markup = None
    if result.get("order_id") not in (None, "?"):
        markup = reorder_keyboard([{
            "id": result["order_id"],
            "service_name": result["service"],
            "quantity": result["quantity"],
        }])
    # Per-user personality (feature 5, 15 Nov 2026): the
    # confirmation is shaped for the user's learned tone — brief
    # gets the summary alone (no humour line, no hint message),
    # chatty gets one warm line, formal gets a polite opening.
    # No learned tone -> the summary + humour + hint exactly as
    # before. Prices and the order itself are untouched.
    shaped = tone_order_summary(user_id, lang, summary)
    brief = user_tone(user_id) == "brief"
    if not brief:
        shaped += "\n" + humor_line(user_id, lang)
    # No long dash in any reply (owner, 17 Nov 2026): the humour
    # line can carry one ("Order in — nice choice!"), and this
    # send bypasses reply_message, so strip it here.
    await message.reply_text(
        _strip_dashes(shaped),
        reply_markup=markup,
    )
    if not brief:
        await message.reply_text(
            t("order_done_hint", lang),
            reply_markup=hide_reply_keyboard(),
        )
    _record_bot_reply(summary)


def pending_recurring_for_user(user_id: int):
    """(confirm_id, draft) of the user's most recent repeating-order
    plan awaiting Confirm, or (None, None)."""
    for confirm_id, draft in reversed(list(PENDING_RECURRING.items())):
        if draft["user_id"] == user_id:
            return confirm_id, draft
    return None, None


def pending_auto_refill_for_user(user_id: int):
    """(confirm_id, setup) of the user's most recent auto-refill
    awaiting Confirm, or (None, None)."""
    for confirm_id, setup in reversed(list(PENDING_AUTO_REFILL.items())):
        if setup["user_id"] == user_id:
            return confirm_id, setup
    return None, None


def list_auto_refills(user_id: int):
    """The user's confirmed auto-refills (in-memory registry), or []."""
    return list(AUTO_REFILL_ACTIVE.get(user_id) or [])


def register_auto_refill(setup, user_id: int):
    """Switch an auto-refill on from a confirmed setup. Returns
    the stored refill record. IN-MEMORY ONLY until the server
    bot_refills table lands (see AUTO_REFILL_ACTIVE): the record
    carries count_usage and last_count/last_check so the hourly
    check can run from it, and the server worker will persist
    the same shape in bot_refills."""
    refill = {
        "id": f"mem-{uuid.uuid4().hex[:12]}",
        "user_id": user_id,
        "service": setup.get("service"),
        "link": setup.get("link"),
        "target": setup.get("target"),
        "metric": setup.get("metric"),
        "platform": setup.get("platform"),
        "daily_cap": setup.get("daily_cap"),
        "trigger": setup.get("trigger"),
        "spent_today": 0,
        "spent_date": None,
        "last_count": None,
        "last_check": None,
        "count_usage": {},
        "created_at": time.time(),
    }
    AUTO_REFILL_ACTIVE.setdefault(user_id, []).append(refill)
    return refill


def _auto_refill_metric(service_hint, service):
    """The countable metric for a refill: the kind the user named
    ("followers", "views", "likes", "members", "subscribers"), or
    the service's own kind. Only views/followers (TikTok),
    views/subscribers (YouTube) and members (Telegram) have a
    count chain — anything else refuses at setup."""
    hint = (service_hint or "").strip().lower()
    for metric in ("followers", "views", "likes", "members", "subscribers"):
        if metric in hint:
            return metric
    name = str((service or {}).get("name") or "").lower()
    for metric in ("followers", "views", "likes", "members", "subscribers"):
        if metric in name:
            return metric
    category = str((service or {}).get("category") or "").lower()
    for metric in ("followers", "views", "likes", "members", "subscribers"):
        if metric in category:
            return metric
    return None


async def start_recurring_plan(draft, user_id: int):
    """Create a repeating order on the server from a confirmed draft.

    Returns (schedule, error_key): schedule is the server's record
    ({"id", "next_run_at", ...}), error_key is "plan_failed" or None.
    """
    try:
        result = await paxyo.create_recurring(
            user_id,
            int(draft["service"]["service"]),
            draft["link"],
            draft["quantity"],
            draft["interval_minutes"],
        )
    except Exception as exc:
        log.warning("create_recurring failed: %s", exc)
        return None, "plan_failed"
    schedule = result.get("schedule", result) if isinstance(result, dict) else {}
    return schedule, None


def pending_delayed_for_user(user_id: int):
    """(confirm_id, draft) of the user's most recent delayed order
    awaiting Confirm, or (None, None)."""
    for confirm_id, draft in reversed(list(PENDING_DELAYED.items())):
        if draft["user_id"] == user_id:
            return confirm_id, draft
    return None, None


def _delayed_record_fields(record):
    """A server or memory delayed-order row -> the common dict the
    scheduler and the list use. Server rows carry the same keys;
    memory rows already do. Coerces the numeric fields. `provider`
    is "gop" / "smm" (second provider, 15 Nov 2026); old rows
    without one read as GOP, and `combined_id` is derived from it
    so the due-time placement can find the exact service — a bare
    id alone could place the wrong provider's service after a
    restart. A stored long-form provider value reads by its prefix
    ("smm..." -> "smm", anything else -> "gop")."""
    raw_provider = str(record.get("provider") or "").strip().lower()
    provider = "smm" if raw_provider.startswith("smm") else "gop"
    try:
        service_id = (
            int(record["service_id"])
            if record.get("service_id") is not None else None
        )
    except (TypeError, ValueError):
        service_id = None
    combined_id = record.get("combined_id") or (
        f"{provider}:{service_id}"
        if service_id is not None else None
    )
    return {
        "id": record.get("id"),
        "telegram_id": record.get("telegram_id"),
        "service_id": service_id,
        "provider": provider,
        "combined_id": combined_id,
        "link": record.get("link"),
        "quantity": int(record["quantity"]) if record.get("quantity") is not None else None,
        "total": record.get("total"),
        "run_at": record.get("run_at"),
        "status": record.get("status") or "scheduled",
        "idempotency_key": record.get("idempotency_key"),
        "created_at": record.get("created_at"),
        "order_id": record.get("order_id"),
        "reason": record.get("reason"),
        "_memory": str(record.get("id", "")).startswith("mem-"),
    }


async def delayed_store_create(draft, user_id: int):
    """Save a confirmed delayed order: server first (POST
    /delayed-orders), memory when the endpoint is not live yet (404)
    or the API is unreachable. Returns (record, error_key): record
    is the common dict above, error_key is "delayed_save_failed" or
    None. The memory fallback keeps the order even when the server
    is down — but memory does not survive a restart, so the server
    is the durable home; the scheduler warns when it places a
    memory-only order."""
    try:
        result = await paxyo.create_delayed_order(
            user_id,
            int(draft["service"]["service"]),
            draft["link"],
            draft["quantity"],
            draft["total"],
            draft["run_at"],
            draft["idempotency_key"],
            # Second provider (15 Nov 2026): the due-time placement
            # must route to the same provider the user picked.
            provider=service_provider(draft["service"]),
        )
    except httpx.HTTPStatusError as exc:
        if exc.response.status_code == 404:
            result = None  # endpoint not live yet -> memory
        else:
            log.warning("create_delayed_order rejected: %s", exc.response.status_code)
            return None, "delayed_save_failed"
    except Exception as exc:
        log.warning("create_delayed_order failed: %s", exc)
        result = None  # API unreachable -> memory
    if result is None:
        record = _delayed_record_fields({
            "id": "mem-" + uuid.uuid4().hex[:8],
            "telegram_id": user_id,
            "service_id": draft["service"]["service"],
            "provider": service_provider(draft["service"]),
            "link": draft["link"],
            "quantity": draft["quantity"],
            "total": draft["total"],
            "run_at": draft["run_at"],
            "status": "scheduled",
            "idempotency_key": draft["idempotency_key"],
            "created_at": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S"),
        })
        DELAYED_MEMORY[record["id"]] = record
        # Stale Confirm (19 Nov 2026, Order ID 1881): a normal
        # order's Confirm card left unconfirmed, then a delayed
        # order scheduled, then a bare "Ok" placed the OLD order.
        # Saving the delayed order retires any pending normal
        # Confirm for this user, so a later bare acceptance has
        # nothing stale to place. The delayed order itself lives
        # in DELAYED_MEMORY / on the server, never in PENDING,
        # so this cannot touch it.
        drop_pending_confirms_for_user(user_id)
        return record, None
    record = result.get("delayed_order", result) if isinstance(result, dict) else {}
    if not record or record.get("id") is None:
        # The server answered but gave no id: keep the order in
        # memory so it is not lost, rather than reporting success
        # for an order nobody will place.
        record = _delayed_record_fields({
            "id": "mem-" + uuid.uuid4().hex[:8],
            "telegram_id": user_id,
            "service_id": draft["service"]["service"],
            "provider": service_provider(draft["service"]),
            "link": draft["link"],
            "quantity": draft["quantity"],
            "total": draft["total"],
            "run_at": draft["run_at"],
            "status": "scheduled",
            "idempotency_key": draft["idempotency_key"],
            "created_at": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S"),
        })
        DELAYED_MEMORY[record["id"]] = record
    # Stale Confirm (19 Nov 2026, Order ID 1881): see the memory
    # path above — a successfully saved delayed order retires any
    # pending normal Confirm for this user.
    drop_pending_confirms_for_user(user_id)
    return _delayed_record_fields(record), None


async def delayed_store_list(user_id: int):
    """The user's scheduled delayed orders: server rows plus
    memory rows, soonest first. A server failure returns only the
    memory rows, never an exception."""
    rows = []
    try:
        rows.extend(await paxyo.list_delayed_orders(user_id))
    except Exception as exc:
        log.warning("list_delayed_orders failed: %s", exc)
    rows.extend(
        r for r in DELAYED_MEMORY.values()
        if r.get("telegram_id") == user_id and r.get("status") == "scheduled"
    )
    out = [_delayed_record_fields(r) for r in rows]
    out.sort(key=lambda r: str(r.get("run_at") or ""))
    return out


async def delayed_store_cancel(record, user_id: int):
    """Cancel one scheduled delayed order (memory or server).
    Returns True when it was cancelled, False otherwise."""
    if record.get("_memory"):
        return DELAYED_MEMORY.pop(record["id"], None) is not None
    try:
        result = await paxyo.cancel_delayed_order(record["id"], user_id)
    except Exception as exc:
        log.warning("cancel_delayed_order failed: %s", exc)
        return False
    return result is not None


async def delayed_store_due():
    """All scheduled delayed orders whose run_at is now or past:
    server rows plus memory rows. A server failure returns only the
    memory rows, never an exception."""
    rows = []
    try:
        rows.extend(await paxyo.due_delayed_orders())
    except Exception as exc:
        log.warning("due_delayed_orders failed: %s", exc)
    now = datetime.now(timezone.utc)
    for record in DELAYED_MEMORY.values():
        # A row stuck 'placing' for over 30 minutes is treated as due
        # again (the claimer crashed between claim and place) — the
        # claim below still guards against a double placement.
        if record.get("status") == "placing":
            try:
                claimed_at = datetime.strptime(
                    str(record.get("claimed_at")), "%Y-%m-%d %H:%M:%S"
                ).replace(tzinfo=timezone.utc)
            except (TypeError, ValueError):
                claimed_at = None
            if claimed_at is None or now - claimed_at > timedelta(minutes=30):
                rows.append(record)
            continue
        if record.get("status") != "scheduled":
            continue
        try:
            run_at = datetime.strptime(
                str(record.get("run_at")), "%Y-%m-%d %H:%M:%S"
            ).replace(tzinfo=timezone.utc)
        except (TypeError, ValueError):
            continue
        if run_at <= now:
            rows.append(record)
    out = [_delayed_record_fields(r) for r in rows]
    out.sort(key=lambda r: str(r.get("run_at") or ""))
    return out


async def delayed_store_claim(record):
    """Claim a due delayed order for placement. The claim happens
    BEFORE the order is placed, so a crash between claim and place
    cannot double-place it: the server claim is an atomic UPDATE
    (only a row still 'scheduled' is claimed); a memory row is
    marked 'placing' in place. Returns True when this caller owns
    the placement, False when someone else already claimed it."""
    if record.get("_memory"):
        stored = DELAYED_MEMORY.get(record["id"])
        if stored is None or stored.get("status") not in ("scheduled", "placing"):
            return False
        if stored.get("status") == "placing":
            # Re-claim of a stale claim only: a fresh claim is still
            # owned by whoever made it.
            try:
                claimed_at = datetime.strptime(
                    str(stored.get("claimed_at")), "%Y-%m-%d %H:%M:%S"
                ).replace(tzinfo=timezone.utc)
            except (TypeError, ValueError):
                claimed_at = None
            if claimed_at is not None and datetime.now(timezone.utc) - claimed_at <= timedelta(minutes=30):
                return False
        stored["status"] = "placing"
        stored["claimed_at"] = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
        return True
    try:
        return bool(await paxyo.claim_delayed_order(
            record["id"], record.get("telegram_id")
        ))
    except Exception as exc:
        log.warning("claim_delayed_order failed: %s", exc)
        return False


async def delayed_store_finish(record, status, order_id=None, reason=None):
    """Mark a claimed delayed order placed or failed (server or
    memory). Best-effort: a failure here never raises, so the
    scheduler never crashes on bookkeeping."""
    if record.get("_memory"):
        stored = DELAYED_MEMORY.get(record["id"])
        if stored is not None:
            stored["status"] = status
            if order_id is not None:
                stored["order_id"] = order_id
            if reason is not None:
                stored["reason"] = reason
        return
    try:
        await paxyo.finish_delayed_order(
            record["id"], record.get("telegram_id"), status,
            order_id=order_id, reason=reason,
        )
    except Exception as exc:
        log.warning("finish_delayed_order failed: %s", exc)


def _refill_record_fields(record):
    """A server or memory refill row -> the bot-side record shape
    (the dict auto_refill_check() takes). Server rows already
    carry that shape; memory rows are the register_auto_refill
    dict. `_server` marks a row the server holds, so the stop
    handler knows whether to tell the server too. Server rows
    carry the trigger flat (trigger_qty / trigger_pct); it is
    rebuilt into the {"type", "value"} dict here."""
    trigger = record.get("trigger")
    if trigger is None and record.get("trigger_qty") is not None:
        trigger = {"type": "qty", "value": record.get("trigger_qty")}
    elif trigger is None and record.get("trigger_pct") is not None:
        trigger = {"type": "pct", "value": record.get("trigger_pct")}
    out = {
        "id": record.get("id"),
        "telegram_id": record.get("telegram_id"),
        "service": record.get("service") or {},
        "link": record.get("link") or "",
        "target": record.get("target"),
        "metric": record.get("metric"),
        "platform": record.get("platform"),
        "daily_cap": record.get("daily_cap"),
        "trigger": trigger,
        "spent_today": record.get("spent_today") or 0,
        "spent_date": record.get("spent_date"),
        "last_count": record.get("last_count"),
        "last_check": record.get("last_check"),
        "count_usage": dict(record.get("count_usage") or {}),
        "created_at": record.get("created_at"),
        "_server": bool(record.get("_server")),
    }
    return out


async def refill_store_create(setup, user_id: int):
    """Save a confirmed auto-refill: memory first (the record the
    chat already uses), then the server (POST /refills) so the
    hourly worker can see it. Any server failure — 404 (endpoint
    not live yet), unreachable API, a rejected body — keeps the
    memory record and logs: a refill that lives only in memory
    still works for the chat, and the status list says so
    honestly, instead of losing the user's setup over a
    transient server error. Returns the stored record."""
    refill = register_auto_refill(setup, user_id)
    service = setup.get("service") or {}
    try:
        result = await paxyo.create_refill(
            user_id,
            int(service["service"]),
            service_provider(service),
            setup.get("link") or "",
            (setup.get("platform") or "").strip().lower(),
            (setup.get("metric") or "").strip().lower(),
            int(setup.get("target")),
            service,
            str(refill["id"]),
            daily_cap=setup.get("daily_cap"),
            trigger=setup.get("trigger"),
        )
    except Exception as exc:
        log.warning("create_refill failed, keeping memory record: %s", exc)
        return refill
    if not result:
        # 404: endpoint not live yet — memory record stands.
        return refill
    saved = result.get("refill", result) if isinstance(result, dict) else {}
    if not saved or saved.get("id") is None:
        log.warning("create_refill answered without an id, keeping memory record")
        return refill
    # The server id replaces the memory id everywhere: the worker
    # and the stop handler both key on it from here on.
    refill["id"] = saved.get("id")
    refill["_server"] = True
    return refill


async def refill_store_list(user_id: int):
    """The user's confirmed auto-refills: server rows plus memory
    rows, server first. A server failure returns only the memory
    rows, never an exception — so a restart never hides a refill
    the chat already knows about, and a refill the server holds
    stays visible (and stoppable) after a bot restart."""
    rows = []
    try:
        rows.extend(await paxyo.list_refills(user_id))
    except Exception as exc:
        log.warning("list_refills failed: %s", exc)
    seen = set()
    out = []
    for raw in rows:
        record = _refill_record_fields(raw)
        record["_server"] = True
        seen.add(str(record.get("id")))
        out.append(record)
    for record in list_auto_refills(user_id):
        if str(record.get("id")) in seen:
            continue
        out.append(_refill_record_fields(record))
    return out


async def refill_store_stop(record, user_id: int):
    """Stop one auto-refill (memory + server when the server
    holds it). Returns True when it was stopped. A server stop
    that fails leaves the memory record in place so the user
    can try again — telling the user it stopped while the
    worker still tops it up would be worse than the error. A
    409 (already stopped on the server) counts as stopped: the
    row will not be checked again."""
    server_ok = True
    if record.get("_server"):
        try:
            await paxyo.stop_refill(record["id"], user_id)
        except httpx.HTTPStatusError as exc:
            if exc.response.status_code == 409:
                server_ok = True
            else:
                log.warning("stop_refill failed: %s", exc)
                server_ok = False
        except Exception as exc:
            log.warning("stop_refill failed: %s", exc)
            server_ok = False
    if not server_ok:
        return False
    stopped = False
    active = AUTO_REFILL_ACTIVE.get(user_id) or []
    if any(r is record for r in active):
        AUTO_REFILL_ACTIVE[user_id] = [r for r in active if r is not record]
        stopped = True
    elif any(str(r.get("id")) == str(record.get("id")) for r in active):
        AUTO_REFILL_ACTIVE[user_id] = [
            r for r in active if str(r.get("id")) != str(record.get("id"))
        ]
        stopped = True
    return stopped or bool(record.get("_server"))


async def refills_live():
    """True when GET /refills/status answers (server
    api-auto-refill.php installed). Fail-open False: a missing
    method (old fake client) or any error means not live, never
    an exception into the chat."""
    if paxyo is None:
        return False
    try:
        return bool(await paxyo.refills_live())
    except Exception as exc:
        log.warning("refills_live failed: %s", exc)
        return False


def pending_deposit_for_user(user_id: int):
    """(confirm_id, draft) of the user's most recent deposit awaiting
    Confirm, or (None, None)."""
    for confirm_id, draft in reversed(list(PENDING_DEPOSIT.items())):
        if draft["user_id"] == user_id:
            return confirm_id, draft
    return None, None


async def start_deposit(draft, user_id: int):
    """Call POST /deposits for a confirmed draft (amount only,
    owner, 17 Nov 2026 — the method + phone are chosen on the
    popup page, never in chat).

    Returns (result, error): result is the server's record
    ({"deposit_id","popup_token","status":"pending"} — the popup
    token is the one-time key the popup page exchanges for the
    checkout; no checkout URL ever reaches the chat),
    error is None on success, "deposit_not_ready" when the endpoint
    is not live yet (404), "deposit_unavailable" when the payment
    service itself failed (5xx, e.g. Chapa refusing Direct Charge),
    a server message string when the API rejected it (e.g. amount
    below the minimum), "banned" when the user is banned, or
    "deposit_failed".
    """
    # Ban (19 Nov 2026): a banned user deposits nothing — checked
    # first, before any money moves. The callers answer "banned"
    # with the short "banned" reply.
    if await user_is_banned(user_id):
        return None, "banned"
    try:
        # A validated promo code rides on the create call only
        # (ideas batch 2, feature 1, 15 Nov 2026): the server stores
        # it in chapa_response and its hook credits the bonus when
        # the deposit completes. Only a code validate_promo already
        # approved is ever sent — and only on a successful create
        # does the code move to PROMO_DEPOSIT (a failed create keeps
        # it remembered, so the "Try again" retry still carries it).
        validated = VALIDATED_PROMO.get(user_id) or {}
        promo_code = validated.get("code")
        result = await paxyo.create_deposit(
            user_id, draft["amount"],
            promo_code=promo_code,
        )
    except httpx.HTTPStatusError as exc:
        log.warning("create_deposit rejected: %s", exc.response.status_code)
        if exc.response.status_code >= 500:
            # The payment service itself failed (Chapa refusing
            # Direct Charge answers 502): the deposit never started,
            # so the caller offers the embedded deposit page instead
            # of showing the provider's raw refusal in the chat.
            return None, "deposit_unavailable"
        try:
            data = exc.response.json()
        except Exception:
            data = {}
        message = None
        if isinstance(data, dict):
            message = data.get("error") or data.get("message")
        return None, message or "deposit_failed"
    except Exception as exc:
        log.warning("create_deposit failed: %s", exc)
        return None, "deposit_failed"
    if result is None:  # 404: the endpoint is not live yet
        return None, "deposit_not_ready"
    # Start the payment right away (owner, 17 Nov 2026): the bot
    # exchanges the one-time popup token for the Chapa checkout
    # itself — no method, no phone. Chapa collects the method +
    # phone on its own checkout page, so there is no popup form
    # any more: the button below opens the checkout directly.
    # The checkout URL is the button target only — it never
    # appears as message text.
    deposit_id = result.get("deposit_id") if isinstance(result, dict) else None
    token = result.get("popup_token") if isinstance(result, dict) else None
    if deposit_id is not None and token:
        try:
            pay = await paxyo.start_deposit_payment(deposit_id, token)
        except httpx.HTTPStatusError as exc:
            log.warning("start_deposit_payment rejected: %s", exc.response.status_code)
            if exc.response.status_code >= 500:
                return None, "deposit_unavailable"
            try:
                data = exc.response.json()
            except Exception:
                data = {}
            message = None
            if isinstance(data, dict):
                message = data.get("error") or data.get("message")
            return None, message or "deposit_failed"
        except Exception as exc:
            log.warning("start_deposit_payment failed: %s", exc)
            return None, "deposit_failed"
        if pay is None:  # 404: the endpoint is not live yet
            return None, "deposit_unavailable"
        if isinstance(pay, dict) and pay.get("checkout_url"):
            result = dict(result)
            result["checkout_url"] = pay["checkout_url"]
    # Remember the deposit id so "did my deposit go through?"
    # can recheck this deposit without listing first — and watch
    # it for automatic credit, so the user is told the moment it
    # lands without tapping anything.
    if deposit_id is not None:
        LAST_DEPOSIT[user_id] = deposit_id
        import time

        DEPOSIT_CREDIT_WATCH[user_id] = {
            "deposit_id": deposit_id,
            "started_at": time.time(),
        }
    if promo_code:
        # The code is spent on THIS deposit: it moves to
        # PROMO_DEPOSIT (so the completion recheck can report the
        # bonus) and is forgotten as a standing code — a second
        # deposit needs the code typed again.
        PROMO_DEPOSIT[user_id] = {
            "code": promo_code,
            "percent": validated.get("percent"),
            "deposit_id": deposit_id,
        }
        VALIDATED_PROMO.pop(user_id, None)
    return result, None


def deposit_instructions_text(result, amount, method, lang: str) -> str:
    """Short payment instructions from the server's deposit record.

    USSD push first (Chapa Direct Charge): the prompt arrives on the
    user's phone, so there is no code to dial and no link to open.
    Then the USSD code to dial and/or the checkout link, when the
    server returns them. Never claims the money is credited — the
    server credits the balance only after Chapa confirms the payment."""
    if result.get("pushed") or result.get("auth_type") == "ussd":
        return t(
            "deposit_pushed", lang,
            amount=format_money(amount),
            method=METHOD_LABELS.get(method, method),
        )
    steps = []
    ussd = result.get("ussd_code")
    pay_to = result.get("pay_to")
    url = result.get("checkout_url")
    if ussd:
        steps.append(t("deposit_step_ussd", lang, code=ussd))
    if pay_to:
        steps.append(t("deposit_step_pay_to", lang, pay_to=pay_to))
    if url:
        steps.append(t("deposit_step_link", lang, url=url))
    if not steps:
        steps.append(t("deposit_step_website", lang))
    return t(
        "deposit_instructions", lang,
        amount=format_money(amount),
        method=METHOD_LABELS.get(method, method),
        steps="\n".join(steps),
    )


def make_deposit_qr_png(url: str):
    """QR code PNG bytes for a checkout URL, or None. Pure-Python
    segno (no Pillow, no system deps). Never raises: a bad URL, a
    missing library, or an over-long URL just means no QR photo.
    The URL is only ever one the server returned — never invented."""
    url = (url or "").strip()
    if not url.startswith(("http://", "https://")):
        return None
    try:
        import segno
        qr = segno.make(url, error="m")
        buf = io.BytesIO()
        qr.save(buf, kind="png", scale=8, border=2)
        return buf.getvalue()
    except Exception as exc:
        log.warning("deposit QR failed: %s", exc)
        return None


async def maybe_send_deposit_qr(message, result, lang: str):
    """Deposit by QR (ideas batch 1 #9, 16 Nov 2026): after the
    deposit is created, when the server actually returned a
    checkout URL for it, send a QR code photo of that URL so the
    user scans it with their phone camera and pays — alongside
    the existing instructions and Web App button. No checkout URL
    means no photo, silently: the instructions already carry the
    link (or the USSD push / website fallback) and nothing is
    invented. Never raises — a failed photo must not fail the
    deposit message that already went out."""
    try:
        url = (result or {}).get("checkout_url")
        png = make_deposit_qr_png(url) if url else None
        if png is None:
            return
        await message.reply_photo(
            photo=InputFile(io.BytesIO(png), filename="deposit-qr.png"),
            caption=t("deposit_qr_caption", lang),
        )
    except Exception as exc:
        log.warning("deposit QR send failed: %s", exc)


def deposit_webapp_keyboard(lang: str, amount=None, allow_retry: bool = False,
                            user_id: int = None) -> InlineKeyboardMarkup:
    """Embedded deposit (owner, 15 Nov 2026): open the Paxyo deposit
    page INSIDE Telegram as a Web App, so the chat never closes while
    the user pays. One row only (owner, 17 Nov 2026): no plain-link
    row and no "I paid" row — the balance credits automatically
    (Chapa callback + the credit watcher) and the user is told when
    it lands. With an amount the button names it ("Deposit 100.00
    ETB"); without one it is generic (the insufficient-balance
    nudge, where the user may want to deposit more than the
    shortfall). Ideas batch (15 Nov 2026): when a deposit just
    failed and `allow_retry` is set, a second row offers "🔁 Try
    again" — it restarts the same deposit (amount kept) instead of
    making the user retype it."""
    if amount is not None:
        label = t("deposit_webapp_button", lang, amount=format_money(amount))
    else:
        label = t("deposit_webapp_button_plain", lang)
    rows = [
        [InlineKeyboardButton(label, web_app=WebAppInfo(url=DEPOSIT_WEBAPP_URL))],
    ]
    if allow_retry and user_id is not None and user_id in FAILED_DEPOSIT:
        rows.append([
            InlineKeyboardButton(
                t("deposit_retry_button", lang), callback_data="retrydep"
            )
        ])
    return InlineKeyboardMarkup(rows)


def deposit_checkout_keyboard(result, draft, lang: str):
    """Inline keyboard for a started deposit (owner, 17 Nov 2026):
    ONE row — a plain URL button that opens the Chapa checkout
    directly. Chapa collects the payment method + phone on its
    own page, so there is no popup form any more: no Web App
    button, no method/phone step anywhere in the bot. The
    checkout URL is the button target only — it never appears as
    message text — and there is no "I paid" row: the balance
    credits automatically (Chapa callback + credit watcher).
    None when the server returned no checkout URL."""
    url = (result or {}).get("checkout_url") or ""
    if not isinstance(url, str) or not url.startswith("https://"):
        return None
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(
            t("deposit_popup_button", lang,
              amount=format_money(draft["amount"])),
            url=url,
        )],
    ])


def deposit_success_markup(result, draft, lang: str):
    """Keyboard for a started deposit (owner, 17 Nov 2026): the
    checkout button when the server returned a checkout URL,
    else None — no "I paid" recheck button any more. (A None
    markup still replaces the Confirm/Cancel buttons on the
    edited card, so a user cannot tap Confirm twice; the credit
    watcher tells them when the deposit lands.)"""
    return deposit_checkout_keyboard(result, draft, lang)


def deposit_webapp_message(amount, lang: str, allow_retry: bool = False,
                           user_id: int = None):
    """(text, keyboard) for the embedded-deposit fallback, shown when
    the USSD push could not be sent: the user deposits on the Paxyo
    page inside Telegram instead of leaving for the website. The
    keyboard may gain the "Try again" row (ideas batch, 15 Nov 2026)."""
    return (
        t("deposit_webapp", lang),
        deposit_webapp_keyboard(
            lang, amount=amount, allow_retry=allow_retry, user_id=user_id,
        ),
    )


# Bare "I paid" / "I approved it" (text is already normalised).
# Only the exact phrases count: a longer message goes through the
# classifier instead, so "I paid for the order" is not hijacked.
PAID_WORDS = frozenset({
    "i paid", "i have paid", "i've paid", "i paid already",
    "i approved it", "i have approved it", "i approved",
    "paid", "approved",
    "ከፍዬአለሁ", "ከፈልኩ", "ከፍያለሁ",
})


# Questions about where the services come from / what Paxyo pays for
# them (owner rule, 13 Nov 2026: the supply chain stays secret).
# Caught locally, before Gemini is even called, so the model is never
# given a chance to name a supplier. Amharic "አቅራቢ" is the word for
# a supplier; other Amharic phrasings go through the classifier's
# "source_question" intent instead.
SOURCE_QUESTION_PATTERNS = (
    "provider", "supplier", "supplies", "resell", "smm", "wholesale",
    "middleman", "where do you get", "where do you buy",
    "who gives you", "who supplies", "who is behind",
    "how much do you buy", "how much did you buy",
    "are you a panel", "is this a panel", "is paxyo a panel",
    "አቅራቢ",
)


def is_source_question(text: str) -> bool:
    """True when the message asks where Paxyo's services come from,
    who supplies them, or what Paxyo pays for them."""
    s = normalize_text(text or "")
    return any(p in s for p in SOURCE_QUESTION_PATTERNS)


def is_loyalty_question(text: str) -> bool:
    """True when the message asks about a loyalty bonus (feature 9,
    15 Nov 2026): "loyalty" anywhere, or "bonus" together with
    ordering ("bonus for ordering a lot"). A "bonus code" is a
    promo-code question, not a loyalty question, and a
    first-deposit bonus has no ordering word — both stay out."""
    s = normalize_text(text or "")
    if "loyalty" in s:
        return True
    if "code" in s:
        return False
    return "bonus" in s and ("order" in s or "ordering" in s)


async def loyalty_answer_text(user_id: int, lang: str, app=None) -> str:
    """Answer a loyalty-bonus question (feature 9, 15 Nov 2026):
    404 (the endpoint is not live yet) or any failure answers
    honestly that the bonus isn't switched on yet; a live endpoint
    explains the rule (10% of every 10 completed orders' total,
    credited to the Paxyo balance). The check itself may award a
    milestone that is already due — the server credits it, and
    the reply then says so with the EXACT bonus figure from the
    reply, so an award triggered by the question is never silent;
    William also gets the admin report for that credit (same as
    the delivery hook). The bot never credits anything itself."""
    result = None
    try:
        if paxyo is not None:
            result = await paxyo.check_loyalty(user_id)
    except Exception as exc:
        log.warning("loyalty check failed: %s", exc)
        result = None
    if result is None:
        return t("loyalty_not_live", lang)
    if isinstance(result, dict) and result.get("awarded"):
        try:
            bonus = float(result.get("bonus_etb") or 0)
            milestone = int(result.get("milestone") or 0)
        except (TypeError, ValueError):
            bonus, milestone = 0, 0
        if bonus > 0 and milestone > 0:
            await _notify_loyalty_award(
                app, user_id, result.get("username"), bonus, milestone
            )
            return t(
                "loyalty_explained_awarded", lang,
                bonus=format_money(bonus),
                order_number=milestone * 10,
                percent=LOYALTY_BONUS_PERCENT,
            )
    return t("loyalty_explained", lang, percent=LOYALTY_BONUS_PERCENT)


# The user wants to sell Paxyo's services themselves (next batch,
# 14 Nov 2026). This is NOT the source question: "are you a
# reseller?" asks about Paxyo and still deflects. The difference
# is the user wanting to sell — first-person want / can-I /
# become / how-do-I. A plain "do you sell followers?" (asking
# whether Paxyo sells) matches none of these.
_RESELLER_REQUEST_PATTERNS = (
    "want to resell", "wanna resell", "can i resell",
    "could i resell", "how do i resell", "how can i resell",
    "how to resell", "become a reseller", "be a reseller",
    "become reseller", "interested in reselling",
    "start reselling", "resell your", "resell paxyo",
    "want to sell", "wanna sell", "can i sell", "could i sell",
    "how do i sell your", "how can i sell your",
    "how to sell your", "sell your services", "sell paxyo",
)


def is_reseller_request(text: str) -> bool:
    """True when the user wants to sell Paxyo's services
    themselves — not when they ask whether Paxyo resells."""
    s = " ".join((normalize_text(text or "")).strip().lower().split())
    return any(p in s for p in _RESELLER_REQUEST_PATTERNS)


# The user wants a human — support (next batch, 14 Nov 2026).
# "Who owns / who is the owner" is in here too: the contact reply
# is generic customer support now (owner rule, 15 Nov 2026 — a
# support reply never names a person), and the owner question gets
# that same support line plus how to reach them. A reported
# problem ("my payment failed, fix my account") matches none of
# these — that stays the support_issue redirect.
_CONTACT_REQUEST_PATTERNS = (
    "talk to a human", "talk to someone", "talk with a human",
    "speak to a human", "speak with a human", "speak to someone",
    "talk to a real person", "speak to a real person",
    "i need support", "need support", "i want support",
    "need help from support", "contact you", "contact william",
    "contact the owner", "contact admin", "contact support",
    "how do i contact", "how can i contact", "how to contact",
    "talk to william", "speak to william", "talk to the owner",
    "speak to the owner", "get in touch", "customer support",
    "who is the owner", "who owns paxyo", "who runs paxyo",
    "who is william", "who is yohannes", "who is the boss",
    # "ባለቤት" is "owner" in Amharic and Tigrinya (owner rule,
    # 15 Nov 2026): an owner question in Ge'ez script must reach
    # the same generic support line as the English one — without
    # it, "Paxyo ባለቤት ማን ነው?" fell through to the local facts
    # and got the name.
    "ባለቤት",
)


def is_contact_request(text: str) -> bool:
    """True when the user asks to reach a human — support, the
    owner or the admin — rather than reporting a problem."""
    s = " ".join((normalize_text(text or "")).strip().lower().split())
    return any(p in s for p in _CONTACT_REQUEST_PATTERNS)


# Premium subscriptions (CapCut Pro, Canva Pro, ...) and the SMS OTP
# verification service are PAUSED (owner, 14 Nov 2026). The guard
# matches the brand names and the OTP-service phrasing — but never a
# message that names a social-media metric: "premium followers",
# "Spotify followers" and "Telegram Premium members" are real orders
# (the catalogue has 293 "premium" services and Spotify
# followers/likes), and "Telegram Premium" on its own is a Bot Start
# service. CapCut/Canva/Netflix/OTP have no services in the
# catalogue, so the bare brand names are safe. The metric check is
# word-based on plurals only: "I would like CapCut Pro" must still
# match (the verb "like" is not the metric "likes").
_PAUSED_SERVICES_PATTERNS = (
    "capcut", "canva", "netflix",
    "spotify premium", "youtube premium",
    "premium subscription", "premium subscriptions",
    "cheap premium", "buy premium", "get premium", "want premium",
    "need premium", "sell premium", "do you sell premium",
    "do you have premium",
    "sms otp", "otp verification", "otp number", "otp code",
    "otp service", "sms verification",
    "buy otp", "need otp", "want otp", "get otp", "otp for",
    "otp to verify",
)
_PAUSED_METRIC_WORDS = (
    "followers", "likes", "views", "comments", "subscribers",
    "reactions", "members", "shares", "saves",
)


def is_paused_services_request(text: str) -> bool:
    """True when the user asks for a paused service — a premium
    subscription or SMS OTP verification. False for anything that
    names a social-media metric (that is an order) or Telegram
    Premium (a real Bot Start service)."""
    s = " ".join((normalize_text(text or "")).strip().lower().split())
    if "telegram premium" in s:
        return False
    words = set(re.findall(r"[a-z]+", s))
    if words & set(_PAUSED_METRIC_WORDS):
        return False
    return any(p in s for p in _PAUSED_SERVICES_PATTERNS)


# Which services never drop (owner, 14 Nov 2026): ONLY Telegram
# reactions, Telegram views and Facebook reactions. Every other
# service keeps the terms language — results not guaranteed
# permanent, drops may occur — and the bot must never claim
# never-drop for those. The claim is only ever given when the
# user ASKS about drops for one of the three; it is never
# volunteered unprompted.
_NEVER_DROP_KINDS = (
    ("telegram", "reactions", "Telegram reactions"),
    ("telegram", "views", "Telegram views"),
    ("facebook", "reactions", "Facebook reactions"),
)
_DROP_WORDS = (
    "drop", "disappear", "fade", "fall off", "go away", "vanish",
    "decrease", "go down",
)


def never_drop_kind(text: str, platform=None, service_hint=None):
    """The never-drop service kind the message asks about, or None.

    The message must ask about drops AND pin the service to one of
    the three covered kinds (platform + metric). A drop question
    about anything else — TikTok followers, Instagram likes,
    Telegram followers, a bare "do they drop?" with no platform —
    returns None, so the terms/refund answer stands.
    """
    s = " ".join((normalize_text(text or "")).strip().lower().split())
    if not any(p in s for p in _DROP_WORDS):
        return None
    plat = (platform or "").strip().lower() or None
    if plat is None:
        if "private channel" in s:
            plat = "max"
        else:
            for w, p in _PLATFORM_WORDS.items():
                if re.search(rf"\b{re.escape(w)}\b", s):
                    plat = p
                    break
    hint = (service_hint or "").strip().lower()
    metric = kind_from_text(hint) if hint else None
    if metric is None:
        metric = kind_from_text(s)
    # Telegram views ARE post views (service-types inventory §3):
    # a "post views" question is a Telegram views question.
    if metric == "post views":
        metric = "views"
    if metric is None or plat is None:
        return None
    for p, m, label in _NEVER_DROP_KINDS:
        if p == plat and m == metric:
            return label
    return None


def _service_never_drop_kind(service):
    """The never-drop kind of a service dict, or None.

    Same three kinds as never_drop_kind, read from the service's
    own category/name: "Telegram Reactions", "Telegram Post Views",
    "Facebook Reactions". A Bot Start service has no
    reactions/views metric in its name, so it never matches.
    """
    if not service:
        return None
    text = (
        str(service.get("category") or "")
        + " " + str(service.get("name") or "")
    ).lower()
    plat = None
    for p in ("telegram", "facebook"):
        if re.search(rf"\b{re.escape(p)}\b", text):
            plat = p
            break
    if plat is None:
        return None
    metric = kind_from_text(text)
    # Telegram views ARE post views (service-types inventory §3).
    if metric == "post views":
        metric = "views"
    if metric is None:
        return None
    for p, m, label in _NEVER_DROP_KINDS:
        if p == plat and m == metric:
            return label
    return None


def is_paid_phrase(text: str) -> bool:
    """True when the message is just 'I paid' / 'I approved it' —
    the user saying the payment is done and asking whether it went
    through."""
    s = " ".join((text or "").strip().lower().split())
    s = s.strip(" .!,?።፣")
    return s in PAID_WORDS


# ------------------------------------------------------- promo codes --
# Ideas batch 2, feature 1 (15 Nov 2026): a user types a promo code
# in chat ("PAXYO20", "my code is WELCOME10"). The code is validated
# against the server FIRST (POST /promo-codes/validate) and only a
# validated code is remembered — and only for the user's NEXT
# deposit, attached to its create call so the server hook credits
# the bonus when the deposit completes. A code never discounts an
# order price and never creates money from nothing: the bonus is a
# deposit credit only, on a real completed deposit, once per user,
# once per deposit. Detection is deliberately narrow so order text
# is never hijacked: a bare token, or an explicit "my code is X",
# that is letters+digits, 4–20 chars, with no draft open and no
# other intent matching. A bare number ("1000") is a quantity, not
# a code; a bare word ("hello") is chat, not a code; a code-shaped
# token inside an order message stays an order.
_PROMO_TOKEN_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]{3,19}$")
_PROMO_EXPLICIT_RE = re.compile(
    r"\b(?:promo\s+code|my\s+code|code)\s*(?:is|:)?\s*"
    r"([A-Za-z0-9][A-Za-z0-9_-]{3,19})\b",
    re.IGNORECASE,
)
# Words that mean the message is about something else, so a
# code-shaped token riding in it is never treated as a promo offer.
_PROMO_OFFER_BLOCK_WORDS = frozenset((
    "order", "deposit", "balance", "buy", "pay", "top", "recharge",
    "price", "cancel", "help",
))
_PROMO_DECLINE_WORDS = frozenset((
    "no", "nope", "nah", "no thanks", "not really", "no thank you",
    "አይ", "አይደለም",
))


def _is_promo_shaped(token: str) -> bool:
    """True when a token looks like a promo code: letters+digits,
    4–20 chars, no spaces. A token of digits only is a quantity or
    a service ID; a token of letters only is a word — neither is a
    code, so both are rejected here."""
    token = (token or "").strip(".,!?")
    if not _PROMO_TOKEN_RE.match(token):
        return False
    return any(ch.isalpha() for ch in token) and any(
        ch.isdigit() for ch in token
    )


def extract_promo_code(text: str):
    """The promo code a message carries, or None.

    A bare code-shaped token ("PAXYO20"), or an explicit phrasing
    ("my code is WELCOME10", "promo code PAXYO20", "code: ABC123").
    Anything else — order text, a question, a bare number or word —
    returns None. The code is uppercased: the server normalises
    the same way, and normalize_text already lowercased the message
    by the time this runs."""
    s = (text or "").strip()
    if not s:
        return None
    match = _PROMO_EXPLICIT_RE.search(s)
    if match and _is_promo_shaped(match.group(1)):
        return match.group(1).upper()
    if " " not in s and "\n" not in s and _is_promo_shaped(s):
        return s.upper()
    return None


def extract_promo_offer(text: str):
    """A code-shaped token inside a short message that says nothing
    else ("PAXYO20 please", "use WELCOME10") — ambiguous, so the
    bot asks "Is this a promo code?" instead of validating it
    outright. Returns the uppercased code, or None. Never fires on
    a message with a link, a platform or metric word, or an order /
    deposit / balance word: those are orders, not codes."""
    s = (text or "").strip()
    words = s.split()
    if not 2 <= len(words) <= 3:
        return None
    if extract_links(s):
        return None
    if kind_from_text(s) is not None:
        return None
    if _explicit_platform_word(s) is not None:
        return None
    lowered = {w.strip(".,!?").lower() for w in words}
    if lowered & _PROMO_OFFER_BLOCK_WORDS:
        return None
    for token in words:
        if _is_promo_shaped(token):
            return token.upper()
    return None


def _promo_busy(user_id: int) -> bool:
    """True when the user has an order, deposit, plan or choice
    open — a promo code typed now must not hijack it. The code is
    only read when nothing is being built and no Confirm card is
    pending."""
    if (
        PARTIAL.get(user_id)
        or DEPOSIT_DRAFT.get(user_id)
        or DELAYED_DRAFT.get(user_id)
        or RECURRING_DRAFT.get(user_id)
        or SPLIT_DRAFT.get(user_id)
        or BUDGET_OPTIONS.get(user_id)
    ):
        return True
    for store in (
        PENDING, PENDING_DEPOSIT, PENDING_DELAYED,
        PENDING_RECURRING, PENDING_BATCH,
    ):
        if any(
            (draft or {}).get("user_id") == user_id
            for draft in store.values()
        ):
            return True
    return False

# Intents that are side questions, not order input (mid-order
# understanding, 16 Nov 2026): a message with one of these intents
# typed while an order is open is answered by its normal branch,
# and the open order is parked first (see the guard before the
# conversational-intent branches). Deliberately NOT here: order
# input (order, delayed_order, recurring, batch, change_order,
# refill, split_payment, budget, usual, goal, max_for_balance,
# discount, free_sample, price_pushback, safety, refund_policy,
# geo_target, content_help), cancel (it drops the draft),
# deposit (its flow parks already), and free chat (off_topic /
# unclear — it keeps the draft by design, and "unclear" feeds the
# order-flow tail). paxyo_info / how_to stay out too: their
# answers can be about the order being built, so the draft stays.
_SIDE_QUESTION_INTENTS = frozenset((
    "settings", "balance", "orders", "deposit_status", "help",
    "how_to_order", "miniapp", "social", "invite", "greeting",
    "source_question", "reseller", "contact", "paused_services",
    "support_issue",
))


def is_promo_decline(text: str) -> bool:
    """True when the message declines the open promo-code question
    ("no", "not really", …). Only read while an offer is open."""
    s = " ".join((text or "").strip().lower().split())
    s = s.strip(" .!,?።፣")
    return s in _PROMO_DECLINE_WORDS


# The server's plain validate messages, mapped to the bot's own
# templates (so the reply comes back in the user's language). An
# unknown message is shown verbatim in English, or as the generic
# invalid line in any other language — the bot never invents a
# reason a code failed.
_PROMO_SERVER_MESSAGES = {
    "That promo code does not exist.": "promo_invalid",
    "This promo code is no longer active.": "promo_inactive",
    "This promo code has expired.": "promo_expired",
    "This promo code has been used up.": "promo_used_up",
    "You have already used this code.": "promo_already_used",
}


def _promo_failure_text(result, lang: str) -> str:
    """The honest reply for a validate that came back ok:false:
    the server's own message, in the user's language when it is
    one of the known ones. Never an invented reason."""
    message = None
    if isinstance(result, dict):
        message = result.get("message")
    if isinstance(message, str) and message.strip():
        key = _PROMO_SERVER_MESSAGES.get(message.strip())
        if key is not None:
            return t(key, lang)
        if lang == "en":
            return message.strip()
    return t("promo_invalid", lang)


async def handle_promo_code(update, code: str, lang: str, voice=False):
    """Validate one code and answer in one short line. On success
    the code is remembered for the user's next deposit only
    (VALIDATED_PROMO); on already-used the plain already-used line;
    on invalid/expired the server's own reason; on a missing
    endpoint (404 -> None) the honest not-switched-on line — never
    a pretence the code worked. A validate call never credits
    anything and never reserves a use."""
    user = update.effective_user
    if paxyo is None:
        await reply_message(
            update.message, t("promo_not_live", lang), lang, voice=voice,
        )
        return
    try:
        result = await paxyo.validate_promo(user.id, code)
    except Exception as exc:
        log.warning("validate_promo failed: %s", exc)
        await reply_message(
            update.message, t("not_understood", lang), lang, voice=voice,
        )
        return
    if result is None:  # 404: the endpoint is not live yet
        await reply_message(
            update.message, t("promo_not_live", lang), lang, voice=voice,
        )
        return
    if not isinstance(result, dict) or not result.get("ok"):
        if isinstance(result, dict) and result.get("already_used"):
            await reply_message(
                update.message, t("promo_already_used", lang),
                lang, voice=voice,
            )
            return
        await reply_message(
            update.message, _promo_failure_text(result, lang),
            lang, voice=voice,
        )
        return
    percent = result.get("percent")
    try:
        percent = int(percent) if percent is not None else None
    except (TypeError, ValueError):
        percent = None
    VALIDATED_PROMO[user.id] = {"code": code, "percent": percent}
    await reply_message(
        update.message,
        t("promo_accepted", lang, percent=percent if percent is not None else "?"),
        lang, voice=voice,
    )


def extract_invite_code(text: str):
    """The invite code a message carries, or None.

    A bare REF... token, or an explicit phrasing (\"my code is
    REF...\"). Promo codes never start with REF (the derivation
    always does), so a REF-prefixed token is an invite code, never
    a promo code. Reuses extract_promo_code's shapes — the two
    code families look alike in chat.
    """
    code = extract_promo_code(text)
    if code is not None and code.startswith("REF"):
        return code
    return None


def format_person_name(first_name, username):
    """Display name for naming a user to someone else (referral
    notices, 19 Nov 2026): first name plus @username when one
    exists, first name alone when there is none, @username alone
    when there is no first name. Never a phone number, Telegram
    id or balance. Returns None when nothing is known."""
    name = (first_name or "").strip()
    handle = (username or "").strip().lstrip("@")
    if name and handle:
        return f"{name} (@{handle})"
    if name:
        return name
    if handle:
        return f"@{handle}"
    return None


async def _notify_referrer_joined(bot, referrer_id: int,
                                  joiner_name=None,
                                  joiner_username=None) -> bool:
    """Tell a referrer someone joined with their code (William,
    16 Nov 2026): the code giver hears about it the moment a new
    user registers with their code. Since 19 Nov 2026 the new
    user is named (first name plus @username when one exists).
    Best-effort and never raises — a failed send must not break
    the registration reply (or /start). Returns True when the
    message was sent. Language is the referrer's last seen
    language (LAST_LANG), English when the referrer never chatted
    with the bot."""
    try:
        referrer_id = int(referrer_id)
    except (TypeError, ValueError):
        return False
    if referrer_id <= 0 or bot is None:
        return False
    lang = LAST_LANG.get(referrer_id, "en")
    display = format_person_name(joiner_name, joiner_username)
    if display is None:
        display = "አንድ ሰው" if lang == "am" else "Someone"
    try:
        await bot.send_message(
            chat_id=referrer_id,
            text=t("referral_joined", lang, name=display),
            reply_markup=hide_reply_keyboard(),
        )
    except Exception as exc:
        log.warning("referral-joined notify failed: %s", exc)
        return False
    return True


async def handle_invite_code_text(update, text: str, lang: str, voice=False) -> bool:
    """In-chat invite codes (both-sides referral bonus, 16 Nov
    2026): a user types a friend's invite code in the chat. True
    when the message carried an invite code and has been answered;
    False when it was not a code at all. A code typed while an
    order is open is understood, not swallowed as the link
    (live bug, 22:45 EAT 16 Nov 2026): the open order is parked
    first (saved, resumable with "order"). Runs BEFORE the promo
    branch: a REF code is
    promo-shaped, and typing one must NEVER show the invite-friends
    card — that card is only for \"my invite link\" requests (live
    bug, 19:27 EAT 16 Nov 2026: typing REFCVTYSVA3 showed the card
    and registered nothing). The referrer is registered with the
    server (POST /referrals); the 20% bonus itself is credited
    server-side on the first deposit, both sides. The bot never
    promises a bonus it did not register: an unavailable endpoint
    gets an honest \"try again later\", never a false confirmation.
    """
    user = update.effective_user
    code = extract_invite_code(text)
    if code is None:
        return False
    # Mid-order understanding (16 Nov 2026): a code typed while an
    # order is open is understood, not swallowed as the link — the
    # open order is parked first (saved, resumable with "order")
    # and the code is answered normally.
    await _park_order_and_note(update, user.id, lang, voice=voice)
    # Own code: checked locally — no server call, exact by derivation.
    if code == user_invite_code(user.id):
        await reply_message(
            update.message, t("invite_code_own", lang), lang, voice=voice,
        )
        return True
    # Invalid: the checksum fails locally — a mistyped code is
    # never sent to the server, and never credits the wrong person.
    if code != INVITE_CODE and invite_code_owner(code) is None:
        await reply_message(
            update.message, t("invite_code_invalid", lang), lang,
            voice=voice,
        )
        return True
    try:
        result = await paxyo.record_referral(user.id, code)
    except httpx.HTTPStatusError as exc:
        status = exc.response.status_code
        if status == 409:
            # Already deposited: the bonus is first-deposit only.
            await reply_message(
                update.message, t("invite_code_too_late", lang), lang,
                voice=voice,
            )
            return True
        if status == 400:
            # Server-side validation (a code the server rejects):
            # same plain line as a locally invalid code.
            await reply_message(
                update.message, t("invite_code_invalid", lang), lang,
                voice=voice,
            )
            return True
        log.warning("record_referral failed (%s): %s", status, exc)
        await reply_message(
            update.message, t("invite_code_unavailable", lang), lang,
            voice=voice,
        )
        return True
    except Exception as exc:
        log.warning("record_referral failed: %s", exc)
        await reply_message(
            update.message, t("invite_code_unavailable", lang), lang,
            voice=voice,
        )
        return True
    if result is None:
        # 404: the endpoint is not live yet — never claim the code
        # was saved when it was not.
        await reply_message(
            update.message, t("invite_code_unavailable", lang), lang,
            voice=voice,
        )
        return True
    if result.get("already_recorded"):
        # First referrer wins (server rule): a user who already has
        # one cannot add another. Referrer 0 means they joined with
        # the shared link — no real referrer, but the row still
        # stands, so the code cannot be added.
        referrer = result.get("referrer_telegram_id") or 0
        key = (
            "invite_code_already" if referrer
            else "invite_code_already_shared"
        )
        await reply_message(
            update.message, t(key, lang), lang, voice=voice,
        )
        return True
    referrer = result.get("referrer_telegram_id") or 0
    key = (
        "invite_code_registered" if referrer
        else "invite_code_registered_shared"
    )
    await reply_message(
        update.message, t(key, lang), lang, voice=voice,
    )
    if referrer:
        # Registration notice (William, 16 Nov 2026): the code giver
        # hears someone joined with their code. After the user's own
        # reply above, and best-effort — a failed notify never
        # changes that reply. Shared code records referrer 0, so no
        # message goes out for it.
        try:
            _bot = update.message.get_bot()
        except Exception:
            _bot = None
        await _notify_referrer_joined(
            _bot, referrer, user.first_name, user.username,
        )
    return True


async def handle_promo_text(update, text: str, lang: str, voice=False) -> bool:
    """The promo-code branch of handle_order_text: True when the
    message was a promo code (or a question about one) and has been
    answered, False when it was not a code at all. Runs before the
    classifier, with the other deterministic local guards. A code
    typed while an order is open is understood, not swallowed as
    the link (mid-order understanding, 16 Nov 2026): the open
    order is parked first (saved, resumable with "order"). A REF
    token never reaches here: the invite-code handler above already
    answered it — a typed invite code is registered, never shown
    the invite-friends card and never validated as a promo code."""
    user = update.effective_user
    code = extract_promo_code(text)
    offer = extract_promo_offer(text)
    if code is None and offer is None:
        return False
    await _park_order_and_note(update, user.id, lang, voice=voice)
    if code is not None:
        # A fresh code supersedes any pending "Is this a promo
        # code?" question — the user just gave the real one.
        PROMO_OFFER.pop(user.id, None)
        await handle_promo_code(update, code, lang, voice=voice)
        return True
    if offer is not None:
        PROMO_OFFER[user.id] = offer
        await reply_message(
            update.message, t("promo_ask", lang, code=offer),
            lang, voice=voice,
        )
        return True
    return False


# --------------------------------------------------- report a problem ---
# Ideas batch 2, feature 2 (15 Nov 2026): the user reports a problem
# with an order — or without one. Detection is deterministic, before
# the classifier, the same shape as the promo-code branch above: a
# "my order didn't arrive" would otherwise be read as an "orders"
# intent and answered with the history table. The flow NEVER
# refunds: it only files the report on the server (POST
# /support-reports) and says so in the confirmation. The report
# must not hijack an in-progress draft or Confirm card: it refuses
# to start while anything is being built (see _promo_busy) and the
# user finishes or cancels that first; while the flow is open, every
# message is read as the report's answer, so no draft can start
# underneath it. A quick-reply tap mid-flow drops the flow and the
# tap runs normally instead of being filed as a problem.

_REPORT_PROBLEM_PHRASES = (
    "report a problem", "report an issue", "report the problem",
    "report this problem", "report my problem", "report problem",
    "report a issue", "i want to report", "i need to report",
    "problem with my order", "problem with the order",
    "problem with order", "problem with this order",
    "problem with an order", "there's a problem", "there is a problem",
    "theres a problem", "something wrong with my order",
    "something wrong with the order", "something's wrong with my order",
    "something is wrong with my order", "issue with my order",
    "issue with the order", "issue with order",
    "there is something wrong", "there's something wrong",
)
_REPORT_ARRIVAL_PHRASES = (
    "didn't arrive", "did not arrive", "didnt arrive",
    "never arrived", "not arrived", "hasn't arrived",
    "has not arrived", "haven't arrived", "not delivered",
    "never delivered", "didn't come", "did not come", "didnt come",
    "didn't deliver", "did not deliver", "didn't show up",
    "did not show up", "never showed up",
)
# A reply to a delivery/order message is a complaint when it says
# the order did not arrive, is wrong, stuck or missing — but NOT a
# "where is it" (that is a status question, answered elsewhere) and
# NOT a "thanks" (that is just a thanks).
_REPORT_COMPLAINT_PHRASES = (
    "didn't arrive", "did not arrive", "didnt arrive",
    "never arrived", "not arrived", "hasn't arrived",
    "has not arrived", "not delivered", "never delivered",
    "didn't come", "did not come", "didn't work", "did not work",
    "not working", "wrong", "problem", "issue", "stuck",
    "missing", "broken", "failed", "didn't get", "did not get",
    "never got", "nothing arrived", "no delivery", "still not",
    "not here yet",
)
_REPORT_NO_ORDER_PHRASES = (
    "no order", "not about an order", "not an order",
    "something else", "none", "no specific order",
    "general problem", "other problem",
)
_REPORT_ORDER_RE = re.compile(r"order\s*(?:number|no\.?|#)?\s*(\d+)")
_REPORT_HASH_RE = re.compile(r"#\s*(\d+)")
# A digit run after "order" followed by one of these is a quantity
# ("order 10000 views"), not an order id — see
# extract_report_order_id.
_REPORT_METRIC_WORDS = frozenset((
    "views", "followers", "likes", "comments", "subscribers",
    "reactions", "members", "shares", "saves",
))
_REPORT_QUOTED_RE = re.compile(
    r"order\s*#\s*(\d+)|order\s+id:\s*(\d+)", re.IGNORECASE
)


def is_report_problem_request(text: str) -> bool:
    """True when the message reports a problem: an explicit report
    phrase ("report a problem with order 1841", "there's a problem
    with my order"), or an order that did not arrive ("my order
    1841 didn't arrive"). A bare "my order" with no problem word
    is not a report — that stays the history/status flow."""
    s = " ".join((normalize_text(text or "")).strip().lower().split())
    if not s:
        return False
    if any(p in s for p in _REPORT_PROBLEM_PHRASES):
        return True
    if "order" in s and any(p in s for p in _REPORT_ARRIVAL_PHRASES):
        return True
    return False


def is_report_complaint(text: str) -> bool:
    """True when a reply to a delivery/order message complains
    about that order (it did not arrive, is wrong, stuck, missing).
    The quoted message already pins the order, so no "order" word
    is needed here."""
    s = " ".join((normalize_text(text or "")).strip().lower().split())
    if not s:
        return False
    return any(p in s for p in _REPORT_COMPLAINT_PHRASES)


def extract_report_order_id(text: str):
    """The order id a report message names, or None. "order 1841",
    "order #1841", "order number 1841", "#1841" or a bare "1841".
    A digit run followed by "k" or by a metric word is a quantity
    ("order 10k views" — normalize_text already expanded the "k"
    to "10000" by the time this runs), not an order id, so it is
    skipped."""
    s = " ".join((normalize_text(text or "")).strip().lower().split())
    if not s:
        return None
    if re.fullmatch(r"\d+", s):
        return int(s)
    for match in _REPORT_ORDER_RE.finditer(s):
        after = s[match.end():match.end() + 1]
        if after == "k":
            continue
        rest = s[match.end():].strip()
        if rest:
            first_word = re.split(r"[\s,.!?]+", rest)[0]
            if first_word in _REPORT_METRIC_WORDS:
                continue
        return int(match.group(1))
    match = _REPORT_HASH_RE.search(s)
    if match:
        return int(match.group(1))
    return None


def extract_quoted_order_id(quoted_text):
    """The order id a quoted bot message names, or None. The
    delivery message says "order #1839", the order summary says
    "Order ID: 1839". A Confirm card names no order id yet, so a
    reply to it never matches here."""
    if not quoted_text:
        return None
    match = _REPORT_QUOTED_RE.search(str(quoted_text))
    if not match:
        return None
    return int(match.group(1) or match.group(2))


def _is_report_no_order(text: str) -> bool:
    """True when the user, asked which order the report is about,
    says it is not about an order ("no order", "something else")."""
    s = " ".join((normalize_text(text or "")).strip().lower().split())
    return any(p in s for p in _REPORT_NO_ORDER_PHRASES)


def report_pick_keyboard(orders) -> InlineKeyboardMarkup:
    """One button per recent order ("⚠️ #<id> <short name> ×<qty>",
    callback "report:<order_id>") plus "Something else — no order"
    ("report:none"), for the "which order?" step. Buttons stay
    English, like Confirm cards."""
    buttons = []
    for o in list(orders or [])[:5]:
        order_id = o.get("id") or o.get("order_id")
        if order_id is None:
            continue
        name = short_service_name(o.get("service_name") or "") or f"service {o.get('service_id')}"
        buttons.append([
            InlineKeyboardButton(
                f"⚠️ #{order_id} {name} ×{int(o.get('quantity') or 0)}",
                callback_data=f"report:{order_id}",
            )
        ])
    buttons.append([
        InlineKeyboardButton(
            t("report_no_order_button", "en"), callback_data="report:none"
        )
    ])
    return InlineKeyboardMarkup(buttons)


async def _report_ask_which(update, user_id: int, lang: str, voice=False):
    """Ask which order the report is about: the recent orders as
    buttons to tap, or a typed order number. With no recent orders
    the user is asked for the number (or "no order") in text."""
    REPORT_PENDING[user_id] = {"order_id": None, "step": "pick"}
    orders = []
    try:
        if paxyo is not None:
            orders = await paxyo.recent_orders(user_id, limit=5) or []
    except Exception as exc:
        log.warning("report recent orders failed: %s", exc)
        orders = []
    if orders:
        await reply_message(
            update.message, t("report_ask_which", lang), lang, voice=voice,
            reply_markup=report_pick_keyboard(orders),
        )
    else:
        await reply_message(
            update.message, t("report_ask_which_no_orders", lang),
            lang, voice=voice,
        )


async def _report_ask_description(update, user_id: int, order_id,
                                  lang: str, voice=False):
    """The order is known (or explicitly none): ask for the problem
    in one message. "cancel" drops the flow, handled by the caller."""
    REPORT_PENDING[user_id] = {"order_id": order_id, "step": "describe"}
    if order_id is None:
        text = t("report_ask_no_order", lang)
    else:
        text = t("report_ask_order", lang, order_id=order_id)
    await reply_message(update.message, text, lang, voice=voice)


async def _report_file(update, user_id: int, order_id, message: str,
                       lang: str, voice=False):
    """File the report and answer. The flow is popped FIRST, so a
    retry or a double-tap can never file it twice. A None reply
    (404: endpoint not live yet, or the named order is not this
    user's — the server answers both the same way) or any other
    failure is answered honestly with the t.me/paxyo fallback —
    the bot never pretends the report was filed."""
    REPORT_PENDING.pop(user_id, None)
    # The server caps the message at 2000 characters and rejects
    # longer input — trim, so a long description still files.
    text = (message or "").strip()[:2000]
    result = None
    if paxyo is not None:
        try:
            result = await paxyo.report_problem(
                user_id, text, order_id=order_id
            )
        except Exception as exc:
            log.warning("report_problem failed: %s", exc)
            result = None
    if isinstance(result, dict) and result.get("ok"):
        if order_id is None:
            await reply_message(
                update.message, t("report_filed_no_order", lang),
                lang, voice=voice,
            )
        else:
            await reply_message(
                update.message, t("report_filed", lang, order_id=order_id),
                lang, voice=voice,
            )
        return
    if order_id is None:
        await reply_message(
            update.message, t("report_not_live_no_order", lang),
            lang, voice=voice,
        )
    else:
        await reply_message(
            update.message, t("report_not_live", lang, order_id=order_id),
            lang, voice=voice,
        )


async def handle_report_text(update, text: str, lang: str, voice=False,
                             quoted_text=None) -> bool:
    """The report-a-problem branch of handle_order_text: True when
    the message belonged to the report flow and has been answered,
    False when it was not a report at all. Runs before the
    classifier, with the other deterministic local guards.

    An open flow reads every message as its answer: "cancel" (or
    "never mind", "stop") drops it and files nothing; in the "pick"
    step an order number (or a tap, handled by on_callback) moves
    to the description, "no order" reports without one, and anything
    else re-asks which order instead of filing against the wrong
    one; in the "describe" step any message is the description and
    is filed once. A quick-reply tap is not a description: the flow
    is dropped and the tap runs normally.

    A new report starts from a typed request, or from a complaint
    replied to a delivery/order message (the quoted text pins the
    order). It never starts while an order, deposit, plan or
    Confirm card is open — the user finishes or cancels that first,
    so a report can never hijack a draft."""
    user = update.effective_user
    flow = REPORT_PENDING.get(user.id)
    if flow is not None:
        if quick_reply_action(text) is not None:
            REPORT_PENDING.pop(user.id, None)
            return False
        if is_cancel_request(text):
            REPORT_PENDING.pop(user.id, None)
            await reply_message(
                update.message, t("report_cancelled", lang),
                lang, voice=voice,
            )
            return True
        if flow.get("step") == "pick":
            order_id = extract_report_order_id(text)
            if order_id is not None:
                await _report_ask_description(
                    update, user.id, order_id, lang, voice=voice
                )
                return True
            if _is_report_no_order(text):
                await _report_ask_description(
                    update, user.id, None, lang, voice=voice
                )
                return True
            await _report_ask_which(update, user.id, lang, voice=voice)
            return True
        # Describe step: a bare "yes" is not a description — ask
        # again instead of filing one word.
        if is_acceptance(text):
            await _report_ask_description(
                update, user.id, flow.get("order_id"), lang, voice=voice
            )
            return True
        await _report_file(
            update, user.id, flow.get("order_id"), text, lang, voice=voice
        )
        return True
    if quoted_text:
        quoted_id = extract_quoted_order_id(quoted_text)
        if quoted_id is not None and is_report_complaint(text):
            if _promo_busy(user.id):
                await reply_message(
                    update.message, t("report_busy", lang),
                    lang, voice=voice,
                )
                return True
            await _report_ask_description(
                update, user.id, quoted_id, lang, voice=voice
            )
            return True
    if is_report_problem_request(text):
        if _promo_busy(user.id):
            await reply_message(
                update.message, t("report_busy", lang), lang, voice=voice
            )
            return True
        order_id = extract_report_order_id(text)
        if order_id is not None:
            await _report_ask_description(
                update, user.id, order_id, lang, voice=voice
            )
            return True
        await _report_ask_which(update, user.id, lang, voice=voice)
        return True
    return False


async def _promo_bonus_line(user_id: int, deposit_id, lang: str) -> str:
    """The bonus line for a deposit that just completed, or "" when
    no promo code was attached to it. The server hook in
    bot_dep_status() is the primary credit path; the redeem call
    here is the safety net the server contract names — it returns
    the recorded bonus with duplicate:true when the hook already
    paid (never a second credit), and pays it when the hook did
    not (e.g. the deposit was made on the website after a validated
    code). The entry is cleared either way: one deposit, one bonus.
    When the redeem reply carries the bonus figure it is shown
    exactly; when the endpoint is not live the plain applied line
    stands (the hook may still have paid); when the redeem clearly
    fails the honest could-not-add line stands instead."""
    user_id = int(user_id)
    attached = PROMO_DEPOSIT.get(user_id)
    validated = VALIDATED_PROMO.get(user_id)
    entry = None
    from_attached = False
    if attached is not None:
        if attached.get("deposit_id") is None or (
            deposit_id is not None
            and str(attached.get("deposit_id")) == str(deposit_id)
        ):
            entry = attached
            from_attached = True
    if entry is None and validated is not None:
        # A website deposit (e.g. paid on the embedded page after
        # the chat push failed): no code was ever attached to its
        # create call, so the hook never saw it — redeem is the
        # only path to the bonus, and only for THIS deposit.
        entry = validated
    if entry is None:
        return ""
    code = entry.get("code")
    percent = entry.get("percent")
    if from_attached:
        # The code was spent on this deposit the moment it was
        # created: it is cleared whatever the redeem says — the
        # hook may still have paid, and a second deposit needs the
        # code typed again.
        PROMO_DEPOSIT.pop(user_id, None)
        VALIDATED_PROMO.pop(user_id, None)
    if not code or deposit_id is None:
        return ""
    if paxyo is None:
        return t(
            "promo_bonus_applied", lang, code=code,
            percent=percent if percent is not None else "?",
        )
    try:
        redeem = await paxyo.redeem_promo(user_id, code, deposit_id)
    except Exception as exc:
        log.warning("redeem_promo failed: %s", exc)
        if not from_attached:
            VALIDATED_PROMO.pop(user_id, None)
        return t("promo_bonus_failed", lang, code=code)
    if redeem is None:  # 404: the endpoint is not live yet
        if from_attached:
            return t(
                "promo_bonus_applied", lang, code=code,
                percent=percent if percent is not None else "?",
            )
        # The website deposit never carried the code, so nothing
        # could have paid the bonus — keep the code remembered for
        # the next deposit instead of dropping it silently.
        return ""
    if isinstance(redeem, dict) and redeem.get("ok"):
        if not from_attached:
            VALIDATED_PROMO.pop(user_id, None)
        bonus = redeem.get("bonus_etb")
        if bonus is not None:
            return t(
                "promo_bonus", lang, code=code,
                bonus=format_money(bonus),
                percent=(
                    redeem.get("percent")
                    if redeem.get("percent") is not None
                    else (percent if percent is not None else "?")
                ),
            )
        return t(
            "promo_bonus_applied", lang, code=code,
            percent=percent if percent is not None else "?",
        )
    if not from_attached:
        VALIDATED_PROMO.pop(user_id, None)
    return t("promo_bonus_failed", lang, code=code)


async def _maybe_big_deposit_alert(app, deposit, user_id: int,
                                   username, balance):
    """One admin alert for a completed deposit of BIG_DEPOSIT_ETB
    or more (feature 8, 15 Nov 2026): amount, user, method, new
    balance when known. Admin-only, via notify_admins — never to
    a customer. Deduped by deposit id in BIG_DEPOSIT_ALERTED: the
    status path can be called repeatedly for the same deposit (an
    "I paid" recheck), and each completed deposit alerts exactly
    once per process. Only ever called from the completed branch,
    so a failed or pending deposit never alerts. Never raises."""
    if app is None:
        return
    try:
        amount = float(deposit.get("amount") or 0)
    except (TypeError, ValueError):
        return
    if amount < BIG_DEPOSIT_ETB:
        return
    dep_key = str(deposit.get("id") or f"{user_id}:{amount}")
    if dep_key in BIG_DEPOSIT_ALERTED:
        return
    BIG_DEPOSIT_ALERTED.add(dep_key)
    who = f"@{username} ({user_id})" if username else f"user {user_id}"
    method = str(
        deposit.get("method") or deposit.get("payment_method") or "?"
    )
    method_label = METHOD_LABELS.get(method.lower(), method)
    text = t(
        "big_deposit_alert", "en",
        amount=format_money(amount), user=who, method=method_label,
    )
    if balance is not None:
        try:
            text += t(
                "big_deposit_balance", "en",
                balance=format_money(balance),
            )
        except (TypeError, ValueError):
            pass
    await notify_admins(app, text)


async def _referral_bonus_lines(user_id: int, deposit, lang: str, app=None,
                              first_name=None, username=None) -> list:
    """Referral-bonus notices for a completed first deposit (William,
    16 Nov 2026). The server's deposit record carries referral_bonus
    {referrer, invitee_paid, referrer_paid, invitee_bonus,
    referrer_bonus, invitee_notified, referrer_notified} — paid /
    notified flags from bot_referrals, gated on THIS deposit id (see
    server/api-referrals.php ref_bonus_for_deposit). A side is
    messaged only when paid AND not yet notified; the notify-ack call
    then marks it sent server-side, so a second recheck — even after
    a bot restart — never re-sends it. The invitee's line is returned
    (appended to the recheck reply); the referrer's is sent directly
    (needs app — without it the side is skipped this time and picked
    up on a later recheck, the flag stays 0). The referrer's message
    names the friend who deposited and the exact bonus they made
    (19 Nov 2026): the name comes from first_name/username when the
    caller has them, else a best-effort get_chat lookup, else the
    unnamed wording. Never raises: a failed send or ack only logs,
    and the reply still stands."""
    bonus = (deposit or {}).get("referral_bonus")
    if not isinstance(bonus, dict):
        return []
    dep_id = deposit.get("id")
    lines = []
    # Invitee side: this user, this deposit.
    if bonus.get("invitee_paid") and not bonus.get("invitee_notified"):
        try:
            amount = float(bonus.get("invitee_bonus") or 0)
        except (TypeError, ValueError):
            amount = 0.0
        if amount > 0:
            lines.append(
                t("referral_bonus_invitee", lang, amount=format_money(amount))
            )
            try:
                await paxyo.ack_referral_bonus(user_id, dep_id, "invitee")
            except Exception as exc:
                log.warning("referral bonus ack (invitee) failed: %s", exc)
    # Referrer side: a different user, so it is sent directly.
    referrer = bonus.get("referrer") or 0
    if (
        bonus.get("referrer_paid")
        and not bonus.get("referrer_notified")
        and referrer
        and app is not None
    ):
        try:
            referrer = int(referrer)
            amount = float(bonus.get("referrer_bonus") or 0)
        except (TypeError, ValueError):
            referrer = 0
            amount = 0.0
        if referrer > 0 and amount > 0:
            display = format_person_name(first_name, username)
            if display is None and app is not None:
                # The credit watcher has no user object — ask
                # Telegram for the depositor's name, best-effort.
                try:
                    chat = await app.bot.get_chat(user_id)
                    display = format_person_name(
                        getattr(chat, "first_name", None),
                        getattr(chat, "username", None),
                    )
                except Exception as exc:
                    log.warning(
                        "referral depositor name lookup failed: %s", exc
                    )
            referrer_lang = LAST_LANG.get(referrer, "en")
            if display is not None:
                text = t(
                    "referral_bonus_referrer_named",
                    referrer_lang,
                    name=display, amount=format_money(amount),
                )
            else:
                text = t(
                    "referral_bonus_referrer",
                    referrer_lang,
                    amount=format_money(amount),
                )
            try:
                await app.bot.send_message(
                    chat_id=referrer,
                    text=text,
                    reply_markup=hide_reply_keyboard(),
                )
            except Exception as exc:
                log.warning("referral bonus notify (referrer) failed: %s", exc)
            else:
                try:
                    await paxyo.ack_referral_bonus(user_id, dep_id, "referrer")
                except Exception as exc:
                    log.warning("referral bonus ack (referrer) failed: %s", exc)
    return lines


async def deposit_status_text(user_id: int, lang: str, app=None,
                              username=None, first_name=None) -> str:
    """Recheck the user's most recent deposit and say what happened,
    in one short message.

    The most recent in-session deposit (LAST_DEPOSIT) is checked
    first; after a restart the newest deposit from the list endpoint
    is used instead. The status call IS the recheck — the server
    re-verifies a pending deposit with Chapa before answering — so
    the bot never credits anything itself; it only reports what the
    server says, and never invents a failure reason.

    `app` (the PTB Application, from the call site's context) lets
    a completed deposit of BIG_DEPOSIT_ETB or more alert William
    once — see _maybe_big_deposit_alert. Without it the text is
    the same, just with no alert (the offline tests call it that
    way)."""
    deposit_id = LAST_DEPOSIT.get(user_id)
    deposit = None
    if deposit_id is not None:
        try:
            deposit = await paxyo.deposit_status(deposit_id, user_id)
        except Exception as exc:
            log.warning("deposit_status failed: %s", exc)
            return t("not_understood", lang)
        if deposit is None:  # 404: the endpoint is not live yet
            return t("deposit_check_not_ready", lang)
    else:
        try:
            deposits = await paxyo.list_deposits(user_id)
        except Exception as exc:
            log.warning("list_deposits failed: %s", exc)
            return t("not_understood", lang)
        if deposits is None:  # 404: the endpoint is not live yet
            return t("deposit_check_not_ready", lang)
        if not deposits:
            return t("no_deposits", lang)
        newest = deposits[0]
        try:
            deposit = await paxyo.deposit_status(newest.get("id"), user_id)
        except Exception as exc:
            log.warning("deposit_status failed: %s", exc)
            return t("not_understood", lang)
        if deposit is None:  # 404: the endpoint is not live yet
            return t("deposit_check_not_ready", lang)
    status = str(deposit.get("status") or "").strip().lower()
    amount = deposit.get("amount")
    amount_text = format_money(amount) if amount is not None else "?"
    if status in ("completed", "success", "paid"):
        checked_id = deposit_id if deposit_id is not None else deposit.get("id")
        promo_line = await _promo_bonus_line(user_id, checked_id, lang)
        try:
            data = await paxyo.balance(user_id)
            balance = data.get("balance") if data.get("found") else None
        except Exception as exc:
            log.warning("balance failed after deposit recheck: %s", exc)
            balance = None
        if balance is None:
            base = t("deposit_went_through_nobalance", lang, amount=amount_text)
        else:
            base = t(
                "deposit_went_through", lang,
                amount=amount_text, balance=format_money(balance),
            )
        # Big-deposit alert (feature 8, 15 Nov 2026): a completed
        # deposit of BIG_DEPOSIT_ETB or more alerts William once.
        # Deduped inside _maybe_big_deposit_alert, so a repeated
        # recheck of the same deposit never re-alerts.
        await _maybe_big_deposit_alert(
            app, deposit, user_id, username, balance
        )
        # Remember deposit method (23, 15 Nov 2026): a completed
        # deposit teaches the bot the user's last successful method,
        # so the next deposit offers it first. The method rides on
        # the deposit record (api-deposits.php). Best-effort and
        # throttled (schedule_traits_save): a failed save never
        # changes the reply, and a repeated recheck of the same
        # deposit re-saves the same value.
        _method = str(deposit.get("method") or "").strip().lower()
        if _method in ("telebirr", "cbe", "cbebirr", "mpesa"):
            _traits_entry(user_id)["last_deposit_method"] = _method
            schedule_traits_save(
                user_id, {"last_deposit_method": _method}
            )
        extra_lines = []
        if promo_line:
            extra_lines.append(promo_line)
        extra_lines.extend(
            await _referral_bonus_lines(
                user_id, deposit, lang, app,
                first_name=first_name, username=username,
            )
        )
        if extra_lines:
            return base + "\n" + "\n".join(extra_lines)
        return base
    if status in ("failed", "cancelled", "canceled", "expired", "rejected"):
        reason = (
            deposit.get("message") or deposit.get("error")
            or deposit.get("reason")
        )
        if isinstance(reason, str) and reason.strip():
            return t(
                "deposit_failed_reason", lang,
                amount=amount_text, reason=reason.strip(),
            )
        return t("deposit_failed_check", lang, amount=amount_text)
    return t("deposit_still_pending", lang, amount=amount_text)


async def stop_one_schedule(update, sched, lang, voice=False):
    """Cancel one repeating order and confirm it in one short line."""
    user = update.effective_user
    try:
        await paxyo.cancel_recurring(sched.get("id"), user.id)
    except Exception as exc:
        log.warning("cancel_recurring failed: %s", exc)
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    name = short_service_name(sched.get("service_name")) or f"service {sched.get('service_id')}"
    await reply_message(
        update.message, t("schedule_stopped", lang, service=name), lang, voice=voice
    )


async def stop_schedules_flow(update, schedules, lang, voice=False):
    """One active schedule -> cancel it directly; several -> buttons
    so the user picks which one to stop."""
    if len(schedules) == 1:
        await stop_one_schedule(update, schedules[0], lang, voice=voice)
        return
    await reply_message(
        update.message, t("ask_which_schedule", lang), lang, voice=voice,
        reply_markup=stop_schedule_keyboard(schedules),
    )


async def handle_stop_schedule(update, lang, voice=False):
    """'Stop the repeating order' / 'cancel my schedule'."""
    user = update.effective_user
    try:
        schedules = await paxyo.list_recurring(user.id)
    except Exception as exc:
        log.warning("list_recurring failed: %s", exc)
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    if not schedules:
        await reply_message(update.message, t("no_schedules", lang), lang, voice=voice)
        return
    await stop_schedules_flow(update, schedules, lang, voice=voice)


_THAT_LINK_ONLY = (
    "that link", "same link", "the same link", "that one",
    "the link from before", "last link", "that post", "that video",
)


def _is_recurring_followup(text, user_id):
    """True when a message only answers the open repeating-order
    plan's question: a bare link, "that link", or a runs answer
    ("10 times", a bare number while the plan waits for runs). A
    fuller message (a fresh order, a balance question, a deposit)
    is not a follow-up and goes through the normal dispatch."""
    draft = RECURRING_DRAFT.get(user_id) or {}
    if not draft:
        return False
    links = extract_links(text or "")
    rest = text or ""
    for link in links:
        rest = rest.replace(link, " ")
    rest = " ".join(rest.strip().lower().split())
    if links and not rest:
        # A bare link answers the plan's link question, unless a
        # normal order is being built at the same time, in which
        # case the link belongs to that order.
        return not PARTIAL.get(user_id)
    if not draft.get("link"):
        if (
            any(p in rest for p in _THAT_LINK_ONLY)
            and not re.search(r"\d", rest)
        ):
            return True
    if draft.get("runs") is None:
        if parse_runs(text) is not None:
            # A runs answer carries no link, platform, metric or
            # interval words: "repeat it 10 times" counts,
            # "10k views every hour" does not.
            if links:
                return False
            words = rest.split()
            if any(w in _PLATFORMS or w in _METRICS for w in words):
                return False
            if re.search(
                r"\b(every|hour|hours|hr|hrs|day|days|minute|minutes|min|mins|week|weeks)\b",
                rest,
            ):
                return False
            return True
        if rest.isdigit() and not DEPOSIT_DRAFT.get(user_id):
            # A bare number is the runs answer, unless a normal
            # order is waiting for its quantity.
            partial = PARTIAL.get(user_id) or {}
            return not (partial.get("link") and not partial.get("quantity"))
    return False


def _runs_from_total(user_id, merged):
    """Runs from a total the user already gave: a parked or
    in-progress draft, or the plain Confirm card still waiting,
    for the SAME platform whose quantity is a whole multiple of
    this plan's per-drop quantity. 100k total at 10k a drop is 10
    runs. None when there is no such total, or it does not split
    evenly: the bot then asks how many times instead of guessing.
    """
    try:
        per_drop = int(merged.get("quantity") or 0)
    except (TypeError, ValueError):
        return None
    if per_drop <= 0:
        return None
    platform = (merged.get("platform") or "").strip().lower()
    if not platform:
        return None
    _candidates = [PARTIAL.get(user_id) or {}, PARKED_DRAFT.get(user_id) or {}]
    _cid, _pending = pending_for_user(user_id)
    if _pending is not None:
        _candidates.append(_pending)
    for draft in _candidates:
        try:
            total = int(draft.get("quantity") or 0)
        except (TypeError, ValueError):
            continue
        if total <= per_drop or total % per_drop != 0:
            continue
        draft_platform = (draft.get("platform") or "").strip().lower()
        if draft_platform != platform:
            continue
        return total // per_drop
    return None


async def _refuse_mismatched_link(update, draft_store, user_id, merged,
                                  service, lang, voice=False):
    """A link from ANOTHER platform never reaches Confirm: drop it
    from the draft and ask for the right link. Returns True when
    the link was refused (the caller returns), False when the
    caller continues. Only the platform (domain) is refused here:
    a wrong link TYPE (a post link for a followers service) is
    left to place_pending_order, the same backstop the normal
    order flow uses — it refuses at placement and asks for the
    right link instead of placing."""
    error = validate_order_link(merged.get("link"), service)
    if error != "platform":
        return False
    dropped = {k: v for k, v in merged.items() if v is not None}
    dropped.pop("link", None)
    draft_store[user_id] = dropped
    platform, _hint = _platform_hint_of_service(service)
    await reply_message(
        update.message,
        t(
            "platform_mismatch", lang,
            link_platform=platform_from_link(merged.get("link")),
            platform=(
                (merged.get("platform") or "").strip().lower()
                or platform or ""
            ),
        ),
        lang, voice=voice,
    )
    return True


def _current_conversation_order(user_id):
    """The order this user is already building in THIS conversation:
    the in-progress draft, the parked draft, or the plain Confirm
    card still waiting. Returns the first one found, or None. Only
    for link (and platform/hint) reuse by the drip handler: an old
    placed order is never in this list, so a stale link from
    another order can never sneak in this way."""
    if PARTIAL.get(user_id):
        return PARTIAL[user_id]
    if PARKED_DRAFT.get(user_id):
        return PARKED_DRAFT[user_id]
    _cid, pending = pending_for_user(user_id)
    if pending is not None:
        return pending
    return None


async def handle_recurring_text(update, text, intent, lang, voice=False):
    """Build a BOUNDED repeating-order plan (drip-feed) over several
    turns, then show the plan summary with a Confirm card. Nothing
    is created on the server until the user taps Confirm (or says
    yes): a plan that repeats by itself must never start on a
    misunderstood message.

    Missing pieces are asked in order: platform -> link -> quantity
    -> interval -> runs. The link is NEVER taken from the user's
    last order unless they explicitly say so ("that link"): a
    stale link for another platform must never land on a Confirm
    card, and a link from another platform is refused before the
    card (a wrong link type is caught at placement, the same
    backstop the normal order flow uses). The link IS taken from
    the current conversation (the draft being built, the parked
    draft, or the plain card still waiting), so a drip version of
    the order just discussed does not ask for the link again.
    The plan is always bounded: the number of runs
    comes from the user ("10 times"), from a total they already
    gave (100k total at 10k a drop is 10 runs), or the bot asks
    "how many times?". The card shows per-drop quantity, interval,
    runs, total quantity, total cost and the last drop. On Confirm
    the plan is placed as ONE provider drip-feed order
    (runs/interval), charged up front: never as an open-ended
    schedule, and never faked with separate orders.
    """
    user = update.effective_user
    stored = RECURRING_DRAFT.get(user.id) or {}
    new_platform = (intent.get("platform") or "").strip().lower()
    stored_platform = (stored.get("platform") or "").strip().lower()
    if new_platform and stored_platform and new_platform != stored_platform:
        stored = {}
    merged = {}
    for key in ("platform", "service_hint", "link", "quantity",
                "interval_minutes", "runs"):
        value = intent.get(key)
        merged[key] = value if value is not None else stored.get(key)
    if merged.get("interval_minutes") is None:
        merged["interval_minutes"] = parse_interval_minutes(text)
    try:
        interval = (
            int(merged["interval_minutes"])
            if merged.get("interval_minutes") is not None
            else None
        )
    except (TypeError, ValueError):
        interval = None
    merged["interval_minutes"] = interval
    if interval is not None and interval < MIN_RECURRING_MINUTES:
        RECURRING_DRAFT.pop(user.id, None)
        await reply_message(update.message, t("interval_too_short", lang), lang, voice=voice)
        return
    # Runs: from the message ("10 times"), from a bare number when
    # the plan is only waiting for runs, or from a total the user
    # already gave for the same platform (see _runs_from_total).
    # A count under 2 is not a repeat.
    if merged.get("runs") is None:
        merged["runs"] = parse_runs(text)
    if (
        merged.get("runs") is None
        and merged.get("quantity") is not None
        and merged.get("interval_minutes") is not None
        and (text or "").strip().isdigit()
    ):
        merged["runs"] = int((text or "").strip())
    if merged.get("runs") is None:
        merged["runs"] = _runs_from_total(user.id, merged)
    try:
        runs = int(merged["runs"]) if merged.get("runs") is not None else None
    except (TypeError, ValueError):
        runs = None
    if runs is not None and runs < 2:
        runs = None
    merged["runs"] = runs
    # The link is resolved from the user's most recent order ONLY
    # when they explicitly say so ("that link"): never silently.
    # A link pasted in this message (or carried by the intent)
    # always wins; otherwise the bot asks for it.
    last_service_id = None
    if not merged.get("link"):
        _raw_links = extract_links(text)
        if _raw_links:
            merged["link"] = _raw_links[0]
    if not merged.get("link") and mentions_that_link(text):
        last = await resolve_last_order(user.id)
        if last and last.get("link"):
            merged["link"] = last.get("link")
            last_service_id = last.get("combined_id") or last.get("service_id")
    if not merged.get("link"):
        # The link from the CURRENT conversation: the draft being
        # built, the parked draft a price question just saved, or
        # the plain Confirm card still waiting. Those are this
        # conversation, so their links are safe to reuse — unlike
        # an old placed order, which stays explicit-"that link"-
        # only. The platform and hint ride along when the request
        # does not name its own.
        _current = _current_conversation_order(user.id)
        if _current is not None and _current.get("link"):
            merged["link"] = _current.get("link")
            if not merged.get("platform") and _current.get("platform"):
                merged["platform"] = _current.get("platform")
            if not merged.get("service_hint") and _current.get("service_hint"):
                merged["service_hint"] = _current.get("service_hint")
    if not merged.get("platform") and not merged.get("service_hint") and last_service_id is None:
        RECURRING_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(update.message, t("ask_platform", lang), lang, voice=voice)
        return
    if not merged.get("link"):
        RECURRING_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(
            update.message,
            ask_link_text(merged.get("platform"), merged.get("service_hint"), lang),
            lang, voice=voice,
        )
        return
    if not merged.get("quantity"):
        RECURRING_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(update.message, t("ask_quantity", lang), lang, voice=voice)
        return
    if not merged.get("interval_minutes"):
        RECURRING_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(update.message, t("ask_interval", lang), lang, voice=voice)
        return
    if not merged.get("runs"):
        RECURRING_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(update.message, t("ask_runs", lang), lang, voice=voice)
        return

    # Complete plan: pick the service and show the summary with Confirm.
    RECURRING_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
    # Drip-feed must be live on the server before the card is
    # shown: a repeat is a provider drip-feed order, and without
    # the endpoint the bot would promise what it cannot place.
    # The service's own drip-feed flag is checked after the pick.
    # A probe failure is "not live", never silence: the probe
    # itself is total too, but this call must never raise into
    # the turn either (19 Nov 2026: it did, and the user got
    # no reply at all).
    try:
        _drip_live = await paxyo.dripfeed_live()
    except Exception:
        _drip_live = False
    if not _drip_live:
        await reply_message(update.message, t("drip_not_live", lang), lang, voice=voice)
        return
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("services fetch failed: %s", exc)
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    service = None
    if (
        last_service_id is not None
        and not merged.get("platform")
        and not merged.get("service_hint")
    ):
        for s in services:
            try:
                if int(s.get("service", 0)) == int(last_service_id):
                    service = s
                    break
            except (TypeError, ValueError):
                continue
    if service is None:
        picks = pick_services(
            services, platform=merged.get("platform"),
            service_hint=merged.get("service_hint"),
            reaction_emoji=reaction_emoji(text),
        )
        if not picks:
            await reply_message(
                update.message,
                no_service_reply(
                    merged.get("platform"), merged.get("service_hint"),
                    text, lang,
                ) or t("no_service", lang),
                lang, voice=voice,
            )
            return
        service = picks[0]
    error = validate_quantity(merged.get("quantity"), service)
    if error:
        await reply_message(
            update.message,
            t(
                "bad_quantity",
                lang,
                service=short_service_name(service.get("name")),
                min=service.get("min"),
                max=service.get("max"),
            ),
            lang,
            voice=voice,
        )
        return
    # The link must fit the service: a Telegram link on a TikTok
    # order never reaches the Confirm card.
    if await _refuse_mismatched_link(
        update, RECURRING_DRAFT, user.id, merged, service, lang, voice=voice
    ):
        return
    if service.get("dripfeed") is False:
        RECURRING_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(
            update.message, t("drip_service_no_dripfeed", lang), lang, voice=voice
        )
        return
    per_drop = int(merged["quantity"])
    rate = float(service.get("rate_etb_per_1000", 0))
    total_qty = per_drop * runs
    total_cost = estimated_total_etb(rate, total_qty)
    # Affordability is judged on the TOTAL of all runs, never on
    # one drop: the provider charges the whole drip up front.
    _shortfall = await _low_balance_shortfall(user.id, service, total_cost)
    if _shortfall is not None:
        _short_amount, _balance = _shortfall
        RECURRING_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(
            update.message,
            t(
                "drip_low_balance", lang,
                total=format_money(total_cost),
                runs=runs,
                per_run=f"{per_drop:,}",
                interval=format_interval(interval),
                balance=format_money(_balance),
                shortfall=format_money(_short_amount),
            ),
            lang, voice=voice,
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton(
                    t("deposit_webapp_button", lang,
                      amount=format_money(_short_amount)),
                    callback_data=f"depshort:{_short_amount:.2f}",
                )
            ]]),
        )
        return
    # Weekly spending limit (#25): the same refusal as a normal
    # order, judged on the total.
    _weekly_limit = get_pref(user.id, "pref_weekly_spend_limit_etb")
    if _weekly_limit is not None:
        _spent = await _weekly_spent_etb(user.id)
        if _spent + total_cost > _weekly_limit:
            RECURRING_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
            await reply_message(
                update.message,
                t(
                    "drip_weekly_limit", lang,
                    spent=format_money(_spent),
                    limit=format_money(_weekly_limit),
                    total=format_money(total_cost),
                ),
                lang, voice=voice,
            )
            return
    confirm_id = uuid.uuid4().hex[:12]
    RECURRING_DRAFT.pop(user.id, None)
    PENDING[confirm_id] = {
        "user_id": user.id,
        "service": service,
        "link": merged["link"],
        "quantity": total_qty,
        "total": total_cost,
        "full_name": False,
        "platform": merged.get("platform"),
        "service_hint": merged.get("service_hint"),
        "reaction_emoji": reaction_emoji(text),
        "drip": {
            "runs": runs,
            "interval": interval,
            "per_run_qty": per_drop,
        },
    }
    _note = (
        f"Drip-feed: {runs} runs of {per_drop:,} every "
        f"{format_interval(interval)}. "
        f"Last drop {_drip_end_text(runs, interval)}."
    )
    _sent = await reply_message(
        update.message,
        confirm_card_text(
            lang, service, total_qty, total_cost, merged["link"],
            note=_note, full_name=False,
        ),
        lang,
        reply_markup=confirm_keyboard(confirm_id),
    )
    _remember_card_message(PENDING[confirm_id], update.message, _sent)

async def handle_auto_refill_text(update, text, intent, lang, voice=False):
    """Build an auto-refill (keep-above-target) setup over several
    turns, then show the preview with a Confirm card. Nothing is
    switched on until the user taps Confirm (or says yes): a
    setup that spends the user's balance by itself must never
    start on a misunderstood message.

    Missing pieces are asked in order: platform -> link ->
    target -> guards (when to top up, whether there is a daily
    limit). The link is NEVER taken from the user's last order:
    a stale link here would top up the wrong post, every hour,
    until someone notices. Only a link sent in THIS conversation
    (the message, the draft being built, or the plain card still
    waiting) is used. The preview says plainly that the bot will
    use the user's balance when the count drops, names the
    trigger and the daily limit (or that there is none), and
    says the refill can be stopped any time — that warning is
    the point of the Confirm card, not fine print.
    """
    user = update.effective_user
    stored = AUTO_REFILL_DRAFT.get(user.id) or {}
    new_platform = (intent.get("platform") or "").strip().lower()
    stored_platform = (stored.get("platform") or "").strip().lower()
    if new_platform and stored_platform and new_platform != stored_platform:
        stored = {}
    merged = {}
    for key in ("platform", "service_hint", "link", "target",
                "trigger", "daily_cap", "guards_asked",
                "guards_decided"):
        value = intent.get(key)
        merged[key] = value if value is not None else stored.get(key)
    if merged.get("target") is None:
        merged["target"] = parse_auto_refill_target(text)
    if merged.get("target") is None and (text or "").strip().isdigit():
        # A bare number while the setup waits for its target.
        merged["target"] = int((text or "").strip())
    try:
        target = int(merged["target"]) if merged.get("target") is not None else None
    except (TypeError, ValueError):
        target = None
    if target is not None and target < 10:
        target = None
    merged["target"] = target
    if not merged.get("link"):
        _raw_links = extract_links(text)
        if _raw_links:
            merged["link"] = _raw_links[0]
    if not merged.get("link"):
        # The link from the CURRENT conversation only: the draft
        # being built, the parked draft, or the plain Confirm
        # card still waiting. Never the last placed order.
        _current = _current_conversation_order(user.id)
        if _current is not None and _current.get("link"):
            merged["link"] = _current.get("link")
            if not merged.get("platform") and _current.get("platform"):
                merged["platform"] = _current.get("platform")
            if not merged.get("service_hint") and _current.get("service_hint"):
                merged["service_hint"] = _current.get("service_hint")
    if not merged.get("platform") and not merged.get("service_hint"):
        AUTO_REFILL_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(update.message, t("ask_platform", lang), lang, voice=voice)
        return
    if not merged.get("link"):
        AUTO_REFILL_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(
            update.message,
            ask_link_text(merged.get("platform"), merged.get("service_hint"), lang),
            lang, voice=voice,
        )
        return
    if merged.get("target") is None:
        AUTO_REFILL_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(
            update.message, t("ask_auto_refill_target", lang), lang, voice=voice,
        )
        return

    # Complete setup: pick the service, then check the count can
    # actually be read for it. A platform+metric with no count
    # chain (Instagram today) is refused honestly here, before
    # any Confirm card promises it.
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("services fetch failed: %s", exc)
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    picks = pick_services(
        services, platform=merged.get("platform"),
        service_hint=merged.get("service_hint"),
        reaction_emoji=reaction_emoji(text),
    )
    if not picks:
        await reply_message(
            update.message,
            no_service_reply(
                merged.get("platform"), merged.get("service_hint"),
                text, lang,
            ) or t("no_service", lang),
            lang, voice=voice,
        )
        return
    service = picks[0]
    metric = _auto_refill_metric(merged.get("service_hint"), service)
    platform = (merged.get("platform") or "").strip().lower()
    if not platform:
        platform = (platform_from_link(merged["link"]) or "").strip().lower()
    if metric is None or not count_chain_supports(platform, metric):
        AUTO_REFILL_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(
            update.message,
            t("auto_refill_count_unsupported", lang, platform=platform or "this"),
            lang, voice=voice,
        )
        return
    minimum = _service_min_qty(service)
    if target < minimum:
        AUTO_REFILL_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(
            update.message,
            t(
                "auto_refill_target_too_small", lang,
                service=short_service_name(service.get("name")),
                min=minimum,
            ),
            lang, voice=voice,
        )
        return
    # The link must fit the service, same backstop as the normal
    # order flow: a Telegram link on a TikTok refill never
    # reaches the Confirm card.
    if await _refuse_mismatched_link(
        update, AUTO_REFILL_DRAFT, user.id, merged, service, lang, voice=voice
    ):
        return
    # Guards (owner, 20 Nov 2026): before the preview, the setup
    # asks once when to top up and whether there is a daily
    # limit. Defaults: 5% below the target, no daily limit. The
    # answer is parsed from the message that follows the
    # question; "ok" keeps both, a drop ("when it drops by 200",
    # "10%") or a limit ("limit 1000 a day") replaces them. An
    # answer that parses as neither keeps the defaults — the
    # preview states them plainly and the user can still cancel.
    if not merged.get("guards_decided"):
        if merged.get("guards_asked"):
            parsed_trigger = parse_auto_refill_trigger(text)
            parsed_cap = parse_auto_refill_daily_cap(text)
            if parsed_trigger is not None:
                merged["trigger"] = parsed_trigger
            if parsed_cap is not None:
                merged["daily_cap"] = parsed_cap
            merged["guards_decided"] = True
            merged["guards_asked"] = None
        else:
            _draft = {k: v for k, v in merged.items() if v is not None}
            _draft["guards_asked"] = True
            AUTO_REFILL_DRAFT[user.id] = _draft
            await reply_message(
                update.message,
                t("ask_auto_refill_guards", lang, target=f"{target:,}"),
                lang, voice=voice,
            )
            return
    confirm_id = uuid.uuid4().hex[:12]
    AUTO_REFILL_DRAFT.pop(user.id, None)
    PENDING_AUTO_REFILL[confirm_id] = {
        "user_id": user.id,
        "service": service,
        "link": merged["link"],
        "target": target,
        "metric": metric,
        "platform": platform,
        "daily_cap": merged.get("daily_cap"),
        "trigger": merged.get("trigger"),
    }
    # A dedicated preview, not confirm_card_text: there is no
    # single order here, so no quantity and no total — showing
    # "0.00 ETB" would be a lie, the top-ups cost later. The
    # balance warning is the note on top, in plain words.
    _note = (
        f"Auto-refill: keep {metric} above {target:,} — checked every hour. "
        f"I will use your balance "
        f"{auto_refill_trigger_text(merged.get('trigger'), target, lang)}, "
        f"only the missing amount. "
        f"{auto_refill_limit_text(merged.get('daily_cap'), lang)} "
        "You can stop it any time — just say 'stop auto refill'."
    )
    _preview = _strip_dashes("\n".join([
        t("confirm_title", lang), "",
        _note, "",
        f"{short_service_name(service.get('name'))} (#{service.get('service')})",
        f"⏱ {service.get('average_time') or 'n/a'}",
        f"💰 {format_money(service.get('rate_etb_per_1000', 0))} ETB / 1000",
        f"🔗 {merged['link']}",
        "",
        t("public_reminder", lang),
    ]))
    _sent = await reply_message(
        update.message,
        _preview,
        lang,
        reply_markup=confirm_keyboard(confirm_id),
    )
    _remember_card_message(PENDING_AUTO_REFILL[confirm_id], update.message, _sent)


def _is_auto_refill_followup(text, user_id):
    """True when a message only answers the open auto-refill
    setup's question: a bare link, a bare number while the
    setup waits for its target, or an answer to the guards
    question ("ok", "when it drops by 200", "10%", "limit 1000
    a day"). A fuller message (a fresh order, a balance
    question, a deposit) is not a follow-up and goes through
    the normal dispatch."""
    draft = AUTO_REFILL_DRAFT.get(user_id) or {}
    if not draft:
        return False
    links = extract_links(text or "")
    rest = text or ""
    for link in links:
        rest = rest.replace(link, " ")
    rest = " ".join(rest.strip().lower().split())
    if draft.get("guards_asked"):
        if rest in ("ok", "okay", "yes", "keep", "default", "no",
                    "no limit", "none", "unlimited", "no cap"):
            return True
        if parse_auto_refill_trigger(text) is not None:
            return True
        if parse_auto_refill_daily_cap(text) is not None:
            return True
        if rest.isdigit():
            return True
        return False
    if links and not rest:
        return not PARTIAL.get(user_id)
    if draft.get("target") is None and rest.isdigit():
        partial = PARTIAL.get(user_id) or {}
        return not (partial.get("link") and not partial.get("quantity"))
    return False


async def handle_auto_refill_status(update, lang, voice=False):
    """List the user's confirmed auto-refills, or say there are
    none. The lines are honest about the server: until the
    refill endpoint is live the hourly check is not installed,
    and a refill saved on this chat only (the server save
    failed) is named as such, so the user is never told a
    refill is checking when it is not."""
    user = update.effective_user
    refills = await refill_store_list(user.id)
    if not refills:
        await reply_message(
            update.message, t("auto_refill_none", lang), lang, voice=voice,
        )
        return
    lines = []
    for refill in refills:
        service = refill.get("service") or {}
        trigger = auto_refill_trigger_text(
            refill.get("trigger"), refill.get("target"), lang)
        if refill.get("daily_cap") is None:
            limit = ("no daily limit" if lang != "am"
                     else "የቀን ገደብ የለም")
        else:
            limit = (f"at most {format_money(refill.get('daily_cap'))} ETB a day"
                     if lang != "am" else
                     f"በቀን እስከ {format_money(refill.get('daily_cap'))} ETB")
        lines.append(
            f"{short_service_name(service.get('name'))}: "
            f"keep {refill.get('metric')} above {refill.get('target'):,} — "
            f"tops up {trigger}, {limit} — "
            f"{refill.get('link')}"
        )
    if not await refills_live():
        lines.append(
            "The hourly check on the server is not installed yet, "
            "so no top-up will happen until that is live."
        )
    if any(not r.get("_server") for r in refills):
        lines.append(
            "One refill is saved on this chat only and not on the "
            "server yet, so the hourly check will not see it."
        )
    await reply_message(
        update.message, "\n".join(lines), lang, voice=voice,
    )


async def handle_auto_refill_stop(update, text, lang, voice=False):
    """Stop the user's auto-refill(s). One refill stops itself;
    several ask which one (the same shape as stop_schedule)."""
    user = update.effective_user
    refills = await refill_store_list(user.id)
    if not refills:
        await reply_message(
            update.message, t("auto_refill_none_to_stop", lang), lang, voice=voice,
        )
        return
    if len(refills) == 1:
        stopped = refills[0]
        if not await refill_store_stop(stopped, user.id):
            await reply_message(
                update.message, t("auto_refill_stop_failed", lang),
                lang, voice=voice,
            )
            return
        await reply_message(
            update.message,
            t(
                "auto_refill_stopped", lang,
                service=short_service_name((stopped.get("service") or {}).get("name")),
            ),
            lang, voice=voice,
        )
        return
    # Several: stop the one the message names, or ask.
    named = None
    low = (text or "").lower()
    for refill in refills:
        service = refill.get("service") or {}
        name = short_service_name(service.get("name")).lower()
        if name and name in low:
            named = refill
            break
        if (refill.get("link") or "") in (text or ""):
            named = refill
            break
    if named is not None:
        if not await refill_store_stop(named, user.id):
            await reply_message(
                update.message, t("auto_refill_stop_failed", lang),
                lang, voice=voice,
            )
            return
        await reply_message(
            update.message,
            t(
                "auto_refill_stopped", lang,
                service=short_service_name((named.get("service") or {}).get("name")),
            ),
            lang, voice=voice,
        )
        return
    await reply_message(
        update.message,
        t("stop_which", lang) + "\n" + "\n".join(
            f"- {short_service_name((r.get('service') or {}).get('name'))}: "
            f"keep {r.get('metric')} above {r.get('target'):,}"
            for r in refills
        ),
        lang, voice=voice,
    )


async def handle_delayed_order_text(update, text, intent, lang, voice=False):
    """Build a one-time delayed order over several turns, then show
    the Confirm card with the scheduled time. Nothing is scheduled
    on the server until the user taps Confirm (or says yes): an
    order that places itself later must never start on a
    misunderstood message.

    Missing pieces are asked in order: platform -> link -> quantity
    -> delay. The link is resolved from the user's most recent order
    when they say "that link" or give no link at all — the Confirm
    card shows the link and the scheduled time, and Confirm is the
    safety net.
    """
    user = update.effective_user
    stored = DELAYED_DRAFT.get(user.id) or {}
    new_platform = (intent.get("platform") or "").strip().lower()
    stored_platform = (stored.get("platform") or "").strip().lower()
    if new_platform and stored_platform and new_platform != stored_platform:
        stored = {}
    merged = {}
    for key in ("platform", "service_hint", "link", "quantity", "delay_minutes"):
        value = intent.get(key)
        merged[key] = value if value is not None else stored.get(key)
    if merged.get("delay_minutes") is None:
        merged["delay_minutes"] = parse_delay_minutes(text)
    try:
        delay = (
            int(merged["delay_minutes"])
            if merged.get("delay_minutes") is not None
            else None
        )
    except (TypeError, ValueError):
        delay = None
    merged["delay_minutes"] = delay
    last_service_id = None
    if not merged.get("link"):
        _raw_links = extract_links(text)
        if _raw_links:
            merged["link"] = _raw_links[0]
    if not merged.get("link") and mentions_that_link(text):
        last = await resolve_last_order(user.id)
        if last and last.get("link"):
            merged["link"] = last.get("link")
            last_service_id = last.get("combined_id") or last.get("service_id")
    if not merged.get("platform") and not merged.get("service_hint") and last_service_id is None:
        DELAYED_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(update.message, t("ask_platform", lang), lang, voice=voice)
        return
    if not merged.get("link"):
        DELAYED_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(
            update.message,
            ask_link_text(merged.get("platform"), merged.get("service_hint"), lang),
            lang, voice=voice,
        )
        return
    if not merged.get("quantity"):
        DELAYED_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(update.message, t("ask_quantity", lang), lang, voice=voice)
        return
    if not merged.get("delay_minutes"):
        DELAYED_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(update.message, t("ask_delay", lang), lang, voice=voice)
        return

    # Complete order: pick the service and show the Confirm card with
    # the scheduled time.
    DELAYED_DRAFT[user.id] = {k: v for k, v in merged.items() if v is not None}
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("services fetch failed: %s", exc)
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    service = None
    if (
        last_service_id is not None
        and not merged.get("platform")
        and not merged.get("service_hint")
    ):
        for s in services:
            try:
                if int(s.get("service", 0)) == int(last_service_id):
                    service = s
                    break
            except (TypeError, ValueError):
                continue
    if service is None:
        picks = pick_services(
            services, platform=merged.get("platform"),
            service_hint=merged.get("service_hint"),
            reaction_emoji=reaction_emoji(text),
        )
        if not picks:
            await reply_message(
                update.message,
                no_service_reply(
                    merged.get("platform"), merged.get("service_hint"),
                    text, lang,
                ) or t("no_service", lang),
                lang, voice=voice,
            )
            return
        service = picks[0]
    error = validate_quantity(merged.get("quantity"), service)
    if error:
        await reply_message(
            update.message,
            t(
                "bad_quantity",
                lang,
                service=short_service_name(service.get("name")),
                min=service.get("min"),
                max=service.get("max"),
            ),
            lang,
            voice=voice,
        )
        return
    if await _refuse_mismatched_link(
        update, DELAYED_DRAFT, user.id, merged, service, lang, voice=voice
    ):
        return
    quantity = int(merged["quantity"])
    rate = float(service.get("rate_etb_per_1000", 0))
    total = estimated_total_etb(rate, quantity)
    run_at = delayed_run_at_iso(merged["delay_minutes"])
    confirm_id = uuid.uuid4().hex[:12]
    DELAYED_DRAFT.pop(user.id, None)
    PENDING_DELAYED[confirm_id] = {
        "user_id": user.id,
        "service": service,
        "link": merged["link"],
        "quantity": quantity,
        "total": total,
        "run_at": run_at,
        "idempotency_key": "delay-" + uuid.uuid4().hex[:16],
    }
    # Confirm card: always text — it carries the Confirm buttons.
    await reply_message(
        update.message,
        _delayed_confirm_text(
            lang, service, quantity, total, merged["link"], run_at,
        ),
        lang,
        reply_markup=confirm_keyboard(confirm_id),
    )


def deposit_method_again_keyboard(method, lang):
    """"✅ Telebirr again" / "Use a different method" (23, 15 Nov
    2026). Callback data "depagain:<method>" / "depdiff". The
    method label comes from METHOD_LABELS ("cbe" is CBE Birr);
    unknown methods (mpesa, cbebirr — not in chat yet) show their
    slug capitalised, never a raw code."""
    label = METHOD_LABELS.get(method, str(method).capitalize())
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(
            t("deposit_method_again_button", "en", method=label),
            callback_data=f"depagain:{method}",
        )],
        [InlineKeyboardButton(
            t("deposit_method_other_button", "en"),
            callback_data="depdiff",
        )],
    ])


async def _remembered_deposit_method(user_id: int):
    """The user's last successful deposit method, or None. The
    in-memory traits mirror first (loaded at session restore);
    the server when the mirror is empty. Only the four methods
    the deposit flow knows; anything else is not a method. Never
    raises — a 404 (endpoint not live yet) is just "nothing
    remembered"."""
    entry = USER_TRAITS.get(int(user_id)) or {}
    method = entry.get("last_deposit_method")
    if method in ("telebirr", "cbe", "cbebirr", "mpesa"):
        return method
    try:
        traits = await paxyo.load_traits(user_id)
    except Exception as exc:
        log.warning("deposit method traits load failed: %s", exc)
        return None
    if not isinstance(traits, dict):
        return None
    method = traits.get("last_deposit_method")
    if method in ("telebirr", "cbe", "cbebirr", "mpesa"):
        # Fill the mirror so the next deposit in this process does
        # not re-fetch.
        _traits_entry(user_id)["last_deposit_method"] = method
        return method
    return None


async def _continue_parked_draft(message, user_id, lang, voice=False):
    """Resume a parked order draft (deposit-hijack fix, 16 Nov
    2026): the draft is back in PARTIAL; ask the next missing
    piece, or show the Confirm card when it is complete."""
    draft = PARTIAL.get(user_id) or {}
    if draft.get("link") and draft.get("quantity"):
        await complete_order(message, user_id, dict(draft), lang, voice=voice)
        return
    if draft.get("link"):
        await reply_message(message, t("ask_quantity", lang), lang, voice=voice)
        return
    if draft.get("platform") or draft.get("service_hint"):
        await reply_message(
            message,
            ask_link_text(draft.get("platform"), draft.get("service_hint"), lang),
            lang, voice=voice,
        )
        return
    await reply_message(message, t("ask_platform", lang), lang, voice=voice)


# Deposit guide image (19 Nov 2026): the how-to-pay photo shipped
# with the repo, so the bot can send it from its own files — no
# hosting and no file_id step needed. The file rides along with
# the Fly deploy like the rest of the repo.
DEPOSIT_GUIDE_IMAGE = os.path.join(
    os.path.dirname(os.path.abspath(__file__)),
    "assets", "how_to_pay_paxyo_deposit.png",
)


async def successful_deposits_count(user_id: int):
    """Number of the user's completed deposits (19 Nov 2026):
    GET /deposits, counting status completed/success/paid. The
    list endpoint already exists server-side (api-deposits.php)
    and returns the status per deposit — no new server endpoint
    is needed. Returns None when the count cannot be read (the
    endpoint is not live yet, or a read error): the caller then
    shows the old deposit card, so a read failure never blocks
    a deposit."""
    try:
        deposits = await paxyo.list_deposits(user_id, limit=100)
    except Exception as exc:
        log.warning("successful deposits count failed: %s", exc)
        return None
    if deposits is None:
        return None
    return sum(
        1 for dep in deposits
        if isinstance(dep, dict)
        and str(dep.get("status") or "").strip().lower()
        in ("completed", "success", "paid")
    )


async def send_deposit_guide(message, amount, lang: str):
    """Deposit guide card for a user with fewer than 3 successful
    deposits (owner, 19 Nov 2026): the how-to-pay photo plus the
    steps, with a Deposit now button that continues to the
    Confirm card. Nothing is created on the server here — the
    guide only teaches; the deposit starts at Confirm, as
    before. The photo is best-effort: a missing file or a failed
    send still sends the text and button, so the deposit flow
    never breaks on an image."""
    text = t("deposit_guide", lang, amount=format_money(amount))
    markup = InlineKeyboardMarkup([[
        InlineKeyboardButton(
            t("deposit_guide_button", lang), callback_data="depguide"
        ),
    ]])
    try:
        with open(DEPOSIT_GUIDE_IMAGE, "rb") as fh:
            photo = fh.read()
    except Exception as exc:
        log.warning("deposit guide image missing: %s", exc)
        photo = None
    if photo:
        try:
            await message.reply_photo(
                photo=InputFile(
                    io.BytesIO(photo),
                    filename="how-to-pay-paxyo-deposit.png",
                ),
                caption=text,
                reply_markup=markup,
            )
            return
        except Exception as exc:
            log.warning("deposit guide photo failed: %s", exc)
    await message.reply_text(text, reply_markup=markup)


def deposit_confirm_card(user_id: int, amount, lang: str):
    """(text, markup) for a deposit Confirm card (owner, 17 Nov
    2026): the amount ONLY — the method + phone are chosen on the
    popup page after Confirm, never in chat. Registers the card in
    PENDING_DEPOSIT (amount only) and in DEPOSIT_ABANDONED (so a
    card never tapped gets one Resume nudge after 3 quiet hours).
    Nothing is created on the server until the user taps Confirm
    (or says yes)."""
    import time

    confirm_id = uuid.uuid4().hex[:12]
    PENDING_DEPOSIT[confirm_id] = {
        "user_id": user_id,
        "amount": amount,
    }
    DEPOSIT_ABANDONED[user_id] = {
        "confirm_id": confirm_id,
        "amount": amount,
        "started_at": time.time(),
        "nudged_at": None,
    }
    lines = [
        t("confirm_title", lang),
        "",
        f"💰 {format_money(amount)} ETB",
    ]
    # A validated promo code shows on the card, so the user sees
    # the bonus will apply before they confirm (ideas batch 2,
    # feature 1, 15 Nov 2026). The code itself is only attached
    # when the deposit is created (start_deposit).
    _validated = VALIDATED_PROMO.get(user_id) or {}
    if _validated.get("code"):
        lines.append(
            t(
                "deposit_confirm_promo", lang,
                code=_validated["code"],
                percent=(
                    _validated["percent"]
                    if _validated.get("percent") is not None
                    else "?"
                ),
            )
        )
    return _strip_dashes("\n".join(lines)), confirm_keyboard(confirm_id)


async def handle_deposit_text(update, text, intent, lang, voice=False):
    """Build a deposit (amount only, owner, 17 Nov 2026), then
    show a Confirm summary. The method + phone are never asked
    in chat — the user picks them on the deposit popup page after
    Confirm. Nothing is created on the server until the user taps
    Confirm (or says yes): money must never move on a
    misunderstood message. The server creates the deposit and
    credits the balance only after Chapa confirms the payment;
    the bot never credits anything itself."""
    user = update.effective_user
    # Deposit-hijack fix (16 Nov 2026): the deposit flow starts
    # here, so an open order draft is parked first (saved, not
    # lost) — a number the user then sends is the deposit amount,
    # never an order quantity. Only on flow start: later turns
    # find DEPOSIT_DRAFT already open and park nothing. A bundle
    # draft is dropped (ideas batch 1 #3): it has no parked resume.
    if not DEPOSIT_DRAFT.get(user.id) and _park_order_draft(user.id):
        await reply_message(
            update.message, t("draft_parked", lang), lang, voice=voice,
        )
    if not DEPOSIT_DRAFT.get(user.id):
        BUNDLE_DRAFT.pop(user.id, None)
    stored = DEPOSIT_DRAFT.get(user.id) or {}
    amount = intent.get("amount")
    try:
        amount = float(amount) if amount is not None else None
    except (TypeError, ValueError):
        amount = None
    if amount is None:
        amount = parse_deposit_amount(text)
    if amount is None:
        amount = stored.get("amount")
    # A method or phone typed along with the amount ("deposit 10
    # by telebirr, phone 09...") is deliberately ignored: the
    # user picks both on the popup page after Confirm, so the
    # chat never asks for them and never repeats them.
    if amount is not None and (amount <= 0 or amount > MAX_DEPOSIT_ETB):
        DEPOSIT_DRAFT[user.id] = {}
        await reply_message(update.message, t("deposit_too_big", lang), lang, voice=voice)
        return
    if amount is None:
        DEPOSIT_DRAFT[user.id] = {}
        await reply_message(update.message, t("ask_deposit_amount", lang), lang, voice=voice)
        return
    # Complete: Confirm card (amount only), always text — it
    # carries the buttons.
    DEPOSIT_DRAFT.pop(user.id, None)
    DEPOSIT_METHOD_DECLINED.discard(user.id)
    PARTIAL.pop(user.id, None)
    RECURRING_DRAFT.pop(user.id, None)
    # Deposit guide (owner, 19 Nov 2026): until the user has 3
    # successful deposits, show the how-to-pay guide instead of
    # the old card. The amount is kept in DEPOSIT_DRAFT so the
    # guide's Deposit now button can continue to the Confirm
    # card. A count that cannot be read shows the old card, so
    # the guide never blocks a deposit.
    count = await successful_deposits_count(user.id)
    if count is not None and count < 3:
        DEPOSIT_DRAFT[user.id] = {"amount": amount}
        await send_deposit_guide(update.message, amount, lang)
        return
    card_text, card_markup = deposit_confirm_card(user.id, amount, lang)
    await reply_message(
        update.message, card_text, lang,
        reply_markup=card_markup,
    )


async def _low_balance_shortfall(user_id: int, service, total: float):
    """(shortfall, balance) in ETB when the user's Paxyo balance is
    below this order's total, else None. ANY order counts, not only
    the user's usual: the live test on 15 Nov 2026 showed the
    usual-only gate silently hid the warning whenever the bot's
    in-memory traits were wiped by a deploy (traits only survive a
    restart once the server traits endpoint is installed), so a
    user ordering something new and unaffordable got no warning at
    all. A balance that covers the total, or a balance that cannot
    be read, returns None. The warning never blocks the order —
    the caller shows it and still shows the Confirm card."""
    user_id = int(user_id)
    try:
        bal = await paxyo.balance(user_id)
    except Exception as exc:
        log.warning("low-balance check failed: %s", exc)
        return None
    if not bal.get("found"):
        return None
    try:
        balance = float(bal.get("balance", 0))
    except (TypeError, ValueError):
        return None
    if balance >= total:
        return None
    return (round(total - balance, 2), balance)


def _prefer_pick(picks, user_id):
    """The pick to use from an ordered candidate list: a favourite
    service (#21) first when one is among the picks, else a
    service with no claimed time when try-new (#40) is on, else
    the first pick (the picker's own order — fastest or cheapest
    first). A favourite is matched by bare service id, on either
    side of a combined id."""
    favourites = get_pref(user_id, "pref_favourite_services") or []
    if favourites:
        for pick in picks:
            bare = str(pick.get("service"))
            combined_bare = str(
                (pick.get("combined_id") or "").split(":")[-1]
            )
            if bare in favourites or combined_bare in favourites:
                return pick
    if get_pref(user_id, "pref_try_new"):
        for pick in picks:
            if parse_average_time(pick.get("average_time")) is None:
                return pick
    return picks[0]


async def _weekly_spent_etb(user_id, now=None):
    """ETB spent on orders in the last 7 days (#25), from the
    server order history (charge/total + created_at). A row with
    no date counts (it cannot be proven old); unparseable rows
    are skipped; a failed fetch counts as 0, so the limit never
    blocks an order on a read error."""
    now = (now or datetime.now(EAT_TZ)).astimezone(EAT_TZ)
    try:
        orders = await paxyo.recent_orders(user_id, limit=100) or []
    except Exception as exc:
        log.warning("weekly spent orders failed: %s", exc)
        return 0.0
    spent = 0.0
    week_ago = now - timedelta(days=7)
    for order in orders:
        if not isinstance(order, dict):
            continue
        created = _parse_order_created_at(order.get("created_at"))
        if created is not None and created < week_ago:
            continue
        try:
            spent += float(
                order.get("charge", order.get("total")) or 0
            )
        except (TypeError, ValueError):
            continue
    return spent


async def _balance_alert_line(user_id):
    """The low-balance alert line (#24) when the balance is below
    the level the customer set, else None. A balance that cannot
    be read returns None — no warning on a read error."""
    threshold = get_pref(user_id, "pref_low_balance_alert_etb")
    if threshold is None:
        return None
    try:
        bal = await paxyo.balance(user_id)
    except Exception as exc:
        log.warning("low-balance alert check failed: %s", exc)
        return None
    if not bal.get("found"):
        return None
    try:
        balance = float(bal.get("balance", 0))
    except (TypeError, ValueError):
        return None
    if balance >= threshold:
        return None
    return (
        f"Your balance is {format_money(balance)} ETB — below the "
        f"{format_money(threshold)} ETB alert you set."
    )


async def complete_order(message, user_id, merged, lang, voice=False,
                         named_service_id=None, last_service_id=None,
                         note: str = None, ask_metric: bool = True,
                         show_full_name: bool = False):
    """Fetch services, pick/validate the service, show the Confirm card.

    The order being built stays in PARTIAL until the card is shown,
    then it lives in PENDING. Returns True when the Confirm card was
    shown. A service the user named by ID is used as-is (validated:
    it must exist, be active and not be blacklisted); a bad named
    service is refused in one line with a one-tap "Use the fastest
    one" button, and the order stays in PARTIAL. Otherwise the
    fastest service is picked as before — including the last order's
    service for "order on that link again". A blacklisted service is
    never used, whichever path picked it. `note` is a one-line
    warning on the card (a quantity change, a doubled usual, a
    risky link, a handle to double-check). When no metric was named
    and the fastest services are different kinds (views vs likes
    vs comments), the bot asks which kind instead of silently
    picking the wrong one — the order stays in PARTIAL, so the
    answer completes it. `ask_metric=False` skips that question
    (the "Use the fastest one" button: the user already chose).
    """
    PARTIAL[user_id] = {k: v for k, v in merged.items() if v is not None}
    # A complete order was built (and is about to be confirmed or
    # placed): the cancelled draft is history now.
    CANCELLED_DRAFT.pop(user_id, None)
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("services fetch failed: %s", exc)
        await reply_message(message, t("not_understood", lang), lang, voice=voice)
        return False

    service = None
    # Cancel-cutting item 2 (16 Nov 2026): a service the user
    # chose themselves (named by ID, pinned, or the last order's)
    # is never silently swapped when it is auto-paused — the
    # pause check below the pick needs to know the pick was
    # theirs, not the bot's.
    _user_chosen_service = False
    if named_service_id is not None:
        service, svc_error = resolve_named_service(services, named_service_id)
        if svc_error is not None:
            token = uuid.uuid4().hex[:12]
            FASTEST_FALLBACK[token] = {
                "user_id": user_id,
                "merged": {k: v for k, v in merged.items() if v is not None},
            }
            key = {
                "blacklisted": "service_blacklisted",
                "not_found": "service_not_found",
                "disabled": "service_disabled",
            }[svc_error]
            await reply_message(
                message, t(key, lang), lang, voice=voice,
                reply_markup=fastest_fallback_keyboard(token, lang),
            )
            return False
        _user_chosen_service = True
    # First-order nudge pin (ideas batch, 15 Nov 2026): the user
    # tapped "Start a test order", so THIS order pins the cheapest
    # views service instead of the fastest pick. One-shot, and only
    # when this order is for the same platform and metric as the
    # nudge, the service is still active and not blacklisted, and
    # the user did not name a service by ID — an abandoned nudge
    # never hijacks a different order. Consumed here either way.
    # The learned usual (feature 5, 15 Nov 2026) pins the same
    # way when there is no nudge pin: a "same as usual" fallback
    # with no recent order still lands on the usual service.
    pinned = NUDGE_SERVICE.pop(user_id, None)
    if pinned is None:
        pinned = USUAL_SERVICE.pop(user_id, None)
    if pinned is not None and service is None and named_service_id is None:
        pin = find_service_by_id(services, pinned)
        if pin is not None and pin.get("active", True):
            try:
                # The blacklist is a GOP list (second
                # provider, 15 Nov 2026): it never excludes an SMM
                # service that happens to share the number.
                usable = (
                    int(pin.get("service", 0)) not in BLACKLISTED_SERVICES
                    or service_provider(pin) == "smm"
                )
            except (TypeError, ValueError):
                usable = False
            if usable:
                pin_platform, _ = _platform_hint_of_service(pin)
                pin_metric = _primary_metric(
                    " ".join(_name_kinds(pin.get("name")))
                )
                if (
                    pin_platform == merged.get("platform")
                    and pin_metric is not None
                    and pin_metric in _name_kinds(merged.get("service_hint") or "")
                ):
                    service = pin
                    _user_chosen_service = True
    # Quoted-service pin (19:28 EAT 16 Nov 2026, live fault): the
    # Confirm card must show the service whose price was quoted in
    # the chat just before this order — a user quoted 1.6 ETB was
    # handed a 1,118.04 ETB traffic service. One-shot, only when
    # this order is for the same platform and metric as the quote,
    # and only when the quoted service is still orderable (in the
    # catalogue, active, not blacklisted, not auto-paused, quantity
    # within min/max). The quote is consumed only when it matches
    # this order — an order for something else leaves it alone.
    # When the quoted service cannot be ordered, the automatic pick
    # below runs and the card carries a plain note naming the quoted
    # service and the replacement — never a silent swap. A quantity
    # that is not a multiple of 10 is the user's number to fix, not
    # a reason to drop the pin (any service would refuse it).
    _quoted_note = None
    _quoted = QUOTED_SERVICE.get(user_id)
    if (
        _quoted is not None and service is None
        and named_service_id is None
        and _quoted.get("platform")
        and _quoted.get("platform") == merged.get("platform")
        and _quoted.get("metric")
        and kind_from_text(merged.get("service_hint") or "") == _quoted["metric"]
    ):
        QUOTED_SERVICE.pop(user_id, None)
        _q = find_service_by_id(services, _quoted["combined_id"])
        _q_reason = None
        if _q is None or not _q.get("active", True):
            _q_reason = "unavailable"
        else:
            # Identity check (16 Nov 2026): the pin stores only a
            # combined id, and ids are only unique inside one
            # catalogue — a quote remembered from another list must
            # never pin a different service that happens to share
            # the number (test fault: a TikTok views quote pinned
            # Telegram Channel Members #2001). The resolved service
            # must BE the quoted one: same platform, same metric,
            # same price — otherwise the pin is dropped and the
            # automatic pick below runs with a note, never a
            # silent swap.
            _q_platform, _ = _platform_hint_of_service(_q)
            try:
                _q_price = float(_q.get("rate_etb_per_1000") or 0)
            except (TypeError, ValueError):
                _q_price = -1.0
            if (
                _q_platform != _quoted.get("platform")
                or _quoted.get("metric") not in _name_kinds(
                    str(_q.get("name") or ""),
                    str(_q.get("category") or ""),
                )
                or abs(_q_price - float(_quoted.get("price") or 0)) > 0.01
            ):
                _q_reason = "unavailable"
            else:
                try:
                    _q_blacklisted = (
                        int(_q.get("service", 0)) in BLACKLISTED_SERVICES
                        and service_provider(_q) == "gop"
                    )
                except (TypeError, ValueError):
                    _q_blacklisted = True
                if _q_blacklisted:
                    _q_reason = "unavailable"
                else:
                    _paused_now = await _cached_paused_services()
                    if (
                        _paused_now is not None
                        and service_combined_id(_q) in _paused_now
                    ):
                        _q_reason = "paused"
                    elif merged.get("quantity") is not None and validate_quantity(
                        merged.get("quantity"), _q
                    ) in ("below_min", "above_max"):
                        _q_reason = "quantity"
        if _q_reason is None:
            service = _q
        else:
            _quoted_note = (_q_reason, _q)
    if (
        service is None
        and last_service_id is not None
        and not merged.get("platform")
        and not merged.get("service_hint")
    ):
        # "Order on that link again": reuse the last order's service —
        # unless it is now blacklisted or turned off, in which case
        # the fastest pick below takes over.
        found = find_service_by_id(services, last_service_id)
        if found is not None and found.get("active", True):
            try:
                usable = int(found.get("service", 0)) not in BLACKLISTED_SERVICES
            except (TypeError, ValueError):
                usable = False
            if usable:
                service = found
                _user_chosen_service = True
    # The pref-filtered pool the automatic pick drew from (None
    # when the service was user-chosen): the same-emoji lower-min
    # offer below must draw from it too, or it could offer a
    # service that breaks the customer's own rule.
    _pick_pool = None
    # Story/post (16 Nov 2026): the pick keys off the link type
    # — a post link never gets a story service. An explicit draft
    # flag (the "not for story" correction) wins over the link.
    _story = _story_flag(
        merged.get("link"), merged.get("service_hint"),
        merged.get("story"),
    )
    if service is None:
        # Rating demotion (ideas batch 2, feature 3, 15 Nov 2026):
        # the fastest pick is demoted by the services' bad ratings
        # (one cached ratings call at most; any failure ranks as
        # today). A named, pinned or last-order service above is
        # never demoted — the user chose it. The Confirm card still
        # shows the picked service + price, unchanged.
        # Per-customer prefs (customizations, 15 Nov 2026): the
        # automatic pick only ever sees services that fit what the
        # customer set (max slowness, price ceiling, refill-only,
        # delivery deadline). A service the user NAMED, or the
        # pinned/last-order service above, is their explicit choice
        # and is not filtered. When every candidate is filtered
        # out, the bot says which setting blocked it and keeps the
        # draft — it never places an order on a service that breaks
        # the customer's own rule. Cheapest-first (#4) rides the
        # picker's own "cheapest" ranking word.
        _deadline = _deadline_from_draft(merged.get("deadline"))
        _pool, _blocked_by = filter_pref_candidates(
            services, user_id, deadline=_deadline,
        )
        _pick_pool = _pool
        if _blocked_by is not None:
            await reply_message(
                message,
                _pref_blocked_text(_blocked_by, user_id),
                lang, voice=voice,
            )
            return False
        _hint = merged.get("service_hint")
        if pref_pick_order(user_id) == "cheapest":
            _hint = ((_hint or "") + " cheapest").strip()
        # Favourites (#21) / try-new (#40): the pick needs more
        # than the top 3 to choose from — fetch 10, prefer from
        # them, and keep the ask-metric question on the top 3.
        _pick_limit = 10 if (
            get_pref(user_id, "pref_favourite_services")
            or get_pref(user_id, "pref_try_new")
        ) else 3
        picks = await pick_services_rated(
            _pool, platform=merged.get("platform"), service_hint=_hint,
            reaction_emoji=merged.get("reaction_emoji"),
            limit=_pick_limit,
            quantity=merged.get("quantity"),
            story=_story,
        )
        if not picks:
            # A specific reaction emoji with no dedicated service:
            # say so honestly (owner, 14 Nov 2026) — never
            # silently sell the Positive mix.
            if merged.get("reaction_emoji") and "reaction" in (merged.get("service_hint") or "").lower():
                await reply_message(
                    message,
                    t("no_exact_reaction", lang, emoji=merged["reaction_emoji"]),
                    lang, voice=voice,
                )
                return False
            await reply_message(
                message,
                no_service_reply(
                    merged.get("platform"), merged.get("service_hint"),
                    merged.get("service_hint") or "", lang,
                ) or t("no_service", lang),
                lang, voice=voice,
            )
            return False
        if ask_metric and not merged.get("service_hint"):
            # No metric was named and the fastest services are
            # different kinds (views vs likes vs comments): ask
            # which kind instead of silently picking the wrong one
            # (13 Nov 2026 — a views order got Comment Likes).
            # When the metric is known (a hint), the fastest pick
            # still applies with no question. Only the top 3
            # decide the question: with favourites / try-new on,
            # the pick list is 10 long, and a 4th-place kind must
            # not force a question.
            metrics = []
            for pick in picks[:3]:
                found = _primary_kind(
                    pick.get("name"), pick.get("category")
                )
                if found and found not in metrics:
                    metrics.append(found)
            if len(metrics) > 1:
                # One-tap "Use the fastest one" (round 7, 13 Nov
                # 2026): until now the button only appeared when a
                # service named by ID was refused, so in two live
                # retests it never appeared at all. It is offered
                # here too, so the user can skip the choice and take
                # the fastest service for the platform.
                _token = uuid.uuid4().hex[:12]
                FASTEST_FALLBACK[_token] = {
                    "user_id": user_id,
                    "merged": {
                        k: v for k, v in merged.items() if v is not None
                    },
                }
                await reply_message(
                    message,
                    t("ask_metric_choose", lang, metrics=", ".join(metrics)),
                    lang, voice=voice,
                    reply_markup=fastest_fallback_keyboard(_token, lang),
                )
                return False
        # Favourites (#21) / try-new (#40): prefer from the (up
        # to 10) picks — a favourite first, else a service with
        # no claimed time, else the picker's first pick.
        service = _prefer_pick(picks, user_id)
    if _user_chosen_service and service is not None:
        # Cancel-cutting item 2 (16 Nov 2026): a service the user
        # chose that is auto-paused right now is never used —
        # say so plainly and offer the fastest one instead, with
        # one tap. The pick path above already skips paused
        # services, so only a user-chosen service can reach here
        # paused. The draft stays in PARTIAL, so tapping the
        # button resumes the same order on the fastest service.
        _paused_now = await _cached_paused_services()
        if (
            _paused_now is not None
            and service_combined_id(service) in _paused_now
        ):
            _token = uuid.uuid4().hex[:12]
            FASTEST_FALLBACK[_token] = {
                "user_id": user_id,
                "merged": {k: v for k, v in merged.items() if v is not None},
            }
            await reply_message(
                message,
                t(
                    "service_paused", lang,
                    service=short_service_name(service.get("name"))
                    or f"service {service.get('service')}",
                ),
                lang, voice=voice,
                reply_markup=fastest_fallback_keyboard(_token, lang),
            )
            return False
    error = validate_quantity(merged.get("quantity"), service)
    if error == "below_min" and merged.get("reaction_emoji"):
        # Screenshot bug (16 Nov 2026): the quantity is below the
        # picked service's minimum — offer the closest SAME-EMOJI
        # service that allows it instead of only rejecting the
        # number. Same platform + same emoji, cheapest first (the
        # emoji pick rule); the first service whose min/max and
        # multiple-of-10 rule fit the quantity wins, and the order
        # continues to the Confirm card on it.
        _rel, _paused, _health = await _pick_context()
        _alts = pick_services(
            _pick_pool if _pick_pool is not None else services,
            platform=merged.get("platform"),
            service_hint=merged.get("service_hint"),
            reaction_emoji=merged.get("reaction_emoji"),
            limit=100,
            reliability=_rel, paused=_paused, balance_health=_health,
            quantity=merged.get("quantity"),
            story=_story,
        )
        for _alt in _alts:
            if validate_quantity(merged.get("quantity"), _alt) is None:
                service = _alt
                error = None
                break
    if error:
        await reply_message(
            message,
            t(
                "bad_quantity",
                lang,
                service=short_service_name(service.get("name")),
                min=service.get("min"),
                max=service.get("max"),
            ),
            lang,
            voice=voice,
        )
        return False

    quantity = int(merged["quantity"])
    rate = float(service.get("rate_etb_per_1000", 0))
    total = estimated_total_etb(rate, quantity)

    # Weekly spending limit (#25): refuse before the card when
    # this order would take the week's spending over the limit
    # the customer set — naming what was spent. The draft stays,
    # so they can change or turn off the limit and try again.
    _weekly_limit = get_pref(user_id, "pref_weekly_spend_limit_etb")
    if _weekly_limit is not None:
        _spent = await _weekly_spent_etb(user_id)
        if _spent + total > _weekly_limit:
            await reply_message(
                message,
                f"You've spent {format_money(_spent)} ETB this week "
                f"and your limit is {format_money(_weekly_limit)} "
                f"ETB — this order ({format_money(total)} ETB) "
                "would take you over it. I kept your order; say "
                "\"turn off the weekly limit\" to change it.",
                lang, voice=voice,
            )
            return False

    # Drip-feed (#15, customizations, 15 Nov 2026): "spread 10000
    # views over 2 days". The provider places ONE order with
    # runs/interval — never faked with separate orders. The plan
    # must split evenly (see drip_plan); the service must offer
    # drip-feed; and the server must honour the fields (see
    # dripfeed_live). When any of those fails, the bot says so
    # honestly and keeps the draft — it never silently places a
    # normal order for a drip request.
    drip = None
    span = merged.get("drip_span")
    deadline = _deadline_from_draft(merged.get("deadline"))
    if span is not None:
        # A probe failure is "not live", never silence (19 Nov
        # 2026: the unwrapped probe raised and the turn got no
        # reply at all).
        try:
            _drip_live = await paxyo.dripfeed_live()
        except Exception:
            _drip_live = False
        if not _drip_live:
            await reply_message(
                message,
                "Drip-feed isn't set up on the server yet, so I "
                "can't spread this order. I can place it normally, "
                "or repeat it on a schedule instead — say \"place "
                "it normally\" or \"repeat it every day\".",
                lang, voice=voice,
            )
            return False
        if service.get("dripfeed") is False:
            await reply_message(
                message,
                "This service doesn't offer drip-feed, so I can't "
                "spread the order on it. Say \"place it normally\" "
                "to order it all at once, or pick another service.",
                lang, voice=voice,
            )
            return False
        drip = drip_plan(quantity, service, span)
        if drip is None:
            await reply_message(
                message,
                f"I can't spread {quantity:,} evenly over "
                f"{format_interval(span)} on this service — the "
                "runs would be too small or uneven. Try a quantity "
                "that splits evenly, like a round number, or a "
                "longer time.",
                lang, voice=voice,
            )
            return False

    # Low-balance warning (15 Nov 2026, feature 1): the user's
    # usual service, and the balance is short of the total. The
    # warning goes out BEFORE the Confirm card, names the exact
    # shortfall, and carries a one-tap deposit button for exactly
    # that shortfall (callback "depshort:<amount>" — it pre-fills
    # the deposit flow's amount, then asks for method and phone).
    # The Confirm card is still shown below it: the user can still
    # confirm and place the order.
    _shortfall = await _low_balance_shortfall(user_id, service, total)
    if _shortfall is not None:
        _short_amount, _balance = _shortfall
        await reply_message(
            message,
            t(
                "low_balance_warning", lang,
                balance=format_money(_balance),
                shortfall=format_money(_short_amount),
                total=format_money(total),
            ),
            lang, voice=voice,
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton(
                    t("deposit_webapp_button", lang,
                      amount=format_money(_short_amount)),
                    callback_data=f"depshort:{_short_amount:.2f}",
                )
            ]]),
        )

    # Low balance alert (#24): no shortfall, but the balance is
    # below the level the customer set — a note on the card, not
    # a block. Only when the alert is set.
    _alert_line = None
    if _shortfall is None:
        _alert_line = await _balance_alert_line(user_id)

    confirm_id = uuid.uuid4().hex[:12]
    PARTIAL.pop(user_id, None)  # the order now lives in PENDING
    BUDGET_OPTIONS.pop(user_id, None)  # a budget choice is spent now
    DEPOSIT_DRAFT.pop(user_id, None)  # a half-built deposit is stale now
    _pending_entry = {
        "user_id": user_id,
        "service": service,
        "link": merged["link"],
        "quantity": quantity,
        "total": total,
        "full_name": show_full_name,
        # Draft context, so a link-check refusal (item 5) can
        # restore the order the user was building: platform,
        # metric, reaction emoji and quantity ride along.
        "platform": merged.get("platform"),
        "service_hint": merged.get("service_hint"),
        "reaction_emoji": merged.get("reaction_emoji"),
    }
    if drip is not None:
        _pending_entry["drip"] = {
            "runs": drip[0],
            "interval": drip[1],
            "per_run_qty": drip[2],
            "span_min": span,
        }
    if deadline is not None:
        _pending_entry["deadline"] = deadline.isoformat()
    # Card notes: the drip plan and the deadline, on top of the
    # existing note (a quantity change, a doubled usual, a risky
    # link). The card is the one place the customer SEES the drip
    # plan before anything is placed.
    _card_notes = []
    if note:
        _card_notes.append(note)
    if _quoted_note is not None:
        # Quoted-service re-quote (19:28 EAT 16 Nov 2026): the
        # service whose price was quoted cannot be ordered after
        # all — the card says so plainly and names the replacement
        # + its price, never silently swapping.
        _q_reason, _q = _quoted_note
        _q_name = (
            short_service_name(_q.get("name"))
            if _q is not None else "that service"
        ) or "that service"
        if _q_reason == "quantity" and _q is not None:
            _reason = t(
                "quoted_quantity", lang,
                min=_q.get("min"), max=_q.get("max"),
            )
        else:
            _reason = t(f"quoted_{_q_reason}", lang)
        _card_notes.append(t(
            "quoted_service_changed", lang,
            service=_q_name, reason=_reason,
            replacement=short_service_name(service.get("name")),
            price=format_money(rate),
        ))
    if _alert_line is not None:
        _card_notes.append(_alert_line)
    if drip is not None:
        _card_notes.append(
            f"Drip-feed: {drip[0]} runs of {drip[2]:,} every "
            f"{format_interval(drip[1])} "
            f"({format_interval(span)} total)."
        )
    if deadline is not None:
        _card_notes.append(
            "Needed by "
            f"{deadline.astimezone(EAT_TZ).strftime('%A %H:%M')} EAT."
        )
    _card_note = "\n".join(_card_notes) if _card_notes else None
    # Place small orders without asking (#18): explicit opt-in
    # only, small orders only (the customer's cap, at most 100
    # ETB), and never for a drip order — a drip plan must be shown
    # on the card first. The order is placed now, no Confirm card;
    # the summary says so.
    _allowed, _cap = pref_no_confirm_cap(user_id)
    if _allowed and drip is None and total <= _cap:
        _pending_entry["no_confirm"] = True
        PENDING[confirm_id] = _pending_entry
        await send_order_result(message, lang, _pending_entry, user_id)
        PENDING.pop(confirm_id, None)
        return True
    PENDING[confirm_id] = _pending_entry
    # Confirm card: always text — a voice message cannot carry buttons.
    _sent = await reply_message(
        message,
        confirm_card_text(lang, service, quantity, total, merged["link"],
                          note=_card_note, full_name=show_full_name),
        lang,
        reply_markup=confirm_keyboard(confirm_id),
    )
    _remember_card_message(_pending_entry, message, _sent)
    return True


# ------------------------------------------- edge-case handlers ------
# Messy real-world inputs (owner spec, 13 Nov 2026). Each handler
# answers one kind of messy message and either shows a Confirm card
# (never placing anything itself) or a one-line answer. Prices always
# come from the server's service list — never from the user's words.

async def _usual_fallback(update, user_id: int, intent: dict, lang: str,
                          voice: bool = False) -> bool:
    """'Give me the usual' with no recent order on the server:
    fall back to the LEARNED usuals (feature 5, 15 Nov 2026).
    Pre-fills the draft with the usual platform + metric +
    quantity, pins the usual service (one-shot, like the
    first-order nudge pin), and asks for the link — the user still
    confirms before anything is placed. Only when the usual is
    established: the same platform+metric placed at least twice,
    or loaded from the server. A one-off order never becomes the
    "usual". Returns True when the fallback applied, False when
    there is no established usual to fall back to."""
    user_id = int(user_id)
    if not _usual_is_established(user_id):
        return False
    traits = USER_TRAITS.get(user_id) or {}
    # The stored usual may be a combined id ("smm:7501", second
    # provider, 15 Nov 2026) or an old bare int (GOP).
    raw_usual = traits.get("usual_service_id")
    if isinstance(raw_usual, str) and ":" in raw_usual:
        service_id = raw_usual
    else:
        try:
            service_id = int(raw_usual or 0) or None
        except (TypeError, ValueError):
            service_id = None
    platform = traits.get("usual_platform")
    metric = traits.get("usual_metric")
    if not service_id or not platform or not metric:
        return False
    quantity = traits.get("usual_quantity")
    try:
        quantity = int(quantity) if quantity is not None else None
    except (TypeError, ValueError):
        quantity = None
    # An explicit quantity in the same message wins, like the
    # last-order path ("same as usual but 2000"); a multiplier
    # ("double it") scales the usual quantity the same way.
    explicit = intent.get("quantity")
    try:
        explicit = int(explicit) if explicit is not None else None
    except (TypeError, ValueError):
        explicit = None
    if explicit is not None:
        quantity = explicit
    else:
        multiplier = intent.get("quantity_multiplier")
        try:
            multiplier = float(multiplier) if multiplier is not None else 1
        except (TypeError, ValueError):
            multiplier = 1
        if quantity is not None and multiplier != 1:
            quantity = int(quantity * multiplier)
    metric_words = str(metric).replace("_", " ")
    service_hint = f"{platform} {metric_words}"
    PARTIAL[user_id] = {
        k: v for k, v in {
            "platform": platform,
            "service_hint": service_hint,
            "quantity": quantity,
        }.items() if v is not None
    }
    USUAL_SERVICE[user_id] = service_id
    # Name the usual service in the reply when the catalogue has
    # it; otherwise the platform + metric words stand on their own.
    name = service_hint
    try:
        services = await paxyo.services()
        found = find_service_by_id(services, service_id)
        if found is not None:
            name = short_service_name(found.get("name"))
    except Exception as exc:
        log.warning("usual fallback service lookup failed: %s", exc)
    if quantity is not None:
        line = t("usual_from_memory", lang, service=name, quantity=quantity)
    else:
        line = t("usual_from_memory_no_qty", lang, service=name)
    await reply_message(
        update.message,
        line + "\n" + ask_link_text(platform, service_hint, lang),
        lang, voice=voice,
    )
    return True


# ------------------------------------------------------- round 3 (15 Nov 2026) ---
# Features 11, 12, 13, 22, 23, 30. Each one is small, deterministic
# and offline-tested; money steps stay in deterministic code and
# every order/refund still needs a Confirm step.

_PLATFORM_DISPLAY = {
    "tiktok": "TikTok", "instagram": "Instagram",
    "telegram": "Telegram", "youtube": "YouTube",
    "facebook": "Facebook", "x": "X",
}


def is_browse_services_request(text: str) -> bool:
    """True when the user asks to BROWSE services ("show me TikTok
    followers services", "list telegram views services", "what
    services do you have for Instagram followers"). Needs a
    browse verb + the word "service(s)". An order ("order 1000
    TikTok views") never matches — it has no browse verb — and a
    price question ("how much is TikTok views") has no "service"
    word, so it keeps its own fast path."""
    s = " ".join((text or "").strip().lower().split())
    if "service" not in s and "services" not in s:
        return False
    if re.search(r"\b(show|list|browse|see)\b", s):
        return True
    return s.startswith("what ") and "service" in s


def _browse_label(platform, metric):
    """Display label for a browse list ("TikTok Followers")."""
    parts = []
    if platform:
        parts.append(_PLATFORM_DISPLAY.get(platform, platform.title()))
    if metric:
        parts.append(metric.title())
    return " ".join(parts) or "Services"


def _browse_page_text(entry, page: int) -> str:
    """One page of the browse list: numbered services with the
    price per 1000 in ETB, fastest first (the stored order)."""
    services = entry["services"]
    total = len(services)
    start = page * BROWSE_PAGE_SIZE
    page_items = services[start:start + BROWSE_PAGE_SIZE]
    lines = [f"{entry['label']} services (fastest first):"]
    for i, s in enumerate(page_items, start + 1):
        lines.append(
            f"{i}. {short_service_name(s.get('name'))}, "
            f"{format_money(s.get('rate_etb_per_1000', 0))} ETB/1000"
        )
    if total > BROWSE_PAGE_SIZE:
        pages = (total + BROWSE_PAGE_SIZE - 1) // BROWSE_PAGE_SIZE
        lines.append(f"Page {page + 1} of {pages}")
    return "\n".join(lines)


def _browse_keyboard(entry, page: int):
    """One button per service on the page (tap to order it) plus
    Next when more pages follow. Callback data is
    "browse:<combined id>" ("browse:smm:7501", second provider,
    15 Nov 2026 — a bare id could not tell the providers apart)
    / "browsepage:<n>"."""
    services = entry["services"]
    start = page * BROWSE_PAGE_SIZE
    page_items = services[start:start + BROWSE_PAGE_SIZE]
    buttons = []
    for s in page_items:
        try:
            sid = int(s.get("service"))
        except (TypeError, ValueError):
            continue
        name = short_service_name(s.get("name")) or f"service {sid}"
        price = format_money(s.get("rate_etb_per_1000", 0))
        buttons.append([InlineKeyboardButton(
            f"{name[:28]}: {price}",
            callback_data=f"browse:{service_combined_id(s)}",
        )])
    total_pages = (len(services) + BROWSE_PAGE_SIZE - 1) // BROWSE_PAGE_SIZE
    if page + 1 < total_pages:
        buttons.append([InlineKeyboardButton(
            t("browse_next_button", "en"),
            callback_data=f"browsepage:{page + 1}",
        )])
    return InlineKeyboardMarkup(buttons) if buttons else None


async def handle_browse_services(update, text, lang, voice=False):
    """List the matching services in chat, fastest first, 10 per
    page. A platform with no metric lists every service of that
    platform; no platform or metric at all asks which platform
    instead of dumping the whole 7,000-service catalogue. Prices
    come from the catalogue (rate x 420), never from the AI. A
    "cheapest" hint ranks by price, like the cheapest questions
    do — the list is otherwise fastest first."""
    user = update.effective_user
    platform, metric = detect_platform_metric(text)
    if platform and metric:
        hint = f"{platform} {metric}"
    elif platform:
        hint = platform
    elif metric:
        hint = metric
    else:
        await reply_message(
            update.message, t("ask_platform", lang), lang, voice=voice,
        )
        return
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("browse services failed: %s", exc)
        await reply_message(
            update.message, t("not_understood", lang), lang, voice=voice,
        )
        return
    picks = pick_services(
        services or [], platform=platform, service_hint=hint, limit=1000,
    )
    label = _browse_label(platform, metric)
    if not picks:
        await reply_message(
            update.message,
            t("browse_empty", lang, label=label), lang, voice=voice,
        )
        return
    entry = {"services": picks, "page": 0, "label": label}
    BROWSE_LISTS[user.id] = entry
    await reply_message(
        update.message, _browse_page_text(entry, 0), lang, voice=voice,
        reply_markup=_browse_keyboard(entry, 0),
    )


def parse_cancel_order_request(text):
    """The placed order a cancel message names, or None. "cancel
    order #1841" / "cancel 1841" -> 1841; "cancel my last order"
    / "cancel the latest order" -> "last". A bare "cancel my
    order" (no id, no "last") is None — the normal cancel flow
    owns it. The order-id reading reuses extract_report_order_id,
    so "cancel order 10k views" is a quantity, never an order id."""
    s = " ".join((text or "").strip().lower().split())
    if not s.startswith("cancel"):
        return None
    if re.search(r"\b(?:last|latest)\s+order\b", s):
        return "last"
    order_id = extract_report_order_id(text)
    if order_id is not None:
        return order_id
    match = re.search(r"cancel\s+#?\s*(\d+)", s)
    if match:
        rest = s[match.end():].strip()
        if rest:
            first = re.split(r"[\s,.!?]+", rest)[0]
            if first in _REPORT_METRIC_WORDS:
                return None
        return int(match.group(1))
    return None


def pending_cancel_for_user(user_id: int):
    """(confirm_id, entry) of the user's most recent order-cancel
    awaiting Confirm, or (None, None)."""
    for confirm_id, entry in reversed(list(PENDING_CANCEL.items())):
        if entry["user_id"] == user_id:
            return confirm_id, entry
    return None, None


async def handle_cancel_order_text(update, text, target, lang,
                                   voice=False):
    """"Cancel my last order" / "cancel order #1841": show the
    placed order with a Confirm card. Only while the provider
    still allows cancelling — an already completed / cancelled /
    failed order gets an honest line, never a card. The card
    carries the full stored total, which is what the refund pays
    back. One cancel card at a time: an older one is dropped
    first. Nothing is cancelled here — the Confirm tap (or a bare
    "yes") runs _run_cancel_order_confirm."""
    user = update.effective_user
    _cid, _old = pending_cancel_for_user(user.id)
    if _cid is not None:
        PENDING_CANCEL.pop(_cid, None)
    order = None
    if target == "last":
        order = await resolve_last_order(user.id)
        if not order:
            await reply_message(
                update.message, t("cancel_order_no_orders", lang),
                lang, voice=voice,
            )
            return
        order_id = order.get("id") or order.get("order_id")
        if not order_id:
            await reply_message(
                update.message, t("cancel_order_no_orders", lang),
                lang, voice=voice,
            )
            return
    else:
        order_id = target
        try:
            data = await paxyo.order_status(order_id, user.id)
        except Exception as exc:
            log.warning("cancel order status failed: %s", exc)
            await reply_message(
                update.message, t("not_understood", lang),
                lang, voice=voice,
            )
            return
        if not data:
            await reply_message(
                update.message,
                t("cancel_order_not_found", lang, order_id=order_id),
                lang, voice=voice,
            )
            return
        order = data.get("order", data) if isinstance(data, dict) else {}
        if not isinstance(order, dict):
            order = {}
        order["id"] = order.get("id") or order.get("order_id") or order_id
    status = str((order or {}).get("status") or "").strip().lower()
    if status in ("completed", "complete", "success", "paid",
                  "cancelled", "canceled", "refunded", "failed"):
        await reply_message(
            update.message,
            t(
                "cancel_order_already_done", lang,
                order_id=order_id, status=status or "completed",
            ),
            lang, voice=voice,
        )
        return
    total = (order or {}).get("total", (order or {}).get("charge"))
    try:
        total = round(float(total), 2) if total is not None else None
    except (TypeError, ValueError):
        total = None
    try:
        quantity = int((order or {}).get("quantity") or 0)
    except (TypeError, ValueError):
        quantity = 0
    name = short_service_name((order or {}).get("service_name")) or (
        f"service {(order or {}).get('service_id')}"
        if (order or {}).get("service_id") else f"order #{order_id}"
    )
    confirm_id = uuid.uuid4().hex[:12]
    PENDING_CANCEL[confirm_id] = {
        "user_id": user.id,
        "order_id": order_id,
        "total": total,
        "service_name": name,
        "quantity": quantity,
    }
    lines = [
        t("confirm_title", lang),
        "",
        t(
            "cancel_order_ask", lang,
            service=name, quantity=quantity,
            total=format_money(total) if total is not None else "?",
            order_id=order_id,
        ),
    ]
    await reply_message(
        update.message, "\n".join(lines), lang,
        reply_markup=confirm_keyboard(confirm_id),
    )


async def _run_cancel_order_confirm(user_id, entry, lang, respond):
    """Run a confirmed order cancel: POST /orders/{id}/cancel,
    then report the refund. `respond` is the reply function
    (query.edit_message_text for a tap, message.reply_text for a
    bare "yes"). Never raises. A None reply (endpoint not live
    yet) says so honestly; an ok:false reply carries the server's
    reason (already completed, provider refused); a success names
    the EXACT refunded figure from the server, falling back to
    the stored total on the card, never an invented figure."""
    order_id = entry["order_id"]
    try:
        result = await paxyo.cancel_order(order_id, user_id)
    except Exception as exc:
        log.warning("cancel order %s failed: %s", order_id, exc)
        await respond(t("cancel_order_failed", lang, order_id=order_id))
        return
    if result is None:
        await respond(t("cancel_order_not_live", lang))
        return
    if isinstance(result, dict) and result.get("ok") is False:
        reason = (result.get("error") or "").strip()
        if reason:
            await respond(t("cancel_order_refused", lang, reason=reason))
        else:
            await respond(
                t("cancel_order_failed", lang, order_id=order_id)
            )
        return
    refunded = None
    if isinstance(result, dict):
        refunded = result.get("refunded_etb")
    if refunded is None:
        refunded = entry.get("total")
    # Cancel-cutting item 4 (16 Nov 2026): the user asked for
    # this cancel themselves, so the order is done — drop it from
    # the watch here, or the next cycle would see the provider
    # word "cancelled" and mistake it for a provider cancel and
    # try to rescue it. (Before this fix the entry was left
    # watched: harmless while "cancelled" was only ever dropped,
    # fatal once a provider cancel is rescued.)
    WATCHED_ORDERS.pop(order_id, None)
    await respond(
        t(
            "cancel_order_done", lang, order_id=order_id,
            refunded=(
                format_money(refunded) if refunded is not None else "?"
            ),
        )
    )


async def _maybe_partial_refund(app, user_id, order_id, quantity):
    """Attempt the partial-delivery refund for one partial order.
    Returns (line, info): the user-facing line, or (None, None)
    when nothing is owed or nothing happened. `info` carries the
    server's exact figures (delivered, remains, refunded_etb,
    quantity) for the top-up check (see _maybe_topup_missing).
    Never raises. A 404 (endpoint not live yet) or a 409/502 (the
    status moved on, or the provider did not confirm) returns
    (None, None) — the caller keeps watching, so a later cycle
    retries instead of refunding on stale data. The refund figure
    is the server's exact figure, never computed here; the
    quantity falls back to delivered + remains when the caller
    does not know it."""
    try:
        result = await paxyo.partial_refund(order_id, user_id)
    except Exception as exc:
        log.warning("partial refund %s failed: %s", order_id, exc)
        return None, None
    if not isinstance(result, dict) or not result.get("ok"):
        return None, None
    try:
        refunded = float(result.get("refunded_etb") or 0)
        delivered = int(result.get("delivered") or 0)
        remains = int(result.get("remains") or 0)
    except (TypeError, ValueError):
        return None, None
    if refunded <= 0 and remains <= 0:
        return None, None
    try:
        qty = int(quantity or 0)
    except (TypeError, ValueError):
        qty = 0
    if qty <= 0:
        qty = delivered + remains
    info = {
        "delivered": delivered,
        "remains": remains,
        "refunded": refunded,
        "quantity": qty,
    }
    return t(
        "partial_refunded", "en",
        order_id=order_id, delivered=delivered, quantity=qty,
        remains=remains, refunded=format_money(refunded),
    ), info


async def _maybe_topup_missing(app, user_id, order_id, watched, info):
    """Top up the missing part (#17, customizations, 15 Nov 2026):
    only part of the order delivered, and the customer set "top up
    the missing part" — order the missing quantity on the SAME
    service, paid from the refunded part, instead of only
    refunding. Returns the user-facing line when a top-up was
    placed, or when it was wanted but too expensive (the
    "refunded instead" line); None when the top-up does not apply
    (remains too small, not a multiple of 10, or the placement
    failed) — the caller then sends the plain refund line.
    Money rule: the top-up costs at most the refunded part, plus
    at most 10% of the confirmed total from Paxyo's pocket — and
    only when the server honours the cover (split_cover_live).
    When the cost exceeds refunded + cover, the refund stands and
    the customer is told so. The top-up is watched like any placed
    order, so it gets its own delivery message. Never raises."""
    service = watched.get("service") or {}
    quantity = int(info.get("quantity") or 0)
    remains = int(info.get("remains") or 0)
    delivered = int(info.get("delivered") or 0)
    refunded = float(info.get("refunded") or 0)
    lang = LAST_LANG.get(user_id, "en")
    if remains <= 0:
        return None
    minimum = _ceil_to_10(_service_min_qty(service))
    if remains < minimum or remains % 10 != 0:
        return None
    cost = estimated_total_etb(
        float(service.get("rate_etb_per_1000") or 0), remains
    )
    confirmed_total = float(
        (watched.get("split") or {}).get("confirmed_total")
        or watched.get("total") or 0
    )
    if confirmed_total <= 0:
        confirmed_total = estimated_total_etb(
            float(service.get("rate_etb_per_1000") or 0), quantity
        )
    cover = 0.0
    if cost > refunded:
        try:
            cover_live = await paxyo.split_cover_live()
        except Exception:
            cover_live = False
        if not cover_live:
            return t(
                "topup_too_expensive", lang,
                ordered=quantity, delivered=delivered,
                missing=remains, cost=format_money(cost),
                refunded=format_money(refunded),
            )
        cover = round(
            min(
                cost - refunded,
                confirmed_total * SPLIT_COVER_MAX_FRACTION,
            ),
            2,
        )
        if cost > refunded + cover:
            return t(
                "topup_too_expensive", lang,
                ordered=quantity, delivered=delivered,
                missing=remains, cost=format_money(cost),
                refunded=format_money(refunded),
            )
    split_kwargs = {}
    if cover > 0:
        split_kwargs = {
            "confirmed_total_etb": float(confirmed_total),
            "paxyo_cover_etb": float(cover),
        }
    try:
        result = await create_order_for_service(
            paxyo, user_id, service, watched.get("link"), remains,
            uuid.uuid4().hex, split=split_kwargs,
        )
    except Exception as exc:
        log.warning("top-up %s failed: %s", order_id, exc)
        return None
    order = result.get("order", result) if isinstance(result, dict) else {}
    new_id = order.get("id") or order.get("order_id") or "?"
    if str(new_id) in ("", "?"):
        return None
    watch_order(
        user_id, new_id, service, remains, watched.get("link"),
        total=cost, deadline=watched.get("deadline"),
    )
    return t(
        "topup_done", lang,
        ordered=quantity, delivered=delivered, missing=remains,
        cost=format_money(cost),
    )


# "Reorder with a different quantity" (22): a reorder phrase plus
# a number. The strong phrases name the last order outright
# ("reorder my last order with 2000 views", "same order but 500",
# "repeat my last order with 1000"); the weak one ("order again
# with 500") only counts when the message names no platform of
# its own — "order again 1000 tiktok views" names TikTok, so it
# stays a normal order instead of silently reusing the last
# order's (possibly different) service. "Same as last time but
# 500" is NOT here: the usual handler already takes it (the
# explicit quantity wins there).
_REORDER_NEW_QTY_RES = (
    (re.compile(
        r"reorder(?:\s+my|\s+the)?\s+(?:last|latest)\s+order"
        r"\s+(?:but\s+|with\s+)?(\d[\d,]*)"
    ), True),
    (re.compile(
        r"same\s+order\s+(?:but\s+|with\s+)?(\d[\d,]*)"
    ), True),
    (re.compile(
        r"repeat(?:\s+my)?\s+(?:last|latest)\s+order"
        r"\s+(?:but\s+|with\s+)?(\d[\d,]*)"
    ), True),
    (re.compile(
        r"order\s+again\s+(?:but\s+|with\s+)?(\d[\d,]*)"
    ), False),
)


def parse_reorder_quantity(text):
    """The new quantity of a "reorder with a different quantity"
    message, or None. Digits only (normalize_text already expanded
    "2k" to "2000" before this runs)."""
    s = " ".join((text or "").strip().lower().split())
    for rx, strong in _REORDER_NEW_QTY_RES:
        match = rx.search(s)
        if not match:
            continue
        if not strong and _explicit_platform_word(text) is not None:
            continue
        try:
            qty = int(match.group(1).replace(",", ""))
        except (TypeError, ValueError):
            continue
        if qty > 0:
            return qty
    return None


async def handle_reorder_new_quantity(update, text, lang, voice=False):
    """"Same as last time but 500" with a reorder phrase: the last
    order's service + link with the NEW quantity, as a Confirm
    card. Mirrors handle_usual (same service pin, same max cap),
    except the quantity is the one the user just named — never
    the last order's. No last order -> an honest line, never a
    guessed service."""
    user = update.effective_user
    wanted = parse_reorder_quantity(text)
    last = await resolve_last_order(user.id)
    if not last or not last.get("link"):
        await reply_message(
            update.message, t("reorder_no_last", lang),
            lang, voice=voice,
        )
        return
    # The server's order list carries the combined id (second
    # provider, 15 Nov 2026) — prefer it, so a reorder of an SMM
    # order re-pins the SMM service, not the GOP service
    # that happens to share the bare number.
    service_id = last.get("combined_id") or last.get("service_id")
    platform = None
    hint = None
    service = None
    capped = False
    if service_id is not None:
        try:
            services = await paxyo.services()
        except Exception as exc:
            log.warning("reorder services failed: %s", exc)
            services = []
        service = find_service_by_id(services or [], service_id)
        if service is not None:
            platform, _hint = _platform_hint_of_service(service)
            metric = _primary_metric(
                " ".join(_name_kinds(service.get("name")))
            )
            if metric:
                hint = f"{platform} {metric}" if platform else metric
            try:
                max_qty = int(service.get("max", 0) or 0)
            except (TypeError, ValueError):
                max_qty = 0
            if max_qty > 0 and wanted > max_qty:
                wanted = (max_qty // 10) * 10
                capped = True
    if platform is None and service_id is None:
        service_name = str(last.get("service_name") or "")
        for p in ("instagram", "tiktok", "telegram", "youtube",
                  "facebook", "x"):
            if p in service_name.lower():
                platform = p
                break
    note = t("change_note", lang, quantity=wanted)
    if capped:
        note = (
            f"{note}\n"
            f"{t('usual_capped', lang, max=max_qty)}"
        )
    merged = {
        "platform": platform,
        "service_hint": hint,
        "link": last.get("link"),
        "quantity": wanted,
    }
    await complete_order(
        update.message, user.id, merged, lang, voice=voice,
        named_service_id=service_id, last_service_id=service_id,
        note=note,
    )


async def handle_usual(update, text, intent, lang, voice=False):
    """'Give me the usual' — the last order as a Confirm card.

    Service + link + quantity come from the most recent order on the
    server. A multiplier ("double it") scales the quantity, capped
    at the service maximum (and the cap is said out loud). No last
    order -> ask what they usually order."""
    user = update.effective_user
    last = await resolve_last_order(user.id)
    if not last or not last.get("link"):
        # No recent order on the server — fall back to the learned
        # usuals (feature 5): the stored usual service + quantity
        # pre-fill the next order, and the bot asks for the link.
        # Only when the usual is established; otherwise the honest
        # "no usual yet" line below.
        if await _usual_fallback(update, user.id, intent, lang, voice=voice):
            return
        await reply_message(update.message, t("no_usual", lang), lang, voice=voice)
        return
    quantity = last.get("quantity")
    try:
        quantity = int(quantity) if quantity is not None else None
    except (TypeError, ValueError):
        quantity = None
    if quantity is None:
        await reply_message(update.message, t("no_usual", lang), lang, voice=voice)
        return
    explicit = intent.get("quantity")
    try:
        explicit = int(explicit) if explicit is not None else None
    except (TypeError, ValueError):
        explicit = None
    if explicit is not None:
        # "same like as usual please order 1k views": the new
        # quantity in the same message wins over the last order's.
        wanted = explicit
    else:
        multiplier = intent.get("quantity_multiplier")
        try:
            multiplier = float(multiplier) if multiplier is not None else 1
        except (TypeError, ValueError):
            multiplier = 1
        wanted = int(quantity * multiplier)
    # The server's order list carries the combined id (second
    # provider, 15 Nov 2026) — prefer it, so "same as usual"
    # re-pins the SMM service, not the GOP service that
    # happens to share the bare number.
    service_id = last.get("combined_id") or last.get("service_id")
    service_name = str(last.get("service_name") or "")
    platform = None
    if service_id is None:
        # No service id on the last order: guess the platform from
        # the service name so the flow can still pick a service.
        for p in ("instagram", "tiktok", "telegram", "youtube", "facebook", "x"):
            if p in service_name.lower():
                platform = p
                break
    note = t("usual_note", lang)
    if service_id is not None:
        try:
            services = await paxyo.services()
            found = find_service_by_id(services, service_id)
            if found is not None:
                max_qty = int(found.get("max", 0) or 0)
                if max_qty > 0 and wanted > max_qty:
                    wanted = (max_qty // 10) * 10
                    note = (
                        f"{t('usual_note', lang)}\n"
                        f"{t('usual_capped', lang, max=max_qty)}"
                    )
        except Exception as exc:
            log.warning("usual cap lookup failed: %s", exc)
    merged = {
        "platform": platform,
        "service_hint": None,
        "link": last.get("link"),
        "quantity": wanted,
    }
    await complete_order(
        update.message, user.id, merged, lang, voice=voice,
        named_service_id=service_id, last_service_id=service_id,
        note=note,
    )


_BUDGET_ORDINALS = {
    "first": 0, "1st": 0, "1": 0,
    "second": 1, "2nd": 1, "2": 1,
    "third": 2, "3rd": 2, "3": 2,
}


def budget_choice_index(text: str):
    """Index of the budget option the user picked ("first one",
    "second one", "1", "2"), or None. Only the bare words match, so
    "first one" picks option 0 but "first order" does not."""
    s = " ".join((text or "").strip().lower().split())
    if not s:
        return None
    for word, idx in _BUDGET_ORDINALS.items():
        if s in (word, f"{word} one", f"the {word} one", f"{word} option"):
            return idx
    return None


async def handle_budget_text(update, text, intent, lang, voice=False):
    """Budget-first ordering: '10k for 500 birr, what do I get?'

    Lists the cheapest and the fastest option for the asked quantity
    with their real Paxyo prices, and asks which one. When the budget
    does not buy the asked quantity, says the most it buys instead.
    Never invents a price and never negotiates one."""
    user = update.effective_user
    budget = intent.get("amount")
    try:
        budget = float(budget) if budget is not None else None
    except (TypeError, ValueError):
        budget = None
    if budget is None:
        await reply_message(update.message, t("budget_ask", lang), lang, voice=voice)
        return
    quantity = intent.get("quantity")
    try:
        quantity = int(quantity) if quantity is not None else None
    except (TypeError, ValueError):
        quantity = None
    platform = (intent.get("platform") or "").strip().lower() or None
    hint = intent.get("service_hint")
    if not platform and not hint:
        # A budget question in the middle of an order ("how much
        # views can 10 br get me" after a TikTok views order) is
        # about that platform and metric — not about every service
        # Paxyo sells.
        platform, hint = _conversation_context(user.id)
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("budget services failed: %s", exc)
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    picks = pick_services(services, platform=platform, service_hint=hint, limit=100)
    if not picks:
        await reply_message(
            update.message,
            no_service_reply(platform, hint, text, lang)
            or t("no_service", lang),
            lang, voice=voice,
        )
        return
    metric = hint or platform or "service"
    cheapest = min(picks, key=lambda s: float(s.get("rate_etb_per_1000", 0) or 0))

    def _avg(s):
        v = parse_average_time(s.get("average_time"))
        return v if v is not None else 10 ** 9

    fastest = min(picks, key=_avg)
    options = []
    seen = set()
    for svc in (cheapest, fastest):
        sid = svc.get("service")
        if sid in seen:
            continue
        seen.add(sid)
        options.append(svc)
    if quantity is None:
        # State the quantity each option buys, not just the per-1000
        # price: "how much views can 10 br get me" is a question
        # about a number (13 Nov 2026 — the bot listed prices and
        # never said how many views). An option the budget cannot
        # buy at minimum is left out; when none is affordable, say
        # so with the cheapest minimum instead.
        shown = []
        shown_services = []
        for s in options:
            qty = qty_for_amount(
                budget, float(s.get("rate_etb_per_1000", 0) or 0)
            )
            if qty < int(s.get("min", 0) or 0):
                continue
            metric_word = (
                kind_from_text(hint or "")
                or kind_from_text(clean_service_name(s.get("name")) or "")
                or "service"
            )
            shown.append(
                f"{short_service_name(s.get('name'))} — "
                f"about {qty:,} {metric_word} "
                f"({format_money(s.get('rate_etb_per_1000', 0))} ETB per 1000)"
            )
            shown_services.append(s)
        if not shown:
            await reply_message(
                update.message,
                t(
                    "budget_too_small", lang, budget=format_money(budget),
                    minimum=int(cheapest.get("min", 0) or 0),
                    metric=metric,
                    name=short_service_name(cheapest.get("name")),
                    total=format_money(estimated_total_etb(
                        float(cheapest.get("rate_etb_per_1000", 0) or 0),
                        int(cheapest.get("min", 0) or 0),
                    )),
                ),
                lang, voice=voice,
            )
            return
        option_text = "; ".join(shown)
        # Remember what was shown, in order, so "first one" /
        # "second one" picks it instead of starting a new order.
        BUDGET_OPTIONS[user.id] = {
            "platform": platform, "service_hint": hint,
            "quantity": None, "options": shown_services,
        }
        await reply_message(
            update.message,
            t("budget_no_quantity", lang, budget=format_money(budget),
              options=option_text),
            lang, voice=voice,
        )
        return
    cheapest_total = estimated_total_etb(
        float(cheapest.get("rate_etb_per_1000", 0)), quantity
    )
    if cheapest_total <= budget:
        option_text = "; ".join(
            f"{short_service_name(s.get('name'))} — "
            f"{format_money(estimated_total_etb(float(s.get('rate_etb_per_1000', 0)), quantity))} ETB"
            for s in options
        )
        # Remember what was shown, in order, so "first one" /
        # "second one" picks it instead of starting a new order.
        BUDGET_OPTIONS[user.id] = {
            "platform": platform, "service_hint": hint,
            "quantity": quantity, "options": options,
        }
        await reply_message(
            update.message,
            t("budget_options", lang, quantity=quantity, metric=metric,
              options=option_text),
            lang, voice=voice,
        )
        return
    rate = float(cheapest.get("rate_etb_per_1000", 0) or 0)
    if rate <= 0:
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    max_qty = int(budget / (rate / 1000))
    max_qty = (max_qty // 10) * 10
    min_qty = int(cheapest.get("min", 0) or 0)
    if max_qty >= min_qty and max_qty > 0:
        await reply_message(
            update.message,
            t(
                "budget_max", lang, budget=format_money(budget),
                quantity=quantity, metric=metric, max_quantity=max_qty,
                name=short_service_name(cheapest.get("name")),
                total=format_money(
                    estimated_total_etb(rate, max_qty)
                ),
            ),
            lang, voice=voice,
        )
        return
    await reply_message(
        update.message,
        t(
            "budget_too_small", lang, budget=format_money(budget),
            minimum=min_qty, metric=metric,
            name=short_service_name(cheapest.get("name")),
            total=format_money(estimated_total_etb(rate, min_qty)),
        ),
        lang, voice=voice,
    )


async def resolve_batch_drafts(drafts, user_id):
    """Resolve each draft to a real service. Returns (ready, missing):
    ready is [{service, link, quantity, total}], missing is a list of
    one-line problems. (None, None) means the services fetch failed.
    A draft with no link or no quantity is missing, not guessed."""
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("batch services failed: %s", exc)
        return None, None
    ready, missing = [], []
    for d in drafts:
        link = (d.get("link") or "").strip()
        qty = d.get("quantity")
        label = d.get("service_hint") or d.get("platform") or "order"
        if not link:
            missing.append(f"{label} — no link")
            continue
        if qty is None:
            missing.append(f"{link} — no quantity")
            continue
        service = None
        named = d.get("service_id")
        if named is not None:
            service, svc_error = resolve_named_service(services, named)
            if svc_error is not None:
                missing.append(f"{link} — service {named} is not available")
                continue
        if service is None:
            # Story/post (16 Nov 2026): the pick keys off the link
            # type — a post link never gets a story service. Only
            # the reactions pool reads the flag, so other drafts
            # are unaffected.
            picks = pick_services(
                services, platform=d.get("platform"),
                service_hint=d.get("service_hint"),
                story=_story_flag(
                    d.get("link"), d.get("service_hint"),
                    d.get("story"),
                ),
            )
            if not picks:
                missing.append(f"{link} — no service found")
                continue
            service = picks[0]
        error = validate_quantity(qty, service)
        if error:
            missing.append(
                f"{link} — {short_service_name(service.get('name'))}: "
                f"quantity must be between "
                f"{service.get('min')} and {service.get('max')}"
            )
            continue
        ready.append({
            "service": service,
            "link": link,
            "quantity": int(qty),
            "total": estimated_total_etb(
                float(service.get("rate_etb_per_1000", 0)), int(qty)
            ),
        })
    return ready, missing


async def show_batch_confirm(message, user_id, ready, lang, voice=False):
    """One Confirm card listing every order in the batch, with the
    combined total. One Confirm places them all."""
    confirm_id = uuid.uuid4().hex[:12]
    PENDING_BATCH[confirm_id] = {"user_id": user_id, "orders": ready}
    total = sum(o["total"] for o in ready)
    lines = [t("batch_title", lang, n=len(ready)), ""]
    for i, o in enumerate(ready, 1):
        lines.append(
            f"{i}. {short_service_name(o['service'].get('name'))} "
            f"×{o['quantity']} → {o['link']} — "
            f"{format_money(o['total'])} ETB"
        )
    lines.append("")
    lines.append(t("batch_total", lang, total=format_money(total)))
    # Batch Confirm card: always text — it carries the buttons.
    await reply_message(
        message, "\n".join(lines), lang, voice=voice,
        reply_markup=confirm_keyboard(confirm_id),
    )


async def place_batch(batch, user_id):
    """Place every order in a confirmed batch. Returns (results, error):
    results is [(draft, order_id or None, error or None)]. The balance
    is checked once against the batch total first; a failure on one
    order never stops the others, and each order gets its own
    idempotency key so a retry cannot double-charge it. A banned
    user places nothing: error is ("banned",)."""
    # Ban (19 Nov 2026): checked first, before any money moves.
    if await user_is_banned(user_id):
        return None, ("banned",)
    orders = batch["orders"]
    total = sum(o["total"] for o in orders)
    try:
        bal = await paxyo.balance(user_id)
    except Exception as exc:
        log.warning("batch balance check failed: %s", exc)
        return None, ("not_understood",)
    if not bal.get("found") or float(bal.get("balance", 0)) < total:
        return None, ("insufficient", bal.get("balance", 0), total)
    results = []
    for draft in orders:
        try:
            result = await create_order_for_service(
                paxyo, user_id, draft["service"], draft["link"],
                draft["quantity"], uuid.uuid4().hex,
            )
        except httpx.HTTPStatusError as exc:
            log.warning("batch create_order rejected: %s", exc.response.status_code)
            results.append((draft, None, "order_failed"))
            continue
        except Exception as exc:
            log.warning("batch create_order failed: %s", exc)
            results.append((draft, None, "order_failed"))
            continue
        order = result.get("order", result) if isinstance(result, dict) else {}
        order_id = order.get("id") or order.get("order_id") or "?"
        LAST_ORDER[user_id] = order_id
        # Per-user personality (feature 5, 15 Nov 2026): each
        # placed order in the batch is proof of the user's usual,
        # like a single placed order (see learn_from_placed_order).
        learn_from_placed_order(user_id, draft["service"], draft["quantity"])
        results.append((draft, order_id, None))
    return results, None


def batch_result_text(results, lang: str) -> str:
    """One short line per order in a placed batch: ✅ with the order
    id, or ❌ when that one could not be placed."""
    lines = []
    for draft, order_id, error in results:
        name = short_service_name(draft["service"].get("name"))
        if error is None:
            lines.append(f"✅ {draft['quantity']} {name} → Order {order_id}")
        else:
            lines.append(f"❌ {draft['quantity']} {name}, could not be placed")
    return "\n".join(lines)


# ------------------------------------------------------ post bundle -----
# Ideas batch 1 #3 (16 Nov 2026): "Boost my new post" orders views +
# likes + reactions together for ONE post link — one combined Confirm
# card, one grand total, one payment, three legs placed sequentially.
# The batch machinery does the heavy lifting (resolve_batch_drafts,
# the Confirm card shape, the per-leg result lines); the bundle adds
# the three-leg draft, the one quantity question, and watching every
# placed leg so the normal rescue rules apply per leg.

def is_post_bundle_request(text: str) -> bool:
    """True for a post-boost request: "boost my new post", "boost
    this post", "promote my latest post". A named metric ("boost my
    post with 1000 views") is a single-service order, not a bundle —
    and "boost" without "post" ("boost my tiktok") is one too."""
    s = " ".join(normalize_text(text or "").split())
    if "boost" not in s and "promote" not in s:
        return False
    if "post" not in s.split():
        return False
    if kind_from_text(text) is not None:
        return False
    return True


def bundle_quantities_from_text(text):
    """{"views", "likes", "reactions"} from a bundle quantity
    answer, or None. One number applies to all three legs ("1000");
    three numbers each next to its metric ("1000 views, 500 likes,
    200 reactions") apply per leg. A partial answer (only some legs)
    is None — the caller asks again instead of guessing the rest.
    Numbers inside the links themselves are never read as
    quantities: the text is split around the links first (a post
    link ending in /180 is not a quantity of 180)."""
    text = re.sub(r"https?://\S+|t\.me/\S+", " ", text or "")
    parts = re.split(r"[,;]|\band\b", text)
    found = {}
    fallback = None
    for part in parts:
        qty = quantity_from_text(part)
        if qty is None:
            continue
        metric = kind_from_text(part)
        if metric in ("views", "likes", "reactions"):
            found[metric] = qty
        elif fallback is None:
            fallback = qty
    if len(found) == 3:
        return found
    if fallback is not None and not found:
        return {
            "views": fallback, "likes": fallback, "reactions": fallback,
        }
    return None


async def show_bundle_confirm(message, user_id, ready, lang, voice=False):
    """One combined Confirm card for a post bundle: the three legs
    with quantities and the one grand total. One Confirm places all
    three legs — never a leg the user did not confirm."""
    confirm_id = uuid.uuid4().hex[:12]
    PENDING_BUNDLE[confirm_id] = {"user_id": user_id, "orders": ready}
    total = sum(o["total"] for o in ready)
    lines = [t("bundle_title", lang), ""]
    for i, o in enumerate(ready, 1):
        lines.append(
            f"{i}. {short_service_name(o['service'].get('name'))} "
            f"×{o['quantity']} → {o['link']} — "
            f"{format_money(o['total'])} ETB"
        )
    lines.append("")
    lines.append(t("batch_total", lang, total=format_money(total)))
    # Bundle Confirm card: always text — it carries the buttons.
    await reply_message(
        message, "\n".join(lines), lang, voice=voice,
        reply_markup=confirm_keyboard(confirm_id),
    )


async def place_bundle(bundle, user_id):
    """Place every leg of a confirmed post bundle, sequentially.
    Returns (results, error) like place_batch — but every placed
    leg is watched, so the normal rescue rules (price cap,
    cross-provider) apply per leg and a leg that fails later is
    rescued or refunded by the watcher. A leg that fails at
    placement was never charged, so there is nothing to refund
    for it — the result line says plainly it could not be placed.
    A banned user places nothing: error is ("banned",)."""
    # Ban (19 Nov 2026): checked first, before any money moves.
    if await user_is_banned(user_id):
        return None, ("banned",)
    orders = bundle["orders"]
    total = sum(o["total"] for o in orders)
    try:
        bal = await paxyo.balance(user_id)
    except Exception as exc:
        log.warning("bundle balance check failed: %s", exc)
        return None, ("not_understood",)
    if not bal.get("found") or float(bal.get("balance", 0)) < total:
        return None, ("insufficient", bal.get("balance", 0), total)
    results = []
    for draft in orders:
        try:
            result = await create_order_for_service(
                paxyo, user_id, draft["service"], draft["link"],
                draft["quantity"], uuid.uuid4().hex,
            )
        except httpx.HTTPStatusError as exc:
            log.warning("bundle create_order rejected: %s", exc.response.status_code)
            results.append((draft, None, "order_failed"))
            continue
        except Exception as exc:
            log.warning("bundle create_order failed: %s", exc)
            results.append((draft, None, "order_failed"))
            continue
        order = result.get("order", result) if isinstance(result, dict) else {}
        order_id = order.get("id") or order.get("order_id") or "?"
        LAST_ORDER[user_id] = order_id
        # Per-user personality (feature 5, 15 Nov 2026): each
        # placed leg is proof of the user's usual, like a single
        # placed order.
        learn_from_placed_order(user_id, draft["service"], draft["quantity"])
        watch_order(
            user_id, order_id, draft["service"], draft["quantity"],
            draft["link"], total=draft["total"],
        )
        results.append((draft, order_id, None))
    return results, None


async def handle_post_bundle(update, text, intent, lang, voice=False):
    """Build a post bundle over turns: the post link, then the
    quantities (asked once, or the user's default quantity), then
    the combined Confirm card. A bundle is for ONE post link: a
    profile/channel link is refused with the video-link question,
    and the link is never guessed. Nothing is placed before the
    user confirms the card."""
    user = update.effective_user
    intent = intent or {}
    stored = BUNDLE_DRAFT.get(user.id) or {}
    links = extract_links(text)
    link = links[0] if links else stored.get("link")
    platform = None
    if link:
        platform = platform_from_link(link)
    if platform is None:
        platform = (
            (intent.get("platform") or stored.get("platform") or "")
            .strip().lower() or None
        )
    quantities = (
        bundle_quantities_from_text(text) or stored.get("quantities")
    )
    if quantities is None and platform:
        # The user's default quantity (customizations #12): one
        # number for all three legs, so they do not repeat it.
        default_qty = pref_default_quantity(user.id, platform, "views")
        if default_qty:
            quantities = {
                "views": default_qty,
                "likes": default_qty,
                "reactions": default_qty,
            }
    if not link:
        BUNDLE_DRAFT[user.id] = {
            "platform": platform, "quantities": quantities,
        }
        await reply_message(
            update.message,
            ask_link_text(platform, None, lang)
            if platform else t("bundle_ask_link", lang),
            lang, voice=voice,
        )
        return
    # A bundle boosts one POST: a profile/channel link cannot take
    # views, likes or reactions, so it is refused with the
    # video-link question instead of placing on the wrong link
    # (link check, item 5). An unknown link shape passes, as the
    # validator does — the provider resolves short links.
    if link_content_kind(link) == "profile":
        BUNDLE_DRAFT[user.id] = {
            "platform": platform, "link": None,
            "quantities": quantities,
        }
        await reply_message(
            update.message,
            ask_link_text(platform, "views", lang),
            lang, voice=voice,
        )
        return
    if quantities is None:
        BUNDLE_DRAFT[user.id] = {
            "platform": platform, "link": link, "quantities": None,
        }
        await reply_message(
            update.message, t("bundle_ask_quantities", lang),
            lang, voice=voice,
        )
        return
    BUNDLE_DRAFT.pop(user.id, None)
    drafts = [
        {
            "platform": platform,
            "service_hint": (
                f"{platform} {metric}" if platform else metric
            ),
            "link": link,
            "quantity": quantities[metric],
        }
        for metric in ("views", "likes", "reactions")
    ]
    ready, missing = await resolve_batch_drafts(drafts, user.id)
    if ready is None:
        await reply_message(
            update.message, t("not_understood", lang), lang, voice=voice
        )
        return
    if missing:
        understood = "\n".join(
            f"{short_service_name(o['service'].get('name'))} "
            f"×{o['quantity']} → {o['link']}"
            for o in ready
        ) or "none"
        await reply_message(
            update.message,
            t(
                "batch_missing", lang, understood=understood,
                missing="\n".join(missing),
            ),
            lang, voice=voice,
        )
        return
    await show_bundle_confirm(update.message, user.id, ready, lang, voice=voice)


# ----------------------------------------------------- check my post ----
# Ideas batch 2 #2 (16 Nov 2026): "check my post" tells the user if
# the post is public, its current views, and whether it is ready for
# an order. Only a public Telegram channel page can actually be read
# (the ?embed=1 widget page carries the view count); every other
# platform's page needs JavaScript or a login, so the bot says plainly
# it cannot read the counts there — never inventing numbers. A check
# never starts an order draft.

def is_post_check_request(text: str) -> bool:
    """True for a post-check request: a link plus "check", "public",
    "ready for an order", or "how many views/likes does this post
    have". A bare link is an order, not a check; a price question
    ("how much are views") has no link and never matches."""
    if not extract_links(text):
        return False
    s = " ".join(normalize_text(text or "").split())
    # Word-boundary matches: normalize_text keeps "public?" attached
    # to its punctuation, so a split-word membership test misses it.
    if re.search(r"\bcheck\b", s):
        return True
    if re.search(r"\bpublic\b", s):
        return True
    if re.search(r"\bready\b", s) and re.search(r"\border\b", s):
        return True
    if "how many" in s and (
        re.search(r"\bviews\b", s) or re.search(r"\blikes\b", s)
    ):
        return True
    return False


def _parse_telegram_post_html(html: str):
    """The view count from a Telegram ?embed=1 widget page, or None.
    Pure regex on the widget markup (verified live 16 Nov 2026:
    tgme_widget_message_views">2.82M</span>). The count is reported
    exactly as the page shows it ("2.82M") — never converted or
    guessed. None when the markup is absent or the page has no post
    widget at all."""
    if not html:
        return None
    match = re.search(
        r"tgme_widget_message_views[^>]*>([^<]+)<", html
    )
    if match is None:
        return None
    views = match.group(1).strip()
    return views or None


async def _fetch_telegram_post_stats(link: str):
    """{"public": True/False/None, "views": str|None} for a Telegram
    post link, from the public ?embed=1 widget page (10s timeout,
    browser User-Agent — the plain post URL redirects to the channel
    page, which carries no counts). True only when the page carries
    the post widget; False on a 404 (private or deleted); None when
    the page cannot be read at all (network error, unexpected page)
    — an unreadable page is never reported as private. Never raises."""
    url = (link or "").strip()
    if "?" in url:
        url = url.split("?", 1)[0]
    url += "?embed=1"
    try:
        async with httpx.AsyncClient(
            timeout=10.0, trust_env=False
        ) as client:
            resp = await client.get(
                url,
                headers={
                    "User-Agent": (
                        "Mozilla/5.0 (X11; Linux x86_64) "
                        "AppleWebKit/537.36 Chrome/120 Safari/537.36"
                    )
                },
            )
    except Exception as exc:
        log.warning("post check fetch failed: %s", exc)
        return {"public": None, "views": None}
    if resp.status_code == 404:
        return {"public": False, "views": None}
    if resp.status_code != 200:
        return {"public": None, "views": None}
    html = resp.text or ""
    if "tgme_widget_message_bubble" not in html:
        return {"public": None, "views": None}
    return {"public": True, "views": _parse_telegram_post_html(html)}


async def handle_post_check(update, text, lang, voice=False):
    """Answer a post check in one short reply. The link is validated
    first (a real post URL on a known platform); a profile/channel
    link or an unknown link is refused plainly. Telegram posts are
    checked live on the public page; other platforms' counts cannot
    be read from here, so the bot says so and confirms the link is
    the right shape for an order when the post is public."""
    user = update.effective_user
    links = extract_links(text)
    link = links[0] if links else None
    platform = platform_from_link(link) if link else None
    if platform is None:
        await reply_message(
            update.message, t("post_check_unknown_link", lang),
            lang, voice=voice,
        )
        return
    disp = _PLATFORM_DISPLAY.get(platform, platform.title())
    if link_content_kind(link) == "profile":
        await reply_message(
            update.message,
            t("post_check_not_post_link", lang, platform=disp),
            lang, voice=voice,
        )
        return
    if platform != "telegram":
        await reply_message(
            update.message,
            t("post_check_cant_read", lang, platform=disp),
            lang, voice=voice,
        )
        return
    stats = await _fetch_telegram_post_stats(link)
    if stats.get("public") is True:
        if stats.get("views"):
            await reply_message(
                update.message,
                t(
                    "post_check_public_views", lang,
                    views=stats["views"],
                ),
                lang, voice=voice,
            )
        else:
            await reply_message(
                update.message,
                t("post_check_public_no_counts", lang),
                lang, voice=voice,
            )
        return
    if stats.get("public") is False:
        await reply_message(
            update.message, t("post_check_not_public", lang),
            lang, voice=voice,
        )
        return
    await reply_message(
        update.message, t("post_check_unknown", lang),
        lang, voice=voice,
    )


async def handle_split_text(update, text, split, lang, voice=False):
    """Split one quantity across several posts: 'split 5,000 likes
    across my last 5 Instagram posts'.

    The bot cannot fetch the user's posts, so it asks for the links
    (they can be pasted together), counts them, and says how many are
    still missing. When all links are in, each gets an equal share
    (rounded down to a multiple of 10) and the batch Confirm card
    shows the split."""
    user = update.effective_user
    stored = SPLIT_DRAFT.get(user.id) or {}
    quantity = split.get("quantity") or stored.get("quantity")
    count = split.get("count") or stored.get("count")
    platform = split.get("platform") or stored.get("platform")
    hint = split.get("service_hint") or stored.get("service_hint")
    links = list(stored.get("links") or [])
    for link in extract_links(text):
        if link not in links:
            links.append(link)
    try:
        quantity = int(quantity) if quantity is not None else None
        count = int(count) if count is not None else None
    except (TypeError, ValueError):
        quantity = count = None
    if quantity is None or count is None or count <= 0:
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    metric = hint or platform or "likes"
    each = (quantity // count // 10) * 10
    if each <= 0:
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    if len(links) < count:
        SPLIT_DRAFT[user.id] = {
            "platform": platform,
            "service_hint": hint,
            "quantity": quantity,
            "count": count,
            "links": links,
        }
        if not links:
            await reply_message(
                update.message,
                t("split_ask_links", lang, count=count, quantity=quantity,
                  metric=metric, each=each),
                lang, voice=voice,
            )
        else:
            await reply_message(
                update.message,
                t("split_missing", lang, got=len(links), count=count,
                  missing=count - len(links)),
                lang, voice=voice,
            )
        return
    SPLIT_DRAFT.pop(user.id, None)
    drafts = [
        {"platform": platform, "service_hint": hint, "link": link, "quantity": each}
        for link in links[:count]
    ]
    ready, missing = await resolve_batch_drafts(drafts, user.id)
    if ready is None:
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    if missing:
        understood = "\n".join(
            f"{short_service_name(o['service'].get('name'))} ×{o['quantity']} → {o['link']}"
            for o in ready
        ) or "none"
        await reply_message(
            update.message,
            t("batch_missing", lang, understood=understood,
              missing="\n".join(missing)),
            lang, voice=voice,
        )
        return
    await show_batch_confirm(update.message, user.id, ready, lang, voice=voice)


def parse_bulk_drafts(text, intent=None):
    """Several links pasted in one message -> one batch draft per
    link (15 Nov 2026, feature 2). Returns a list of
    {"platform", "service_hint", "link", "quantity"} drafts, or
    None when there are fewer than 2 or more than 5 links.

    The platform comes from each link's own domain
    (platform_from_link); the metric comes from the message's
    words ("1000 views ..."), shared across all links. Quantities:
    a number next to a link belongs to that link ("1000 views to
    <link1>, 2000 views to <link2>"); a single quantity in the
    message applies to every link ("1000 views for these three
    links"). A link with no quantity anywhere gets quantity None
    and is reported as missing by the batch flow — never guessed.
    Numbers inside the links themselves are never read as
    quantities: the text is split around the links first."""
    links = extract_links(text)
    if len(links) < 2 or len(links) > 5:
        return None
    intent = intent or {}
    # Segments of text around each link: segment i is before link
    # i, segment i+1 is after it. Quantities are read per segment,
    # so a number inside a link can never be mistaken for one.
    # One rule for the whole message, so a quantity is never
    # claimed by two links: when the first quantity comes before
    # the first link ("1000 views to <link1>, 2000 to <link2>"),
    # each link takes the quantity in its preceding segment; when
    # it comes after ("<link1> 1000 views, <link2> 2000 views"),
    # each link takes the quantity in its following segment.
    parts = re.split(r"https?://\S+|t\.me/\S+", text or "")
    metric = kind_from_text(text) or kind_from_text(
        intent.get("service_hint") or ""
    )
    shared = quantity_from_text(" ".join(parts))
    qty_before_link = quantity_from_text(parts[0]) is not None
    drafts = []
    for i, link in enumerate(links):
        if qty_before_link:
            qty = quantity_from_text(parts[i])
        else:
            qty = (
                quantity_from_text(parts[i + 1])
                if i + 1 < len(parts) else None
            )
        if qty is None:
            qty = shared
        platform = platform_from_link(link)
        if platform is None:
            platform = (intent.get("platform") or "").strip().lower() or None
        hint = None
        if platform and metric:
            hint = f"{platform} {metric}"
        elif metric:
            hint = metric
        elif intent.get("service_hint"):
            hint = intent.get("service_hint")
        drafts.append({
            "platform": platform,
            "service_hint": hint,
            "link": link,
            "quantity": qty,
        })
    return drafts


async def handle_batch_text(update, text, intent, lang, voice=False):
    """Several orders in one message, or one quantity split across
    posts. Each order is resolved to a real service and shown on one
    batch Confirm card; one Confirm places them all. Anything the
    bot could not parse is listed back and asked about — never
    guessed."""
    user = update.effective_user
    split = intent.get("split")
    if split:
        await handle_split_text(update, text, split, lang, voice=voice)
        return
    orders = intent.get("orders")
    if not orders:
        # No orders list from the classifier (15 Nov 2026, feature
        # 2): the user pasted several links in one message. Parse
        # them locally — platform per link, one quantity for all
        # links, or a quantity per link — and show the same one
        # combined Confirm card. More than 5 links: ask the user
        # to split them into smaller messages, never drop any.
        links = extract_links(text)
        if len(links) >= 2:
            if len(links) > 5:
                await reply_message(
                    update.message,
                    t("bulk_too_many", lang, n=len(links)),
                    lang, voice=voice,
                )
                return
            orders = parse_bulk_drafts(text, intent)
    if not orders:
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    if len(orders) > 5:
        await reply_message(
            update.message,
            t("bulk_too_many", lang, n=len(orders)),
            lang, voice=voice,
        )
        return
    ready, missing = await resolve_batch_drafts(orders, user.id)
    if ready is None:
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    if missing:
        understood = "\n".join(
            f"{short_service_name(o['service'].get('name'))} ×{o['quantity']} → {o['link']}"
            for o in ready
        ) or "none"
        await reply_message(
            update.message,
            t("batch_missing", lang, understood=understood,
              missing="\n".join(missing)),
            lang, voice=voice,
        )
        return
    await show_batch_confirm(update.message, user.id, ready, lang, voice=voice)


_CHANGE_PHRASES = (
    "instead", "make it", "change", "just get", "rather",
)


def _is_quantity_change(text, merged, pending):
    """True when a message with a new quantity is a change to the
    order awaiting Confirm, not a new order: it says so ("200
    instead", "make it 200"), or it names the same platform and kind
    as the pending service (a bare "200" while a Confirm card is up
    means "200 instead"). A different platform or kind is a new
    order and still asks for its link."""
    s = " ".join((text or "").strip().lower().split())
    if any(p in s for p in _CHANGE_PHRASES):
        return True
    service = pending.get("service") or {}
    hay = _clean_kind_text(
        str(service.get("name") or "") + " "
        + str(service.get("category") or "")
    ).lower()
    platform = (merged.get("platform") or "").strip().lower()
    if platform:
        words = re.findall(r"[a-z]+", hay)
        if platform not in words:
            return False
    kind = kind_from_text(text)
    if kind is not None:
        kind_words = {
            _canonical_metric(w) for w in kind.split()
        } - {None}
        if kind_words != _name_kinds(service.get("name")):
            return False
    return True


def _remember_card_message(pending, user_message, sent):
    """Remember which Telegram message carries a Confirm card, on
    the PENDING entry itself: the chat id from the user's message
    and the message id from the sent card. A later replacement
    (a reaction correction, a quantity change) deletes that message
    instead of leaving a stale card stacked in the chat. Missing
    ids are simply not stored — deletion is best effort."""
    if not isinstance(pending, dict):
        return
    chat_id = getattr(user_message, "chat_id", None)
    message_id = getattr(sent, "message_id", None)
    if chat_id is not None:
        pending["chat_id"] = chat_id
    if message_id is not None:
        pending["message_id"] = message_id


async def drop_pending_card(update, pending):
    """Delete the Confirm card message of a pending order, best
    effort. Called when the card is replaced (a reaction
    correction) so its buttons cannot place the old service. The
    PENDING entry is popped by the caller either way; a failed
    delete (message too old, no rights, no stored id) is logged,
    never fatal — the old buttons are dead once the entry is
    gone."""
    message_id = (pending or {}).get("message_id")
    chat_id = (pending or {}).get("chat_id")
    if not message_id or not chat_id:
        return
    try:
        bot = update.message.get_bot()
    except Exception:
        return
    try:
        await bot.delete_message(chat_id=chat_id, message_id=message_id)
    except Exception as exc:
        log.warning("dropping old card failed: %s", exc)


async def try_reaction_correction(update, text, lang, voice=False):
    """A different reaction emoji for the order already awaiting
    Confirm ("I want only 🙏 reaction") re-picks the service for
    that emoji and shows a NEW card — never the old card unchanged
    (owner, 14 Nov 2026: a 🙏 correction re-showed the Positive mix
    card). The link and quantity come from the pending order, and
    the old card is dropped so its buttons cannot place the old
    service. Returns True when a correction was handled. Only when
    the pending service is a reactions service and the new emoji
    differs from it. The message's OWN fields decide: a link or a
    quantity in the message is a new order, not a correction — the
    merged draft still carries the old link and quantity (PARTIAL
    survives the card), so merged must not be consulted here."""
    user = update.effective_user
    _cid, _pending = pending_for_user(user.id)
    if _pending is None:
        return False
    _pending_name = str(_pending["service"].get("name") or "")
    if "reaction" not in _pending_name.lower():
        return False
    _own = local_intent(text)
    if _own.get("link") or _own.get("quantity"):
        return False
    _new_emoji = reaction_emoji(text)
    _old_emoji = reaction_emoji(_pending_name)
    if (
        _new_emoji is None
        or _old_emoji is None
        or _new_emoji == _old_emoji
    ):
        return False
    try:
        _services = await paxyo.services()
    except Exception as exc:
        log.warning("correction services failed: %s", exc)
        _services = []
    # The correction re-picks on the PENDING order's platform:
    # a Facebook ❤️ correction must re-pick a Facebook service,
    # not a Telegram one (owner, 14 Nov 2026 — the exact-emoji
    # rule covers Facebook reactions too).
    _platform, _hint = _platform_hint_of_service(_pending["service"])
    if not _hint or "reaction" not in _hint:
        _hint = f"{_platform} reactions" if _platform else "reactions"
    _picks = pick_services(
        _services, platform=_platform,
        service_hint=_hint,
        reaction_emoji=_new_emoji,
        story=_story_flag(_pending.get("link"), _hint),
    ) if _services else []
    if not _picks:
        _reply = t("no_exact_reaction", lang, emoji=_new_emoji)
        await reply_message(update.message, _reply, lang, voice=voice)
        log_confusion(user.id, text, _reply, "correction")
        return True
    _service = _picks[0]
    _new_qty = int(_pending["quantity"])
    _error = validate_quantity(_new_qty, _service)
    if _error:
        _reply = t(
            "bad_quantity", lang,
            service=short_service_name(_service.get("name")),
            min=_service.get("min"), max=_service.get("max"),
        )
        await reply_message(update.message, _reply, lang, voice=voice)
        log_confusion(user.id, text, _reply, "correction")
        return True
    _new_total = estimated_total_etb(
        float(_service.get("rate_etb_per_1000", 0)), _new_qty
    )
    _new_id = uuid.uuid4().hex[:12]
    PENDING.pop(_cid, None)
    _new_pending = {
        "user_id": user.id, "service": _service,
        "link": _pending["link"], "quantity": _new_qty,
        "total": _new_total,
        "full_name": _pending.get("full_name", False),
    }
    PENDING[_new_id] = _new_pending
    # The old card goes first, so the chat never shows two live
    # cards for one order (live bug, 14 Nov 2026: both Pray cards
    # stayed stacked, each with its own Confirm/Cancel).
    await drop_pending_card(update, _pending)
    _card = confirm_card_text(
        lang, _service, _new_qty, _new_total, _pending["link"],
        note=t("change_note", lang, quantity=_new_qty),
        full_name=_pending.get("full_name", False),
    )
    _sent = await reply_message(
        update.message, _card, lang,
        reply_markup=confirm_keyboard(_new_id),
    )
    _remember_card_message(_new_pending, update.message, _sent)
    log_confusion(user.id, text, _card, "correction")
    return True


async def try_draft_reaction_correction(update, text, lang, voice=False):
    """A different reaction emoji for the order being BUILT (a
    PARTIAL draft, no Confirm card yet — screenshot bug, 16 Nov
    2026: "I want only like reaction" after a bad quantity got
    "I did not understand" and the draft died). Re-picks the
    service for that emoji on the draft's platform, KEEPS the link
    and the rest of the draft, and runs complete_order again — so
    a stored quantity that is valid for the new service re-shows
    the Confirm card, and one below the new service's minimum
    gets the same-emoji lower-min offer (or the plain minimum).
    Returns True when a correction was handled. Only when the
    draft is a reactions draft and the new emoji differs from it.
    The message's OWN fields decide: a link or a quantity in the
    message is a new order, not a correction — the merged draft
    still carries the old link and quantity (PARTIAL survives the
    card), so merged must not be consulted here. The emoji may be
    named by character or by word ("only laughing", "only love",
    "only kissing"): the word form needs no "reaction" word here,
    because the draft already says reactions. Platform-general:
    a Facebook draft re-picks a Facebook service, never a
    Telegram one. No exact service for that emoji on that
    platform: complete_order says so honestly (no_exact_reaction)
    and keeps the draft — never silently sells another emoji."""
    user = update.effective_user
    draft = PARTIAL.get(user.id)
    if not draft:
        return False
    hint = draft.get("service_hint") or ""
    if "reaction" not in hint.lower() and not draft.get("reaction_emoji"):
        return False
    _own = local_intent(text)
    if _own.get("link") or _own.get("quantity"):
        return False
    _new_emoji = reaction_emoji(text) or _reaction_emoji_from_words(text)
    _old_emoji = draft.get("reaction_emoji") or reaction_emoji(hint)
    if _new_emoji is None:
        return False
    if _old_emoji is not None and _new_emoji == _old_emoji:
        return False
    draft["reaction_emoji"] = _new_emoji
    merged = {k: v for k, v in draft.items() if v is not None}
    await complete_order(update.message, user.id, merged, lang, voice=voice)
    log_confusion(user.id, text, "draft reaction correction", "correction")
    return True


# "Not for story its for tg post" (story/post bug, 16 Nov 2026):
# the user corrects a reactions draft that was picked as story
# services. The match is deliberately wordy — "post" alone is
# too common ("post a comment"), so the phrase must say it is a
# post and not a story, or name a Telegram post outright.
_STORY_POST_CORRECTION_PHRASES = (
    "not for story", "not story", "no story", "not a story",
    "for tg post", "for telegram post", "tg post", "telegram post",
    "its for post", "it's for post", "its a post", "it's a post",
    "for post", "post not story", "not story post",
)


async def try_story_post_correction(update, text, lang, voice=False):
    """'Not for story its for tg post': the reactions draft (or
    the open Confirm card) is for a POST, not a story. Switches
    it to post reactions and re-picks a post-reaction service,
    keeping the link and the quantity. A tg:// link in the draft
    is dropped at the same time — it is never an order link, so
    the bot asks for a real post link instead of carding it.
    Returns True when handled. Only when a reactions draft or a
    reactions card is open; anything else is not a correction."""
    user = update.effective_user
    s = " ".join((text or "").strip().lower().split())
    if not any(p in s for p in _STORY_POST_CORRECTION_PHRASES):
        return False
    _cid, _pending = pending_for_user(user.id)
    if _pending is not None and "reaction" in str(
        _pending["service"].get("name") or ""
    ).lower():
        # Move the card back to a draft, mark it post, re-run:
        # complete_order re-picks (post services only, same emoji)
        # and shows a new card; the old card is dropped first.
        _platform, _hint = _platform_hint_of_service(_pending["service"])
        PARTIAL[user.id] = {
            "platform": _platform,
            "service_hint": _hint,
            "link": _pending.get("link"),
            "quantity": _pending.get("quantity"),
            "reaction_emoji": reaction_emoji(
                str(_pending["service"].get("name") or "")
            ),
            "story": False,
        }
        if str(PARTIAL[user.id].get("link") or "").strip().lower().startswith("tg://"):
            PARTIAL[user.id]["link"] = None
        PENDING.pop(_cid, None)
        await drop_pending_card(update, _pending)
        await complete_order(
            update.message, user.id, dict(PARTIAL[user.id]), lang,
            voice=voice,
        )
        log_confusion(user.id, text, "story/post correction", "correction")
        return True
    draft = PARTIAL.get(user.id)
    if draft and (
        "reaction" in (draft.get("service_hint") or "").lower()
        or draft.get("reaction_emoji")
    ):
        draft["story"] = False
        if str(draft.get("link") or "").strip().lower().startswith("tg://"):
            draft["link"] = None
        merged = {k: v for k, v in draft.items() if v is not None}
        await complete_order(update.message, user.id, merged, lang, voice=voice)
        log_confusion(user.id, text, "story/post correction", "correction")
        return True
    return False


# ------------------------------------------------ editable Confirm card ----
# 19 Nov 2026 (live case): after the bot showed a correct drip-feed
# Confirm card, "Lets change the link" twice got "I did not
# understand" — the classifier never called it change_order, and
# handle_change_order only knew quantity. Edits are now caught
# locally, before the classifier, whenever a Confirm card is
# pending: the same pending entry is updated in place (same
# confirm_id, never a second card), the price is re-derived from
# the service rate, affordability is re-checked on the new total,
# and the full updated card is re-shown with Confirm/Cancel.
# Works on normal PENDING cards (drip plans live there too) and on
# PENDING_DELAYED cards. PENDING_RECURRING holds no cards any more
# (nothing creates one — the drip flow writes to PENDING), so edits
# do not cover it. PENDING_BATCH / PENDING_BUNDLE / PENDING_REFILL
# cards are not editable either: a batch, bundle or refill is a
# different shape, and the user cancels it and starts again.

_EDIT_VERBS = (
    "change", "edit", "update", "switch", "make it", "set it",
)
_EDIT_VERBS_GEEZ = ("ቀይር", "ለውጥ")
_EDIT_ASK_KEYS = {
    "link": "edit_ask_link",
    "quantity": "edit_ask_quantity",
    "per_run": "edit_ask_per_run",
    "runs": "edit_ask_runs",
    "interval": "edit_ask_interval",
    "amount": "edit_ask_amount",
    "service": "edit_ask_service",
    "delay": "edit_ask_delay",
}
_EDIT_FIELD_WORDS = {
    "link": ("link", "ሊንክ"),
    "runs": ("run", "runs", "times", "repeat"),
    "interval": ("every", "each", "gap", "interval", "ሰዓት"),
    "per_run": (
        "per run", "per drop", "each time", "each run",
        "every time", "per time",
    ),
    "amount": ("amount", "total", "cost", "price", "birr", "etb",
               "spend", "ዋጋ", "መጠን", "ብር"),
    "service": ("service", "አገልግሎት"),
    "delay": ("delay", "schedule"),
    "quantity": (
        "quantity", "views", "followers", "likes", "comments",
        "subscribers", "members", "shares", "reactions",
        "ቁጥር", "ብዛት",
    ),
}


def _edit_has_word(s: str, words) -> bool:
    """True when any word/phrase in `words` appears in `s` as a
    whole word (multi-word phrases by substring)."""
    for word in words:
        if " " in word:
            if word in s:
                return True
        elif re.search(rf"\b{re.escape(word)}\b", s):
            return True
    return False


def _edit_first_number(text):
    """First plain number in the text, or the last number-word
    value ("two thousand" -> 2000), or None."""
    for match in re.finditer(r"\d[\d,]*", text or ""):
        try:
            return int(match.group(0).replace(",", ""))
        except ValueError:
            continue
    values = _number_word_values(text)
    return values[-1] if values else None


def _edit_quantity_value(text):
    """The new quantity in an edit message, or None. "change the
    quantity from 5,000 to 2,000" means 2,000 (the last number),
    not 5,000 — the first-number rule would take the old value."""
    match = re.search(
        r"\bfrom\b\s*\d[\d,]*\s*\bto\b\s*(\d[\d,]*)",
        (text or "").lower(),
    )
    if match:
        try:
            return int(match.group(1).replace(",", ""))
        except ValueError:
            pass
    qty = quantity_from_text(text)
    if qty is not None:
        return qty
    return _edit_first_number(text)


def _edit_runs_value(text):
    """The new run count in an edit message, or None. "make it 5
    runs" and "change runs to 5" both read as 5."""
    runs = parse_runs(text)
    if runs is not None:
        return runs
    match = re.search(
        r"(?:runs?|times|repeat)\D{0,12}(\d+)", (text or "").lower()
    )
    if match:
        try:
            return int(match.group(1))
        except ValueError:
            return None
    return None


def parse_card_edit(text, pending=None, intent=None, store="pending"):
    """A Confirm-card edit in plain words, or None when the message
    is not one. Returns {"field", "value"}: "value" is the new
    value, or None when the field is named but the value is missing
    (the caller then asks for it in one short question). Fields:
    link, quantity, per_run, runs, interval, amount, service, and
    delay (delayed cards only). Pure: no state, no network.

    A bare link pasted on its own while a card is pending counts
    as a link edit when it differs from the card's link. On a drip
    card, a bare interval ("every 2 hours"), run count ("5 runs")
    or per-run amount ("200 views each time") also counts — there
    is nothing else those phrases can mean with a drip card open.
    """
    if not text:
        return None
    s = " ".join(str(text).strip().lower().split())
    links = extract_links(text)
    has_edit_word = (
        any(w in s for w in _EDIT_VERBS)
        or any(w in s for w in _EDIT_VERBS_GEEZ)
        or (
            "instead" in s
            and (
                re.search(r"\d", s)
                or _edit_has_word(s, _EDIT_FIELD_WORDS["quantity"])
                or _edit_has_word(s, _EDIT_FIELD_WORDS["link"])
            )
        )
    )
    if not has_edit_word:
        # A bare new link, or a bare drip field, with a card open.
        if pending is not None:
            stripped = (text or "").strip().rstrip(".,!?")
            if (
                links
                and re.fullmatch(r"https?://\S+|t\.me/\S+", stripped)
                and links[0] != (pending.get("link") or "")
            ):
                return {"field": "link", "value": links[0]}
            if pending.get("drip"):
                interval = parse_interval_minutes(text)
                if interval is not None and (
                    "every" in s or "each" in s
                    or "hourly" in s or "daily" in s
                ):
                    return {"field": "interval", "value": interval}
                runs = parse_runs(text)
                if runs is not None:
                    return {"field": "runs", "value": runs}
                if _edit_has_word(s, _EDIT_FIELD_WORDS["per_run"]):
                    value = _edit_quantity_value(text)
                    if value is not None:
                        return {"field": "per_run", "value": value}
        return None
    intent = intent or {}

    def _intent_value(key):
        value = intent.get(key)
        try:
            return int(value) if value is not None else None
        except (TypeError, ValueError):
            return None

    if _edit_has_word(s, _EDIT_FIELD_WORDS["link"]) or (
        links
        and not any(
            _edit_has_word(s, _EDIT_FIELD_WORDS[f])
            for f in ("runs", "interval", "per_run", "amount",
                      "service", "delay", "quantity")
        )
    ):
        value = links[0] if links else None
        if value is None and intent.get("link"):
            value = intent.get("link")
        return {"field": "link", "value": value}
    if _edit_has_word(s, _EDIT_FIELD_WORDS["runs"]):
        value = _edit_runs_value(text)
        return {"field": "runs", "value": value}
    if _edit_has_word(s, _EDIT_FIELD_WORDS["per_run"]):
        value = _edit_quantity_value(text)
        if value is None:
            value = _intent_value("quantity")
        return {"field": "per_run", "value": value}
    if _edit_has_word(s, _EDIT_FIELD_WORDS["interval"]):
        value = parse_interval_minutes(text)
        return {"field": "interval", "value": value}
    if _edit_has_word(s, _EDIT_FIELD_WORDS["amount"]):
        value = parse_money_amount(text)
        if value is None:
            value = _edit_first_number(text)
        if value is None:
            value = _intent_value("amount")
        return {"field": "amount", "value": value}
    if _edit_has_word(s, _EDIT_FIELD_WORDS["service"]):
        service_id = extract_service_id(text)
        if service_id is None:
            service_id = _intent_value("service_id")
        if service_id is None:
            # "change service to 1002": the id sits after "to",
            # which extract_service_id does not read.
            match = re.search(
                r"service\s+(?:to\s+)?#?\s*(\d+)", s
            )
            if match:
                try:
                    service_id = int(match.group(1))
                except ValueError:
                    service_id = None
        if service_id is not None:
            return {"field": "service", "value": {"service_id": service_id}}
        local = local_intent(text)
        if local.get("platform") or local.get("service_hint"):
            return {"field": "service", "value": {
                "platform": local.get("platform"),
                "service_hint": local.get("service_hint"),
            }}
        return {"field": "service", "value": None}
    if store == "delayed" and _edit_has_word(s, _EDIT_FIELD_WORDS["delay"]):
        value = parse_delay_minutes(text)
        return {"field": "delay", "value": value}
    if (
        _edit_has_word(s, _EDIT_FIELD_WORDS["quantity"])
        or "make it" in s or "change it" in s or "instead" in s
    ):
        value = _edit_quantity_value(text)
        if value is None:
            value = _intent_value("quantity")
        return {"field": "quantity", "value": value}
    return None


def _card_edit_value_from_text(field, text, pending=None):
    """The new value for `field` from a bare reply to the bot's
    one-line ask ("Which link...?" -> the pasted link, "How
    many...?" -> the number), or None when the reply carries no
    value for that field. Pure."""
    if field == "link":
        links = extract_links(text)
        if links:
            return links[0]
        return _validate_link((text or "").strip())
    if field in ("quantity", "per_run"):
        return _edit_quantity_value(text)
    if field == "runs":
        runs = parse_runs(text)
        if runs is not None:
            return runs
        return _edit_first_number(text)
    if field == "interval":
        value = parse_interval_minutes(text)
        if value is not None:
            return value
        return _parse_duration_minutes(text)
    if field == "amount":
        value = parse_money_amount(text)
        if value is not None:
            return value
        return _edit_first_number(text)
    if field == "service":
        service_id = extract_service_id(text)
        if service_id is None:
            match = re.search(
                r"service\s+(?:to\s+)?#?\s*(\d+)",
                (text or "").strip().lower(),
            )
            if match:
                try:
                    service_id = int(match.group(1))
                except ValueError:
                    service_id = None
        if service_id is not None:
            return {"service_id": service_id}
        local = local_intent(text)
        if local.get("platform") or local.get("service_hint"):
            return {
                "platform": local.get("platform"),
                "service_hint": local.get("service_hint"),
            }
        return None
    if field == "delay":
        return parse_delay_minutes(text)
    return None


def _pending_card_for_user(user_id: int):
    """(confirm_id, pending, store) of the user's Confirm card, or
    (None, None, None). A normal/drip card (PENDING) wins over a
    delayed one when both are open — the normal card is the one
    the user is most likely editing."""
    confirm_id, pending = pending_for_user(user_id)
    if pending is not None:
        return confirm_id, pending, "pending"
    delay_id, delayed = pending_delayed_for_user(user_id)
    if delayed is not None:
        return delay_id, delayed, "delayed"
    return None, None, None


def _stored_edit_card(user_id: int):
    """(confirm_id, pending, store, field) of the card edit the bot
    is waiting on a value for, or (None, None, None, None). A stale
    entry (its card already confirmed or cancelled) is dropped
    unread, so it can never eat a later message."""
    entry = CARD_EDIT_PENDING.get(user_id)
    if not entry:
        return None, None, None, None
    store = entry.get("store")
    table = PENDING if store == "pending" else PENDING_DELAYED
    pending = table.get(entry.get("confirm_id"))
    if pending is None or pending.get("user_id") != user_id:
        CARD_EDIT_PENDING.pop(user_id, None)
        return None, None, None, None
    return entry.get("confirm_id"), pending, store, entry.get("field")


def _recompute_drip(pending, service=None, *, per_run=None, runs=None,
                    interval=None, total=None):
    """A drip plan after one edit, or (None, error). Error is one
    of "bad_quantity" (per-run below the service minimum, above
    its maximum, or not a multiple of 10), "bad_runs" (fewer than
    2), "bad_interval" (shorter than 30 minutes), "bad_split" (a
    total that does not split evenly into equal runs), or
    "not_drip" (the card is not a drip plan). Returns
    ({"per_run_qty", "runs", "interval", "quantity", "total"},
    None). Pure: the pending dict is untouched."""
    drip = dict((pending or {}).get("drip") or {})
    if not drip:
        return None, "not_drip"
    service = service if service is not None else (pending or {}).get("service") or {}
    try:
        cur_per = int(drip.get("per_run_qty") or 0)
        cur_runs = int(drip.get("runs") or 0)
        cur_interval = int(drip.get("interval") or 0)
    except (TypeError, ValueError):
        return None, "bad_quantity"
    if per_run is not None:
        cur_per = int(per_run)
    if runs is not None:
        cur_runs = int(runs)
    if interval is not None:
        cur_interval = int(interval)
    if total is not None:
        total = int(total)
        if total <= 0 or cur_runs < 1 or total % cur_runs != 0:
            return None, "bad_split"
        cur_per = total // cur_runs
    if cur_runs < 2:
        return None, "bad_runs"
    if cur_interval < MIN_RECURRING_MINUTES:
        return None, "bad_interval"
    if validate_quantity(cur_per, service) is not None:
        return None, "bad_quantity"
    total_qty = cur_per * cur_runs
    total_cost = estimated_total_etb(
        float(service.get("rate_etb_per_1000") or 0), total_qty
    )
    return {
        "per_run_qty": cur_per, "runs": cur_runs,
        "interval": cur_interval, "quantity": total_qty,
        "total": total_cost,
    }, None


def _drip_card_line(pending, lang):
    """The drip line for a re-shown drip card, in the shape the
    original card used: runs, per-run quantity, interval and the
    last drop."""
    drip = pending.get("drip") or {}
    return (
        f"Drip-feed: {drip.get('runs')} runs of "
        f"{int(drip.get('per_run_qty') or 0):,} every "
        f"{format_interval(drip.get('interval'))}. "
        f"Last drop {_drip_end_text(drip.get('runs'), drip.get('interval'))}."
    )


def _delayed_confirm_text(lang, service, quantity, total, link, run_at,
                          note=None):
    """The Confirm card text for a delayed order, with an optional
    one-line note on top. Same lines handle_delayed_order_text
    builds, so an edited delayed card reads exactly like the
    original one."""
    lines = [t("confirm_title", lang), ""]
    if note:
        lines.append(note)
        lines.append("")
    lines.extend([
        f"{short_service_name(service.get('name'))}",
        f"🔢 {quantity}",
        f"🧾 {format_money(total)} ETB",
        f"🔗 {link}",
        "",
        t("delayed_confirm_note", lang, time=format_eat_run_at(run_at)),
    ])
    return _strip_dashes("\n".join(lines))


async def _reshow_card(update, confirm_id, pending, store, lang, note=None,
                       voice=False):
    """Drop the stale card and re-show the (edited or unchanged)
    Confirm card under the SAME confirm_id, with Confirm/Cancel.
    A drip card always carries its drip line; a delayed card is
    re-built in its own shape."""
    await drop_pending_card(update, pending)
    service = pending.get("service") or {}
    if store == "delayed":
        text = _delayed_confirm_text(
            lang, service, pending["quantity"], pending["total"],
            pending["link"], pending["run_at"], note=note,
        )
    else:
        if pending.get("drip"):
            line = _drip_card_line(pending, lang)
            note = f"{note}\n{line}" if note else line
        text = confirm_card_text(
            lang, service, pending["quantity"], pending["total"],
            pending["link"], note=note,
            full_name=pending.get("full_name", False),
        )
    sent = await reply_message(
        update.message, text, lang,
        reply_markup=confirm_keyboard(confirm_id),
    )
    _remember_card_message(pending, update.message, sent)
    return text


async def apply_card_edit(update, user_id, confirm_id, pending, store,
                          edit, lang, text="", voice=False):
    """Apply one parsed edit to a pending Confirm card IN PLACE
    (same confirm_id, same entry — never a second pending confirm)
    and re-show the full updated card. Returns True when the edit
    was handled with a reply. Nothing is placed: Confirm after an
    edit places the UPDATED order, Cancel still cancels it. The
    price is re-derived from the service rate, and affordability
    is re-checked on the new total (a shortfall warns first, like
    the original card, and the card is still shown). A refused
    edit leaves the card unchanged."""
    service = pending.get("service") or {}
    field = edit["field"]
    value = edit.get("value")
    drip = dict(pending.get("drip") or {}) if store == "pending" else {}
    note = None
    if field == "link":
        # Re-validated the same way the original order flow does:
        # a link from another platform never reaches the card; a
        # wrong link TYPE is the placement backstop's job
        # (place_pending_order refuses it at Confirm with the
        # right-link question), so it is not refused here.
        error = validate_order_link(value, service)
        if error == "platform":
            platform, _hint = _platform_hint_of_service(service)
            await reply_message(
                update.message,
                t(
                    "platform_mismatch", lang,
                    link_platform=platform_from_link(value),
                    platform=(
                        (pending.get("platform") or "").strip().lower()
                        or platform or ""
                    ),
                ),
                lang, voice=voice,
            )
            return True
        pending["link"] = value
        note = t("edit_note", lang, what="link")
    elif field in ("quantity", "per_run", "amount"):
        if field == "amount":
            # What the amount buys, rounded DOWN to a multiple of
            # 10. Rounded first: float division makes exactly
            # 84 ETB at 42 ETB/1000 read as 1999.9999, which the
            # floor would short-change to 1990.
            rate = float(service.get("rate_etb_per_1000") or 0)
            if rate <= 0:
                new_qty = None
            else:
                new_qty = (int(round(float(value) / (rate / 1000))) // 10) * 10
            if new_qty <= 0:
                new_qty = None
        else:
            new_qty = int(value)
        if new_qty is None:
            await reply_message(
                update.message,
                t(
                    "bad_quantity", lang,
                    service=short_service_name(service.get("name")),
                    min=service.get("min"), max=service.get("max"),
                ),
                lang, voice=voice,
            )
            return True
        if drip:
            if field == "per_run":
                vals, err = _recompute_drip(pending, per_run=new_qty)
            else:
                vals, err = _recompute_drip(pending, total=new_qty)
            if err == "bad_split":
                await reply_message(
                    update.message,
                    t("edit_drip_split", lang, runs=drip.get("runs")),
                    lang, voice=voice,
                )
                return True
            if err is not None:
                await reply_message(
                    update.message,
                    t(
                        "bad_quantity", lang,
                        service=short_service_name(service.get("name")),
                        min=service.get("min"), max=service.get("max"),
                    ),
                    lang, voice=voice,
                )
                return True
            pending["drip"].update({
                "per_run_qty": vals["per_run_qty"],
                "runs": vals["runs"],
                "interval": vals["interval"],
            })
            pending["quantity"] = vals["quantity"]
            pending["total"] = vals["total"]
        else:
            if validate_quantity(new_qty, service) is not None:
                await reply_message(
                    update.message,
                    t(
                        "bad_quantity", lang,
                        service=short_service_name(service.get("name")),
                        min=service.get("min"), max=service.get("max"),
                    ),
                    lang, voice=voice,
                )
                return True
            pending["quantity"] = new_qty
            pending["total"] = estimated_total_etb(
                float(service.get("rate_etb_per_1000") or 0), new_qty
            )
        note = t("change_note", lang, quantity=pending["quantity"])
    elif field == "runs":
        if not drip:
            await reply_message(
                update.message, t("edit_no_runs", lang), lang, voice=voice,
            )
            return True
        vals, err = _recompute_drip(pending, runs=int(value))
        if err == "bad_runs":
            CARD_EDIT_PENDING[user_id] = {
                "field": "runs", "confirm_id": confirm_id, "store": store,
            }
            await reply_message(
                update.message, t("ask_runs", lang), lang, voice=voice,
            )
            return True
        if err is not None:
            await reply_message(
                update.message,
                t(
                    "bad_quantity", lang,
                    service=short_service_name(service.get("name")),
                    min=service.get("min"), max=service.get("max"),
                ),
                lang, voice=voice,
            )
            return True
        pending["drip"].update({
            "per_run_qty": vals["per_run_qty"],
            "runs": vals["runs"],
            "interval": vals["interval"],
        })
        pending["quantity"] = vals["quantity"]
        pending["total"] = vals["total"]
        note = t("edit_note", lang, what=f"{vals['runs']} runs")
    elif field == "interval":
        if not drip:
            await reply_message(
                update.message, t("edit_no_interval", lang),
                lang, voice=voice,
            )
            return True
        vals, err = _recompute_drip(pending, interval=int(value))
        if err == "bad_interval":
            CARD_EDIT_PENDING[user_id] = {
                "field": "interval", "confirm_id": confirm_id,
                "store": store,
            }
            await reply_message(
                update.message, t("interval_too_short", lang),
                lang, voice=voice,
            )
            return True
        if err is not None:
            await reply_message(
                update.message,
                t(
                    "bad_quantity", lang,
                    service=short_service_name(service.get("name")),
                    min=service.get("min"), max=service.get("max"),
                ),
                lang, voice=voice,
            )
            return True
        pending["drip"].update({
            "per_run_qty": vals["per_run_qty"],
            "runs": vals["runs"],
            "interval": vals["interval"],
        })
        pending["quantity"] = vals["quantity"]
        pending["total"] = vals["total"]
        note = t(
            "edit_note", lang,
            what=f"every {format_interval(vals['interval'])}",
        )
    elif field == "service":
        try:
            services = await paxyo.services()
        except Exception as exc:
            log.warning("card edit services failed: %s", exc)
            services = []
        new_service = None
        if isinstance(value, dict) and value.get("service_id") is not None:
            new_service, svc_error = resolve_named_service(
                services, value["service_id"]
            )
            if svc_error is not None:
                await reply_message(
                    update.message, t("edit_service_not_found", lang),
                    lang, voice=voice,
                )
                return True
        else:
            picks = pick_services(
                services or [],
                platform=(value or {}).get("platform"),
                service_hint=(value or {}).get("service_hint"),
                limit=100,
            )
            if not picks:
                await reply_message(
                    update.message, t("edit_service_not_found", lang),
                    lang, voice=voice,
                )
                return True
            new_service = _prefer_pick(picks, user_id)
        if drip and new_service.get("dripfeed") is False:
            await reply_message(
                update.message, t("drip_service_no_dripfeed", lang),
                lang, voice=voice,
            )
            return True
        link_error = validate_order_link(pending.get("link"), new_service)
        if link_error == "platform":
            platform, _hint = _platform_hint_of_service(new_service)
            await reply_message(
                update.message,
                t(
                    "platform_mismatch", lang,
                    link_platform=platform_from_link(pending.get("link")),
                    platform=platform or "",
                ),
                lang, voice=voice,
            )
            return True
        if drip:
            vals, err = _recompute_drip(pending, service=new_service)
            if err is not None:
                await reply_message(
                    update.message,
                    t(
                        "bad_quantity", lang,
                        service=short_service_name(new_service.get("name")),
                        min=new_service.get("min"),
                        max=new_service.get("max"),
                    ),
                    lang, voice=voice,
                )
                return True
            pending["drip"].update({
                "per_run_qty": vals["per_run_qty"],
                "runs": vals["runs"],
                "interval": vals["interval"],
            })
            pending["quantity"] = vals["quantity"]
            pending["total"] = vals["total"]
        else:
            if validate_quantity(pending["quantity"], new_service) is not None:
                await reply_message(
                    update.message,
                    t(
                        "bad_quantity", lang,
                        service=short_service_name(new_service.get("name")),
                        min=new_service.get("min"),
                        max=new_service.get("max"),
                    ),
                    lang, voice=voice,
                )
                return True
            pending["total"] = estimated_total_etb(
                float(new_service.get("rate_etb_per_1000") or 0),
                pending["quantity"],
            )
        pending["service"] = new_service
        platform, hint = _platform_hint_of_service(new_service)
        pending["platform"] = platform
        pending["service_hint"] = hint
        note = t(
            "edit_note", lang,
            what=f"service {short_service_name(new_service.get('name'))}",
        )
    elif field == "delay":
        if store != "delayed":
            return False
        pending["run_at"] = delayed_run_at_iso(int(value))
        note = t(
            "edit_note", lang,
            what=f"runs {format_eat_run_at(pending['run_at'])}",
        )
    else:
        return False
    CARD_EDIT_PENDING.pop(user_id, None)
    service = pending.get("service") or {}
    shortfall = await _low_balance_shortfall(
        user_id, service, pending["total"]
    )
    if shortfall is not None:
        short_amount, balance = shortfall
        await reply_message(
            update.message,
            t(
                "low_balance_warning", lang,
                balance=format_money(balance),
                shortfall=format_money(short_amount),
                total=format_money(pending["total"]),
            ),
            lang, voice=voice,
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton(
                    t("deposit_webapp_button", lang,
                      amount=format_money(short_amount)),
                    callback_data=f"depshort:{short_amount:.2f}",
                )
            ]]),
        )
    # A successful edit is a correction to the pending order: log
    # it like the old quantity-change path did, so the failure log
    # still sees it.
    card_text = await _reshow_card(
        update, confirm_id, pending, store, lang, note=note, voice=voice,
    )
    log_confusion(user_id, text, card_text, "correction")
    return True


async def _run_card_edit(update, user_id, edit, lang, text="", voice=False):
    """Run one parsed card edit: ask for the value when it is
    missing (and wait for the next message), or apply it at once.
    Returns True when the edit was handled with a reply."""
    confirm_id, pending, store = _pending_card_for_user(user_id)
    if pending is None:
        return False
    if edit.get("value") is None:
        CARD_EDIT_PENDING[user_id] = {
            "field": edit["field"], "confirm_id": confirm_id,
            "store": store,
        }
        await reply_message(
            update.message, t(_EDIT_ASK_KEYS[edit["field"]], lang),
            lang, voice=voice,
        )
        return True
    return await apply_card_edit(
        update, user_id, confirm_id, pending, store, edit, lang,
        text=text, voice=voice,
    )


async def handle_card_edit_text(update, text, lang, voice=False):
    """A Confirm-card edit in this message, or False when the
    message is not one. Runs before the classifier (see
    handle_order_text): "Lets change the link" never reaches the
    "I did not understand" fallback while a card is pending. A
    value the bot asked for is read here too — the very next
    message after "Which link...?" is the new link. A cancel while
    the bot is waiting for a value drops just the edit question
    and re-shows the unchanged card; the order itself is not
    cancelled by it."""
    user = update.effective_user
    confirm_id, pending, store, field = _stored_edit_card(user.id)
    if pending is not None:
        if is_cancel_request(text):
            CARD_EDIT_PENDING.pop(user.id, None)
            await _reshow_card(
                update, confirm_id, pending, store, lang, voice=voice,
            )
            return True
        edit = parse_card_edit(text, pending, store=store)
        if edit is not None and edit["field"] != field:
            # The user switched to a different field mid-ask.
            CARD_EDIT_PENDING.pop(user.id, None)
            return await _run_card_edit(
                update, user.id, edit, lang, text=text, voice=voice,
            )
        value = _card_edit_value_from_text(field, text, pending)
        if value is None:
            await reply_message(
                update.message, t(_EDIT_ASK_KEYS[field], lang),
                lang, voice=voice,
            )
            return True
        return await apply_card_edit(
            update, user.id, confirm_id, pending, store,
            {"field": field, "value": value}, lang, text=text,
            voice=voice,
        )
    confirm_id, pending, store = _pending_card_for_user(user.id)
    if pending is None:
        return False
    edit = parse_card_edit(text, pending, store=store)
    if edit is None:
        return False
    return await _run_card_edit(
        update, user.id, edit, lang, text=text, voice=voice,
    )


async def handle_change_order(update, text, intent, lang, voice=False):
    """'Change the quantity from 5,000 to 2,000 before it starts.'

    A Confirm card waiting for Confirm is edited in place (new
    quantity, new total, updated card). A half-built order takes the
    new quantity and continues. An order that is already placed
    cannot be changed — the live status is shown instead."""
    user = update.effective_user
    # Editable Confirm card (19 Nov 2026): the classifier can also
    # call a card edit "change_order" — link, runs, interval,
    # amount or service, not just quantity. Those go through the
    # same edit path as the local pre-classifier check, so the card
    # is edited in place instead of falling through to the
    # quantity-only code below.
    _cid, _pending = pending_for_user(user.id)
    if _pending is not None:
        _edit = parse_card_edit(text, _pending, intent=intent, store="pending")
        if _edit is not None:
            await _run_card_edit(
                update, user.id, _edit, lang, text=text, voice=voice,
            )
            return
    _did, _delayed = pending_delayed_for_user(user.id)
    if _delayed is not None:
        _edit = parse_card_edit(text, _delayed, intent=intent, store="delayed")
        if _edit is not None:
            await _run_card_edit(
                update, user.id, _edit, lang, text=text, voice=voice,
            )
            return
    new_qty = intent.get("quantity")
    try:
        new_qty = int(new_qty) if new_qty is not None else None
    except (TypeError, ValueError):
        new_qty = None
    if new_qty is not None and not _quantity_grounded_in_text(text, new_qty):
        # The classifier carries the pending order's quantity
        # forward from conversation history (live bug, 14 Nov
        # 2026: "I want only ❤️ reaction" arrived as a
        # change_order with quantity=10, and the quantity path
        # re-issued the same Pray card instead of the emoji
        # correction running). A quantity the user did not type
        # in this message is not a quantity change — drop it, so
        # the number extraction below and the correction check
        # see only what this message actually said.
        new_qty = None
    if new_qty is None:
        # "change the quantity from 5,000 to 2,000": the last number
        # in the message is the new value.
        nums = re.findall(r"\d[\d,]*", text or "")
        if nums:
            try:
                new_qty = int(nums[-1].replace(",", ""))
            except ValueError:
                new_qty = None
    if new_qty is None:
        # No number: maybe a different reaction emoji for the
        # pending order ("I want only 🙏 reaction") — that re-picks
        # the service instead of failing with "not understood".
        # Or for the order still being built (a PARTIAL draft, no
        # card yet — screenshot bug, 16 Nov 2026): the same
        # correction, keeping the draft.
        if await try_reaction_correction(update, text, lang, voice=voice):
            return
        if await try_draft_reaction_correction(update, text, lang, voice=voice):
            return
        if await try_story_post_correction(update, text, lang, voice=voice):
            return
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    confirm_id, pending = pending_for_user(user.id)
    if pending is not None:
        service = pending["service"]
        error = validate_quantity(new_qty, service)
        if error:
            await reply_message(
                update.message,
                t(
                    "bad_quantity", lang,
                    service=short_service_name(service.get("name")),
                    min=service.get("min"), max=service.get("max"),
                ),
                lang, voice=voice,
            )
            return
        pending["quantity"] = new_qty
        pending["total"] = estimated_total_etb(
            float(service.get("rate_etb_per_1000", 0)), new_qty
        )
        _sent = await reply_message(
            update.message,
            confirm_card_text(
                lang, service, new_qty, pending["total"], pending["link"],
                note=t("change_note", lang, quantity=new_qty),
                full_name=pending.get("full_name", False),
            ),
            lang,
            reply_markup=confirm_keyboard(confirm_id),
        )
        _remember_card_message(pending, update.message, _sent)
        return
    partial = PARTIAL.get(user.id)
    if partial:
        partial["quantity"] = new_qty
        merged = {
            k: partial.get(k)
            for k in ("platform", "service_hint", "link", "quantity", "service_id")
        }
        if merged.get("link") and merged.get("quantity"):
            await complete_order(
                update.message, user.id, merged, lang, voice=voice,
                note=t("change_note", lang, quantity=new_qty),
            )
            return
        PARTIAL[user.id] = {k: v for k, v in merged.items() if v is not None}
        if not merged.get("link"):
            await reply_message(
                update.message,
                ask_link_text(merged.get("platform"), merged.get("service_hint"), lang),
                lang, voice=voice,
            )
        else:
            await reply_message(update.message, t("ask_platform", lang), lang, voice=voice)
        return
    # Already placed (or nothing at all): the live status decides.
    order_id = LAST_ORDER.get(user.id)
    if order_id is None:
        last = await resolve_last_order(user.id)
        if last:
            order_id = last.get("id") or last.get("order_id")
    if order_id is not None:
        await reply_message(
            update.message,
            f"{t('already_placed', lang)}\n"
            f"{await last_order_status_text(user.id, lang)}",
            lang, voice=voice,
        )
        return
    await reply_message(update.message, t("no_order_to_change", lang), lang, voice=voice)


# Refill in chat (15 Nov 2026, feature 3): "refill my last
# order" / "refill order #1841" is a request to refill a finished
# order — a REAL provider refill through POST /orders/{id}/refill
# — not the old "it finished short, contact support" flow. The
# two are told apart by the phrasing: a refill request names the
# refill and the order ("refill my last order", "refill order
# #1841"); a short-delivery complaint ("it stopped at 800 out of
# 1,000, send the rest") keeps the old flow below.
_REFILL_REQUEST_PATTERNS = (
    "refill my last order", "refill my latest order",
    "refill my previous order", "refill my order",
    "refill the last order", "refill last order",
    "refill order", "refill #",
)
_REFILL_COMPLETED_STATUSES = ("completed", "complete", "done", "success", "paid")


def is_refill_request(text: str) -> bool:
    """True when the message asks to refill a specific order
    ("refill my last order", "refill order #1841") — as opposed
    to reporting that an order finished short."""
    s = " ".join((text or "").strip().lower().split())
    return any(p in s for p in _REFILL_REQUEST_PATTERNS)


def _refill_order_id(text: str):
    """The order number in "refill order #1841" / "refill #1841",
    or None when the message names no number (the last order is
    meant then)."""
    m = re.search(r"order\s*#?\s*(\d+)", text or "", re.IGNORECASE)
    if m:
        return int(m.group(1))
    m = re.search(r"#\s*(\d+)", text or "")
    if m:
        return int(m.group(1))
    return None


def _refill_order_status(order) -> str:
    """The stored status of a recent-order row, lowercased."""
    return str(
        (order or {}).get("status")
        or (order or {}).get("order", {}).get("status", "")
        or ""
    ).strip().lower()


async def handle_refill_request(update, text, lang, voice=False):
    """"Refill my last order" / "refill order #1841": resolve the
    order from the user's own recent orders — completed only — and
    show a Confirm card. Nothing is refilled until the user
    confirms. A named order that is not theirs (or not in the
    recent list) gets an honest not-found; a named order that is
    not completed yet is refused with its real status; with no
    completed order at all, the bot says so instead of offering a
    card for an order that cannot be refilled."""
    user = update.effective_user
    wanted = _refill_order_id(text)
    try:
        orders = await paxyo.recent_orders(user.id, limit=20)
    except Exception as exc:
        log.warning("refill recent_orders failed: %s", exc)
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    if not orders:
        await reply_message(
            update.message, t("refill_no_completed", lang), lang, voice=voice
        )
        return
    order = None
    if wanted is not None:
        order = next(
            (o for o in orders
             if str(o.get("id") or o.get("order_id")) == str(wanted)),
            None,
        )
        if order is None:
            await reply_message(
                update.message, t("refill_order_not_found", lang),
                lang, voice=voice,
            )
            return
    else:
        order = next(
            (o for o in orders
             if _refill_order_status(o) in _REFILL_COMPLETED_STATUSES),
            None,
        )
        if order is None:
            first = orders[0]
            await reply_message(
                update.message,
                t(
                    "refill_not_completed", lang,
                    order_id=first.get("id") or first.get("order_id") or "?",
                    status=_refill_order_status(first) or "pending",
                ),
                lang, voice=voice,
            )
            return
    status = _refill_order_status(order)
    if status not in _REFILL_COMPLETED_STATUSES:
        await reply_message(
            update.message,
            t(
                "refill_not_completed", lang,
                order_id=order.get("id") or order.get("order_id") or "?",
                status=status or "pending",
            ),
            lang, voice=voice,
        )
        return
    order_id = order.get("id") or order.get("order_id")
    # Prefer the combined id (second provider, 15 Nov 2026): the
    # refill's re-order resolves the exact service, not the other
    # provider's service of the same bare number.
    service_id = order.get("combined_id")
    if service_id is None:
        try:
            service_id = int(order.get("service_id") or 0) or None
        except (TypeError, ValueError):
            service_id = None
    try:
        quantity = int(order.get("quantity") or 0) or None
    except (TypeError, ValueError):
        quantity = None
    if order_id is None or service_id is None or quantity is None:
        await reply_message(
            update.message, t("refill_order_not_found", lang),
            lang, voice=voice,
        )
        return
    confirm_id = uuid.uuid4().hex[:12]
    PENDING_REFILL[confirm_id] = {
        "user_id": user.id,
        "order_id": order_id,
        "service_id": service_id,
        "service_name": str(order.get("service_name") or ""),
        "link": order.get("link") or "",
        "quantity": quantity,
    }
    service_name = str(order.get("service_name") or "")
    if service_name:
        service_name = short_service_name(service_name)
    else:
        service_name = f"service {service_id}"
    # Confirm card: always text — it carries the buttons.
    await reply_message(
        update.message,
        t(
            "refill_confirm", lang, order_id=order_id,
            service=service_name, quantity=quantity,
            link=order.get("link") or "",
        ),
        lang, voice=voice,
        reply_markup=confirm_keyboard(confirm_id),
    )


async def _build_refill_reorder(user_id: int, refill, lang: str):
    """(card_text, keyboard) for re-placing a refill's order as a
    brand-new order — same service, quantity and link — or None
    when the original service can no longer be ordered. The card
    carries the refill_reorder_note, so the user sees it is a NEW
    order, never a refill. The PENDING entry is created here, so
    the card's Confirm button places it through the normal single
    order path."""
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("refill reorder services failed: %s", exc)
        return None
    service, svc_error = resolve_named_service(services, refill["service_id"])
    if svc_error is not None or service is None:
        return None
    quantity = refill["quantity"]
    error = validate_quantity(quantity, service)
    if error:
        return None
    total = estimated_total_etb(
        float(service.get("rate_etb_per_1000", 0)), int(quantity)
    )
    confirm_id = uuid.uuid4().hex[:12]
    PENDING[confirm_id] = {
        "user_id": user_id,
        "service": service,
        "link": refill["link"],
        "quantity": int(quantity),
        "total": total,
        "full_name": False,
    }
    return (
        confirm_card_text(
            lang, service, int(quantity), total, refill["link"],
            note=t("refill_reorder_note", lang),
        ),
        confirm_keyboard(confirm_id),
    )


async def _run_refill_confirm(user_id: int, refill, lang: str,
                              respond, send_new):
    """Carry out a confirmed refill. `respond(text, reply_markup)`
    replaces/answers the refill card (the callback's
    edit_message_text, or the text-acceptance's reply_text);
    `send_new(text, reply_markup)` sends a fresh message (the
    callback's message reply, or the same reply_text). On a real
    refill the answer names the refill id. On
    refill_supported:false the honest "no refills for this order"
    message goes out first and a SECOND Confirm card for a
    brand-new order of the same service follows — the new order is
    never called a refill."""
    # Ban (19 Nov 2026): a banned user refills nothing.
    if await user_is_banned(user_id):
        await respond(t("banned", lang))
        return
    order_id = refill["order_id"]
    try:
        result = await paxyo.refill_order(order_id, user_id)
    except httpx.HTTPStatusError as exc:
        if exc.response.status_code == 409:
            reason = ""
            try:
                body = exc.response.json()
                if isinstance(body, dict):
                    reason = str(
                        body.get("error") or body.get("message") or ""
                    )
            except Exception:
                reason = ""
            await respond(
                t(
                    "refill_not_refillable", lang,
                    reason=reason or "it isn't available for this order",
                )
            )
            return
        log.warning("refill_order rejected: %s", exc.response.status_code)
        await respond(t("refill_failed", lang))
        return
    except Exception as exc:
        log.warning("refill_order failed: %s", exc)
        await respond(t("refill_failed", lang))
        return
    if result is None:  # 404: the endpoint is not live yet
        await respond(t("refill_not_ready", lang))
        return
    if isinstance(result, dict) and result.get("ok"):
        refill_id = result.get("refill_id") or "?"
        await respond(
            t("refill_done", lang, order_id=order_id, refill_id=refill_id)
        )
        return
    if isinstance(result, dict) and result.get("refill_supported") is False:
        await respond(t("refill_unsupported", lang))
        reorder = await _build_refill_reorder(user_id, refill, lang)
        if reorder is None:
            await send_new(
                t(
                    "refill_not_refillable", lang,
                    reason="the original service is no longer available",
                )
            )
            return
        card_text, markup = reorder
        await send_new(card_text, reply_markup=markup)
        return
    reason = ""
    if isinstance(result, dict):
        reason = str(result.get("error") or "")
    await respond(
        t(
            "refill_not_refillable", lang,
            reason=reason or "it isn't available for this order",
        )
    )


async def handle_refill(update, text, intent, lang, voice=False):
    """'It stopped at 800 out of 1,000, send the rest now.'

    The live status is checked first. Still running -> say so with
    the status. Finished short -> point at support for a refill.
    The bot never promises a refill or a refund, and never places a
    second order without Confirm.

    A message that ASKS for a refill of an order ("refill my last
    order", "refill order #1841") is not this flow — it goes to
    handle_refill_request, which shows a Confirm card for a real
    provider refill of a completed order."""
    if is_refill_request(text):
        await handle_refill_request(update, text, lang, voice=voice)
        return
    user = update.effective_user
    order_id = LAST_ORDER.get(user.id)
    if order_id is None:
        last = await resolve_last_order(user.id)
        if last:
            order_id = last.get("id") or last.get("order_id")
    if order_id is None:
        await reply_message(update.message, t("no_orders", lang), lang, voice=voice)
        return
    try:
        data = await paxyo.order_status(order_id, user.id)
    except Exception as exc:
        log.warning("refill order_status failed: %s", exc)
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    status = str(
        data.get("status") or data.get("order", {}).get("status", "?")
    ).strip().lower()
    if status in ("pending", "in_progress", "processing", "partial",
                  "in progress"):
        await reply_message(
            update.message, t("refill_running", lang, status=status),
            lang, voice=voice,
        )
        return
    if status in ("completed", "complete", "done"):
        await reply_message(update.message, t("refill_finished", lang), lang, voice=voice)
        return
    await reply_message(
        update.message, await last_order_status_text(user.id, lang),
        lang, voice=voice,
    )


async def handle_order_wait(update, text, lang, voice=False):
    """'Why hasn't it started yet? It's been 45 seconds.'

    The real status plus the service's average time, so the answer
    is a real start window — never a bare 'soon'. Falls back to the
    plain status line when no average time is known."""
    user = update.effective_user
    last = await resolve_last_order(user.id)
    order_id = LAST_ORDER.get(user.id)
    if order_id is None and last:
        order_id = last.get("id") or last.get("order_id")
    if order_id is None:
        await reply_message(update.message, t("no_orders", lang), lang, voice=voice)
        return
    try:
        data = await paxyo.order_status(order_id, user.id)
    except Exception as exc:
        log.warning("order wait status failed: %s", exc)
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    status = str(
        data.get("status") or data.get("order", {}).get("status", "?")
    ).strip()
    # Prefer the combined id (second provider, 15 Nov 2026): the
    # bare id alone could read the other provider's average time.
    service_id = (last or {}).get("combined_id") or (last or {}).get("service_id")
    service_name = (last or {}).get("service_name")
    avg = None
    if service_id is not None:
        try:
            services = await paxyo.services()
            found = find_service_by_id(services, service_id)
            if found is not None:
                avg = found.get("average_time")
                service_name = found.get("name")
        except Exception as exc:
            log.warning("order wait services failed: %s", exc)
    if avg:
        await reply_message(
            update.message,
            t(
                "order_wait", lang, order_id=order_id, status=status,
                service=short_service_name(service_name)
                or f"service {service_id}",
                avg=avg,
            ),
            lang, voice=voice,
        )
        return
    await reply_message(
        update.message, await last_order_status_text(user.id, lang),
        lang, voice=voice,
    )


async def handle_max_for_balance(update, text, intent, lang, voice=False):
    """'Give me however many views my remaining 42.50 birr can buy.'

    Reverse-calculates from the real balance: floor(balance /
    price-per-unit), rounded down to a multiple of 10, capped by the
    service min/max. Shown on a Confirm card like any other order.
    When the balance buys less than the minimum, say so and suggest
    a deposit."""
    user = update.effective_user
    try:
        data = await paxyo.balance(user.id)
    except Exception as exc:
        log.warning("max-for-balance failed: %s", exc)
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    if not data.get("found"):
        await reply_message(update.message, t("greeting", lang), lang, voice=voice)
        return
    balance = float(data.get("balance", 0))
    platform = (intent.get("platform") or "").strip().lower() or None
    hint = intent.get("service_hint")
    last_service_id = None
    if not platform and not hint:
        last = await resolve_last_order(user.id)
        if last and last.get("service_id"):
            last_service_id = last.get("combined_id") or last.get("service_id")
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("max-for-balance services failed: %s", exc)
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    service = None
    if last_service_id is not None:
        service = find_service_by_id(services, last_service_id)
        if service is not None and not service.get("active", True):
            service = None
    if service is None:
        picks = pick_services(services, platform=platform, service_hint=hint)
        if not picks:
            await reply_message(
                update.message,
                no_service_reply(platform, hint, text, lang)
                or t("no_service", lang),
                lang, voice=voice,
            )
            return
        service = picks[0]
    rate = float(service.get("rate_etb_per_1000", 0) or 0)
    if rate <= 0:
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    max_qty = int(balance / (rate / 1000))
    max_qty = (max_qty // 10) * 10
    max_qty = min(max_qty, int(service.get("max", 0) or max_qty))
    if max_qty < int(service.get("min", 0) or 0):
        await reply_message(
            update.message,
            t("max_for_balance_none", lang, balance=format_money(balance)),
            lang, voice=voice,
        )
        return
    metric = hint or short_service_name(service.get("name"))
    link = intent.get("link")
    note = t(
        "max_for_balance_offer", lang, balance=format_money(balance),
        quantity=max_qty, metric=metric,
    )
    if link:
        merged = {
            "platform": platform, "service_hint": hint,
            "link": link, "quantity": max_qty,
        }
        await complete_order(
            update.message, user.id, merged, lang, voice=voice,
            named_service_id=service.get("service"), note=note,
        )
        return
    # No link yet: remember the computed quantity and ask for it.
    PARTIAL[user.id] = {
        "platform": platform, "service_hint": hint, "quantity": max_qty,
    }
    await reply_message(update.message, note, lang, voice=voice)


async def handle_cheapest_reply(update, intent, lang, voice, key):
    """One real answer for haggling, free samples and price pushback:
    the cheapest real service at its real Paxyo price. Prices are
    fixed — the bot never negotiates and never applies a
    user-supplied price anywhere."""
    user = update.effective_user
    platform = (intent.get("platform") or "").strip().lower() or None
    hint = intent.get("service_hint")
    if not platform and not hint:
        # "Something cheaper" in the middle of an order names no
        # platform of its own: stay on the platform and metric
        # already in the conversation.
        platform, hint = _conversation_context(user.id)
    quantity = intent.get("quantity")
    try:
        quantity = int(quantity) if quantity is not None else None
    except (TypeError, ValueError):
        quantity = None
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("cheapest lookup failed: %s", exc)
        await reply_message(update.message, t("not_understood", lang), lang, voice=voice)
        return
    service = cheapest_service(services, platform=platform, service_hint=hint)
    if service is None:
        await reply_message(
            update.message,
            no_service_reply(platform, hint, "", lang)
            or t("no_service", lang),
            lang, voice=voice,
        )
        return
    metric = hint or short_service_name(service.get("name"))
    if quantity is None:
        quantity = int(service.get("min", 0) or 0)
    service_max = int(service.get("max", 0) or 0)
    if service_max and quantity > service_max:
        # Never offer a quantity the service cannot take.
        quantity = service_max
    price = (
        f"{format_money(estimated_total_etb(float(service.get('rate_etb_per_1000', 0)), quantity))} "
        f"ETB for {quantity}"
    )
    await reply_message(
        update.message,
        with_pending_note(
            user.id, lang,
            t(
                key, lang, metric=metric,
                service=short_service_name(service.get("name")),
                price=price,
            ),
        ),
        lang, voice=voice,
    )


async def handle_order_text(update: Update, context: ContextTypes.DEFAULT_TYPE,
                            text: str, voice: bool = False, intent: dict = None,
                            quoted_text: str = None):
    """Shared flow for text messages and transcribed voice messages.

    Reply rules (owner, 13 Nov 2026):
    - Text in -> text out, always. Voice in -> voice out, except the
      Confirm card and the post-acceptance summary, which are always
      text (a voice message cannot carry buttons, and a voice
      confirmation must end with a readable text record of the order).
    - A bare acceptance ("yes", "confirm", "አዎ", ...) while an order
      is pending places that order — no new intent is extracted.
    - Gemini first classifies the message (order, recurring, schedules,
      stop_schedule, balance, orders, deposit, deposit_status,
      auto_refill, auto_refill_status, auto_refill_stop,
      how_to_order, how_to, miniapp, social, help, greeting,
      paxyo_info, source_question, reseller, contact, paused_services, usual, goal,
      budget, batch, change_order, refill, split_payment,
      max_for_balance, discount, safety, refund_policy, geo_target,
      free_sample, price_pushback, content_help, support_issue,
      cancel, off_topic, unclear). EXCEPT a simple chat message
      (plain greeting, question about Paxyo, help / how-to-order /
      how-to) is pinned down locally first and skips the classify
      call entirely (simple_chat_intent, 17 Nov 2026) — one AI call
      (or none) instead of two.
      Conversational intents are answered before the order flow, so the bot talks like
      customer support instead of only understanding orders;
      a real question always gets a free AI answer (owner,
      14 Nov 2026) — only non-question chit-chat is steered back
      to ordering, from the third turn.
    - Asked where the services come from, or what Paxyo pays for them,
      the bot deflects in one short line (local guard first, then the
      "source_question" intent) — it never names a supplier, never
      gives a figure, and never says the supply chain's name.
    - Deposits are built over several turns (amount -> method ->
      phone) and shown as a Confirm summary; nothing is created
      until confirmed. Typos and slang are normalised first
      ("teleirr" -> "telebirr"), so misspelled messages still
      classify.
    - Orders are built over several turns: what the user already gave
      (platform, service, link, quantity) is remembered per user in
      PARTIAL, so a bare "2000" after a link completes the order. A
      different platform starts a new order; cancelling clears it.
    - A service the user names ("use service 6139", "the cheapest
      Instagram followers", "same service as last time") is used for
      that order instead of the fastest one — validated first (it must
      exist, be active and not be blacklisted). A bad named service is
      refused in one line with a one-tap "Use the fastest one" button.
    - "That link" resolves from the user's most recent order (the
      Paxyo API, so it survives restarts), and a repeating-order plan
      ("every 3 hours") is built the same way, then shown as a plan
      summary with Confirm — nothing repeats until confirmed.
    - Orders work in Amharic, Tigrinya, Oromo and English, by text.
      (Voice messages are still transcribed when sent, but the bot
      does not claim to take orders by voice — owner, 13 Nov 2026.)
      The reply is always in the language of the user's current
      message (owner, 14 Nov 2026): English in -> English out,
      Amharic in -> Amharic out, and the same for Tigrinya and
      Oromo — never the previous turn's language.
    - A user replying TO one of the bot's messages (a quote) is read
      in that context: "1000" replied to "How many?" is the quantity;
      "yes" replied to a Confirm card confirms it. See
      reply_or_bare_intent, checked before the classifier.
    """
    # Turn timing (17 Nov 2026 — a live reply took 29s while both
    # AI calls took under 1s each): one log line per stage, timings
    # + intent type only, so the next slow reply shows exactly
    # where its seconds went instead of being guessed at. `age` is
    # the time from Telegram's own timestamp on the message to this
    # handler starting — a large age means the update waited (queue
    # / delivery: PTB handles updates one at a time), not that the
    # bot worked slowly. Never logs the message text.
    _t0 = time.monotonic()
    try:
        _msg_date = getattr(update.message, "date", None)
        _age = time.time() - _msg_date.timestamp() if _msg_date is not None else -1.0
    except Exception:
        _age = -1.0
    if _age >= 0:
        log.info("turn received age %.2fs", _age)
    _intent_source = "injected" if intent is not None else "local"
    user = update.effective_user
    # Tolerate typos and slang before anything else: the classifier,
    # the acceptance check and the follow-up parsers all see the
    # cleaned text. URLs are kept verbatim (case-sensitive links).
    text = normalize_text(text)
    # Reply in the language of THIS message (owner, 14 Nov 2026):
    # the bridge flag is reset every turn, so a bridged turn can
    # never leak into the next one.
    _set_bridge_lang(None)
    _detected = detect_language(text, user.language_code)
    lang = _detected
    # Translate-bridge (owner, 13 Nov 2026; Oromo and Tigrinya
    # added 14 Nov 2026): a message in Amharic, Tigrinya or Oromo
    # is translated to English by Gemini first, so the whole flow
    # below runs in English and the main AI never has to guess the
    # language. Prose replies are translated back before sending
    # (see reply_message). Only non-English text triggers it —
    # English never touches the bridge. If translation fails or
    # comes back unchanged, the original text is used and the local
    # handling applies untouched.
    if _detected in ("am", "ti", "om"):
        _english = await translate_to_english(text, source_lang=_detected)
        if _english and _english.strip() != text.strip():
            text = _english
            lang = "en"
            _set_bridge_lang(_detected)
    # Conversation memory: remember who is speaking and what they
    # said, so the bot's first reply of this turn is recorded.
    # The detected language is also remembered per user: the next
    # voice note's transcription retry hints it (owner, 14 Nov
    # 2026 — an Amharic voice note must not be auto-detected as
    # Arabic on the retry).
    _CURRENT_USER_ID.set(user.id)
    _LAST_USER_TEXT.set(text)
    LAST_LANG[user.id] = _detected
    # Session store (smart-loop round 1, 14 Nov 2026): a fresh
    # process restores this user's history and order draft from
    # the API, so a restart or redeploy does not wipe the chat.
    # The restore runs in the background (17 Nov 2026: the three
    # API calls took ~7s in sequence and every first turn after a
    # restart paid it) — this turn answers from fresh state at
    # once and the restore lands a moment later for the next
    # turn. The _SESSION_RESTORED guard is claimed synchronously
    # by the kick-off, so a second turn arriving while the
    # restore is in flight never starts a second one.
    schedule_session_restore(user.id)
    _turn_log("session", _t0)
    # Language lock (#37): the customer set a fixed reply
    # language — it overrides this message's detected language
    # (and the bridge direction), so every reply follows the
    # lock. The lock lives in the prefs the background restore
    # loads, so on the first turn after a restart the restore
    # may not have landed yet and the detected language is used
    # until then; from the next turn the lock applies.
    # LAST_LANG follows the lock too, so scheduler messages use
    # it as well.
    _locked_lang = get_pref(user.id, "pref_language")
    if _locked_lang:
        lang = _locked_lang
        _detected = _locked_lang
        LAST_LANG[user.id] = _locked_lang
        _set_bridge_lang(
            _locked_lang if _locked_lang != "en" else None
        )
    # Abandoned-order nudge (feature 4, 15 Nov 2026): a message
    # from the user means they are not quiet — stamp the draft's
    # last-activity time so the scheduler's 30-minute clock
    # restarts. Runs for every message while a draft exists, even
    # a balance question: quiet means no messages at all.
    touch_partial_activity(user.id)

    # "Forget what you know about me" (feature 5, 15 Nov 2026):
    # the user can wipe their learned traits at any time — the
    # server row AND the in-memory mirror + counters. The session
    # (history/draft/language) is untouched. Answered here, before
    # the classifier, so it is never misread as an order.
    if is_forget_traits_request(text):
        await forget_traits(user.id)
        await reply_message(
            update.message, t("traits_forgotten", lang), lang, voice=voice,
        )
        return

    # Per-customer settings (customizations, 15 Nov 2026): "what
    # are my settings", "cheapest first", "my link is ...", "don't
    # message me at night" — handled in plain words, in the user's
    # language. Runs right after the forget-traits check, before
    # anything else: a settings command never leaks into an order,
    # and the parser never matches an order message.
    if await handle_settings_text(update.message, user.id, text, lang, voice):
        await _park_order_and_note(update, user.id, lang, voice=voice)
        return

    # Declining the Friday offer by typing "no" / "not today"
    # (feature 5): ends the offer quietly — no nagging, and no
    # re-offer this week (FRIDAY_OFFERED already holds the week's
    # key from when the offer was sent). Only read while an offer
    # is open, so a "no" anywhere else keeps its normal meaning.
    # Runs here, before the free-chat branch: "no thanks" is free
    # chat ("thanks"), and would otherwise be answered as small
    # talk instead of ending the offer.
    if user.id in FRIDAY_PENDING and is_friday_decline(text):
        FRIDAY_PENDING.pop(user.id, None)
        FRIDAY_LINK.pop(user.id, None)
        await reply_message(
            update.message, t("friday_declined", lang), lang, voice=voice,
        )
        return

    # Report a problem (ideas batch 2, feature 2, 15 Nov 2026):
    # a typed report request, a complaint replied to a delivery or
    # order message, or the next message of an open report flow.
    # Deterministic, before the classifier — the same "orders"
    # phrasing would otherwise show the history table. Runs here,
    # before the quick-reply buttons and the offensive guard, so a
    # frustrated complaint starts the report instead of being
    # pushed back, and a description is never misread as an order.
    if await handle_report_text(
        update, text, lang, voice=voice, quoted_text=quoted_text
    ):
        return

    # Feedback follow-up (feature 10, 15 Nov 2026): the next
    # message after a 👎 tap on "How was your first order?" — the
    # answer is filed as a support report against that order, or
    # the flow is dropped on "cancel" with nothing filed.
    if await handle_feedback_text(update, text, lang, voice=voice):
        return

    # Persistent quick-reply buttons (ideas batch, 15 Nov 2026):
    # a tap is a deterministic shortcut, handled before the
    # classifier — never fed to the AI. A typed label does the
    # same thing. "Order" starts a fresh order; the rest reuse
    # the existing intent handlers' replies.
    quick = quick_reply_action(text)
    if quick is not None:
        if quick == "order":
            # Deposit-hijack fix (16 Nov 2026): a parked draft
            # resumes here — saying "order" continues the saved
            # order; otherwise a fresh order starts as before.
            # Only when no draft is being built right now: a
            # parked draft must never overwrite the live one.
            if (
                not PARTIAL.get(user.id)
                and _resume_parked_draft(user.id) is not None
            ):
                await _continue_parked_draft(
                    update.message, user.id, lang, voice=voice
                )
                return
            PARTIAL.pop(user.id, None)
            RECURRING_DRAFT.pop(user.id, None)
            DELAYED_DRAFT.pop(user.id, None)
            BUNDLE_DRAFT.pop(user.id, None)
            # Late-reply fix (16 Nov 2026): a plain "order" gets
            # this instant line, no AI call — the user is told what
            # to send next (service + link) instead of waiting on
            # the classifier for a platform question.
            await reply_message(
                update.message, t("order_prompt", lang), lang, voice=voice,
            )
            return
        # Any other flow switch parks the open order draft first
        # (deposit-hijack fix, 16 Nov 2026): the draft is saved,
        # not lost, and the user is told in one short line. The
        # deposit switch parks inside handle_deposit_text instead
        # (it also covers the typed-deposit path), so it is not
        # parked twice here.
        if quick != "deposit" and _park_order_draft(user.id):
            await reply_message(
                update.message, t("draft_parked", lang), lang, voice=voice,
            )
        # A bundle draft is dropped on a flow switch (ideas batch 1
        # #3): it has no parked resume, so it must not eat the next
        # message after the user switched away.
        BUNDLE_DRAFT.pop(user.id, None)
        if quick == "balance":
            await reply_message(
                update.message, await balance_text(user.id, lang),
                lang, voice=voice,
            )
            return
        if quick == "orders":
            markup = None
            try:
                orders = await paxyo.recent_orders(user.id)
                if orders:
                    markup = reorder_keyboard(orders)
            except Exception as exc:
                log.warning("quick orders keyboard failed: %s", exc)
            await reply_message(
                update.message, await orders_history_text(user.id, lang),
                lang, voice=voice, reply_markup=markup,
            )
            return
        if quick == "deposit":
            await handle_deposit_text(update, text, {}, lang, voice=voice)
            return
        if quick == "support":
            await reply_message(
                update.message,
                with_pending_note(user.id, lang, t("contact_owner", lang)),
                lang, voice=voice,
            )
            return

    # Per-user personality (feature 5, 15 Nov 2026): learn the
    # user's tone from their own message — one vote per message,
    # never from a single message, never from the bot's replies.
    # Quick-reply taps return above, so a button tap is never a
    # tone vote; everything else the user typed is.
    observe_tone(user.id, text)

    # Arabic-script text (owner, 14 Nov 2026): the bot has no
    # Arabic templates and must never mirror Arabic back. It can
    # only arrive from a mis-transcribed voice note (a transcriber
    # mis-detecting Amharic as Arabic) or a typed message
    # in a language the bot does not speak. Answer honestly
    # instead of feeding it to the classifier or the AI.
    if _has_arabic_script(text):
        await reply_message(
            update.message, t("not_understood_language", lang),
            lang, voice=voice,
        )
        return

    # Offensive users (owner, 13 Nov 2026): push back firmly and
    # bluntly — never polite, never apologetic. A second insult in
    # the same exchange refuses to continue; a third goes silent.
    # The bot itself never uses slurs back. Any non-offensive
    # message resets the count.
    if is_offensive(text):
        count = OFFENSE_COUNT.get(user.id, 0) + 1
        OFFENSE_COUNT[user.id] = count
        if count >= 3:
            return
        if count >= 2:
            await reply_message(update.message, t("offensive_refusal", lang), lang, voice=voice)
            return
        await reply_message(update.message, t("offensive_pushback", lang), lang, voice=voice)
        return
    OFFENSE_COUNT.pop(user.id, None)

    # "please order now" with a Confirm card pending (owner override,
    # 13 Nov 2026): place the pending order at once, no second card.
    if is_order_now(text):
        _cid, _pending = pending_for_user(user.id)
        if _pending is not None:
            PENDING.pop(_cid, None)
            await send_order_result(update.message, lang, _pending, user.id)
            return

    # The user wants to sell Paxyo's services themselves, or to
    # reach customer support (next batch, 14 Nov 2026): answer at once,
    # without calling Gemini, and before free-chat handling — a
    # short "I need support" must not become a generic chat reply.
    # The reseller check runs before the source-question guard
    # below: "resell" is a source-question word, but "I want to
    # resell" is the user asking to sell, not asking about Paxyo's
    # supplier. Both answers are one short line with the contact,
    # so asking again just repeats it.
    if intent is None and is_reseller_request(text):
        await _park_order_and_note(update, user.id, lang, voice=voice)
        await reply_message(
            update.message, t("reseller_contact", lang), lang, voice=voice
        )
        return
    if intent is None and is_contact_request(text):
        await _park_order_and_note(update, user.id, lang, voice=voice)
        await reply_message(
            update.message, t("contact_owner", lang), lang, voice=voice
        )
        return

    # Premium subscriptions and SMS OTP verification are paused
    # (owner, 14 Nov 2026): answer at once, without calling Gemini,
    # and before free-chat handling — "do you sell CapCut Pro" must
    # not become a generic chat reply or an order. One short line,
    # no date, no price, never a social-media service instead.
    if intent is None and is_paused_services_request(text):
        await _park_order_and_note(update, user.id, lang, voice=voice)
        await reply_message(
            update.message, t("paused_services", lang), lang, voice=voice
        )
        return

    # In-chat invite codes (both-sides referral bonus, 16 Nov 2026):
    # a typed REF code registers the referrer — it must never reach
    # the promo branch, which used to answer it with the
    # invite-friends card (live bug, 19:27 EAT 16 Nov 2026).
    if intent is None and await handle_invite_code_text(update, text, lang, voice=voice):
        return

    # Promo codes (ideas batch 2, feature 1, 15 Nov 2026): a bare
    # code-shaped token, or "my code is X", is validated against the
    # server before anything else can misread it — but only when
    # nothing is being built and no Confirm card is pending, so a
    # code typed mid-order or mid-deposit never hijacks that draft.
    if intent is None and await handle_promo_text(update, text, lang, voice=voice):
        return

    # A bare quantity + reaction emoji ("10 🙏", "🙏 10") or a bare
    # 🙏 starts a Telegram reactions order (owner, 14 Nov 2026 —
    # live retest: "10 🙏" alone got "I did not understand", and
    # the bare link after it asked "Which platform?"). The draft
    # carries platform Telegram + the emoji, so the link the user
    # sends next completes the order instead of asking for the
    # platform. Skipped while a Confirm card is pending: there the
    # normal flow handles the emoji as a correction and the number
    # as a quantity change.
    _reaction_start = bare_reaction_order(text)
    if _reaction_start is not None:
        _cid, _pending = pending_for_user(user.id)
        if _pending is None:
            _emoji, _qty = _reaction_start
            _draft = {
                "platform": "telegram",
                "service_hint": "telegram reactions",
                "reaction_emoji": _emoji,
            }
            if _qty is not None:
                _draft["quantity"] = _qty
            PARTIAL[user.id] = _draft
            await reply_message(
                update.message,
                ask_link_text("telegram", "telegram reactions", lang),
                lang, voice=voice,
            )
            return

    # A bare non-reaction emoji is a media reaction (owner, 14
    # Nov 2026): the AI reacts first, naturally — only a genuinely
    # delayed or failed order adds one short line. It never touches
    # the draft or the Confirm card. Reaction emoji take the
    # reactions path below instead.
    _media_emoji = _bare_non_reaction_emoji(text)
    if _media_emoji is not None:
        if await media_reply_for_text(update, _media_emoji, lang, voice=voice):
            return

    # A conversational message mid-order (round 8, 14 Nov 2026):
    # "do you understand", "what do you mean", free chat — answer
    # like a normal AI first, then continue the order. Never
    # swallowed by the link prompt. The draft and any Confirm card
    # stay untouched.
    if await conversation_reply(update, text, lang, voice=voice):
        return

    # A bare reaction emoji (round 8.1, 14 Nov 2026): "👍" is a
    # reply, not a new order — it is the reaction the user wants.
    # Only a message that IS just the emoji takes this branch: a
    # full order message that merely contains one ("I want 👍
    # reactions for … 1000") goes through the order flow as usual.
    # In a reactions order context (a reactions draft is being
    # built, or a reactions Confirm card is pending) it is
    # acknowledged as that choice first, then the link is asked
    # for, and it is stored in the draft so the picker matches
    # the family. With no order context at all it gets a natural
    # reply, never the stock link request on its own — and the
    # draft is still started (service_hint "reactions"), so the
    # link the user sends next completes a reactions order. A bare
    # emoji while a NON-reactions order is being built is just an
    # acknowledgement — it falls through to the normal flow, it
    # never hijacks that order into reactions. (It runs before
    # reply_or_bare_intent so the emoji is never misread as a
    # service search.)
    emoji = reaction_emoji(text)
    _bare_emoji = (
        emoji is not None
        and (text or "").strip().replace("\ufe0f", "")
        == emoji.replace("\ufe0f", "")
    )
    if _bare_emoji:
        _cid, _pending = pending_for_user(user.id)
        _stored = PARTIAL.get(user.id) or {}
        _is_reactions_pending = _pending is not None and "reaction" in (
            short_service_name((_pending.get("service") or {}).get("name"))
            + " "
            + str((_pending.get("service") or {}).get("category") or "")
        ).lower()
        _is_reactions_draft = "reaction" in (
            _stored.get("service_hint") or ""
        ).lower()
        if _is_reactions_pending or _is_reactions_draft:
            if _is_reactions_draft:
                _stored["reaction_emoji"] = emoji
                PARTIAL[user.id] = {
                    k: v for k, v in _stored.items() if v is not None
                }
            await reply_message(
                update.message,
                t("emoji_ack_order", lang, emoji=emoji),
                lang, voice=voice,
            )
            return
        if _pending is None and not _stored:
            PARTIAL[user.id] = {
                "service_hint": "reactions", "reaction_emoji": emoji,
            }
            await reply_message(
                update.message,
                t(
                    "emoji_ack_fresh", lang, emoji=emoji,
                    meaning=EMOJI_MEANINGS.get(emoji, ""),
                ),
                lang, voice=voice,
            )
            return

    # Catch-all for a bare emoji the reactions path did not claim
    # (owner, 14 Nov 2026 — "he also misunderstood the emoji"): a
    # bare 👀, 😤 ... is a reaction, not a failed order, and a
    # bare reaction emoji while a Confirm card is pending is an
    # acknowledgement, not a new order. Both get the AI's natural
    # reaction, like a GIF — never "I did not understand". A bare
    # reaction emoji while a
    # NON-reactions draft is being built keeps the old behaviour
    # (the flow below re-asks for the missing piece), so this
    # only fires for an emoji the reactions path does not claim,
    # or while a card is pending. The draft and the card are never
    # touched.
    if _is_bare_emoji(text):
        _cid, _pending = pending_for_user(user.id)
        if emoji is None or _pending is not None:
            _first = emoji_meanings(text)
            await media_reply_for_text(
                update, _first[0][0] if _first else None, lang,
                voice=voice,
            )
            return

    # Bare-quantity answers and replies to the bot's questions are
    # read before the classifier, so "1000 please" after "How many?"
    # (or "1000" replied TO that message) completes the order
    # instead of being misread as a service search.
    if intent is None:
        intent = reply_or_bare_intent(text, quoted_text, user.id)

    # The promo-code question (ideas batch 2, feature 1, 15 Nov
    # 2026) is one-shot: the very next message either confirms it
    # ("yes" validates the code), declines it ("no" drops it), or
    # moves on (any other message drops it too), so a stale offer
    # can never fire later. A "yes" while a Confirm card is pending
    # belongs to that card, not the offer — the acceptance block
    # below places the order, and the offer is dropped as stale.
    if user.id in PROMO_OFFER:
        if is_acceptance(text) and not _promo_busy(user.id):
            _code = PROMO_OFFER.pop(user.id, None)
            await handle_promo_code(update, _code, lang, voice=voice)
            return
        if is_promo_decline(text):
            PROMO_OFFER.pop(user.id, None)
            await reply_message(
                update.message, t("promo_no", lang), lang, voice=voice,
            )
            return
        PROMO_OFFER.pop(user.id, None)

    # Bare acceptance of a pending order: place it and answer with the
    # full order summary IN TEXT. Checked before intent extraction, so
    # a "yes" is never misread as a new order.
    if is_acceptance(text):
        confirm_id, pending = pending_for_user(user.id)
        if pending is not None:
            PENDING.pop(confirm_id, None)
            await send_order_result(update.message, lang, pending, user.id)
            return
        # A "yes" can also confirm a repeating-order plan awaiting
        # Confirm: create the schedule and answer with a short text
        # confirmation (a plan summary is always text).
        rec_id, rec_draft = pending_recurring_for_user(user.id)
        if rec_draft is not None:
            PENDING_RECURRING.pop(rec_id, None)
            schedule, error = await start_recurring_plan(rec_draft, user.id)
            if error:
                await update.message.reply_text(t("plan_failed", lang))
                return
            await update.message.reply_text(
                t(
                    "plan_started",
                    lang,
                    quantity=rec_draft["quantity"],
                    service=short_service_name(rec_draft["service"].get("name")),
                    interval=format_interval(rec_draft["interval_minutes"]),
                )
            )
            return
        # A "yes" can also confirm an auto-refill setup awaiting
        # Confirm: switch it on (memory + server when the refill
        # endpoint is live) and answer with a short text
        # confirmation.
        auto_id, auto_setup = pending_auto_refill_for_user(user.id)
        if auto_setup is not None:
            PENDING_AUTO_REFILL.pop(auto_id, None)
            await refill_store_create(auto_setup, user.id)
            await update.message.reply_text(
                t(
                    "auto_refill_started",
                    lang,
                    service=short_service_name(
                        (auto_setup.get("service") or {}).get("name")
                    ),
                    trigger=auto_refill_trigger_text(
                        auto_setup.get("trigger"),
                        auto_setup.get("target"), lang,
                    ),
                    limit=auto_refill_limit_text(
                        auto_setup.get("daily_cap"), lang,
                    ),
                )
            )
            return
        # A "yes" can also confirm a one-time delayed order awaiting
        # Confirm: schedule it and answer with a short text
        # confirmation (a scheduled order is always text).
        delay_id, delay_draft = pending_delayed_for_user(user.id)
        if delay_draft is not None:
            PENDING_DELAYED.pop(delay_id, None)
            record, error = await delayed_store_create(delay_draft, user.id)
            if error:
                await update.message.reply_text(t("delayed_save_failed", lang))
                return
            await update.message.reply_text(
                t(
                    "delayed_started",
                    lang,
                    quantity=delay_draft["quantity"],
                    service=short_service_name(delay_draft["service"].get("name")),
                    time=format_eat_run_at(delay_draft["run_at"]),
                )
            )
            return
        # A "yes" can also confirm a deposit awaiting Confirm: start
        # it and answer with the payment instructions IN TEXT (they
        # carry a link/code the user must read, so voice is wrong).
        # A second "yes" while the first is still starting the
        # deposit (19 Nov 2026): the first "yes" already popped
        # the draft, so this check must come before the lookup —
        # say it is starting, never start it twice.
        if user.id in DEPOSIT_CONFIRM_IN_FLIGHT.values():
            await update.message.reply_text(
                t("deposit_confirm_processing", lang)
            )
            return
        dep_id, dep_draft = pending_deposit_for_user(user.id)
        if dep_draft is not None:
            PENDING_DEPOSIT.pop(dep_id, None)
            DEPOSIT_CONFIRM_IN_FLIGHT[dep_id] = user.id
            try:
                result, error = await start_deposit(dep_draft, user.id)
                # Ban (19 Nov 2026): a banned user deposits nothing.
                if error == "banned":
                    await update.message.reply_text(t("banned", lang))
                    return
                if error:
                    if error in ("deposit_not_ready", "deposit_failed", "deposit_unavailable"):
                        # The push could not be sent: offer the deposit
                        # page embedded in Telegram instead of a bare
                        # paxyo.et text. Keep the failed draft so the
                        # "Try again" button can restart it (ideas
                        # batch, 15 Nov 2026).
                        FAILED_DEPOSIT[user.id] = dict(dep_draft)
                        text, markup = deposit_webapp_message(
                            dep_draft["amount"], lang,
                            allow_retry=True, user_id=user.id,
                        )
                        await update.message.reply_text(text, reply_markup=markup)
                    else:
                        await update.message.reply_text(_strip_dashes(error))
                    return
                await update.message.reply_text(
                    t(
                        "deposit_popup_ready", lang,
                        amount=format_money(dep_draft["amount"]),
                    ),
                    reply_markup=deposit_success_markup(result, dep_draft, lang),
                )
            finally:
                DEPOSIT_CONFIRM_IN_FLIGHT.pop(dep_id, None)
            return
        # A "yes" can also confirm a batch of orders awaiting Confirm:
        # place them all and answer with one short line per order.
        batch_id, batch = pending_batch_for_user(user.id)
        if batch is not None:
            PENDING_BATCH.pop(batch_id, None)
            results, error = await place_batch(batch, user.id)
            if error:
                key = error[0]
                if key == "insufficient":
                    await update.message.reply_text(
                        t(
                            "insufficient",
                            lang,
                            balance=format_money(error[1]),
                            total=format_money(error[2]),
                        ),
                        reply_markup=deposit_webapp_keyboard(lang),
                    )
                else:
                    await update.message.reply_text(t(key, lang))
                return
            await update.message.reply_text(batch_result_text(results, lang))
            return
        # A "yes" can also confirm a post bundle awaiting Confirm:
        # place its three legs and answer with one short line per
        # leg (ideas batch 1 #3, 16 Nov 2026).
        bundle_id, bundle = pending_bundle_for_user(user.id)
        if bundle is not None:
            PENDING_BUNDLE.pop(bundle_id, None)
            results, error = await place_bundle(bundle, user.id)
            if error:
                key = error[0]
                if key == "insufficient":
                    await update.message.reply_text(
                        t(
                            "insufficient",
                            lang,
                            balance=format_money(error[1]),
                            total=format_money(error[2]),
                        ),
                        reply_markup=deposit_webapp_keyboard(lang),
                    )
                else:
                    await update.message.reply_text(t(key, lang))
                return
            await update.message.reply_text(batch_result_text(results, lang))
            return
        # A "yes" can also confirm a refill awaiting Confirm: refill
        # the completed order at the provider (or, when the provider
        # offers no refills, say so honestly and offer a second
        # Confirm for a brand-new order of the same service).
        refill_id, refill = pending_refill_for_user(user.id)
        if refill is not None:
            PENDING_REFILL.pop(refill_id, None)
            await _run_refill_confirm(
                user.id, refill, lang,
                respond=update.message.reply_text,
                send_new=update.message.reply_text,
            )
            return
        # A "yes" can also confirm an order cancel awaiting Confirm
        # (12, 15 Nov 2026): cancel it at the provider and refund
        # the full total to the user's balance.
        cancel_id, cancel_entry = pending_cancel_for_user(user.id)
        if cancel_entry is not None:
            PENDING_CANCEL.pop(cancel_id, None)
            await _run_cancel_order_confirm(
                user.id, cancel_entry, lang,
                respond=update.message.reply_text,
            )
            return
        # A "yes" can also accept the offer to check a payment receipt
        # the user sent as a photo: recheck the most recent deposit
        # with Chapa and say what happened.
        if user.id in RECEIPT_OFFER:
            RECEIPT_OFFER.pop(user.id, None)
            await reply_message(
                update.message,
                await deposit_status_text(
                    user.id, lang,
                    app=getattr(context, "application", None),
                    username=user.username,
                    first_name=user.first_name,
                ),
                lang, voice=voice,
            )
            return
        # A "yes" can also accept the Friday-pattern offer (feature
        # 5, 15 Nov 2026): pre-fill the pattern's service + quantity
        # and ask for the link. Checked last here, so a "yes" to a
        # real Confirm card, plan, delayed order, batch or receipt
        # always wins over the offer.
        if user.id in FRIDAY_PENDING:
            pattern = FRIDAY_PENDING.pop(user.id)
            await _friday_accept_reply(
                update, user.id, pattern, lang, voice=voice
            )
            return
        # No pending order: fall through; the normal flow answers
        # "not understood".

    # Editable Confirm card (19 Nov 2026): "Lets change the link"
    # while a card is pending is caught here, before the classifier
    # — the classifier never called it change_order, so it fell
    # through to "I did not understand". Only fires when a card is
    # actually pending; anything else falls through untouched.
    if await handle_card_edit_text(update, text, lang, voice=voice):
        return

    # "I paid" / "I approved it" while a deposit is pending: the user
    # is asking whether the deposit went through — recheck it with
    # Chapa instead of classifying the message. Skipped while a
    # deposit Confirm card is still open (that deposit has not been
    # created yet, so there is nothing to recheck).
    if is_paid_phrase(text):
        _dep_id, _dep_draft = pending_deposit_for_user(user.id)
        if _dep_draft is None:
            await reply_message(
                update.message,
                await deposit_status_text(
                    user.id, lang,
                    app=getattr(context, "application", None),
                    username=user.username,
                    first_name=user.first_name,
                ),
                lang, voice=voice,
            )
            return

    # Browse services (11, 15 Nov 2026): "show me TikTok followers
    # services" lists the matching services in chat, fastest first
    # — deterministic, before the classifier, so it is never read
    # as an order for the first service on the list.
    if intent is None and is_browse_services_request(text):
        await _park_order_and_note(update, user.id, lang, voice=voice)
        await handle_browse_services(update, text, lang, voice=voice)
        return

    # Asked where the services come from, or what Paxyo pays for
    # them: deflect at once, without calling Gemini. Skipped when the
    # intent was injected by the photo handler (already classified).
    if intent is None and is_source_question(text):
        await _park_order_and_note(update, user.id, lang, voice=voice)
        await reply_message(update.message, t("source_question", lang), lang, voice=voice)
        return

    # Loyalty-bonus question (feature 9, 15 Nov 2026): answered
    # deterministically, before the classifier — the AI would
    # otherwise guess the rule or the percentage. A 404 answers
    # honestly that the bonus isn't switched on yet.
    if intent is None and is_loyalty_question(text):
        await _park_order_and_note(update, user.id, lang, voice=voice)
        await reply_message(
            update.message,
            await loyalty_answer_text(
                user.id, lang,
                app=getattr(context, "application", None),
            ),
            lang, voice=voice,
        )
        return

    # "Same as usual" (round 6, 13 Nov 2026): the AI sometimes
    # reads it as a plain order and the flow then asks for the link,
    # even though the last order's link is known. Catch the phrasing
    # locally, before the classifier, and route it to the usual
    # handler with the quantity from the message. (An injected
    # intent — a photo — is never overridden.)
    if intent is None and is_usual_request(text):
        _words = set(re.findall(r"[a-z]+", text.lower()))
        intent = _empty_intent(
            "usual",
            quantity=quantity_from_text(text),
            quantity_multiplier=(
                2 if "double" in _words
                else 3 if "triple" in _words else None
            ),
        )
    # Reorder with a different quantity (22, 15 Nov 2026): "reorder
    # my last order with 2000 views" / "same order but 500" reuses
    # the last order's service + link with the new quantity.
    # Deterministic, before the classifier — the classifier would
    # otherwise read it as a fresh order and ask for the link.
    # "Same as last time but 500" is not here: the usual handler
    # above already takes it (the explicit quantity wins there).
    if intent is None and parse_reorder_quantity(text) is not None:
        await handle_reorder_new_quantity(update, text, lang, voice=voice)
        return
    # A cancel command is deterministic (live bug, 14 Nov 2026
    # 19:10 and 19:29 EAT): a bare "Cancel" with nothing pending
    # came back from the AI as off_topic and got a free-chat
    # continuation ("no one can guarantee zero risk"), contradicting
    # the standing ban answer. Caught locally, before the
    # classifier, like the usual-request check above — the cancel
    # branch below then answers deterministically.
    if intent is None and is_cancel_request(text):
        intent = _empty_intent("cancel")
    # "My invite link" is deterministic too (late-reply fix, 16 Nov
    # 2026): it had no fast path, so it waited on the AI. Caught
    # locally, before the classifier, like the cancel check above —
    # the invite branch below then answers with the user's own code.
    if intent is None and is_invite_link_request(text):
        intent = _empty_intent("invite")
    # Price questions are answered from local detection only, BEFORE
    # the AI classifier (live bug, 14 Nov 2026: the price arrived
    # 68 seconds late because the classifier and the bridge ran
    # first, and the queue of earlier updates delayed it further).
    # local_intent reads the platform, metric and quantity straight
    # from the message, and the price comes from the catalogue —
    # the AI is never in the path. When this fast path cannot name
    # a service (price is None), the flow continues to the
    # classifier and the post-classification price branch below,
    # which may resolve it from the AI's intent instead.
    if intent is None and is_price_question(text):
        _local = local_intent(text)
        # Mid-order understanding (16 Nov 2026): only a draft
        # that was ALREADY open gets parked. price_answer_text
        # remembers the question itself as a draft (_remember_
        # price_question), and that just-created memory is not an
        # unfinished order — parking it would tell the user an
        # order was saved when none was being built.
        _had_draft = bool(PARTIAL.get(user.id)) or (
            pending_for_user(user.id)[1] is not None
        )
        price = await price_answer_text(user.id, text, _local, lang)
        if price is not None:
            if _had_draft:
                await _park_order_and_note(update, user.id, lang, voice=voice)
            await reply_message(update.message, price, lang, voice=voice)
            return
    # How to get a Telegram post link: a deterministic answer,
    # before the classifier (owner, 14 Nov 2026 — the AI kept
    # getting the steps wrong, and the free answer was
    # desktop-flavoured). Never a free AI reply for this one.
    if intent is None and is_telegram_post_link_question(text):
        await _park_order_and_note(update, user.id, lang, voice=voice)
        await reply_message(
            update.message, t("telegram_post_link", lang), lang,
            voice=voice,
        )
        return
    # Post bundle (ideas batch 1 #3, 16 Nov 2026): "Boost my new
    # post" orders views + likes + reactions for one post link.
    # The detector runs before the classifier, so the AI can never
    # misread a boost as a single-service order. A bundle draft in
    # progress keeps eating its follow-ups — the link, then the
    # quantities — but only those: any other message falls through
    # to the normal flow (and the order branch drops the draft).
    if is_post_bundle_request(text) or (
        user.id in BUNDLE_DRAFT
        and (
            extract_links(text)
            or bundle_quantities_from_text(text) is not None
        )
    ):
        await handle_post_bundle(update, text, intent, lang, voice=voice)
        return
    # Check my post (ideas batch 2 #2, 16 Nov 2026): a link plus a
    # check word is a check, not an order — no draft is started.
    if is_post_check_request(text):
        await _park_order_and_note(update, user.id, lang, voice=voice)
        await handle_post_check(update, text, lang, voice=voice)
        return
    # `intent` is injected by the photo handler (a picture's link is
    # already classified by Gemini vision, so a second text
    # classification of the bare link would be wasted and could
    # misread it). Otherwise the text is classified here — with the
    # catalogue as a hint when it is available (cached 10 minutes;
    # a fetch failure just means no services section, as before).
    if intent is None:
        # Simple-chat fast path (owner, 17 Nov 2026): a plain
        # greeting or a question about Paxyo itself is pinned down
        # locally, so the AI classify call is skipped and the turn
        # costs one AI call (paxyo_info, how_to) or none (greeting,
        # help, how_to_order). Anything else still goes through the
        # classifier below — see simple_chat_intent for the guards.
        _simple = simple_chat_intent(text)
        if _simple is not None:
            intent = _simple
            _intent_source = "fast"
        else:
            _svc_t0 = time.monotonic()
            try:
                _services = await paxyo.services() if paxyo is not None else None
            except Exception:
                _services = None
            _turn_log("services", _svc_t0)
            _intent_source = "classifier"
            intent = await extract_intent(
                text, user_id=user.id, services=_services
            )
    intent_type = (intent.get("intent") or "unclear").strip().lower()
    _turn_log(f"intent {intent_type} {_intent_source}", _t0)
    # Off-topic steering counts consecutive off-topic turns; any
    # Paxyo topic resets it.
    if intent_type not in ("off_topic", "unclear"):
        OFF_TOPIC_COUNT.pop(user.id, None)

    # Settings fallback (customizations, 15 Nov 2026): the
    # deterministic handler above catches settings phrasings it
    # knows; when the AI calls it "settings" anyway, show the
    # settings list (with how to change one) instead of falling
    # through to the order flow.
    if intent_type == "settings":
        await reply_message(
            update.message, pref_settings_text(user.id),
            lang, voice=voice,
        )
        return

    # A message that pastes a link and names a metric with an order
    # verb IS an order, even when the AI called it something else
    # (round 7, 13 Nov 2026: "I want TikTok followers for <video
    # link>" came back as "safety", so the link-mismatch answer
    # never fired in that turn and the followers draft leaked into
    # the next one). Missing fields are filled from the message
    # itself, so the order flow sees the link and the metric.
    if intent_type in _ORDER_OVERRIDABLE and is_order_request(text):
        _local = local_intent(text)
        for _k in (
            "platform", "service_hint", "link", "quantity", "service_id",
        ):
            if intent.get(_k) is None and _local.get(_k) is not None:
                intent[_k] = _local[_k]
        intent["intent"] = "order"
        intent_type = "order"

    # Auto-refill guard (19 Nov 2026): the mirror of the order
    # override above. The AI is the primary classifier and
    # local_intent only runs when it is unreachable, so a "keep
    # my followers above 15k" misread as a plain "order" would
    # build a one-time 15k order for real money. When the message
    # deterministically asks to keep a count above a target, it
    # is an auto-refill setup whatever the classifier called it
    # ("order", "unclear", "safety"...) — the target rides along
    # and the quantity is dropped, so the order flow never sees
    # it. The auto-refill intents themselves are not in
    # _ORDER_OVERRIDABLE, so a stop/status can never be rewritten
    # by this guard.
    if intent_type in ("order",) + _ORDER_OVERRIDABLE and (
        is_auto_refill_request(text)
    ):
        intent["intent"] = "auto_refill"
        intent_type = "auto_refill"
        intent["target"] = parse_auto_refill_target(text)
        intent["quantity"] = None

    # Friday pattern (feature 5, 15 Nov 2026): a light message —
    # greeting, small talk, or an unclear message — on the weekday
    # the user usually orders on gets the one-per-week offer
    # instead of the stock greeting / steer-back. Order messages
    # never reach this gate (they are "order", "usual", "batch",
    # …), so an order in progress is never hijacked — and the
    # offer itself refuses while a draft or Confirm card is open.
    # The check runs here, when the user messages, not in the
    # 60-second scheduler: no wake-up spam, no message to a user
    # who is not chatting.
    if intent_type in ("greeting", "off_topic", "unclear"):
        # One recent-orders list for both gates (owner, 18 Nov
        # 2026): the Friday gate and the feedback gate each
        # fetched the same list, so a light turn paid for it twice
        # (plus feedback_asked) — 26.16s of light_gates live on
        # 18 Nov 2026 while the server was slow. A failed shared
        # fetch passes None and each gate fetches on its own,
        # exactly as before.
        _orders = None
        try:
            _orders = (
                await paxyo.recent_orders(user.id, limit=20)
                if paxyo is not None
                else None
            )
        except Exception as exc:
            log.warning("light gates orders failed: %s", exc)
        if await maybe_friday_pattern_offer(
            update, user.id, lang, orders=_orders
        ):
            return
        # Feedback check (feature 10, 15 Nov 2026): the same
        # light-intent gate, after the Friday offer — a user due
        # for the one-time "how was your first order?" ask gets
        # it instead of the stock greeting. Never hijacks an order
        # message, never runs while a draft or Confirm is open
        # (checked inside), never via the scheduler.
        if await maybe_feedback_ask(
            update, user.id, lang, orders=_orders
        ):
            return

    # The Friday / feedback gates above each call the server
    # (recent_orders), so a slow server stalls a light turn here —
    # log the stage to catch it.
    _turn_log("light_gates", _t0)

    # A question about an order awaiting Confirm ("how fast would
    # those 1000 views actually arrive?") is answered from the
    # pending service whatever the classifier called it — paxyo_info,
    # unclear, anything. The round-3 fix only ran inside the order
    # flow, so a paxyo_info classification answered it with the
    # generic line instead of the real "about 1 minute". A number
    # that equals the pending quantity is a reference to that order,
    # not new information.
    if intent_type in ("paxyo_info", "unclear", "order", "off_topic"):
        _cid, _pending = pending_for_user(user.id)
        if _pending is not None:
            _question = pending_order_question(
                text, _pending.get("quantity")
            )
            if _question is not None:
                _answer = pending_confirm_answer(
                    _pending.get("service"), _question, lang
                )
                if _answer is not None:
                    await reply_message(
                        update.message, _answer, lang, voice=voice
                    )
                    return

    # --- round 5: direct answers that must not fall through to the
    # --- order flow or the generic AI line ---
    # The price question is answered by the deterministic detector,
    # never by the AI's classification (live bug, 14 Nov 2026: the
    # same "I want 👍 reaction ... how much 1k" got its price from
    # Groq and lost it from DeepSeek, because the old intent-type
    # gate let the classifier decide whether a price question got
    # its price at all).
    if is_price_question(text):
        # Same draft snapshot as the fast path above: only a draft
        # that was already open gets parked, never the memory the
        # price computation itself just wrote.
        _had_draft = bool(PARTIAL.get(user.id)) or (
            pending_for_user(user.id)[1] is not None
        )
        price = await price_answer_text(user.id, text, intent, lang)
        if price is not None:
            if _had_draft:
                await _park_order_and_note(update, user.id, lang, voice=voice)
            await reply_message(update.message, price, lang, voice=voice)
            return
    if is_ban_question(text):
        await reply_message(update.message, with_pending_note(user.id, lang, t("ban_no", lang)), lang, voice=voice)
        return
    # The link of a past order (owner, 14 Nov 2026): answer with
    # the ACTUAL link from history — never the history list, never
    # an invented link. Runs before the history-table handler
    # below, so "send me the link of the last order" does not get
    # the table instead.
    if is_link_recall_question(text):
        recall = await link_recall_text(user.id, text, lang)
        await reply_message(update.message, recall, lang, voice=voice)
        return
    _never_drop = never_drop_kind(
        text, intent.get("platform"), intent.get("service_hint")
    )
    if _never_drop is not None:
        # Owner, 14 Nov 2026: Telegram reactions, Telegram views
        # and Facebook reactions never drop. Only when the user
        # asks about drops for one of those three — every other
        # drop question falls through to the terms/refund answer.
        # Runs before terms_answer, so a covered question never
        # gets the generic "drops may occur" line.
        await reply_message(
            update.message,
            with_pending_note(
                user.id, lang, t("never_drop", lang, service=_never_drop)
            ),
            lang, voice=voice,
        )
        return
    if is_pay_methods_question(text):
        # "How can I pay?" (round 6, 13 Nov 2026): list the methods
        # FIRST — the deposit flow jumps straight to "How much do you
        # want to deposit?" and the user never sees them.
        await reply_message(update.message, with_pending_note(user.id, lang, t("paxyo_pay", lang)), lang, voice=voice)
        return
    if is_public_question(text):
        await reply_message(update.message, with_pending_note(user.id, lang, t("public_answer", lang)), lang, voice=voice)
        return
    if is_comment_likes_question(text):
        # Owner, 14 Nov 2026: for likes on a comment the bot needs
        # the video/post link plus either the comment's own link or
        # the username. A deterministic Paxyo fact — the AI must
        # never invent a different requirement.
        await reply_message(update.message, with_pending_note(user.id, lang, t("comment_likes_need", lang)), lang, voice=voice)
        return
    if is_telegram_post_link_question(text):
        # Deterministic Telegram post-link steps (owner, 14 Nov
        # 2026): the AI kept getting them wrong. Runs here too so
        # a classifier that already ran (photo intent) cannot send
        # the question to a free AI reply.
        await reply_message(update.message, t("telegram_post_link", lang), lang, voice=voice)
        return
    _terms = terms_answer(text, lang)
    if _terms is not None:
        await reply_message(update.message, with_pending_note(user.id, lang, _terms), lang, voice=voice)
        return
    if is_history_question(text):
        summary = history_summary_text(user.id, lang)
        await reply_message(
            update.message,
            summary if summary is not None else t("history_none", lang),
            lang, voice=voice,
        )
        return
    if intent_type in ("paxyo_info", "unclear") and pending_order_question(text) == "speed":
        answer = await speed_answer_text(user.id, text, intent, lang)
        if answer is not None:
            await reply_message(update.message, answer, lang, voice=voice)
            return
    # "First one" / "second one" after a budget list: the user picked
    # one of the options just shown. Resolve it to that service and
    # ask for the link — the order continues from the picked service
    # instead of the reply being misread as a new order.
    if user.id in BUDGET_OPTIONS:
        choice = budget_choice_index(text)
        if choice is not None:
            stored_options = BUDGET_OPTIONS.get(user.id) or {}
            options = stored_options.get("options") or []
            if 0 <= choice < len(options):
                BUDGET_OPTIONS.pop(user.id, None)
                service = options[choice]
                merged = {
                    "platform": stored_options.get("platform"),
                    "service_hint": stored_options.get("service_hint"),
                    "link": None,
                    "quantity": stored_options.get("quantity"),
                    # By combined id (second provider, 15 Nov
                    # 2026): the cheapest option may be an SMM
                    # service, and a bare id would re-pin the
                    # GOP service of the same number.
                    "service_id": service_combined_id(service),
                }
                PARTIAL[user.id] = {k: v for k, v in merged.items() if v is not None}
                await reply_message(
                    update.message,
                    ask_link_text(merged.get("platform"), merged.get("service_hint"), lang),
                    lang, voice=voice,
                )
                return

    # Mid-order side questions (16 Nov 2026, widened scope): a
    # balance / orders / help / greeting / ... question typed while
    # an order is open is answered by its normal branch below —
    # but first the open order is parked, so the answer never
    # hijacks it and "order" resumes it afterwards. The round-5
    # direct answers above already ran with the draft intact
    # (order questions, price, terms), and the Friday offer gate
    # already refused while a draft is open — this guard only
    # covers the side-question intents listed above.
    if intent_type in _SIDE_QUESTION_INTENTS:
        await _park_order_and_note(update, user.id, lang, voice=voice)

    # --- conversational intents: answered before the order flow ---
    if intent_type == "cancel":
        # Cancel a PLACED order (12, 15 Nov 2026): "cancel my last
        # order" / "cancel order #1841" shows that order with a
        # Confirm card. Only when no Confirm card is open — an open
        # card owns the word "cancel" (dropping it is the existing
        # behaviour below), and the user can ask again after.
        cancel_target = parse_cancel_order_request(text)
        if cancel_target is not None:
            _cid, _pending = pending_for_user(user.id)
            _rid, _rec = pending_recurring_for_user(user.id)
            _did, _delay = pending_delayed_for_user(user.id)
            _depid, _dep = pending_deposit_for_user(user.id)
            _bid, _batch = pending_batch_for_user(user.id)
            _rfid, _refill = pending_refill_for_user(user.id)
            if (
                _pending is None and _rec is None and _delay is None
                and _dep is None and _batch is None and _refill is None
            ):
                await handle_cancel_order_text(
                    update, text, cancel_target, lang, voice=voice
                )
                return
        # "I don't want to" / "cancel": drop any pending order and any
        # order being built, and say so. When BOTH a pending order and
        # repeating orders exist, "cancel" is ambiguous — ask which one
        # to stop instead of guessing.
        confirm_id, pending = pending_for_user(user.id)
        rec_id, rec_draft = pending_recurring_for_user(user.id)
        if rec_draft is not None and pending is None:
            PENDING_RECURRING.pop(rec_id, None)
            RECURRING_DRAFT.pop(user.id, None)
            await reply_message(update.message, t("cancelled", lang), lang, voice=voice)
            log_confusion(user.id, text, t("cancelled", lang), "abandoned")
            return
        auto_id, auto_setup = pending_auto_refill_for_user(user.id)
        if auto_setup is not None and pending is None and rec_draft is None:
            PENDING_AUTO_REFILL.pop(auto_id, None)
            AUTO_REFILL_DRAFT.pop(user.id, None)
            await reply_message(update.message, t("cancelled", lang), lang, voice=voice)
            log_confusion(user.id, text, t("cancelled", lang), "abandoned")
            return
        dep_id, dep_draft = pending_deposit_for_user(user.id)
        if dep_draft is not None and pending is None and rec_draft is None:
            PENDING_DEPOSIT.pop(dep_id, None)
            DEPOSIT_DRAFT.pop(user.id, None)
            await reply_message(update.message, t("cancelled", lang), lang, voice=voice)
            log_confusion(user.id, text, t("cancelled", lang), "abandoned")
            return
        batch_id, batch = pending_batch_for_user(user.id)
        if batch is not None and pending is None and rec_draft is None and dep_draft is None:
            PENDING_BATCH.pop(batch_id, None)
            SPLIT_DRAFT.pop(user.id, None)
            await reply_message(update.message, t("cancelled", lang), lang, voice=voice)
            log_confusion(user.id, text, t("cancelled", lang), "abandoned")
            return
        delay_id, delay_draft = pending_delayed_for_user(user.id)
        if delay_draft is not None and pending is None and rec_draft is None and dep_draft is None and batch is None:
            PENDING_DELAYED.pop(delay_id, None)
            DELAYED_DRAFT.pop(user.id, None)
            await reply_message(update.message, t("cancelled", lang), lang, voice=voice)
            log_confusion(user.id, text, t("cancelled", lang), "abandoned")
            return
        # A bare "cancel" while an order-cancel card is open drops
        # that card (12, 15 Nov 2026) — same as every other pending
        # Confirm card above. Only when no order/plan/deposit card
        # is open, so the more specific drops above always win.
        cancel_id, cancel_entry = pending_cancel_for_user(user.id)
        if cancel_entry is not None and pending is None:
            PENDING_CANCEL.pop(cancel_id, None)
            await reply_message(update.message, t("cancelled", lang), lang, voice=voice)
            log_confusion(user.id, text, t("cancelled", lang), "abandoned")
            return
        if pending is not None:
            try:
                schedules = await paxyo.list_recurring(user.id)
            except Exception:
                schedules = []
            if schedules:
                buttons = [[
                    InlineKeyboardButton(
                        t("stop_this_order", lang),
                        callback_data=f"cancel:{confirm_id}",
                    )
                ]]
                for sched in schedules:
                    label = (
                        f"🛑 {short_service_name(sched.get('service_name')) or sched.get('service_id')} "
                        f"every {format_interval(sched.get('interval_minutes'))}"
                    )
                    buttons.append([InlineKeyboardButton(
                        label, callback_data=f"stoprec:{sched.get('id')}"
                    )])
                await reply_message(
                    update.message, t("stop_which", lang), lang, voice=voice,
                    reply_markup=InlineKeyboardMarkup(buttons),
                )
                return
            clear_order_state(user.id, cancelled=pending)
            await reply_message(update.message, t("cancelled", lang), lang, voice=voice)
            log_confusion(user.id, text, t("cancelled", lang), "abandoned")
            return
        # No pending order: the user may mean a repeating order.
        try:
            schedules = await paxyo.list_recurring(user.id)
        except Exception:
            schedules = []
        if schedules:
            await stop_schedules_flow(update, schedules, lang, voice=voice)
            return
        # Or a scheduled (delayed) order.
        try:
            delayed = await delayed_store_list(user.id)
        except Exception:
            delayed = []
        if delayed:
            await handle_cancel_delayed(update, lang, voice=voice)
            return
        # Nothing was being built or waiting: say so instead of
        # "Order cancelled." (live bug, 14 Nov 2026 19:10 and 19:29
        # EAT — a bare "Cancel" with nothing pending got a free AI
        # continuation). "Order cancelled." stays for a real draft
        # or card that was just dropped.
        had_something = bool(
            PARTIAL.get(user.id)
            or RECURRING_DRAFT.get(user.id)
            or AUTO_REFILL_DRAFT.get(user.id)
            or DELAYED_DRAFT.get(user.id)
            or DEPOSIT_DRAFT.get(user.id)
            or SPLIT_DRAFT.get(user.id)
        )
        clear_order_state(user.id)
        RECURRING_DRAFT.pop(user.id, None)
        AUTO_REFILL_DRAFT.pop(user.id, None)
        DELAYED_DRAFT.pop(user.id, None)
        DEPOSIT_DRAFT.pop(user.id, None)
        SPLIT_DRAFT.pop(user.id, None)
        dep_id, _dep = pending_deposit_for_user(user.id)
        if dep_id is not None:
            PENDING_DEPOSIT.pop(dep_id, None)
        batch_id, _batch = pending_batch_for_user(user.id)
        if batch_id is not None:
            PENDING_BATCH.pop(batch_id, None)
        delay_id, _delay = pending_delayed_for_user(user.id)
        if delay_id is not None:
            PENDING_DELAYED.pop(delay_id, None)
        await reply_message(
            update.message,
            t(
                "cancelled" if had_something else "nothing_to_cancel",
                lang,
            ),
            lang, voice=voice,
        )
        if had_something:
            log_confusion(user.id, text, t("cancelled", lang), "abandoned")
        return
    if intent_type == "recurring":
        await handle_recurring_text(update, text, intent, lang, voice=voice)
        return
    if intent_type == "auto_refill":
        await handle_auto_refill_text(update, text, intent, lang, voice=voice)
        return
    if intent_type == "auto_refill_status":
        await handle_auto_refill_status(update, lang, voice=voice)
        return
    if intent_type == "auto_refill_stop":
        await handle_auto_refill_stop(update, text, lang, voice=voice)
        return
    if intent_type == "delayed_orders":
        await reply_message(
            update.message, await delayed_orders_text(user.id, lang),
            lang, voice=voice,
        )
        return
    if intent_type == "cancel_delayed":
        await handle_cancel_delayed(update, lang, voice=voice)
        return
    if intent_type == "schedules":
        await reply_message(
            update.message, await schedules_text(user.id, lang), lang, voice=voice
        )
        return
    if intent_type == "stop_schedule":
        await handle_stop_schedule(update, lang, voice=voice)
        return
    if intent_type == "balance":
        await reply_message(
            update.message, await balance_text(user.id, lang), lang, voice=voice
        )
        return
    if intent_type == "orders":
        # "Why hasn't it started yet?" gets the real status plus the
        # service's average time; a plain history question gets the
        # full table (owner, 13 Nov 2026). "Show my TikTok orders"
        # filters the table to that platform (ideas batch 1 #6,
        # 16 Nov 2026): the platform rides in the intent.
        if is_wait_question(text):
            await handle_order_wait(update, text, lang, voice=voice)
            return
        await reply_message(
            update.message,
            await orders_history_text(
                user.id, lang,
                platform=intent.get("platform"),
            ),
            lang, voice=voice,
        )
        return
    if intent_type == "deposit":
        await handle_deposit_text(update, text, intent, lang, voice=voice)
        return
    if intent_type == "deposit_status":
        await reply_message(
            update.message,
            await deposit_status_text(
                user.id, lang,
                app=getattr(context, "application", None),
                username=user.username,
                first_name=user.first_name,
            ),
            lang, voice=voice,
        )
        return
    # --- messy real-world inputs (owner edge-case spec, 13 Nov 2026) ---
    if intent_type == "usual":
        await handle_usual(update, text, intent, lang, voice=voice)
        return
    if intent_type == "goal":
        # A goal is not a service: ask which metric matters, then
        # build the order from the answer.
        await reply_message(
            update.message,
            with_pending_note(user.id, lang, t("ask_metric", lang)),
            lang, voice=voice,
        )
        return
    if intent_type == "budget":
        await handle_budget_text(update, text, intent, lang, voice=voice)
        return
    if intent_type == "batch":
        await handle_batch_text(update, text, intent, lang, voice=voice)
        return
    if intent_type == "change_order":
        await handle_change_order(update, text, intent, lang, voice=voice)
        return
    if intent_type == "refill":
        await handle_refill(update, text, intent, lang, voice=voice)
        return
    if intent_type == "split_payment":
        # One payment source per order: the Telebirr half is deposited
        # first, then the order comes from the wallet balance.
        await reply_message(
            update.message,
            with_pending_note(user.id, lang, t("split_payment_no", lang)),
            lang, voice=voice,
        )
        return
    if intent_type == "max_for_balance":
        await handle_max_for_balance(update, text, intent, lang, voice=voice)
        return
    if intent_type == "discount":
        await handle_cheapest_reply(update, intent, lang, voice, "discount_no")
        return
    if intent_type == "free_sample":
        await handle_cheapest_reply(update, intent, lang, voice, "free_sample_no")
        return
    if intent_type == "price_pushback":
        # Prices are fixed by Paxyo — the bot never applies a
        # user-supplied price anywhere; it offers the cheapest real
        # option instead.
        await handle_cheapest_reply(update, intent, lang, voice, "price_fixed")
        return
    if intent_type == "safety":
        # Honest, never overpromising: gradual and widely used, but
        # no zero-risk guarantee, and followers are not guaranteed
        # real Ethiopian people. A slower service is offered when the
        # platform is known.
        safety_text = t("safety", lang)
        platform = (intent.get("platform") or "").strip().lower() or None
        hint = intent.get("service_hint")
        if platform or hint:
            try:
                services = await paxyo.services()
                slow = slowest_service(
                    services, platform=platform, service_hint=hint
                )
                if slow is not None and slow.get("average_time"):
                    safety_text += "\n" + t(
                        "safety_slow", lang,
                        service=short_service_name(slow.get("name")),
                        avg=slow.get("average_time"),
                    )
            except Exception as exc:
                log.warning("safety slowest lookup failed: %s", exc)
        await reply_message(
            update.message,
            with_pending_note(user.id, lang, safety_text),
            lang, voice=voice,
        )
        return
    if intent_type == "refund_policy":
        # Never invent a refund policy: support reviews it, the bot
        # promises nothing itself.
        await reply_message(
            update.message,
            with_pending_note(user.id, lang, t("refund_policy", lang)),
            lang, voice=voice,
        )
        return
    if intent_type == "geo_target":
        await reply_message(
            update.message,
            with_pending_note(user.id, lang, t("geo_no", lang)),
            lang, voice=voice,
        )
        return
    if intent_type == "content_help":
        # Brief general tips are allowed, then back to ordering.
        await reply_message(
            update.message,
            with_pending_note(user.id, lang, t("content_help", lang)),
            lang, voice=voice,
        )
        return
    if intent_type == "reseller":
        # The user wants to sell Paxyo's services themselves:
        # send them to customer support. One short line, repeated as-is
        # if they ask again.
        await reply_message(
            update.message,
            with_pending_note(user.id, lang, t("reseller_contact", lang)),
            lang, voice=voice,
        )
        return
    if intent_type == "contact":
        # The user wants a human: our customer support at t.me/paxyo.
        await reply_message(
            update.message,
            with_pending_note(user.id, lang, t("contact_owner", lang)),
            lang, voice=voice,
        )
        return
    if intent_type == "paused_services":
        # Premium subscriptions and SMS OTP verification are paused
        # (owner, 14 Nov 2026): one short line, repeated as-is if
        # they ask again. No date, no price, never a social-media
        # service offered instead.
        await reply_message(
            update.message,
            with_pending_note(user.id, lang, t("paused_services", lang)),
            lang, voice=voice,
        )
        return
    if intent_type == "support_issue":
        # The bot cannot fix the website account itself: point at the
        # deposit recheck and the Paxyo team.
        await reply_message(
            update.message,
            with_pending_note(user.id, lang, t("support_redirect", lang)),
            lang, voice=voice,
        )
        return
    if intent_type == "help":
        await reply_message(update.message, t("help", lang), lang, voice=voice)
        return
    if intent_type == "how_to_order":
        # Short numbered guide + a Start button that begins the order
        # flow (asks for the platform). The button forces text: a
        # voice message cannot carry buttons.
        await reply_message(
            update.message, t("how_to_order", lang), lang, voice=voice,
            reply_markup=start_order_keyboard(lang),
        )
        return
    if intent_type == "miniapp":
        await reply_message(update.message, t("miniapp", lang), lang, voice=voice)
        return
    if intent_type == "social":
        await reply_message(update.message, t("social", lang), lang, voice=voice)
        return
    if intent_type == "invite":
        # Invite link (per-user codes, 15 Nov 2026): the user's OWN
        # code + link, derived locally — the AI never invents a code.
        # Both-sides referral bonus (16 Nov 2026): the card says the
        # friend AND the code owner get 20% on the friend's first
        # deposit. This branch is ONLY for "my invite link" requests
        # — a typed code never lands here (see handle_invite_code_text).
        _own_code = user_invite_code(user.id)
        await reply_message(
            update.message,
            t("invite_link", lang, link=user_invite_link(user.id), code=_own_code),
            lang, voice=voice,
            reply_markup=invite_link_keyboard(_own_code, lang),
        )
        return
    if intent_type == "greeting":
        await reply_message(
            update.message, t("greeting", lang), lang, voice=voice,
            reply_markup=hide_reply_keyboard(),
        )
        _turn_log("sent", _t0)
        return
    if intent_type == "source_question":
        await reply_message(update.message, t("source_question", lang), lang, voice=voice)
        return
    if intent_type == "paxyo_info":
        # Bare platform word (17 Nov 2026): the classifier read
        # "Twitter" as an info question, so the platform never
        # reached the draft — and the next "How much is it"
        # quoted Facebook Followers for an X order. When the
        # message is just the platform word and local_intent
        # agrees it is an order on that platform, remember the
        # platform in the draft so the following turns inherit
        # it. Never overwrites a draft on another platform, and
        # never seeds while a Confirm card is open. A real info
        # question ("what is Twitter?") has more words and never
        # matches the bare-word check at all.
        _bare_platform = _bare_platform_word(text)
        if _bare_platform is not None:
            _own = local_intent(text)
            if (
                _own.get("intent") == "order"
                and _own.get("platform") == _bare_platform
            ):
                _cid, _pending = pending_for_user(user.id)
                _draft = PARTIAL.get(user.id) or {}
                _draft_platform = (
                    (_draft.get("platform") or "").strip().lower() or None
                )
                if _pending is None and _draft_platform in (
                    None, _bare_platform,
                ):
                    PARTIAL[user.id] = {
                        **_draft, "platform": _bare_platform,
                    }
        _paxyo_answer = await answer_paxyo_question(text, lang, user_id=user.id)
        _turn_log("answer", _t0)
        await reply_message(
            update.message, _paxyo_answer,
            lang, voice=voice,
        )
        _turn_log("sent", _t0)
        return
    if intent_type == "how_to":
        # A how-to question gets a free AI answer, like DeepSeek
        # would give (owner, 14 Nov 2026). No steer-back line: it
        # is about ordering, not off-topic chat. The AI is up here
        # (the classifier ran), so a None answer only means an
        # empty reply — the short Paxyo line is the fallback.
        general = await answer_general_question(text, lang)
        _turn_log("answer", _t0)
        await reply_message(
            update.message,
            general if general is not None else t("paxyo_info_fallback", lang),
            lang, voice=voice,
        )
        _turn_log("sent", _t0)
        return
    if intent_type == "off_topic":
        # Off-topic steering (owner, 13 Nov 2026; widened 14 Nov
        # 2026): a real QUESTION always gets a free AI answer plus
        # one short steer-back line — never the canned deflection,
        # however many turns it takes. Only non-question chit-chat
        # is capped: the first two turns get a general answer plus
        # a nudge, the third (and beyond) steers back.
        if is_question(text):
            general = await answer_general_question(text, lang)
            if general is not None:
                await reply_message(
                    update.message,
                    general + "\n" + t("off_topic_nudge", lang),
                    lang, voice=voice,
                )
                return
            # AI down: fall through to the cap logic below, which
            # ends in the one-line deflection.
        count = OFF_TOPIC_COUNT.get(user.id, 0) + 1
        OFF_TOPIC_COUNT[user.id] = count
        if count >= 3:
            await reply_message(update.message, t("off_topic_steer", lang), lang, voice=voice)
            return
        general = await answer_general_question(text, lang)
        if general is None:
            await reply_message(update.message, t("off_topic", lang), lang, voice=voice)
            return
        await reply_message(
            update.message, general + "\n" + t("off_topic_nudge", lang),
            lang, voice=voice,
        )
        return

    # Mid-deposit follow-up: the user is answering the bot's deposit
    # question ("50", "telebirr", "099387383"). Gemini may call a bare
    # answer "unclear", so fill the deposit draft from the message
    # itself when it carries a deposit field. A phone number or a
    # method word is unambiguous; a bare number only counts when no
    # order is being built at the same time. A promo code typed
    # mid-deposit is NONE of those (ideas batch 2, feature 1, 15 Nov
    # 2026): "PAXYO20" carries the number 20, and without this guard
    # parse_deposit_amount would silently rewrite the amount the user
    # already gave — the draft is left exactly as it was. The code
    # itself is answered by handle_promo_text before the classifier
    # (mid-order understanding, 16 Nov 2026), so it never reaches
    # this branch at all.
    # Deposit-hijack fix (16 Nov 2026): a bare number also counts
    # when the classifier called it an "order" — while the deposit
    # flow is asking for an amount, a number IS the deposit amount
    # (the open order draft was parked when the flow started, so
    # the "no order being built" guard below already passes).
    _bare_number = re.fullmatch(r"[\d,]+", (text or "").strip()) is not None
    if user.id in DEPOSIT_DRAFT and (
        intent_type == "unclear"
        or (_bare_number and intent_type == "order")
    ):
        phone = normalize_phone(text)
        method = normalize_method(text)
        amount = parse_deposit_amount(text)
        if (
            extract_promo_code(text) is None
            and extract_promo_offer(text) is None
            and (
                phone is not None or method is not None or (
                    amount is not None and not PARTIAL.get(user.id)
                )
            )
        ):
            merged_intent = {
                "intent": "deposit",
                "platform": None, "service_hint": None, "link": None,
                "quantity": None, "interval_minutes": None,
                "amount": amount, "method": method, "phone": phone,
            }
            await handle_deposit_text(update, text, merged_intent, lang, voice=voice)
            return

    # The user is answering the split-links question: feed the pasted
    # links into the waiting split instead of starting a single order
    # with the first link.
    if user.id in SPLIT_DRAFT and extract_links(text):
        stored_split = SPLIT_DRAFT.get(user.id) or {}
        await handle_split_text(update, text, {
            "quantity": stored_split.get("quantity"),
            "count": stored_split.get("count"),
            "platform": stored_split.get("platform"),
            "service_hint": stored_split.get("service_hint"),
        }, lang, voice=voice)
        return

    # Bulk orders pasted as links (15 Nov 2026, feature 2): an
    # "order" message carrying 2 or more links is several orders in
    # one message, not a single order with the first link — route it
    # to the batch flow, which shows one combined Confirm card with
    # the grand total. A delayed order being built keeps its own
    # routing, and a single-link message is unchanged.
    if (
        intent_type == "order"
        and user.id not in DELAYED_DRAFT
        and len(extract_links(text)) >= 2
    ):
        await handle_batch_text(update, text, intent, lang, voice=voice)
        return

    # A one-time delayed order (owner, 14 Nov 2026): "order 10k views
    # to this link after 3 hrs". The delay rides in the intent
    # (delay_minutes, from the classifier or local_intent) or is read
    # from the message itself; a delayed draft already being built
    # keeps routing here on follow-up turns (link / quantity / delay
    # answers), unless the message names a different platform — that
    # starts a new order and drops the delayed draft, the same rule
    # the normal order flow uses.
    _delay = intent.get("delay_minutes") or parse_delay_minutes(text)
    if intent_type == "delayed_order" or (_delay is not None and intent_type == "order"):
        intent = dict(intent)
        intent["delay_minutes"] = _delay
        await handle_delayed_order_text(update, text, intent, lang, voice=voice)
        return
    if user.id in DELAYED_DRAFT and intent_type in ("order", "unclear", "delayed_order"):
        _stored_delayed = DELAYED_DRAFT[user.id]
        _new_platform = (intent.get("platform") or "").strip().lower()
        _stored_platform = (_stored_delayed.get("platform") or "").strip().lower()
        if _stored_delayed.get("delay_minutes") is not None and not (
            _new_platform and _stored_platform and _new_platform != _stored_platform
        ):
            await handle_delayed_order_text(update, text, intent, lang, voice=voice)
            return
        # A different platform: drop the delayed draft and fall
        # through to the normal order flow.
        DELAYED_DRAFT.pop(user.id, None)

    # A repeating-order plan being built keeps routing here on
    # follow-up turns (a bare link, "that link", or how many
    # times), unless the message names a different platform:
    # that starts a new order and drops the plan, the same rule
    # the delayed flow uses.
    if user.id in RECURRING_DRAFT and intent_type in ("order", "unclear"):
        _stored_rec = RECURRING_DRAFT[user.id]
        _new_platform = (intent.get("platform") or "").strip().lower()
        _stored_platform = (_stored_rec.get("platform") or "").strip().lower()
        if _is_recurring_followup(text, user.id) and not (
            _new_platform and _stored_platform and _new_platform != _stored_platform
        ):
            await handle_recurring_text(update, text, intent, lang, voice=voice)
            return
        if _new_platform and _stored_platform and _new_platform != _stored_platform:
            RECURRING_DRAFT.pop(user.id, None)

    # An auto-refill setup being built keeps routing here on
    # follow-up turns (a bare link, or the target number),
    # unless the message names a different platform: that starts
    # a new order and drops the setup, the same rule the
    # recurring flow uses.
    if user.id in AUTO_REFILL_DRAFT and intent_type in ("order", "unclear", "auto_refill"):
        _stored_auto = AUTO_REFILL_DRAFT[user.id]
        _new_platform = (intent.get("platform") or "").strip().lower()
        _stored_platform = (_stored_auto.get("platform") or "").strip().lower()
        if _is_auto_refill_followup(text, user.id) and not (
            _new_platform and _stored_platform and _new_platform != _stored_platform
        ):
            await handle_auto_refill_text(update, text, intent, lang, voice=voice)
            return
        if _new_platform and _stored_platform and _new_platform != _stored_platform:
            AUTO_REFILL_DRAFT.pop(user.id, None)

    # --- order flow: multi-turn state ---
    # A bundle draft is dropped here (ideas batch 1 #3): reaching
    # the normal order flow means the user is ordering something
    # else — the bundle hook above already ate the bundle's own
    # follow-ups (link, quantities).
    BUNDLE_DRAFT.pop(user.id, None)
    # What the user already gave is remembered per user in PARTIAL, so a
    # bare "2000" after a link, or a bare link after a service, completes
    # the order instead of "I did not understand". A message naming a
    # different platform starts a new order and drops the stored pieces.
    stored = PARTIAL.get(user.id) or {}
    stored_platform = (stored.get("platform") or "").strip().lower()
    # A bare link completing a draft the user already started is a
    # slot-fill, not a new order (live bug, 14 Nov 2026 19:27 EAT):
    # "10 🙏" then a bare link asked "How many?" and built a Post
    # Views card, because the AI guessed "views" for the bare post
    # link and that hint overwrote the reactions draft in the merge
    # below (and the metric-change reset wiped the rest). A link
    # carries no words of its own — when the message names no metric
    # and no platform, and the link is for the draft's platform (or
    # has none, like a @handle), the AI's guessed platform and hint
    # are dropped for this turn so the stored draft's metric, emoji
    # and quantity survive. A draft with no platform of its own
    # (the bare-emoji acknowledgement stores only the hint and the
    # emoji) has nothing to conflict with, so the link's platform
    # is no bar either — the platform still comes from the link
    # itself below (live bug, 14 Nov 2026 20:26 EAT: bare 😂 then a
    # bare link then "10" lost the reactions draft the same way).
    # A message WITH words still goes through the normal
    # platform/metric logic below, and a link for a different
    # platform still starts a fresh order.
    _bare_link = (extract_links(text) or [None])[0]
    _bare_link_platform = (
        platform_from_link(_bare_link)
        if _bare_link is not None else None
    )
    if (
        stored
        and _bare_link is not None
        and kind_from_text(text) is None
        and _explicit_platform_word(text) is None
        and (
            _bare_link_platform is None
            or not stored_platform
            or _bare_link_platform == stored_platform
        )
    ):
        intent = dict(intent)
        intent["platform"] = None
        intent["service_hint"] = None
    new_platform = (intent.get("platform") or "").strip().lower()
    # Stale-draft fix (16 Nov 2026): the message's own platform
    # word counts too — the classifier may carry the old platform
    # forward from an earlier conversation, so a new order on
    # another platform ("I want tiktok views" after a Telegram
    # reactions draft) must drop the stored draft even when the
    # AI's platform agrees with the old one.
    _msg_platform = _explicit_platform_word(text)
    if (
        _msg_platform
        and stored_platform
        and _msg_platform != stored_platform
    ):
        stored = {}
    elif new_platform and stored_platform and new_platform != stored_platform:
        stored = {}
    merged = {}
    for key in ("platform", "service_hint", "link", "quantity", "service_id",
                "named_by_id", "reaction_emoji", "deadline", "drip_span",
                "story"):
        value = intent.get(key)
        merged[key] = value if value is not None else stored.get(key)

    # A new order with a different metric REPLACES the old draft,
    # never merges with it (round 7, 13 Nov 2026: a followers draft
    # survived into the next turn, so a views order got the followers
    # answer, and a remembered 200-view draft auto-showed a Confirm
    # card). The metric is read from the message's own words first
    # (Amharic included), then from the AI's hint. A clarification
    # of the same metric ("likes for my comment" is still likes)
    # does not reset.
    metric_changed = False
    # A bare emoji carries no words (round 8.1, 14 Nov 2026): its
    # emoji-only kind ("👍" -> "reactions") must not wipe a draft
    # being built for another metric, or rewrite that draft's
    # kind. The emoji fallback in kind_from_text only counts when
    # the message also has words naming a kind — or when the AI's
    # hint names one.
    _text_has_words = any(ch.isalpha() for ch in (text or ""))
    _new_kind = (kind_from_text(text) if _text_has_words else None) or kind_from_text(
        intent.get("service_hint") or ""
    )
    _stored_kind = kind_from_text(stored.get("service_hint") or "")
    _new_metric = _primary_metric(_new_kind)
    _stored_metric = _primary_metric(_stored_kind)
    if (
        _new_metric is not None
        and _stored_metric is not None
        and _new_metric != _stored_metric
    ):
        stored = {}
        metric_changed = True
        for key in ("platform", "service_hint", "link", "quantity",
                    "service_id", "named_by_id", "reaction_emoji",
                    "deadline", "drip_span", "story"):
            merged[key] = intent.get(key)

    # A link pasted in THIS message always wins over the stored
    # link and over any link the classifier carried from history
    # (story/post bug, 16 Nov 2026: a fresh t.me post link did
    # not replace the stored tg://openmessage link). A tg:// deep
    # link is never an order link: drop it so the bot asks for a
    # real post link instead of carding it.
    _fresh_link = (extract_links(text) or [None])[0]
    if _fresh_link is not None:
        merged["link"] = _fresh_link
    if str(merged.get("link") or "").strip().lower().startswith("tg://"):
        merged["link"] = None

    # A bare number right before the metric ("200 TikTok views") is
    # the quantity even when the AI did not return one (round 7:
    # "please order now 200 TikTok views" asked "How many?"
    # instead of placing the order).
    if merged.get("quantity") is None:
        merged["quantity"] = quantity_before_metric(text)

    # Metric-from-text safety net (13 Nov 2026): the classifier
    # sometimes returns an order intent with no service_hint (or only
    # the platform word), and then complete_order picks the fastest
    # service of the whole platform — a views order got Tiktok Comment
    # Likes. When the message itself names a metric, use it. A hint
    # that already carries a metric word is never overridden. merged
    # is stored into PARTIAL at the ask-link/ask-quantity steps, so a
    # derived hint survives a later bare-link message.
    hint_words = set(
        (merged.get("service_hint") or "").strip().lower().split()
    )
    if not (hint_words & set(_METRICS)):
        metric = metric_from_text(text)
        if metric:
            platform = (merged.get("platform") or "").strip().lower()
            merged["service_hint"] = (
                f"{platform} {metric}" if platform else metric
            )

    # "Likes for my comment" is a different kind from "likes for my
    # video": the classifier often returns just "tiktok likes" for a
    # comment-likes request, and the fastest pick would then be a
    # video-likes service. When the message itself names a kind the
    # hint does not carry, the message wins — the hint is rewritten
    # to the kind the user actually asked for. A bare emoji names
    # no kind in words (round 8.1), so it never rewrites the hint.
    kind = kind_from_text(text) if _text_has_words else None
    if kind is not None:
        kind_words = {
            _canonical_metric(w) for w in kind.split()
        } - {None}
        hint_kind_words = {
            _canonical_metric(w)
            for w in (merged.get("service_hint") or "").split()
        } - {None}
        # Stale-draft fix (16 Nov 2026): the platform comes from
        # the message's own words too — a hint the classifier
        # carried forward from an earlier conversation must not
        # leave the new order on the old platform. The link still
        # wins when the message pastes one, so the platform word
        # is only used when there is no link in the draft.
        _msg_platform = (
            _explicit_platform_word(text)
            if not merged.get("link") else None
        )
        _merged_platform = (merged.get("platform") or "").strip().lower()
        if (
            kind_words != hint_kind_words
            or (_msg_platform and _msg_platform != _merged_platform)
        ):
            platform = _msg_platform or _merged_platform
            if _msg_platform:
                merged["platform"] = _msg_platform
            merged["service_hint"] = (
                f"{platform} {kind}" if platform else kind
            )

    # The reaction emoji being ordered rides in the draft (round
    # 8.1, 14 Nov 2026): the service picker matches the exact
    # family (👍 -> thumbs up / like) instead of guessing. It comes
    # from this message first, else from the stored draft, and is
    # dropped when the order stops being about reactions.
    if "reaction" in (merged.get("service_hint") or "").lower():
        merged["reaction_emoji"] = (
            reaction_emoji(text) or stored.get("reaction_emoji")
        )
    else:
        merged["reaction_emoji"] = None

    # A service the user named: Gemini's service_id first, the local
    # ID regex as fallback ("service 6139", "#6139", a bare "6139").
    # A bare number is a service ID, not a quantity — quantities must
    # be multiples of 10 — so "6139" alone never becomes quantity 6139.
    named_service_id = merged.get("service_id")
    if named_service_id is None:
        named_service_id = extract_service_id(text)
    if named_service_id is not None:
        merged["service_id"] = named_service_id
        bare = re.sub(r"[.!?]+$", "", text.strip())
        if re.fullmatch(r"\d+", bare) and merged.get("quantity") == named_service_id:
            merged["quantity"] = None

    # "That link" / "same service": resolve from the user's most
    # recent order, which lives on the server and survives restarts.
    # "Same service" names the last order's service for this order,
    # even when a fresh link was given.
    last_service_id = None
    same_service = mentions_same_service(text)
    link_from_last = False
    if (not merged.get("link") and mentions_that_link(text)) or same_service:
        last = await resolve_last_order(user.id)
        if last:
            if not merged.get("link") and mentions_that_link(text):
                merged["link"] = last.get("link")
                link_from_last = True
                last_service_id = last.get("service_id")
            if same_service and named_service_id is None:
                last_service_id = last.get("service_id")
                if last_service_id is not None:
                    named_service_id = last_service_id
                    merged["service_id"] = named_service_id

    # The full long service name is shown only when the user entered
    # a service ID (owner, 13 Nov 2026) — in this message, or in an
    # earlier turn of this order (remembered in PARTIAL). A service
    # from "same service as last time" is not an entered ID.
    named_by_id = bool(
        extract_service_id(text) is not None
        or intent.get("service_id") is not None
        or merged.get("named_by_id")
    )
    if named_by_id:
        merged["named_by_id"] = True

    # The link the user just pasted always wins (round 6,
    # 13 Nov 2026): the AI sometimes drops it, and then the flow
    # asks for the link again even though the user sent it — the
    # ask-link loop. A bare @handle message is a link too.
    text_links = extract_links(text)
    if text_links:
        merged["link"] = text_links[0]
    elif not merged.get("link"):
        handle = next(
            (tok for tok in (text or "").split() if tok.startswith("@")),
            None,
        )
        if handle is not None and handle.lower() != "@paxyo_bot":
            merged["link"] = handle
    # Per-customer default link (#11, customizations, 15 Nov
    # 2026): when the user did not paste a link in this message
    # and the draft has none, use their remembered usual link —
    # so they do not paste it every time. A link typed in this
    # message always wins (the block above). Only when the link's
    # platform fits the order being built (or no platform is set
    # yet): a TikTok default link never hijacks a YouTube order —
    # the bot just asks for the link instead.
    if not merged.get("link"):
        _default_link = get_pref(user.id, "pref_default_link")
        if _default_link:
            _default_platform = platform_from_link(_default_link)
            _merged_platform = (merged.get("platform") or "").strip().lower()
            if (
                _default_platform is None
                or not _merged_platform
                or _default_platform == _merged_platform
            ):
                merged["link"] = _default_link
    # Saved links (#31): "use my main link" in the order being
    # built — the named link fills the draft the same way the
    # default link does. (A bare "use my main link" with no order
    # is answered by the settings handler, which stores it in
    # the draft and asks what to order.)
    if not merged.get("link"):
        _saved_name = re.search(
            r"\buse my ([a-z0-9_-]+) link\b", (text or "").lower()
        )
        if _saved_name:
            _saved_links = get_pref(user.id, "pref_saved_links") or {}
            _saved_link = _saved_links.get(_saved_name.group(1))
            if _saved_link:
                _saved_platform = platform_from_link(_saved_link)
                _merged_platform = (
                    merged.get("platform") or ""
                ).strip().lower()
                if (
                    _saved_platform is None
                    or not _merged_platform
                    or _saved_platform == _merged_platform
                ):
                    merged["link"] = _saved_link
    # Delivery deadline (#20) and drip-feed (#15) in plain words:
    # "i need it by friday 5pm", "spread 10000 views over 2 days".
    # Parsed from THIS message and stored in the draft — the
    # deadline as an ISO string (the draft is saved to the server
    # as JSON, so no datetimes in it). "place it anyway" / "ignore
    # the deadline" clears a deadline set earlier in this order.
    if re.search(
        r"\b(place it anyway|ignore the deadline|forget the deadline)\b",
        (text or "").lower(),
    ):
        merged.pop("deadline", None)
    else:
        _deadline = parse_deadline(text)
        if _deadline is not None:
            merged["deadline"] = _deadline.isoformat()
    # "Place it normally" (after a drip-feed refusal above): drop
    # the spread, so the order goes all at once. The same for "no
    # drip" / "forget the drip".
    if re.search(
        r"\b(place it normally|no drip|forget the drip)\b",
        (text or "").lower(),
    ):
        merged.pop("drip_span", None)
    _drip_span = parse_drip_span(text)
    if _drip_span is not None:
        merged["drip_span"] = _drip_span
    # The platform comes from the LINK (owner, 14 Nov 2026): a
    # pasted t.me link is Telegram, facebook.com is Facebook, and
    # so on — whatever the AI guessed, whatever the stored draft
    # said, and whatever a forwarded/attached message says. The one
    # exception is a platform the user typed themselves in this
    # message ("YouTube subscribers" + a TikTok link): that stays a
    # mismatch and the guard below asks for the correction.
    if merged.get("link"):
        _link_platform = platform_from_link(merged["link"])
        if _link_platform is not None:
            _explicit = _explicit_platform_word(text)
            if _explicit is None or _explicit == _link_platform:
                merged["platform"] = _link_platform
                if merged.get("service_hint"):
                    merged["service_hint"] = " ".join(
                        _link_platform
                        if _platform_word_to_canonical(w) is not None
                        and _platform_word_to_canonical(w) != _link_platform
                        else w
                        for w in merged["service_hint"].split()
                    )
    # Cancelled-order guard (round 6): right after a cancel, the
    # AI sometimes returns the cancelled order's link/quantity from
    # conversation history even though the user typed nothing of the
    # sort — and the flow then auto-shows the cancelled Confirm
    # card. Only the exact cancelled values are dropped, and only
    # while the user has not typed them in this message (a link or
    # quantity the user just pasted is a deliberate fresh choice and
    # is kept). Values from the stored draft or from "that link" are
    # never touched. The record clears only when an order is placed
    # (see complete_order / place_order_now): a fresh link in a turn
    # that never becomes an order must not clear it (round 7), or
    # the AI can resurrect the cancelled link from history on the
    # next turn.
    cancelled_draft = CANCELLED_DRAFT.get(user.id) or {}
    if cancelled_draft:
        if (merged.get("link")
                and merged["link"] == cancelled_draft.get("link")
                and not _link_grounded_in_text(text, merged["link"])
                and not link_from_last):
            merged["link"] = stored.get("link")
        if (merged.get("quantity") is not None
                and merged["quantity"] == cancelled_draft.get("quantity")
                and not _quantity_grounded_in_text(
                    text, merged["quantity"])):
            merged["quantity"] = stored.get("quantity")
    # A metric change starts a fresh order: a link or quantity the
    # AI carried over from the old order's history is dropped unless
    # the user typed it in this message (round 7, 13 Nov 2026: after
    # a followers draft, "I want TikTok views" auto-showed a Confirm
    # card for the remembered link and quantity). A reply to the
    # bot's question is explicit context, not history, so it is
    # never dropped. "That link" is resolved after this and can
    # still bring the last order's link back.
    if metric_changed and quoted_text is None:
        if merged.get("link") and not _link_grounded_in_text(
            text, merged.get("link")
        ):
            merged["link"] = None
        if (merged.get("quantity") is not None
                and not _quantity_grounded_in_text(
                    text, merged.get("quantity"))):
            merged["quantity"] = None
    # A link for the wrong platform ("YouTube subscribers" to a
    # TikTok URL): point it out and wait for the correction — never
    # place a mismatched order. Handles (@user1) have no domain, so
    # they never trigger this.
    merged_platform = (merged.get("platform") or "").strip().lower()
    merged_link_platform = (
        platform_from_link(merged["link"]) if merged.get("link") else None
    )
    if (
        merged_platform
        and merged_link_platform
        and merged_platform != merged_link_platform
    ):
        PARTIAL[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(
            update.message,
            t(
                "platform_mismatch", lang,
                link_platform=merged_link_platform,
                platform=merged_platform,
            ),
            lang, voice=voice,
        )
        return
    # A link for the wrong kind of thing (round 6, 13 Nov 2026): a
    # profile link for views/likes, or a video link for followers.
    # Say so in one plain line and ask for the right link — never
    # loop "Please send the link" with no explanation. The bad link
    # is dropped from the draft so it cannot loop. TikTok links only:
    # TikTok URL shapes are unambiguous (vt.tiktok.com and /video/
    # are a video; tiktok.com/@user is a profile), while other
    # platforms' links serve several metrics and the provider
    # confirms the order on the Confirm card.
    if (merged.get("link") and merged.get("service_hint")
            and platform_from_link(merged["link"]) == "tiktok"):
        _need = metric_content_kind(merged["service_hint"])
        _have = link_content_kind(merged["link"])
        if _need is not None and _have is not None and _need != _have:
            _metric = kind_from_text(merged["service_hint"]) or "services"
            _dropped = dict(merged)
            _dropped.pop("link", None)
            PARTIAL[user.id] = {
                k: v for k, v in _dropped.items() if v is not None
            }
            _key = (
                "link_kind_video_for_profile"
                if _need == "profile"
                else "link_kind_profile_for_video"
            )
            await reply_message(
                update.message, t(_key, lang, metric=_metric),
                lang, voice=voice,
            )
            return

    # A Telegram channel link is Telegram, but it is not a post
    # (owner, 14 Nov 2026: "t.me is not only telegram post, it
    # could also be telegram channel"). When the order needs a post
    # (views, likes, comments, shares, reactions), a channel link
    # cannot be ordered on — ask for the specific post link instead
    # of showing a card for the channel. Followers/members/
    # subscribers take a channel link as-is.
    if (
        merged.get("link")
        and platform_from_link(merged["link"]) == "telegram"
        and link_content_kind(merged["link"]) == "profile"
        and _needs_post_link(merged.get("service_hint"))
    ):
        _metric = kind_from_text(merged.get("service_hint") or "") or "services"
        _dropped = dict(merged)
        _dropped.pop("link", None)
        PARTIAL[user.id] = {
            k: v for k, v in _dropped.items() if v is not None
        }
        await reply_message(
            update.message,
            t("channel_link_needs_post", lang, metric=_metric),
            lang, voice=voice,
        )
        return

    # A question about an order awaiting Confirm ("how fast can you
    # deliver it?") is answered from the pending service — the order
    # stays open and the Confirm card stays up. The PARTIAL branch
    # below already answers questions about an order being built;
    # this one covers the Confirm card. Placed before the "nothing
    # to work with" check, or the question would fall through to
    # the busy line while the AI is down.
    if not merged.get("link") and not merged.get("quantity"):
        _cid, _pending = pending_for_user(user.id)
        if _pending is not None:
            question = pending_order_question(
                text, _pending.get("quantity")
            )
            if question is not None:
                answer = pending_confirm_answer(
                    _pending.get("service"), question, lang
                )
                if answer is not None:
                    await reply_message(
                        update.message, answer, lang, voice=voice
                    )
                    return

    # A new quantity for the order already awaiting Confirm ("could I
    # get 200 views instead?") updates that card — the link and the
    # service are already known, so the bot never asks for the link
    # again (13 Nov 2026 — it did ask, and the user had to paste the
    # link a second time). A different platform or kind is a new
    # order, not a change, and still asks for its link. The quantity
    # must be typed in THIS message (live bug, 14 Nov 2026: the AI
    # carried the pending quantity forward from history, so an emoji
    # switch arrived with quantity=10 and re-issued the same card
    # here instead of reaching the correction below).
    if not merged.get("link") and merged.get("quantity"):
        _cid, _pending = pending_for_user(user.id)
        if (
            _pending is not None
            and _is_quantity_change(text, merged, _pending)
            and _quantity_grounded_in_text(text, merged["quantity"])
        ):
            service = _pending["service"]
            new_qty = int(merged["quantity"])
            error = validate_quantity(new_qty, service)
            if error:
                await reply_message(
                    update.message,
                    t(
                        "bad_quantity", lang,
                        service=short_service_name(service.get("name")),
                        min=service.get("min"), max=service.get("max"),
                    ),
                    lang, voice=voice,
                )
                return
            _pending["quantity"] = new_qty
            _pending["total"] = estimated_total_etb(
                float(service.get("rate_etb_per_1000", 0)), new_qty
            )
            _card = confirm_card_text(
                lang, service, new_qty, _pending["total"],
                _pending["link"],
                note=t("change_note", lang, quantity=new_qty),
                full_name=_pending.get("full_name", False),
            )
            _sent = await reply_message(
                update.message, _card, lang,
                reply_markup=confirm_keyboard(_cid),
            )
            _remember_card_message(_pending, update.message, _sent)
            log_confusion(user.id, text, _card, "correction")
            return

    # A different reaction emoji for the order already awaiting
    # Confirm ("I want only 🙏 reaction") re-picks the service for
    # that emoji and shows a NEW card — never the old card
    # unchanged (owner, 14 Nov 2026: a 🙏 correction re-showed the
    # Positive mix card). See try_reaction_correction. And the
    # same for the order still being built (a PARTIAL draft, no
    # card yet — screenshot bug, 16 Nov 2026): the draft is kept
    # and the Confirm card (or the quantity question) is re-shown
    # for the new emoji.
    if await try_reaction_correction(update, text, lang, voice=voice):
        return
    if await try_draft_reaction_correction(update, text, lang, voice=voice):
        return
    if await try_story_post_correction(update, text, lang, voice=voice):
        return

    # Nothing to work with at all: not understood. (A bare number or a
    # bare link with no context still counts as something: it is stored
    # and the bot asks for the next missing piece below.)
    if is_order_now(text) and intent_type != "order" and not merged.get("platform") and not merged.get("service_hint") and not merged.get("link"):
        await reply_message(update.message, t("ask_platform", lang), lang, voice=voice)
        return
    if (
        intent_type != "order"
        and not merged.get("platform")
        and not merged.get("service_hint")
        and not merged.get("link")
        and not merged.get("quantity")
        and not merged.get("service_id")
    ):
        if intent.get("gemini_failed"):
            await reply_message(update.message, t("gemini_busy", lang), lang, voice=voice)
        else:
            # Better fallback (smart-loop round 1, 14 Nov 2026):
            # a slot-specific question instead of a dead end, and
            # the confusion goes in the failure log.
            await fallback_reply(
                update.message, user.id, text, lang, voice=voice,
                merged=merged,
            )
        return
    # A named service implies its platform, so the bot asks for the
    # link next instead of the platform.
    if (
        not merged.get("platform")
        and not merged.get("service_hint")
        and last_service_id is None
        and not merged.get("service_id")
    ):
        PARTIAL[user.id] = {k: v for k, v in merged.items() if v is not None}
        await reply_message(update.message, t("ask_platform", lang), lang, voice=voice)
        return
    # A question about the order being built ("how fast can you
    # deliver it?", "wouldn't it drop?") is answered from the stored
    # service instead of asking for the link again. Only when the
    # order is actually waiting for its link and the message carries
    # no new order details — the helper checks that. The partial
    # stays open, so the next message still completes the order.
    if not merged.get("link") and (stored.get("platform") or stored.get("service_hint")):
        question = pending_order_question(text, stored.get("quantity"))
        if question is not None:
            try:
                services = await paxyo.services()
            except Exception as exc:
                log.warning("pending-question services failed: %s", exc)
                services = []
            picks = pick_services(
                services, platform=stored.get("platform"),
                service_hint=stored.get("service_hint"),
                reaction_emoji=stored.get("reaction_emoji"),
            ) if services else []
            if picks:
                service = picks[0]
                name = short_service_name(service.get("name"))
                if question == "speed":
                    avg = service.get("average_time")
                    if parse_average_time(avg) is not None:
                        answer = t("pending_speed", lang, service=name, avg=avg)
                    else:
                        answer = t("pending_speed_unknown", lang, service=name)
                else:
                    # Owner, 14 Nov 2026: Telegram reactions,
                    # Telegram views and Facebook reactions never
                    # drop — say so instead of the refill line.
                    kind = _service_never_drop_kind(service)
                    if kind is not None:
                        answer = t("never_drop", lang, service=kind)
                    else:
                        low = str(service.get("name") or "").lower()
                        if "no refill" in low:
                            refill = t("pending_no_refill", lang)
                        elif "refill" in low:
                            refill = t("pending_has_refill", lang)
                        else:
                            refill = t("pending_refill_unknown", lang)
                        answer = t(
                            "pending_drop", lang, service=name, refill=refill
                        )
                await reply_message(update.message, answer, lang, voice=voice)
                return
    if not merged.get("link"):
        PARTIAL[user.id] = {k: v for k, v in merged.items() if v is not None}
        # The emoji was the reaction choice (round 8.1, 14 Nov
        # 2026): acknowledge it first, then ask for the link —
        # never the stock link line on its own.
        _emoji = merged.get("reaction_emoji")
        if _emoji and "reaction" in (merged.get("service_hint") or "").lower():
            _reply = t("emoji_ack_order", lang, emoji=_emoji)
        else:
            _reply = ask_link_text(
                merged.get("platform"), merged.get("service_hint"), lang
            )
        # A price question that reached this far (the direct price
        # answer above found no service, or the catalogue hiccuped)
        # still gets its price in the very reply that asks for the
        # link — the price is deterministic code, never left to the
        # AI's wording (live bug, 14 Nov 2026: DeepSeek's reply
        # asked for the link with no price at all). The line is
        # only prepended when a service can actually be named, so
        # it can never duplicate a price already in the reply —
        # neither template above carries one.
        if is_price_question(text):
            _line, _p, _h, _s = await _price_line(
                user.id, text, merged.get("platform"),
                merged.get("service_hint"), merged.get("quantity"),
                lang, reaction_emoji=merged.get("reaction_emoji"),
            )
            if _line is not None:
                _reply = _line + "\n" + _reply
        await reply_message(update.message, _reply, lang, voice=voice)
        return
    # Per-customer default quantity (#12, customizations, 15 Nov
    # 2026): when the user did not say how many and the draft has
    # none, use their usual quantity for this platform+metric — so
    # they do not repeat it every time. A quantity typed in this
    # message always wins. The Confirm card below is the safety
    # net: the user can still change it before confirming.
    if not merged.get("quantity"):
        _default_metric = kind_from_text(merged.get("service_hint") or "")
        _default_qty = pref_default_quantity(
            user.id,
            (merged.get("platform") or "").strip().lower(),
            _trait_slug(_default_metric) if _default_metric else "",
        )
        if _default_qty:
            merged["quantity"] = _default_qty
    if not merged.get("quantity"):
        PARTIAL[user.id] = {k: v for k, v in merged.items() if v is not None}
        # Reaction picker (ideas batch 1 #1, 16 Nov 2026): a
        # reactions draft with no emoji chosen yet gets the emoji
        # buttons on the quantity question, so the user taps
        # instead of typing. The catalogue fetch failing just
        # means a plain question — never a failed message.
        _picker = None
        _picker_text = t("ask_quantity", lang)
        if (
            "reaction" in (merged.get("service_hint") or "").lower()
            and not merged.get("reaction_emoji")
            and merged.get("platform")
        ):
            try:
                _picker_services = await paxyo.services()
            except Exception as exc:
                log.warning(
                    "reaction picker services failed: %s", exc
                )
                _picker_services = None
            if _picker_services is not None:
                _picker = reaction_picker_keyboard(
                    merged.get("platform"), _picker_services
                )
                if _picker is not None:
                    _picker_text = (
                        t("reaction_picker_prompt", lang)
                        + "\n" + t("ask_quantity", lang)
                    )
        await reply_message(
            update.message, _picker_text, lang, voice=voice,
            reply_markup=_picker,
        )
        return

    # Complete order: fetch services, use the named service (or the
    # fastest one), and show the Confirm card. A handle target is
    # shown exactly as typed with a spelling double-check, and a
    # private account or expiring story link gets a one-line warning
    # on the card. Shortened links need no warning — the provider
    # resolves them.
    notes = []
    if merged.get("link") and str(merged["link"]).strip().startswith("@"):
        notes.append(t("check_handle", lang, handle=str(merged["link"]).strip()))
    if link_needs_warning(text, merged.get("link")):
        notes.append(t("link_warning", lang))
    # The full long service name is shown only when the user
    # entered a service ID (owner, 13 Nov 2026) — tracked above,
    # across turns of this order.
    show_full_name = bool(merged.get("named_by_id"))
    # Explicit "order now" (owner override, 13 Nov 2026): a fully
    # specified order is placed at once, no Confirm card. If it
    # cannot be placed (ambiguous metric, missing detail), fall
    # through to the normal Confirm card below.
    if is_order_now(text) and merged.get("link") and merged.get("quantity"):
        placed = await place_order_now(
            update.message, user.id, merged, lang,
            named_service_id=named_service_id,
            last_service_id=last_service_id,
            note="\n".join(notes) if notes else None,
            show_full_name=show_full_name,
        )
        if placed:
            return
    await complete_order(
        update.message, user.id, merged, lang, voice=voice,
        named_service_id=named_service_id,
        last_service_id=last_service_id,
        note="\n".join(notes) if notes else None,
        show_full_name=show_full_name,
    )


async def on_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Text in -> text out, always. The bot never answers a text
    # message with a voice message (handle_order_text gets voice=False).
    if _update_seen(update):
        return
    # A reply/quote (owner, 13 Nov 2026): when the user replies to
    # one of the bot's own messages, the quoted text is passed on so
    # the reply is read in that context ("1000" to "How many?" is
    # the quantity). Replies to anyone else's message are ignored.
    quoted = getattr(update.message, "reply_to_message", None)
    quoted_text = None
    if quoted is not None:
        sender = getattr(quoted, "from_user", None)
        if sender is None or getattr(sender, "is_bot", False):
            quoted_text = getattr(quoted, "text", None) or None
    # A text message always gets a reply: an unhandled failure
    # in the order flow must never go silent (19 Nov 2026: the
    # first live drip request after a deploy got no reply at all
    # because the dripfeed probe raised here). Same safety net
    # as on_voice; the exception is logged, not hidden.
    try:
        await handle_order_text(
            update, context, update.message.text or "", quoted_text=quoted_text
        )
    except Exception as exc:
        log.exception("text order flow failed: %s", exc)
        await update.message.reply_text(
            t("not_understood", lang_of("", update.effective_user.language_code))
        )


async def on_voice(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """A voice message (owner, 13 Nov 2026): download it, transcribe
    it with Gemini, SHOW the transcription ("You said: ...")
    so the user can see what the bot heard, then handle the
    transcribed text exactly like the same typed message. The old
    handler lumped download and transcription into one try block,
    so a download failure looked like a transcription failure and
    an exception inside handle_order_text could go silent — both
    are separate now, and the flow is wrapped so it can never go
    silent. Replies are text: the bot does not claim to take orders
    by voice (owner, 13 Nov 2026), so voice=False."""
    if _update_seen(update):
        return
    user = update.effective_user
    lang = lang_of("", user.language_code)
    try:
        voice_file = await update.message.voice.get_file()
        audio = bytes(await voice_file.download_as_bytearray())
    except Exception as exc:
        _log_ai_failure("voice download failed", exc)
        await update.message.reply_text(t("voice_download_failed", lang))
        return
    # After a restart the in-memory language and history are empty
    # and the background restore has not run yet — a voice note
    # would transcribe with no hint at all. Load the stored
    # session first (one best-effort API call, only when memory
    # is empty) so the hint can come from the user's own written
    # Amharic in the stored history (owner, 18 Nov 2026: the
    # server-stored lang was poisoned to "en", only the history
    # holds the truth). Never raises; never blocks a voice note
    # whose history is already in memory.
    if not CHAT_HISTORY.get(user.id):
        await _fetch_session(user.id)
    try:
        text = await transcribe_voice_with_retry(
            audio, user.id, user.language_code
        )
    except Exception as exc:
        _log_ai_failure("voice transcription failed", exc)
        await update.message.reply_text(t("transcribe_failed", lang))
        return
    if not text:
        await update.message.reply_text(t("transcribe_failed", lang))
        return
    await update.message.reply_text(
        t("voice_heard", lang, text=text.strip())
    )
    try:
        await handle_order_text(update, context, text, voice=False)
    except Exception as exc:
        log.exception("voice order flow failed: %s", exc)
        await update.message.reply_text(t("not_understood", lang))


async def on_video_note(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """A video note (round face message) carries no transcription:
    one plain line, never silence."""
    if _update_seen(update):
        return
    lang = lang_of("", update.effective_user.language_code)
    await update.message.reply_text(t("voice_video_note", lang))


# ------------------------------------------- context-aware media ----
# Media replies — Groq first (owner, 17 Nov 2026): when the
# user sends a GIF, a sticker or a bare emoji, the AI (the normal
# chain, Groq first, same as free chat) reacts FIRST,
# naturally, like a person reacting to that GIF/sticker/emoji —
# in the user's language. THEN, and only then, the system's
# memory is added: when the most recent order is actually delayed
# (past its average time) or failed, ONE short deterministic line
# about that real order is appended. No delay means no order
# mention at all — not even when the user seems frustrated, not
# even right after an order was placed. A media reaction is a
# reply, not a reset: it never loses a half-built order or a
# pending Confirm card, and it never invents an order that does
# not exist. Photos are NOT routed here: they are read by Gemini
# vision (route_photo_result).
_MEDIA_MOODS = {
    "😤": "frustrated", "😡": "frustrated", "🤬": "frustrated",
    "😩": "frustrated", "😠": "frustrated", "😖": "frustrated",
    "😫": "frustrated", "😭": "frustrated", "😢": "frustrated",
    "🎉": "happy", "🥳": "happy", "😍": "happy", "❤️": "happy",
    "😄": "happy", "😁": "happy", "😀": "happy", "😃": "happy",
    "🙂": "happy", "😊": "happy", "👍": "happy", "👏": "happy",
    "😂": "happy", "🤣": "happy",
    "🙏": "thanks",
    # A wave is a greeting, not thanks (owner, 14 Nov 2026 — a 👋
    # sticker got "You're welcome!"): 👋, 🙋 and ✋ all greet.
    "👋": "greeting", "🙋": "greeting", "✋": "greeting",
}


def media_mood(emoji):
    """The mood of one emoji (\"frustrated\" / \"happy\" /
    \"thanks\" / \"greeting\"), or None when it carries no mood."""
    return _MEDIA_MOODS.get(emoji)


def _bare_non_reaction_emoji(text):
    """The emoji when the message IS just one non-reaction emoji
    (\"😤\", \"👀\", \"👋\"), else None. Reaction emoji (👍 ❤️ 🔥
    🙏 😍 🎉 ...) take the reactions path instead, so they never
    reach this branch."""
    s = (text or "").strip()
    if not s or reaction_emoji(s) is not None:
        return None
    for emoji in _MEDIA_MOODS:
        if s.replace("\ufe0f", "") == emoji.replace("\ufe0f", ""):
            return emoji
    return None


def _is_bare_emoji(text: str) -> bool:
    """True when the message is only emoji — one emoji, or a short
    run of them (\"😂😂\"). Variation selectors, skin tones,
    joiners and keycap marks are stripped first; letters, digits
    and punctuation all fail, so a word or a link never counts.
    Used by the catch-all in handle_order_text: a bare emoji the
    reactions path does not claim (👀, 😤, ...) must never
    fall through to \"I did not understand\" (owner, 14 Nov 2026
    — \"he also misunderstood the emoji\")."""
    s = (text or "").strip()
    if not s:
        return False
    s = re.sub(r"[\ufe0f\u200d\U0001f3fb-\U0001f3ff\u20e3]", "", s)
    if not s:
        return False
    return all(
        "\U0001f000" <= ch <= "\U0001faff"
        or "\u2600" <= ch <= "\u27bf"
        or "\u2190" <= ch <= "\u21ff"
        or "\u2300" <= ch <= "\u23ff"
        or "\u2b00" <= ch <= "\u2bff"
        for ch in s
    )


def delay_line(ctx: dict, lang: str) -> str:
    """One short deterministic line about a delayed or failed order,
    or "" — the memory the bot adds after the AI's natural reply
    (owner, 14 Nov 2026). Only delayed/failed orders get a line:
    on-track, completed, awaiting-Confirm, draft and no-order all
    return "", so the order is never dragged into a GIF or emoji
    reply when there is no delay. The order id, service, status
    and average time all come from the real order state — never
    invented, never "soon"."""
    situation = ctx.get("situation")
    if situation not in ("delayed", "failed"):
        return ""
    order_id = ctx.get("order_id")
    service = ctx.get("service") or "your order"
    status = ctx.get("status") or ""
    avg = ctx.get("avg")
    if lang == "am":
        ref = f"orderዎ #{order_id}" if order_id else "የመጨረሻው orderዎ"
        time = f"፣ አብዛኛውን ጊዜ {avg} ያህል ይወስዳል" if avg else ""
        if situation == "failed":
            return f"በነገራችን ላይ፣ {ref} ({service}) አልተሳካም።"
        return (
            f"በነገራችን ላይ፣ {ref} ({service}) "
            f"አሁንም {status} ላይ ነው{time}።"
        )
    ref = f"order #{order_id}" if order_id else "last order"
    time = f", usually about {avg}" if avg else ""
    if situation == "failed":
        return f"By the way, your {ref} ({service}) didn't go through."
    return (
        f"By the way, your {ref} ({service}) is still {status}{time}."
    )


def _media_ai_prompt(kind, emoji):
    """What the user sent, as the AI sees it: the media kind and
    the emoji when there is one. No order info ever reaches the AI
    — the delay line is deterministic code, added afterwards."""
    if kind == "gif":
        return "The user just sent a GIF in the chat."
    if kind == "sticker":
        if emoji:
            return (
                "The user just sent a sticker in the chat. "
                f"Its emoji is {emoji}."
            )
        return "The user just sent a sticker in the chat."
    if emoji:
        return f"The user just sent the {emoji} emoji in the chat."
    return "The user just sent an emoji in the chat."


async def media_ai_reply(kind, emoji, lang: str):
    """The AI's natural reaction to one GIF, sticker or bare emoji
    — Groq first, the same chain as free chat (owner, 17 Nov
    2026). The prompt carries only the media (kind + emoji) and
    the language: no order info, so the AI can never drag an order
    into the reply. Returns the reply text, or None when the AI is
    down or answered empty — the caller then uses the deterministic
    fallback instead of going silent."""
    lang_name = {
        "am": "Amharic (Ethiopic fidels mixed with English)",
        "ti": "Tigrinya (Ge'ez script)",
        "om": "Oromo (Afaan Oromo, Latin script)",
    }.get(lang, "English")
    system = (
        "React briefly (1-2 short sentences), like a person "
        "chatting with a friend — natural, warm, human. Reply in "
        + lang_name + ". Do not mention any order, do not ask "
        "about orders, do not sell anything, and do not quote a "
        "price. Never warn the user against buying followers, "
        "likes, views, members or reactions, and never call them "
        "fake — Paxyo sells these services."
    )
    try:
        reply = await ai_generate(
            _media_ai_prompt(kind, emoji), system=system
        )
    except Exception as exc:
        _log_ai_failure("media AI reply failed", exc)
        return None
    return strip_moralizing((reply or "").strip()) or None


def _media_ai_fallback(emoji, lang: str) -> str:
    """The one-line deterministic reply when every AI provider is
    down: the bot never goes silent over a GIF, sticker or emoji.
    Mood-aware (a wave greets, frustration is heard), one line per
    language — the old rotating canned replies are gone (owner,
    14 Nov 2026: the AI replies first). The delay line, when one
    is owed, is appended separately by media_reply. The unknown-
    mood default is the neutral rule-5 line (16 Nov 2026): NEVER
    a "fun" guess — an unreadable GIF is not funny, it is just
    unread."""
    mood = media_mood(emoji)
    lines = {
        "greeting": {
            "en": "Hello! 👋 Great to see you, what would you like to order?",
            "am": "ሰላም! 👋 ደስ ብሎኛል፣ ምን ማዘዝ ይፈልጋሉ?",
        },
        "frustrated": {
            "en": "I hear you, tell me what happened and I'll sort it out.",
            "am": "ገብቶኛል፣ ምን እንደተፈጠረ ንገሩኝ።",
        },
        "thanks": {
            "en": "You're welcome! 😊 Anything else you need?",
            "am": "እንኳን ደህና መጡ! 😊 ሌላ ምን ይፈልጋሉ?",
        },
    }.get(mood) or {
        "en": t("gif_mood_unclear", "en"),
        "am": t("gif_mood_unclear", "am"),
    }
    return lines.get(lang) or lines["en"]


def _parse_created_at(value):
    """An ISO-8601 created_at string -> aware datetime, or None
    when the value is missing or unparseable."""
    if not value:
        return None
    try:
        dt = datetime.fromisoformat(str(value).strip())
    except (ValueError, TypeError):
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def _order_is_delayed(order, avg_minutes):
    """True when an in-progress order is past its average time.
    Unknown created_at or unknown average time -> True: the old
    behaviour assumed the user was waiting, and a delay apology
    is the safe reply when the bot genuinely cannot tell."""
    if avg_minutes is None:
        return True
    created = _parse_created_at(order.get("created_at"))
    if created is None:
        return True
    elapsed = (datetime.now(timezone.utc) - created).total_seconds() / 60
    return elapsed > avg_minutes


async def media_order_context(user_id: int) -> dict:
    """The order situation a media reply is grounded in: the most
    recent placed order's real status and average time (same data
    as the \"why hasn't it started\" answer), a pending Confirm
    card, a half-built draft, or nothing at all. Never invents an
    order — \"none\" means no order is claimed. An in-progress
    order is \"delayed\" only when its elapsed time is past its
    average time (owner, 14 Nov 2026 — a GIF while order #1837
    was merely in progress got a delay apology); otherwise it is
    \"on_track\"."""
    try:
        last = await resolve_last_order(user_id)
    except Exception as exc:
        log.warning("media order context failed: %s", exc)
        last = None
    if last:
        status = str(last.get("status") or "").strip().lower()
        # Prefer the combined id (second provider, 15 Nov 2026):
        # the bare id alone could read the other provider's
        # service of the same number.
        service_id = last.get("combined_id") or last.get("service_id")
        service_name = last.get("service_name")
        avg = None
        if service_id is not None:
            try:
                services = await paxyo.services()
                found = find_service_by_id(services, service_id)
                if found is not None:
                    avg = found.get("average_time")
                    service_name = found.get("name")
            except Exception as exc:
                log.warning("media order context services failed: %s", exc)
        if status in ("completed", "complete"):
            situation = "completed"
        elif status in (
            "pending", "in_progress", "in progress",
            "processing", "partial",
        ):
            situation = (
                "delayed"
                if _order_is_delayed(last, parse_average_time(avg))
                else "on_track"
            )
        elif status in ("failed", "cancelled", "canceled", "refunded"):
            situation = "failed"
        else:
            situation = "none"
        return {
            "situation": situation,
            "order_id": last.get("id") or last.get("order_id"),
            "status": status,
            "service": (
                short_service_name(service_name)
                or f"service {service_id}"
            ),
            "avg": avg, "total": last.get("charge"),
        }
    _cid, _pending = pending_for_user(user_id)
    if _pending is not None:
        service = _pending.get("service") or {}
        return {
            "situation": "awaiting_confirm",
            "service": short_service_name(service.get("name")) or "your order",
            "total": _pending.get("total"),
            "order_id": None, "status": None, "avg": None,
        }
    if PARTIAL.get(user_id):
        return {
            "situation": "draft", "service": None,
            "order_id": None, "status": None, "avg": None,
        }
    return {
        "situation": "none", "service": None,
        "order_id": None, "status": None, "avg": None,
    }


# ------------------------------------------------- GIF / sticker mood -----
# Media & GIF Reaction Handling (William, 16 Nov 2026): the bot
# must WATCH a GIF, sticker or image and reply to its mood — never
# a generic "fun" line. Gemini vision classifies the media into
# one of four moods; anything it cannot classify (or cannot read
# at all) is "unclear" and gets the neutral rule-5 reply. One word
# back from the model keeps the call cheap; frames are small and
# few (one frame for a GIF, the image itself for a sticker).
GIF_MOOD_PROMPT = (
    "Look at this image — one frame from a GIF or a sticker a "
    "customer just sent in a chat. What emotion does it show? "
    "Reply with exactly one word and nothing else: angry, "
    "confused, happy, sad, or unclear. Angry covers frustrated, "
    "annoyed and yelling; confused covers waiting, impatient and "
    "puzzled; happy covers excited, celebrating and thankful; sad "
    "covers disappointed and crying. Use unclear only when no "
    "emotion can be read at all."
)

GIF_MOODS = ("angry", "confused", "happy", "sad", "unclear")


def _parse_gif_mood(text: str) -> str:
    """One mood word from the vision reply, or "unclear" when it
    names no known mood. Liberal on purpose: the model may answer
    "angry!" or a short sentence — the first known word wins. Pure."""
    low = (text or "").strip().lower()
    if not low:
        return "unclear"
    for mood in GIF_MOODS:
        if re.search(r"\b" + re.escape(mood) + r"\b", low):
            return mood
    return "unclear"


async def classify_media_mood(image_bytes: bytes,
                              mime_type: str = "image/jpeg") -> str:
    """One mood word from Gemini vision for one frame/image, or
    "unclear" when vision fails, answers empty, or names no known
    mood. Never raises — the caller answers neutrally instead."""
    if not image_bytes:
        return "unclear"
    try:
        raw = await gemini_vision(
            image_bytes, prompt=GIF_MOOD_PROMPT, mime_type=mime_type
        )
    except Exception as exc:
        _log_ai_failure("gif mood vision failed", exc)
        return "unclear"
    return _parse_gif_mood(raw)


async def _extract_gif_frame(video_bytes: bytes):
    """One small JPEG frame from a GIF/MP4 animation (or a video
    sticker): the middle frame when ffprobe can read the duration,
    else half a second in, else the first frame. Returns None when
    ffmpeg is missing (Dockerfile installs it; without it the GIF
    simply cannot be watched), the bytes are not a video, or
    anything fails. Never raises; the video bytes are written to
    one temp file and deleted afterwards."""
    if not video_bytes or len(video_bytes) > MAX_PHOTO_BYTES:
        return None
    if shutil.which("ffmpeg") is None:
        return None
    tmp = None
    try:
        with tempfile.NamedTemporaryFile(suffix=".mp4", delete=False) as f:
            f.write(video_bytes)
            tmp = f.name
        ts = 0.5
        try:
            probe = await asyncio.create_subprocess_exec(
                "ffprobe", "-v", "error", "-show_entries",
                "format=duration", "-of", "csv=p=0", tmp,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            out, _ = await asyncio.wait_for(probe.communicate(), timeout=10)
            dur = float((out or b"").decode().strip() or 0)
            if dur > 0:
                ts = dur / 2
        except Exception:
            pass
        for attempt_ts in (ts, 0.0):
            try:
                proc = await asyncio.create_subprocess_exec(
                    "ffmpeg", "-y", "-ss", str(attempt_ts), "-i", tmp,
                    "-frames:v", "1", "-vf", "scale=480:-1",
                    "-f", "image2pipe", "-vcodec", "mjpeg", "pipe:1",
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                )
                out, _ = await asyncio.wait_for(
                    proc.communicate(), timeout=15
                )
            except Exception:
                continue
            if out:
                return out
        return None
    except Exception as exc:
        log.warning("gif frame extraction failed: %s", exc)
        return None
    finally:
        if tmp:
            try:
                os.unlink(tmp)
            except OSError:
                pass


async def _download_media_file(obj):
    """The bytes of a Telegram file object (animation / sticker),
    or None when there is no file, it is too big, or the download
    fails. Never raises."""
    if obj is None:
        return None
    try:
        size = getattr(obj, "file_size", None)
        if isinstance(size, int) and size > MAX_PHOTO_BYTES:
            return None
        f = await obj.get_file()
        data = bytes(await f.download_as_bytearray())
    except Exception as exc:
        log.warning("media download failed: %s", exc)
        return None
    if not data or len(data) > MAX_PHOTO_BYTES:
        return None
    return data


async def describe_media_mood(kind: str, message) -> str:
    """The mood of a GIF or sticker the user just sent, from vision:
    "angry" / "confused" / "happy" / "sad" / "unclear". A GIF is an
    MP4 animation, so one frame is pulled with ffmpeg; a video
    sticker (.webm) the same way; a static sticker (.webp) goes to
    vision as-is. An animated (.tgs) sticker has no raster image
    to read, so it is "unclear". "unclear" also covers every
    failure — no file, no ffmpeg, vision down — so the caller can
    answer neutrally instead of guessing. Never raises."""
    if kind == "gif":
        data = await _download_media_file(
            getattr(message, "animation", None)
        )
        if data is None:
            return "unclear"
        frame = await _extract_gif_frame(data)
        if frame is None:
            return "unclear"
        return await classify_media_mood(frame)
    if kind == "sticker":
        sticker = getattr(message, "sticker", None)
        if sticker is None:
            return "unclear"
        if getattr(sticker, "is_animated", False) is True:
            return "unclear"
        data = await _download_media_file(sticker)
        if data is None:
            return "unclear"
        if getattr(sticker, "is_video", False) is True:
            frame = await _extract_gif_frame(data)
            if frame is None:
                return "unclear"
            return await classify_media_mood(frame)
        return await classify_media_mood(data, mime_type="image/webp")
    return "unclear"


async def media_reply(update, emoji, lang: str, voice: bool = False,
                      kind: str = "emoji", mood: str = None) -> str:
    """Answer one media reaction (GIF, sticker, bare emoji) and
    return the text sent. DeepSeek (the normal AI chain, same as
    free chat) reacts FIRST, naturally, like a person — the prompt
    carries only the media (kind + emoji) and the language, never
    order info. THEN, and only then, the system's memory is added:
    when the user's most recent order is actually delayed (past its
    average time) or failed, one short deterministic line about
    that real order is appended. No delay means no order mention
    at all — not even when the user seems frustrated, not even
    right after an order was placed (owner, 14 Nov 2026). Reads
    order state only — it never clears a draft or a Confirm card.
    Photos are NOT routed here: they are read by Gemini vision
    (route_photo_result) and keep working as before.

    Media & GIF Reaction Handling (16 Nov 2026): for a GIF or a
    sticker the reply comes from the VISION mood (the `mood`
    argument, classified by describe_media_mood) — never from the
    blind text AI, which could only guess "fun". A known mood gets
    its matching line; "unclear" (vision could not read it) falls
    back to the emoji mood when the sticker carries one, else the
    neutral rule-5 line. Bare emoji keep the old path: the AI
    reacts first, the deterministic fallback covers it being down.
    """
    user = update.effective_user
    if kind in ("gif", "sticker") and mood in (
        "angry", "confused", "happy", "sad",
    ):
        text = t(f"gif_mood_{mood}", lang)
    elif kind in ("gif", "sticker"):
        # Vision could not read it: the sticker's emoji still
        # speaks when it carries a known mood (a 😡 sticker is
        # frustration), otherwise the neutral line — never a guess.
        text = _media_ai_fallback(emoji, lang)
    else:
        text = await media_ai_reply(kind, emoji, lang)
        if not text:
            text = _media_ai_fallback(emoji, lang)
    ctx = await media_order_context(user.id)
    line = delay_line(ctx, lang)
    if line:
        text = text + "\n" + line
    if voice:
        await reply_message(update.message, text, lang, voice=voice)
    else:
        # No long dash in any reply (owner, 17 Nov 2026): the AI
        # reply can carry one, and this send bypasses reply_message.
        await update.message.reply_text(_strip_dashes(text))
    return text


async def media_reply_for_text(update, emoji, lang: str, voice: bool = False) -> bool:
    """A bare non-reaction emoji in handle_order_text: answer it
    from the user's situation. Always True when called — the
    caller returns."""
    await media_reply(update, emoji, lang, voice=voice)
    return True


async def on_animation(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """A GIF (owner, 13 Nov 2026): never silent, never
    'I did not understand'. A caption is the user's message and is
    handled normally; otherwise the GIF is WATCHED first (16 Nov
    2026 — vision classifies its mood, 1 frame via ffmpeg) and the
    reply matches the mood — an angry GIF is never called "fun",
    and a GIF vision cannot read gets the neutral line. Only a
    genuinely delayed or failed order adds one short line about
    that order (owner, 14 Nov 2026)."""
    if _update_seen(update):
        return
    caption = (update.message.caption or "").strip()
    if caption:
        await handle_order_text(update, context, caption)
        return
    user = update.effective_user
    lang = LAST_LANG.get(user.id) or lang_of("", user.language_code)
    mood = await describe_media_mood("gif", update.message)
    await media_reply(update, None, lang, kind="gif", mood=mood)


async def on_sticker(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """A sticker (owner, 13 Nov 2026): same as a GIF — a caption is
    the user's message; otherwise the sticker is watched first
    (16 Nov 2026): a static sticker goes to vision as webp, a
    video sticker via one ffmpeg frame, an animated (.tgs) sticker
    cannot be read. When vision cannot read it, the sticker's own
    emoji still speaks when it carries a known mood — otherwise
    the neutral line, never a "fun" guess."""
    if _update_seen(update):
        return
    caption = (update.message.caption or "").strip()
    if caption:
        await handle_order_text(update, context, caption)
        return
    user = update.effective_user
    lang = LAST_LANG.get(user.id) or lang_of("", user.language_code)
    sticker = getattr(update.message, "sticker", None)
    emoji = getattr(sticker, "emoji", None) if sticker else None
    mood = await describe_media_mood("sticker", update.message)
    await media_reply(update, emoji, lang, kind="sticker", mood=mood)


# ------------------------------------------------------------ photos ------
# A picture in gets a picture-reading reply, not "I did not
# understand". The largest size is downloaded (in memory only — never
# written to disk) and sent to Gemini vision, which returns compact
# JSON (see VISION_PROMPT). Routing:
# - deposit_receipt: what was found is shown and the user is offered
#   a recheck of their most recent deposit (button or a bare "yes").
#   That recheck is the same deposit_status_text the text flow uses,
#   so the server re-verifies with Chapa before answering.
# - order: the extracted link starts the order flow with the intent
#   already built (no second Gemini call). A photo of a profile/post
#   while an order is being built fills the missing link the same
#   way a typed link would, because handle_order_text merges PARTIAL.
# - support/other: the summary plus one short follow-up question.
# A vision failure, timeout or unreadable result gets one short
# fallback line — never a retry loop.

def receipt_keyboard(lang: str) -> InlineKeyboardMarkup:
    """One button: "Yes, check it" — recheck the deposit the receipt
    is about. The button is text-only, like the Confirm card."""
    return InlineKeyboardMarkup(
        [[InlineKeyboardButton(t("check_deposit_button", lang),
                               callback_data="checkdep:")]]
    )


def _usable_photo_link(link):
    """The vision-read link, normalized to a usable post/profile
    URL, or None. A scheme-less "instagram.com/someone" gets
    https://; a bare username, a link with no recognisable
    platform domain, or anything the order flow cannot place is
    never injected — the caller asks for the link instead. The
    link is never guessed: only what vision actually read, with
    its scheme completed."""
    raw = str(link or "").strip()
    if not raw:
        return None
    if "://" not in raw:
        raw = "https://" + raw.lstrip("/")
    found = extract_links(raw)
    if not found:
        return None
    if platform_from_link(found[0]) is None:
        return None
    return found[0]


async def route_photo_result(update, result: dict, lang: str):
    """Act on a parsed vision result, in the user's language."""
    user = update.effective_user
    want = result.get("want") or "other"
    if want == "deposit_receipt":
        amount = result.get("amount")
        tx_ref = result.get("tx_ref")
        if amount is None and not tx_ref:
            # A payment screenshot the model could not read: say so
            # and ask for the amount in text.
            await update.message.reply_text(t("photo_receipt_no_details", lang))
            return
        # What was found, then offer the recheck. The recheck does
        # not need the tx_ref — deposit_status_text rechecks the
        # user's most recent deposit — but the ref is remembered in
        # case the user quotes it, and shown so they can confirm it
        # is theirs.
        details = "a payment"
        if amount is not None:
            details = f"a {format_money(amount)} ETB payment"
        if tx_ref:
            details += f", ref {tx_ref}"
        RECEIPT_OFFER[user.id] = {"amount": amount, "tx_ref": tx_ref}
        await update.message.reply_text(
            t("photo_receipt_found", lang, details=details),
            reply_markup=receipt_keyboard(lang),
        )
        return
    if want == "order":
        link = result.get("link")
        platform = result.get("platform")
        metric = result.get("metric")
        # The hint for the draft: the platform the LINK belongs to
        # wins over vision's platform word (the link decides, as in
        # the text flow); the metric rides along when vision saw one.
        if link:
            usable = _usable_photo_link(link)
            if usable is not None:
                link_platform = platform_from_link(usable)
                hint = None
                if metric:
                    hint = " ".join(
                        p for p in (link_platform, metric) if p
                    ) or None
                # The link is already classified by vision: inject the
                # intent so the order flow starts without a second
                # Gemini call. Platform from the link's domain, so the
                # flow goes straight to "how many?".
                intent = {
                    "intent": "order",
                    "platform": link_platform,
                    "service_hint": hint,
                    "link": usable,
                    "quantity": None,
                    "interval_minutes": None,
                    "amount": None,
                    "method": None,
                    "phone": None,
                }
                await handle_order_text(
                    update, None, usable, intent=intent
                )
                return
            # A link vision read but that is not a usable post/profile
            # URL is never injected — fall through to the no-link
            # path below, which asks for the link instead.
        hint = " ".join(
            p for p in (platform, metric) if p
        ) or None
        if platform or metric:
            # No usable link, but the picture shows what the order is
            # for: keep the platform/metric in the draft and ask for
            # the link with the per-type question — never guess a link.
            PARTIAL[user.id] = {
                k: v for k, v in {
                    "platform": platform, "service_hint": hint,
                }.items() if v is not None
            }
        username = result.get("username")
        if username:
            await update.message.reply_text(
                t("photo_order_username", lang, username=username)
            )
            return
        if platform or metric:
            await update.message.reply_text(
                ask_link_text(platform, hint, lang)
            )
            return
        await update.message.reply_text(t("photo_unreadable", lang))
        return
    # support / other: the summary plus one short follow-up question.
    summary = (result.get("summary") or "").strip()
    if not summary:
        await update.message.reply_text(t("photo_unreadable", lang))
        return
    await update.message.reply_text(t("photo_other", lang, summary=summary))


async def on_photo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if _update_seen(update):
        return
    user = update.effective_user
    message = update.message
    # Language from the caption when there is one, else the
    # Telegram account language; default English.
    lang = lang_of(message.caption or "", user.language_code)
    photos = message.photo or []
    if not photos:
        await message.reply_text(t("photo_unreadable", lang))
        return
    # The largest size is last.
    photo = photos[-1]
    size = getattr(photo, "file_size", None)
    if size is not None and size > MAX_PHOTO_BYTES:
        await message.reply_text(t("photo_too_big", lang))
        return
    try:
        photo_file = await photo.get_file()
        image = bytes(await photo_file.download_as_bytearray())
    except Exception as exc:
        log.warning("photo download failed: %s", exc)
        await message.reply_text(t("photo_unreadable", lang))
        return
    if len(image) > MAX_PHOTO_BYTES:
        await message.reply_text(t("photo_too_big", lang))
        return
    try:
        raw = await ai_vision(image)
    except Exception as exc:
        _log_ai_failure("ai_vision failed", exc)
        await message.reply_text(t("photo_unreadable", lang))
        return
    result = parse_vision_result(raw)
    if result is None:
        await message.reply_text(t("photo_unreadable", lang))
        return
    await route_photo_result(update, result, lang)


async def _edit_callback_message(query, text, reply_markup=None):
    """Edit the message behind a tapped button, whether it is text
    or a photo (19 Nov 2026): the deposit guide is a photo with a
    caption, and Telegram refuses editMessageText on a photo
    ("there is no text in the message to edit"), so tapping
    Deposit now did nothing live. Try the text edit first, then
    the caption edit, then a fresh message as a last resort (a
    caption over 1024 chars is refused too); the user always sees
    the result, and a failure is logged instead of crashing the
    callback."""
    try:
        await query.edit_message_text(text, reply_markup=reply_markup)
        return
    except Exception as exc:
        log.warning("callback text edit failed, trying caption: %s", exc)
    try:
        await query.edit_message_caption(
            caption=text, reply_markup=reply_markup
        )
        return
    except Exception as exc:
        log.warning("callback caption edit failed, sending anew: %s", exc)
    try:
        await query.message.reply_text(text, reply_markup=reply_markup)
    except Exception as exc:
        log.warning("callback reply failed: %s", exc)


async def on_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if _update_seen(update):
        return
    query = update.callback_query
    await query.answer()
    user = update.effective_user
    lang = lang_of(query.message.text or "", user.language_code)
    action, _, arg = (query.data or "").partition(":")

    if action in ("rescue_yes", "rescue_no"):
        # Ask-first (#6, customizations, 15 Nov 2026): the
        # customer's answer to a rescue proposal. Yes re-invokes
        # the rescue with the accepted proposal (the proposed
        # service when it is still usable, else a fresh pick);
        # No refunds only. The ask message is replaced by the
        # outcome, so the chat never keeps a dead Yes/No card —
        # and a tap on an already-answered proposal says so.
        app = getattr(context, "application", None)
        watched = WATCHED_ORDERS.get(arg)
        if watched is None or watched.get("user_id") != user.id:
            await query.edit_message_text(t("cancelled", lang))
            return
        proposal = watched.get("rescue_proposal")
        if proposal is None:
            await query.edit_message_text(
                "This one is already handled, nothing more to do here."
            )
            return
        watched.pop("rescue_proposal", None)
        if action == "rescue_no":
            await query.edit_message_text(
                await _decline_rescue_proposal(app, arg, watched, proposal)
            )
            return
        await query.edit_message_text("Moving it, one moment…")
        kind = proposal.get("kind")
        if kind == "failed":
            await _attempt_failed_rescue(
                app, arg, watched, proposal=proposal
            )
        elif kind == "split_test":
            await _attempt_split_test_rescue(
                app, arg, watched, proposal=proposal
            )
        else:
            await _attempt_stall_rescue(
                app, arg, watched, proposal=proposal
            )
        return

    if action == "checkdep":
        # "Yes, check it" on a payment-receipt photo: recheck the
        # most recent deposit and replace the receipt message with
        # the result (same recheck the text flow uses).
        RECEIPT_OFFER.pop(user.id, None)
        await query.edit_message_text(
            await deposit_status_text(
                user.id, lang,
                app=getattr(context, "application", None),
                username=user.username,
                first_name=user.first_name,
            )
        )
        return

    if action == "depshort":
        # One-tap deposit of exactly the shortfall (15 Nov 2026,
        # feature 1): the low-balance warning's button carries the
        # shortfall amount. It shows the deposit Confirm card
        # straight away (amount only, 17 Nov 2026 — the method +
        # phone are chosen on the popup page after Confirm), and
        # nothing is created until the deposit Confirm card is
        # tapped. The order's own Confirm card stays open
        # underneath.
        try:
            _amount = float(arg)
        except (TypeError, ValueError):
            _amount = None
        if _amount is None or _amount <= 0:
            await query.edit_message_text(t("cancelled", lang))
            return
        card_text, card_markup = deposit_confirm_card(
            user.id, _amount, lang
        )
        await query.edit_message_text(card_text, reply_markup=card_markup)
        return

    if action == "depguide":
        # Deposit now on the guide card (19 Nov 2026): continue to
        # the Confirm card for the amount the guide was shown for.
        # The amount rides on DEPOSIT_DRAFT, saved when the guide
        # was shown; a missing draft (a restart dropped it) asks
        # for the amount instead. The guide itself never created
        # anything, so this is the first Confirm card for the
        # deposit. The guide is a photo with a caption, so the edit
        # must go through _edit_callback_message, which falls back
        # to the caption edit — a plain edit_message_text is
        # refused by Telegram on a photo and the tap does nothing.
        draft = DEPOSIT_DRAFT.pop(user.id, None) or {}
        amount = draft.get("amount")
        if amount is None:
            await _edit_callback_message(
                query, t("ask_deposit_amount", lang)
            )
            return
        card_text, card_markup = deposit_confirm_card(
            user.id, amount, lang
        )
        await _edit_callback_message(
            query, card_text, reply_markup=card_markup
        )
        return

    if action == "depagain":
        # Remember deposit method (23, 15 Nov 2026) — the method
        # itself is now chosen on the popup page (17 Nov 2026),
        # so both "again" and "different method" just show the
        # deposit Confirm card for the amount on file. No amount
        # on file (a restart dropped the draft) asks for the
        # amount instead. These buttons only exist on old messages;
        # new flows never offer a method in chat.
        if arg not in ("telebirr", "cbe", "cbebirr", "mpesa"):
            await query.edit_message_text(t("cancelled", lang))
            return
        draft = DEPOSIT_DRAFT.get(user.id) or {}
        if draft.get("amount") is None:
            await query.edit_message_text(t("ask_deposit_amount", lang))
            return
        card_text, card_markup = deposit_confirm_card(
            user.id, draft["amount"], lang
        )
        await query.edit_message_text(card_text, reply_markup=card_markup)
        return

    if action == "depdiff":
        # "Use a different method" (23): the method is chosen on
        # the popup page now, so this just shows the deposit
        # Confirm card for the amount on file.
        draft = DEPOSIT_DRAFT.get(user.id) or {}
        if draft.get("amount") is None:
            await query.edit_message_text(t("ask_deposit_amount", lang))
            return
        card_text, card_markup = deposit_confirm_card(
            user.id, draft["amount"], lang
        )
        await query.edit_message_text(card_text, reply_markup=card_markup)
        return

    if action == "start_order":
        # "Start an order" from the how-to guide: drop any half-built
        # order or plan and ask which platform, so the next message
        # starts a fresh order.
        PARTIAL.pop(user.id, None)
        RECURRING_DRAFT.pop(user.id, None)
        DELAYED_DRAFT.pop(user.id, None)
        await query.edit_message_text(t("ask_platform", lang))
        return

    if action == "react":
        # Reaction picker (ideas batch 1 #1, 16 Nov 2026): the user
        # tapped an emoji button on the quantity question. The
        # draft's emoji becomes the tapped one and the draft
        # continues — a Confirm card when the quantity is already
        # valid, else the plain quantity question (the choice is
        # made, so no picker this time). No exact service for the
        # tapped emoji is complete_order's honest
        # no_exact_reaction line, never a silent different emoji.
        # A stale button (the draft is gone) gets an honest line.
        draft = PARTIAL.get(user.id)
        if (
            not draft
            or "reaction" not in (draft.get("service_hint") or "").lower()
        ):
            await query.edit_message_text(t("reaction_picker_gone", lang))
            return
        touch_partial_activity(user.id)
        draft["reaction_emoji"] = arg
        merged = {
            k: draft.get(k)
            for k in (
                "platform", "service_hint", "link", "quantity",
                "service_id", "named_by_id", "reaction_emoji",
                "story",
            )
        }
        await query.edit_message_text(
            t("reaction_picker_picked", lang, emoji=arg)
        )
        if not merged.get("quantity"):
            PARTIAL[user.id] = {
                k: v for k, v in merged.items() if v is not None
            }
            await reply_message(
                query.message, t("ask_quantity", lang), lang,
            )
            return
        await complete_order(
            query.message, user.id, merged, lang,
            named_service_id=merged.get("service_id"),
            show_full_name=bool(merged.get("named_by_id")),
        )
        return

    if action == "resume_draft":
        # Abandoned-order nudge (feature 4, 15 Nov 2026): the user
        # tapped "Resume my order" on the nudge. Re-ask for the
        # next missing piece of THAT draft — platform -> link ->
        # quantity, the same order (and the same question helper)
        # as the normal flow — so the user picks up where they
        # left off. A draft that is already complete shows its
        # Confirm card instead (complete_order, the flow's next
        # step). A draft that is gone by now (completed, cancelled,
        # expired) gets an honest answer, never a rebuilt order.
        draft = PARTIAL.get(user.id)
        if not draft:
            await query.edit_message_text(t("resume_draft_gone", lang))
            return
        touch_partial_activity(user.id)
        resume_lang = LAST_LANG.get(user.id) or lang
        merged = {
            k: draft.get(k)
            for k in (
                "platform", "service_hint", "link", "quantity",
                "service_id", "named_by_id", "reaction_emoji",
            )
        }
        if (
            (merged.get("platform") or merged.get("service_hint"))
            and merged.get("link")
            and merged.get("quantity")
        ):
            await complete_order(
                query.message, user.id, merged, resume_lang,
                named_service_id=merged.get("service_id"),
                show_full_name=bool(merged.get("named_by_id")),
            )
            return
        await query.edit_message_text(
            _fallback_slot_question(user.id, {}, resume_lang)
        )
        return

    if action == "resumedep":
        # Abandoned-deposit nudge (14, 15 Nov 2026): "Resume my
        # deposit" re-shows the SAME Confirm card, so the existing
        # Confirm/Cancel tail handles the tap. A card that is gone
        # by now (confirmed, cancelled, replaced) gets an honest
        # answer, never a rebuilt deposit. The abandoned record is
        # dropped: one nudge per abandoned deposit, ever.
        dep_draft = PENDING_DEPOSIT.get(arg)
        if dep_draft is None or dep_draft.get("user_id") != user.id:
            await query.edit_message_text(
                t("abandoned_deposit_gone", lang)
            )
            return
        DEPOSIT_ABANDONED.pop(user.id, None)
        lines = [
            t("confirm_title", lang),
            "",
            f"💰 {format_money(dep_draft['amount'])} ETB",
        ]
        _validated = VALIDATED_PROMO.get(user.id) or {}
        if _validated.get("code"):
            lines.append(
                t(
                    "deposit_confirm_promo", lang,
                    code=_validated["code"],
                    percent=(
                        _validated["percent"]
                        if _validated.get("percent") is not None
                        else "?"
                    ),
                )
            )
        await query.edit_message_text(
            "\n".join(lines), reply_markup=confirm_keyboard(arg)
        )
        return

    if action == "usefastest":
        # "Use the fastest one" after a named service turned out
        # unusable: resume the same order with the fastest pick.
        # The Confirm card arrives as a new message (the error message
        # stays above it, so the user sees what happened).
        fallback = FASTEST_FALLBACK.pop(arg, None)
        if fallback is None or fallback["user_id"] != user.id:
            await query.edit_message_text(t("cancelled", lang))
            return
        merged = dict(fallback["merged"])
        merged.pop("service_id", None)
        # The stored order (PARTIAL) may still know the metric the
        # failed message dropped ("tiktok views"): use it, so the
        # fallback picks the fastest VIEWS service, never the
        # globally fastest service for the platform.
        stored = PARTIAL.get(user.id) or {}
        if not merged.get("service_hint") and stored.get("service_hint"):
            merged["service_hint"] = stored["service_hint"]
        if not merged.get("platform") and stored.get("platform"):
            merged["platform"] = stored["platform"]
        # The user already chose "the fastest one" — do not ask
        # which metric; the fastest pick is what they tapped for.
        await complete_order(query.message, user.id, merged, lang,
                             ask_metric=False)
        return

    if action == "retrydep":
        # One-tap deposit retry (ideas batch, 15 Nov 2026): restart
        # the same deposit draft (amount/method/phone kept) after a
        # failed push. The draft is consumed here — a retry that
        # fails again re-saves it through start_deposit's failure
        # path, so the button stays usable. Same double-tap guard
        # as Confirm (19 Nov 2026): a second tap while the first
        # retry is still starting gets the processing message,
        # never "Order cancelled".
        retry_key = f"retry:{user.id}"
        if DEPOSIT_CONFIRM_IN_FLIGHT.get(retry_key) == user.id:
            await _edit_callback_message(
                query, t("deposit_confirm_processing", lang)
            )
            return
        draft = FAILED_DEPOSIT.pop(user.id, None)
        if draft is None:
            await _edit_callback_message(query, t("cancelled", lang))
            return
        DEPOSIT_CONFIRM_IN_FLIGHT[retry_key] = user.id
        try:
            await _edit_callback_message(
                query, t("deposit_confirm_processing", lang)
            )
            result, error = await start_deposit(draft, user.id)
            # Ban (19 Nov 2026): a banned user deposits nothing.
            if error == "banned":
                await _edit_callback_message(query, t("banned", lang))
                return
            if error:
                if error in ("deposit_not_ready", "deposit_failed", "deposit_unavailable"):
                    FAILED_DEPOSIT[user.id] = dict(draft)
                    text, markup = deposit_webapp_message(
                        draft["amount"], lang,
                        allow_retry=True, user_id=user.id,
                    )
                    await _edit_callback_message(
                        query, text, reply_markup=markup
                    )
                else:
                    await _edit_callback_message(
                        query, _strip_dashes(error)
                    )
                return
            await _edit_callback_message(
                query,
                t(
                    "deposit_popup_ready", lang,
                    amount=format_money(draft["amount"]),
                ),
                reply_markup=deposit_success_markup(result, draft, lang),
            )
        finally:
            DEPOSIT_CONFIRM_IN_FLIGHT.pop(retry_key, None)
        return

    if action == "reorder":
        # One-tap reorder (ideas batch, 15 Nov 2026): rebuild the
        # same service/quantity/link as a new draft and show the
        # Confirm card. The order comes from the server's list, so
        # a reorder after a restart still works.
        try:
            orders = await paxyo.recent_orders(user.id)
        except Exception as exc:
            log.warning("reorder list failed: %s", exc)
            await query.edit_message_text(t("not_understood", lang))
            return
        order = next(
            (o for o in orders if str(o.get("id") or o.get("order_id")) == arg),
            None,
        )
        if order is None:
            await query.edit_message_text(t("reorder_not_found", lang))
            return
        try:
            services = await paxyo.services()
        except Exception:
            services = []
        service = None
        # Prefer the combined id (second provider, 15 Nov 2026):
        # the bare id alone could re-pin the other provider's
        # service of the same number.
        combined = order.get("combined_id")
        if combined:
            service = find_service_by_id(services or [], combined)
        if service is None:
            for s in services or []:
                try:
                    if int(s.get("service")) == int(order.get("service_id") or 0):
                        service = s
                        break
                except (TypeError, ValueError):
                    continue
        platform = None
        hint = None
        if service is not None:
            platform, _hint = _platform_hint_of_service(service)
            metric = _primary_metric(" ".join(_name_kinds(service.get("name"))))
            if metric:
                hint = f"{platform} {metric}" if platform else metric
        merged = {
            "platform": platform,
            "service_hint": hint,
            "link": order.get("link"),
            "quantity": order.get("quantity"),
        }
        named = order.get("combined_id") or None
        if named is None:
            try:
                named = int(order.get("service_id") or 0) or None
            except (TypeError, ValueError):
                named = None
        await complete_order(
            query.message, user.id, merged, lang,
            named_service_id=named, ask_metric=False,
        )
        return

    if action == "browse":
        # Browse services (11, 15 Nov 2026): tapping a service in
        # the list starts an order for it — the service is pinned
        # one-shot (NUDGE_SERVICE, like the first-order nudge) and
        # the bot asks for the link; the normal flow then asks the
        # quantity and shows the Confirm card for THAT service.
        # The list may be gone after a restart: re-fetch the
        # catalogue and find the service there instead. Any
        # half-built draft is replaced — the tap is an explicit
        # "order this service", like the "Start an order" button.
        service = None
        entry = BROWSE_LISTS.get(user.id)
        if entry is not None:
            # A combined-id tap ("browse:smm:7501", second provider,
            # 15 Nov 2026) matches exactly; a bare-id tap (an older
            # button) matches the first service of that number,
            # GOP first — exactly like before.
            if ":" in (arg or ""):
                service = find_service_by_id(entry.get("services") or [], arg)
            else:
                for s in entry.get("services") or []:
                    try:
                        if int(s.get("service")) == int(arg or 0):
                            service = s
                            break
                    except (TypeError, ValueError):
                        continue
        if service is None:
            try:
                services = await paxyo.services()
            except Exception as exc:
                log.warning("browse tap services failed: %s", exc)
                services = []
            service = find_service_by_id(services or [], arg)
        if service is None:
            await query.edit_message_text(t("cancelled", lang))
            return
        try:
            sid = int(service.get("service"))
        except (TypeError, ValueError):
            await query.edit_message_text(t("cancelled", lang))
            return
        platform, _hint = _platform_hint_of_service(service)
        metric = _primary_metric(
            " ".join(_name_kinds(service.get("name")))
        )
        hint = (
            f"{platform} {metric}"
            if platform and metric else (platform or metric)
        )
        # Pin by COMBINED id (second provider, 15 Nov 2026): a
        # bare id would re-pin the other provider's service of
        # the same number when the draft completes.
        NUDGE_SERVICE[user.id] = service_combined_id(service)
        PARTIAL[user.id] = {
            "platform": platform,
            "service_hint": hint,
        }
        await query.edit_message_text(
            ask_link_text(platform, hint, lang)
        )
        return

    if action == "browsepage":
        # Next page of the browse list (11): re-render the same
        # list at the requested page. A list that is gone (restart)
        # gets an honest answer, never a rebuilt list.
        entry = BROWSE_LISTS.get(user.id)
        if entry is None:
            await query.edit_message_text(t("cancelled", lang))
            return
        try:
            page = int(arg or 0)
        except (TypeError, ValueError):
            page = 0
        total_pages = (
            len(entry["services"]) + BROWSE_PAGE_SIZE - 1
        ) // BROWSE_PAGE_SIZE
        page = max(0, min(page, max(0, total_pages - 1)))
        entry["page"] = page
        await query.edit_message_text(
            _browse_page_text(entry, page),
            reply_markup=_browse_keyboard(entry, page),
        )
        return

    if action == "report":
        # Report a problem (ideas batch 2, feature 2, 15 Nov 2026):
        # "⚠️ Report a problem" on an order in My orders, a tap on
        # a recent order in the "which order?" step, or "Something
        # else — no order" ("report:none"). Starts the flow by
        # asking what's wrong — with the order id when one was
        # tapped, without one when "none". The id is NOT validated
        # against the recent-orders list here: the order may be
        # older than the list, and the server checks ownership when
        # the report is filed. Never starts while an order, deposit,
        # plan or Confirm card is open — the user finishes or
        # cancels that first, so a tap can never hijack a draft.
        if _promo_busy(user.id):
            await query.edit_message_text(t("report_busy", lang))
            return
        report_lang = LAST_LANG.get(user.id) or lang
        if arg == "none":
            order_id = None
        else:
            try:
                order_id = int(arg or 0) or None
            except (TypeError, ValueError):
                order_id = None
        REPORT_PENDING[user.id] = {"order_id": order_id, "step": "describe"}
        if order_id is None:
            await query.edit_message_text(
                t("report_ask_no_order", report_lang)
            )
        else:
            await query.edit_message_text(
                t("report_ask_order", report_lang, order_id=order_id)
            )
        return

    if action == "rate":
        # Rate your order (ideas batch 2, feature 3, 15 Nov 2026):
        # 👍/👎 on the delivery message. One tap files the rating
        # and appends one short line to the message; a second tap
        # answers "Already noted" and files nothing. A 👎 is
        # feedback only — it never refunds (a refund needs a report
        # or support). The endpoint not being live yet is answered
        # honestly, and nothing is asked again. A failed filing
        # leaves the order unmarked, so a retry tap can still file.
        order_id, _, rating = arg.partition(":")
        if rating not in ("good", "bad") or not order_id:
            return
        rate_lang = LAST_LANG.get(user.id) or lang
        # The original message is re-sent with the rating note: strip
        # any long dash it still carries (a card sent before the
        # 18 Nov 2026 dash removal) so the edit is dash-free too.
        base = _strip_dashes(query.message.text or "")
        if order_id in RATED_ORDERS:
            await query.edit_message_text(
                base + "\n\n" + t("rate_already", rate_lang)
            )
            return
        try:
            result = await paxyo.rate_order(order_id, user.id, rating)
        except Exception as exc:
            log.warning("rate order %s failed: %s", order_id, exc)
            await query.edit_message_text(
                base + "\n\n" + t("rate_failed", rate_lang)
            )
            return
        if result is None:
            await query.edit_message_text(
                base + "\n\n" + t("rate_not_live", rate_lang)
            )
            return
        if isinstance(result, dict) and result.get("already_rated"):
            RATED_ORDERS.add(order_id)
            await query.edit_message_text(
                base + "\n\n" + t("rate_already", rate_lang)
            )
            return
        if isinstance(result, dict) and result.get("ok") is False:
            # The not-completed 409: the watch only asks after a
            # completed order, so this should not happen — answer
            # honestly and file nothing.
            await query.edit_message_text(
                base + "\n\n" + t("rate_not_completed", rate_lang)
            )
            return
        RATED_ORDERS.add(order_id)
        await query.edit_message_text(
            base + "\n\n" + t(
                "rate_thanks_good" if rating == "good"
                else "rate_thanks_bad",
                rate_lang,
            )
        )
        return

    if action == "feedback":
        # Feedback check (feature 10, 15 Nov 2026): 👍/👎 on "How
        # was your first order with Paxyo?" Good thanks them and
        # ends it; bad asks what went wrong in one message and
        # opens FEEDBACK_PENDING, so the next message is filed via
        # report_problem against this first order. The ask is
        # already recorded as asked (in memory and on the server),
        # so a tap can never re-ask. Nothing is filed here.
        verdict, _, fb_order_id = arg.partition(":")
        if verdict not in ("good", "bad") or not fb_order_id:
            return
        fb_lang = LAST_LANG.get(user.id) or lang
        # Satisfaction score (20, 15 Nov 2026): the feedback tap
        # ALSO files a rating for the order (good/bad), so the
        # admin's satisfaction score counts it. Best-effort and
        # once per order — the server enforces once (409), and a
        # 404 (endpoint not live yet) or any failure changes
        # nothing about the feedback reply itself. A tap that was
        # already rated on the delivery message 409s silently.
        try:
            await paxyo.rate_order(fb_order_id, user.id, verdict)
        except Exception as exc:
            log.warning("feedback rating failed: %s", exc)
        if verdict == "good":
            await query.edit_message_text(t("feedback_thanks", fb_lang))
            return
        try:
            fb_order_id = int(fb_order_id)
        except (TypeError, ValueError):
            pass
        FEEDBACK_PENDING[user.id] = {"order_id": fb_order_id}
        await query.edit_message_text(
            t("feedback_bad_ask", fb_lang, order_id=fb_order_id)
        )
        return

    if action == "friday":
        # Friday pattern (feature 5, 15 Nov 2026): "Yes, place it"
        # on the weekly offer. Pre-fills the pattern's service +
        # quantity and asks for the link — the old link is never
        # reused silently; the "Same link as last time" button
        # offers it, and the user confirms it by tapping. Nothing
        # is placed here: the normal Confirm card still gates the
        # order. A stale tap (offer already answered) gets the
        # honest gone line.
        pattern = FRIDAY_PENDING.pop(user.id, None)
        if pattern is None:
            await query.edit_message_text(t("friday_gone", lang))
            return
        try:
            # The service id is a COMBINED id ("gop:<id>" /
            # "smm:<id>", second provider, 15 Nov 2026), so it
            # contains a colon itself — split from the right.
            _sid, _qty = arg.rsplit(":", 1)
            if (
                _sid != str(pattern["service_id"])
                or int(_qty) != int(pattern["quantity"])
            ):
                raise ValueError
        except (TypeError, ValueError):
            await query.edit_message_text(t("friday_gone", lang))
            return
        text, markup = await _friday_accept_text(
            user.id, pattern, lang
        )
        await query.edit_message_text(text, reply_markup=markup)
        return

    if action == "fridayno":
        # Declining the Friday offer ends it quietly — no nagging,
        # no re-offer this week (FRIDAY_OFFERED already holds the
        # week's key from when the offer was sent).
        FRIDAY_PENDING.pop(user.id, None)
        FRIDAY_LINK.pop(user.id, None)
        await query.edit_message_text(t("friday_declined", lang))
        return

    if action == "fridaylink":
        # "Same link as last time" on a Friday offer: the user
        # confirms the old link explicitly, so it is used — then
        # the normal Confirm card runs. The one-shot service pin
        # is dropped first: the named service id below carries
        # the service, and a stale pin must never hijack a later
        # order.
        link = FRIDAY_LINK.pop(user.id, None)
        if not link:
            await query.edit_message_text(t("friday_gone", lang))
            return
        try:
            # The service id is a COMBINED id ("gop:<id>" /
            # "smm:<id>", second provider, 15 Nov 2026), so it
            # contains a colon itself — split from the right. The
            # id stays a string: find_service_by_id resolves a
            # combined id exactly, and an unknown one answers
            # honestly downstream instead of crashing here.
            _sid, _qty = arg.rsplit(":", 1)
            _qty = int(_qty)
        except (TypeError, ValueError):
            await query.edit_message_text(t("friday_gone", lang))
            return
        USUAL_SERVICE.pop(user.id, None)
        try:
            services = await paxyo.services()
        except Exception:
            services = []
        service = find_service_by_id(services or [], _sid)
        platform = None
        hint = None
        if service is not None:
            platform, _h = _platform_hint_of_service(service)
            metric = _primary_metric(
                " ".join(_name_kinds(service.get("name")))
            )
            if metric:
                hint = f"{platform} {metric}" if platform else metric
        await complete_order(
            query.message, user.id,
            {
                "platform": platform, "service_hint": hint,
                "link": link, "quantity": _qty,
            },
            lang, named_service_id=_sid,
        )
        return

    if action == "firstorder":
        # First-order nudge (ideas batch, 15 Nov 2026): the user
        # tapped "Start a test order" on the cheapest-test offer.
        # The service id rides in the button ("firstorder:5535"),
        # so merely seeing the offer never pins anything — the
        # cheapest views service is pinned for this one order only
        # once the user taps (NUDGE_SERVICE, consumed by
        # complete_order); the user sends the link next and the
        # Confirm card shows it.
        try:
            service_id = int(arg or 0) or None
        except (TypeError, ValueError):
            service_id = None
        if service_id is None:
            await query.edit_message_text(t("first_order_gone", lang))
            return
        try:
            services = await paxyo.services()
        except Exception:
            services = []
        service = find_service_by_id(services or [], service_id)
        if service is None:
            await query.edit_message_text(t("first_order_gone", lang))
            return
        platform, _hint = _platform_hint_of_service(service)
        metric = _primary_metric(" ".join(_name_kinds(service.get("name"))))
        quantity = 1000
        PARTIAL[user.id] = {
            "platform": platform,
            "service_hint": f"{platform} {metric}" if platform and metric else metric,
            "link": None,
            "quantity": quantity,
        }
        # Pin the cheapest service for the order this nudge builds.
        # By COMBINED id (second provider, 15 Nov 2026): the
        # cheapest service may be an SMM one, and a bare id would
        # re-pin the GOP service of the same number.
        NUDGE_SERVICE[user.id] = service_combined_id(service)
        # The tap starts the draft's quiet clock (abandoned-order
        # nudge, feature 4): if the user never sends the link,
        # the nudge fires ~30 minutes from here.
        touch_partial_activity(user.id)
        total = estimated_total_etb(
            float(service.get("rate_etb_per_1000", 0)), quantity
        )
        await query.edit_message_text(
            t(
                "first_order_link", lang,
                service=short_service_name(service.get("name")),
                quantity=quantity, total=format_money(total),
            )
        )
        return

    if action == "stoprec":
        # Stop one repeating order from a button.
        try:
            schedules = await paxyo.list_recurring(user.id)
        except Exception as exc:
            log.warning("list_recurring failed: %s", exc)
            await query.edit_message_text(t("not_understood", lang))
            return
        sched = next(
            (s for s in schedules if str(s.get("id")) == arg), None
        )
        if sched is None:
            await query.edit_message_text(t("no_schedules", lang))
            return
        try:
            await paxyo.cancel_recurring(sched.get("id"), user.id)
        except Exception as exc:
            log.warning("cancel_recurring failed: %s", exc)
            await query.edit_message_text(t("not_understood", lang))
            return
        name = short_service_name(sched.get("service_name")) or f"service {sched.get('service_id')}"
        await query.edit_message_text(
            t("schedule_stopped", lang, service=name)
        )
        return

    if action == "canceldelay":
        # Cancel one scheduled order from a button.
        try:
            orders = await delayed_store_list(user.id)
        except Exception as exc:
            log.warning("delayed_store_list failed: %s", exc)
            await query.edit_message_text(t("not_understood", lang))
            return
        order = next(
            (o for o in orders if str(o.get("id")) == arg), None
        )
        if order is None:
            await query.edit_message_text(t("no_delayed_orders", lang))
            return
        await delayed_store_cancel(order, user.id)
        try:
            services = await paxyo.services()
        except Exception:
            services = []
        service = None
        # Prefer the combined id (second provider, 15 Nov 2026):
        # the bare id alone could name the other provider's
        # service of the same number in the confirmation.
        combined = order.get("combined_id")
        if combined:
            service = find_service_by_id(services or [], combined)
        if service is None:
            for s in services or []:
                try:
                    if int(s.get("service")) == int(order.get("service_id") or 0):
                        service = s
                        break
                except (TypeError, ValueError):
                    continue
        name = (
            short_service_name(service.get("name"))
            if service
            else f"service {order.get('service_id')}"
        )
        await query.edit_message_text(
            t("delayed_cancelled", lang, service=name)
        )
        return

    # Single order first, then a repeating-order plan: both use the
    # same Confirm/Cancel buttons, distinguished by which store holds
    # the id.
    pending = PENDING.pop(arg, None)
    if pending is not None:
        if pending["user_id"] != user.id:
            await query.edit_message_text(t("cancelled", lang))
            return
        if action == "cancel":
            # Cancelling clears the stored order state (round 6,
            # 13 Nov 2026): a fresh order after this starts from
            # scratch instead of auto-showing the cancelled card.
            clear_order_state(user.id, cancelled=pending)
            await query.edit_message_text(t("cancelled", lang))
            log_confusion(user.id, "Cancel", t("cancelled", lang), "abandoned")
            return
        # Double confirm (#38): a big order (over the level the
        # customer set) needs a second Confirm tap. The first tap
        # re-shows the card as a second confirmation; the second
        # tap places it. Only for normal PENDING orders.
        if action == "confirm":
            _double = get_pref(user.id, "pref_double_confirm_etb")
            if (
                _double is not None
                and float(pending.get("total") or 0) > _double
                and not pending.get("double_confirmed")
            ):
                pending["double_confirmed"] = True
                PENDING[arg] = pending
                await query.edit_message_text(
                    "This is a big order, "
                    f"{format_money(pending['total'])} ETB. Tap "
                    "Confirm again to place it.",
                    reply_markup=confirm_keyboard(arg),
                )
                return
        # Button tap: place the order and replace the Confirm card with
        # the full order summary IN TEXT — the same summary a voice
        # acceptance gets as a new message (see send_order_result).
        result, error = await place_pending_order(pending, user.id)
        if error:
            key = error[0]
            if key == "insufficient":
                await query.edit_message_text(
                    t(
                        "insufficient",
                        lang,
                        balance=format_money(error[1]),
                        total=format_money(error[2]),
                    ),
                    reply_markup=deposit_webapp_keyboard(lang),
                )
            elif key == "bad_link":
                # Link check (item 5): do not place — the card is
                # replaced with the right-link question, and the
                # draft (minus the bad link) is restored so the
                # user can continue by sending just the link.
                _platform, _hint = _restore_draft_after_bad_link(
                    pending, user.id
                )
                await query.edit_message_text(
                    ask_link_text(_platform, _hint, lang)
                )
            elif key == "bad_quantity":
                _svc = pending.get("service") or {}
                await query.edit_message_text(
                    t(
                        "bad_quantity", lang,
                        service=short_service_name(_svc.get("name")),
                        min=_svc.get("min"), max=_svc.get("max"),
                    )
                )
            else:
                await query.edit_message_text(t(key, lang))
            return
        summary = t(
            "order_summary",
            lang,
            service=result["service"],
            quantity=result["quantity"],
            link=result["link"],
            total=format_money(result["total"]),
            order_id=result["order_id"],
            status=result["status"],
        )
        # Split-test (15 Nov 2026): same note as the
        # text-acceptance summary above.
        if result.get("split_test"):
            summary += "\n" + t(
                "order_split_test_placed", lang,
                test_quantity=result["test_quantity"],
                quantity=result["quantity"],
            )
        # Drip-feed (19 Nov 2026): same note as the
        # text-acceptance summary above.
        _drip_line = _drip_summary_line(lang, result.get("drip") or {})
        if _drip_line:
            summary += "\n" + _drip_line
        # Auto-repeat (#16, customizations, 15 Nov 2026): same
        # hook as the text-acceptance summary — a standing repeat
        # for this order type starts now, once.
        if await _maybe_start_auto_repeat(user.id, pending):
            repeat = get_pref(user.id, "pref_auto_repeat") or {}
            summary += (
                "\nRepeating every "
                f"{format_interval(repeat.get('interval_minutes', 0))} "
                "from now on."
            )
        # Per-user personality (feature 5, 15 Nov 2026): the same
        # tone shaping as the text-acceptance summary — brief gets
        # the summary alone, chatty one warm line, formal a polite
        # opening. No learned tone -> summary + humour, as before.
        shaped = tone_order_summary(user.id, lang, summary)
        if user_tone(user.id) != "brief":
            shaped += "\n" + humor_line(user.id, lang)
        # No long dash in any reply (owner, 17 Nov 2026): the humour
        # line can carry one, and this edit bypasses reply_message.
        await query.edit_message_text(_strip_dashes(shaped))
        return

    rec_draft = PENDING_RECURRING.pop(arg, None)
    if rec_draft is not None:
        if rec_draft["user_id"] != user.id:
            await query.edit_message_text(t("cancelled", lang))
            return
        if action == "cancel":
            await query.edit_message_text(t("cancelled", lang))
            return
        # Confirm tap: create the repeating order on the server and
        # replace the plan summary with a short confirmation (text).
        schedule, error = await start_recurring_plan(rec_draft, user.id)
        if error:
            await query.edit_message_text(t("plan_failed", lang))
            return
        await query.edit_message_text(
            t(
                "plan_started",
                lang,
                quantity=rec_draft["quantity"],
                service=short_service_name(rec_draft["service"].get("name")),
                interval=format_interval(rec_draft["interval_minutes"]),
            )
        )
        return

    auto_setup = PENDING_AUTO_REFILL.pop(arg, None)
    if auto_setup is not None:
        if auto_setup["user_id"] != user.id:
            await query.edit_message_text(t("cancelled", lang))
            return
        if action == "cancel":
            await query.edit_message_text(t("cancelled", lang))
            return
        # Confirm tap: switch the auto-refill on (memory + server
        # when the refill endpoint is live) and replace the
        # preview with a short confirmation (text).
        await refill_store_create(auto_setup, user.id)
        await query.edit_message_text(
            t(
                "auto_refill_started",
                lang,
                service=short_service_name(
                    (auto_setup.get("service") or {}).get("name")
                ),
                trigger=auto_refill_trigger_text(
                    auto_setup.get("trigger"),
                    auto_setup.get("target"), lang,
                ),
                limit=auto_refill_limit_text(
                    auto_setup.get("daily_cap"), lang,
                ),
            )
        )
        return

    delay_draft = PENDING_DELAYED.pop(arg, None)
    if delay_draft is not None:
        if delay_draft["user_id"] != user.id:
            await query.edit_message_text(t("cancelled", lang))
            return
        if action == "cancel":
            await query.edit_message_text(t("cancelled", lang))
            return
        # Confirm tap: schedule the order and replace the card with
        # a short confirmation (text).
        record, error = await delayed_store_create(delay_draft, user.id)
        if error:
            await query.edit_message_text(t("delayed_save_failed", lang))
            return
        await query.edit_message_text(
            t(
                "delayed_started",
                lang,
                quantity=delay_draft["quantity"],
                service=short_service_name(delay_draft["service"].get("name")),
                time=format_eat_run_at(delay_draft["run_at"]),
            )
        )
        return

    if DEPOSIT_CONFIRM_IN_FLIGHT.get(arg) == user.id:
        # Double tap (19 Nov 2026): the first tap is still starting
        # the deposit — the draft is already popped, but the deposit
        # is NOT cancelled. Say it is starting instead of falling
        # through to "Order cancelled" below.
        await _edit_callback_message(
            query, t("deposit_confirm_processing", lang)
        )
        return
    dep_draft = PENDING_DEPOSIT.pop(arg, None)
    if dep_draft is not None:
        if dep_draft["user_id"] != user.id:
            await _edit_callback_message(query, t("cancelled", lang))
            return
        if action == "cancel":
            await _edit_callback_message(query, t("cancelled", lang))
            return
        # Confirm tap: mark it in flight BEFORE the slow
        # start_deposit calls, and tell the user at once that it
        # is starting — the card used to sit unchanged until the
        # server answered, which read as lag and invited a second
        # tap. The finally clears the flag whatever happens, so a
        # later tap is never stuck on "processing". The card can
        # sit on the guide photo (20 Nov 2026), so every edit here
        # goes through _edit_callback_message — a plain
        # edit_message_text is refused on a photo and the Confirm
        # tap does nothing.
        DEPOSIT_CONFIRM_IN_FLIGHT[arg] = user.id
        try:
            await _edit_callback_message(
                query, t("deposit_confirm_processing", lang)
            )
            # Start the deposit and replace the summary with the
            # payment instructions (text — they carry a link/code
            # the user must read).
            result, error = await start_deposit(dep_draft, user.id)
            # Ban (19 Nov 2026): a banned user deposits nothing.
            if error == "banned":
                await _edit_callback_message(query, t("banned", lang))
                return
            if error:
                if error in ("deposit_not_ready", "deposit_failed", "deposit_unavailable"):
                    # The push could not be sent: offer the deposit page
                    # embedded in Telegram instead of a bare paxyo.et text.
                    # Keep the failed draft so the "Try again" button can
                    # restart it (ideas batch, 15 Nov 2026).
                    FAILED_DEPOSIT[user.id] = dict(dep_draft)
                    text, markup = deposit_webapp_message(
                        dep_draft["amount"], lang,
                        allow_retry=True, user_id=user.id,
                    )
                    await _edit_callback_message(
                        query, text, reply_markup=markup
                    )
                else:
                    await _edit_callback_message(
                        query, _strip_dashes(error)
                    )
                return
            await _edit_callback_message(
                query,
                t(
                    "deposit_popup_ready", lang,
                    amount=format_money(dep_draft["amount"]),
                ),
                reply_markup=deposit_success_markup(result, dep_draft, lang),
            )
        finally:
            DEPOSIT_CONFIRM_IN_FLIGHT.pop(arg, None)
        return

    batch = PENDING_BATCH.pop(arg, None)
    if batch is not None:
        if batch["user_id"] != user.id:
            await query.edit_message_text(t("cancelled", lang))
            return
        if action == "cancel":
            await query.edit_message_text(t("cancelled", lang))
            return
        # Confirm tap: place every order in the batch and replace the
        # card with one short line per order.
        results, error = await place_batch(batch, user.id)
        if error:
            key = error[0]
            if key == "insufficient":
                await query.edit_message_text(
                    t(
                        "insufficient",
                        lang,
                        balance=format_money(error[1]),
                        total=format_money(error[2]),
                    ),
                    reply_markup=deposit_webapp_keyboard(lang),
                )
            else:
                await query.edit_message_text(t(key, lang))
            return
        await query.edit_message_text(batch_result_text(results, lang))
        return

    bundle = PENDING_BUNDLE.pop(arg, None)
    if bundle is not None:
        if bundle["user_id"] != user.id:
            await query.edit_message_text(t("cancelled", lang))
            return
        if action == "cancel":
            await query.edit_message_text(t("cancelled", lang))
            return
        # Confirm tap: place the bundle's three legs and replace the
        # card with one short line per leg (ideas batch 1 #3).
        results, error = await place_bundle(bundle, user.id)
        if error:
            key = error[0]
            if key == "insufficient":
                await query.edit_message_text(
                    t(
                        "insufficient",
                        lang,
                        balance=format_money(error[1]),
                        total=format_money(error[2]),
                    ),
                    reply_markup=deposit_webapp_keyboard(lang),
                )
            else:
                await query.edit_message_text(t(key, lang))
            return
        await query.edit_message_text(batch_result_text(results, lang))
        return

    refill = PENDING_REFILL.pop(arg, None)
    if refill is not None:
        if refill["user_id"] != user.id:
            await query.edit_message_text(t("cancelled", lang))
            return
        if action == "cancel":
            await query.edit_message_text(t("cancelled", lang))
            return
        # Confirm tap: refill the completed order at the provider
        # (or, when the provider offers no refills, say so honestly
        # and offer a second Confirm for a brand-new order of the
        # same service instead).
        await _run_refill_confirm(
            user.id, refill, lang,
            respond=query.edit_message_text,
            send_new=query.message.reply_text,
        )
        return

    cancel_entry = PENDING_CANCEL.pop(arg, None)
    if cancel_entry is not None:
        if cancel_entry["user_id"] != user.id:
            await query.edit_message_text(t("cancelled", lang))
            return
        if action == "cancel":
            await query.edit_message_text(t("cancelled", lang))
            return
        # Confirm tap: cancel the placed order at the provider and
        # refund the full total to the user's balance (12, 15 Nov
        # 2026). The card is replaced in place with the outcome.
        await _run_cancel_order_confirm(
            user.id, cancel_entry, lang,
            respond=query.edit_message_text,
        )
        return

    await query.edit_message_text(t("cancelled", lang))


# ------------------------------------------- recurring scheduler ----
# A background loop that runs the repeating orders. It wakes every 60
# seconds and asks the server which schedules are due. The free tier
# sleeps after ~15 minutes idle, so a schedule can be hours late: it
# still runs ONCE on wake (the server advances next_run_at from now,
# never from the stale time), never once per missed interval. A run is
# placed with an idempotency key per schedule+slot, so even if the
# server did not advance the time, a retry returns the same order
# instead of a second charge.

RECURRING_CHECK_SECONDS = 60
MIN_RECURRING_MINUTES = 30


QUIET_HELD = {}  # telegram_id -> [(text, reply_markup)] held during quiet hours
QUIET_HELD_MAX = 50  # per user: older held messages drop past this


async def notify_user(app, user_id: int, text: str, reply_markup=None):
    """Send a plain text message to a user from the scheduler. Never
    raises — a failed send must not kill the loop. reply_markup is
    for the abandoned-order nudge's Resume button; every other
    scheduler message stays plain text.
    Quiet hours (#19, customizations, 15 Nov 2026): when the user
    is inside their quiet hours, the message is HELD (in memory,
    in QUIET_HELD) instead of sent, and flushed in the morning by
    run_quiet_flush_cycle. Admins are exempt — William's alerts
    always go out, quiet hours or not."""
    # No long dash in any reply (owner, 17 Nov 2026): strip it
    # before the quiet-hours hold, so a held message is clean too
    # when the morning flush re-sends it through here.
    text = _strip_dashes(text)
    if (
        user_id not in ADMIN_TELEGRAM_IDS
        and in_quiet_hours(user_id)
    ):
        held = QUIET_HELD.setdefault(int(user_id), [])
        held.append((text, reply_markup))
        if len(held) > QUIET_HELD_MAX:
            del held[:len(held) - QUIET_HELD_MAX]
        return
    try:
        await app.bot.send_message(
            chat_id=user_id, text=text,
            reply_markup=(
                reply_markup if reply_markup is not None
                else hide_reply_keyboard()
            ),
        )
    except Exception as exc:
        log.warning("notify_user %s failed: %s", user_id, exc)


async def run_quiet_flush_cycle(app):
    """Send the messages held during quiet hours (#19) to every
    user whose quiet hours have ended. A short header first, so
    the morning batch reads as one catch-up, then each held
    message in the order it was held (with its own buttons).
    Best-effort: a failed send is logged by notify_user and never
    raises. Held messages for a user still inside quiet hours
    stay held. Called from run_scheduler_cycle."""
    if not QUIET_HELD:
        return
    for user_id in list(QUIET_HELD.keys()):
        held = QUIET_HELD.get(user_id) or []
        if not held:
            QUIET_HELD.pop(user_id, None)
            continue
        if in_quiet_hours(user_id):
            continue
        QUIET_HELD.pop(user_id, None)
        lang = LAST_LANG.get(user_id, "en")
        await notify_user(app, user_id, t("quiet_morning", lang))
        for text, markup in held:
            await notify_user(app, user_id, text, reply_markup=markup)


async def notify_admins(app, text: str):
    """Send an admin-only alert to every ADMIN_TELEGRAM_IDS id
    (William, who has started @paxorder_bot). Admin alerts are
    English only and never name the provider — the price watch
    and the provider-balance watch use this, never notify_user
    to a customer. Never raises: one failed send must not stop
    the others or kill the scheduler loop."""
    for admin_id in sorted(ADMIN_TELEGRAM_IDS):
        await notify_user(app, admin_id, text)


def _service_pause_admin_text(service, cancel_count, paused_until):
    """One line for William when a service is auto-paused
    (cancel-cutting item 2, 16 Nov 2026): which service, how
    many provider cancels triggered it, until when it is paused.
    English only, no provider name — the service is identified
    by its name and number, as the customer sees it."""
    name = short_service_name((service or {}).get("name")) or (
        f"service {(service or {}).get('service')}"
    )
    when = paused_until or "24 hours from now"
    count = cancel_count if cancel_count is not None else 3
    return (
        f"Service paused: {name}, {count} provider cancels in "
        f"24 hours. Paused until {when}. It will be skipped in "
        "picking until then."
    )


async def run_one_schedule(app, sched, services_by_id):
    """Place one due repeating order, or pause it when the balance is
    short. One due schedule = at most one order per cycle."""
    schedule_id = sched.get("id")
    user_id = sched.get("user_id")
    # Resolve by COMBINED id first ("smm:<id>" / "gop:<id>",
    # second provider, 15 Nov 2026); the recurring table stores
    # only a bare service id today, so old rows still resolve the
    # GOP service — exactly like before. (A recurring order
    # on an SMM service needs the server's recurring row to carry
    # the provider; see HANDOVER.md — until then, recurring
    # orders are effectively GOP.)
    service = None
    combined = sched.get("combined_id")
    if combined:
        service = services_by_id.get(combined)
    if service is None:
        try:
            service_id = int(sched.get("service_id"))
        except (TypeError, ValueError):
            service_id = None
        service = services_by_id.get(service_id) if service_id is not None else None
    if service is None:
        log.warning(
            "recurring %s: service %s not found, skipping",
            schedule_id, sched.get("service_id"),
        )
        return
    try:
        quantity = int(sched.get("quantity") or 0)
    except (TypeError, ValueError):
        quantity = 0
    if quantity <= 0:
        log.warning("recurring %s: bad quantity, skipping", schedule_id)
        return
    # Ban (19 Nov 2026): a banned user's repeat never places —
    # pause the schedule on the server and tell the user plainly.
    if await user_is_banned(user_id):
        try:
            await paxyo.pause_recurring(schedule_id, user_id)
        except Exception as exc:
            log.warning("recurring %s: pause failed: %s", schedule_id, exc)
        await notify_user(app, user_id, t("banned", "en"))
        return
    total = estimated_total_etb(float(service.get("rate_etb_per_1000", 0)), quantity)
    try:
        bal = await paxyo.balance(user_id)
    except Exception as exc:
        log.warning("recurring %s: balance check failed: %s", schedule_id, exc)
        return  # retry next cycle; nothing placed, nothing sent
    balance = float(bal.get("balance", 0)) if bal.get("found") else 0.0
    name = short_service_name(service.get("name"))
    if balance < total:
        # Never place an order the user cannot pay for: pause the
        # schedule on the server and tell the user why, once.
        try:
            await paxyo.pause_recurring(schedule_id, user_id)
        except Exception as exc:
            log.warning("recurring %s: pause failed: %s", schedule_id, exc)
        await notify_user(
            app, user_id,
            t(
                "plan_paused", "en", service=name,
                balance=format_money(balance), total=format_money(total),
            ),
        )
        return
    slot = sched.get("next_run_at") or ""
    key = f"rec-{schedule_id}-{slot}"
    try:
        # Provider-aware placement (second provider, 15 Nov 2026):
        # the resolved service dict decides the endpoint.
        result = await create_order_for_service(
            paxyo, user_id, service, sched.get("link"), quantity, key
        )
    except Exception as exc:
        log.warning("recurring %s: order failed: %s", schedule_id, exc)
        await notify_user(app, user_id, t("recurring_failed", "en"))
        return
    order = result.get("order", result) if isinstance(result, dict) else {}
    order_id = order.get("id") or order.get("order_id") or "?"
    status = order.get("status", "pending")
    try:
        await paxyo.mark_recurring_ran(schedule_id, user_id, order_id)
    except Exception as exc:
        # The order is placed; the idempotency key (schedule+slot)
        # means a retry next cycle returns the same order, not a
        # second charge. Log and move on.
        log.warning("recurring %s: mark_ran failed: %s", schedule_id, exc)
    # Ideas batch (15 Nov 2026): watch for delivery/stuck updates.
    watch_order(user_id, order_id, service, quantity, sched.get("link"),
                total=total)
    await notify_user(
        app, user_id,
        t(
            "recurring_placed", "en", quantity=quantity, service=name,
            order_id=order_id, status=status,
        ),
    )


def _delayed_failure_reason(exc):
    """An honest short reason for a failed delayed placement, from
    the server's error body when it has one — never invented."""
    response = getattr(exc, "response", None)
    data = {}
    if response is not None:
        try:
            data = response.json()
        except Exception:
            data = {}
    if isinstance(data, dict):
        message = data.get("error") or data.get("message")
        if message:
            return str(message)
    return "the order could not be placed"


async def run_one_delayed(app, item, services_by_id):
    """Place one due one-time delayed order, exactly once.

    Balance is checked BEFORE the claim (a transient balance
    failure just retries next cycle); the claim happens BEFORE the
    order is placed, so a crash between claim and place cannot
    double-place it — a row stuck 'placing' for over 30 minutes is
    treated as due again (see api-delayed-orders.php), so a crash
    delays the order instead of losing it. On success the user is
    messaged with the order ID; on failure, honestly with the
    reason — never invented."""
    delayed_id = item.get("id")
    user_id = item.get("telegram_id")
    # Resolve by COMBINED id first ("smm:<id>" / "gop:<id>",
    # second provider, 15 Nov 2026): the bare id alone could pick
    # the other provider's service of the same number. Old rows
    # without a combined id fall back to the bare id, which still
    # finds the GOP service — exactly like before.
    service = None
    combined = item.get("combined_id")
    if combined:
        service = services_by_id.get(combined)
    if service is None:
        try:
            service_id = int(item.get("service_id"))
        except (TypeError, ValueError):
            service_id = None
        service = services_by_id.get(service_id) if service_id is not None else None
    if service is None:
        log.warning(
            "delayed %s: service %s not found, marking failed",
            delayed_id, item.get("service_id"),
        )
        await delayed_store_finish(
            item, "failed", reason="the service is no longer available"
        )
        if user_id is not None:
            await notify_user(
                app, user_id,
                t(
                    "delayed_failed", "en",
                    service=f"service {item.get('service_id')}",
                    reason="the service is no longer available",
                ),
            )
        return
    try:
        quantity = int(item.get("quantity") or 0)
    except (TypeError, ValueError):
        quantity = 0
    if quantity <= 0:
        log.warning("delayed %s: bad quantity, marking failed", delayed_id)
        await delayed_store_finish(
            item, "failed", reason="the quantity is not valid anymore"
        )
        if user_id is not None:
            await notify_user(
                app, user_id,
                t(
                    "delayed_failed", "en",
                    service=short_service_name(service.get("name")),
                    reason="the quantity is not valid anymore",
                ),
            )
        return
    # Ban (19 Nov 2026): a banned user's scheduled order never
    # places — mark it failed once and tell the user plainly.
    if user_id is not None and await user_is_banned(user_id):
        await delayed_store_finish(
            item, "failed", reason="account is blocked"
        )
        await notify_user(app, user_id, t("banned", "en"))
        return
    total = estimated_total_etb(float(service.get("rate_etb_per_1000", 0)), quantity)
    try:
        bal = await paxyo.balance(user_id)
    except Exception as exc:
        log.warning("delayed %s: balance check failed: %s", delayed_id, exc)
        return  # retry next cycle; nothing claimed, nothing placed
    balance = float(bal.get("balance", 0)) if bal.get("found") else 0.0
    name = short_service_name(service.get("name"))
    if balance < total:
        # Never place an order the user cannot pay for: mark the
        # scheduled order failed and tell the user why, once.
        await delayed_store_finish(
            item, "failed", reason="insufficient balance"
        )
        await notify_user(
            app, user_id,
            t(
                "delayed_insufficient", "en",
                balance=format_money(balance), total=format_money(total),
            ),
        )
        return
    if not await delayed_store_claim(item):
        # Someone (another process, or a previous cycle) already
        # claimed it: exactly-once means this caller does nothing.
        return
    try:
        result = await create_order_for_service(
            paxyo, user_id, service, item.get("link"), quantity,
            item.get("idempotency_key") or f"delay-{delayed_id}",
        )
    except Exception as exc:
        reason = _delayed_failure_reason(exc)
        log.warning("delayed %s: order failed: %s", delayed_id, exc)
        await delayed_store_finish(item, "failed", reason=reason)
        await notify_user(
            app, user_id,
            t("delayed_failed", "en", service=name, reason=reason),
        )
        return
    order = result.get("order", result) if isinstance(result, dict) else {}
    order_id = order.get("id") or order.get("order_id") or "?"
    status = order.get("status", "pending")
    await delayed_store_finish(item, "placed", order_id=order_id)
    # Ideas batch (15 Nov 2026): watch for delivery/stuck updates.
    watch_order(user_id, order_id, service, quantity, item.get("link"),
                total=total)
    await notify_user(
        app, user_id,
        t(
            "delayed_placed", "en", quantity=quantity, service=name,
            order_id=order_id, status=status,
        ),
    )


async def run_delayed_cycle(app):
    """One pass over due one-time delayed orders. Never raises.

    Caveat (owner, 14 Nov 2026): on free Render the process sleeps
    ~15 minutes idle, so a due order may run late, on the next
    wake — exact timing needs an always-on server (the Google
    Cloud move, approved 22:58 EAT, fixes this too)."""
    try:
        due = await delayed_store_due()
    except Exception as exc:
        log.warning("delayed due fetch failed: %s", exc)
        return
    if not due:
        return
    try:
        services = await paxyo.services()
    except Exception as exc:
        log.warning("delayed services fetch failed: %s", exc)
        return
    by_id = {}
    for s in services or []:
        if not isinstance(s, dict):
            continue
        # Keyed by COMBINED id ("gop:<id>" / "smm:<id>", second
        # provider, 15 Nov 2026) and — for old rows without one —
        # by bare id, first entry wins (the merged catalogue lists
        # the live GOP services first, so a bare id still
        # finds the GOP service, exactly like before).
        by_id[service_combined_id(s)] = s
        try:
            by_id.setdefault(int(s.get("service")), s)
        except (TypeError, ValueError):
            continue
    for item in due:
        if not isinstance(item, dict):
            continue
        await run_one_delayed(app, item, by_id)


def _price_watch_changes(snapshot, services):
    """Services whose catalogue price moved since the snapshot:
    [{service_id, combined_id, provider, name, old_price,
    new_price}] (ETB per 1000). Prices compare rounded to 4
    decimals — the server stores DECIMAL(12,4), so anything finer
    is storage noise, not a change. Blacklisted services (never
    sold) are skipped, and a service that is new since the snapshot
    is not a change — it joins the snapshot silently on the next
    save. Snapshot keys are COMBINED ids ("gop:<id>" /
    "smm:<id>", second provider, 15 Nov 2026); a bare-int key from
    an old snapshot reads as a GOP id, so the first cycle
    after the wiring compares the GOP services as before
    and treats every SMM service as new."""
    old = {}
    for sid, price in (snapshot or {}).items():
        try:
            value = round(float(price), 4)
        except (TypeError, ValueError):
            continue
        key = str(sid)
        if ":" not in key:
            try:
                key = f"gop:{int(key)}"
            except (TypeError, ValueError):
                continue
        old[key] = value
    changes = []
    for s in services or []:
        if not isinstance(s, dict):
            continue
        try:
            bare = int(s.get("service") or 0)
            new_price = round(float(s.get("rate_etb_per_1000") or 0), 4)
        except (TypeError, ValueError):
            continue
        if bare <= 0:
            continue
        # The blacklist is a GOP list — it never excludes an
        # SMM service that happens to share the number.
        if bare in BLACKLISTED_SERVICES and service_provider(s) == "gop":
            continue
        combined = service_combined_id(s)
        if combined not in old:
            continue
        if old[combined] == new_price:
            continue
        changes.append({
            "service_id": bare,
            "combined_id": combined,
            "provider": service_provider(s),
            "name": s.get("name") or f"service {bare}",
            "old_price": old[combined],
            "new_price": new_price,
        })
    return changes


def _price_watch_alert_text(changes) -> str:
    """One compact admin alert for the changed services: id, name,
    old -> new provider rate (USD, price/multiplier, 4 decimals),
    old -> new Paxyo selling price (ETB), and the margin effect
    (margin per 1000 = price x (multiplier-200)/multiplier — the
    owner buys 1 USD for 200 ETB and sells at the provider's
    multiplier: 420 for GOP, 400 for SMM)."""
    lines = [f"⚠️ Provider prices changed ({len(changes)} service"
             f"{'s' if len(changes) != 1 else ''}):"]
    for c in changes:
        multiplier = (
            SMM_SELL_MULTIPLIER_ETB
            if c.get("provider") == "smm"
            else GOP_SELL_MULTIPLIER_ETB
        )
        old_rate = c["old_price"] / multiplier
        new_rate = c["new_price"] / multiplier
        effect = (
            (c["new_price"] - c["old_price"]) * (multiplier - 200) / multiplier
        )
        # GOP keeps its bare "#1665" label; an SMM service
        # shows its combined id so the two providers' same numbers
        # never look alike in the alert.
        label = c.get("combined_id") or str(c["service_id"])
        if label.startswith("gop:"):
            label = label[4:]
        lines.append(
            f"#{label} "
            f"{short_service_name(c['name']) or c['name']}: "
            f"${old_rate:.4f} → ${new_rate:.4f} "
            f"({format_money(c['old_price'])} → "
            f"{format_money(c['new_price'])} ETB), "
            f"margin {effect:+.2f} ETB/1000"
        )
    return "\n".join(lines)


def _snapshot_ids(snapshot):
    """Combined ids present in a price-watch snapshot, with the
    same bare-int -> GOP normalisation _price_watch_changes uses."""
    ids = set()
    for sid in (snapshot or {}):
        key = str(sid)
        if ":" not in key:
            try:
                key = f"gop:{int(key)}"
            except (TypeError, ValueError):
                continue
        ids.add(key)
    return ids


async def _alert_faster_services(app, snapshot, services):
    """New faster service alert (ideas batch 2 #6, 16 Nov 2026):
    a service that is NEW in the refreshed catalogue and FASTER
    than a user's usual service for the same platform+metric earns
    that user one alert. Hooked into the price-watch snapshot
    comparison, so it runs only when the catalogue was really
    refreshed — and never on the bootstrap cycle, where every
    service is new. Notification only: it never changes an order
    (the fastest-first pick already prefers the new service on
    the next order). One alert per user per service, ever
    (FASTER_SERVICE_ALERTED); the snapshot save is the primary
    guard — a service stops being new once it is snapshotted.
    Never raises."""
    try:
        known = _snapshot_ids(snapshot)
        new_services = []
        for s in services or []:
            if not isinstance(s, dict):
                continue
            if service_combined_id(s) in known:
                continue
            try:
                bare = int(s.get("service") or 0)
            except (TypeError, ValueError):
                continue
            if bare <= 0:
                continue
            if bare in BLACKLISTED_SERVICES and service_provider(s) == "gop":
                continue
            if not s.get("active", True):
                continue
            if parse_average_time(s.get("average_time")) is None:
                # No claimed time — it cannot be shown faster.
                continue
            new_services.append(s)
        if not new_services or not USER_TRAITS:
            return
        for user_id, traits in list(USER_TRAITS.items()):
            usual_id = traits.get("usual_service_id")
            platform = traits.get("usual_platform")
            metric = traits.get("usual_metric")
            if not usual_id or not platform or not metric:
                continue
            usual = find_service_by_id(services, usual_id)
            if usual is None:
                continue
            usual_minutes = parse_average_time(
                usual.get("average_time"))
            if usual_minutes is None:
                continue
            for s in new_services:
                s_platform, _hint = _platform_hint_of_service(s)
                s_metric = _trait_slug(kind_from_text(
                    f"{s.get('name') or ''} {s.get('category') or ''}"
                ) or "")
                if s_platform != platform or s_metric != metric:
                    continue
                s_minutes = parse_average_time(s.get("average_time"))
                if s_minutes is None or s_minutes >= usual_minutes:
                    continue
                key = (int(user_id), service_combined_id(s))
                if key in FASTER_SERVICE_ALERTED:
                    continue
                FASTER_SERVICE_ALERTED.add(key)
                lang = LAST_LANG.get(int(user_id)) or "en"
                await notify_user(app, int(user_id), t(
                    "faster_service_alert", lang,
                    platform=platform, metric=metric,
                    service=short_service_name(s.get("name"))
                    or s.get("name") or "service",
                    new_time=s.get("average_time"),
                    usual_service=short_service_name(usual.get("name"))
                    or usual.get("name") or "your usual service",
                    usual_time=usual.get("average_time"),
                ))
    except Exception as exc:
        log.warning("faster service alert failed: %s", exc)


async def run_price_watch_cycle(app):
    """One provider price-change watch pass (feature 6, 15 Nov
    2026): when the catalogue was REALLY refreshed since the last
    watch run, compare each price against the stored snapshot and
    alert William once per change. First run with an empty
    snapshot stores it WITHOUT alerting (bootstrap). The new
    snapshot is stored right after alerting, so a change alerts
    exactly once. Never raises — a failed snapshot fetch skips
    the cycle and retries next time, never alerts on stale data;
    a 404 switches the watch off with a log warning."""
    global _PRICE_WATCH_LAST_REFRESH, _PRICE_WATCH_OFF
    try:
        if _PRICE_WATCH_OFF:
            return
        count = getattr(paxyo, "services_refresh_count", None)
        if count is None:
            # The client does not expose a refresh counter — the
            # watch cannot tell a fresh catalogue from a cached
            # one, so it stays off rather than guessing.
            return
        if count == _PRICE_WATCH_LAST_REFRESH:
            return
        try:
            services = await paxyo.services()
        except Exception as exc:
            log.warning("price watch services failed: %s", exc)
            return
        get_snapshot = getattr(paxyo, "get_price_snapshot", None)
        if get_snapshot is None:
            _PRICE_WATCH_OFF = True
            log.warning(
                "price watch off: client has no get_price_snapshot"
            )
            return
        try:
            snapshot = await get_snapshot()
        except Exception as exc:
            # Any failure that is not a 404: skip this cycle and
            # retry next time — never alert on stale data.
            log.warning("price watch snapshot fetch failed: %s", exc)
            return
        if snapshot is None:
            # 404: the endpoint is not live yet — the watch stays
            # off with an honest log warning, never a crash.
            _PRICE_WATCH_OFF = True
            log.warning(
                "price watch off: GET /price-watch/snapshot "
                "returned 404 (endpoint not live yet)"
            )
            return
        new_map = {}
        for s in services or []:
            if not isinstance(s, dict):
                continue
            try:
                sid = int(s.get("service") or 0)
                price = round(float(s.get("rate_etb_per_1000") or 0), 4)
            except (TypeError, ValueError):
                continue
            # Snapshot keys are COMBINED ids ("gop:<id>" /
            # "smm:<id>", second provider, 15 Nov 2026) — a bare
            # id would let one provider's price overwrite the
            # other's in the snapshot.
            if sid > 0:
                new_map[service_combined_id(s)] = price
        if not snapshot:
            # Bootstrap: store the first snapshot silently — every
            # price would otherwise "change" at once.
            try:
                await paxyo.save_price_snapshot(new_map)
            except Exception as exc:
                log.warning("price watch bootstrap save failed: %s", exc)
                return
            _PRICE_WATCH_LAST_REFRESH = count
            return
        changes = _price_watch_changes(snapshot, services)
        if changes:
            await notify_admins(app, _price_watch_alert_text(changes))
        # New faster service alert (ideas batch 2 #6, 16 Nov 2026):
        # a service that is new in this refresh and faster than a
        # user's usual service for the same platform+metric earns
        # that user one alert. Runs on the same snapshot comparison,
        # before the new snapshot is saved — and never on the
        # bootstrap cycle above, where every service is new.
        await _alert_faster_services(app, snapshot, services)
        try:
            saved = await paxyo.save_price_snapshot(new_map)
        except Exception as exc:
            # The alert already went out; the save failed, so the
            # next cycle compares against the older snapshot and
            # may re-alert once — honest, and it degrades instead
            # of losing the change entirely.
            log.warning("price watch snapshot save failed: %s", exc)
            return
        if saved is None:
            _PRICE_WATCH_OFF = True
            log.warning(
                "price watch off: POST /price-watch/snapshot "
                "returned 404 (endpoint not live yet)"
            )
            return
        _PRICE_WATCH_LAST_REFRESH = count
    except Exception as exc:
        log.warning("price watch cycle failed: %s", exc)


async def _provider_balance_step(app, provider, balance, state):
    """One provider's step of the low-balance state machine (feature
    7, 15 Nov 2026; two providers since item 12, 16 Nov 2026):
    at or above the low threshold ($3) is ok; dropping below it
    alerts ONCE ("low"); while below it there are no repeats;
    crossing back above it resets to ok; dropping below $1.00
    while already low alerts ONCE more ("critically low"). The
    alert is the SAME alert as before (reused, not a second one) —
    it now carries the provider slug so William knows which
    balance to top up. Returns the new state. Never raises."""
    if balance >= PROVIDER_LOW_BALANCE_USD:
        return "ok"
    if balance >= PROVIDER_CRITICAL_BALANCE_USD:
        if state == "ok":
            await notify_admins(
                app,
                PROVIDER_BALANCE_LOW_TEXT.format(
                    balance=f"{balance:.2f}", provider=provider
                ),
            )
            return "low"
        if state == "critical":
            # Climbed back out of critical into low: no alert,
            # but a later drop below $1 alerts again.
            return "low"
        return state
    # Below $1.00: one critical alert, however we got here — a jump
    # straight from ok sends only this one, not both.
    if state != "critical":
        await notify_admins(
            app,
            PROVIDER_BALANCE_CRITICAL_TEXT.format(
                balance=f"{balance:.2f}", provider=provider
            ),
        )
        return "critical"
    return state


async def run_provider_balance_cycle(app, now=None):
    """One low-provider-balance check (feature 7, 15 Nov 2026):
    at most one check per hour, from admin_stats()'s
    provider_balance_usd (the server reads the provider balance;
    see server/api-admin-stats.php). State machine: at or above
    the low threshold ($3) is ok; dropping below it alerts ONCE
    ("low"); while below it there are no repeats; crossing back
    above it resets to ok; dropping below $1.00 while already low
    alerts ONCE more ("critically low"). A missing field or a 404
    means the watch is off — a log warning, never a crash, never
    an alert. Never raises.
    Two providers since item 12 (16 Nov 2026): the same check
    runs for the second provider's smm_balance_usd (server/
    api-admin-stats.php converts its INR balance to USD). Each
    provider keeps its own state, and each alerts once per
    crossing with the same alert text — the guard (see
    _provider_balance_health) reads the states, never the alert.
    A stats reply without smm_balance_usd (endpoint not updated
    yet) leaves the second provider's state untouched."""
    global _PROVIDER_BALANCE_LAST_CHECK, _PROVIDER_BALANCE_STATE
    global _PROVIDER_BALANCE_STATE_SMM
    try:
        import time

        if now is None:
            now = time.monotonic()
        if now - _PROVIDER_BALANCE_LAST_CHECK < PROVIDER_BALANCE_CHECK_SECONDS:
            return
        _PROVIDER_BALANCE_LAST_CHECK = now
        try:
            stats = await paxyo.admin_stats()
        except Exception as exc:
            log.warning("provider balance check failed: %s", exc)
            return
        if not isinstance(stats, dict) or "provider_balance_usd" not in stats:
            # 404 (admin_stats() returns None) or an endpoint that
            # does not report the balance yet: the watch is off.
            log.warning(
                "provider balance watch off: /admin/stats has no "
                "provider_balance_usd (endpoint not live yet)"
            )
            return
        try:
            balance = float(stats.get("provider_balance_usd"))
        except (TypeError, ValueError):
            log.warning(
                "provider balance watch off: provider_balance_usd "
                "is not a number: %r", stats.get("provider_balance_usd")
            )
            return
        _PROVIDER_BALANCE_STATE = await _provider_balance_step(
            app, "gop", balance, _PROVIDER_BALANCE_STATE
        )
        if "smm_balance_usd" in stats:
            try:
                smm_balance = float(stats.get("smm_balance_usd"))
            except (TypeError, ValueError):
                log.warning(
                    "provider balance watch off: smm_balance_usd "
                    "is not a number: %r", stats.get("smm_balance_usd")
                )
                return
            _PROVIDER_BALANCE_STATE_SMM = await _provider_balance_step(
                app, "smm", smm_balance, _PROVIDER_BALANCE_STATE_SMM
            )
    except Exception as exc:
        log.warning("provider balance cycle failed: %s", exc)


async def run_scheduler_cycle(app):
    """One pass over due repeating orders and due one-time delayed
    orders. Never raises."""
    try:
        due = await paxyo.due_recurring()
    except Exception as exc:
        log.warning("recurring due fetch failed: %s", exc)
        due = []
    if due:
        try:
            services = await paxyo.services()
        except Exception as exc:
            log.warning("recurring services fetch failed: %s", exc)
            services = []
        by_id = {}
        for s in services or []:
            if not isinstance(s, dict):
                continue
            # Keyed by COMBINED id ("gop:<id>" / "smm:<id>", second
            # provider, 15 Nov 2026) and — for rows without one —
            # by bare id, first entry wins (GOP first,
            # exactly like before).
            by_id[service_combined_id(s)] = s
            try:
                by_id.setdefault(int(s.get("service")), s)
            except (TypeError, ValueError):
                continue
        for sched in due:
            if not isinstance(sched, dict):
                continue
            await run_one_schedule(app, sched, by_id)
    await run_delayed_cycle(app)
    # Ideas batch (15 Nov 2026): delivery updates + stuck warnings
    # for orders the bot placed. Same 60-second cadence as the
    # schedules above, same tolerance for the free tier sleeping.
    await run_delivery_watch_cycle(app)
    # Provider price-change watch (feature 6, 15 Nov 2026): only
    # compares when the catalogue was really refreshed; the
    # snapshot endpoint is the dedupe. Low provider balance
    # (feature 7): throttled to one check per hour inside the
    # cycle itself. Both never raise and never message a customer.
    await run_price_watch_cycle(app)
    await run_provider_balance_cycle(app)
    # Abandoned-order nudge (feature 4, 15 Nov 2026): one Resume
    # nudge per half-built draft after ~30 quiet minutes. Same
    # 60-second cadence as the delivery watch above.
    await run_abandoned_nudge_cycle(app)
    # Abandoned-deposit nudge (14, 15 Nov 2026): one Resume nudge
    # per deposit whose Confirm card was shown but never tapped,
    # after 3 quiet hours — never to a user who completed a deposit
    # since. Uptime watch (19): the provider + the paxyo.et API,
    # one alert per target after two consecutive failures, one
    # recovery message when it comes back. Fraud watch (17): the
    # server's flagged users, relayed to William once each. All
    # three never raise and never message a customer.
    await run_abandoned_deposit_cycle(app)
    # Automatic deposit credit (owner, 17 Nov 2026): tell the user
    # the moment a watched deposit completes — no "I paid" tap.
    await run_deposit_credit_cycle(app)
    await run_uptime_watch_cycle(app)
    await run_fraud_watch_cycle(app)
    # Quiet hours (#19, customizations, 15 Nov 2026): flush the
    # messages held overnight to every user whose quiet hours
    # have ended. Last in the cycle, so the flush never races a
    # message the same cycle just held.
    await run_quiet_flush_cycle(app)


async def scheduler_loop(app):
    """Background loop: run the due repeating orders and due delayed
    orders every 60 seconds until the task is cancelled (on
    shutdown). Started next to the webhook server in serve_webhook()."""
    while True:
        await run_scheduler_cycle(app)
        await asyncio.sleep(RECURRING_CHECK_SECONDS)


# ------------------------------------------- webhook (Render web service) ---

class HealthHandler(tornado.web.RequestHandler):
    """GET / -> 200 'ok'. Render's health check hits this path."""

    def get(self):
        self.set_status(200)
        self.set_header("Content-Type", "text/plain")
        self.write("ok")


def build_webhook_app(app):
    """Tornado app serving the Telegram webhook AND Render's health check.

    PTB's own run_webhook server only serves the webhook path (POST), so
    GET / would 404 and Render's healthCheckPath would fail the deploy.
    This reuses PTB's TelegramHandler for the webhook path (the same code
    run_webhook uses internally) and adds GET / -> 200 'ok' next to it.
    """
    from telegram.ext._utils.webhookhandler import WebhookAppClass

    tornado_app = WebhookAppClass(f"/{get_webhook_path()}", app.bot, app.update_queue, None)
    tornado_app.add_handlers(r".*", [(r"/", HealthHandler)])
    return tornado_app


def build_application():
    """Build the PTB Application with all handlers. No network calls."""
    # trust_env=False so the Telegram clients ignore any proxy env vars
    # and talk directly to api.telegram.org (same as the API clients).
    telegram_request = HTTPXRequest(httpx_kwargs={"trust_env": False})
    app = (
        ApplicationBuilder()
        .token(TELEGRAM_BOT_TOKEN)
        .request(telegram_request)
        .get_updates_request(telegram_request)
        .build()
    )
    app.add_handler(CommandHandler("start", start))
    app.add_handler(CommandHandler("balance", balance_cmd))
    app.add_handler(CommandHandler("orders", orders_cmd))
    app.add_handler(CommandHandler("schedules", schedules_cmd))
    app.add_handler(CommandHandler("delayed", delayed_cmd))
    # Ideas batch (15 Nov 2026): /digest is on-demand only — no
    # scheduler is wired, nothing is sent anywhere by this command.
    app.add_handler(CommandHandler("digest", digest_cmd))
    app.add_handler(CommandHandler("help", help_cmd))
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, on_text))
    app.add_handler(MessageHandler(filters.VOICE, on_voice))
    app.add_handler(MessageHandler(filters.VIDEO_NOTE, on_video_note))
    app.add_handler(MessageHandler(filters.ANIMATION, on_animation))
    app.add_handler(MessageHandler(filters.Sticker.ALL, on_sticker))
    app.add_handler(MessageHandler(filters.PHOTO, on_photo))
    app.add_handler(CallbackQueryHandler(on_callback))
    return app


async def serve_webhook(app, port: int, stop_event=None):
    """Start the app, set the Telegram webhook, serve HTTP until stopped.

    Mirrors what Application.run_webhook does, except the HTTP server
    also answers Render's health check (GET /). Order matches PTB's
    run_webhook: initialize -> set webhook -> start update processing.
    `stop_event` is for tests; in production the process stops on
    SIGINT/SIGTERM (Render sends SIGTERM on deploy/shutdown).
    """
    await app.initialize()
    webhook_url = build_webhook_url()
    await app.bot.set_webhook(url=webhook_url, max_connections=40)
    # Log only the base URL: the full webhook URL contains the bot token
    # as its path, and the token must never appear in a log.
    log.info("Telegram webhook set (base %s)", get_webhook_base_url())
    await app.start()
    # The repeating-orders scheduler runs next to the webhook server.
    # It only places orders the server says are due, and it tolerates
    # the free tier sleeping: a late schedule runs once on wake.
    scheduler_task = asyncio.create_task(scheduler_loop(app))
    server = HTTPServer(build_webhook_app(app))
    server.listen(port, address="0.0.0.0")
    log.info(
        "Listening on 0.0.0.0:%s (webhook /%s, health GET /)",
        port, get_webhook_path(),
    )
    stop = stop_event or asyncio.Event()
    if stop_event is None:
        loop = asyncio.get_running_loop()
        try:
            for sig in (signal.SIGINT, signal.SIGTERM):
                loop.add_signal_handler(sig, stop.set)
        except (NotImplementedError, ValueError, RuntimeError):
            pass  # signals unavailable (tests / non-main thread)
    await stop.wait()
    scheduler_task.cancel()
    try:
        await scheduler_task
    except asyncio.CancelledError:
        pass
    server.stop()
    await app.stop()
    await app.shutdown()


def run_webhook_server(app, port: int):
    """Blocking entry point: run the webhook server until stopped."""
    asyncio.run(serve_webhook(app, port))


# ----------------------------------------------------------------- main ---

def main():
    missing = [
        name
        for name, value in [
            ("TELEGRAM_BOT_TOKEN", TELEGRAM_BOT_TOKEN),
            ("BOT_API_SECRET", BOT_API_SECRET),
            ("GEMINI_API_KEY", GEMINI_API_KEY),
        ]
        if not value
    ]
    if missing:
        log.error("Missing required environment variables: %s", ", ".join(missing))
        raise SystemExit(1)
    if not get_webhook_base_url():
        log.error(
            "No webhook base URL: set WEBHOOK_URL, or run on Render where "
            "RENDER_EXTERNAL_URL is set automatically"
        )
        raise SystemExit(1)

    global paxyo
    paxyo = PaxyoClient()
    app = build_application()

    # TODO (later phase): a stall monitor that polls fetch_order_status()
    # via paxyo.order_status() for recent orders and, when the picked
    # service stalls, cancels/refunds and moves to the next-fastest service
    # from the same category. Not built in this version.

    log.info(
        "Paxyo Order bot starting (webhook %s, model %s, cloud-tts am %s / en %s)",
        build_webhook_url(), GEMINI_MODEL,
        GOOGLE_CLOUD_TTS_VOICE, GOOGLE_CLOUD_TTS_VOICE_EN,
    )
    run_webhook_server(app, get_webhook_port())


if __name__ == "__main__":
    main()
